async fn model_gateway_status_view(
    state: &AppState,
) -> std::result::Result<ModelGatewayStatusView, ApiError> {
    let generated_at = Utc::now();
    let profiles = state
        .storage
        .model_gateway_profiles()
        .list_all(state.tenant_id)
        .await
        .map_err(ApiError::from_storage)?;
    let usage_by_profile: HashMap<String, ModelGatewayProfileUsageSummary> = state
        .storage
        .model_gateway_profiles()
        .summarize_recent_usage(state.tenant_id, generated_at - Duration::hours(1))
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .map(|summary| (summary.profile_id.clone(), summary))
        .collect();

    let mut sources = Vec::new();
    let mut seen_profile_ids = HashSet::new();
    let mut database_profile_count_by_lane = BTreeMap::<String, usize>::new();
    let mut enabled_database_profile_count_by_lane = BTreeMap::<String, usize>::new();
    for profile in profiles {
        *database_profile_count_by_lane
            .entry(profile.lane.clone())
            .or_default() += 1;
        if profile.enabled {
            *enabled_database_profile_count_by_lane
                .entry(profile.lane.clone())
                .or_default() += 1;
        }
        seen_profile_ids.insert(profile.profile_id.clone());
        sources.push(model_gateway_status_source_from_record(profile));
    }

    let mut env_profile_count_by_lane = BTreeMap::<String, usize>::new();
    if let Some(config) =
        ModelGatewayPoolConfig::from_env(MODEL_LANE_ASSISTANT_CHAT).map_err(|error| {
            ApiError::internal(
                "model_gateway_pool_env_invalid",
                format!("failed to load assistant chat model gateway pool: {error}"),
            )
        })?
    {
        let env_profiles = config.active_profiles_by_priority();
        env_profile_count_by_lane.insert(config.lane.clone(), env_profiles.len());
        state.gateway_limiter.ensure_lane_limit(
            &config.lane,
            config.lane_limits.max_concurrency,
            config.lane_limits.queue_limit,
            config.lane_limits.queue_timeout_ms,
        );
        for profile in env_profiles {
            if seen_profile_ids.insert(profile.profile_id.clone()) {
                sources.push(model_gateway_status_source_from_env_profile(
                    &config.lane,
                    profile,
                ));
            }
        }
    }

    let mut profile_counts_by_lane = BTreeMap::<String, usize>::new();
    profile_counts_by_lane
        .entry(MODEL_LANE_ASSISTANT_CHAT.to_string())
        .or_default();
    for source in &sources {
        *profile_counts_by_lane
            .entry(source.lane.clone())
            .or_default() += 1;
    }

    let lanes = profile_counts_by_lane
        .iter()
        .map(|(lane, profile_count)| {
            let snapshot = state.gateway_limiter.lane_snapshot(lane);
            let database_profile_count = database_profile_count_by_lane
                .get(lane)
                .copied()
                .unwrap_or(0);
            let enabled_database_profile_count = enabled_database_profile_count_by_lane
                .get(lane)
                .copied()
                .unwrap_or(0);
            let env_profile_count = env_profile_count_by_lane.get(lane).copied().unwrap_or(0);
            let active_source =
                model_gateway_lane_active_source(enabled_database_profile_count, env_profile_count);
            ModelGatewayLaneStatusView {
                lane: lane.clone(),
                routing_mode: model_gateway_lane_routing_mode(lane),
                active_source: active_source.to_string(),
                canary_percent: model_gateway_lane_canary_percent(lane),
                max_concurrency: snapshot.max_concurrency,
                active: snapshot.active,
                queued: snapshot.queued,
                queue_limit: snapshot.queue_limit,
                queue_timeout_ms: snapshot.queue_timeout_ms,
                profile_count: *profile_count,
                active_profile_count: model_gateway_lane_active_profile_count(
                    active_source,
                    enabled_database_profile_count,
                    env_profile_count,
                ),
                database_profile_count,
                env_profile_count,
            }
        })
        .collect::<Vec<_>>();
    let active_source_by_lane = lanes
        .iter()
        .map(|lane| (lane.lane.clone(), lane.active_source.clone()))
        .collect::<BTreeMap<_, _>>();

    let providers = sources
        .into_iter()
        .map(|source| {
            state.gateway_limiter.ensure_profile_limit(
                &source.profile_id,
                source.max_concurrency,
                None,
                None,
            );
            state.gateway_limiter.ensure_profile_rate_limit(
                &source.profile_id,
                model_gateway_i32_to_u32(source.rpm_limit),
                model_gateway_i32_to_u32(source.tpm_limit),
            );
            let limit_snapshot = state.gateway_limiter.profile_snapshot(&source.profile_id);
            let rate_snapshot = state
                .gateway_limiter
                .profile_rate_snapshot(&source.profile_id);
            let stats = state
                .gateway_limiter
                .provider_stats_snapshot(&source.profile_id);
            let usage = usage_by_profile.get(&source.profile_id);
            let active_source = active_source_by_lane
                .get(&source.lane)
                .map(String::as_str)
                .unwrap_or("none");
            let eligible = model_gateway_provider_source_eligible(&source, active_source);
            let dormant_reason =
                model_gateway_provider_dormant_reason(&source, active_source).map(str::to_string);
            let quality_score = usage.and_then(|summary| {
                model_gateway_percent(summary.shadow_eval_pass_count, summary.shadow_eval_count)
            });
            let format_pass_rate = usage.and_then(|summary| {
                model_gateway_percent(
                    summary.shadow_eval_format_pass_count,
                    summary.shadow_eval_count,
                )
            });
            let repair_rate = usage.and_then(|summary| {
                model_gateway_percent(summary.shadow_eval_repair_count, summary.shadow_eval_count)
            });
            ModelGatewayProviderStatusView {
                profile_id: source.profile_id,
                display_name: source.display_name,
                lane: source.lane,
                provider_id: source.provider_id,
                model_id: source.model_id,
                wire_api: source.wire_api,
                source: source.source,
                eligible,
                dormant_reason,
                priority: source.priority,
                enabled: source.enabled,
                max_concurrency: limit_snapshot.max_concurrency,
                active: limit_snapshot.active,
                queued: limit_snapshot.queued,
                queue_limit: limit_snapshot.queue_limit,
                queue_timeout_ms: limit_snapshot.queue_timeout_ms,
                rpm_limit: source.rpm_limit,
                tpm_limit: source.tpm_limit,
                minute_request_count: rate_snapshot.request_count,
                minute_token_count: rate_snapshot.token_count,
                request_count: usage
                    .map(|summary| summary.request_count as u64)
                    .unwrap_or(0),
                success_count: usage
                    .map(|summary| summary.success_count as u64)
                    .unwrap_or(0),
                failure_count: usage
                    .map(|summary| summary.failure_count as u64)
                    .unwrap_or(0),
                timeout_count: usage
                    .map(|summary| summary.timeout_count as u64)
                    .unwrap_or(0),
                rate_limit_count: usage
                    .map(|summary| summary.rate_limit_count as u64)
                    .unwrap_or(0),
                would_throttle_count: usage
                    .map(|summary| summary.would_throttle_count as u64)
                    .unwrap_or(0),
                input_tokens: usage
                    .map(|summary| summary.input_tokens as u64)
                    .unwrap_or(0),
                output_tokens: usage
                    .map(|summary| summary.output_tokens as u64)
                    .unwrap_or(0),
                runtime_success_count: stats.success_count,
                runtime_failure_count: stats.failure_count,
                runtime_timeout_count: stats.timeout_count,
                runtime_rate_limit_count: stats.rate_limit_count,
                shadow_eval_count: usage
                    .map(|summary| summary.shadow_eval_count as u64)
                    .unwrap_or(0),
                shadow_eval_pass_count: usage
                    .map(|summary| summary.shadow_eval_pass_count as u64)
                    .unwrap_or(0),
                shadow_eval_fail_count: usage
                    .map(|summary| summary.shadow_eval_fail_count as u64)
                    .unwrap_or(0),
                shadow_eval_format_pass_count: usage
                    .map(|summary| summary.shadow_eval_format_pass_count as u64)
                    .unwrap_or(0),
                shadow_eval_repair_count: usage
                    .map(|summary| summary.shadow_eval_repair_count as u64)
                    .unwrap_or(0),
                quality_score,
                format_pass_rate,
                repair_rate,
                last_shadow_eval_at: usage.and_then(|summary| summary.last_shadow_eval_at.clone()),
                last_profile_test_status: usage
                    .and_then(|summary| summary.last_profile_test_status.clone()),
                last_profile_test_at: usage
                    .and_then(|summary| summary.last_profile_test_at.clone()),
                consecutive_failures: stats.consecutive_failures,
                p50_latency_ms: stats.p50_latency_ms,
                p95_latency_ms: stats.p95_latency_ms,
                circuit_open: stats.circuit_open,
                opened_until: stats.opened_until,
                last_success_at: stats.last_success_at,
                last_failure_at: stats.last_failure_at,
                last_failure_reason: stats.last_failure_reason,
            }
        })
        .collect();

    Ok(ModelGatewayStatusView {
        generated_at,
        lanes,
        providers,
        runtime: model_gateway_runtime_status_view(state).await?,
    })
}

