async fn test_model_gateway_profile(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(profile_id): Path<String>,
    Json(request): Json<ModelGatewayProfileTestRequest>,
) -> std::result::Result<Json<ModelGatewayProfileTestResponse>, ApiError> {
    let _user = require_model_gateway_operator_session(&state, &headers).await?;
    let profile_id = validate_model_gateway_profile_id(&profile_id)?;
    validate_model_gateway_numeric("timeout_ms", request.timeout_ms)?;
    let profile = state
        .storage
        .model_gateway_profiles()
        .get_by_profile_id(state.tenant_id, &profile_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| model_gateway_profile_not_found(&profile_id))?;
    let auth_configured = profile
        .auth_env_key_name
        .as_deref()
        .map(model_gateway_auth_env_is_configured)
        .unwrap_or(false);
    if model_gateway_profile_requires_configured_auth_env(&profile) && !auth_configured {
        let checked_at = Utc::now();
        record_model_gateway_profile_test_event(
            &state,
            &profile,
            "missing_secret",
            None,
            Some("missing_secret"),
            checked_at,
        )
        .await?;
        return Ok(Json(ModelGatewayProfileTestResponse {
            profile_id: profile.profile_id,
            status: "missing_secret".to_string(),
            message: "未找到该 profile 绑定的环境变量，请先在服务端配置 API Key。".to_string(),
            auth_configured,
            checked_at,
        }));
    }

    let probe_timeout_ms = request
        .timeout_ms
        .map(|value| value as u64)
        .unwrap_or(5_000)
        .clamp(1_000, 30_000);
    let mut provider_profile = model_gateway_provider_profile_from_record(profile.clone());
    provider_profile.timeout_ms = Some(probe_timeout_ms);
    let probe_started_at = Instant::now();
    let probe_result = run_model_gateway_profile_probe(provider_profile).await;
    let latency_ms = Some(probe_started_at.elapsed().as_millis() as u64);
    let (status, message, error_kind) = if let Ok(response) = probe_result {
        let reply_chars = response.output_text.trim().chars().count();
        if reply_chars == 0 {
            (
                "failed".to_string(),
                "真实连通性检查失败：provider 返回空回复。".to_string(),
                Some("empty_provider_reply"),
            )
        } else {
            (
                "ok".to_string(),
                format!("真实连通性检查通过，收到 {reply_chars} 字回复。"),
                None,
            )
        }
    } else {
        (
            "failed".to_string(),
            "真实连通性检查失败，已隐藏 provider 错误细节。".to_string(),
            Some("provider_probe_failed"),
        )
    };
    let checked_at = Utc::now();
    record_model_gateway_profile_test_event(
        &state, &profile, &status, latency_ms, error_kind, checked_at,
    )
    .await?;

    Ok(Json(ModelGatewayProfileTestResponse {
        profile_id: profile.profile_id,
        status,
        message,
        auth_configured,
        checked_at,
    }))
}

fn model_gateway_profile_requires_configured_auth_env(profile: &ModelGatewayProfile) -> bool {
    let auth_mode = profile.auth_mode.trim().to_ascii_lowercase();
    if auth_mode.is_empty() || auth_mode == "none" {
        return false;
    }
    auth_mode == "env_key" || auth_mode.ends_with("_env") || auth_mode.contains("env_key")
}

async fn record_model_gateway_profile_test_event(
    state: &AppState,
    profile: &ModelGatewayProfile,
    status: &str,
    latency_ms: Option<u64>,
    error_kind: Option<&str>,
    now: DateTime<Utc>,
) -> std::result::Result<(), ApiError> {
    let event_type = match status {
        "ok" => "profile_test_ok",
        "missing_secret" => "profile_test_missing_secret",
        _ => "profile_test_failed",
    };
    state
        .storage
        .model_gateway_profiles()
        .record_event(
            state.tenant_id,
            NewModelGatewayProfileEvent {
                profile_id: profile.profile_id.clone(),
                lane: profile.lane.clone(),
                event_type: event_type.to_string(),
                latency_ms: latency_ms.and_then(model_gateway_u64_to_i32),
                input_tokens: None,
                output_tokens: None,
                error_kind: error_kind.map(model_gateway_sanitized_error_kind),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)
}

async fn run_model_gateway_profile_probe(
    profile: ModelProviderProfile,
) -> std::result::Result<LlmResponse, ApiError> {
    tokio::task::spawn_blocking(move || {
        let env_prefix = model_gateway_profile_env_prefix(&profile.profile_id);
        let model = profile.model_id.clone();
        let provider = build_provider_from_profile_env(
            &env_prefix,
            &profile,
            bootstrap_default_prompt_registry(),
        )?;
        let request = LlmRequest {
            model,
            lane: Some(MODEL_LANE_ASSISTANT_CHAT.to_string()),
            system_prompt_key: None,
            input: "请用一句话回复：model gateway profile smoke test".to_string(),
        };
        provider.complete(&request)
    })
    .await
    .map_err(|error| {
        ApiError::internal(
            "model_gateway_profile_probe_join_failed",
            format!("model gateway profile probe worker join failed: {error}"),
        )
    })?
    .map_err(|_error| {
        ApiError::bad_request(
            "model_gateway_profile_probe_failed",
            "model gateway profile probe failed".to_string(),
        )
    })
}

fn model_gateway_new_profile_from_request(
    request: ModelGatewayProfileCreateRequest,
) -> std::result::Result<NewModelGatewayProfile, ApiError> {
    let preset = request
        .recommended_preset
        .as_deref()
        .and_then(model_gateway_preset_by_id);
    let profile_id = validate_model_gateway_profile_id(&request.profile_id)?;
    let display_name = validate_model_gateway_required_text("display_name", &request.display_name)?;
    let lane = model_gateway_optional_text(request.lane)
        .or_else(|| preset.as_ref().map(|preset| preset.lane.clone()))
        .unwrap_or_else(|| MODEL_GATEWAY_DEFAULT_LANE.to_string());
    let provider_id = model_gateway_optional_text(request.provider_id)
        .or_else(|| preset.as_ref().map(|preset| preset.provider_id.clone()))
        .unwrap_or_else(|| "custom".to_string());
    let model_id = model_gateway_optional_text(request.model_id)
        .or_else(|| preset.as_ref().map(|preset| preset.model_id.clone()))
        .unwrap_or_else(|| "custom".to_string());
    let wire_api = model_gateway_optional_text(request.wire_api)
        .or_else(|| preset.as_ref().map(|preset| preset.wire_api.clone()))
        .unwrap_or_else(|| "openai-compatible".to_string());
    let capabilities = request
        .capabilities
        .or_else(|| preset.as_ref().map(|preset| preset.capabilities.clone()))
        .unwrap_or_else(|| json!({}));

    validate_model_gateway_numeric("max_concurrency", request.max_concurrency)?;
    validate_model_gateway_numeric("rpm_limit", request.rpm_limit)?;
    validate_model_gateway_numeric("tpm_limit", request.tpm_limit)?;
    validate_model_gateway_numeric("timeout_ms", request.timeout_ms)?;

    Ok(NewModelGatewayProfile {
        id: Uuid::new_v4(),
        profile_id,
        display_name,
        lane,
        provider_id,
        model_id,
        base_url: model_gateway_optional_text(request.base_url),
        api_path: model_gateway_optional_text(request.api_path)
            .or_else(|| preset.as_ref().and_then(|preset| preset.api_path.clone())),
        wire_api,
        auth_mode: model_gateway_optional_text(request.auth_mode)
            .unwrap_or_else(|| "env_key".to_string()),
        auth_env_key_name: model_gateway_optional_text(request.auth_env_key_name),
        recommended_preset: model_gateway_optional_text(request.recommended_preset)
            .or_else(|| preset.as_ref().map(|preset| preset.preset_id.clone())),
        max_concurrency: request
            .max_concurrency
            .or_else(|| preset.as_ref().map(|preset| preset.max_concurrency)),
        rpm_limit: request
            .rpm_limit
            .or_else(|| preset.as_ref().and_then(|preset| preset.rpm_limit)),
        tpm_limit: request
            .tpm_limit
            .or_else(|| preset.as_ref().and_then(|preset| preset.tpm_limit)),
        timeout_ms: request
            .timeout_ms
            .or_else(|| preset.as_ref().map(|preset| preset.timeout_ms)),
        priority: request
            .priority
            .or_else(|| preset.as_ref().map(|preset| preset.priority))
            .unwrap_or(100),
        enabled: request.enabled.unwrap_or(true),
        capabilities,
    })
}

fn model_gateway_update_from_request(
    request: ModelGatewayProfileUpdateRequest,
) -> std::result::Result<ModelGatewayProfileUpdate, ApiError> {
    validate_model_gateway_numeric("max_concurrency", request.max_concurrency)?;
    validate_model_gateway_numeric("rpm_limit", request.rpm_limit)?;
    validate_model_gateway_numeric("tpm_limit", request.tpm_limit)?;
    validate_model_gateway_numeric("timeout_ms", request.timeout_ms)?;

    Ok(ModelGatewayProfileUpdate {
        display_name: request
            .display_name
            .map(|value| validate_model_gateway_required_text("display_name", &value))
            .transpose()?,
        lane: request
            .lane
            .map(|value| validate_model_gateway_required_text("lane", &value))
            .transpose()?,
        provider_id: request
            .provider_id
            .map(|value| validate_model_gateway_required_text("provider_id", &value))
            .transpose()?,
        model_id: request
            .model_id
            .map(|value| validate_model_gateway_required_text("model_id", &value))
            .transpose()?,
        base_url: request.base_url.map(|value| value.trim().to_string()),
        api_path: request.api_path.map(|value| value.trim().to_string()),
        wire_api: request
            .wire_api
            .map(|value| validate_model_gateway_required_text("wire_api", &value))
            .transpose()?,
        auth_mode: request
            .auth_mode
            .map(|value| validate_model_gateway_required_text("auth_mode", &value))
            .transpose()?,
        auth_env_key_name: request
            .auth_env_key_name
            .map(|value| value.trim().to_string()),
        recommended_preset: request
            .recommended_preset
            .map(|value| value.trim().to_string()),
        max_concurrency: request.max_concurrency,
        rpm_limit: request.rpm_limit,
        tpm_limit: request.tpm_limit,
        timeout_ms: request.timeout_ms,
        priority: request.priority,
        enabled: request.enabled,
        capabilities: request.capabilities,
    })
}

fn model_gateway_profile_view(profile: ModelGatewayProfile) -> ModelGatewayProfileView {
    let has_secret = profile
        .auth_env_key_name
        .as_deref()
        .map(model_gateway_auth_env_is_configured)
        .unwrap_or(false);

    ModelGatewayProfileView {
        id: profile.id.to_string(),
        profile_id: profile.profile_id,
        display_name: profile.display_name,
        lane: profile.lane,
        provider_id: profile.provider_id,
        model_id: profile.model_id,
        base_url: profile.base_url.map(|url| redact_model_gateway_url(&url)),
        api_path: profile.api_path,
        wire_api: profile.wire_api,
        auth_mode: profile.auth_mode,
        auth_env_key_name: profile.auth_env_key_name,
        has_secret,
        recommended_preset: profile.recommended_preset,
        max_concurrency: profile.max_concurrency,
        rpm_limit: profile.rpm_limit,
        tpm_limit: profile.tpm_limit,
        timeout_ms: profile.timeout_ms,
        priority: profile.priority,
        enabled: profile.enabled,
        capabilities: profile.capabilities,
        created_at: profile.created_at,
        updated_at: profile.updated_at,
    }
}

fn model_gateway_optional_text(value: Option<String>) -> Option<String> {
    value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn validate_model_gateway_profile_id(value: &str) -> std::result::Result<String, ApiError> {
    let normalized = value.trim();
    if normalized.is_empty() || normalized.len() > 128 {
        return Err(ApiError::bad_request(
            "invalid_model_gateway_profile_id",
            "profile_id 不能为空，且长度不能超过 128".to_string(),
        ));
    }
    if !normalized
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.'))
    {
        return Err(ApiError::bad_request(
            "invalid_model_gateway_profile_id",
            "profile_id 只能包含字母、数字、短横线、下划线或点号".to_string(),
        ));
    }

    Ok(normalized.to_string())
}

fn validate_model_gateway_required_text(
    field: &'static str,
    value: &str,
) -> std::result::Result<String, ApiError> {
    let normalized = value.trim();
    if normalized.is_empty() {
        return Err(ApiError::bad_request(
            "validation_error",
            format!("{field} is required"),
        ));
    }
    Ok(normalized.to_string())
}

fn validate_model_gateway_numeric(
    field: &'static str,
    value: Option<i32>,
) -> std::result::Result<(), ApiError> {
    if value.is_some_and(|value| value <= 0) {
        return Err(ApiError::bad_request(
            "validation_error",
            format!("{field} must be greater than 0"),
        ));
    }
    Ok(())
}

fn model_gateway_auth_env_is_configured(env_key_name: &str) -> bool {
    std::env::var(env_key_name)
        .ok()
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn redact_model_gateway_url(url: &str) -> String {
    let Some((scheme, rest)) = url.split_once("://") else {
        return url.to_string();
    };
    let Some(at_index) = rest.find('@') else {
        return url.to_string();
    };
    let slash_index = rest.find('/').unwrap_or(rest.len());
    if at_index > slash_index {
        return url.to_string();
    }
    format!("{scheme}://[redacted]@{}", &rest[at_index + 1..])
}

fn model_gateway_profile_not_found(profile_id: &str) -> ApiError {
    ApiError::not_found(
        "model_gateway_profile_not_found",
        format!("model gateway profile {profile_id} was not found"),
    )
}

fn auth_session_token_from_headers(headers: &HeaderMap) -> Option<String> {
    let raw = headers.get(header::COOKIE)?.to_str().ok()?;
    raw.split(';').find_map(|entry| {
        let (name, value) = entry.trim().split_once('=')?;
        (name == AUTH_SESSION_COOKIE_NAME && !value.is_empty()).then(|| value.to_string())
    })
}

fn set_session_cookie_headers(session_token: &str) -> std::result::Result<HeaderMap, ApiError> {
    let mut headers = HeaderMap::new();
    headers.insert(
        header::SET_COOKIE,
        HeaderValue::from_str(&format!(
            "{AUTH_SESSION_COOKIE_NAME}={session_token}; Path=/; HttpOnly; SameSite=Lax; Max-Age={}",
            AUTH_SESSION_TTL_DAYS * 24 * 60 * 60
        ))
        .map_err(|error| ApiError::internal("auth_cookie_invalid", error.to_string()))?,
    );
    Ok(headers)
}

fn clear_session_cookie_headers() -> std::result::Result<HeaderMap, ApiError> {
    let mut headers = HeaderMap::new();
    headers.insert(
        header::SET_COOKIE,
        HeaderValue::from_str(&format!(
            "{AUTH_SESSION_COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0"
        ))
        .map_err(|error| ApiError::internal("auth_cookie_invalid", error.to_string()))?,
    );
    Ok(headers)
}

fn to_auth_user_view(user: &User, email_verified: bool) -> AuthUserView {
    AuthUserView {
        id: user.id,
        email: user.email.clone(),
        display_name: user.display_name.clone(),
        email_verified,
    }
}

fn to_auth_session_view(session: &UserSession, email: &str) -> AuthSessionView {
    AuthSessionView {
        id: session.id,
        user_id: session.user_id,
        email: email.to_string(),
        auth_method: session.auth_method.clone(),
        created_at: session.created_at,
        expires_at: session.expires_at,
    }
}

fn to_auth_audit_event_view(
    event: AuthAuditEvent,
    current_session_id: UserSessionId,
) -> AuthAuditEventView {
    AuthAuditEventView {
        id: event.id,
        event_name: event.event_name,
        outcome: event.outcome,
        email: event.email_normalized,
        device_fingerprint: event.device_fingerprint,
        current_session: event.session_id == Some(current_session_id),
        details: safe_auth_audit_details(&event.metadata),
        created_at: event.created_at,
    }
}

fn safe_auth_audit_details(metadata: &Value) -> Value {
    let Some(object) = metadata.as_object() else {
        return json!({});
    };

    let mut details = Map::new();
    for key in [
        "purpose",
        "reason",
        "auth_method",
        "reused",
        "revoked",
        "matched_binding_count",
        "claimed_dataset_count",
        "skipped_owned_dataset_count",
        "attempt_count_before",
    ] {
        if let Some(value) = object.get(key) {
            details.insert(key.to_string(), value.clone());
        }
    }
    Value::Object(details)
}

fn merge_secret_binding_ids(
    left: &[SecretBindingId],
    right: &[SecretBindingId],
) -> Vec<SecretBindingId> {
    let mut merged = Vec::with_capacity(left.len() + right.len());
    for id in left.iter().chain(right.iter()) {
        if !merged.iter().any(|existing| existing == id) {
            merged.push(*id);
        }
    }
    merged
}

fn dataset_is_visible(
    dataset: &Dataset,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> bool {
    dataset
        .owner_user_id
        .is_some_and(|owner_user_id| Some(owner_user_id) == current_user_id)
        || (dataset.owner_user_id.is_none() && dataset.visibility == DatasetVisibility::Public)
        || dataset.default_secret_binding_ids.iter().any(|secret_id| {
            active_secret_binding_ids
                .iter()
                .any(|active_id| active_id == secret_id)
        })
}

fn dataset_local_scope_is_visible(dataset: &Dataset, local_thread_id: Option<&str>) -> bool {
    let local_only = dataset
        .metadata
        .get("local_only")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if !local_only || dataset.owner_user_id.is_some() {
        return true;
    }
    dataset
        .metadata
        .get("local_thread_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .is_some_and(|dataset_thread_id| Some(dataset_thread_id) == local_thread_id)
}

fn dataset_is_visible_by_local_thread_scope(
    dataset: &Dataset,
    local_thread_id: Option<&str>,
) -> bool {
    dataset.owner_user_id.is_none()
        && dataset
            .metadata
            .get("local_only")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        && dataset
            .metadata
            .get("local_thread_id")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .is_some_and(|dataset_thread_id| Some(dataset_thread_id) == local_thread_id)
}

fn dataset_is_visible_for_request(
    dataset: &Dataset,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
) -> bool {
    (dataset_is_visible(dataset, active_secret_binding_ids, current_user_id)
        && dataset_local_scope_is_visible(dataset, local_thread_id))
        || dataset_is_visible_by_local_thread_scope(dataset, local_thread_id)
}

fn dataset_is_hidden_from_standard_dataset_list(dataset: &Dataset) -> bool {
    dataset_is_external_temporary_scope(dataset)
        || dataset_is_system_external_document_parse_source(dataset)
}

fn dataset_is_system_external_document_parse_source(dataset: &Dataset) -> bool {
    if dataset.key.starts_with("external-parse-dataset-") {
        return true;
    }
    dataset
        .metadata
        .get("external_source")
        .or_else(|| dataset.metadata.get("externalSource"))
        .and_then(Value::as_object)
        .and_then(|external_source| {
            external_source
                .get("created_by")
                .or_else(|| external_source.get("createdBy"))
        })
        .and_then(Value::as_str)
        == Some("external_document_parse")
}

fn filter_visible_datasets(
    datasets: Vec<Dataset>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
) -> Vec<Dataset> {
    datasets
        .into_iter()
        .filter(|dataset| {
            dataset_is_visible_for_request(
                dataset,
                active_secret_binding_ids,
                current_user_id,
                local_thread_id,
            )
        })
        .collect()
}

async fn enrich_visible_datasets_for_scope_planning(
    state: &AppState,
    datasets: Vec<Dataset>,
    current_user_id: Option<UserId>,
) -> std::result::Result<Vec<Dataset>, ApiError> {
    let mut enriched = Vec::with_capacity(datasets.len());
    for mut dataset in datasets {
        let documents = list_documents_for_dataset_scope(state, dataset.id)
            .await?
            .into_iter()
            .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
            .collect::<Vec<_>>();
        if documents.is_empty() {
            enriched.push(dataset);
            continue;
        }

        let mut estimated_word_count = 0usize;
        let mut parse_status_counts = BTreeMap::<String, usize>::new();
        let mut content_type_counts = BTreeMap::<String, usize>::new();
        let mut document_title_hints = BTreeSet::<String>::new();
        let mut material_hints = BTreeSet::<String>::new();
        let mut noun_term_hints = BTreeSet::<String>::new();
        let mut section_title_hints = BTreeSet::<String>::new();
        let mut understanding_strategy_hints = BTreeSet::<String>::new();

        for hint in dataset
            .metadata
            .get("document_title_hints")
            .or_else(|| dataset.metadata.get("documentTitleHints"))
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            document_title_hints.insert(hint.to_string());
        }

        for hint in dataset
            .metadata
            .get("material_hints")
            .or_else(|| dataset.metadata.get("materialHints"))
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            material_hints.insert(hint.to_string());
        }

        for (index, document) in documents.iter().enumerate() {
            let chunks = if index < ASSISTANT_RUN_SCOPE_SUMMARY_DOC_LIMIT {
                state
                    .storage
                    .document_chunks()
                    .list_by_document(state.tenant_id, document.id)
                    .await
                    .map_err(ApiError::from_storage)?
            } else {
                Vec::new()
            };
            estimated_word_count += assistant_scope_document_word_count(document, &chunks);
            *parse_status_counts
                .entry(assistant_scope_document_parse_status(document, &chunks))
                .or_insert(0) += 1;
            *content_type_counts
                .entry(assistant_scope_content_kind(&document.content_type).to_string())
                .or_insert(0) += 1;
            if let Some(title_hint) = assistant_scope_document_title_hint(document) {
                document_title_hints.insert(title_hint);
            }
            assistant_scope_collect_material_hints(document, &chunks, &mut material_hints);
            assistant_scope_collect_document_understanding_hints(
                &chunks,
                &mut noun_term_hints,
                &mut section_title_hints,
                &mut understanding_strategy_hints,
            );
        }

        let document_count = documents.len();
        let latest_activity = documents
            .iter()
            .map(|document| document.updated_at)
            .max()
            .unwrap_or(dataset.updated_at);

        dataset
            .metadata
            .insert("document_count".to_string(), json!(document_count));
        dataset
            .metadata
            .insert("documents_count".to_string(), json!(document_count));
        if estimated_word_count > 0 {
            dataset.metadata.insert(
                "estimated_word_count".to_string(),
                json!(estimated_word_count),
            );
        }
        dataset.metadata.insert(
            "parse_status_summary".to_string(),
            json!(assistant_scope_count_summary(&parse_status_counts)),
        );
        dataset.metadata.insert(
            "content_type_summary".to_string(),
            json!(assistant_scope_count_summary(&content_type_counts)),
        );
        dataset.metadata.insert(
            "latest_upload".to_string(),
            json!(latest_activity.to_rfc3339()),
        );
        if !document_title_hints.is_empty() {
            dataset.metadata.insert(
                "document_title_hints".to_string(),
                json!(document_title_hints
                    .into_iter()
                    .take(12)
                    .collect::<Vec<_>>()),
            );
        }
        if !material_hints.is_empty() {
            dataset.metadata.insert(
                "material_hints".to_string(),
                json!(material_hints.into_iter().take(8).collect::<Vec<_>>()),
            );
        }
        if !noun_term_hints.is_empty() {
            dataset.metadata.insert(
                "noun_term_hints".to_string(),
                json!(noun_term_hints.into_iter().take(16).collect::<Vec<_>>()),
            );
        }
        if !section_title_hints.is_empty() {
            dataset.metadata.insert(
                "section_title_hints".to_string(),
                json!(section_title_hints.into_iter().take(16).collect::<Vec<_>>()),
            );
        }
        if !understanding_strategy_hints.is_empty() {
            dataset.metadata.insert(
                "document_understanding_strategies".to_string(),
                json!(understanding_strategy_hints
                    .into_iter()
                    .take(6)
                    .collect::<Vec<_>>()),
            );
        }
        enriched.push(dataset);
    }
    Ok(enriched)
}

fn assistant_scope_document_word_count(document: &Document, chunks: &[DocumentChunk]) -> usize {
    let chunk_tokens = chunks
        .iter()
        .map(|chunk| chunk.token_count.max(0) as usize)
        .sum::<usize>();
    if chunk_tokens > 0 {
        return chunk_tokens;
    }
    for key in [
        "estimated_word_count",
        "estimatedWordCount",
        "word_count",
        "wordCount",
    ] {
        if let Some(value) = document.metadata.get(key).and_then(|value| {
            value
                .as_u64()
                .or_else(|| value.as_str()?.parse::<u64>().ok())
        }) {
            return value as usize;
        }
    }
    0
}

fn assistant_scope_document_title_hint(document: &Document) -> Option<String> {
    let raw_title = document.title.trim();
    let raw = if raw_title.is_empty() {
        let filename = document
            .object_key
            .rsplit('/')
            .next()
            .unwrap_or(&document.object_key)
            .rsplit('\\')
            .next()
            .unwrap_or(&document.object_key);
        filename.trim()
    } else {
        raw_title
    };
    let without_extension = raw
        .rsplit_once('.')
        .and_then(|(stem, extension)| {
            let stem = stem.trim();
            let extension = extension.trim();
            if stem.is_empty() || extension.is_empty() || extension.chars().any(char::is_whitespace)
            {
                None
            } else {
                Some(stem)
            }
        })
        .unwrap_or(raw);
    let normalized =
        without_extension.trim_matches(|ch: char| ch.is_whitespace() || ".-_".contains(ch));
    if normalized.is_empty() {
        None
    } else {
        Some(normalized.chars().take(80).collect())
    }
}

fn assistant_scope_document_parse_status(document: &Document, chunks: &[DocumentChunk]) -> String {
    if let Some(value) = document_metadata_parse_status(document) {
        return value;
    }
    if let Some(parse_status) = extract_media_metadata_from_chunks(chunks).and_then(|metadata| {
        metadata
            .get("parse_status")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    }) {
        return parse_status;
    }
    document.lifecycle.as_str().to_string()
}

fn document_metadata_parse_status(document: &Document) -> Option<String> {
    for key in ["parse_status", "parseStatus", "status"] {
        if let Some(value) = document
            .metadata
            .get(key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            return Some(value.to_string());
        }
    }
    None
}

fn assistant_scope_content_kind(content_type: &str) -> &'static str {
    let lower = content_type.trim().to_ascii_lowercase();
    if lower.starts_with("audio/") {
        "audio"
    } else if lower.starts_with("video/") {
        "video"
    } else if lower.starts_with("image/") {
        "image"
    } else if lower.contains("pdf") {
        "pdf"
    } else if lower.contains("spreadsheet") || lower.contains("excel") || lower.contains("csv") {
        "spreadsheet"
    } else if lower.contains("presentation") || lower.contains("powerpoint") {
        "presentation"
    } else if lower.starts_with("text/") || lower.contains("document") || lower.contains("word") {
        "text"
    } else {
        "other"
    }
}

fn assistant_scope_collect_material_hints(
    document: &Document,
    chunks: &[DocumentChunk],
    material_hints: &mut BTreeSet<String>,
) {
    match infer_media_kind_from_content_type(&document.content_type) {
        "audio" | "video" => {
            material_hints.insert("audio_video".to_string());
        }
        _ => {}
    }
    if let Some(media_metadata) = extract_media_metadata_from_chunks(chunks) {
        material_hints.insert("audio_video".to_string());
        if media_metadata
            .get("transcript_segments")
            .and_then(Value::as_array)
            .is_some_and(|items| !items.is_empty())
        {
            material_hints.insert("transcript_possible".to_string());
        }
        if media_metadata
            .get("scenes")
            .and_then(Value::as_array)
            .is_some_and(|items| !items.is_empty())
        {
            material_hints.insert("scene_possible".to_string());
        }
        if media_metadata
            .get("keyframe_ocr_snippets")
            .and_then(Value::as_array)
            .is_some_and(|items| !items.is_empty())
        {
            material_hints.insert("keyframe_ocr_possible".to_string());
        }
    }
}

fn assistant_scope_collect_document_understanding_hints(
    chunks: &[DocumentChunk],
    noun_term_hints: &mut BTreeSet<String>,
    section_title_hints: &mut BTreeSet<String>,
    understanding_strategy_hints: &mut BTreeSet<String>,
) {
    for chunk in chunks {
        for term in document_chunk_noun_terms(chunk).into_iter().take(16) {
            noun_term_hints.insert(term);
            if noun_term_hints.len() >= 64 {
                break;
            }
        }
        for hint in document_chunk_section_title_hints(chunk)
            .into_iter()
            .take(8)
        {
            section_title_hints.insert(hint);
            if section_title_hints.len() >= 64 {
                break;
            }
        }
        if let Some(strategy) = chunk
            .metadata
            .get("understanding")
            .and_then(|value| value.get("strategy"))
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            understanding_strategy_hints.insert(strategy.to_string());
        }
        if noun_term_hints.len() >= 64
            && section_title_hints.len() >= 64
            && understanding_strategy_hints.len() >= 8
        {
            break;
        }
    }
}

fn assistant_scope_count_summary(counts: &BTreeMap<String, usize>) -> String {
    counts
        .iter()
        .map(|(key, count)| format!("{key}:{count}"))
        .collect::<Vec<_>>()
        .join("，")
}

fn owner_user_id_is_visible(
    owner_user_id: Option<UserId>,
    current_user_id: Option<UserId>,
) -> bool {
    owner_user_id.is_none() || owner_user_id == current_user_id
}

fn ensure_owner_managed_resource(
    resource_kind: &'static str,
    resource_id: String,
    owner_user_id: Option<UserId>,
    current_user_id: Option<UserId>,
) -> std::result::Result<(), ApiError> {
    if owner_user_id.is_some() && owner_user_id != current_user_id {
        return Err(ApiError::not_found(
            &format!("{resource_kind}_not_found"),
            format!("{resource_kind} {resource_id} was not found"),
        ));
    }
    Ok(())
}

fn parse_dataset_lifecycle_update(
    lifecycle: Option<String>,
) -> std::result::Result<Option<DatasetLifecycle>, ApiError> {
    lifecycle
        .map(|value| {
            let normalized = value.trim().to_ascii_lowercase();
            DatasetLifecycle::from_str(&normalized).ok_or_else(|| {
                ApiError::bad_request(
                    "validation_error",
                    format!("unsupported dataset lifecycle: {value}"),
                )
            })
        })
        .transpose()
}

fn parse_document_lifecycle_update(
    lifecycle: Option<String>,
) -> std::result::Result<Option<DocumentLifecycle>, ApiError> {
    lifecycle
        .map(|value| {
            let normalized = value.trim().to_ascii_lowercase();
            DocumentLifecycle::from_str(&normalized).ok_or_else(|| {
                ApiError::bad_request(
                    "validation_error",
                    format!("unsupported document lifecycle: {value}"),
                )
            })
        })
        .transpose()
}

fn dataset_not_found_error(dataset_id: DatasetId) -> ApiError {
    ApiError::not_found(
        "dataset_not_found",
        format!(
            "dataset {} was not found for tenant or current access scope",
            dataset_id
        ),
    )
}

async fn load_visible_dataset(
    state: &AppState,
    dataset_id: DatasetId,
    active_secret_binding_ids: &[SecretBindingId],
) -> std::result::Result<Dataset, ApiError> {
    load_visible_dataset_for_user(state, dataset_id, active_secret_binding_ids, None).await
}

async fn load_visible_dataset_for_user(
    state: &AppState,
    dataset_id: DatasetId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<Dataset, ApiError> {
    load_visible_dataset_for_user_with_local_scope(
        state,
        dataset_id,
        active_secret_binding_ids,
        current_user_id,
        None,
    )
    .await
}

async fn load_visible_dataset_for_user_with_local_scope(
    state: &AppState,
    dataset_id: DatasetId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
) -> std::result::Result<Dataset, ApiError> {
    let dataset = state
        .storage
        .datasets()
        .get_by_id(state.tenant_id, dataset_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| dataset_not_found_error(dataset_id))?;
    if !dataset_is_visible_for_request(
        &dataset,
        active_secret_binding_ids,
        current_user_id,
        local_thread_id,
    ) {
        return Err(dataset_not_found_error(dataset_id));
    }
    Ok(dataset)
}

async fn load_visible_dataset_for_assistant_scope(
    state: &AppState,
    dataset_id: DatasetId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
    selected_scope: &Value,
) -> std::result::Result<Dataset, ApiError> {
    match load_visible_dataset_for_user_with_local_scope(
        state,
        dataset_id,
        active_secret_binding_ids,
        current_user_id,
        local_thread_id,
    )
    .await
    {
        Ok(dataset) => Ok(dataset),
        Err(error) if selected_scope_temporary_dataset_id(selected_scope) == Some(dataset_id) => {
            let dataset = state
                .storage
                .datasets()
                .get_by_id(state.tenant_id, dataset_id)
                .await
                .map_err(ApiError::from_storage)?
                .ok_or_else(|| dataset_not_found_error(dataset_id))?;
            if dataset_is_external_temporary_scope(&dataset) {
                Ok(dataset)
            } else {
                Err(error)
            }
        }
        Err(error) => Err(error),
    }
}

async fn load_visible_document_for_user(
    state: &AppState,
    document_id: DocumentId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<Document, ApiError> {
    load_visible_document_for_user_with_local_scope(
        state,
        document_id,
        active_secret_binding_ids,
        current_user_id,
        None,
    )
    .await
}

async fn load_visible_document_for_assistant_scope(
    state: &AppState,
    document_id: DocumentId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
    selected_scope: &Value,
) -> std::result::Result<Document, ApiError> {
    match load_visible_document_for_user_with_local_scope(
        state,
        document_id,
        active_secret_binding_ids,
        current_user_id,
        local_thread_id,
    )
    .await
    {
        Ok(document) => Ok(document),
        Err(error) => {
            let Some(temporary_dataset_id) = selected_scope_temporary_dataset_id(selected_scope)
            else {
                return Err(error);
            };
            let document = state
                .storage
                .documents()
                .get_by_id(state.tenant_id, document_id)
                .await
                .map_err(ApiError::from_storage)?
                .ok_or_else(|| {
                    ApiError::not_found(
                        "document_not_found",
                        format!("document {} was not found", document_id),
                    )
                })?;
            if !owner_user_id_is_visible(document.owner_user_id, current_user_id) {
                return Err(error);
            }
            if !document_belongs_to_dataset_scope(state, &document, temporary_dataset_id).await? {
                return Err(error);
            }
            let dataset = state
                .storage
                .datasets()
                .get_by_id(state.tenant_id, temporary_dataset_id)
                .await
                .map_err(ApiError::from_storage)?
                .ok_or_else(|| dataset_not_found_error(temporary_dataset_id))?;
            if !dataset_is_external_temporary_scope(&dataset) {
                return Err(error);
            }
            Ok(document)
        }
    }
}

async fn load_visible_document_for_user_with_local_scope(
    state: &AppState,
    document_id: DocumentId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
) -> std::result::Result<Document, ApiError> {
    let document = state
        .storage
        .documents()
        .get_by_id(state.tenant_id, document_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "document_not_found",
                format!("document {} was not found", document_id),
            )
        })?;
    if !owner_user_id_is_visible(document.owner_user_id, current_user_id) {
        return Err(ApiError::not_found(
            "document_not_found",
            format!("document {} was not found", document_id),
        ));
    }
    if document_has_visible_dataset_scope(
        state,
        &document,
        active_secret_binding_ids,
        current_user_id,
        local_thread_id,
    )
    .await?
    {
        return Ok(document);
    }
    Err(ApiError::not_found(
        "document_not_found",
        format!("document {} was not found", document_id),
    ))
}

async fn document_has_visible_dataset_scope(
    state: &AppState,
    document: &Document,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
) -> std::result::Result<bool, ApiError> {
    if load_visible_dataset_for_user_with_local_scope(
        state,
        document.dataset_id,
        active_secret_binding_ids,
        current_user_id,
        local_thread_id,
    )
    .await
    .is_ok()
    {
        return Ok(true);
    }

    let membership_dataset_ids = state
        .storage
        .dataset_document_memberships()
        .list_dataset_ids_by_document(state.tenant_id, document.id)
        .await
        .map_err(ApiError::from_storage)?;
    for dataset_id in membership_dataset_ids {
        if load_visible_dataset_for_user_with_local_scope(
            state,
            dataset_id,
            active_secret_binding_ids,
            current_user_id,
            local_thread_id,
        )
        .await
        .is_ok()
        {
            return Ok(true);
        }
    }
    Ok(false)
}

async fn document_belongs_to_dataset_scope(
    state: &AppState,
    document: &Document,
    dataset_id: DatasetId,
) -> std::result::Result<bool, ApiError> {
    if document.dataset_id == dataset_id {
        return Ok(true);
    }
    let membership_dataset_ids = state
        .storage
        .dataset_document_memberships()
        .list_dataset_ids_by_document(state.tenant_id, document.id)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(membership_dataset_ids.contains(&dataset_id))
}

async fn list_documents_for_visible_dataset_scopes(
    state: &AppState,
    visible_dataset_ids: &HashSet<DatasetId>,
    current_user_id: Option<UserId>,
) -> std::result::Result<Vec<Document>, ApiError> {
    let mut documents = Vec::new();
    let mut seen = HashSet::new();
    for dataset_id in visible_dataset_ids {
        for document in list_documents_for_dataset_scope(state, *dataset_id)
            .await?
            .into_iter()
            .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
            .filter(|document| document.lifecycle != DocumentLifecycle::Archived)
        {
            if seen.insert(document.id) {
                documents.push(document);
            }
        }
    }
    documents.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| left.title.cmp(&right.title))
    });
    Ok(documents)
}

async fn visible_document_ids_for_dataset(
    state: &AppState,
    dataset_id: DatasetId,
    current_user_id: Option<UserId>,
) -> std::result::Result<HashSet<DocumentId>, ApiError> {
    Ok(list_documents_for_dataset_scope(state, dataset_id)
        .await?
        .into_iter()
        .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
        .map(|document| document.id)
        .collect())
}

async fn list_documents_for_dataset_scope(
    state: &AppState,
    dataset_id: DatasetId,
) -> std::result::Result<Vec<Document>, ApiError> {
    state
        .storage
        .documents()
        .list_by_dataset_scope(state.tenant_id, dataset_id)
        .await
        .map_err(ApiError::from_storage)
}

