const EXTERNAL_OBSERVABILITY_ACCESS_HEADER: &str = "x-ai-data-platform-external-observability-key";

fn external_observability_configured_access_key() -> Option<String> {
    std::env::var("EXTERNAL_OBSERVABILITY_ACCESS_KEY")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .or_else(|| {
            std::env::var("EXTERNAL_INTEGRATIONS_OBSERVATION_KEY")
                .ok()
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty())
        })
}

fn external_observability_access_allowed(headers: &HeaderMap) -> bool {
    let Some(expected) = external_observability_configured_access_key() else {
        return true;
    };
    let Some(actual) = headers
        .get(EXTERNAL_OBSERVABILITY_ACCESS_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return false;
    };
    Sha256::digest(expected.as_bytes()) == Sha256::digest(actual.as_bytes())
}

async fn list_external_conversation_tests(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<ExternalConversationTestsQuery>,
) -> std::result::Result<Json<ListExternalConversationTestsResponse>, ApiError> {
    if !external_observability_access_allowed(&headers) {
        return Err(ApiError::unauthorized(
            "external_observability_access_required",
            "external conversation tests require an observability access key".to_string(),
        ));
    }

    let integration_id = query
        .integration_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    validate_required(
        "integration_id",
        integration_id.as_deref().unwrap_or_default(),
    )?;
    let conversation_external_id = query
        .conversation_external_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let limit = query.limit.unwrap_or(50).clamp(1, 100) as i64;
    let rows = sqlx::query(
        r#"
        select e.id::text as event_id,
               e.channel_connection_id,
               coalesce(c.display_name, e.channel_connection_id) as integration_display_name,
               e.platform,
               e.conversation_external_id,
               e.message_external_id,
               e.direction,
               e.assistant_run_id,
               r.user_prompt as question_text,
               coalesce(r.output_artifacts, '[]'::jsonb) as output_artifacts,
               e.payload_summary,
               e.created_at,
               r.updated_at as assistant_updated_at,
               case
                   when latest_reply_event.created_at is null then null
                   else greatest(
                       0::bigint,
                       floor(extract(epoch from (latest_reply_event.created_at - e.created_at)) * 1000)::bigint
                   )
               end as duration_ms,
               case
                   when e.assistant_run_id is null then 'no_run'
                   when exists (
                       select 1
                       from assistant_run_events ev
                       where ev.tenant_id = e.tenant_id
                         and ev.run_id = e.assistant_run_id
                         and ev.event_name in (
                             'assistant_run.external_channel_model_reply_failed',
                             'assistant_run.failed'
                         )
                   ) then 'failed'
                   when exists (
                       select 1
                       from assistant_run_events ev
                       where ev.tenant_id = e.tenant_id
                         and ev.run_id = e.assistant_run_id
                         and ev.event_name = 'assistant_run.external_channel_model_reply_rejected'
                   ) then 'rejected'
                   when exists (
                       select 1
                       from assistant_run_events ev
                       where ev.tenant_id = e.tenant_id
                         and ev.run_id = e.assistant_run_id
                         and ev.event_name = 'assistant_run.external_channel_model_reply_unavailable'
                   ) then 'unavailable'
                   when exists (
                       select 1
                       from assistant_run_events ev
                       where ev.tenant_id = e.tenant_id
                         and ev.run_id = e.assistant_run_id
                         and ev.event_name in (
                             'assistant_run.external_channel_model_reply_completed',
                             'assistant_run.completed'
                         )
                   ) then 'completed'
                   else 'running'
               end as assistant_status,
               latest_reply_event.event_name as assistant_event
        from external_message_events e
        left join external_channel_connections c
          on c.tenant_id = e.tenant_id
         and c.id = e.channel_connection_id
        left join assistant_runs r
          on r.tenant_id = e.tenant_id
         and r.id = e.assistant_run_id
        left join lateral (
            select ev.event_name,
                   ev.created_at
            from assistant_run_events ev
            where ev.tenant_id = e.tenant_id
              and ev.run_id = e.assistant_run_id
              and ev.event_name like 'assistant_run.external_channel_model_reply_%'
            order by ev.created_at desc
            limit 1
        ) latest_reply_event on true
        where e.tenant_id = $1
          and ($2::text is null or e.channel_connection_id = $2)
          and ($3::text is null or e.conversation_external_id = $3)
        order by e.created_at desc
        limit $4
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id.as_deref())
    .bind(conversation_external_id.as_deref())
    .bind(limit)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let tests = rows
        .into_iter()
        .map(|row| {
            let payload_summary =
                external_integration_redacted_summary(row.get::<Value, _>("payload_summary"));
            let question_text = row
                .get::<Option<String>, _>("question_text")
                .map(|text| truncate_assistant_supply_text(&text, 800))
                .filter(|text| !text.is_empty());
            let output_artifacts = row.get::<Value, _>("output_artifacts");
            let answer_text =
                external_channel_observation_answer_text_from_output_artifacts(&output_artifacts)
                    .map(|text| truncate_assistant_supply_text(&text, 1200))
                    .filter(|text| !text.is_empty());
            ExternalConversationTestView {
                event_id: row.get("event_id"),
                integration_id: row.get("channel_connection_id"),
                integration_display_name: row.get("integration_display_name"),
                platform: row.get("platform"),
                conversation_external_id: row.get("conversation_external_id"),
                sender_external_id: payload_summary
                    .get("sender_external_id")
                    .and_then(Value::as_str)
                    .map(str::to_string),
                message_external_id: row.get("message_external_id"),
                direction: row.get("direction"),
                assistant_run_id: row
                    .get::<Option<Uuid>, _>("assistant_run_id")
                    .map(AssistantRunId),
                assistant_status: row.get("assistant_status"),
                assistant_event: row.get("assistant_event"),
                question_text,
                answer_text,
                duration_ms: row.get("duration_ms"),
                created_at: row.get("created_at"),
                assistant_updated_at: row.get("assistant_updated_at"),
                payload_summary,
            }
        })
        .collect();

    Ok(Json(ListExternalConversationTestsResponse { tests }))
}

async fn get_external_conversation_timeline(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(event_id): Path<String>,
    Query(query): Query<ExternalConversationTimelineQuery>,
) -> std::result::Result<Json<ExternalConversationTimelineResponse>, ApiError> {
    if !external_observability_access_allowed(&headers) {
        return Err(ApiError::unauthorized(
            "external_observability_access_required",
            "external conversation tests require an observability access key".to_string(),
        ));
    }

    let event_uuid = parse_external_conversation_event_id(&event_id)?;
    let row = sqlx::query(
        r#"
        select e.id::text as event_id,
               e.channel_connection_id,
               coalesce(c.display_name, e.channel_connection_id) as integration_display_name,
               e.platform,
               e.conversation_external_id,
               e.message_external_id,
               e.direction,
               e.assistant_run_id
        from external_message_events e
        left join external_channel_connections c
          on c.tenant_id = e.tenant_id
         and c.id = e.channel_connection_id
        where e.tenant_id = $1
          and e.id = $2
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(event_uuid)
    .fetch_optional(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?
    .ok_or_else(|| {
        ApiError::not_found(
            "external_conversation_test_not_found",
            format!("external conversation test event {event_id} was not found"),
        )
    })?;

    let assistant_run_id = row
        .get::<Option<Uuid>, _>("assistant_run_id")
        .map(AssistantRunId);
    let events = if let Some(run_id) = assistant_run_id {
        state
            .storage
            .assistant_runs()
            .list_events(state.tenant_id, run_id)
            .await
            .map_err(ApiError::from_storage)?
            .into_iter()
            .map(|event| {
                external_conversation_timeline_event_view(event, query.debug.unwrap_or(false))
            })
            .collect()
    } else {
        Vec::new()
    };

    Ok(Json(ExternalConversationTimelineResponse {
        event_id: row.get("event_id"),
        integration_id: row.get("channel_connection_id"),
        integration_display_name: row.get("integration_display_name"),
        platform: row.get("platform"),
        conversation_external_id: row.get("conversation_external_id"),
        message_external_id: row.get("message_external_id"),
        direction: row.get("direction"),
        assistant_run_id,
        events,
    }))
}

fn parse_external_conversation_event_id(raw: &str) -> std::result::Result<Uuid, ApiError> {
    Uuid::parse_str(raw.trim()).map_err(|_| {
        ApiError::bad_request(
            "invalid_external_conversation_test_event_id",
            format!("{raw} is not a valid UUID"),
        )
    })
}

fn external_conversation_timeline_event_view(
    event: AssistantRunEvent,
    include_debug: bool,
) -> ExternalConversationTimelineEventView {
    let payload = external_conversation_timeline_sanitized_payload(event.payload);
    let artifact_links = external_conversation_timeline_artifact_links(&payload);
    let phase = external_conversation_timeline_phase(&event.event_name, &payload);
    let status = external_conversation_timeline_status(&event.event_name, &payload);
    let display_text = external_conversation_timeline_display_text(&event.event_name, &payload);
    let payload_summary = external_conversation_timeline_payload_summary(
        &event.event_name,
        &payload,
        &artifact_links,
    );
    let debug_payload = include_debug.then_some(payload);

    ExternalConversationTimelineEventView {
        sequence_no: event.sequence_no,
        event_name: event.event_name,
        phase,
        status,
        display_text,
        artifact_links,
        payload_summary,
        debug_payload,
        created_at: event.created_at,
    }
}

fn external_conversation_timeline_sanitized_payload(payload: Value) -> Value {
    if payload.get("schema").and_then(Value::as_str) == Some(EXTERNAL_CHANNEL_SSE_SCHEMA_V1)
        || payload.get("schema").and_then(Value::as_str) == Some(ASSISTANT_RUN_SSE_SCHEMA_V1)
    {
        external_channel_public_stream_payload(payload)
    } else {
        external_integration_redacted_summary(payload)
    }
}

fn external_conversation_timeline_phase(event_name: &str, payload: &Value) -> Option<String> {
    external_conversation_timeline_string(
        payload,
        &["phase", "phase_name", "phaseName"],
        &["/data/phase", "/data/phase_name", "/data/phaseName"],
        80,
    )
    .or_else(|| {
        event_name
            .strip_prefix("assistant_run.")
            .and_then(|suffix| suffix.split('_').next())
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    })
}

fn external_conversation_timeline_status(event_name: &str, payload: &Value) -> Option<String> {
    external_conversation_timeline_string(
        payload,
        &["status", "task_status", "taskStatus"],
        &[
            "/data/status",
            "/data/task_status",
            "/data/taskStatus",
            "/data/reply/task_status",
            "/data/reply/taskStatus",
            "/data/reply/card/status",
            "/reply/task_status",
            "/reply/card/status",
        ],
        80,
    )
    .or_else(|| {
        let event_name = event_name.to_ascii_lowercase();
        if event_name.contains("failed") {
            Some("failed".to_string())
        } else if event_name.contains("completed") || event_name.contains("published") {
            Some("completed".to_string())
        } else if event_name.contains("queued") {
            Some("queued".to_string())
        } else if event_name.contains("started") || event_name.contains("received") {
            Some("running".to_string())
        } else {
            None
        }
    })
}

fn external_conversation_timeline_display_text(
    event_name: &str,
    payload: &Value,
) -> Option<String> {
    external_conversation_timeline_string(
        payload,
        &["display_text", "displayText", "text", "message"],
        &[
            "/data/display_text",
            "/data/displayText",
            "/data/text",
            "/data/message",
            "/data/reply/text",
            "/data/reply/card/display_text",
            "/data/reply/card/displayText",
            "/reply/text",
            "/reply/card/display_text",
            "/reply/card/displayText",
        ],
        500,
    )
    .or_else(|| {
        if event_name.ends_with(".completed") {
            Some("本轮已完成。".to_string())
        } else if event_name.ends_with(".started") {
            Some("已开始处理。".to_string())
        } else {
            None
        }
    })
}

fn external_conversation_timeline_string(
    payload: &Value,
    keys: &[&str],
    pointers: &[&str],
    max_chars: usize,
) -> Option<String> {
    keys.iter()
        .filter_map(|key| payload.get(*key))
        .chain(
            pointers
                .iter()
                .filter_map(|pointer| payload.pointer(pointer)),
        )
        .filter_map(external_conversation_timeline_string_value)
        .map(|value| truncate_assistant_supply_text(&value, max_chars))
        .find(|value| !value.is_empty())
}

fn external_conversation_timeline_string_value(value: &Value) -> Option<String> {
    match value {
        Value::String(value) => {
            let trimmed = value.trim();
            (!trimmed.is_empty() && trimmed != "[redacted]").then(|| trimmed.to_string())
        }
        Value::Number(value) => Some(value.to_string()),
        Value::Bool(value) => Some(value.to_string()),
        _ => None,
    }
}

fn external_conversation_timeline_payload_summary(
    event_name: &str,
    payload: &Value,
    artifact_links: &[String],
) -> Value {
    let mut summary = Map::new();
    summary.insert(
        "event_name".to_string(),
        Value::String(event_name.to_string()),
    );
    copy_json_fields(
        payload,
        &mut summary,
        &[
            "schema",
            "event_id",
            "sequence",
            "phase",
            "status",
            "display_text",
            "status_url",
            "poll_after_seconds",
            "reply_type",
            "task_status",
        ],
    );
    if let Some(data) = payload.get("data") {
        copy_json_fields(
            data,
            &mut summary,
            &[
                "phase",
                "status",
                "display_text",
                "status_url",
                "poll_after_seconds",
            ],
        );
        if let Some(reply) = data.get("reply") {
            copy_json_fields(
                reply,
                &mut summary,
                &["reply_type", "task_status", "requires_confirmation"],
            );
        }
    }
    if !artifact_links.is_empty() {
        summary.insert("artifact_links".to_string(), json!(artifact_links));
    }
    if summary.len() == 1 {
        if let Some(object) = payload.as_object() {
            let keys: Vec<String> = object.keys().take(12).cloned().collect();
            if !keys.is_empty() {
                summary.insert("payload_keys".to_string(), json!(keys));
            }
        }
    }
    Value::Object(summary)
}

fn external_conversation_timeline_artifact_links(payload: &Value) -> Vec<String> {
    let mut links = Vec::new();
    external_conversation_timeline_collect_artifact_links(payload, &mut links, 0);
    links
}

fn external_conversation_timeline_collect_artifact_links(
    value: &Value,
    links: &mut Vec<String>,
    depth: usize,
) {
    if depth > 6 {
        return;
    }
    match value {
        Value::Array(items) => {
            for item in items {
                external_conversation_timeline_collect_artifact_links(item, links, depth + 1);
            }
        }
        Value::Object(object) => {
            for key in ["artifact_links", "artifactLinks"] {
                if let Some(value) = object.get(key) {
                    external_conversation_timeline_collect_link_value(value, links);
                }
            }
            for key in [
                "public_url",
                "publicUrl",
                "generated_artifact_url",
                "generatedArtifactUrl",
                "artifact_public_url",
                "artifactPublicUrl",
                "html_preview_url",
                "htmlPreviewUrl",
                "html_download_url",
                "htmlDownloadUrl",
                "download_url",
                "downloadUrl",
            ] {
                if let Some(value) = object.get(key) {
                    external_conversation_timeline_collect_link_value(value, links);
                }
            }
            for value in object.values() {
                external_conversation_timeline_collect_artifact_links(value, links, depth + 1);
            }
        }
        Value::String(_) => {}
        _ => {}
    }
}

fn external_conversation_timeline_collect_link_value(value: &Value, links: &mut Vec<String>) {
    match value {
        Value::String(value) => external_conversation_timeline_push_artifact_link(links, value),
        Value::Array(items) => {
            for item in items {
                external_conversation_timeline_collect_link_value(item, links);
            }
        }
        Value::Object(object) => {
            for key in ["url", "href", "public_url", "publicUrl"] {
                if let Some(value) = object.get(key) {
                    external_conversation_timeline_collect_link_value(value, links);
                }
            }
        }
        _ => {}
    }
}

fn external_conversation_timeline_push_artifact_link(links: &mut Vec<String>, value: &str) {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || trimmed.starts_with("data:")
        || !(trimmed.starts_with("https://")
            || trimmed.starts_with("http://")
            || trimmed.starts_with('/'))
        || links.iter().any(|link| link == trimmed)
    {
        return;
    }
    links.push(trimmed.to_string());
}

async fn list_external_integrations(
    State(state): State<AppState>,
) -> std::result::Result<Json<ListExternalIntegrationsResponse>, ApiError> {
    let mut integrations = Vec::new();
    let channel_rows = sqlx::query(
        r#"
        select c.id,
               c.platform,
               c.display_name,
               c.status,
               c.health_status,
               c.last_event_at,
               c.last_success_at,
               c.last_failure_at,
               c.disabled_at,
               c.config_redacted,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.confirmation_state = 'pending'
               ), 0)::bigint as pending_action_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ->> 'status' = 'dispatch_blocked'
               ), 0)::bigint as blocked_action_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and (
                        a.result_summary ->> 'status' = 'dispatch_failed'
                        or a.result_summary ->> 'status' in (
                            'external_action_failed',
                            'external_action_cancelled',
                            'external_action_rejected'
                        )
                     )
               ), 0)::bigint as failed_action_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ->> 'status' = 'dispatched'
               ), 0)::bigint as dispatched_action_count,
               (
                   select max(a.updated_at)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
               ) as latest_action_at,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
               ), 0)::bigint as total_action_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ? 'external_callback'
               ), 0)::bigint as result_callback_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ->> 'status' = 'dispatched'
               ), 0)::bigint as waiting_result_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ->> 'status' = 'external_action_succeeded'
               ), 0)::bigint as result_succeeded_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ->> 'status' in (
                        'external_action_failed',
                        'external_action_cancelled',
                        'external_action_rejected'
                     )
               ), 0)::bigint as result_failed_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ->> 'status' in (
                        'external_action_running',
                        'external_action_accepted'
                     )
               ), 0)::bigint as result_running_count,
               (
                   select max(a.updated_at)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.result_summary ? 'external_callback'
               ) as latest_result_callback_at,
               coalesce((
                   select count(*)
                   from assistant_run_events e
                   where e.tenant_id = c.tenant_id
                     and e.event_name = 'assistant_run.external_search_evidence_required'
                     and e.payload ->> 'channel_connection_id' = c.id
                     and coalesce(e.payload ->> 'search_evidence_required', 'false') = 'true'
               ), 0)::bigint as search_evidence_required_count,
               (
                   select max(e.created_at)
                   from assistant_run_events e
                   where e.tenant_id = c.tenant_id
                     and e.event_name = 'assistant_run.external_search_evidence_required'
                     and e.payload ->> 'channel_connection_id' = c.id
               ) as latest_search_evidence_required_at,
               coalesce((
                   select count(*)
                   from external_principals p
                   where p.tenant_id = c.tenant_id
                     and p.platform = c.platform
                     and p.v3_user_id is null
                     and p.is_disabled = false
               ), 0)::bigint as unmapped_principal_count,
               coalesce((
                   select count(*)
                   from external_principals p
                   where p.tenant_id = c.tenant_id
                     and p.platform = c.platform
                     and p.is_disabled = true
               ), 0)::bigint as disabled_principal_count,
               (
                   select max(p.updated_at)
                   from external_principals p
                   where p.tenant_id = c.tenant_id
                     and p.platform = c.platform
               ) as latest_principal_updated_at,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type = 'external_artifact.status'
               ), 0)::bigint as artifact_status_action_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type = 'external_artifact.publish'
               ), 0)::bigint as artifact_publish_action_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type = 'external_artifact.revoke'
               ), 0)::bigint as artifact_revoke_action_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type in ('external_artifact.status', 'external_artifact.publish', 'external_artifact.revoke')
                     and a.confirmation_state = 'pending'
               ), 0)::bigint as artifact_pending_confirmation_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type in ('external_artifact.status', 'external_artifact.publish', 'external_artifact.revoke')
                     and a.result_summary ->> 'status' = 'dispatch_blocked'
               ), 0)::bigint as artifact_blocked_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type in ('external_artifact.status', 'external_artifact.publish', 'external_artifact.revoke')
                     and (
                        a.result_summary ->> 'status' = 'dispatch_failed'
                        or (
                            a.failure_kind is not null
                            and coalesce(a.result_summary ->> 'status', '') <> 'dispatch_blocked'
                        )
                     )
               ), 0)::bigint as artifact_failed_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type = 'external_artifact.publish'
                     and a.result_summary ->> 'status' = 'dispatched'
               ), 0)::bigint as artifact_published_count,
               coalesce((
                   select count(*)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type = 'external_artifact.revoke'
                     and a.result_summary ->> 'status' = 'dispatched'
               ), 0)::bigint as artifact_revoked_count,
               (
                   select max(a.updated_at)
                   from external_action_runs a
                   where a.tenant_id = c.tenant_id
                     and a.requester_summary ->> 'channel_connection_id' = c.id
                     and a.action_type in ('external_artifact.status', 'external_artifact.publish', 'external_artifact.revoke')
               ) as latest_artifact_action_at
        from external_channel_connections c
        where c.tenant_id = $1
        order by c.updated_at desc
        "#,
    )
    .bind(state.tenant_id.0)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in channel_rows {
        let config_redacted = row.get::<Value, _>("config_redacted");
        integrations.push(ExternalIntegrationSummaryView {
            integration_id: row.get("id"),
            integration_kind: "channel".to_string(),
            display_name: row.get("display_name"),
            provider: row.get("platform"),
            status: row.get("status"),
            health_status: row.get("health_status"),
            last_event_at: row.get("last_event_at"),
            last_sync_at: None,
            last_success_at: row.get("last_success_at"),
            last_failure_at: row.get("last_failure_at"),
            disabled_at: row.get("disabled_at"),
            pending_action_count: row.get("pending_action_count"),
            blocked_action_count: row.get("blocked_action_count"),
            failed_action_count: row.get("failed_action_count"),
            dispatched_action_count: row.get("dispatched_action_count"),
            latest_action_at: row.get("latest_action_at"),
            action_summary: external_action_lifecycle_summary(
                row.get("total_action_count"),
                row.get("pending_action_count"),
                row.get("blocked_action_count"),
                row.get("failed_action_count"),
                row.get("waiting_result_count"),
                row.get("result_callback_count"),
                row.get("result_succeeded_count"),
                row.get("result_failed_count"),
                row.get("result_running_count"),
                row.get("latest_action_at"),
                row.get("latest_result_callback_at"),
            ),
            config_summary: external_integration_config_summary(&config_redacted),
            search_summary: external_search_evidence_summary(
                row.get("search_evidence_required_count"),
                row.get("latest_search_evidence_required_at"),
            ),
            drift_summary: external_channel_drift_summary(
                row.get("unmapped_principal_count"),
                row.get("disabled_principal_count"),
                row.get("latest_principal_updated_at"),
            ),
            artifact_summary: external_artifact_summary(
                row.get("artifact_status_action_count"),
                row.get("artifact_publish_action_count"),
                row.get("artifact_revoke_action_count"),
                row.get("artifact_pending_confirmation_count"),
                row.get("artifact_blocked_count"),
                row.get("artifact_failed_count"),
                row.get("artifact_published_count"),
                row.get("artifact_revoked_count"),
                row.get("latest_artifact_action_at"),
            ),
        });
    }

    let source_rows = sqlx::query(
        r#"
        with source_base as (
            select s.*,
                   coalesce(
                       s.config_redacted #>> '{database_source,default_dataset_id}',
                       s.config_redacted #>> '{databaseSource,defaultDatasetId}',
                       s.config_redacted #>> '{mysql_source,default_dataset_id}',
                       s.config_redacted #>> '{mysqlSource,defaultDatasetId}'
                   ) as database_default_dataset_id
            from external_source_connections s
            where s.tenant_id = $1
        )
        select s.id,
               s.connector_kind,
               s.display_name,
               s.health_status,
               s.last_sync_at,
               s.last_success_at,
               s.last_failure_at,
               s.disabled_at,
               s.config_redacted,
               s.database_default_dataset_id,
               coalesce((
                   select count(*)
                   from external_permission_snapshots ps
                   where ps.tenant_id = s.tenant_id
                     and ps.source_id = s.id
               ), 0)::bigint as acl_snapshot_count,
               coalesce((
                   select count(*)
                   from external_permission_snapshots ps
                   where ps.tenant_id = s.tenant_id
                     and ps.source_id = s.id
                     and ps.captured_at < now() - interval '24 hours'
               ), 0)::bigint as stale_acl_snapshot_count,
               (
                   select max(ps.captured_at)
                   from external_permission_snapshots ps
                   where ps.tenant_id = s.tenant_id
                     and ps.source_id = s.id
               ) as latest_acl_captured_at,
               coalesce((
                   select count(*)
                   from external_sync_runs r
                   where r.tenant_id = s.tenant_id
                     and r.source_id = s.id
                     and (r.status in ('failed', 'dead_lettered') or r.failure_kind is not null)
               ), 0)::bigint as failed_sync_count,
               (
                   select r.status
                   from external_sync_runs r
                   where r.tenant_id = s.tenant_id
                     and r.source_id = s.id
                   order by r.updated_at desc
                   limit 1
               ) as latest_sync_status,
               coalesce((
                   select count(*)
                   from documents d
                   where d.tenant_id = s.tenant_id
                     and d.lifecycle <> 'archived'
                     and d.metadata #>> '{external_source,source_id}' = s.id
                     and (
                        s.database_default_dataset_id is null
                        or d.dataset_id::text = s.database_default_dataset_id
                     )
               ), 0)::bigint as database_document_count,
               coalesce((
                   select count(*)
                   from documents d
                   where d.tenant_id = s.tenant_id
                     and d.lifecycle = 'indexed'
                     and d.metadata #>> '{external_source,source_id}' = s.id
                     and (
                        s.database_default_dataset_id is null
                        or d.dataset_id::text = s.database_default_dataset_id
                     )
               ), 0)::bigint as database_indexed_document_count,
               coalesce((
                   select count(*)
                   from documents d
                   where d.tenant_id = s.tenant_id
                     and d.lifecycle = 'failed'
                     and d.metadata #>> '{external_source,source_id}' = s.id
                     and (
                        s.database_default_dataset_id is null
                        or d.dataset_id::text = s.database_default_dataset_id
                     )
               ), 0)::bigint as database_failed_document_count,
               coalesce((
                   select count(*)
                   from documents d
                   where d.tenant_id = s.tenant_id
                     and d.lifecycle in ('received', 'extracted')
                     and d.metadata #>> '{external_source,source_id}' = s.id
                     and (
                        s.database_default_dataset_id is null
                        or d.dataset_id::text = s.database_default_dataset_id
                     )
               ), 0)::bigint as database_processing_document_count,
               coalesce((
                   select count(*)
                   from documents d
                   join document_chunks c
                     on c.tenant_id = d.tenant_id
                    and c.document_id = d.id
                   where d.tenant_id = s.tenant_id
                     and d.lifecycle <> 'archived'
                     and d.metadata #>> '{external_source,source_id}' = s.id
                     and (
                        s.database_default_dataset_id is null
                        or d.dataset_id::text = s.database_default_dataset_id
                     )
               ), 0)::bigint as database_chunk_count,
               coalesce((
                   select count(*)
                   from documents d
                   join document_chunks c
                     on c.tenant_id = d.tenant_id
                    and c.document_id = d.id
                   where d.tenant_id = s.tenant_id
                     and d.lifecycle <> 'archived'
                     and c.state = 'indexed'
                     and d.metadata #>> '{external_source,source_id}' = s.id
                     and (
                        s.database_default_dataset_id is null
                        or d.dataset_id::text = s.database_default_dataset_id
                     )
               ), 0)::bigint as database_indexed_chunk_count,
               (
                   select max(d.updated_at)
                   from documents d
                   where d.tenant_id = s.tenant_id
                     and d.lifecycle <> 'archived'
                     and d.metadata #>> '{external_source,source_id}' = s.id
                     and (
                        s.database_default_dataset_id is null
                        or d.dataset_id::text = s.database_default_dataset_id
                     )
               ) as database_latest_document_updated_at
        from source_base s
        order by s.updated_at desc
        "#,
    )
    .bind(state.tenant_id.0)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in source_rows {
        let disabled_at = row.get::<Option<DateTime<Utc>>, _>("disabled_at");
        let config_redacted = row.get::<Value, _>("config_redacted");
        let database_readiness = if source_database_config_fragment(&config_redacted).is_some() {
            external_database_dataset_readiness_summary(
                row.get("database_default_dataset_id"),
                row.get("database_document_count"),
                row.get("database_indexed_document_count"),
                row.get("database_failed_document_count"),
                row.get("database_processing_document_count"),
                row.get("database_chunk_count"),
                row.get("database_indexed_chunk_count"),
                row.get("database_latest_document_updated_at"),
            )
        } else {
            Value::Null
        };
        integrations.push(ExternalIntegrationSummaryView {
            integration_id: row.get("id"),
            integration_kind: "source".to_string(),
            display_name: row.get("display_name"),
            provider: row.get("connector_kind"),
            status: if disabled_at.is_some() {
                "disabled".to_string()
            } else {
                "enabled".to_string()
            },
            health_status: row.get("health_status"),
            last_event_at: None,
            last_sync_at: row.get("last_sync_at"),
            last_success_at: row.get("last_success_at"),
            last_failure_at: row.get("last_failure_at"),
            disabled_at,
            pending_action_count: 0,
            blocked_action_count: 0,
            failed_action_count: 0,
            dispatched_action_count: 0,
            latest_action_at: None,
            action_summary: external_action_lifecycle_summary(
                0, 0, 0, 0, 0, 0, 0, 0, 0, None, None,
            ),
            config_summary: external_integration_config_summary(&config_redacted),
            search_summary: external_search_evidence_summary(0, None),
            drift_summary: external_source_drift_summary_with_database_readiness(
                row.get("acl_snapshot_count"),
                row.get("stale_acl_snapshot_count"),
                row.get("failed_sync_count"),
                row.get("latest_sync_status"),
                row.get("latest_acl_captured_at"),
                database_readiness,
            ),
            artifact_summary: external_artifact_summary(0, 0, 0, 0, 0, 0, 0, 0, None),
        });
    }

    integrations.sort_by(|left, right| {
        right
            .last_failure_at
            .or(right.latest_action_at)
            .or(right.last_success_at)
            .or(right.last_event_at)
            .or(right.last_sync_at)
            .cmp(
                &left
                    .last_failure_at
                    .or(left.latest_action_at)
                    .or(left.last_success_at)
                    .or(left.last_event_at)
                    .or(left.last_sync_at),
            )
    });

    Ok(Json(ListExternalIntegrationsResponse { integrations }))
}

async fn get_external_integration_audit(
    State(state): State<AppState>,
    Path(integration_id): Path<String>,
    Query(query): Query<ExternalIntegrationAuditQuery>,
) -> std::result::Result<Json<ExternalIntegrationAuditResponse>, ApiError> {
    validate_required("integration_id", &integration_id)?;
    let filter = external_integration_audit_filter(query)?;
    let channel_exists = external_channel_connection_exists(&state, &integration_id).await?;
    let source_exists = external_source_connection_exists(&state, &integration_id).await?;
    if !channel_exists && !source_exists {
        return Err(ApiError::not_found(
            "external_integration_not_found",
            format!("external integration {integration_id} was not found"),
        ));
    }

    let mut items = Vec::new();
    if channel_exists {
        items.extend(load_external_channel_audit_items(&state, &integration_id).await?);
    }
    if source_exists {
        items.extend(load_external_source_audit_items(&state, &integration_id).await?);
    }
    items.retain(|item| external_integration_audit_item_matches(item, &filter));
    items.sort_by(|left, right| right.created_at.cmp(&left.created_at));
    items.truncate(filter.limit);
    Ok(Json(ExternalIntegrationAuditResponse {
        integration_id,
        items,
    }))
}

fn external_integration_audit_filter(
    query: ExternalIntegrationAuditQuery,
) -> std::result::Result<ExternalIntegrationAuditFilter, ApiError> {
    let item_type = query
        .item_type
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty() && *value != "all")
        .map(|value| value.to_ascii_lowercase())
        .map(|value| match value.as_str() {
            "message" | "action" | "sync" | "search_evidence" => Ok(value),
            _ => Err(ApiError::bad_request_with_details(
                "external_integration_audit_item_type_invalid",
                "audit item_type must be one of message, action, search_evidence, sync, or all"
                    .to_string(),
                json!({ "item_type": value }),
            )),
        })
        .transpose()?;
    let action_state = query
        .action_state
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty() && *value != "all")
        .map(|value| value.to_ascii_lowercase())
        .map(|value| match value.as_str() {
            "result_callback"
            | "waiting_result"
            | "failed"
            | "blocked"
            | "pending_confirmation" => Ok(value),
            _ => Err(ApiError::bad_request_with_details(
                "external_integration_audit_action_state_invalid",
                "audit action_state must be one of result_callback, waiting_result, failed, blocked, pending_confirmation, or all".to_string(),
                json!({ "action_state": value }),
            )),
        })
        .transpose()?;
    if action_state.is_some() && item_type.as_deref().is_some_and(|value| value != "action") {
        return Err(ApiError::bad_request(
            "external_integration_audit_filter_conflict",
            "action_state can only be combined with item_type=action or all".to_string(),
        ));
    }
    let action_id = query
        .action_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    if action_id.is_some() && item_type.as_deref().is_some_and(|value| value != "action") {
        return Err(ApiError::bad_request(
            "external_integration_audit_filter_conflict",
            "action_id can only be combined with item_type=action or all".to_string(),
        ));
    }
    let limit = query.limit.unwrap_or(50).clamp(1, 100);
    Ok(ExternalIntegrationAuditFilter {
        item_type,
        action_state,
        action_id,
        limit,
    })
}

fn external_integration_audit_item_matches(
    item: &ExternalIntegrationAuditItemView,
    filter: &ExternalIntegrationAuditFilter,
) -> bool {
    if let Some(item_type) = filter.item_type.as_deref() {
        if item.item_type != item_type {
            return false;
        }
    }
    if let Some(action_id) = filter.action_id.as_deref() {
        if item.item_type != "action" || item.action_id.as_deref() != Some(action_id) {
            return false;
        }
    }
    let Some(action_state) = filter.action_state.as_deref() else {
        return true;
    };
    if item.item_type != "action" {
        return false;
    }
    let lifecycle_status = item
        .summary
        .get("action_lifecycle_status")
        .and_then(Value::as_str)
        .or(item.status.as_deref())
        .unwrap_or_default();
    let confirmation_state = item
        .summary
        .get("confirmation_state")
        .and_then(Value::as_str)
        .unwrap_or_default();
    match action_state {
        "result_callback" => item
            .summary
            .get("result_callback_received")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        "waiting_result" => lifecycle_status == "dispatched",
        "failed" => {
            item.failure_kind.is_some()
                || matches!(
                    lifecycle_status,
                    "dispatch_failed"
                        | "external_action_failed"
                        | "external_action_cancelled"
                        | "external_action_rejected"
                )
        }
        "blocked" => lifecycle_status == "dispatch_blocked",
        "pending_confirmation" => confirmation_state == "pending",
        _ => true,
    }
}

async fn disable_external_integration(
    State(state): State<AppState>,
    Path(integration_id): Path<String>,
    Json(request): Json<ExternalIntegrationControlRequest>,
) -> std::result::Result<Json<ExternalIntegrationControlResponse>, ApiError> {
    validate_required("integration_id", &integration_id)?;
    let now = Utc::now();
    let reason_present = external_control_reason_present(request.reason.as_deref());
    let channel_count =
        disable_external_channel_connection(&state, &integration_id, reason_present, now).await?;
    let source_count =
        disable_external_source_connection(&state, &integration_id, reason_present, now).await?;
    if channel_count == 0 && source_count == 0 {
        return Err(ApiError::not_found(
            "external_integration_not_found",
            format!("external integration {integration_id} was not found"),
        ));
    }

    Ok(Json(ExternalIntegrationControlResponse {
        accepted: true,
        integration_id,
        integration_kind: external_control_integration_kind(channel_count, source_count),
        action: "disable".to_string(),
        status: "disabled".to_string(),
        message: "external integration disabled; future events or sync jobs will be rejected"
            .to_string(),
        affected_action_count: 0,
        sync_run_id: None,
        workflow_execution: None,
        enqueued_tasks: Vec::new(),
    }))
}

async fn retry_external_integration(
    State(state): State<AppState>,
    Path(integration_id): Path<String>,
    Json(request): Json<ExternalIntegrationControlRequest>,
) -> std::result::Result<Json<ExternalIntegrationControlResponse>, ApiError> {
    validate_required("integration_id", &integration_id)?;
    let channel_exists = external_channel_connection_exists(&state, &integration_id).await?;
    let source_exists = external_source_connection_exists(&state, &integration_id).await?;
    if !channel_exists && !source_exists {
        return Err(ApiError::not_found(
            "external_integration_not_found",
            format!("external integration {integration_id} was not found"),
        ));
    }

    let mut sync_response = None;
    if source_exists {
        let sync_kind = request
            .sync_kind
            .clone()
            .or_else(|| Some("incremental".to_string()));
        sync_response = Some(
            enqueue_external_source_sync(
                &state,
                &integration_id,
                CreateExternalSourceSyncRequest {
                    sync_kind,
                    dataset_id: None,
                    dataset_external_id: None,
                    dataset_title: None,
                    checkpoint: json!({
                        "management_retry": true,
                    }),
                    connector_context: json!({
                        "requested_from": "external_integrations_panel",
                    }),
                },
            )
            .await?,
        );
    }

    let mut action_schedule = ExternalActionRetrySchedule::default();
    if channel_exists {
        action_schedule =
            retry_external_channel_action_runs(&state, &integration_id, Utc::now()).await?;
    }

    let status = if sync_response.is_some() {
        "running"
    } else if action_schedule.affected_action_count > 0 {
        "retry_queued"
    } else {
        "no_retryable_action"
    };
    let (sync_run_id, mut workflow_execution, mut enqueued_tasks) = sync_response
        .map(|response| {
            (
                Some(response.sync_run_id),
                Some(response.workflow_execution),
                response.enqueued_tasks,
            )
        })
        .unwrap_or((None, None, Vec::new()));
    if workflow_execution.is_none() {
        workflow_execution = action_schedule.workflow_execution;
    }
    enqueued_tasks.extend(action_schedule.enqueued_tasks);

    Ok(Json(ExternalIntegrationControlResponse {
        accepted: true,
        integration_id,
        integration_kind: external_control_integration_kind(
            channel_exists as u64,
            source_exists as u64,
        ),
        action: "retry".to_string(),
        status: status.to_string(),
        message: if source_exists {
            "external source retry sync has been enqueued".to_string()
        } else if action_schedule.affected_action_count > 0 {
            "retryable external action runs have been queued".to_string()
        } else {
            "no retryable external action run was found".to_string()
        },
        affected_action_count: action_schedule.affected_action_count,
        sync_run_id,
        workflow_execution,
        enqueued_tasks,
    }))
}

