async fn retry_external_channel_action_runs(
    state: &AppState,
    integration_id: &str,
    now: DateTime<Utc>,
) -> std::result::Result<ExternalActionRetrySchedule, ApiError> {
    let rows = sqlx::query(
        r#"
        select id
        from external_action_runs
        where tenant_id = $1
          and requester_summary ->> 'channel_connection_id' = $2
          and external_request_id is null
          and confirmation_state in ('not_required', 'confirmed')
          and result_summary ->> 'status' in ('dispatch_blocked', 'dispatch_failed')
        order by updated_at desc
        limit 10
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let mut schedule = ExternalActionRetrySchedule::default();
    for row in rows {
        let action_id: String = row.get("id");
        let started =
            enqueue_external_action_dispatch_retry(state, integration_id, &action_id, now).await?;
        if schedule.workflow_execution.is_none() {
            schedule.workflow_execution = Some(started.execution.clone());
        }
        schedule.enqueued_tasks.extend(started.enqueued_tasks);
        schedule.affected_action_count += 1;
    }
    Ok(schedule)
}

async fn enqueue_external_action_dispatch_retry(
    state: &AppState,
    connection_id: &str,
    action_id: &str,
    now: DateTime<Utc>,
) -> std::result::Result<AdvanceWorkflowExecutionResponse, ApiError> {
    let workflow_execution =
        build_initial_external_action_dispatch_execution(state, connection_id, action_id, now)?;
    let initial_event =
        build_initial_external_action_dispatch_event(&workflow_execution, connection_id, action_id);
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&workflow_execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal_with_dependencies(
        &state.storage,
        &state.workflow_catalog,
        &state.event_bus,
        state.tenant_id,
        workflow_execution.id,
        WorkflowSignal::Start,
    )
    .await?;
    mark_external_action_retry_queued(state, action_id, &started, now).await?;
    Ok(started)
}

async fn mark_external_action_retry_queued(
    state: &AppState,
    action_id: &str,
    started: &AdvanceWorkflowExecutionResponse,
    now: DateTime<Utc>,
) -> std::result::Result<(), ApiError> {
    let task_ids: Vec<String> = started
        .enqueued_tasks
        .iter()
        .map(|task| task.id.to_string())
        .collect();
    let result_patch = json!({
        "status": "retry_queued",
        "retry": {
            "workflow_execution_id": started.execution.id,
            "workflow_stage": started.execution.stage,
            "task_ids": task_ids,
            "queue": "external_action",
            "queued_at": now,
        },
        "updated_at": now,
    });
    sqlx::query(
        r#"
        update external_action_runs
        set result_summary = result_summary || $3,
            failure_kind = null,
            updated_at = $4
        where tenant_id = $1 and id = $2
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(action_id)
    .bind(result_patch)
    .bind(now)
    .execute(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;
    Ok(())
}

async fn load_external_channel_audit_items(
    state: &AppState,
    integration_id: &str,
) -> std::result::Result<Vec<ExternalIntegrationAuditItemView>, ApiError> {
    let mut items = Vec::new();
    let message_rows = sqlx::query(
        r#"
        select assistant_run_id,
               direction,
               platform,
               conversation_external_id,
               message_external_id,
               payload_summary,
               created_at
        from external_message_events
        where tenant_id = $1 and channel_connection_id = $2
        order by created_at desc
        limit 25
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in message_rows {
        let payload_summary = row.get::<Value, _>("payload_summary");
        items.push(ExternalIntegrationAuditItemView {
            item_type: "message".to_string(),
            created_at: row.get("created_at"),
            assistant_run_id: row
                .get::<Option<Uuid>, _>("assistant_run_id")
                .map(AssistantRunId),
            action_id: None,
            status: Some(row.get("direction")),
            failure_kind: None,
            summary: json!({
                "platform": row.get::<String, _>("platform"),
                "conversation_external_id": row.get::<String, _>("conversation_external_id"),
                "message_external_id": row.get::<String, _>("message_external_id"),
                "payload_summary": external_integration_redacted_summary(payload_summary),
            }),
        });
    }

    let search_rows = sqlx::query(
        r#"
        select run_id,
               payload,
               created_at
        from assistant_run_events
        where tenant_id = $1
          and event_name = 'assistant_run.external_search_evidence_required'
          and payload ->> 'channel_connection_id' = $2
        order by created_at desc
        limit 25
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in search_rows {
        let payload = row.get::<Value, _>("payload");
        items.push(ExternalIntegrationAuditItemView {
            item_type: "search_evidence".to_string(),
            created_at: row.get("created_at"),
            assistant_run_id: Some(AssistantRunId(row.get("run_id"))),
            action_id: None,
            status: Some("v3_search_evidence_required".to_string()),
            failure_kind: None,
            summary: json!({
                "action_type": "web_search",
                "freshness": payload
                    .get("freshness")
                    .and_then(Value::as_str)
                    .unwrap_or("unspecified"),
                "requires_v3_validation": payload
                    .get("requires_v3_validation")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
                "search_evidence_required": true,
                "no_live_search_claim": payload
                    .get("no_live_search_claim")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
                "query_chars": payload
                    .get("query_chars")
                    .and_then(Value::as_u64)
                    .unwrap_or(0),
                "message_external_id": payload
                    .get("message_external_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
                "source": "assistant_run.external_search_evidence_required",
            }),
        });
    }

    let action_rows = sqlx::query(
        r#"
        select id,
               assistant_run_id,
               action_type,
               target_system,
               arguments_redacted,
               confirmation_state,
               external_request_id,
               result_summary,
               failure_kind,
               updated_at
        from external_action_runs
        where tenant_id = $1
          and requester_summary ->> 'channel_connection_id' = $2
        order by updated_at desc
        limit 25
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    for row in action_rows {
        let result_summary = row.get::<Value, _>("result_summary");
        let confirmation_state = row.get::<String, _>("confirmation_state");
        let status = result_summary
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or(confirmation_state.as_str())
            .to_string();
        items.push(ExternalIntegrationAuditItemView {
            item_type: "action".to_string(),
            created_at: row.get("updated_at"),
            assistant_run_id: row
                .get::<Option<Uuid>, _>("assistant_run_id")
                .map(AssistantRunId),
            action_id: Some(row.get("id")),
            status: Some(status),
            failure_kind: row.get("failure_kind"),
            summary: external_action_run_audit_summary(
                &row.get::<String, _>("action_type"),
                &row.get::<String, _>("target_system"),
                &row.get::<Value, _>("arguments_redacted"),
                &confirmation_state,
                row.get::<Option<String>, _>("external_request_id")
                    .as_deref(),
                &result_summary,
            ),
        });
    }

    Ok(items)
}

async fn load_external_source_audit_items(
    state: &AppState,
    integration_id: &str,
) -> std::result::Result<Vec<ExternalIntegrationAuditItemView>, ApiError> {
    let rows = sqlx::query(
        r#"
        select sync_kind,
               status,
               checkpoint,
               counts,
               failure_kind,
               updated_at
        from external_sync_runs
        where tenant_id = $1 and source_id = $2
        order by updated_at desc
        limit 50
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(integration_id)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    Ok(rows
        .into_iter()
        .map(|row| ExternalIntegrationAuditItemView {
            item_type: "sync".to_string(),
            created_at: row.get("updated_at"),
            assistant_run_id: None,
            action_id: None,
            status: Some(row.get("status")),
            failure_kind: row.get("failure_kind"),
            summary: json!({
                "sync_kind": row.get::<String, _>("sync_kind"),
                "counts": external_integration_redacted_summary(row.get::<Value, _>("counts")),
                "checkpoint": external_integration_redacted_summary(row.get::<Value, _>("checkpoint")),
            }),
        })
        .collect())
}

fn external_integration_config_summary(config: &Value) -> Value {
    let dispatch_auth = external_action_dispatch_auth_from_config(config);
    let inbound_auth_configured =
        external_channel_inbound_bearer_token_from_config(config).is_some();
    json!({
        "key_count": config.as_object().map(Map::len).unwrap_or(0),
        "redacted_value_present": external_integration_has_redacted_value(config),
        "inbound_auth_mode": if inbound_auth_configured { "bearer" } else { "none" },
        "dispatch_endpoint_configured": external_action_dispatch_url_from_config(config, "external_business_action.invoke").is_some()
            || external_action_dispatch_url_from_config(config, "external_artifact.publish").is_some(),
        "dispatch_auth_mode": external_action_dispatch_auth_mode(&dispatch_auth),
        "platform_callback_token_configured": external_config_string(
            config,
            &[
                "token",
                "callback_token",
                "callbackToken",
                "verification_token",
                "verificationToken",
            ],
        )
        .is_some(),
        "database_source": external_database_source_config_summary(config),
    })
}

fn external_database_source_config_summary(config: &Value) -> Value {
    let Some(database_source) = source_database_config_fragment(config) else {
        if let Some(pending) = config
            .get("database_source_pending")
            .or_else(|| config.get("databaseSourcePending"))
            .cloned()
        {
            return json!({
                "configured": false,
                "credential_status": "pending_secret_binding",
                "pending": external_integration_redacted_summary(pending),
            });
        }
        return json!({ "configured": false });
    };
    match MySqlSourceConfig::from_value(&database_source) {
        Ok(config) => serde_json::to_value(config.redacted_summary())
            .unwrap_or_else(|_| json!({ "configured": true, "valid": true })),
        Err(error) => json!({
            "configured": true,
            "valid": false,
            "error": error.to_string(),
        }),
    }
}

fn external_channel_drift_summary(
    unmapped_principal_count: i64,
    disabled_principal_count: i64,
    latest_principal_updated_at: Option<DateTime<Utc>>,
) -> Value {
    let signal = if disabled_principal_count > 0 {
        "disabled_principals"
    } else if unmapped_principal_count > 0 {
        "identity_mapping_gap"
    } else {
        "ok"
    };
    json!({
        "signal": signal,
        "unmapped_principal_count": unmapped_principal_count.max(0),
        "disabled_principal_count": disabled_principal_count.max(0),
        "latest_principal_updated_at": latest_principal_updated_at,
    })
}

#[cfg(test)]
fn external_source_drift_summary(
    acl_snapshot_count: i64,
    stale_acl_snapshot_count: i64,
    failed_sync_count: i64,
    latest_sync_status: Option<String>,
    latest_acl_captured_at: Option<DateTime<Utc>>,
) -> Value {
    external_source_drift_summary_with_database_readiness(
        acl_snapshot_count,
        stale_acl_snapshot_count,
        failed_sync_count,
        latest_sync_status,
        latest_acl_captured_at,
        Value::Null,
    )
}

fn external_source_drift_summary_with_database_readiness(
    acl_snapshot_count: i64,
    stale_acl_snapshot_count: i64,
    failed_sync_count: i64,
    latest_sync_status: Option<String>,
    latest_acl_captured_at: Option<DateTime<Utc>>,
    database_dataset_readiness: Value,
) -> Value {
    let latest_sync_status_lower = latest_sync_status.as_deref().map(str::to_ascii_lowercase);
    let signal = if acl_snapshot_count <= 0 {
        "acl_missing"
    } else if latest_sync_status_lower
        .as_deref()
        .is_some_and(|status| matches!(status, "failed" | "dead_lettered"))
        || failed_sync_count > 0
    {
        "sync_failed"
    } else if stale_acl_snapshot_count > 0 {
        "acl_stale"
    } else if latest_sync_status_lower
        .as_deref()
        .is_some_and(|status| matches!(status, "queued" | "running"))
    {
        "sync_recovering"
    } else {
        "ok"
    };
    let mut summary = json!({
        "signal": signal,
        "acl_snapshot_count": acl_snapshot_count.max(0),
        "stale_acl_snapshot_count": stale_acl_snapshot_count.max(0),
        "failed_sync_count": failed_sync_count.max(0),
        "latest_sync_status": latest_sync_status,
        "latest_acl_captured_at": latest_acl_captured_at,
    });
    if !database_dataset_readiness.is_null() {
        summary["database_dataset_readiness"] = database_dataset_readiness;
    }
    summary
}

fn external_database_dataset_readiness_summary(
    default_dataset_id: Option<String>,
    document_count: i64,
    indexed_document_count: i64,
    failed_document_count: i64,
    processing_document_count: i64,
    chunk_count: i64,
    indexed_chunk_count: i64,
    latest_document_updated_at: Option<DateTime<Utc>>,
) -> Value {
    let document_count = document_count.max(0);
    let indexed_document_count = indexed_document_count.max(0);
    let failed_document_count = failed_document_count.max(0);
    let processing_document_count = processing_document_count.max(0);
    let chunk_count = chunk_count.max(0);
    let indexed_chunk_count = indexed_chunk_count.max(0);
    let signal = if document_count == 0 {
        "no_documents"
    } else if indexed_document_count > 0 && indexed_chunk_count > 0 {
        if failed_document_count > 0 || processing_document_count > 0 {
            "partial_ready"
        } else {
            "ready"
        }
    } else if failed_document_count > 0 && processing_document_count == 0 {
        "failed"
    } else {
        "processing"
    };
    json!({
        "signal": signal,
        "default_dataset_id": default_dataset_id,
        "document_count": document_count,
        "indexed_document_count": indexed_document_count,
        "failed_document_count": failed_document_count,
        "processing_document_count": processing_document_count,
        "chunk_count": chunk_count,
        "indexed_chunk_count": indexed_chunk_count,
        "latest_document_updated_at": latest_document_updated_at,
    })
}

fn external_artifact_summary(
    status_action_count: i64,
    publish_action_count: i64,
    revoke_action_count: i64,
    pending_confirmation_count: i64,
    blocked_count: i64,
    failed_count: i64,
    published_count: i64,
    revoked_count: i64,
    latest_artifact_action_at: Option<DateTime<Utc>>,
) -> Value {
    let signal = if pending_confirmation_count > 0 {
        "artifact_confirmation_pending"
    } else if failed_count > 0 {
        "artifact_failed"
    } else if blocked_count > 0 {
        "artifact_blocked"
    } else if revoked_count > 0 {
        "artifact_revoked"
    } else if published_count > 0 {
        "artifact_published"
    } else if status_action_count + publish_action_count + revoke_action_count > 0 {
        "artifact_observed"
    } else {
        "none"
    };
    json!({
        "signal": signal,
        "status_action_count": status_action_count.max(0),
        "publish_action_count": publish_action_count.max(0),
        "revoke_action_count": revoke_action_count.max(0),
        "pending_confirmation_count": pending_confirmation_count.max(0),
        "blocked_count": blocked_count.max(0),
        "failed_count": failed_count.max(0),
        "published_count": published_count.max(0),
        "revoked_count": revoked_count.max(0),
        "latest_artifact_action_at": latest_artifact_action_at,
    })
}

