async fn apply_database_source_profile(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(source_id): Path<String>,
    Json(request): Json<ApplyDatabaseSourceProfileRequest>,
) -> std::result::Result<Json<ApplyDatabaseSourceProfileResponse>, ApiError> {
    ensure_main_system_external_source_access(&state, &headers, &source_id).await?;
    let source = load_enabled_database_source_connection(&state, &source_id).await?;
    let config = mysql_source_config_for_request(&source, &request.database_source)?;
    let profile = profile_mysql_database(&config, request.sample_limit.unwrap_or(100))
        .await
        .map_err(database_source_error_to_api)?;
    let database_source =
        database_source_config_with_profile_mappings(&config, &profile, &request.tables)?;
    let updated_at = if request.dry_run {
        None
    } else {
        Some(
            update_database_source_config_redacted(&state, &source.source_id, &database_source)
                .await?,
        )
    };

    Ok(Json(ApplyDatabaseSourceProfileResponse {
        accepted: true,
        source_id: source.source_id,
        connector_kind: source.connector_kind,
        dry_run: request.dry_run,
        redacted_summary: serde_json::to_value(
            MySqlSourceConfig::from_value(&database_source)
                .map_err(database_source_error_to_api)?
                .redacted_summary(),
        )
        .unwrap_or_else(|_| json!({})),
        database_source,
        profile: serde_json::to_value(profile).unwrap_or_else(|_| json!({})),
        updated_at,
    }))
}

async fn aggregate_database_source(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(source_id): Path<String>,
    Json(request): Json<AggregateDatabaseSourceRequest>,
) -> std::result::Result<Json<AggregateDatabaseSourceResponse>, ApiError> {
    ensure_main_system_external_source_access(&state, &headers, &source_id).await?;
    validate_required("table", &request.table)?;
    let source = load_enabled_database_source_connection(&state, &source_id).await?;
    let config = mysql_source_config_for_request(&source, &request.database_source)?;
    let aggregate_request = MySqlAggregateRequest {
        table: request.table,
        dimensions: request.dimensions,
        metric: request.metric,
        aggregation: request.aggregation,
        order_direction: None,
        latest_time_column: None,
        limit: request.limit,
        scan_limit: request.scan_limit,
    };
    let result = aggregate_mysql_table(&config, &aggregate_request)
        .await
        .map_err(database_source_error_to_api)?;
    Ok(Json(AggregateDatabaseSourceResponse {
        source_id: source.source_id,
        connector_kind: source.connector_kind,
        redacted_summary: serde_json::to_value(config.redacted_summary())
            .unwrap_or_else(|_| json!({})),
        result: serde_json::to_value(result).unwrap_or_else(|_| json!({})),
    }))
}

async fn get_database_source_status(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(source_id): Path<String>,
) -> std::result::Result<Json<GetDatabaseSourceStatusResponse>, ApiError> {
    ensure_main_system_external_source_access(&state, &headers, &source_id).await?;
    let source = load_enabled_database_source_connection(&state, &source_id).await?;
    let redacted_summary = external_database_source_config_summary(&source.config_redacted);
    let status = database_source_status_summary(&state, &source).await?;
    Ok(Json(GetDatabaseSourceStatusResponse {
        source_id: source.source_id,
        connector_kind: source.connector_kind,
        redacted_summary,
        status,
    }))
}

async fn get_external_channel_database_source_status(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path((connection_id, source_external_id)): Path<(String, String)>,
) -> std::result::Result<Json<GetDatabaseSourceStatusResponse>, ApiError> {
    validate_required("connection_id", &connection_id)?;
    validate_required("source_external_id", &source_external_id)?;

    let connection = load_external_channel_connection(&state, &connection_id).await?;
    ensure_external_channel_inbound_bearer_auth(&headers, &connection)?;
    ensure_external_channel_enabled(&connection_id, &connection)?;
    let source_id = non_empty_trimmed_string(&source_external_id).ok_or_else(|| {
        ApiError::bad_request(
            "validation_error",
            "source_external_id is required".to_string(),
        )
    })?;
    ensure_external_channel_database_source_allowed(&connection, &source_id)?;

    let source = load_enabled_database_source_connection(&state, &source_id).await?;
    let redacted_summary = external_database_source_config_summary(&source.config_redacted);
    let status = database_source_status_summary(&state, &source).await?;
    Ok(Json(GetDatabaseSourceStatusResponse {
        source_id: source.source_id,
        connector_kind: source.connector_kind,
        redacted_summary,
        status,
    }))
}

async fn create_external_channel_database_source(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(connection_id): Path<String>,
    Json(request): Json<CreateExternalDatabaseSourceRequest>,
) -> std::result::Result<(StatusCode, Json<CreateExternalDatabaseSourceResponse>), ApiError> {
    validate_required("connection_id", &connection_id)?;
    let connection = load_external_channel_connection(&state, &connection_id).await?;
    ensure_external_channel_inbound_bearer_auth(&headers, &connection)?;
    ensure_external_channel_enabled(&connection_id, &connection)?;

    let prepared = prepare_external_channel_database_source_config(&connection_id, &request)?;
    let source = upsert_external_channel_database_source_connection(
        &state,
        &prepared.source_id,
        &prepared.source_key,
        &prepared.display_name,
        &prepared.base_url_redacted,
        &prepared.config_redacted,
        &prepared.health_status,
    )
    .await?;
    allow_external_channel_database_source(
        &state,
        &connection_id,
        &source.source_id,
        &source.display_name,
    )
    .await?;

    Ok((
        StatusCode::ACCEPTED,
        Json(CreateExternalDatabaseSourceResponse {
            accepted: true,
            source_external_id: prepared.source_id.clone(),
            source_id: source.source_id.clone(),
            source: json!({
                "id": source.source_id,
                "name": source.display_name,
                "connector_kind": source.connector_kind,
                "status": prepared.credential_status,
            }),
            redacted_summary: prepared.redacted_summary,
            credential_status: prepared.credential_status,
            warnings: prepared.warnings,
        }),
    ))
}

#[derive(Clone, Debug)]
struct PreparedExternalChannelDatabaseSource {
    source_id: String,
    source_key: String,
    display_name: String,
    base_url_redacted: String,
    config_redacted: Value,
    redacted_summary: Value,
    credential_status: String,
    health_status: String,
    warnings: Vec<String>,
}

fn prepare_external_channel_database_source_config(
    connection_id: &str,
    request: &CreateExternalDatabaseSourceRequest,
) -> std::result::Result<PreparedExternalChannelDatabaseSource, ApiError> {
    let source_id = validate_external_database_source_id(&request.source_external_id)?;
    let connector_kind = normalize_external_database_connector_kind(&request.connector_kind)?;
    let display_name =
        trim_optional(request.name.clone()).unwrap_or_else(|| format!("业务库 {source_id}"));
    let requested_tables = normalize_external_database_source_table_names(&request.tables)?;
    let connection_env = request
        .connection_env
        .as_deref()
        .and_then(non_empty_trimmed_string)
        .or_else(|| {
            request
                .database_source
                .get("connection_env")
                .or_else(|| request.database_source.get("connectionEnv"))
                .and_then(Value::as_str)
                .and_then(non_empty_trimmed_string)
        });
    let raw_connection_url = request
        .connection_url
        .as_deref()
        .and_then(non_empty_trimmed_string);
    let database = request
        .database
        .as_deref()
        .and_then(non_empty_trimmed_string)
        .or_else(|| {
            request
                .database_source
                .get("database")
                .and_then(Value::as_str)
                .and_then(non_empty_trimmed_string)
        })
        .or_else(|| {
            raw_connection_url
                .as_deref()
                .and_then(infer_database_name_from_connection_url)
        });
    let raw_credential_supplied = raw_connection_url.is_some()
        || request
            .username
            .as_deref()
            .and_then(non_empty_trimmed_string)
            .is_some()
        || request
            .password
            .as_deref()
            .and_then(non_empty_trimmed_string)
            .is_some();
    let mut warnings = Vec::new();
    let (config_redacted, redacted_summary, credential_status, health_status, base_url_redacted) =
        if let Some(connection_env) = connection_env {
            let database = database.ok_or_else(|| {
                ApiError::bad_request(
                    "external_database_source_database_required",
                    "database is required when connection_env is supplied".to_string(),
                )
            })?;
            let mut database_source = match request.database_source.clone() {
                Value::Object(map) => Value::Object(map),
                Value::Null => json!({}),
                _ => {
                    return Err(ApiError::bad_request(
                        "external_database_source_invalid",
                        "database_source must be an object when supplied".to_string(),
                    ))
                }
            };
            set_payload_value(
                &mut database_source,
                "connection_env",
                json!(connection_env),
            );
            set_payload_value(&mut database_source, "database", json!(database));
            if let Some(dataset_external_id) = request
                .dataset_external_id
                .as_deref()
                .and_then(non_empty_trimmed_string)
            {
                set_payload_value(
                    &mut database_source,
                    "requested_dataset_external_id",
                    json!(dataset_external_id),
                );
            }
            let config = MySqlSourceConfig::from_value(&database_source)
                .map_err(database_source_error_to_api)?;
            if raw_credential_supplied {
                warnings.push(
                    "connection_url/username/password were received but not stored because connection_env was supplied"
                        .to_string(),
                );
            }
            (
                json!({
                    "database_source": database_source,
                    "external_channel": {
                        "connection_id": connection_id,
                        "source_external_id": source_id,
                        "requested_tables": requested_tables,
                        "dataset_external_id": request.dataset_external_id,
                        "dataset_title": request.dataset_title,
                    },
                    "credential_status": "ready",
                    "raw_credentials_stored": false,
                }),
                serde_json::to_value(config.redacted_summary()).unwrap_or_else(|_| json!({})),
                "ready".to_string(),
                "unknown".to_string(),
                format!("env:{connection_env}"),
            )
        } else {
            if !raw_credential_supplied {
                return Err(ApiError::bad_request(
                    "external_database_source_credential_required",
                    "connection_env is required for an immediately usable database source; raw credentials are accepted only as a pending secret-binding request"
                        .to_string(),
                ));
            }
            let database = database.unwrap_or_else(|| "unknown".to_string());
            let redacted_url = raw_connection_url
                .as_deref()
                .map(redact_database_connection_url)
                .unwrap_or_else(|| "[not supplied]".to_string());
            warnings.push(
                "raw database credentials were not stored; bind a server-side connection_env to make this source usable"
                    .to_string(),
            );
            (
                json!({
                    "database_source_pending": {
                        "kind": connector_kind,
                        "database": database,
                        "connection_url_redacted": redacted_url,
                        "username_supplied": request.username.as_ref().is_some_and(|value| !value.trim().is_empty()),
                        "password_supplied": request.password.as_ref().is_some_and(|value| !value.trim().is_empty()),
                        "requested_tables": requested_tables,
                        "dataset_external_id": request.dataset_external_id,
                        "dataset_title": request.dataset_title,
                    },
                    "external_channel": {
                        "connection_id": connection_id,
                        "source_external_id": source_id,
                    },
                    "credential_status": "pending_secret_binding",
                    "raw_credentials_stored": false,
                }),
                json!({
                    "configured": false,
                    "kind": connector_kind,
                    "database": database,
                    "connection_url_redacted": redacted_url,
                    "requested_tables": requested_tables,
                    "credential_status": "pending_secret_binding",
                }),
                "pending_secret_binding".to_string(),
                "pending_secret_binding".to_string(),
                redacted_url,
            )
        };

    Ok(PreparedExternalChannelDatabaseSource {
        source_key: format!("external-channel:{connection_id}:database:{source_id}"),
        source_id,
        display_name,
        base_url_redacted,
        config_redacted,
        redacted_summary,
        credential_status,
        health_status,
        warnings,
    })
}

fn normalize_external_database_connector_kind(kind: &str) -> std::result::Result<String, ApiError> {
    let normalized = kind
        .trim()
        .chars()
        .filter(|ch| !matches!(ch, '-' | '_' | ' ' | '\t' | '\n' | '\r'))
        .flat_map(|ch| ch.to_lowercase())
        .collect::<String>();
    match normalized.as_str() {
        "" | "mysql" | "mysqlsource" | "databasesource" => Ok("mysql".to_string()),
        "postgresql" | "postgres" | "sqlserver" | "oracle" | "mongodb" | "restapi" => {
            Err(ApiError::bad_request_with_details(
                "unsupported_connector_kind",
                "the first external database-source API version only supports mysql".to_string(),
                json!({
                    "requested_connector_kind": kind,
                    "supported_connector_kinds": ["mysql"],
                }),
            ))
        }
        _ => Err(ApiError::bad_request_with_details(
            "unsupported_connector_kind",
            "connector_kind must be mysql for this endpoint".to_string(),
            json!({
                "requested_connector_kind": kind,
                "supported_connector_kinds": ["mysql"],
            }),
        )),
    }
}

fn validate_external_database_source_id(value: &str) -> std::result::Result<String, ApiError> {
    let value = non_empty_trimmed_string(value).ok_or_else(|| {
        ApiError::bad_request(
            "validation_error",
            "source_external_id must not be empty".to_string(),
        )
    })?;
    if value.chars().count() > 128
        || value
            .chars()
            .any(|ch| ch.is_control() || matches!(ch, '/' | '\\' | '?' | '#'))
    {
        return Err(ApiError::bad_request(
            "validation_error",
            "source_external_id must be printable text within 128 characters and must not contain path separators".to_string(),
        ));
    }
    Ok(value)
}

fn normalize_external_database_source_table_names(
    tables: &[String],
) -> std::result::Result<Vec<String>, ApiError> {
    let mut output = Vec::new();
    for table in tables {
        let Some(table) = non_empty_trimmed_string(table) else {
            continue;
        };
        if table.chars().count() > 128 || table.chars().any(char::is_control) {
            return Err(ApiError::bad_request(
                "validation_error",
                "tables must contain printable table names within 128 characters".to_string(),
            ));
        }
        if !output.contains(&table) {
            output.push(table);
        }
    }
    Ok(output)
}

fn infer_database_name_from_connection_url(url: &str) -> Option<String> {
    let without_query = url.split(['?', '#']).next().unwrap_or(url);
    let after_scheme = without_query
        .strip_prefix("jdbc:mysql://")
        .or_else(|| without_query.strip_prefix("mysql://"))
        .unwrap_or(without_query);
    after_scheme
        .rsplit('/')
        .next()
        .and_then(non_empty_trimmed_string)
        .and_then(|value| value.split(';').next().and_then(non_empty_trimmed_string))
}

fn redact_database_connection_url(url: &str) -> String {
    let without_query = url.split(['?', '#']).next().unwrap_or(url.trim());
    let Some((scheme, rest)) = without_query.split_once("://") else {
        return "[redacted-database-url]".to_string();
    };
    let rest = rest.rsplit_once('@').map(|(_, host)| host).unwrap_or(rest);
    format!("{scheme}://{rest}")
}

async fn upsert_external_channel_database_source_connection(
    state: &AppState,
    source_id: &str,
    source_key: &str,
    display_name: &str,
    base_url_redacted: &str,
    config_redacted: &Value,
    health_status: &str,
) -> std::result::Result<ExternalSourceConnectionSummary, ApiError> {
    let now = Utc::now();
    let row = sqlx::query(
        r#"
        insert into external_source_connections (
            id,
            tenant_id,
            connector_kind,
            source_key,
            display_name,
            base_url_redacted,
            config_redacted,
            status,
            sync_mode,
            permission_mode,
            health_status,
            created_at,
            updated_at
        )
        values ($1, $2, 'mysql', $3, $4, $5, $6, 'enabled', 'pull', 'source_acl_snapshot', $7, $8, $8)
        on conflict (tenant_id, id) do update
        set connector_kind = 'mysql',
            display_name = excluded.display_name,
            base_url_redacted = excluded.base_url_redacted,
            config_redacted = external_source_connections.config_redacted || excluded.config_redacted,
            status = 'enabled',
            sync_mode = 'pull',
            permission_mode = 'source_acl_snapshot',
            health_status = excluded.health_status,
            disabled_at = null,
            updated_at = excluded.updated_at
        returning id,
                  connector_kind,
                  display_name,
                  sync_mode,
                  permission_mode,
                  health_status,
                  config_redacted,
                  disabled_at
        "#,
    )
    .bind(source_id)
    .bind(state.tenant_id.0)
    .bind(source_key)
    .bind(display_name)
    .bind(base_url_redacted)
    .bind(config_redacted)
    .bind(health_status)
    .bind(now)
    .fetch_one(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;
    Ok(ExternalSourceConnectionSummary {
        source_id: row.get("id"),
        connector_kind: row.get("connector_kind"),
        display_name: row.get("display_name"),
        sync_mode: row.get("sync_mode"),
        permission_mode: row.get("permission_mode"),
        health_status: row.get("health_status"),
        config_redacted: row.get("config_redacted"),
        disabled_at: row.get("disabled_at"),
    })
}

async fn allow_external_channel_database_source(
    state: &AppState,
    connection_id: &str,
    source_id: &str,
    display_name: &str,
) -> std::result::Result<(), ApiError> {
    let row = sqlx::query(
        r#"
        select config_redacted
        from external_channel_connections
        where tenant_id = $1 and id = $2
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(connection_id)
    .fetch_optional(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;
    let Some(row) = row else {
        return Err(ApiError::not_found(
            "external_channel_connection_not_found",
            format!("external channel connection {connection_id} was not found"),
        ));
    };
    let mut config: Value = row.get("config_redacted");
    ensure_json_object(&mut config);
    let mut allowed = external_channel_allowed_database_source_ids(&config)
        .into_iter()
        .collect::<Vec<_>>();
    if !allowed.iter().any(|existing| existing == source_id) {
        allowed.push(source_id.to_string());
    }
    set_payload_value(&mut config, "allowed_database_source_ids", json!(allowed));
    let mut sources = config
        .get("database_sources")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    if !sources.iter().any(|source| {
        source
            .get("source_id")
            .or_else(|| source.get("source_external_id"))
            .and_then(Value::as_str)
            == Some(source_id)
            || source.as_str() == Some(source_id)
    }) {
        sources.push(json!({
            "source_id": source_id,
            "source_external_id": source_id,
            "display_name": display_name,
            "connector_kind": "mysql",
            "created_by": "external_channel_database_source_api",
            "created_at": Utc::now(),
        }));
    }
    set_payload_value(&mut config, "database_sources", Value::Array(sources));
    sqlx::query(
        r#"
        update external_channel_connections
        set config_redacted = $3,
            updated_at = $4
        where tenant_id = $1 and id = $2
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(connection_id)
    .bind(config)
    .bind(Utc::now())
    .execute(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;
    Ok(())
}

async fn enqueue_external_source_sync(
    state: &AppState,
    source_id: &str,
    request: CreateExternalSourceSyncRequest,
) -> std::result::Result<CreateExternalSourceSyncResponse, ApiError> {
    let source = load_external_source_connection(state, source_id).await?;
    enqueue_external_source_sync_for_source(state, source, request, None).await
}

async fn enqueue_external_source_sync_for_source(
    state: &AppState,
    source: ExternalSourceConnectionSummary,
    request: CreateExternalSourceSyncRequest,
    owner_user_id: Option<UserId>,
) -> std::result::Result<CreateExternalSourceSyncResponse, ApiError> {
    if source.disabled_at.is_some() {
        return Err(ApiError::forbidden(
            "external_source_disabled",
            format!(
                "external source connection {} is disabled",
                source.source_id
            ),
        ));
    }

    let sync_kind = normalize_external_source_sync_kind(request.sync_kind.as_deref())?;
    let mut checkpoint = normalize_external_source_sync_object(request.checkpoint, "checkpoint")?;
    let connector_context =
        normalize_external_source_sync_object(request.connector_context, "connector_context")?;
    let connector_context =
        external_source_sync_connector_context_for_execution(&source, connector_context)?;
    if sync_kind == "incremental"
        && external_source_sync_uses_mysql(&source, &connector_context)
        && json_object_is_empty(&checkpoint)
    {
        if let Some(previous_checkpoint) =
            load_latest_successful_external_source_checkpoint(state, &source.source_id).await?
        {
            checkpoint = previous_checkpoint;
        }
    }
    let sync_run_id = Uuid::new_v4();
    create_external_sync_run(state, sync_run_id, &source, &sync_kind, &checkpoint).await?;

    let workflow_execution = build_initial_external_source_sync_execution(
        state,
        &source,
        sync_run_id,
        &sync_kind,
        request.dataset_id,
        owner_user_id,
        &checkpoint,
        &connector_context,
    )?;
    let initial_event = build_initial_external_source_sync_event(
        &workflow_execution,
        &source,
        sync_run_id,
        &sync_kind,
    );
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&workflow_execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal_with_dependencies(
        &state.storage,
        &state.workflow_catalog,
        &state.event_bus,
        state.tenant_id,
        workflow_execution.id,
        WorkflowSignal::Start,
    )
    .await?;
    update_external_sync_run_started(state, sync_run_id, &started).await?;

    Ok(CreateExternalSourceSyncResponse {
        accepted: true,
        source_id: source.source_id,
        sync_run_id: sync_run_id.to_string(),
        sync_kind,
        status: "running".to_string(),
        workflow_execution: started.execution,
        enqueued_tasks: started.enqueued_tasks,
    })
}

async fn create_external_document_parse(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(connection_id): Path<String>,
    Json(request): Json<CreateExternalDocumentParseRequest>,
) -> std::result::Result<(StatusCode, Json<CreateExternalDocumentParseResponse>), ApiError> {
    validate_required("connection_id", &connection_id)?;
    validate_required("document_external_id", &request.document_external_id)?;
    validate_required("content_url", &request.content_url)?;

    let connection = load_external_channel_connection(&state, &connection_id).await?;
    ensure_external_channel_inbound_bearer_auth(&headers, &connection)?;
    ensure_external_channel_enabled(&connection_id, &connection)?;
    let source_id = resolve_external_document_parse_source_id(&request, &connection)?;

    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let source = load_external_source_connection(&state, &source_id).await?;
    if source.disabled_at.is_some() {
        return Err(ApiError::forbidden(
            "external_source_disabled",
            format!("external source connection {} is disabled", source_id),
        ));
    }
    let external_system_user = ensure_external_channel_system_user(&state, &connection_id).await?;
    let current_user_id = Some(external_system_user.id);
    let resolved_dataset = resolve_external_document_parse_dataset(
        &state,
        &request,
        &source,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    claim_legacy_public_external_document_duplicates(
        &state,
        &source_id,
        &request.document_external_id,
        external_system_user.id,
    )
    .await?;

    let downloaded = download_external_document_parse_file(&request).await?;
    let title = request
        .title
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(&request.document_external_id)
        .to_string();
    let content_type = request
        .content_type
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(downloaded.content_type.as_str())
        .to_string();
    let document = state
        .storage
        .documents()
        .create(
            state.tenant_id,
            NewDocument {
                dataset_id: resolved_dataset.dataset.id,
                title,
                object_key: downloaded.object_key,
                content_type,
                secret_binding_ids: Vec::new(),
                owner_user_id: current_user_id,
                metadata: json!({
                    "external_source": {
                        "source_id": source_id.clone(),
                        "source_display_name": source.display_name.clone(),
                        "dataset_id": resolved_dataset.dataset.id,
                        "dataset_key": resolved_dataset.dataset.key.clone(),
                        "dataset_external_id": resolved_dataset.dataset_external_id.clone(),
                        "requested_dataset_external_id": resolved_dataset.requested_dataset_external_id.clone(),
                        "document_external_id": request.document_external_id.clone(),
                        "revision_external_id": request.revision_external_id.clone(),
                        "external_parse_request_id": request.idempotency_key.clone(),
                        "synced_at": Utc::now(),
                    },
                    "external_metadata": if request.metadata.is_object() { request.metadata.clone() } else { json!({}) },
                    "external_document_parse": {
                        "connection_id": connection_id.clone(),
                        "source_content_url_redacted": downloaded.content_url_redacted,
                        "downloaded_bytes": downloaded.size_bytes,
                        "downloaded_at": Utc::now(),
                        "dataset_resolution": {
                            "mode": resolved_dataset.resolution_mode,
                            "auto_created": resolved_dataset.auto_created,
                            "requested_dataset_key": resolved_dataset.requested_dataset_key,
                            "requested_dataset_external_id": resolved_dataset.requested_dataset_external_id.clone(),
                            "v3_dataset_id": resolved_dataset.dataset.id,
                            "v3_dataset_key": resolved_dataset.dataset.key.clone(),
                        },
                    }
                }),
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    let execution = build_initial_upload_ingest_execution(&state, &document)?;
    let initial_event = build_initial_upload_ingest_event(&execution, &document);
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal_with_dependencies(
        &state.storage,
        &state.workflow_catalog,
        &state.event_bus,
        state.tenant_id,
        execution.id,
        WorkflowSignal::Start,
    )
    .await?;

    Ok((
        StatusCode::ACCEPTED,
        Json(CreateExternalDocumentParseResponse {
            accepted: true,
            source_id,
            document_external_id: request.document_external_id,
            revision_external_id: request.revision_external_id,
            document: to_external_document_parse_document_view(document),
            workflow_execution: started.execution,
        }),
    ))
}

#[derive(Clone, Debug)]
struct ResolvedExternalDocumentParseDataset {
    dataset: Dataset,
    dataset_external_id: Option<String>,
    requested_dataset_external_id: Option<String>,
    requested_dataset_key: String,
    resolution_mode: &'static str,
    auto_created: bool,
}

fn resolve_external_document_parse_source_id(
    request: &CreateExternalDocumentParseRequest,
    connection: &ExternalChannelConnectionSummary,
) -> std::result::Result<String, ApiError> {
    non_empty_trimmed_string(&request.source_id)
        .or_else(|| external_channel_default_source_id_from_config(&connection.config_redacted))
        .ok_or_else(|| {
            ApiError::bad_request(
                "validation_error",
                "source_id is required when the external channel has no default_source_id"
                    .to_string(),
            )
        })
}

async fn resolve_external_document_parse_dataset(
    state: &AppState,
    request: &CreateExternalDocumentParseRequest,
    source: &ExternalSourceConnectionSummary,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<ResolvedExternalDocumentParseDataset, ApiError> {
    let owner_user_id = current_user_id.ok_or_else(|| {
        ApiError::internal(
            "external_owner_missing",
            "external document parse requires a system owner".to_string(),
        )
    })?;
    let requested_dataset_external_id = trim_optional(request.dataset_external_id.clone());
    let dataset_external_id = effective_external_document_parse_dataset_external_id(
        requested_dataset_external_id.as_deref(),
    );
    if let Some(dataset_id) = request.dataset_id {
        let dataset = load_visible_dataset_for_user(
            state,
            dataset_id,
            active_secret_binding_ids,
            current_user_id,
        )
        .await?;
        let dataset =
            harden_external_owned_dataset(state, dataset, owner_user_id, "external_document_parse")
                .await?;
        return Ok(ResolvedExternalDocumentParseDataset {
            requested_dataset_key: dataset.key.clone(),
            dataset,
            dataset_external_id,
            requested_dataset_external_id,
            resolution_mode: "provided_dataset_id",
            auto_created: false,
        });
    }

    let requested_dataset_key =
        external_document_parse_dataset_key(&source.source_id, dataset_external_id.as_deref());
    let existing = state
        .storage
        .datasets()
        .list_by_tenant(state.tenant_id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .find(|dataset| dataset.key == requested_dataset_key);
    if let Some(dataset) = existing {
        let dataset =
            harden_external_owned_dataset(state, dataset, owner_user_id, "external_document_parse")
                .await?;
        return Ok(ResolvedExternalDocumentParseDataset {
            dataset,
            dataset_external_id,
            requested_dataset_external_id,
            requested_dataset_key,
            resolution_mode: "source_dataset_reused",
            auto_created: false,
        });
    }

    let dataset = state
        .storage
        .datasets()
        .create_with_metadata(
            state.tenant_id,
            NewDataset {
                key: requested_dataset_key.clone(),
                title: external_document_parse_dataset_title(request, source),
                description: Some(format!(
                    "Auto-created for external source {} document parsing.",
                    source.source_id
                )),
                owner_user_id: Some(owner_user_id),
            },
            json!({
                "visibility": DatasetVisibility::Private.as_str(),
                "default_secret_binding_ids": [],
                "external_source": {
                    "source_id": source.source_id.clone(),
                    "connector_kind": source.connector_kind.clone(),
                    "display_name": source.display_name.clone(),
                    "dataset_external_id": dataset_external_id.clone(),
                    "requested_dataset_external_id": requested_dataset_external_id.clone(),
                    "created_by": "external_document_parse",
                    "created_at": Utc::now(),
                },
            }),
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok(ResolvedExternalDocumentParseDataset {
        dataset,
        dataset_external_id,
        requested_dataset_external_id,
        requested_dataset_key,
        resolution_mode: "source_dataset_created",
        auto_created: true,
    })
}

async fn harden_external_owned_dataset(
    state: &AppState,
    mut dataset: Dataset,
    owner_user_id: UserId,
    reason: &str,
) -> std::result::Result<Dataset, ApiError> {
    if let Some(existing_owner_user_id) = dataset.owner_user_id {
        if existing_owner_user_id != owner_user_id {
            return Err(ApiError::forbidden(
                "external_dataset_owner_mismatch",
                format!(
                    "dataset {} belongs to another account and cannot be used by this external integration",
                    dataset.id
                ),
            ));
        }
    } else {
        dataset = state
            .storage
            .datasets()
            .update_owner_user_id(state.tenant_id, dataset.id, owner_user_id)
            .await
            .map_err(ApiError::from_storage)?
            .ok_or_else(|| {
                ApiError::forbidden(
                    "external_dataset_owner_mismatch",
                    format!(
                        "dataset {} belongs to another account and cannot be claimed by this external integration",
                        dataset.id
                    ),
                )
            })?;
    }

    if dataset.visibility != DatasetVisibility::Private {
        dataset = state
            .storage
            .datasets()
            .update_metadata(
                state.tenant_id,
                dataset.id,
                &json!({
                    "visibility": DatasetVisibility::Private.as_str(),
                    "external_privacy": {
                        "hardened_at": Utc::now(),
                        "reason": reason,
                    }
                }),
            )
            .await
            .map_err(ApiError::from_storage)?;
    }

    Ok(dataset)
}

fn effective_external_document_parse_dataset_external_id(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn external_document_parse_dataset_title(
    request: &CreateExternalDocumentParseRequest,
    source: &ExternalSourceConnectionSummary,
) -> String {
    trim_optional(request.dataset_title.clone())
        .or_else(|| non_empty_trimmed_string(&source.display_name))
        .unwrap_or_else(|| format!("External source {}", source.source_id))
}

fn external_document_parse_dataset_key(
    source_id: &str,
    dataset_external_id: Option<&str>,
) -> String {
    let source_slug = external_document_parse_dataset_key_component(source_id);
    let raw_key = if let Some(dataset_external_id) = dataset_external_id {
        format!(
            "external-source-{}-dataset-{}",
            source_slug,
            external_document_parse_dataset_key_component(dataset_external_id)
        )
    } else {
        format!("external-source-{source_slug}")
    };
    compact_external_document_parse_dataset_key(raw_key)
}

fn external_document_parse_dataset_key_component(value: &str) -> String {
    let mut slug = String::new();
    let mut last_was_separator = false;
    for character in value.trim().chars() {
        if character.is_ascii_alphanumeric() {
            slug.push(character.to_ascii_lowercase());
            last_was_separator = false;
        } else if !slug.is_empty() && !last_was_separator {
            slug.push('-');
            last_was_separator = true;
        }
    }
    while slug.ends_with('-') {
        slug.pop();
    }
    if slug.is_empty() {
        return format!("ref-{}", &sha256_hex([value.as_bytes()])[..12]);
    }
    if slug.len() > 64 {
        let hash = sha256_hex([value.as_bytes()]);
        slug.truncate(48);
        while slug.ends_with('-') {
            slug.pop();
        }
        slug.push('-');
        slug.push_str(&hash[..12]);
    }
    slug
}

fn compact_external_document_parse_dataset_key(mut key: String) -> String {
    if key.len() <= 128 {
        return key;
    }
    let hash = sha256_hex([key.as_bytes()]);
    key.truncate(112);
    while key.ends_with('-') {
        key.pop();
    }
    key.push('-');
    key.push_str(&hash[..12]);
    key
}

async fn get_external_document_parse_detail(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path((connection_id, document_external_id)): Path<(String, String)>,
    Query(query): Query<BTreeMap<String, String>>,
) -> std::result::Result<Json<GetExternalDocumentParseDetailResponse>, ApiError> {
    validate_required("connection_id", &connection_id)?;
    validate_required("document_external_id", &document_external_id)?;

    let connection = load_external_channel_connection(&state, &connection_id).await?;
    ensure_external_channel_inbound_bearer_auth(&headers, &connection)?;
    ensure_external_channel_enabled(&connection_id, &connection)?;
    let external_system_user = ensure_external_channel_system_user(&state, &connection_id).await?;

    let source_id = query
        .get("source_id")
        .or_else(|| query.get("sourceId"))
        .map(String::as_str)
        .and_then(non_empty_trimmed_string)
        .or_else(|| external_channel_default_source_id_from_config(&connection.config_redacted));
    let revision_external_id = query
        .get("revision_external_id")
        .or_else(|| query.get("revisionExternalId"))
        .map(String::as_str)
        .and_then(non_empty_trimmed_string);
    let source_id = match source_id {
        Some(source_id) => Some(source_id),
        None => {
            infer_external_document_source_id(
                &state,
                &document_external_id,
                revision_external_id.as_deref(),
            )
            .await?
        }
    };
    if let Some(source_id) = source_id.as_deref() {
        load_external_source_connection(&state, source_id).await?;
    }

    let mut documents = if let Some(source_id) = source_id.as_deref() {
        find_external_documents_by_external_id(
            &state,
            source_id,
            &document_external_id,
            revision_external_id.as_deref(),
        )
        .await?
    } else {
        Vec::new()
    };
    if documents.is_empty() {
        if let Some(document_id) = Uuid::parse_str(&document_external_id).ok().map(DocumentId) {
            if let Some(document) = state
                .storage
                .documents()
                .get_by_id(state.tenant_id, document_id)
                .await
                .map_err(ApiError::from_storage)?
            {
                let matches_source = source_id.as_deref().map_or_else(
                    || {
                        external_document_source_id_from_metadata(
                            &document.metadata,
                            revision_external_id.as_deref(),
                        )
                        .is_some()
                    },
                    |source_id| {
                        external_document_source_matches(
                            &document.metadata,
                            source_id,
                            revision_external_id.as_deref(),
                        )
                    },
                );
                if matches_source {
                    documents.push(document);
                }
            }
        }
    }

    documents = claim_external_owned_documents(&state, documents, external_system_user.id).await?;

    let mut details = Vec::new();
    for document in documents {
        details.push(to_external_document_parse_detail_item(&state, document).await?);
    }
    details.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    let latest = details.first().cloned();
    let lifecycle = latest.as_ref().map(|item| item.lifecycle.clone());
    let chunk_count = latest.as_ref().map(|item| item.chunk_count);
    let parse_status = latest.as_ref().map(|item| item.parse_status.clone());
    let parse_quality_status = latest
        .as_ref()
        .and_then(|item| item.parse_quality_status.clone());
    let parse_quality_summary = latest
        .as_ref()
        .and_then(|item| item.parse_quality_summary.clone());
    let model_status = latest.as_ref().map(|item| item.model_status.clone());
    let retrieval_evidence_count = latest.as_ref().map(|item| item.retrieval_evidence_count);
    let ingest = latest.as_ref().map(|item| item.ingest.clone());
    let workflow = latest.as_ref().and_then(|item| item.workflow.clone());

    Ok(Json(GetExternalDocumentParseDetailResponse {
        source_id: source_id.unwrap_or_default(),
        document_external_id,
        lifecycle,
        chunk_count,
        chunk_count_camel: chunk_count,
        parse_status: parse_status.clone(),
        parse_status_camel: parse_status,
        parse_quality_status: parse_quality_status.clone(),
        parse_quality_status_camel: parse_quality_status,
        parse_quality_summary: parse_quality_summary.clone(),
        parse_quality_summary_camel: parse_quality_summary,
        model_status: model_status.clone(),
        model_status_camel: model_status,
        retrieval_evidence_count,
        retrieval_evidence_count_camel: retrieval_evidence_count,
        ingest,
        workflow,
        latest,
        documents: details,
    }))
}

async fn update_external_document_dataset(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path((connection_id, document_external_id)): Path<(String, String)>,
    Json(request): Json<UpdateExternalDocumentDatasetRequest>,
) -> std::result::Result<Json<UpdateExternalDocumentDatasetResponse>, ApiError> {
    validate_required("connection_id", &connection_id)?;
    validate_required("document_external_id", &document_external_id)?;
    if request.dataset_id.is_none() && trim_optional(request.dataset_external_id.clone()).is_none()
    {
        return Err(ApiError::bad_request(
            "validation_error",
            "dataset_external_id or dataset_id is required".to_string(),
        ));
    }

    let connection = load_external_channel_connection(&state, &connection_id).await?;
    ensure_external_channel_inbound_bearer_auth(&headers, &connection)?;
    ensure_external_channel_enabled(&connection_id, &connection)?;

    let revision_external_id = trim_optional(request.revision_external_id.clone());
    let inferred_source_id = infer_external_document_source_id(
        &state,
        &document_external_id,
        revision_external_id.as_deref(),
    )
    .await?;
    let source_id = non_empty_trimmed_string(&request.source_id)
        .or_else(|| external_channel_default_source_id_from_config(&connection.config_redacted))
        .or(inferred_source_id)
        .ok_or_else(|| {
            ApiError::bad_request(
                "validation_error",
                "source_id is required when V3 cannot infer a unique source from document_external_id"
                    .to_string(),
            )
        })?;
    let source = load_external_source_connection(&state, &source_id).await?;
    if source.disabled_at.is_some() {
        return Err(ApiError::forbidden(
            "external_source_disabled",
            format!("external source connection {} is disabled", source_id),
        ));
    }

    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let external_system_user = ensure_external_channel_system_user(&state, &connection_id).await?;
    let current_user_id = Some(external_system_user.id);
    let resolve_request = CreateExternalDocumentParseRequest {
        source_id: source_id.clone(),
        dataset_id: request.dataset_id,
        dataset_external_id: request.dataset_external_id.clone(),
        dataset_title: request.dataset_title.clone(),
        document_external_id: document_external_id.clone(),
        revision_external_id: revision_external_id.clone(),
        title: None,
        content_type: None,
        content_url: "https://third-party.example/document-dataset-move".to_string(),
        metadata: json!({}),
        idempotency_key: None,
        allow_http_loopback: false,
    };
    let resolved_dataset = resolve_external_document_parse_dataset(
        &state,
        &resolve_request,
        &source,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    let documents = find_external_documents_by_external_id(
        &state,
        &source_id,
        &document_external_id,
        revision_external_id.as_deref(),
    )
    .await?;
    if documents.is_empty() {
        return Err(ApiError::not_found(
            "external_document_not_found",
            format!("external document {document_external_id} was not found"),
        ));
    }

    let mut previous_dataset_ids = BTreeSet::new();
    let mut moved_documents = Vec::new();
    for document in
        claim_external_owned_documents(&state, documents, external_system_user.id).await?
    {
        previous_dataset_ids.insert(document.dataset_id);
        let metadata_updates = external_document_dataset_move_metadata(
            &document,
            &source,
            &resolved_dataset,
            &document_external_id,
        );
        let updated = state
            .storage
            .documents()
            .move_to_dataset(
                state.tenant_id,
                document.id,
                resolved_dataset.dataset.id,
                &metadata_updates,
                Utc::now(),
            )
            .await
            .map_err(ApiError::from_storage)?;
        moved_documents.push(to_external_document_parse_document_view(updated));
    }
    if moved_documents.is_empty() {
        return Err(ApiError::not_found(
            "external_document_not_found",
            format!("external document {document_external_id} was not found"),
        ));
    }
    moved_documents.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));

    Ok(Json(UpdateExternalDocumentDatasetResponse {
        accepted: true,
        source_id,
        document_external_id,
        revision_external_id,
        dataset_id: resolved_dataset.dataset.id,
        dataset_external_id: resolved_dataset.dataset_external_id,
        moved_count: moved_documents.len() as u32,
        previous_dataset_ids: previous_dataset_ids.into_iter().collect(),
        documents: moved_documents,
    }))
}

fn external_document_dataset_move_metadata(
    document: &Document,
    source: &ExternalSourceConnectionSummary,
    resolved_dataset: &ResolvedExternalDocumentParseDataset,
    document_external_id: &str,
) -> Value {
    let moved_at = Utc::now();
    let mut external_source = document
        .metadata
        .get("external_source")
        .or_else(|| document.metadata.get("externalSource"))
        .cloned()
        .unwrap_or_else(|| json!({}));
    set_payload_value(
        &mut external_source,
        "source_id",
        json!(source.source_id.clone()),
    );
    set_payload_value(
        &mut external_source,
        "source_display_name",
        json!(source.display_name.clone()),
    );
    set_payload_value(
        &mut external_source,
        "dataset_id",
        json!(resolved_dataset.dataset.id),
    );
    set_payload_value(
        &mut external_source,
        "dataset_key",
        json!(resolved_dataset.dataset.key.clone()),
    );
    set_payload_value(
        &mut external_source,
        "dataset_external_id",
        json!(resolved_dataset.dataset_external_id.clone()),
    );
    set_payload_value(
        &mut external_source,
        "requested_dataset_external_id",
        json!(resolved_dataset.requested_dataset_external_id.clone()),
    );
    set_payload_value(
        &mut external_source,
        "document_external_id",
        json!(document_external_id),
    );
    set_payload_value(
        &mut external_source,
        "previous_dataset_id",
        json!(document.dataset_id),
    );
    let previous_dataset_external_id = document
        .metadata
        .get("external_source")
        .or_else(|| document.metadata.get("externalSource"))
        .and_then(Value::as_object)
        .and_then(|object| {
            object
                .get("dataset_external_id")
                .or_else(|| object.get("datasetExternalId"))
        })
        .cloned()
        .unwrap_or(Value::Null);
    set_payload_value(
        &mut external_source,
        "previous_dataset_external_id",
        previous_dataset_external_id,
    );
    set_payload_value(&mut external_source, "moved_at", json!(moved_at));

    json!({
        "external_source": external_source,
        "external_document_dataset_move": {
            "moved_at": moved_at,
            "previous_dataset_id": document.dataset_id,
            "target_dataset_id": resolved_dataset.dataset.id,
            "target_dataset_key": resolved_dataset.dataset.key.clone(),
            "target_dataset_external_id": resolved_dataset.dataset_external_id.clone(),
            "requested_dataset_external_id": resolved_dataset.requested_dataset_external_id.clone(),
            "resolution_mode": resolved_dataset.resolution_mode,
            "auto_created_dataset": resolved_dataset.auto_created
        }
    })
}

