fn external_static_page_image_asset_provenance_summary(
    image_job: &StaticPageImageJobView,
) -> Value {
    let raw = image_job
        .image_prompt_payload
        .pointer("/orchestrator/previewAssetProvenance")
        .or_else(|| {
            image_job
                .image_prompt_payload
                .pointer("/orchestrator/preview_asset_provenance")
        })
        .unwrap_or(&Value::Null);
    let render_asset_url = image_job
        .preview_asset_key
        .as_deref()
        .map(external_static_page_safe_preview_asset_ref)
        .unwrap_or(Value::Null);
    let persisted_preview_asset_key = raw
        .get("persistedPreviewAssetKey")
        .or_else(|| raw.get("persisted_preview_asset_key"))
        .and_then(Value::as_str)
        .map(external_static_page_safe_preview_asset_ref)
        .filter(|value| !value.is_null())
        .unwrap_or_else(|| render_asset_url.clone());
    json!({
        "schema": "v3.static_page_preview_asset_provenance",
        "schemaVersion": 1,
        "renderAssetUrl": render_asset_url,
        "renderAssetPolicy": "use_persisted_v3_preview_asset_for_final_html",
        "sourceAssetKind": raw.get("sourceAssetKind")
            .or_else(|| raw.get("source_asset_kind"))
            .and_then(Value::as_str)
            .map(|value| truncate_assistant_supply_text(value, 64))
            .unwrap_or_else(|| "unknown".to_string()),
        "sourceAssetRef": raw.get("sourceAssetRef")
            .or_else(|| raw.get("source_asset_ref"))
            .and_then(Value::as_str)
            .map(external_static_page_safe_preview_asset_ref)
            .unwrap_or(Value::Null),
        "sourceAssetRefRedacted": raw.get("sourceAssetRefRedacted")
            .or_else(|| raw.get("source_asset_ref_redacted"))
            .and_then(Value::as_bool)
            .unwrap_or(true),
        "sourceAssetHadQuery": raw.get("sourceAssetHadQuery")
            .or_else(|| raw.get("source_asset_had_query"))
            .and_then(Value::as_bool)
            .unwrap_or(false),
        "persisted": raw.get("persisted").and_then(Value::as_bool).unwrap_or_else(|| image_job.preview_asset_key.is_some()),
        "persistedPreviewAssetKey": persisted_preview_asset_key,
        "storageStatus": raw.get("storageStatus")
            .or_else(|| raw.get("storage_status"))
            .and_then(Value::as_str)
            .map(|value| truncate_assistant_supply_text(value, 64))
            .unwrap_or_else(|| if image_job.preview_asset_key.is_some() { "ready".to_string() } else { "unknown".to_string() }),
        "byteSize": raw.get("byteSize").or_else(|| raw.get("byte_size")).and_then(Value::as_u64).map(Value::from).unwrap_or(Value::Null),
        "mimeType": raw.get("mimeType").or_else(|| raw.get("mime_type")).and_then(Value::as_str).map(|value| Value::String(truncate_assistant_supply_text(value, 80))).unwrap_or(Value::Null),
        "width": raw.get("width").and_then(Value::as_i64).map(Value::from).unwrap_or(Value::Null),
        "height": raw.get("height").and_then(Value::as_i64).map(Value::from).unwrap_or(Value::Null),
    })
}

fn external_static_page_safe_preview_asset_ref(value: &str) -> Value {
    let trimmed = value.trim();
    if trimmed.is_empty() || trimmed.starts_with("data:image/") || trimmed.starts_with("blob:") {
        return Value::Null;
    }
    if trimmed.starts_with("http://") || trimmed.starts_with("https://") {
        if let Ok(mut url) = reqwest::Url::parse(trimmed) {
            url.set_query(None);
            url.set_fragment(None);
            return Value::String(truncate_assistant_supply_text(url.as_str(), 500));
        }
        return Value::Null;
    }
    Value::String(truncate_assistant_supply_text(trimmed, 500))
}

fn external_static_page_image_prompt_text(
    image_prompt_payload_summary: &Value,
    fallback_prompt: &str,
) -> String {
    image_prompt_payload_summary
        .get("prompt_text")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| truncate_assistant_supply_text(value, 2000))
        .unwrap_or_else(|| truncate_assistant_supply_text(fallback_prompt, 2000))
}

fn external_static_page_image_prompt_payload_summary(payload: &Value) -> Value {
    let modules = payload
        .get("modules")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .take(8)
                .map(external_static_page_image_module_summary)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let prompt_text = [
        payload.get("promptText"),
        payload.get("prompt_text"),
        payload.get("prompt"),
    ]
    .into_iter()
    .flatten()
    .find_map(Value::as_str)
    .map(|value| truncate_assistant_supply_text(value, 1200));
    json!({
        "truncated": true,
        "summary_for": "static_page_image2_data_publish",
        "title": payload.get("title").cloned().unwrap_or(Value::Null),
        "prompt_text": prompt_text,
        "style_direction": payload.get("style_direction").or_else(|| payload.get("styleDirection")).cloned().unwrap_or(Value::Null),
        "modules": modules,
        "module_count": payload
            .get("modules")
            .and_then(Value::as_array)
            .map(Vec::len)
            .unwrap_or(0),
        "preview_contract_excerpt": external_static_page_value_excerpt(
            payload
                .get("preview_contract")
                .or_else(|| payload.get("previewContract")),
            1000,
        ),
        "data_snapshot_excerpt": external_static_page_value_excerpt(
            payload
                .get("data_snapshot")
                .or_else(|| payload.get("dataSnapshot")),
            1000,
        ),
        "data_snapshot": external_static_page_image_prompt_payload_data_snapshot(payload),
    })
}

fn external_static_page_image_prompt_payload_data_snapshot(payload: &Value) -> Value {
    let snapshot = payload
        .get("data_snapshot")
        .or_else(|| payload.get("dataSnapshot"))
        .cloned()
        .unwrap_or(Value::Null);
    if snapshot.is_null() {
        return Value::Null;
    }
    json!({
        "source": snapshot.get("source").cloned().unwrap_or(Value::Null),
        "snapshotVersion": snapshot
            .get("snapshotVersion")
            .or_else(|| snapshot.get("snapshot_version"))
            .cloned()
            .unwrap_or(Value::Null),
        "updatedAt": snapshot
            .get("updatedAt")
            .or_else(|| snapshot.get("updated_at"))
            .cloned()
            .unwrap_or(Value::Null),
        "validation_summary": snapshot.get("validation_summary").cloned().unwrap_or(Value::Null),
        "sampleRowCount": snapshot
            .get("sampleRowCount")
            .or_else(|| snapshot.pointer("/validation_summary/sampleRowCount"))
            .cloned()
            .unwrap_or(Value::Null),
        "detailRowCount": snapshot
            .get("detailRowCount")
            .or_else(|| snapshot.pointer("/validation_summary/detailRowCount"))
            .cloned()
            .unwrap_or(Value::Null),
        "unitHints": snapshot
            .get("unitHints")
            .or_else(|| snapshot.pointer("/validation_summary/unitHints"))
            .cloned()
            .unwrap_or_else(|| json!([])),
        "data_source_candidates": snapshot
            .get("data_source_candidates")
            .cloned()
            .unwrap_or_else(|| json!([])),
        "field_candidates": static_page_fixed_task_compact_array(
            snapshot.get("field_candidates"),
            12,
        ),
        "module_bindings": static_page_fixed_task_compact_module_bindings(
            snapshot.get("module_bindings"),
        ),
        "structure_signals": snapshot.get("structure_signals").cloned().unwrap_or(Value::Null),
        "refresh_policy": snapshot
            .get("refresh_policy")
            .or_else(|| snapshot.get("refresh"))
            .cloned()
            .unwrap_or(Value::Null),
    })
}

fn static_page_fixed_task_compact_array(value: Option<&Value>, limit: usize) -> Value {
    Value::Array(
        value
            .and_then(Value::as_array)
            .map(|items| items.iter().take(limit).cloned().collect::<Vec<_>>())
            .unwrap_or_default(),
    )
}

fn static_page_fixed_task_compact_module_bindings(value: Option<&Value>) -> Value {
    Value::Array(
        value
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .take(12)
                    .map(|item| {
                        let mut compact = item.clone();
                        if let Some(object) = compact.as_object_mut() {
                            object.insert(
                                "sampleData".to_string(),
                                static_page_fixed_task_compact_array(
                                    item.get("sampleData").or_else(|| item.get("sample_data")),
                                    12,
                                ),
                            );
                        }
                        compact
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default(),
    )
}

fn external_static_page_image_module_summary(module: &Value) -> Value {
    json!({
        "id": module.get("id").cloned().unwrap_or(Value::Null),
        "role": module.get("role").cloned().unwrap_or(Value::Null),
        "title": module.get("title").cloned().unwrap_or(Value::Null),
        "layout": module.get("layout").cloned().unwrap_or(Value::Null),
        "content": module
            .get("content")
            .and_then(Value::as_str)
            .map(|value| truncate_assistant_supply_text(value, 240)),
        "visualization": module.get("visualization").cloned().unwrap_or(Value::Null),
    })
}

fn external_static_page_value_excerpt(value: Option<&Value>, max_chars: usize) -> Value {
    let Some(value) = value else {
        return Value::Null;
    };
    let text = serde_json::to_string(value).unwrap_or_else(|_| value.to_string());
    Value::String(truncate_assistant_supply_text(&text, max_chars))
}

fn external_channel_static_page_image2_codex_execution(
    tenant_id: TenantId,
    workflow_catalog: &WorkflowCatalog,
    assistant_run_id: AssistantRunId,
    local_thread_id: Option<String>,
    fixed_task: CodexHostFixedTaskTemplateContextView,
) -> std::result::Result<(WorkflowExecution, WorkflowEventRecord), ApiError> {
    if !external_channel_static_page_fixed_task_preview_ready(&fixed_task) {
        return Err(ApiError::bad_request(
            "static_page_effect_image_not_ready",
            "static_page_image2_data_publish requires a preview-ready Image2 asset before queuing Codex Host"
                .to_string(),
        ));
    }
    let definition = workflow_catalog
        .find_definition(WorkflowKind::CodexHostTask)
        .ok_or_else(|| {
            ApiError::internal(
                "workflow_definition_missing",
                "codex_host_task workflow definition is not registered".to_string(),
            )
        })?;
    let now = Utc::now();
    let execution_id = WorkflowExecutionId::new();
    let runtime_state = definition.initial_state(execution_id, now);
    let capability = fixed_task.template_id.as_str().to_string();
    let request = CodexHostTaskRequestView {
        assistant_run_id,
        capability: capability.clone(),
        task: Some(
            "Run the fixed V3 Image2-first static-page publish template and return only the fixed output schema."
                .to_string(),
        ),
        local_thread_id,
        fixed_task: Some(fixed_task),
        task_memory_policy: CodexHostTaskMemoryPolicyView::task_scoped(
            assistant_run_id,
            execution_id,
        ),
        safety: CodexHostTaskSafetyPolicyView::default(),
    };
    let mut context = match request.to_workflow_context() {
        Value::Object(map) => map,
        _ => Map::new(),
    };
    context.insert(
        "fixed_task_bundle".to_string(),
        codex_host_fixed_task_bundle_manifest(capability.as_str()),
    );
    context.insert(
        "retries_remaining".to_string(),
        Value::Number(runtime_state.retries_remaining.into()),
    );
    let execution = WorkflowExecution {
        id: execution_id,
        tenant_id,
        dataset_id: None,
        report_plan_id: None,
        kind: WorkflowKind::CodexHostTask,
        version: runtime_state.version,
        stage: runtime_state.stage,
        status: runtime_state.status,
        attempt: 0,
        context: Value::Object(context),
        created_at: now,
        updated_at: now,
    };
    let initial_event = codex_host_fixed_task_created_event(&execution, assistant_run_id);
    Ok((execution, initial_event))
}

fn external_channel_static_page_fixed_task_preview_ready(
    fixed_task: &CodexHostFixedTaskTemplateContextView,
) -> bool {
    fixed_task.template_id == CodexHostFixedTaskTemplateIdView::StaticPageImage2DataPublish
        && fixed_task
            .image2
            .get("preview_asset_key")
            .and_then(Value::as_str)
            .map(str::trim)
            .is_some_and(|value| !value.is_empty())
        && fixed_task
            .image2
            .get("human_confirmation_required")
            .and_then(Value::as_bool)
            == Some(false)
        && fixed_task
            .policies
            .get("effect_image_confirmation_required")
            .and_then(Value::as_bool)
            == Some(false)
        && fixed_task
            .policies
            .get("continue_to_publish_after_effect_image")
            .and_then(Value::as_bool)
            == Some(true)
}

fn external_channel_static_page_image_job_preview_ready(
    image_job: &StaticPageImageJobView,
) -> bool {
    image_job
        .preview_asset_key
        .as_deref()
        .map(str::trim)
        .is_some_and(|value| !value.is_empty())
        && matches!(
            image_job.status,
            contracts::StaticPageImageJobStatusView::PreviewReady
                | contracts::StaticPageImageJobStatusView::Confirmed
        )
}

fn assistant_run_model_is_gpt_55(model: &str) -> bool {
    let normalized = model
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .map(|ch| ch.to_ascii_lowercase())
        .collect::<String>();
    normalized.contains("gpt55")
}

fn assistant_run_primary_model_names(run: &AssistantRun) -> Vec<&str> {
    [
        run.runtime_manifest.pointer("/model"),
        run.runtime_manifest.pointer("/runtime/model"),
        run.runtime_manifest.pointer("/selected_model/model"),
        run.runtime_manifest
            .pointer("/model_gateway/selected_model/model"),
        run.runtime_manifest
            .pointer("/runtime/selected_model/model"),
        run.runtime_manifest
            .pointer("/runtime/model_gateway/selected_model/model"),
    ]
    .into_iter()
    .flatten()
    .filter_map(Value::as_str)
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .collect()
}

fn assistant_run_uses_gpt_55_primary_model(run: &AssistantRun) -> bool {
    assistant_run_primary_model_names(run)
        .into_iter()
        .any(assistant_run_model_is_gpt_55)
}

fn assistant_run_primary_model_unresolved_for_static_page(run: &AssistantRun) -> bool {
    let names = assistant_run_primary_model_names(run);
    names.is_empty()
        || names.iter().all(|model| {
            let normalized = model.trim().to_ascii_lowercase();
            normalized.is_empty()
                || normalized.contains("pending")
                || normalized.contains("unknown")
                || normalized.contains("unresolved")
        })
}

fn assistant_chat_runtime_uses_gpt_55_primary_model() -> bool {
    let runtime = resolve_runtime_selection_from_env(
        "ASSISTANT_RUN",
        MODEL_LANE_ASSISTANT_CHAT,
        DEFAULT_ASSISTANT_RUN_RUNTIME_MODEL,
    );
    assistant_run_model_is_gpt_55(&runtime.model)
}

fn assistant_run_static_page_should_use_gpt_55_local_route(run: &AssistantRun) -> bool {
    assistant_run_uses_gpt_55_primary_model(run)
        || (run.service_lane == "external_channel"
            && assistant_run_primary_model_unresolved_for_static_page(run)
            && assistant_chat_runtime_uses_gpt_55_primary_model())
}

fn external_channel_static_page_publish_completed_event_is_final(
    event: &AssistantRunEvent,
) -> bool {
    if event.event_name != "assistant_run.external_channel_static_page_publish_completed" {
        return false;
    }
    let publish_mode = event
        .payload
        .get("publish_mode")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let provisional_direct_html = event
        .payload
        .get("provisional_direct_html")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    publish_mode != "demo_direct_generated_artifact" && !provisional_direct_html
}

async fn external_channel_static_page_image2_enqueue_if_enabled(
    state: &AppState,
    connection_id: &str,
    connection: &ExternalChannelConnectionSummary,
    run: &AssistantRun,
    draft: &StaticPageDraft,
    image_job: &StaticPageImageJobView,
    message: &ExternalBotMessageView,
    template_reference: Option<&Value>,
    evidence_summary: &Value,
    missing_evidence: &Value,
) -> std::result::Result<Option<WorkflowExecutionId>, ApiError> {
    let fixed_task = external_channel_static_page_image2_fixed_task(
        state.tenant_id,
        connection_id,
        connection,
        run,
        draft,
        image_job,
        message,
        &run.user_prompt,
        template_reference,
        evidence_summary,
        missing_evidence,
    );
    let capability = fixed_task.template_id.as_str();
    let readiness = external_channel_static_page_codex_auto_publish_readiness();
    if !readiness.ready {
        record_codex_host_fixed_task_preflight_rejected(
            state,
            run.id,
            Some(capability),
            &fixed_task,
            readiness.reason,
        )
        .await;
        return Ok(None);
    }
    if !external_channel_static_page_image_job_preview_ready(image_job) {
        record_codex_host_fixed_task_preflight_rejected(
            state,
            run.id,
            Some(capability),
            &fixed_task,
            "static_page_image2_preview_not_ready",
        )
        .await;
        return Ok(None);
    }

    let (execution, initial_event) = external_channel_static_page_image2_codex_execution(
        state.tenant_id,
        &state.workflow_catalog,
        run.id,
        run.local_thread_id.clone(),
        fixed_task,
    )?;
    let execution_id = execution.id;
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    Box::pin(apply_workflow_signal(
        state,
        execution_id,
        WorkflowSignal::Start,
    ))
    .await?;
    Ok(Some(execution_id))
}

