fn external_channel_static_page_source_ref_string(
    source_refs: &Value,
    key: &str,
) -> Option<String> {
    source_refs
        .get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn external_channel_static_page_source_refs_string_array(
    source_refs: &Value,
    key: &str,
) -> Vec<String> {
    source_refs
        .get(key)
        .map(|value| external_string_ids_from_payload_value(value.clone()))
        .unwrap_or_default()
}

fn external_channel_static_page_template_from_source_refs(
    source_refs: &Value,
) -> Option<ExternalArtifactTemplateView> {
    source_refs
        .get("artifact_template")
        .or_else(|| source_refs.get("template"))
        .filter(|value| !value.is_null())
        .and_then(|value| serde_json::from_value(value.clone()).ok())
}

fn external_channel_static_page_message_from_source_refs(
    source_refs: &Value,
    connection: &ExternalChannelConnectionSummary,
    run: &AssistantRun,
) -> ExternalBotMessageView {
    ExternalBotMessageView {
        platform: connection.platform.clone(),
        tenant_external_id: external_channel_static_page_source_ref_string(
            source_refs,
            "tenant_external_id",
        )
        .unwrap_or_else(|| "external-tenant".to_string()),
        bot_external_id: external_channel_static_page_source_ref_string(
            source_refs,
            "bot_external_id",
        )
        .unwrap_or_else(|| "v3".to_string()),
        conversation_external_id: external_channel_static_page_source_ref_string(
            source_refs,
            "conversation_external_id",
        )
        .unwrap_or_else(|| {
            run.local_thread_id
                .clone()
                .unwrap_or_else(|| run.id.to_string())
        }),
        thread_external_id: external_channel_static_page_source_ref_string(
            source_refs,
            "thread_external_id",
        ),
        sender_external_id: external_channel_static_page_source_ref_string(
            source_refs,
            "sender_external_id",
        )
        .unwrap_or_else(|| "external-user".to_string()),
        message_external_id: external_channel_static_page_source_ref_string(
            source_refs,
            "message_external_id",
        )
        .unwrap_or_else(|| run.id.to_string()),
        message_type: ExternalMessageTypeView::Text,
        text: Some(run.user_prompt.clone()),
        default_prompt: None,
        output_format: external_channel_static_page_source_ref_string(source_refs, "output_format")
            .or_else(|| Some("image_text".to_string())),
        render_mode: external_channel_static_page_source_ref_string(source_refs, "render_mode")
            .or_else(|| Some("artifact".to_string())),
        artifact_type: external_channel_static_page_source_ref_string(source_refs, "artifact_type")
            .or_else(|| Some("static_page".to_string())),
        template: external_channel_static_page_template_from_source_refs(source_refs),
        mention_external_user_ids: Vec::new(),
        attachment_refs: Vec::new(),
        business_datasource_ids: Vec::new(),
        available_document_external_ids: Vec::new(),
        available_document_source_id: external_channel_static_page_source_ref_string(
            source_refs,
            "available_document_source_id",
        ),
        dataset_external_id: external_channel_static_page_source_ref_string(
            source_refs,
            "dataset_external_id",
        ),
        dataset_external_ids: external_channel_static_page_source_refs_string_array(
            source_refs,
            "dataset_external_ids",
        ),
        requested_skills: Vec::new(),
        idempotency_key: format!("static-page-auto-publish:{}", run.id),
        received_at: run.created_at,
    }
}

async fn maybe_enqueue_external_static_page_publish_after_image_ready(
    storage: &PgStorage,
    workflow_catalog: &WorkflowCatalog,
    event_bus: &EventBus,
    tenant_id: TenantId,
    execution: &WorkflowExecution,
) -> std::result::Result<(), ApiError> {
    if execution.kind != WorkflowKind::StaticPageImageGeneration
        || execution.status != WorkflowStatus::Succeeded
    {
        return Ok(());
    }
    let Some(job_id) = workflow_context_uuid(&execution.context, "static_page_image_job_id")
        .map(StaticPageImageJobId)
    else {
        return Ok(());
    };
    let Some(job) = storage
        .static_page_image_jobs()
        .get_by_id(tenant_id, job_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(());
    };
    if job
        .preview_asset_key
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .is_none()
    {
        return Ok(());
    }
    let Some(draft) = storage
        .static_page_drafts()
        .get_by_id(tenant_id, job.draft_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(());
    };
    let source_kind = draft.source_refs.get("source").and_then(Value::as_str);
    if !draft
        .source_refs
        .get("auto_publish_generated_artifact")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return Ok(());
    }
    if !matches!(
        source_kind,
        Some("external_channel_static_page_artifact_request")
            | Some("local_chat_static_page_image2_pipeline")
    ) {
        return Ok(());
    }
    let Some(run) = storage
        .assistant_runs()
        .get_by_id(tenant_id, draft.assistant_run_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(());
    };
    let image_job_id = job.id.to_string();
    let gpt55_local_route = assistant_run_static_page_should_use_gpt_55_local_route(&run);
    let codex_visual_contract_publish_ready =
        external_channel_static_page_codex_auto_publish_readiness().ready;
    let already_queued = storage
        .assistant_runs()
        .list_events(tenant_id, run.id)
        .await
        .map_err(ApiError::from_storage)?
        .iter()
        .any(|event| {
            (event.event_name == "assistant_run.external_channel_static_page_publish_queued"
                && event.payload.get("image_job_id").and_then(Value::as_str)
                    == Some(image_job_id.as_str()))
                || (event.event_name
                    == "assistant_run.external_channel_static_page_publish_completed"
                    && event.payload.get("image_job_id").and_then(Value::as_str)
                        == Some(image_job_id.as_str())
                    && (!gpt55_local_route
                        || external_channel_static_page_publish_completed_event_is_final(event)))
        });
    if already_queued {
        return Ok(());
    }
    let state = AppState::new(
        storage.clone(),
        workflow_catalog.clone(),
        tenant_id,
        event_bus.clone(),
    );
    let image_job_view = to_static_page_image_job_view(job);
    let template_reference = draft
        .draft_payload
        .get("templateReference")
        .or_else(|| draft.draft_payload.pointer("/source/templateReference"));
    let evidence_summary = draft
        .draft_payload
        .get("templateEvidenceSummary")
        .or_else(|| {
            draft
                .draft_payload
                .pointer("/source/templateEvidenceSummary")
        })
        .cloned()
        .unwrap_or_else(|| static_page_template_evidence_summary(&run.evidence_state));
    let missing_evidence = draft
        .draft_payload
        .get("missingEvidence")
        .or_else(|| draft.draft_payload.pointer("/source/missingEvidence"))
        .cloned()
        .unwrap_or_else(|| json!({"status": "unknown"}));
    let mut publish_template_payload = json!({
        "source_refs": draft.source_refs.clone(),
    });
    if let Some(reference) = template_reference {
        set_payload_value(
            &mut publish_template_payload,
            "template_reference",
            reference.clone(),
        );
    }
    let publish_template_reference_id =
        external_channel_static_page_template_reference_id_from_payload(&publish_template_payload);
    let publish_template_reference =
        external_channel_static_page_template_reference_from_payload(&publish_template_payload);
    let publish_template_match_policy =
        external_channel_static_page_template_match_policy_from_payload(&publish_template_payload);
    let publish_relaxed_template_match =
        external_channel_static_page_relaxed_template_match_from_payload(&publish_template_payload);
    let publish_style_reuse_policy =
        external_channel_static_page_style_reuse_policy_from_payload(&publish_template_payload);
    let publish_data_refresh_policy =
        external_channel_static_page_data_refresh_policy_from_payload(&publish_template_payload);
    let publish_default_template_scope =
        external_channel_static_page_default_template_scope_from_payload(&publish_template_payload);

    if source_kind == Some("external_channel_static_page_artifact_request") {
        let Some(connection_id) = external_channel_static_page_source_ref_string(
            &draft.source_refs,
            "channel_connection_id",
        ) else {
            return Ok(());
        };
        let connection = match load_external_channel_connection(&state, &connection_id).await {
            Ok(connection) => connection,
            Err(error) => {
                tracing::warn!(
                    code = %error.payload.code,
                    connection_id,
                    "external static-page auto-publish skipped because channel connection was unavailable"
                );
                return Ok(());
            }
        };
        if connection.status != "enabled" {
            return Ok(());
        }
        let recipient_delivery = draft
            .source_refs
            .get("recipient_delivery")
            .cloned()
            .unwrap_or(Value::Null);
        let message = external_channel_static_page_message_from_source_refs(
            &draft.source_refs,
            &connection,
            &run,
        );
        if !codex_visual_contract_publish_ready {
            storage
                .assistant_runs()
                .append_event(
                    tenant_id,
                    run.id,
                    &NewAssistantRunEvent {
                        event_name: "assistant_run.external_channel_static_page_publish_failed"
                            .to_string(),
                        payload: json!({
                            "source": source_kind,
                            "channel_connection_id": connection_id,
                            "draft_id": draft.id,
                            "image_job_id": image_job_view.id,
                            "preview_asset_key": image_job_view.preview_asset_key,
                            "template_id": "static_page_image2_data_publish",
                            "status": "static_page_publish_failed",
                            "publish_mode": "new_generated_artifact_only",
                            "final_publish_route": if gpt55_local_route {
                                "gpt_5_5_image2_codex_publish"
                            } else {
                                "cloudflare_codex"
                            },
                            "gpt_5_5_main_model_preferred": gpt55_local_route,
                            "cloudflare_codex_used": false,
                            "effect_image_confirmation_required": false,
                            "retryable": true,
                            "error": {
                                "code": "static_page_image2_publish_not_ready",
                                "message": "Image2 preview is ready, but the visual-contract static-page publisher is not ready; final dynamic website was not published."
                            },
                            "status_url": external_channel_assistant_run_reply_status_url(
                                &connection_id,
                                run.id,
                            ),
                            "status_method": "GET",
                            "recipient_delivery": recipient_delivery.clone(),
                            "template_reference_id": publish_template_reference_id.clone(),
                            "template_reference": publish_template_reference.clone(),
                            "template_match_policy": publish_template_match_policy.clone(),
                            "relaxed_template_match": publish_relaxed_template_match.clone(),
                            "style_reuse_policy": publish_style_reuse_policy.clone(),
                            "data_refresh_policy": publish_data_refresh_policy.clone(),
                            "default_template_scope": publish_default_template_scope.clone(),
                        }),
                        created_at: Utc::now(),
                    },
                )
                .await
                .map_err(ApiError::from_storage)?;
            return Ok(());
        }
        let codex_execution_id = external_channel_static_page_image2_enqueue_if_enabled(
            &state,
            &connection_id,
            &connection,
            &run,
            &draft,
            &image_job_view,
            &message,
            template_reference,
            &evidence_summary,
            &missing_evidence,
        )
        .await?;
        if let Some(codex_execution_id) = codex_execution_id {
            storage
                .assistant_runs()
                .append_event(
                    tenant_id,
                    run.id,
                    &NewAssistantRunEvent {
                        event_name: "assistant_run.external_channel_static_page_publish_queued"
                            .to_string(),
                        payload: json!({
                            "source": source_kind,
                            "channel_connection_id": connection_id,
                            "draft_id": draft.id,
                            "image_job_id": image_job_view.id,
                            "preview_asset_key": image_job_view.preview_asset_key,
                            "codex_host_workflow_execution_id": codex_execution_id,
                            "template_id": "static_page_image2_data_publish",
                            "publish_mode": "new_generated_artifact_only",
                            "final_publish_route": if gpt55_local_route {
                                "gpt_5_5_image2_codex_publish"
                            } else {
                                "cloudflare_codex"
                            },
                            "gpt_5_5_main_model_preferred": gpt55_local_route,
                            "gpt_5_5_local_publish_after_preview": false,
                            "cloudflare_codex_used": true,
                            "effect_image_confirmation_required": false,
                            "recipient_delivery": recipient_delivery.clone(),
                            "permission_review_status": recipient_delivery
                                .get("permission_review_status")
                                .cloned()
                                .unwrap_or(Value::Null),
                            "editable_after_publish": recipient_delivery
                                .get("editable_after_publish")
                                .cloned()
                                .unwrap_or(Value::Null),
                            "status_url": external_channel_assistant_run_reply_status_url(
                                &connection_id,
                                run.id,
                            ),
                            "status_method": "GET",
                            "poll_after_seconds": 15,
                            "template_reference_id": publish_template_reference_id.clone(),
                            "template_reference": publish_template_reference.clone(),
                            "template_match_policy": publish_template_match_policy.clone(),
                            "relaxed_template_match": publish_relaxed_template_match.clone(),
                            "style_reuse_policy": publish_style_reuse_policy.clone(),
                            "data_refresh_policy": publish_data_refresh_policy.clone(),
                            "default_template_scope": publish_default_template_scope.clone(),
                        }),
                        created_at: Utc::now(),
                    },
                )
                .await
                .map_err(ApiError::from_storage)?;
        }
        return Ok(());
    }

    if !codex_visual_contract_publish_ready {
        storage
            .assistant_runs()
            .append_event(
                tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.main_static_page_publish_failed".to_string(),
                    payload: json!({
                        "source": source_kind,
                        "model_route": if gpt55_local_route {
                            "gpt_5_5_image2_codex_publish"
                        } else {
                            "cloudflare_codex"
                        },
                        "cloudflare_codex_used": false,
                        "fallback_available": false,
                        "local_thread_id": run.local_thread_id,
                        "draft_id": draft.id,
                        "image_job_id": image_job_view.id,
                        "preview_asset_key": image_job_view.preview_asset_key,
                        "template_id": "static_page_image2_data_publish",
                        "publish_mode": "new_generated_artifact_only",
                        "error": {
                            "code": "static_page_image2_publish_not_ready",
                            "message": "Image2 preview is ready, but the visual-contract static-page publisher is not ready; final dynamic website was not published."
                        },
                        "effect_image_confirmation_required": false,
                        "template_reference_id": publish_template_reference_id.clone(),
                        "template_reference": publish_template_reference.clone(),
                        "template_match_policy": publish_template_match_policy.clone(),
                        "relaxed_template_match": publish_relaxed_template_match.clone(),
                        "style_reuse_policy": publish_style_reuse_policy.clone(),
                        "data_refresh_policy": publish_data_refresh_policy.clone(),
                        "default_template_scope": publish_default_template_scope.clone(),
                    }),
                    created_at: Utc::now(),
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        return Ok(());
    }

    let codex_execution_id = assistant_run_static_page_image2_enqueue_if_enabled(
        &state,
        &run,
        &draft,
        &image_job_view,
        template_reference,
        &evidence_summary,
        &missing_evidence,
    )
    .await?;
    if let Some(codex_execution_id) = codex_execution_id {
        mark_static_page_draft_generated_artifact_publish_queued(
            storage,
            tenant_id,
            &draft,
            Some(image_job_id.as_str()),
            codex_execution_id,
        )
        .await?;
        storage
            .assistant_runs()
            .append_event(
                tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.external_channel_static_page_publish_queued"
                        .to_string(),
                    payload: json!({
                        "source": source_kind,
                        "local_thread_id": run.local_thread_id,
                        "draft_id": draft.id,
                        "image_job_id": image_job_view.id,
                        "preview_asset_key": image_job_view.preview_asset_key,
                        "codex_host_workflow_execution_id": codex_execution_id,
                        "template_id": "static_page_image2_data_publish",
                        "publish_mode": "new_generated_artifact_only",
                        "final_publish_route": if gpt55_local_route {
                            "gpt_5_5_image2_codex_publish"
                        } else {
                            "cloudflare_codex"
                        },
                        "gpt_5_5_main_model_preferred": gpt55_local_route,
                        "gpt_5_5_local_publish_after_preview": false,
                        "cloudflare_codex_used": true,
                        "effect_image_confirmation_required": false,
                        "status_method": "GET",
                        "poll_after_seconds": 15,
                        "template_reference_id": publish_template_reference_id.clone(),
                        "template_reference": publish_template_reference.clone(),
                        "template_match_policy": publish_template_match_policy.clone(),
                        "relaxed_template_match": publish_relaxed_template_match.clone(),
                        "style_reuse_policy": publish_style_reuse_policy.clone(),
                        "data_refresh_policy": publish_data_refresh_policy.clone(),
                        "default_template_scope": publish_default_template_scope.clone(),
                    }),
                    created_at: Utc::now(),
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
    }

    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn maybe_enqueue_external_channel_static_page_pipeline(
    state: &AppState,
    connection_id: &str,
    connection: &ExternalChannelConnectionSummary,
    run: &AssistantRun,
    assistant_request: &CreateAssistantRunRequest,
    message: &ExternalBotMessageView,
    now: DateTime<Utc>,
) -> std::result::Result<Option<ExternalBotReplyView>, ApiError> {
    if !external_channel_message_requests_static_page_artifact(message, &assistant_request.prompt) {
        return Ok(None);
    }

    let recipient_delivery =
        external_channel_static_page_recipient_delivery(message, &assistant_request.prompt);
    let selected_scope = assistant_request
        .selected_scope
        .clone()
        .unwrap_or_else(|| run.selected_scope.clone());
    let mut template_reference_id =
        external_channel_static_page_template_reference_id(message, &assistant_request.prompt);
    let template_stability_key =
        external_channel_static_page_template_stability_key(message, &assistant_request.prompt);
    let mut source_refs = json!({
        "source": "external_channel_static_page_artifact_request",
        "auto_publish_generated_artifact": true,
        "effect_image_confirmation_required": false,
        "continue_to_publish_after_effect_image": true,
        "channel_connection_id": connection_id,
        "platform": external_channel_platform_wire_value(&message.platform),
        "tenant_external_id": message.tenant_external_id,
        "bot_external_id": message.bot_external_id,
        "conversation_external_id": message.conversation_external_id,
        "thread_external_id": message.thread_external_id,
        "sender_external_id": message.sender_external_id,
        "message_external_id": message.message_external_id,
        "message_type": external_message_type_wire_value(&message.message_type),
        "artifact_type": message.artifact_type,
        "artifact_template": message.template.as_ref().map(external_artifact_template_summary),
        "output_format": message.output_format,
        "render_mode": message.render_mode,
        "requested_skills": external_requested_skills_summary(&message.requested_skills),
        "database_source_ids": collect_external_static_page_database_source_ids(
            connection,
            &run.selected_scope,
            &run.evidence_state,
        ),
        "recipient_delivery": recipient_delivery.clone(),
        "answer_policy": external_answer_policy_value(message),
    });
    let dataset_artifact_key = static_page_dataset_artifact_key(
        &selected_scope,
        &source_refs,
        &template_stability_key,
        Some(connection_id),
    );
    source_refs = apply_static_page_artifact_stability_to_source_refs(
        source_refs,
        dataset_artifact_key.as_deref(),
        "candidate",
        None,
        now,
    );
    if let Some(dataset_artifact_key) = dataset_artifact_key.as_deref() {
        if static_page_prompt_allows_stable_artifact_reuse(&assistant_request.prompt) {
            if let Some(baseline_draft) = state
                .storage
                .static_page_drafts()
                .find_latest_accepted_baseline_by_artifact_key(
                    state.tenant_id,
                    dataset_artifact_key,
                )
                .await
                .map_err(ApiError::from_storage)?
            {
                if let Some(public_url) =
                    static_page_published_public_url_from_draft(&baseline_draft)
                {
                    let baseline_template_payload = json!({
                        "status": "static_page_stable_artifact_reused",
                        "source_refs": baseline_draft.source_refs.clone(),
                    });
                    let baseline_template_reference_id =
                        external_channel_static_page_template_reference_id_from_payload(
                            &baseline_template_payload,
                        );
                    let baseline_template_reference =
                        external_channel_static_page_template_reference_from_payload(
                            &baseline_template_payload,
                        );
                    let baseline_style_reuse_policy =
                        external_channel_static_page_style_reuse_policy_from_payload(
                            &baseline_template_payload,
                        );
                    let baseline_data_refresh_policy =
                        external_channel_static_page_data_refresh_policy_from_payload(
                            &baseline_template_payload,
                        );
                    let baseline_default_template_scope =
                        external_channel_static_page_default_template_scope_from_payload(
                            &baseline_template_payload,
                        );
                    let event_payload = json!({
                        "type": "v3_static_page_stable_artifact",
                        "status": "static_page_stable_artifact_reused",
                        "channel_connection_id": connection_id,
                        "platform": external_channel_platform_wire_value(&message.platform),
                        "conversation_external_id": message.conversation_external_id,
                        "message_external_id": message.message_external_id,
                        "draft_id": baseline_draft.id,
                        "baseline_draft_id": baseline_draft.id,
                        "baseline_assistant_run_id": baseline_draft.assistant_run_id,
                        "dataset_artifact_key": dataset_artifact_key,
                        "baseline_status": "accepted",
                        "public_url": public_url,
                        "generated_artifact_url": public_url,
                        "artifact_links": [public_url],
                        "image2_skipped": true,
                        "image2_skip_reason": "accepted_dataset_artifact_baseline",
                        "edit_mode": "incremental_existing_artifact",
                        "reuse_policy": "reuse_accepted_baseline_unless_explicit_redesign",
                        "template_reference_id": baseline_template_reference_id,
                        "template_reference": baseline_template_reference,
                        "template_match_policy": "exact_dataset_artifact_key",
                        "relaxed_template_match": Value::Null,
                        "style_reuse_policy": baseline_style_reuse_policy,
                        "data_refresh_policy": baseline_data_refresh_policy,
                        "default_template_scope": baseline_default_template_scope,
                        "status_url": external_channel_assistant_run_reply_status_url(
                            connection_id,
                            run.id,
                        ),
                        "status_method": "GET",
                        "poll_after_seconds": Value::Null,
                        "recipient_delivery": recipient_delivery.clone(),
                        "permission_review_status": recipient_delivery
                            .get("permission_review_status")
                            .cloned()
                            .unwrap_or(Value::Null),
                        "editable_after_publish": recipient_delivery
                            .get("editable_after_publish")
                            .cloned()
                            .unwrap_or(Value::Null),
                        "source_refs": source_refs.clone(),
                    });
                    state
                        .storage
                        .assistant_runs()
                        .append_event(
                            state.tenant_id,
                            run.id,
                            &NewAssistantRunEvent {
                                event_name:
                                    "assistant_run.external_channel_static_page_stable_artifact_reused"
                                        .to_string(),
                                payload: event_payload.clone(),
                                created_at: now,
                            },
                        )
                        .await
                        .map_err(ApiError::from_storage)?;
                    return Ok(Some(
                        external_channel_static_page_stable_artifact_reused_reply(
                            &message.conversation_external_id,
                            &event_payload,
                        ),
                    ));
                }
            }
        }
    }
    if !static_page_prompt_requests_explicit_redesign(&assistant_request.prompt)
        && template_reference_id
            .as_deref()
            .and_then(|value| static_page_generated_template_draft_id(Some(value)))
            .is_none()
    {
        if let Some(template_draft) = find_static_page_template_baseline_by_dataset_overlap(
            state,
            &selected_scope,
            &source_refs,
            None,
            Some(connection_id),
        )
        .await?
        {
            if let Some(template_public_url) =
                static_page_published_public_url_from_draft(&template_draft)
            {
                let template_reference = static_page_generated_template_reference_from_draft(
                    &template_draft,
                    &template_public_url,
                );
                let generated_template_reference_id =
                    static_page_generated_template_reference_id(template_draft.id);
                template_reference_id = Some(generated_template_reference_id.clone());
                source_refs = apply_static_page_template_reference_value_to_source_refs(
                    source_refs,
                    &template_reference,
                );
                set_payload_value(
                    &mut source_refs,
                    "relaxed_template_match",
                    json!({
                        "policy": "dataset_overlap",
                        "template_reference_id": generated_template_reference_id,
                        "baseline_draft_id": template_draft.id,
                        "baseline_assistant_run_id": template_draft.assistant_run_id,
                        "baseline_public_url": template_public_url.as_str(),
                        "reason": "dataset_scope_intersects_existing_template_baseline",
                    }),
                );
                state
                    .storage
                    .assistant_runs()
                    .append_event(
                        state.tenant_id,
                        run.id,
                        &NewAssistantRunEvent {
                            event_name:
                                "assistant_run.external_channel_static_page_relaxed_template_matched"
                                    .to_string(),
                            payload: json!({
                                "policy": "dataset_overlap",
                                "template_reference_id": template_reference_id.as_deref(),
                                "baseline_draft_id": template_draft.id,
                                "baseline_assistant_run_id": template_draft.assistant_run_id,
                                "baseline_public_url": template_public_url.as_str(),
                            }),
                            created_at: now,
                        },
                    )
                    .await
                    .map_err(ApiError::from_storage)?;
            }
        }
    }
    let draft_outcome = create_static_page_draft_for_assistant_run_id(
        state,
        run.id,
        None,
        CreateStaticPageDraftRequest {
            title: None,
            prompt: Some(assistant_request.prompt.clone()),
            template_reference_id,
            selected_scope: Some(selected_scope),
            visibility_snapshot: None,
            source_refs,
            draft_payload: Value::Null,
        },
    )
    .await?;
    let mut template_observability_payload = json!({
        "source_refs": draft_outcome.draft.source_refs.clone(),
    });
    if let Some(reference) = draft_outcome.template_reference.as_ref() {
        set_payload_value(
            &mut template_observability_payload,
            "template_reference",
            reference.clone(),
        );
    }
    let draft_template_reference_id =
        external_channel_static_page_template_reference_id_from_payload(
            &template_observability_payload,
        );
    let draft_template_reference = external_channel_static_page_template_reference_from_payload(
        &template_observability_payload,
    );
    let draft_relaxed_template_match =
        external_channel_static_page_relaxed_template_match_from_payload(
            &template_observability_payload,
        );
    let draft_template_match_policy =
        external_channel_static_page_template_match_policy_from_payload(
            &template_observability_payload,
        );
    let draft_style_reuse_policy = external_channel_static_page_style_reuse_policy_from_payload(
        &template_observability_payload,
    );
    let draft_data_refresh_policy = external_channel_static_page_data_refresh_policy_from_payload(
        &template_observability_payload,
    );
    let draft_default_template_scope =
        external_channel_static_page_default_template_scope_from_payload(
            &template_observability_payload,
        );
    let image_prompt_payload = build_static_page_image_prompt_payload(
        &draft_outcome.draft,
        Some(&assistant_request.prompt),
    );
    let (_status, Json(image_response)) = create_static_page_image_job_for_draft(
        state,
        draft_outcome.draft.clone(),
        CreateStaticPageImageJobRequest {
            prompt: Some(assistant_request.prompt.clone()),
            image_prompt_payload,
        },
    )
    .await?;
    let codex_auto_publish_readiness = external_channel_static_page_codex_auto_publish_readiness();
    let gpt55_main_model_preferred = assistant_run_static_page_should_use_gpt_55_local_route(run);
    let codex_auto_publish_enabled = codex_auto_publish_readiness.ready;
    let gpt55_local_publish_after_preview = false;
    let auto_publish_after_preview = codex_auto_publish_enabled;
    let final_publish_route = if codex_auto_publish_enabled && gpt55_main_model_preferred {
        "gpt_5_5_image2_codex_publish"
    } else if codex_auto_publish_enabled {
        "cloudflare_codex"
    } else {
        "image2_preview_waiting_for_publish_config"
    };
    let create_direct_render_now = false;
    let direct_render_result = if create_direct_render_now {
        let result =
            create_static_page_render_output_inline(state, draft_outcome.draft.clone(), None, true)
                .await?;
        Some(result)
    } else {
        None
    };
    let direct_render_output = direct_render_result.as_ref().map(|(_draft, output)| output);
    let generated_artifact_payload: Option<Value> = None;
    let generated_artifact_url = generated_artifact_payload
        .as_ref()
        .and_then(|payload| payload.get("public_url"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let status_url = external_channel_assistant_run_reply_status_url(connection_id, run.id);
    let poll_after_seconds = if auto_publish_after_preview
        && (generated_artifact_url.is_some() || direct_render_output.is_some())
    {
        Value::from(15)
    } else if generated_artifact_url.is_none() && direct_render_output.is_none() {
        Value::from(15)
    } else {
        Value::Null
    };

    state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run.id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.external_channel_static_page_pipeline_queued"
                    .to_string(),
                payload: json!({
                    "channel_connection_id": connection_id,
                    "platform": external_channel_platform_wire_value(&message.platform),
                    "message_external_id": message.message_external_id,
                    "draft_id": draft_outcome.draft.id,
                    "image_job_id": image_response.image_job.id,
                    "render_output_id": direct_render_output
                        .map(|output| json!(output.id))
                        .unwrap_or(Value::Null),
                    "render_output_status": direct_render_output
                        .map(|output| json!(output.status))
                        .unwrap_or(Value::Null),
                    "html_preview_url": direct_render_output
                        .and_then(|output| output.html_preview_url.clone())
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                    "html_download_url": direct_render_output
                        .and_then(|output| output.html_download_url.clone())
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                    "public_url": generated_artifact_url
                        .as_ref()
                        .map(|value| Value::String(value.clone()))
                        .unwrap_or(Value::Null),
                    "status_url": status_url.clone(),
                    "status_method": "GET",
                    "poll_after_seconds": poll_after_seconds.clone(),
                    "recipient_delivery": recipient_delivery.clone(),
                    "permission_review_status": recipient_delivery
                        .get("permission_review_status")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "editable_after_publish": recipient_delivery
                        .get("editable_after_publish")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "codex_host_workflow_execution_id": Value::Null,
                    "template_id": if codex_auto_publish_enabled {
                        Value::String("static_page_image2_data_publish".to_string())
                    } else {
                        Value::Null
                    },
                    "auto_publish_after_preview": auto_publish_after_preview,
                    "final_publish_route": final_publish_route,
                    "gpt_5_5_main_model_preferred": gpt55_main_model_preferred,
                    "gpt_5_5_local_publish_after_preview": gpt55_local_publish_after_preview,
                    "codex_auto_publish_ready": codex_auto_publish_enabled,
                    "codex_auto_publish_disabled_reason": if codex_auto_publish_enabled {
                        Value::Null
                    } else {
                        Value::String(codex_auto_publish_readiness.reason.to_string())
                    },
                    "direct_html_fallback": direct_render_output.is_some(),
                    "provisional_direct_html": auto_publish_after_preview && direct_render_output.is_some(),
                    "demo_generated_artifact_publish": generated_artifact_url.is_some(),
                    "codex_final_status": if codex_auto_publish_enabled {
                        Value::String("static_page_image2_auto_publish_pending".to_string())
                    } else {
                        Value::Null
                    },
                    "template_reference_id": draft_template_reference_id.clone(),
                    "template_reference": draft_template_reference.clone(),
                    "template_match_policy": draft_template_match_policy.clone(),
                    "relaxed_template_match": draft_relaxed_template_match.clone(),
                    "style_reuse_policy": draft_style_reuse_policy.clone(),
                    "data_refresh_policy": draft_data_refresh_policy.clone(),
                    "default_template_scope": draft_default_template_scope.clone(),
                    "effect_image_confirmation_required": false,
                }),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    let task_status = if generated_artifact_url.is_some() {
        "static_page_published"
    } else if direct_render_output.is_some() {
        "static_page_rendered"
    } else if codex_auto_publish_enabled {
        "static_page_image2_auto_publish_pending"
    } else {
        "static_page_image_preview_queued"
    };
    let text = if generated_artifact_url.is_some() {
        "V3 静态页已生成并发布，可通过 artifact_links[0] 打开页面。".to_string()
    } else if codex_auto_publish_enabled && gpt55_main_model_preferred {
        "已创建静态页草稿并提交 GPT-Image-2 效果图队列；效果图无需客户确认，生成后会继续进入 Image2 视觉合同发布链路，由 GPT-5.5/Codex 依据效果图生成最终动态网站。".to_string()
    } else if codex_auto_publish_enabled {
        "已创建静态页草稿并提交 GPT-Image-2 效果图队列；效果图无需客户确认，生成后会继续进入 Image2 视觉合同发布链路生成最终动态网站。".to_string()
    } else {
        external_channel_static_page_pipeline_reply_text(
            codex_auto_publish_enabled,
            draft_outcome.template_reference.as_ref(),
        )
    };
    Ok(Some(ExternalBotReplyView {
        target_conversation_external_id: message.conversation_external_id.clone(),
        reply_type: ExternalBotReplyTypeView::TaskStatus,
        text: Some(text),
        card: Some(json!({
            "type": "v3_static_page_image2_pipeline",
            "status": task_status,
            "draft_id": draft_outcome.draft.id.to_string(),
            "image_job_id": image_response.image_job.id.to_string(),
            "image_job_status": image_response.image_job.status,
            "render_output_id": direct_render_output
                .map(|output| json!(output.id))
                .unwrap_or(Value::Null),
            "render_output_status": direct_render_output
                .map(|output| json!(output.status))
                .unwrap_or(Value::Null),
            "html_preview_url": direct_render_output
                .and_then(|output| output.html_preview_url.clone())
                .map(Value::String)
                .unwrap_or(Value::Null),
            "html_download_url": direct_render_output
                .and_then(|output| output.html_download_url.clone())
                .map(Value::String)
                .unwrap_or(Value::Null),
            "download_url": direct_render_output
                .and_then(|output| output.download_url.clone())
                .map(Value::String)
                .unwrap_or(Value::Null),
            "public_url": generated_artifact_url
                .as_ref()
                .map(|value| Value::String(value.clone()))
                .unwrap_or(Value::Null),
            "generated_artifact_url": generated_artifact_url
                .as_ref()
                .map(|value| Value::String(value.clone()))
                .unwrap_or(Value::Null),
            "status_url": status_url.clone(),
            "status_method": "GET",
            "poll_after_seconds": poll_after_seconds.clone(),
            "recipient_delivery": recipient_delivery.clone(),
            "permission_review_status": recipient_delivery
                .get("permission_review_status")
                .cloned()
                .unwrap_or(Value::Null),
            "editable_after_publish": recipient_delivery
                .get("editable_after_publish")
                .cloned()
                .unwrap_or(Value::Null),
            "codex_host_workflow_execution_id": Value::Null,
            "fixed_task_template_id": if codex_auto_publish_enabled {
                Value::String("static_page_image2_data_publish".to_string())
            } else {
                Value::Null
            },
            "auto_publish_after_preview": auto_publish_after_preview,
            "final_publish_route": final_publish_route,
            "gpt_5_5_main_model_preferred": gpt55_main_model_preferred,
            "gpt_5_5_local_publish_after_preview": gpt55_local_publish_after_preview,
            "codex_auto_publish_ready": codex_auto_publish_enabled,
            "codex_auto_publish_disabled_reason": if codex_auto_publish_enabled {
                Value::Null
            } else {
                Value::String(codex_auto_publish_readiness.reason.to_string())
            },
            "direct_html_fallback": direct_render_output.is_some(),
            "provisional_direct_html": auto_publish_after_preview && direct_render_output.is_some(),
            "demo_generated_artifact_publish": generated_artifact_url.is_some(),
            "codex_final_status": if codex_auto_publish_enabled {
                Value::String("static_page_image2_auto_publish_pending".to_string())
            } else {
                Value::Null
            },
            "template_reference_id": draft_template_reference_id,
            "template_reference": draft_template_reference,
            "template_match_policy": draft_template_match_policy,
            "relaxed_template_match": draft_relaxed_template_match,
            "style_reuse_policy": draft_style_reuse_policy,
            "data_refresh_policy": draft_data_refresh_policy,
            "default_template_scope": draft_default_template_scope,
            "effect_image_confirmation_required": false,
            "publish_mode": "new_generated_artifact_only",
        })),
        artifact_links: generated_artifact_url.clone().into_iter().collect(),
        task_status: Some(external_channel_public_task_status(task_status).to_string()),
        requires_confirmation: false,
        action_id: None,
        confirmation_id: None,
    }))
}

fn external_channel_generated_artifact_root() -> std::result::Result<PathBuf, ApiError> {
    let root = std::env::var("V3_GENERATED_ARTIFACT_ROOT")
        .ok()
        .map(|value| PathBuf::from(value.trim()))
        .filter(|path| path.is_absolute())
        .unwrap_or_else(|| {
            external_document_object_root()
                .unwrap_or_else(|_| std::env::temp_dir().join("ai-data-platform-v3-objects"))
                .join("generated-artifacts")
        });
    fs::create_dir_all(&root).map_err(|error| {
        ApiError::internal(
            "static_page_generated_artifact_publish_failed",
            format!("failed to create generated artifact root: {error}"),
        )
    })?;
    Ok(root)
}

