async fn create_static_page_image_job_for_draft(
    state: &AppState,
    mut draft: StaticPageDraft,
    request: CreateStaticPageImageJobRequest,
) -> std::result::Result<(StatusCode, Json<CreateStaticPageImageJobResponse>), ApiError> {
    let mut request_image_prompt_payload = request.image_prompt_payload;
    let prompt_only_preview =
        static_page_image_prompt_payload_is_prompt_only(&request_image_prompt_payload);
    if !prompt_only_preview {
        draft = refresh_static_page_draft_data_contract_for_action(
            state,
            draft,
            "submit_static_page_image_preview",
        )
        .await?;
        let enforce_preview_data_quality_gate =
            static_page_draft_requires_preview_data_quality_gate(&draft);
        if enforce_preview_data_quality_gate {
            if let Some((reason, details)) = static_page_preview_data_quality_gate_for_draft(&draft)
            {
                return Err(ApiError::bad_request_with_details(
                    "static_page_preview_data_quality_gate",
                    reason,
                    details,
                ));
            }
        }
        if !request_image_prompt_payload.is_null() {
            refresh_static_page_payload_with_draft_context(
                &mut request_image_prompt_payload,
                &draft,
            );
            if enforce_preview_data_quality_gate {
                if let Some((reason, details)) =
                    static_page_preview_data_quality_gate_for_payload(&request_image_prompt_payload)
                {
                    return Err(ApiError::bad_request_with_details(
                        "static_page_preview_data_quality_gate",
                        reason,
                        details,
                    ));
                }
            }
        }
    }

    let image_prompt_payload = if request_image_prompt_payload.is_null() {
        build_static_page_image_prompt_payload(&draft, request.prompt.as_deref())
    } else {
        request_image_prompt_payload
    };
    let job = state
        .storage
        .static_page_image_jobs()
        .create(
            state.tenant_id,
            &NewStaticPageImageJob {
                draft_id: draft.id,
                assistant_run_id: draft.assistant_run_id,
                status: StaticPageImageJobStatus::Queued,
                queue_position: Some(1),
                image_prompt_payload,
                preview_asset_key: None,
                failure_reason: None,
                confirmed_at: None,
                created_at: Utc::now(),
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    let workflow_execution = build_initial_static_page_image_generation_execution(
        state,
        &draft,
        &job,
        request.prompt.as_deref(),
    )?;
    let initial_event =
        build_initial_static_page_image_generation_event(&workflow_execution, &draft, &job);
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&workflow_execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal_with_dependencies(
        &state.storage,
        &state.workflow_catalog,
        &state.event_bus,
        state.tenant_id,
        workflow_execution.id,
        WorkflowSignal::Start,
    )
    .await?;
    let operations = vec![json!({
        "type": "queue_image_job",
        "jobId": job.id,
        "queuePosition": job.queue_position,
        "queueMessage": "资源正在排队，可以联系商务开通高级用户跳过等待。",
    })];
    draft.draft_payload = apply_static_page_operations_to_payload(
        draft.draft_payload,
        &operations,
        Some("效果图任务已进入资源队列。"),
    );
    append_static_page_operations_metadata(
        &mut draft.draft_payload,
        &operations,
        request.prompt.as_deref(),
        "效果图任务已进入资源队列。",
    );
    draft.status = StaticPageDraftStatus::Queued;
    let draft = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &draft,
        "static_page_image_job.created",
        json!({
            "draft_id": draft.id,
            "image_job_id": job.id,
            "status": job.status.as_str(),
            "queue_position": job.queue_position,
            "workflow_execution_id": workflow_execution.id,
            "workflow_task_id": started.enqueued_tasks.first().map(|task| task.id),
        }),
    )
    .await?;

    Ok((
        StatusCode::CREATED,
        Json(CreateStaticPageImageJobResponse {
            image_job: to_static_page_image_job_view(job),
        }),
    ))
}

