async fn create_static_page_render_for_draft(
    state: &AppState,
    mut draft: StaticPageDraft,
    request: CreateStaticPageRenderRequest,
) -> std::result::Result<(StatusCode, Json<CreateStaticPageRenderResponse>), ApiError> {
    draft = refresh_static_page_draft_data_contract_for_action(state, draft, "render_static_page")
        .await?;
    let image_job = if request.direct_html {
        None
    } else {
        let image_job =
            resolve_static_page_render_image_job(state, &draft, request.image_job_id).await?;
        ensure_static_page_preview_contract_current(&draft, image_job.as_ref())?;
        image_job
    };
    if static_page_draft_requires_final_render_data_quality_gate(&draft) {
        if let Some((reason, details)) =
            static_page_final_render_data_quality_gate_for_draft(&draft)
        {
            return Err(ApiError::bad_request_with_details(
                "static_page_final_render_data_quality_gate",
                reason,
                details,
            ));
        }
    }
    if request.background {
        let mut render_output = state
            .storage
            .static_page_render_outputs()
            .create(
                state.tenant_id,
                &NewStaticPageRenderOutput {
                    draft_id: draft.id,
                    assistant_run_id: draft.assistant_run_id,
                    owner_user_id: draft.owner_user_id,
                    image_job_id: image_job.as_ref().map(|job| job.id),
                    status: StaticPageRenderOutputStatus::Queued,
                    html: String::new(),
                    asset_manifest: build_static_page_render_queue_manifest(
                        &draft,
                        image_job.as_ref(),
                        None,
                        None,
                    ),
                    created_at: Utc::now(),
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        let workflow_execution = build_initial_static_page_render_execution(
            state,
            &draft,
            &render_output,
            image_job.as_ref(),
        )?;
        let initial_event =
            build_initial_static_page_render_event(&workflow_execution, &draft, &render_output);
        state
            .storage
            .workflow_executions()
            .create_with_initial_event(&workflow_execution, &initial_event)
            .await
            .map_err(ApiError::from_storage)?;
        let started = apply_workflow_signal_with_dependencies(
            &state.storage,
            &state.workflow_catalog,
            &state.event_bus,
            state.tenant_id,
            workflow_execution.id,
            WorkflowSignal::Start,
        )
        .await?;
        let started_execution = state
            .storage
            .workflow_executions()
            .get_by_id(state.tenant_id, workflow_execution.id)
            .await
            .map_err(ApiError::from_storage)?
            .ok_or_else(|| {
                ApiError::internal(
                    "workflow_execution_missing_after_start",
                    format!(
                        "workflow execution {} was missing after start",
                        workflow_execution.id
                    ),
                )
            })?;
        render_output.status = static_page_render_output_status_for_workflow(
            &started_execution.status,
            &render_output.status,
        );
        let queue_manifest = build_static_page_render_queue_manifest(
            &draft,
            image_job.as_ref(),
            Some(&started_execution),
            started.enqueued_tasks.first().map(|task| task.id),
        );
        render_output.asset_manifest =
            merge_static_page_render_output_workflow_manifest(&queue_manifest, &started_execution);
        render_output = state
            .storage
            .static_page_render_outputs()
            .update(state.tenant_id, &render_output)
            .await
            .map_err(ApiError::from_storage)?;
        append_static_page_draft_run_event(
            state,
            &draft,
            "static_page_render.queued",
            json!({
                "draft_id": draft.id,
                "render_output_id": render_output.id,
                "image_job_id": render_output.image_job_id,
                "workflow_execution_id": workflow_execution.id,
                "workflow_task_id": started.enqueued_tasks.first().map(|task| task.id),
            }),
        )
        .await?;

        return Ok((
            StatusCode::CREATED,
            Json(CreateStaticPageRenderResponse {
                render_output: to_static_page_render_output_view(
                    render_output,
                    Some(&draft.selected_scope),
                ),
                draft: to_static_page_draft_view(draft),
            }),
        ));
    }

    let rendered = render_static_page(&StaticPageRenderRequest {
        draft_id: draft.id.to_string(),
        assistant_run_id: draft.assistant_run_id.to_string(),
        title: draft.title.clone(),
        draft_payload: draft.draft_payload.clone(),
        selected_scope: draft.selected_scope.clone(),
        visibility_snapshot: draft.visibility_snapshot.clone(),
        preview_asset_key: image_job
            .as_ref()
            .and_then(|job| job.preview_asset_key.clone()),
        image_job_id: image_job.as_ref().map(|job| job.id.to_string()),
    });
    let render_output = state
        .storage
        .static_page_render_outputs()
        .create(
            state.tenant_id,
            &NewStaticPageRenderOutput {
                draft_id: draft.id,
                assistant_run_id: draft.assistant_run_id,
                owner_user_id: draft.owner_user_id,
                image_job_id: image_job.as_ref().map(|job| job.id),
                status: StaticPageRenderOutputStatus::Rendered,
                html: rendered.html,
                asset_manifest: rendered.asset_manifest,
                created_at: Utc::now(),
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    let operations = vec![json!({
        "type": "request_final_render",
        "finalPage": {
            "status": "rendered",
            "renderOutputId": render_output.id,
            "assetManifest": render_output.asset_manifest,
            "directHtml": request.direct_html,
        }
    })];
    let render_summary = if request.direct_html {
        "最终静态页已按快速 HTML 交付模式生成，未经过效果图确认。"
    } else {
        "最终静态页已根据效果图和模块规划生成。"
    };
    draft.draft_payload = apply_static_page_operations_to_payload(
        draft.draft_payload,
        &operations,
        Some(render_summary),
    );
    append_static_page_operations_metadata(
        &mut draft.draft_payload,
        &operations,
        None,
        render_summary,
    );
    draft.status = StaticPageDraftStatus::Rendered;
    let draft = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &draft,
        "static_page_render.created",
        json!({
            "draft_id": draft.id,
            "render_output_id": render_output.id,
            "image_job_id": render_output.image_job_id,
        }),
    )
    .await?;

    Ok((
        StatusCode::CREATED,
        Json(CreateStaticPageRenderResponse {
            render_output: to_static_page_render_output_view(
                render_output,
                Some(&draft.selected_scope),
            ),
            draft: to_static_page_draft_view(draft),
        }),
    ))
}

