fn build_assistant_run_provider_input_with_evidence(
    request: &CreateAssistantRunRequest,
    evidence_state: Option<&Value>,
) -> String {
    let selected_scope = request.selected_scope.as_ref();
    let plain_ordinary_chat = assistant_run_is_plain_ordinary_chat_scope(
        selected_scope,
        evidence_state,
        request.current_artifact.as_ref(),
    );
    let mut sections = if plain_ordinary_chat {
        vec![
            "你是通用模型助手，运行在 AI 数据智能助手中。".to_string(),
            "当前未选择数据集，也没有供料证据；请按普通模型问答直接回答用户问题，可以使用你的通用知识、推理和表达能力，不要因为缺少数据集而拒答、降级或强行讨论数据工作台。".to_string(),
            "只有当用户明确询问本系统、数据集、文档、报表、静态页、上传或采集能力时，才结合产品背景说明系统能力。".to_string(),
        ]
    } else {
        vec![
            "你是 AI 数据智能助手里的模型回答运行时。".to_string(),
            "宿主只负责识别意图、提供上下文和执行受控动作；最终正文由你自行组织，不要按宿主规则拼模板化回答。".to_string(),
            "系统能力背景：可普通聊天、检索供料、读取文档细节、读取音视频转写/场景等媒体细节、创建报表、规划/渲染/修改静态页、导出静态页 ZIP 交付包。涉及供料中的数据、指标、文档事实或产物状态时，不要编造；普通常识和开放问答仍可使用模型通用能力。".to_string(),
        ]
    };
    if assistant_run_scope_is_external_channel(selected_scope) {
        sections.push(
            "外部通道直答合同：本次输出会同步返回给第三方用户，必须直接回答用户问题；禁止把“已收到/处理中/稍后为您分析/系统将结合知识库与数据源/为您输出结论”当作最终答案。若文档未解析、不可见或供料不足，请直接说明当前可见状态和下一步，而不是承诺稍后输出。"
                .to_string(),
        );
        sections.push(
            "外部通道供料表达要求：如果已经收到文档、检索切片、事实快照或会话范围供料，优先把相关证据整理成可执行结论、步骤、表格或清单；不要把“当前可见”“暂未直接检索到”“资料不足”“建议补充资料”放在答案开头。若供料只是相关章节而非专项原文，必须区分“文档明文规定”和“按相关章节/通用规范整理的可参考流程”，不要把推导或通用经验写成文档明文。只有完全没有相关供料、或确实只能确认文档未就绪/不可见时，才用缺资料说明，并给出最短下一步。"
                .to_string(),
        );
    }
    sections.extend(assistant_run_v3_awareness_lines());
    if let Some(answer_policy) = assistant_run_request_external_answer_policy(request) {
        sections.push(format!(
            "本轮外部回答要求（第三方结构化传入）：{}",
            serde_json::to_string(answer_policy).unwrap_or_else(|_| "{}".to_string())
        ));
        sections.extend(assistant_run_external_answer_policy_guidance_lines(
            answer_policy,
        ));
    }
    if let Some(skill_policy) = assistant_run_request_requested_skills_policy(request) {
        sections.push(format!(
            "本轮 SKILL 策略（来自第三方结构化请求，优先于用户文本里的模糊描述）：{}",
            serde_json::to_string(skill_policy).unwrap_or_else(|_| "{}".to_string())
        ));
    }
    if let Some(template_policy) = assistant_run_request_document_template_skills_policy(request) {
        sections.push(format!(
            "本轮文档模板 SKILL（只约束输出结构/格式/风格，不自动作为事实证据）：{}",
            serde_json::to_string(template_policy).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    if !plain_ordinary_chat {
        if let Some(briefing) = request.startup_briefing.as_ref() {
            sections.push(format!(
                "启动简报：{}",
                serde_json::to_string(briefing).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if !plain_ordinary_chat && !request.scope_candidates.is_empty() {
        sections.push(format!(
            "范围候选：{}",
            serde_json::to_string(&request.scope_candidates).unwrap_or_else(|_| "[]".to_string())
        ));
    }
    if !plain_ordinary_chat {
        if let Some(selected_scope) = selected_scope {
            sections.push(format!(
                "当前选中范围：{}",
                serde_json::to_string(selected_scope).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if let Some(evidence_state) = evidence_state {
        if evidence_state.get("status").and_then(Value::as_str) != Some("not_requested") {
            if let Some(brief) = build_assistant_run_model_supply_brief(evidence_state) {
                sections.push(format!("供料提示（供你参考，不是回答模板）：\n{brief}"));
            }
            let model_evidence_state = assistant_run_model_evidence_state(evidence_state);
            sections.push(format!(
                "供料证据（可引用上下文）：{}",
                serde_json::to_string(&model_evidence_state).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if let Some(current_artifact) = request.current_artifact.as_ref() {
        let current_artifact_brief = assistant_run_current_artifact_brief(current_artifact);
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(&current_artifact_brief).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(12)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("最近对话：\n{}", history.join("\n")));
    }

    sections.push(format!("用户问题：{}", request.prompt.trim()));
    sections.join("\n\n")
}

fn assistant_run_scope_is_external_channel(scope: Option<&Value>) -> bool {
    let Some(scope) = scope else {
        return false;
    };
    scope
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|value| value == "external_channel")
        || scope
            .get("mode")
            .and_then(Value::as_str)
            .is_some_and(|value| value == "external_channel")
}

fn build_assistant_run_continue_provider_input(
    run: &AssistantRun,
    request: &ContinueAssistantRunRequest,
    continue_prompt: &str,
    selected_scope: &Value,
    evidence_state: &Value,
    max_steps: usize,
) -> String {
    let plain_ordinary_chat = assistant_run_is_plain_ordinary_chat_scope(
        Some(selected_scope),
        Some(evidence_state),
        request.current_artifact.as_ref(),
    );
    let model_evidence_state = assistant_run_model_evidence_state(evidence_state);
    let mut sections = if plain_ordinary_chat {
        vec![
            "你是通用模型助手，正在继续一轮普通对话。".to_string(),
            "当前没有数据集供料或产物上下文；请按用户继续指令直接作答，不要因为运行在数据智能助手中而限制通用问答能力。".to_string(),
            format!("原始问题：{}", run.user_prompt.trim()),
            format!("继续指令：{}", continue_prompt.trim()),
        ]
    } else {
        vec![
            "你是 AI 数据智能助手里的 AssistantRun 连续执行回答运行时。".to_string(),
            "宿主只负责供料和受控动作；最终正文由你自行组织。如果需要平台能力，只提出下一步动作需求；已有供料可作为上下文参考。".to_string(),
            format!("运行ID：{}", run.id),
            format!("原始问题：{}", run.user_prompt.trim()),
            format!("继续指令：{}", continue_prompt.trim()),
            format!("本次最多连续动作数：{}", max_steps),
            format!(
                "当前选中范围：{}",
                serde_json::to_string(selected_scope).unwrap_or_else(|_| "{}".to_string())
            ),
            format!(
                "供料状态：{}",
                serde_json::to_string(&model_evidence_state).unwrap_or_else(|_| "{}".to_string())
            ),
        ]
    };
    sections.extend(assistant_run_v3_awareness_lines());
    if let Some(answer_policy) = selected_scope
        .get("answer_policy")
        .or_else(|| selected_scope.get("answerPolicy"))
        .filter(|policy| !policy.is_null())
    {
        sections.push(format!(
            "本轮外部回答要求（第三方结构化传入）：{}",
            serde_json::to_string(answer_policy).unwrap_or_else(|_| "{}".to_string())
        ));
        sections.extend(assistant_run_external_answer_policy_guidance_lines(
            answer_policy,
        ));
    }
    if let Some(brief) = build_assistant_run_model_supply_brief(evidence_state) {
        sections.push(format!("供料提示（供你参考，不是回答模板）：\n{brief}"));
    }

    if let Some(current_artifact) = request.current_artifact.as_ref() {
        let current_artifact_brief = assistant_run_current_artifact_brief(current_artifact);
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(&current_artifact_brief).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(8)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("继续前最近对话：\n{}", history.join("\n")));
    }

    sections.join("\n\n")
}

fn build_assistant_run_model_supply_brief(evidence_state: &Value) -> Option<String> {
    let status = evidence_state.get("status").and_then(Value::as_str)?;
    if status == "not_requested" {
        return None;
    }

    let supplied_count = assistant_run_evidence_supplied_count(evidence_state);
    let detail_target_count = assistant_run_detail_target_count(evidence_state);
    let fallback_count = evidence_state
        .get("fallback_supply_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let supply_quality = evidence_state.get("supply_quality");
    let supply_quality_status = supply_quality
        .and_then(|quality| quality.get("status"))
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let citation_locator_count = supply_quality
        .and_then(|quality| quality.get("citationLocatorCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let media_context_count = supply_quality
        .and_then(|quality| quality.get("mediaContextCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let dataset_fact_snapshot_count = supply_quality
        .and_then(|quality| quality.get("datasetFactSnapshotCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let document_not_ready_count = supply_quality
        .and_then(|quality| quality.get("documentNotReadyCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let document_failed_count = supply_quality
        .and_then(|quality| quality.get("documentFailedCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let document_reparsing_count = supply_quality
        .and_then(|quality| quality.get("documentReparsingCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let mut lines = vec![
        format!(
            "状态：{status}；可引用供料 {supplied_count} 条；建议细读目标 {detail_target_count} 个；兜底切片 {fallback_count} 条。"
        ),
        format!(
            "供料质量：{supply_quality_status}；来源定位 {citation_locator_count} 个；库级事实快照 {dataset_fact_snapshot_count} 个；媒体上下文 {media_context_count} 个。"
        ),
        "供料只作为可引用上下文；最终正文由模型自行组织。涉及供料里的数据、指标、文档事实或产物状态时不要编造；普通常识、解释和建议可以使用模型通用知识，并区分供料事实与通用判断。detail_targets 只代表建议细读目标，不是引用依据。".to_string(),
    ];
    if document_not_ready_count > 0 {
        lines.push(format!(
            "文档解析状态：有 {document_not_ready_count} 份可见文档未完全就绪，其中失败 {document_failed_count} 份，重解析/重试中 {document_reparsing_count} 份；涉及这些文档时应说明解析状态，不要声称已经读到完整内容。"
        ));
    }
    if let Some(followup) = evidence_state
        .get("recovery_followup")
        .filter(|value| !value.is_null())
    {
        let question = followup
            .get("question")
            .and_then(Value::as_str)
            .unwrap_or("请补充文档名称、页码、关键词或统计口径，我会沿用本会话继续检索。");
        let status = followup
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("answer_with_current_evidence_then_followup_if_needed");
        lines.push(format!(
            "证据恢复追问：{status}；{question} 模型要求：不能只说“未直接检索到”；先用当前供料和通用知识给一轮可执行答复。若仍无法核验，使用上述追问，并说明下一轮会沿用本会话范围继续检索。"
        ));
    }

    if let Some(items) = evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)
    {
        for (index, item) in items
            .iter()
            .filter_map(assistant_run_model_supply_item_brief)
            .take(ASSISTANT_RUN_MODEL_SUPPLY_BRIEF_ITEM_LIMIT)
            .enumerate()
        {
            lines.push(format!("供料{}：{item}", index + 1));
        }
    }

    if let Some(memory) = evidence_state
        .get("conversation_memory_items")
        .and_then(Value::as_array)
    {
        for (index, item) in memory
            .iter()
            .filter_map(assistant_run_model_memory_item_brief)
            .take(2)
            .enumerate()
        {
            lines.push(format!("历史{}：{item}", index + 1));
        }
    }

    if let Some(targets) = evidence_state
        .get("detail_targets")
        .and_then(Value::as_array)
    {
        let target_briefs = targets
            .iter()
            .filter_map(assistant_run_model_detail_target_brief)
            .take(ASSISTANT_RUN_DETAIL_TARGET_LIMIT)
            .collect::<Vec<_>>();
        if !target_briefs.is_empty() {
            lines.push(format!(
                "建议细读：{}。需要原文措辞、表格/OCR、音视频时间戳或字段定义时，先调用 read_document_detail。",
                target_briefs.join("；")
            ));
        }
    }

    Some(lines.join("\n"))
}

fn assistant_run_model_evidence_state(evidence_state: &Value) -> Value {
    let mut model_state = evidence_state.clone();
    let Some(object) = model_state.as_object_mut() else {
        return model_state;
    };
    let Some(items) = object
        .get_mut("supplied_items")
        .and_then(Value::as_array_mut)
    else {
        return model_state;
    };
    for item in items {
        match item.get("type").and_then(Value::as_str) {
            Some("dataset_entity_scan") => {
                *item = assistant_run_model_dataset_entity_scan_item(item);
            }
            Some("dataset_fact_snapshot") => {
                *item = assistant_run_model_dataset_fact_snapshot_item(item);
            }
            _ => {}
        }
    }
    model_state
}

