fn escape_markdown_table_cell(value: &str) -> String {
    value.replace('|', "\\|").replace('\n', " ")
}

fn assistant_run_model_supply_item_brief(item: &Value) -> Option<String> {
    let item_type = item.get("type").and_then(Value::as_str).unwrap_or("item");
    let source = item
        .get("source")
        .and_then(Value::as_str)
        .unwrap_or("retrieval_evidence");
    let summary = assistant_run_model_text_field(item, &["summary", "content_excerpt"])?;
    let locator = item
        .get("source_locator")
        .or_else(|| item.get("sourceLocator"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let document_id = item
        .get("document_id")
        .or_else(|| item.get("documentId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let mut parts = vec![
        format!("{item_type}/{source}"),
        format!(
            "摘要={}",
            truncate_assistant_supply_text(
                &summary,
                if matches!(item_type, "dataset_entity_scan" | "dataset_fact_snapshot") {
                    ASSISTANT_RUN_MODEL_SCAN_BRIEF_TEXT_LIMIT
                } else {
                    ASSISTANT_RUN_MODEL_SUPPLY_BRIEF_TEXT_LIMIT
                }
            )
        ),
    ];
    if let Some(locator) = locator {
        parts.push(format!("来源={locator}"));
    }
    if let Some(document_id) = document_id {
        parts.push(format!("document_id={document_id}"));
    }
    if let Some(media) = assistant_run_model_media_brief(item) {
        parts.push(media);
    }
    Some(parts.join("；"))
}

fn assistant_run_model_memory_item_brief(item: &Value) -> Option<String> {
    let summary = assistant_run_model_text_field(item, &["summary"])?;
    Some(truncate_assistant_supply_text(
        &summary,
        ASSISTANT_RUN_MODEL_SUPPLY_BRIEF_TEXT_LIMIT,
    ))
}

fn assistant_run_model_detail_target_brief(target: &Value) -> Option<String> {
    let document_id = target
        .get("document_id")
        .or_else(|| target.get("documentId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let reason = target
        .get("reason")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("detail_first_scope");
    let source_locator = target
        .get("source_locator")
        .or_else(|| target.get("sourceLocator"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("");
    if source_locator.is_empty() {
        Some(format!("document_id={document_id}, reason={reason}"))
    } else {
        Some(format!(
            "document_id={document_id}, reason={reason}, source={source_locator}"
        ))
    }
}

fn assistant_run_model_media_brief(item: &Value) -> Option<String> {
    let media = item
        .get("media_context")
        .or_else(|| item.get("mediaContext"))?;
    let kind = media
        .get("media_kind")
        .or_else(|| media.get("mediaKind"))
        .and_then(Value::as_str)
        .unwrap_or("media");
    let parse_status = media
        .get("parse_status")
        .or_else(|| media.get("parseStatus"))
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let transcript_count = media
        .get("transcript_windows")
        .or_else(|| media.get("transcriptWindows"))
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    let scene_count = media
        .get("scene_windows")
        .or_else(|| media.get("sceneWindows"))
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    let ocr_count = media
        .get("keyframe_ocr_snippets")
        .or_else(|| media.get("keyframeOcrSnippets"))
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    Some(format!(
        "媒体={kind}/{parse_status}/transcript:{transcript_count}/scene:{scene_count}/ocr:{ocr_count}"
    ))
}

fn assistant_run_model_text_field(item: &Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        item.get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    })
}

fn build_assistant_run_context_policy(selected_scope: &Value) -> Value {
    let supply_policy = selected_scope
        .get("supply_policy")
        .or_else(|| selected_scope.get("supplyPolicy"))
        .cloned()
        .unwrap_or_else(|| {
            json!({
                "intent": assistant_run_scope_intent(selected_scope),
                "retrievalPolicy": if selected_dataset_ids_from_scope(selected_scope).is_empty() {
                    "not_requested"
                } else {
                    "standard"
                },
                "preferDetail": false,
                "noFakeData": true,
            })
        });
    let retrieval_policy = supply_policy
        .get("retrievalPolicy")
        .or_else(|| supply_policy.get("retrieval_policy"))
        .cloned()
        .unwrap_or_else(|| json!("standard"));
    json!({
        "history_policy": if selected_scope_requests_conversation_memory(selected_scope) {
            "intent_gated_selected"
        } else {
            "intent_gated"
        },
        "supply_policy": "host_supplies_model_answers",
        "retrieval_policy": retrieval_policy,
        "action_policy": assistant_run_scope_action_policy(selected_scope),
        "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
        "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
        "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
        "assistant_intent": assistant_run_scope_intent(selected_scope),
        "scope_supply_policy": supply_policy,
    })
}

async fn complete_assistant_run_provider(
    model_lane: &'static str,
    runtime_mode: String,
    runtime_provider: String,
    runtime_model: String,
    provider_input: String,
) -> std::result::Result<LlmResponse, ApiError> {
    complete_assistant_run_provider_with_env_prefix(
        "ASSISTANT_RUN",
        model_lane,
        runtime_mode,
        runtime_provider,
        runtime_model,
        provider_input,
    )
    .await
}

async fn complete_assistant_run_provider_with_env_prefix(
    env_prefix: impl Into<String>,
    model_lane: &'static str,
    runtime_mode: String,
    runtime_provider: String,
    runtime_model: String,
    provider_input: String,
) -> std::result::Result<LlmResponse, ApiError> {
    let env_prefix = env_prefix.into();
    let retry_attempts = assistant_run_runtime_retry_attempts(&env_prefix);
    let retry_backoff = assistant_run_runtime_retry_backoff(&env_prefix);
    tokio::task::spawn_blocking(move || {
        let provider = build_provider_from_env(
            &env_prefix,
            &runtime_mode,
            runtime_provider,
            bootstrap_default_prompt_registry(),
        )?;
        let request = LlmRequest {
            model: runtime_model,
            lane: Some(model_lane.to_string()),
            system_prompt_key: None,
            input: provider_input,
        };
        for attempt_index in 0..retry_attempts {
            match provider.complete(&request) {
                Ok(response) => return Ok(response),
                Err(error) => {
                    let can_retry = assistant_run_provider_error_is_retryable(&error);
                    if !can_retry || attempt_index + 1 >= retry_attempts {
                        return Err(error);
                    }
                    std::thread::sleep(assistant_run_runtime_retry_delay(
                        retry_backoff,
                        attempt_index,
                    ));
                }
            }
        }
        unreachable!("retry_attempts is always at least one")
    })
    .await
    .map_err(|error| {
        ApiError::internal(
            "assistant_run_join_failed",
            format!("assistant run worker join failed: {error}"),
        )
    })?
    .map_err(|error| ApiError::internal("assistant_run_provider_failed", error.to_string()))
}

async fn complete_assistant_run_provider_with_env_prefix_streaming(
    env_prefix: String,
    model_lane: &'static str,
    runtime_mode: String,
    runtime_provider: String,
    runtime_model: String,
    provider_input: String,
    answer_delta_sink: ExternalChannelAnswerDeltaSink,
) -> std::result::Result<ExternalChannelStreamedProviderResponse, ApiError> {
    let retry_attempts = assistant_run_runtime_retry_attempts(&env_prefix);
    let retry_backoff = assistant_run_runtime_retry_backoff(&env_prefix);
    tokio::task::spawn_blocking(move || {
        let provider = build_provider_from_env(
            &env_prefix,
            &runtime_mode,
            runtime_provider,
            bootstrap_default_prompt_registry(),
        )?;
        let request = LlmRequest {
            model: runtime_model,
            lane: Some(model_lane.to_string()),
            system_prompt_key: None,
            input: provider_input,
        };
        for attempt_index in 0..retry_attempts {
            let mut deltas = Vec::new();
            let mut on_delta = |delta: LlmStreamDelta| {
                deltas.push(delta);
                Ok(())
            };
            match provider.complete_streaming(&request, &mut on_delta) {
                Ok(response) => {
                    return Ok(ExternalChannelStreamedProviderResponse { response, deltas });
                }
                Err(error) => {
                    let can_retry = assistant_run_provider_error_is_retryable(&error);
                    if !can_retry || attempt_index + 1 >= retry_attempts {
                        return Err(error);
                    }
                    answer_delta_sink.emit_answer_retrying("provider_retry");
                    std::thread::sleep(assistant_run_runtime_retry_delay(
                        retry_backoff,
                        attempt_index,
                    ));
                }
            }
        }
        unreachable!("retry_attempts is always at least one")
    })
    .await
    .map_err(|error| {
        ApiError::internal(
            "assistant_run_join_failed",
            format!("assistant run streaming worker join failed: {error}"),
        )
    })?
    .map_err(|error| ApiError::internal("assistant_run_provider_failed", error.to_string()))
}

