fn assistant_run_answer_quality_case_supply_sources(evidence_state: &Value) -> Vec<String> {
    let Some(supply_quality) = evidence_state.get("supply_quality") else {
        return Vec::new();
    };
    let mut sources = Vec::new();
    for (field, source) in [
        ("indexedEvidenceCount", "retrieval_evidence"),
        ("indexed_evidence_count", "retrieval_evidence"),
        ("datasetEntityScanCount", "dataset_entity_scan"),
        ("dataset_entity_scan_count", "dataset_entity_scan"),
        ("datasetFactSnapshotCount", "dataset_fact_snapshot"),
        ("dataset_fact_snapshot_count", "dataset_fact_snapshot"),
        ("spreadsheetRowAnalysisCount", "spreadsheet_row_analysis"),
        ("spreadsheet_row_analysis_count", "spreadsheet_row_analysis"),
        ("mediaContextCount", "media_context"),
        ("media_context_count", "media_context"),
    ] {
        if supply_quality
            .get(field)
            .and_then(Value::as_u64)
            .unwrap_or(0)
            > 0
            && !sources.iter().any(|existing| existing == source)
        {
            sources.push(source.to_string());
        }
    }
    sources
}

fn assistant_run_answer_quality_case_supply_status(evidence_state: &Value) -> String {
    let Some(supply_quality) = evidence_state.get("supply_quality") else {
        return "unknown".to_string();
    };
    if supply_quality
        .get("datasetFactSnapshotCount")
        .or_else(|| supply_quality.get("dataset_fact_snapshot_count"))
        .and_then(Value::as_u64)
        .unwrap_or(0)
        > 0
    {
        return "fact_snapshot_available".to_string();
    }
    if supply_quality
        .get("spreadsheetRowAnalysisCount")
        .or_else(|| supply_quality.get("spreadsheet_row_analysis_count"))
        .and_then(Value::as_u64)
        .unwrap_or(0)
        > 0
    {
        return "spreadsheet_row_analysis_available".to_string();
    }
    supply_quality
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown")
        .to_string()
}

fn assistant_run_answer_quality_exhausted_controlled_answer(
    evidence_state: &Value,
    request: &CreateAssistantRunRequest,
    _remaining_reason: &str,
) -> String {
    if let Some(answer) =
        assistant_run_answer_quality_spreadsheet_controlled_answer(evidence_state, request)
    {
        return answer;
    }
    if let Some(answer) =
        assistant_run_answer_quality_point_list_controlled_answer(evidence_state, request)
    {
        return answer;
    }

    let supplied_count = evidence_state
        .get("supply_quality")
        .and_then(|quality| quality.get("suppliedItemCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    if assistant_run_request_wants_json_output(request) {
        let status = if supplied_count > 0 {
            "needs_more_input_after_retry"
        } else {
            "no_verifiable_evidence"
        };
        let message = if supplied_count > 0 {
            "我已重新核对当前可见材料，但这轮仍未形成可核验结论。"
        } else {
            "我已尝试重新获取可见材料，但这轮没有形成可核验结论。"
        };
        return serde_json::to_string_pretty(&json!({
            "status": status,
            "message": message,
            "question": request.prompt.trim(),
            "supplied_item_count": supplied_count,
            "next_action": "continue_same_conversation_with_more_scope_or_clarification",
            "suggested_user_inputs": ["文档ID", "数据集分组", "页码或章节", "关键词", "统计口径或对象"],
        }))
        .unwrap_or_else(|_| {
            "{\"status\":\"needs_more_input_after_retry\",\"message\":\"需要补充信息后继续。\"}"
                .to_string()
        });
    }
    let is_dissatisfied = assistant_run_request_expresses_dissatisfaction(request);
    if supplied_count > 0 {
        if is_dissatisfied {
            return "我已重新核对可见材料并扩大读取范围，但这轮仍未形成可核验结论。为避免误判，我先不编造结论；请补充具体文档 ID、页码/章节、对象或统计口径。收到补充后，我会沿用本会话已授权的资料范围继续检索并完成回答。".to_string();
        }
        return "我已重新核对当前可见材料，但这轮仍未形成可核验结论。为避免误判，我先不编造结论；请补充具体文档 ID、页码/章节、对象或统计口径。收到补充后，我会沿用本会话已授权的资料范围继续检索并完成回答。".to_string();
    }
    "我已尝试重新获取可见材料，但这轮没有形成可核验结论。为避免误判，我先不编造结论；请补充可用文档 ID、数据集分组或更明确的问题对象。收到补充后，我会沿用本会话继续执行。".to_string()
}

fn assistant_run_answer_quality_spreadsheet_controlled_answer(
    evidence_state: &Value,
    request: &CreateAssistantRunRequest,
) -> Option<String> {
    if !prompt_requests_spreadsheet_row_level_analysis(&request.prompt) {
        return None;
    }
    let rows = assistant_run_spreadsheet_row_analysis_rows(evidence_state)?;
    let requests_absence = prompt_contains_any(&request.prompt, &["缺勤", "未打卡", "没打卡"]);
    let requests_work_hours =
        prompt_contains_any(&request.prompt, &["最长", "最短", "长短", "工时"]);
    let mut absence_rows = rows
        .iter()
        .copied()
        .filter(|row| row.get("category").is_none())
        .collect::<Vec<_>>();
    absence_rows.sort_by(|left, right| {
        assistant_run_spreadsheet_row_text(right, "date")
            .cmp(assistant_run_spreadsheet_row_text(left, "date"))
            .then_with(|| {
                assistant_run_spreadsheet_row_text(left, "employee")
                    .cmp(assistant_run_spreadsheet_row_text(right, "employee"))
            })
    });
    let longest = rows
        .iter()
        .copied()
        .find(|row| row.get("category").and_then(Value::as_str) == Some("longest"));
    let shortest = rows
        .iter()
        .copied()
        .find(|row| row.get("category").and_then(Value::as_str) == Some("shortest"));
    if (!requests_absence || absence_rows.is_empty())
        && (!requests_work_hours || (longest.is_none() && shortest.is_none()))
    {
        return None;
    }
    if assistant_run_request_wants_json_output(request) {
        let absence_json = if requests_absence {
            absence_rows
                .iter()
                .take(20)
                .map(|row| {
                    let category = if row
                        .get("counts_as_absence")
                        .and_then(Value::as_bool)
                        .unwrap_or(true)
                    {
                        "缺勤/未打卡"
                    } else {
                        "未打卡/不考勤"
                    };
                    json!({
                        "category": category,
                        "date": assistant_run_spreadsheet_row_text(row, "date"),
                        "employee": assistant_run_spreadsheet_row_text(row, "employee"),
                        "shift": assistant_run_spreadsheet_row_text(row, "shift"),
                        "status": assistant_run_spreadsheet_row_text(row, "status"),
                    })
                })
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let mut work_hour_extremes = Vec::new();
        if requests_work_hours {
            if let Some(row) = longest {
                work_hour_extremes.push(assistant_run_spreadsheet_work_hour_result_json(
                    "longest",
                    "最长工时",
                    row,
                ));
            }
            if let Some(row) = shortest {
                work_hour_extremes.push(assistant_run_spreadsheet_work_hour_result_json(
                    "shortest",
                    "最短工时",
                    row,
                ));
            }
        }
        return serde_json::to_string_pretty(&json!({
            "status": "answered",
            "source": "spreadsheet_row_analysis",
            "question": request.prompt.trim(),
            "documents": assistant_run_spreadsheet_row_analysis_document_titles(evidence_state),
            "absence_rows": absence_json,
            "work_hour_extremes": work_hour_extremes,
        }))
        .ok();
    }

    let mut lines = vec!["根据已解析的考勤明细，结果如下：".to_string()];
    if requests_absence && !absence_rows.is_empty() {
        lines.push(String::new());
        lines.push("| 类别 | 日期 | 员工 | 班次 | 状态 |".to_string());
        lines.push("|---|---|---|---|---|".to_string());
        for row in absence_rows.into_iter().take(20) {
            let category = if row
                .get("counts_as_absence")
                .and_then(Value::as_bool)
                .unwrap_or(true)
            {
                "缺勤/未打卡"
            } else {
                "未打卡/不考勤"
            };
            lines.push(format!(
                "| {category} | {} | {} | {} | {} |",
                assistant_run_spreadsheet_row_text(row, "date"),
                assistant_run_spreadsheet_row_text(row, "employee"),
                assistant_run_spreadsheet_row_text(row, "shift"),
                assistant_run_spreadsheet_row_text(row, "status"),
            ));
        }
    }
    if requests_work_hours && (longest.is_some() || shortest.is_some()) {
        lines.push(String::new());
        lines.push("| 类型 | 日期 | 员工 | 班次 | 工时 | 状态 |".to_string());
        lines.push("|---|---|---|---|---|---|".to_string());
        if let Some(row) = longest {
            lines.push(assistant_run_spreadsheet_work_hour_result_row(
                "最长工时",
                row,
            ));
        }
        if let Some(row) = shortest {
            lines.push(assistant_run_spreadsheet_work_hour_result_row(
                "最短工时",
                row,
            ));
        }
    }
    let titles = assistant_run_spreadsheet_row_analysis_document_titles(evidence_state);
    if !titles.is_empty() {
        lines.push(String::new());
        lines.push(format!("来源：{}", titles.join("、")));
    }
    Some(lines.join("\n"))
}

fn assistant_run_spreadsheet_work_hour_result_row(label: &str, row: &Value) -> String {
    format!(
        "| {label} | {} | {} | {} | {} | {} |",
        assistant_run_spreadsheet_row_text(row, "date"),
        assistant_run_spreadsheet_row_text(row, "employee"),
        assistant_run_spreadsheet_row_text(row, "shift"),
        assistant_run_spreadsheet_row_text(row, "work_hours_text"),
        assistant_run_spreadsheet_row_text(row, "status"),
    )
}

fn assistant_run_spreadsheet_work_hour_result_json(kind: &str, label: &str, row: &Value) -> Value {
    json!({
        "kind": kind,
        "label": label,
        "date": assistant_run_spreadsheet_row_text(row, "date"),
        "employee": assistant_run_spreadsheet_row_text(row, "employee"),
        "shift": assistant_run_spreadsheet_row_text(row, "shift"),
        "work_hours_text": assistant_run_spreadsheet_row_text(row, "work_hours_text"),
        "status": assistant_run_spreadsheet_row_text(row, "status"),
    })
}

fn assistant_run_spreadsheet_row_text<'a>(row: &'a Value, key: &str) -> &'a str {
    row.get(key).and_then(Value::as_str).unwrap_or("")
}

fn assistant_run_spreadsheet_row_analysis_document_titles(evidence_state: &Value) -> Vec<String> {
    evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("spreadsheet_row_analysis"))
        .flat_map(|item| {
            item.get("documents")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
        })
        .filter_map(|document| document.get("title").and_then(Value::as_str))
        .map(str::trim)
        .filter(|title| !title.is_empty())
        .map(ToOwned::to_owned)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

fn assistant_run_answer_quality_point_list_controlled_answer(
    evidence_state: &Value,
    request: &CreateAssistantRunRequest,
) -> Option<String> {
    if !assistant_run_prompt_requests_point_list_table(&request.prompt) {
        return None;
    }
    let rows = assistant_run_point_list_rows_from_retrieval_evidence(evidence_state);
    if rows.is_empty() {
        return None;
    }
    if assistant_run_request_wants_json_output(request) {
        let rows = rows
            .iter()
            .map(|row| {
                json!({
                    "floor": row.floor,
                    "location": row.location,
                    "name": row.name,
                    "areaid": row.area_id,
                    "type": row.type_label,
                })
            })
            .collect::<Vec<_>>();
        return serde_json::to_string_pretty(&json!({
            "status": "answered",
            "source": "retrieval_point_list",
            "question": request.prompt.trim(),
            "rows": rows,
        }))
        .ok();
    }
    let mut lines = vec![
        "根据已检索到的点位证据，智能梯控/电梯点位如下：".to_string(),
        String::new(),
        "| 楼层 | 位置 | 点位名称 | areaid | 类型 |".to_string(),
        "|---|---|---|---|---|".to_string(),
    ];
    for row in rows {
        lines.push(format!(
            "| {} | {} | {} | {} | {} |",
            row.floor, row.location, row.name, row.area_id, row.type_label
        ));
    }
    Some(lines.join("\n"))
}

#[cfg(test)]
fn assistant_run_answer_quality_retry_budget(request: &CreateAssistantRunRequest) -> usize {
    assistant_run_answer_quality_budget(request).answer_retry_budget
}

fn assistant_run_answer_quality_budget(
    request: &CreateAssistantRunRequest,
) -> AssistantRunQualityBudget {
    let mut budget = if assistant_run_request_expresses_strong_complaint(request) {
        AssistantRunQualityBudget {
            answer_retry_budget: ASSISTANT_RUN_ANSWER_QUALITY_STRONG_COMPLAINT_RETRY_BUDGET,
            react_step_budget: ASSISTANT_RUN_REACT_MAX_STEPS,
            premium_action_budget: 1,
            reason: "strong_complaint",
        }
    } else if assistant_run_request_expresses_dissatisfaction(request) {
        AssistantRunQualityBudget {
            answer_retry_budget: ASSISTANT_RUN_ANSWER_QUALITY_DISSATISFIED_RETRY_BUDGET,
            react_step_budget: ASSISTANT_RUN_REACT_DEFAULT_MAX_STEPS,
            premium_action_budget: 1,
            reason: "dissatisfied",
        }
    } else {
        AssistantRunQualityBudget {
            answer_retry_budget: ASSISTANT_RUN_ANSWER_QUALITY_DEFAULT_RETRY_BUDGET,
            react_step_budget: ASSISTANT_RUN_REACT_DEFAULT_MAX_STEPS,
            premium_action_budget: 0,
            reason: "default",
        }
    };
    if let Some(env_budget) = assistant_run_answer_quality_retry_budget_from_env() {
        budget.answer_retry_budget = env_budget.min(ASSISTANT_RUN_ANSWER_QUALITY_MAX_RETRY_BUDGET);
        budget.reason = "env_override";
    }
    budget.answer_retry_budget = budget
        .answer_retry_budget
        .min(ASSISTANT_RUN_ANSWER_QUALITY_MAX_RETRY_BUDGET);
    budget
}

fn assistant_run_answer_quality_budget_for_evidence(
    request: &CreateAssistantRunRequest,
    evidence_state: &Value,
) -> AssistantRunQualityBudget {
    let mut budget = assistant_run_answer_quality_budget(request);
    if budget.reason == "default"
        && assistant_run_prompt_is_high_risk_quality_task(&request.prompt)
        && assistant_run_supply_quality_suggests_parse_recovery(evidence_state)
    {
        budget.answer_retry_budget = budget.answer_retry_budget.max(2);
        budget.premium_action_budget = budget.premium_action_budget.max(1);
        budget.reason = "parse_quality_recovery";
    }
    budget
}

fn assistant_run_answer_quality_retry_budget_from_env() -> Option<usize> {
    std::env::var("ASSISTANT_RUN_ANSWER_QUALITY_RETRY_BUDGET")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
}

fn assistant_run_supply_quality_suggests_parse_recovery(evidence_state: &Value) -> bool {
    let Some(supply_quality) = evidence_state.get("supply_quality") else {
        return false;
    };
    [
        "lowTextEvidenceCount",
        "documentDegradedParseCount",
        "documentFailedCount",
        "documentReparsingCount",
    ]
    .iter()
    .any(|key| {
        supply_quality
            .get(*key)
            .and_then(Value::as_u64)
            .map(|count| count > 0)
            .unwrap_or(false)
    }) || supply_quality
        .get("notes")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .any(|note| {
            matches!(
                note.as_str(),
                Some("low_text_document_evidence") | Some("parse_quality_degraded")
            )
        })
}

fn assistant_run_request_expresses_dissatisfaction(request: &CreateAssistantRunRequest) -> bool {
    let mut texts = vec![request.prompt.as_str()];
    texts.extend(
        request
            .messages
            .iter()
            .rev()
            .take(6)
            .map(|message| message.content.as_str()),
    );
    texts.into_iter().any(|text| {
        let lower = text.to_ascii_lowercase();
        prompt_contains_any(
            text,
            &[
                "不满意",
                "不太满意",
                "客户不满",
                "客户有些不满意",
                "观感差",
                "回答很差",
                "回答太差",
                "答得差",
                "答非所问",
                "不准确",
                "不准",
                "不对",
                "错了",
                "错误",
                "乱答",
                "瞎答",
                "投诉",
            ],
        ) || ascii_prompt_contains_any(
            &lower,
            &[
                "dissatisfied",
                "unsatisfied",
                "unhappy",
                "wrong",
                "incorrect",
                "inaccurate",
                "poor",
                "bad",
                "complaint",
            ],
        )
    })
}

fn assistant_run_request_expresses_strong_complaint(request: &CreateAssistantRunRequest) -> bool {
    let mut texts = vec![request.prompt.as_str()];
    texts.extend(
        request
            .messages
            .iter()
            .rev()
            .take(6)
            .map(|message| message.content.as_str()),
    );
    texts.into_iter().any(|text| {
        let lower = text.to_ascii_lowercase();
        prompt_contains_any(
            text,
            &[
                "严重不满",
                "很不满意",
                "非常不满意",
                "客户很不满意",
                "反复答错",
                "多次答错",
                "严重错误",
                "线上事故",
                "投诉",
            ],
        ) || ascii_prompt_contains_any(
            &lower,
            &[
                "strong complaint",
                "formal complaint",
                "very dissatisfied",
                "repeatedly wrong",
                "critical failure",
                "incident",
                "escalation",
            ],
        )
    })
}

#[derive(Clone, Debug, PartialEq)]
struct AssistantRunAnswerQualityJudgeDecision {
    verdict: AssistantRunAnswerQualityJudgeVerdict,
    reason: String,
    confidence: f64,
    customer_safe: bool,
    required_actions: Vec<String>,
    premium_action_allowed: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AssistantRunAnswerQualityJudgeVerdict {
    Accept,
    Retry,
    ControlledFallback,
}

async fn assistant_run_answer_quality_retry_reason_with_judge(
    output_text: &str,
    evidence_state: &Value,
    request: &CreateAssistantRunRequest,
    chat_runtime: &LlmRuntimeSelection,
) -> Option<&'static str> {
    if let Some(reason) =
        assistant_run_answer_quality_retry_reason(output_text, evidence_state, request)
    {
        return Some(reason);
    }
    if !assistant_run_answer_quality_judge_should_run(output_text, evidence_state, request) {
        return None;
    }
    let decision = complete_assistant_run_answer_quality_judge(
        chat_runtime,
        request,
        evidence_state,
        output_text,
    )
    .await?;
    assistant_run_answer_quality_retry_reason_from_judge_decision(&decision)
}

fn assistant_run_answer_quality_retry_reason_from_judge_decision(
    decision: &AssistantRunAnswerQualityJudgeDecision,
) -> Option<&'static str> {
    if !decision.customer_safe {
        return Some("model_judge_customer_unsafe_answer");
    }
    match decision.verdict {
        AssistantRunAnswerQualityJudgeVerdict::Accept => None,
        AssistantRunAnswerQualityJudgeVerdict::Retry => match decision.reason.as_str() {
            "parse_quality_insufficient" => Some("model_judge_parse_quality_insufficient"),
            "incomplete_task" => Some("model_judge_incomplete_task"),
            "ungrounded" => Some("model_judge_ungrounded_answer"),
            "low_customer_confidence" => Some("model_judge_low_customer_confidence"),
            "unsafe_internal_leak" => Some("model_judge_customer_unsafe_answer"),
            _ => Some("model_judge_retry"),
        },
        AssistantRunAnswerQualityJudgeVerdict::ControlledFallback => None,
    }
}

fn assistant_run_answer_quality_judge_should_run(
    output_text: &str,
    evidence_state: &Value,
    request: &CreateAssistantRunRequest,
) -> bool {
    if !assistant_run_answer_quality_retry_allowed(output_text, evidence_state) {
        return false;
    }
    if assistant_run_request_expresses_dissatisfaction(request) {
        return true;
    }
    if assistant_run_answer_contains_weak_confidence_marker(output_text) {
        return true;
    }
    if assistant_run_answer_satisfies_spreadsheet_row_analysis(output_text, request, evidence_state)
    {
        return false;
    }
    if assistant_run_answer_satisfies_retrieval_point_list(output_text, request, evidence_state) {
        return false;
    }
    if assistant_run_prompt_is_high_risk_quality_task(&request.prompt) {
        return true;
    }
    if assistant_run_supply_quality_needs_judge(evidence_state) {
        return true;
    }
    assistant_run_answer_is_short_for_structured_request(output_text, request, evidence_state)
}

fn assistant_run_prompt_is_high_risk_quality_task(prompt: &str) -> bool {
    let lower = prompt.to_ascii_lowercase();
    prompt_contains_any(
        prompt,
        &[
            "是谁",
            "谁是",
            "哪些",
            "多少",
            "统计",
            "汇总",
            "排序",
            "排行",
            "排名",
            "表格",
            "出表",
            "缺勤",
            "工时",
            "最长",
            "最短",
            "公司名",
            "智能家居",
            "智能梯控",
        ],
    ) || ascii_prompt_contains_any(
        &lower,
        &[
            "who",
            "which",
            "how many",
            "count",
            "statistic",
            "sort",
            "rank",
            "table",
            "absence",
            "work hour",
        ],
    ) || prompt_requests_document_entity_scan(prompt)
        || prompt_requests_company_entity_statistics(prompt)
        || prompt_requests_table_statistics(prompt)
        || prompt_requests_resume_skill_ranking(prompt)
        || prompt_requests_resume_project_ranking(prompt)
        || prompt_requests_resume_position_ranking(prompt)
        || prompt_requests_resume_location_ranking(prompt)
        || prompt_requests_resume_company_ranking(prompt)
        || prompt_requests_resume_education_ranking(prompt)
        || prompt_requests_resume_certificate_ranking(prompt)
}

fn assistant_run_supply_quality_needs_judge(evidence_state: &Value) -> bool {
    let Some(supply_quality) = evidence_state.get("supply_quality") else {
        return false;
    };
    [
        "fallbackChunkCount",
        "lowTextEvidenceCount",
        "documentDegradedParseCount",
        "documentNotReadyCount",
        "documentFailedCount",
        "documentReparsingCount",
    ]
    .iter()
    .any(|key| {
        supply_quality
            .get(*key)
            .and_then(Value::as_u64)
            .map(|count| count > 0)
            .unwrap_or(false)
    }) || supply_quality
        .get("notes")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .any(|note| {
            matches!(
                note.as_str(),
                Some("fallback_visible_document_chunks_used")
                    | Some("low_text_document_evidence")
                    | Some("parse_quality_degraded")
            )
        })
}

fn assistant_run_answer_is_short_for_structured_request(
    output_text: &str,
    request: &CreateAssistantRunRequest,
    evidence_state: &Value,
) -> bool {
    if !assistant_run_prompt_is_high_risk_quality_task(&request.prompt) {
        return false;
    }
    let supplied_count = evidence_state
        .get("supply_quality")
        .and_then(|quality| quality.get("suppliedItemCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    supplied_count > 0 && output_text.chars().count() < 80
}

fn assistant_run_answer_satisfies_spreadsheet_row_analysis(
    output_text: &str,
    request: &CreateAssistantRunRequest,
    evidence_state: &Value,
) -> bool {
    if !prompt_requests_spreadsheet_row_level_analysis(&request.prompt) {
        return false;
    }
    if assistant_run_answer_contains_insufficient_evidence_marker(output_text)
        || assistant_run_react_output_contains_internal_marker(output_text)
    {
        return false;
    }
    let Some(rows) = assistant_run_spreadsheet_row_analysis_rows(evidence_state) else {
        return false;
    };
    if !output_text.contains('|') {
        return false;
    }

    let requests_absence = prompt_contains_any(&request.prompt, &["缺勤", "未打卡", "没打卡"]);
    let requests_work_hours =
        prompt_contains_any(&request.prompt, &["最长", "最短", "长短", "工时"]);
    let mut saw_absence_answer = !requests_absence;
    let mut saw_longest_answer = !requests_work_hours;
    let mut saw_shortest_answer = !requests_work_hours;

    for row in rows {
        match row.get("category").and_then(Value::as_str) {
            Some("longest") => {
                saw_longest_answer = assistant_run_answer_contains_row_terms(
                    output_text,
                    row,
                    &["最长", "最长工时"],
                );
            }
            Some("shortest") => {
                saw_shortest_answer = assistant_run_answer_contains_row_terms(
                    output_text,
                    row,
                    &["最短", "最短工时"],
                );
            }
            _ if requests_absence && !saw_absence_answer => {
                saw_absence_answer =
                    assistant_run_answer_contains_row_terms(output_text, row, &["缺勤", "未打卡"]);
            }
            _ => {}
        }
    }

    saw_absence_answer && saw_longest_answer && saw_shortest_answer
}

fn assistant_run_spreadsheet_row_analysis_rows(evidence_state: &Value) -> Option<Vec<&Value>> {
    let rows = evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)?
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("spreadsheet_row_analysis"))
        .filter_map(|item| item.get("rows").and_then(Value::as_array))
        .flatten()
        .collect::<Vec<_>>();
    (!rows.is_empty()).then_some(rows)
}

fn assistant_run_answer_contains_row_terms(
    output_text: &str,
    row: &Value,
    category_terms: &[&str],
) -> bool {
    let has_category = category_terms.iter().any(|term| output_text.contains(term));
    if !has_category {
        return false;
    }
    ["date", "employee", "work_hours_text"]
        .iter()
        .filter_map(|key| row.get(*key).and_then(Value::as_str))
        .filter(|term| !term.trim().is_empty())
        .all(|term| output_text.contains(term))
}

fn assistant_run_answer_satisfies_retrieval_point_list(
    output_text: &str,
    request: &CreateAssistantRunRequest,
    evidence_state: &Value,
) -> bool {
    if !assistant_run_prompt_requests_point_list_table(&request.prompt) {
        return false;
    }
    if assistant_run_answer_contains_insufficient_evidence_marker(output_text)
        || assistant_run_react_output_contains_internal_marker(output_text)
        || !output_text.contains('|')
    {
        return false;
    }
    let rows = assistant_run_point_list_rows_from_retrieval_evidence(evidence_state);
    if rows.is_empty() {
        return false;
    }
    let matched = rows
        .iter()
        .filter(|row| output_text.contains(&row.name))
        .count();
    matched >= rows.len().min(3)
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct AssistantRunPointListRow {
    floor: String,
    location: String,
    name: String,
    area_id: String,
    type_label: String,
}

fn assistant_run_prompt_requests_point_list_table(prompt: &str) -> bool {
    let lower = prompt.to_ascii_lowercase();
    let has_point_subject = prompt_contains_any(
        prompt,
        &["智能梯控", "电梯", "扶梯", "梯控", "点位", "楼层", "位置"],
    ) || ascii_prompt_contains_any(
        &lower,
        &["elevator", "escalator", "point", "floor", "location"],
    );
    let has_table_or_list =
        prompt_contains_any(prompt, &["有哪些", "出表", "表格", "列出", "按楼层"])
            || ascii_prompt_contains_any(&lower, &["list", "table"]);
    has_point_subject && has_table_or_list
}

fn assistant_run_point_list_rows_from_retrieval_evidence(
    evidence_state: &Value,
) -> Vec<AssistantRunPointListRow> {
    let mut by_name = BTreeMap::<String, AssistantRunPointListRow>::new();
    for item in evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("retrieval_evidence"))
    {
        let Some(content) = item.get("content_excerpt").and_then(Value::as_str) else {
            continue;
        };
        let Some(name) = assistant_run_marker_value(content, "areaname") else {
            continue;
        };
        if !assistant_run_text_has_elevator_point_signal(&name) {
            continue;
        }
        let area_id = assistant_run_marker_value(content, "areaid").unwrap_or_default();
        let (floor, location) = assistant_run_split_floor_location(&name);
        let type_label = assistant_run_point_type_label(&name);
        by_name
            .entry(name.clone())
            .or_insert(AssistantRunPointListRow {
                floor,
                location,
                name,
                area_id,
                type_label,
            });
    }
    by_name.into_values().collect()
}

fn assistant_run_marker_value(content: &str, marker: &str) -> Option<String> {
    let marker = format!("## {marker}");
    let tail = content.split_once(&marker)?.1.trim();
    let value = tail.split("##").next()?.trim();
    (!value.is_empty()).then(|| value.to_string())
}

fn assistant_run_text_has_elevator_point_signal(value: &str) -> bool {
    prompt_contains_any(value, &["电梯", "扶梯", "梯控"])
        || value.to_ascii_lowercase().contains("elevator")
}

fn assistant_run_point_type_label(name: &str) -> String {
    if prompt_contains_any(name, &["扶梯", "手扶"]) {
        "扶梯".to_string()
    } else if prompt_contains_any(name, &["电梯", "直梯", "观光梯"]) {
        "电梯".to_string()
    } else {
        "点位".to_string()
    }
}

fn assistant_run_split_floor_location(name: &str) -> (String, String) {
    let mut split_at = 0usize;
    for (index, ch) in name.char_indices() {
        if ch.is_ascii_alphanumeric() {
            split_at = index + ch.len_utf8();
            continue;
        }
        break;
    }
    if split_at == 0 {
        return ("".to_string(), name.to_string());
    }
    let floor = name[..split_at].to_string();
    let location = name[split_at..].trim().to_string();
    (floor, location)
}

async fn complete_assistant_run_answer_quality_judge(
    chat_runtime: &LlmRuntimeSelection,
    request: &CreateAssistantRunRequest,
    evidence_state: &Value,
    output_text: &str,
) -> Option<AssistantRunAnswerQualityJudgeDecision> {
    if chat_runtime.mode == "placeholder" || !assistant_run_answer_quality_judge_enabled() {
        return None;
    }
    let provider_input =
        build_assistant_run_answer_quality_judge_input(request, evidence_state, output_text);
    let response = complete_assistant_run_provider(
        MODEL_LANE_ASSISTANT_CHAT,
        chat_runtime.mode.clone(),
        chat_runtime.provider.clone(),
        chat_runtime.model.clone(),
        provider_input,
    )
    .await
    .ok()?;
    parse_assistant_run_answer_quality_judge_decision(&response.output_text)
}

fn assistant_run_answer_quality_judge_enabled() -> bool {
    std::env::var("ASSISTANT_RUN_ANSWER_QUALITY_JUDGE_ENABLED")
        .map(|value| {
            !matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "0" | "false" | "off"
            )
        })
        .unwrap_or(true)
}

fn build_assistant_run_answer_quality_judge_input(
    request: &CreateAssistantRunRequest,
    evidence_state: &Value,
    output_text: &str,
) -> String {
    let supply_quality = evidence_state
        .get("supply_quality")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let model_evidence_state = assistant_run_model_evidence_state(evidence_state);
    let supply_brief = build_assistant_run_model_supply_brief(evidence_state)
        .unwrap_or_else(|| "无供料摘要。".to_string());
    let answer_excerpt = output_text
        .chars()
        .take(ASSISTANT_RUN_ANSWER_QUALITY_JUDGE_ANSWER_CHARS)
        .collect::<String>();
    [
        "你是 V3 AssistantRun 的内部回答质量判卷器，只能输出 JSON，不能回答用户。".to_string(),
        "根据用户问题、供料状态、可回答证据摘要和候选答案，判断候选答案是否可以安全给客户。".to_string(),
        "硬规则：如果已有证据但候选答案推脱、遗漏表格/统计/排序任务、没有回答实体问题、或含内部状态泄露，应 verdict=retry。".to_string(),
        "如果解析质量明显阻塞且可通过升级解析恢复，required_actions 包含 upgrade_parse_vlm；但不要自行回答材料内容。".to_string(),
        "如果确实不可答且没有可靠升级路径，可 verdict=controlled_fallback。".to_string(),
        r#"只输出 JSON Schema：{"verdict":"accept|retry|controlled_fallback","reason":"ok|insufficient_evidence|ungrounded|incomplete_task|parse_quality_insufficient|low_customer_confidence|unsafe_internal_leak","confidence":0.0,"customer_safe":true,"required_actions":["retrieve_evidence","read_document_detail"],"premium_action_allowed":false}"#.to_string(),
        format!("用户问题：{}", request.prompt.trim()),
        format!(
            "供料质量：{}",
            serde_json::to_string(&supply_quality).unwrap_or_else(|_| "{}".to_string())
        ),
        format!("供料摘要：\n{supply_brief}"),
        format!(
            "可回答证据摘要：{}",
            serde_json::to_string(&model_evidence_state).unwrap_or_else(|_| "{}".to_string())
        ),
        format!("候选答案：\n{answer_excerpt}"),
    ]
    .join("\n\n")
}

fn parse_assistant_run_answer_quality_judge_decision(
    raw: &str,
) -> Option<AssistantRunAnswerQualityJudgeDecision> {
    let candidate = assistant_run_react_json_payload_candidate(raw)?;
    let value = serde_json::from_str::<Value>(&candidate).ok()?;
    let verdict = value.get("verdict").and_then(Value::as_str)?;
    let verdict = match verdict.trim().to_ascii_lowercase().as_str() {
        "accept" => AssistantRunAnswerQualityJudgeVerdict::Accept,
        "retry" => AssistantRunAnswerQualityJudgeVerdict::Retry,
        "controlled_fallback" | "controlled-fallback" | "fallback" => {
            AssistantRunAnswerQualityJudgeVerdict::ControlledFallback
        }
        _ => return None,
    };
    let reason = value
        .get("reason")
        .and_then(Value::as_str)
        .map(|reason| reason.trim().to_ascii_lowercase())
        .filter(|reason| !reason.is_empty())
        .unwrap_or_else(|| "ok".to_string());
    let confidence = value
        .get("confidence")
        .and_then(Value::as_f64)
        .unwrap_or(0.0)
        .clamp(0.0, 1.0);
    let customer_safe = value
        .get("customer_safe")
        .or_else(|| value.get("customerSafe"))
        .and_then(Value::as_bool)
        .unwrap_or(verdict == AssistantRunAnswerQualityJudgeVerdict::Accept);
    let required_actions = value
        .get("required_actions")
        .or_else(|| value.get("requiredActions"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|action| !action.is_empty())
        .map(ToOwned::to_owned)
        .collect::<Vec<_>>();
    let premium_action_allowed = value
        .get("premium_action_allowed")
        .or_else(|| value.get("premiumActionAllowed"))
        .and_then(Value::as_bool)
        .unwrap_or(false);
    Some(AssistantRunAnswerQualityJudgeDecision {
        verdict,
        reason,
        confidence,
        customer_safe,
        required_actions,
        premium_action_allowed,
    })
}

fn assistant_run_answer_quality_retry_reason(
    output_text: &str,
    evidence_state: &Value,
    request: &CreateAssistantRunRequest,
) -> Option<&'static str> {
    let output_text = output_text.trim();
    if output_text.is_empty() {
        return assistant_run_answer_quality_retry_allowed(output_text, evidence_state)
            .then_some("empty_answer");
    }
    if assistant_run_react_output_contains_internal_marker(output_text) {
        return assistant_run_answer_quality_retry_allowed(output_text, evidence_state)
            .then_some("internal_marker_answer");
    }
    if external_channel_output_is_generic_orchestration_ack(output_text) {
        return assistant_run_answer_quality_retry_allowed(output_text, evidence_state)
            .then_some("generic_orchestration_ack");
    }
    if assistant_run_answer_contains_insufficient_evidence_marker(output_text)
        && assistant_run_answer_quality_retry_allowed(output_text, evidence_state)
    {
        return Some("insufficient_or_uncertain_answer");
    }
    if assistant_run_request_expresses_dissatisfaction(request)
        && assistant_run_answer_contains_weak_confidence_marker(output_text)
        && assistant_run_answer_quality_retry_allowed(output_text, evidence_state)
    {
        return Some("dissatisfied_user_weak_confidence_answer");
    }
    None
}

fn assistant_run_answer_quality_retry_allowed(output_text: &str, evidence_state: &Value) -> bool {
    if evidence_state.get("status").and_then(Value::as_str) == Some("not_requested") {
        return false;
    }
    let Some(supply_quality) = evidence_state.get("supply_quality") else {
        return false;
    };
    let selected_dataset_count = supply_quality
        .get("selectedDatasetCount")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let supplied_item_count = supply_quality
        .get("suppliedItemCount")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let conversation_memory_count = supply_quality
        .get("conversationMemoryItemCount")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    if selected_dataset_count == 0 && supplied_item_count == 0 && conversation_memory_count == 0 {
        return false;
    }
    if assistant_run_answer_reports_actual_parse_unavailable(output_text, supply_quality) {
        return false;
    }
    true
}

fn assistant_run_answer_reports_actual_parse_unavailable(
    output_text: &str,
    supply_quality: &Value,
) -> bool {
    let unavailable_count = [
        "documentNotReadyCount",
        "documentFailedCount",
        "documentReparsingCount",
    ]
    .iter()
    .filter_map(|key| supply_quality.get(*key).and_then(Value::as_u64))
    .sum::<u64>();
    let low_text_evidence_present = supply_quality
        .get("lowTextEvidenceCount")
        .and_then(Value::as_u64)
        .map(|count| count > 0)
        .unwrap_or_else(|| {
            supply_quality
                .get("notes")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .any(|note| note.as_str() == Some("low_text_document_evidence"))
        });
    if unavailable_count == 0 && !low_text_evidence_present {
        return false;
    }
    let answerable_supply_count = [
        "indexedEvidenceCount",
        "fallbackChunkCount",
        "datasetEntityScanCount",
        "datasetFactSnapshotCount",
        "spreadsheetRowAnalysisCount",
        "mediaContextCount",
        "conversationMemoryItemCount",
    ]
    .iter()
    .filter_map(|key| supply_quality.get(*key).and_then(Value::as_u64))
    .sum::<u64>();
    let low_text_only_answerable_limit = u64::from(low_text_evidence_present);
    if answerable_supply_count > low_text_only_answerable_limit {
        return false;
    }
    prompt_contains_any(
        output_text,
        &[
            "正在解析",
            "解析中",
            "解析失败",
            "解析未完成",
            "未解析完成",
            "资料不足",
            "信息不足",
            "无法回答",
            "无法确认",
            "重解析",
            "重试中",
            "文档未就绪",
            "低质量",
            "解析质量",
            "解析不完整",
            "仅返回了标题字段",
            "只返回了标题字段",
            "原文内容尚未被平台解析",
        ],
    )
}

fn assistant_run_answer_contains_insufficient_evidence_marker(output_text: &str) -> bool {
    let lower = output_text.to_ascii_lowercase();
    prompt_contains_any(
        output_text,
        &[
            "资料不足",
            "材料不足",
            "信息不足",
            "证据不足",
            "数据不足",
            "上下文不足",
            "供料不足",
            "没有足够",
            "未提供足够",
            "不够回答",
            "不足以回答",
            "无法回答",
            "无法确认",
            "无法判断",
            "无法确定",
            "不能确认",
            "不能确定",
            "暂无法",
            "暂时无法",
            "未找到相关",
            "没有找到相关",
            "未直接检索到",
            "没有直接检索到",
            "未检索到",
            "文档未提及",
            "文档中未提及",
            "当前可见信息不足",
            "当前资料不足",
            "当前资料无法",
            "当前信息无法",
            "基于当前可见",
            "基于通用知识",
            "通用知识的建议",
            "当前可见",
            "部分解析状态",
            "部分解析",
            "解析不完整",
            "仅返回了标题字段",
            "只返回了标题字段",
            "原文内容尚未被平台解析",
            "仅基于当前可见",
            "只基于当前可见",
            "只能基于当前可见",
            "需要执行一次",
            "需要先检索",
            "需要先读取",
            "需要先获取",
            "请允许我先",
            "请回复\"继续\"",
            "请回复“继续”",
            "建议发起检索",
            "建议重新检索",
            "没有全量",
            "未全量",
            "完整、无遗漏",
            "需要补充资料",
            "建议补充资料",
            "建议上传",
        ],
    ) || [
        "insufficient information",
        "not enough information",
        "insufficient evidence",
        "cannot determine",
        "can't determine",
        "unable to determine",
        "unable to answer",
        "cannot answer",
        "not enough context",
    ]
    .iter()
    .any(|marker| lower.contains(marker))
}

fn assistant_run_answer_contains_weak_confidence_marker(output_text: &str) -> bool {
    let lower = output_text.to_ascii_lowercase();
    prompt_contains_any(
        output_text,
        &[
            "可能",
            "大概",
            "似乎",
            "推测",
            "猜测",
            "不确定",
            "不完整",
            "部分数据",
            "部分资料",
        ],
    ) || ["maybe", "probably", "likely", "uncertain", "partial"]
        .iter()
        .any(|marker| lower.contains(marker))
}

fn assistant_run_answer_quality_retry_scope(
    selected_scope: &Value,
    prompt: &str,
    attempt_index: usize,
) -> Value {
    let mut retry_scope = selected_scope.clone();
    ensure_json_object(&mut retry_scope);
    let mut supply_policy = assistant_run_scope_supply_policy(&retry_scope);
    set_payload_value(&mut supply_policy, "retrievalPolicy", json!("detail_first"));
    set_payload_value(&mut supply_policy, "preferDetail", json!(true));
    set_payload_value(
        &mut supply_policy,
        "contextBudgetPolicy",
        json!("quality_first_token_tolerant"),
    );

    let mut actions = assistant_run_scope_recommended_tool_actions(selected_scope);
    actions.push("retrieval.search".to_string());
    actions.push("retrieval.read_detail".to_string());
    if prompt_requests_document_entity_scan(prompt) {
        actions.push("retrieval.scan_documents".to_string());
    }
    set_payload_value(
        &mut supply_policy,
        "recommendedActions",
        Value::Array(
            dedupe_strings(actions)
                .into_iter()
                .map(Value::String)
                .collect(),
        ),
    );
    set_payload_value(&mut retry_scope, "supply_policy", supply_policy);
    set_payload_value(
        &mut retry_scope,
        "answer_quality_gate",
        json!({
            "status": "retrying",
            "attempt": attempt_index,
            "strategy": "detail_first_react_expand_supply",
        }),
    );
    retry_scope
}

fn assistant_run_answer_quality_retry_request(
    request: &CreateAssistantRunRequest,
    retry_scope: &Value,
    attempt_index: usize,
    budget: usize,
    quality_budget: &AssistantRunQualityBudget,
    reason: &str,
    previous_answer: &str,
) -> CreateAssistantRunRequest {
    let mut retry_request = request.clone();
    retry_request.selected_scope = Some(retry_scope.clone());
    let mut startup_briefing = retry_request
        .startup_briefing
        .clone()
        .unwrap_or_else(|| json!({}));
    ensure_json_object(&mut startup_briefing);
    set_payload_value(
        &mut startup_briefing,
        "answerQualityGate",
        json!({
            "status": "retrying",
            "attempt": attempt_index,
            "budget": budget,
            "reactStepBudget": quality_budget.react_step_budget,
            "premiumActionBudget": quality_budget.premium_action_budget,
            "premiumActionUsed": 0,
            "reason": reason,
            "strategy": "Run ReAct to expand supply/read detail before producing customer-visible text.",
            "previousAnswerExcerpt": truncate_assistant_supply_text(previous_answer, 600),
            "instruction": "Do not repeat an insufficient/uncertain answer if supplied evidence can answer the question. Retrieve or read detail first, then answer directly from observations.",
        }),
    );
    retry_request.startup_briefing = Some(startup_briefing);
    retry_request
}

fn assistant_run_answer_quality_retry_evidence_state(
    mut evidence_state: Value,
    attempt_index: usize,
    quality_budget: &AssistantRunQualityBudget,
    reason: &str,
) -> Value {
    set_payload_value(
        &mut evidence_state,
        "answer_quality_gate",
        json!({
            "status": "retrying",
            "attempt": attempt_index,
            "budget": quality_budget.answer_retry_budget,
            "react_step_budget": quality_budget.react_step_budget,
            "premium_action_budget": quality_budget.premium_action_budget,
            "premium_action_used": 0,
            "vlm_upgrade_document_ids": [],
            "reason": reason,
            "strategy": "detail_first_react_expand_supply",
        }),
    );
    evidence_state
}

fn assistant_run_assistant_message_content_from_artifacts(artifacts: &[Value]) -> Option<String> {
    artifacts
        .iter()
        .find(|artifact| artifact.get("type").and_then(Value::as_str) == Some("assistant_message"))
        .and_then(|artifact| artifact.get("content").and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn assistant_run_react_attach_natural_fallback_runtime(
    runtime_manifest: &mut Value,
    reason: &str,
    fallback_runtime_manifest: Value,
) {
    if let Some(object) = runtime_manifest.as_object_mut() {
        object.insert(
            "natural_answer_fallback".to_string(),
            json!({
                "reason": reason,
                "runtime": fallback_runtime_manifest,
            }),
        );
    }
}

fn assistant_run_react_unavailable_natural_answer_message() -> String {
    "模型暂时没有返回可展示的自然语言回答，请稍后重试或换一种问法。".to_string()
}

async fn run_assistant_run_react_for_create(
    state: &AppState,
    request: &CreateAssistantRunRequest,
    active_assistant_run_id: AssistantRunId,
    selected_scope: &Value,
    initial_evidence_state: Value,
    local_thread_id: Option<&str>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    runtime_mode: &str,
    runtime_provider: &str,
    runtime_model: &str,
    chat_runtime: &LlmRuntimeSelection,
) -> std::result::Result<AssistantRunReactOutcome, ApiError> {
    let max_steps = assistant_run_react_max_steps();
    let mut evidence_state = initial_evidence_state;
    let mut observations = Vec::<Value>::new();
    let mut events = Vec::<AssistantRunReactEvent>::new();
    let mut execution_trail_steps = Vec::<Value>::new();
    let trace_id = Uuid::new_v4();
    let mut react_trace_steps = Vec::<Value>::new();
    let mut runtime_manifest = json!({
        "mode": runtime_mode,
        "provider": runtime_provider,
        "model": runtime_model,
        "react": {
            "enabled": true,
            "max_steps": max_steps,
        },
    });
    let mut assistant_message = String::new();

    for step_index in 1..=max_steps {
        let step_started = Instant::now();
        let provider_input = build_assistant_run_react_provider_input(
            request,
            Some(&evidence_state),
            &observations,
            step_index,
            max_steps,
        );
        let response = complete_assistant_run_provider(
            MODEL_LANE_ASSISTANT_REACT_JSON,
            runtime_mode.to_string(),
            runtime_provider.to_string(),
            runtime_model.to_string(),
            provider_input,
        )
        .await?;
        runtime_manifest = render_runtime_manifest(&response.runtime);

        let action = match parse_assistant_run_next_action(&response.output_text) {
            Ok(action) => action,
            Err(error) => {
                let fallback_reason = "invalid_action";
                let mut fallback = "safe_status_message";
                if let Some(answer) = assistant_run_react_direct_natural_answer_from_invalid_output(
                    &response.output_text,
                ) {
                    assistant_message = answer;
                    fallback = "direct_natural_model_text";
                } else {
                    let provider_input = build_assistant_run_react_natural_fallback_input(
                        build_assistant_run_provider_input_with_evidence(
                            request,
                            Some(&evidence_state),
                        ),
                        &observations,
                        fallback_reason,
                    );
                    if let Some((answer, fallback_runtime_manifest)) =
                        complete_assistant_run_react_natural_answer_fallback(
                            chat_runtime,
                            provider_input,
                        )
                        .await
                    {
                        assistant_message = answer;
                        fallback = "external_model_natural_answer";
                        assistant_run_react_attach_natural_fallback_runtime(
                            &mut runtime_manifest,
                            fallback_reason,
                            fallback_runtime_manifest,
                        );
                        events.push(AssistantRunReactEvent {
                            event_name: "assistant_run.react.natural_answer_fallback".to_string(),
                            payload: json!({
                                "step": step_index,
                                "reason": fallback_reason,
                                "fallback": fallback,
                            }),
                        });
                        execution_trail_steps.push(json!({
                            "status": "completed",
                            "label": "外部模型自然回答兜底",
                            "react_step": step_index,
                            "fallback": fallback,
                            "reason": fallback_reason,
                            "at": Utc::now(),
                        }));
                    }
                }
                if assistant_message.trim().is_empty() {
                    let _ = error;
                    assistant_message = assistant_run_react_unavailable_natural_answer_message();
                }
                events.push(AssistantRunReactEvent {
                    event_name: "assistant_run.react.invalid_action".to_string(),
                    payload: json!({
                        "step": step_index,
                        "safe_error_code": "invalid_action",
                        "fallback": fallback,
                    }),
                });
                react_trace_steps.push(assistant_run_react_invalid_trace_step(
                    trace_id,
                    Some(active_assistant_run_id),
                    step_index,
                    "invalid_action",
                    step_started.elapsed().as_millis(),
                ));
                execution_trail_steps.push(json!({
                    "status": "completed",
                    "label": "模型自然回答兜底",
                    "react_step": step_index,
                    "fallback": fallback,
                    "at": Utc::now(),
                }));
                break;
            }
        };

        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.action_requested".to_string(),
            payload: json!({
                "step": step_index,
                "action_type": action.action_type.as_str(),
                "reason_summary": redact_react_trace_text(&action.reason_summary, ASSISTANT_RUN_REACT_REASON_TRACE_LIMIT),
                "requires_confirmation": action.requires_confirmation,
            }),
        });

        let result = if let Some(repair) = build_react_protocol_repair_at_step(
            &action,
            &observations,
            selected_scope,
            &evidence_state,
            step_index,
        ) {
            Ok(repair)
        } else {
            execute_assistant_run_react_action(
                state,
                &action,
                selected_scope,
                &mut evidence_state,
                request.current_artifact.as_ref(),
                Some(active_assistant_run_id),
                request.prompt.trim(),
                local_thread_id,
                active_secret_binding_ids,
                current_user_id,
            )
            .await
        };

        let result = match result {
            Ok(result) => result,
            Err(_) => AssistantRunReactActionResult {
                observation: json!({
                    "status": "failed",
                    "action_type": action.action_type.as_str(),
                    "error_code": "tool_failed",
                }),
                trail_step: json!({
                    "status": "failed",
                    "label": assistant_run_react_action_label(&action.action_type),
                    "react_step": step_index,
                    "error_code": "tool_failed",
                    "at": Utc::now(),
                }),
                final_answer: None,
            },
        };

        let observation_summary = assistant_run_react_observation_summary(&result.observation);
        react_trace_steps.push(assistant_run_react_trace_step(
            trace_id,
            Some(active_assistant_run_id),
            step_index,
            &action,
            &observation_summary,
            step_started.elapsed().as_millis(),
        ));
        observations.push(result.observation.clone());
        execution_trail_steps.push(result.trail_step);
        events.push(AssistantRunReactEvent {
            event_name: if result.final_answer.is_some() {
                "assistant_run.react.final_answer".to_string()
            } else {
                "assistant_run.react.action_completed".to_string()
            },
            payload: assistant_run_react_completed_event_payload(
                step_index,
                action.action_type.as_str(),
                &observation_summary,
                None,
                &result.observation,
            ),
        });

        if let Some(final_answer) = result.final_answer {
            assistant_message = final_answer;
            break;
        }
    }

    if assistant_message.trim().is_empty() {
        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.step_limit_reached".to_string(),
            payload: json!({
                "max_steps": max_steps,
                "observation_count": observations.len(),
            }),
        });
        execution_trail_steps.push(json!({
            "status": "completed",
            "label": "达到连续执行上限",
            "max_steps": max_steps,
            "at": Utc::now(),
        }));
        let fallback_reason = "react_step_limit";
        let provider_input = build_assistant_run_react_natural_fallback_input(
            build_assistant_run_provider_input_with_evidence(request, Some(&evidence_state)),
            &observations,
            fallback_reason,
        );
        let mut fallback = "external_model_natural_answer";
        let mut fallback_result =
            complete_assistant_run_react_natural_answer_fallback(chat_runtime, provider_input)
                .await;
        if fallback_result.is_none() {
            fallback = "external_model_compact_natural_answer";
            let compact_provider_input = build_assistant_run_react_compact_natural_fallback_input(
                request.prompt.trim(),
                &evidence_state,
                &observations,
                fallback_reason,
            );
            fallback_result = complete_assistant_run_react_natural_answer_fallback(
                chat_runtime,
                compact_provider_input,
            )
            .await;
        }
        if let Some((answer, fallback_runtime_manifest)) = fallback_result {
            assistant_message = answer;
            assistant_run_react_attach_natural_fallback_runtime(
                &mut runtime_manifest,
                fallback_reason,
                fallback_runtime_manifest,
            );
            events.push(AssistantRunReactEvent {
                event_name: "assistant_run.react.natural_answer_fallback".to_string(),
                payload: json!({
                    "reason": fallback_reason,
                    "fallback": fallback,
                    "max_steps": max_steps,
                }),
            });
            execution_trail_steps.push(json!({
                "status": "completed",
                "label": "外部模型自然回答兜底",
                "fallback": fallback,
                "reason": fallback_reason,
                "at": Utc::now(),
            }));
        } else {
            assistant_message = assistant_run_react_step_limit_followup_message(&evidence_state);
        }
    }
    assistant_run_react_attach_trace(
        &mut runtime_manifest,
        trace_id,
        Some(active_assistant_run_id),
        &react_trace_steps,
    );
    execution_trail_steps.push(assistant_run_react_trace_trail_step(
        trace_id,
        Some(active_assistant_run_id),
        &react_trace_steps,
    ));

    let mut output_artifacts = vec![json!({
        "type": "assistant_message",
        "role": ChatMessageRole::Assistant.as_str(),
        "content": assistant_message,
        "source": "assistant_run_react",
    })];
    output_artifacts.extend(assistant_run_react_output_artifacts_from_observations(
        &observations,
    ));

    Ok(AssistantRunReactOutcome {
        runtime_manifest,
        evidence_state,
        execution_trail_steps,
        output_artifacts,
        events,
    })
}

async fn run_assistant_run_react_for_continue(
    state: &AppState,
    run: &AssistantRun,
    request: &ContinueAssistantRunRequest,
    continue_prompt: &str,
    selected_scope: &Value,
    max_steps: usize,
    initial_evidence_state: &mut Value,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    runtime_mode: &str,
    runtime_provider: &str,
    runtime_model: &str,
    chat_runtime: &LlmRuntimeSelection,
) -> std::result::Result<AssistantRunReactOutcome, ApiError> {
    let max_steps = max_steps.clamp(1, ASSISTANT_RUN_REACT_MAX_STEPS);
    let mut evidence_state = initial_evidence_state.clone();
    let mut observations = Vec::<Value>::new();
    let mut events = Vec::<AssistantRunReactEvent>::new();
    let mut execution_trail_steps = Vec::<Value>::new();
    let trace_id = Uuid::new_v4();
    let mut react_trace_steps = Vec::<Value>::new();
    let mut runtime_manifest = json!({
        "mode": runtime_mode,
        "provider": runtime_provider,
        "model": runtime_model,
        "react": {
            "enabled": true,
            "max_steps": max_steps,
            "entrypoint": "continue_assistant_run",
        },
    });
    let mut assistant_message = String::new();

    for step_index in 1..=max_steps {
        let step_started = Instant::now();
        let provider_input = build_assistant_run_react_continue_provider_input(
            run,
            request,
            continue_prompt,
            selected_scope,
            Some(&evidence_state),
            &observations,
            step_index,
            max_steps,
        );
        let response = complete_assistant_run_provider(
            MODEL_LANE_ASSISTANT_REACT_JSON,
            runtime_mode.to_string(),
            runtime_provider.to_string(),
            runtime_model.to_string(),
            provider_input,
        )
        .await?;
        runtime_manifest = render_runtime_manifest(&response.runtime);

        let action = match parse_assistant_run_next_action(&response.output_text) {
            Ok(action) => action,
            Err(error) => {
                let fallback_reason = "invalid_action";
                let mut fallback = "safe_status_message";
                if let Some(answer) = assistant_run_react_direct_natural_answer_from_invalid_output(
                    &response.output_text,
                ) {
                    assistant_message = answer;
                    fallback = "direct_natural_model_text";
                } else {
                    let provider_input = build_assistant_run_react_natural_fallback_input(
                        build_assistant_run_continue_provider_input(
                            run,
                            request,
                            continue_prompt,
                            selected_scope,
                            &evidence_state,
                            max_steps,
                        ),
                        &observations,
                        fallback_reason,
                    );
                    if let Some((answer, fallback_runtime_manifest)) =
                        complete_assistant_run_react_natural_answer_fallback(
                            chat_runtime,
                            provider_input,
                        )
                        .await
                    {
                        assistant_message = answer;
                        fallback = "external_model_natural_answer";
                        assistant_run_react_attach_natural_fallback_runtime(
                            &mut runtime_manifest,
                            fallback_reason,
                            fallback_runtime_manifest,
                        );
                        events.push(AssistantRunReactEvent {
                            event_name: "assistant_run.react.natural_answer_fallback".to_string(),
                            payload: json!({
                                "step": step_index,
                                "reason": fallback_reason,
                                "fallback": fallback,
                                "entrypoint": "continue_assistant_run",
                            }),
                        });
                        execution_trail_steps.push(json!({
                            "status": "completed",
                            "label": "外部模型自然回答兜底",
                            "react_step": step_index,
                            "fallback": fallback,
                            "reason": fallback_reason,
                            "at": Utc::now(),
                        }));
                    }
                }
                if assistant_message.trim().is_empty() {
                    let _ = error;
                    assistant_message = assistant_run_react_unavailable_natural_answer_message();
                }
                events.push(AssistantRunReactEvent {
                    event_name: "assistant_run.react.invalid_action".to_string(),
                    payload: json!({
                        "step": step_index,
                        "safe_error_code": "invalid_action",
                        "fallback": fallback,
                        "entrypoint": "continue_assistant_run",
                    }),
                });
                react_trace_steps.push(assistant_run_react_invalid_trace_step(
                    trace_id,
                    Some(run.id),
                    step_index,
                    "invalid_action",
                    step_started.elapsed().as_millis(),
                ));
                execution_trail_steps.push(json!({
                    "status": "completed",
                    "label": "模型自然回答兜底",
                    "react_step": step_index,
                    "fallback": fallback,
                    "at": Utc::now(),
                }));
                break;
            }
        };

        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.action_requested".to_string(),
            payload: json!({
                "step": step_index,
                "action_type": action.action_type.as_str(),
                "reason_summary": redact_react_trace_text(&action.reason_summary, ASSISTANT_RUN_REACT_REASON_TRACE_LIMIT),
                "requires_confirmation": action.requires_confirmation,
                "entrypoint": "continue_assistant_run",
            }),
        });

        let result = if let Some(repair) = build_react_protocol_repair_at_step(
            &action,
            &observations,
            selected_scope,
            &evidence_state,
            step_index,
        ) {
            Ok(repair)
        } else {
            execute_assistant_run_react_action(
                state,
                &action,
                selected_scope,
                &mut evidence_state,
                request.current_artifact.as_ref(),
                Some(run.id),
                continue_prompt.trim(),
                run.local_thread_id.as_deref(),
                active_secret_binding_ids,
                current_user_id,
            )
            .await
        };

        let result = match result {
            Ok(result) => result,
            Err(_) => AssistantRunReactActionResult {
                observation: json!({
                    "status": "failed",
                    "action_type": action.action_type.as_str(),
                    "error_code": "tool_failed",
                }),
                trail_step: json!({
                    "status": "failed",
                    "label": assistant_run_react_action_label(&action.action_type),
                    "react_step": step_index,
                    "error_code": "tool_failed",
                    "at": Utc::now(),
                }),
                final_answer: None,
            },
        };

        let observation_summary = assistant_run_react_observation_summary(&result.observation);
        react_trace_steps.push(assistant_run_react_trace_step(
            trace_id,
            Some(run.id),
            step_index,
            &action,
            &observation_summary,
            step_started.elapsed().as_millis(),
        ));
        observations.push(result.observation.clone());
        execution_trail_steps.push(result.trail_step);
        events.push(AssistantRunReactEvent {
            event_name: if result.final_answer.is_some() {
                "assistant_run.react.final_answer".to_string()
            } else {
                "assistant_run.react.action_completed".to_string()
            },
            payload: assistant_run_react_completed_event_payload(
                step_index,
                action.action_type.as_str(),
                &observation_summary,
                Some("continue_assistant_run"),
                &result.observation,
            ),
        });

        if let Some(final_answer) = result.final_answer {
            assistant_message = final_answer;
            break;
        }
    }

    if assistant_message.trim().is_empty() {
        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.step_limit_reached".to_string(),
            payload: json!({
                "max_steps": max_steps,
                "observation_count": observations.len(),
                "entrypoint": "continue_assistant_run",
            }),
        });
        execution_trail_steps.push(json!({
            "status": "completed",
            "label": "达到连续执行上限",
            "max_steps": max_steps,
            "at": Utc::now(),
        }));
        let fallback_reason = "react_step_limit";
        let provider_input = build_assistant_run_react_natural_fallback_input(
            build_assistant_run_continue_provider_input(
                run,
                request,
                continue_prompt,
                selected_scope,
                &evidence_state,
                max_steps,
            ),
            &observations,
            fallback_reason,
        );
        let mut fallback = "external_model_natural_answer";
        let mut fallback_result =
            complete_assistant_run_react_natural_answer_fallback(chat_runtime, provider_input)
                .await;
        if fallback_result.is_none() {
            fallback = "external_model_compact_natural_answer";
            let compact_provider_input = build_assistant_run_react_compact_natural_fallback_input(
                continue_prompt.trim(),
                &evidence_state,
                &observations,
                fallback_reason,
            );
            fallback_result = complete_assistant_run_react_natural_answer_fallback(
                chat_runtime,
                compact_provider_input,
            )
            .await;
        }
        if let Some((answer, fallback_runtime_manifest)) = fallback_result {
            assistant_message = answer;
            assistant_run_react_attach_natural_fallback_runtime(
                &mut runtime_manifest,
                fallback_reason,
                fallback_runtime_manifest,
            );
            events.push(AssistantRunReactEvent {
                event_name: "assistant_run.react.natural_answer_fallback".to_string(),
                payload: json!({
                    "reason": fallback_reason,
                    "fallback": fallback,
                    "max_steps": max_steps,
                    "entrypoint": "continue_assistant_run",
                }),
            });
            execution_trail_steps.push(json!({
                "status": "completed",
                "label": "外部模型自然回答兜底",
                "fallback": fallback,
                "reason": fallback_reason,
                "at": Utc::now(),
            }));
        } else {
            assistant_message = assistant_run_react_step_limit_followup_message(&evidence_state);
        }
    }

    assistant_run_react_attach_trace(
        &mut runtime_manifest,
        trace_id,
        Some(run.id),
        &react_trace_steps,
    );
    execution_trail_steps.push(assistant_run_react_trace_trail_step(
        trace_id,
        Some(run.id),
        &react_trace_steps,
    ));

    *initial_evidence_state = evidence_state.clone();
    let mut output_artifacts = vec![json!({
        "type": "assistant_message",
        "role": ChatMessageRole::Assistant.as_str(),
        "content": assistant_message,
        "source": "assistant_run_react_continue",
    })];
    output_artifacts.extend(assistant_run_react_output_artifacts_from_observations(
        &observations,
    ));

    Ok(AssistantRunReactOutcome {
        runtime_manifest,
        evidence_state,
        execution_trail_steps,
        output_artifacts,
        events,
    })
}

fn build_assistant_run_react_provider_input(
    request: &CreateAssistantRunRequest,
    evidence_state: Option<&Value>,
    observations: &[Value],
    step_index: usize,
    max_steps: usize,
) -> String {
    let null_value = Value::Null;
    let startup_briefing = request.startup_briefing.as_ref().unwrap_or(&null_value);
    let selected_scope = request.selected_scope.as_ref().unwrap_or(&null_value);
    let evidence_for_catalog = evidence_state.unwrap_or(&null_value);
    let planning_catalog = build_assistant_run_react_planning_catalog(
        startup_briefing,
        &request.scope_candidates,
        selected_scope,
        evidence_for_catalog,
    );
    let mut sections = vec![
        "你是智能数据工作台里的 Host-Controlled ReAct 运行时。".to_string(),
        "你只能提出下一步动作，不能假装已经执行平台动作。V3 Host 会验证、执行、记录并返回 observation。".to_string(),
        "只返回一个 JSON 对象，禁止 Markdown，禁止解释 JSON 外的文字。".to_string(),
        "JSON Schema: {\"action_type\":\"retrieve_evidence|web_search|read_document_detail|upgrade_parse_vlm|recall_conversation_memory|list_report_options|report_choice|resolve_video_url|extract_video_ppt_transcript|create_static_page_draft|update_static_page_module|submit_static_page_image_preview|render_static_page|create_report_draft|openclaw_memory_recall|openclaw_readonly_execution|codex_host_task|final_answer\",\"reason_summary\":\"给用户看的简短原因\",\"arguments\":{},\"requires_confirmation\":false}".to_string(),
        "目录、候选列表和系统说明只用于规划下一步，不是可引用证据。".to_string(),
        "选中数据集或对话记忆时，final_answer 必须基于已返回的 observation；否则先选择 retrieve_evidence、read_document_detail 或 recall_conversation_memory。".to_string(),
        "工具选择：retrieve_evidence 用于发现 V3 可见范围内的候选证据；web_search 用于请求 V3 受控外部/网页搜索证据，arguments 至少包含 query 和 reason；未收到带来源和时间的 V3 search evidence 前，不得声称已联网搜索或引用实时网页结果；read_document_detail 用于需要原文措辞、OCR、表格、音视频转写/场景或画像字段等细节时，document_id 必须来自选中范围或已返回 observation；upgrade_parse_vlm 是高成本内部解析修复动作，仅当 answerQualityGate/answer_quality_gate 显示 premium_action_budget > premium_action_used，且 PDF/图片/扫描件解析质量低、缺表格结构或 judge 明确要求升级解析时使用，arguments 必须包含可见 document_id，可选 page_hint/question_focus；它只返回 observation，不是最终答案；最终引用只能来自 observation。".to_string(),
        "如果弱规划目录或供料证据里出现 detailTargets，优先用其中的 document_id 调 read_document_detail；detailTargets 只是深读目标，不是可引用证据。".to_string(),
        "静态页或报表意图且存在数据集时，优先 retrieve_evidence；若需要模块数据、字段、表格/OCR 或原文措辞，继续 read_document_detail，再创建静态页/报表动作。".to_string(),
        "视频 PPT/原文提取：仅支持上传视频文件、直接视频 URL 或公开页面可解析视频地址；先用 resolve_video_url，已有登记视频素材后才用 extract_video_ppt_transcript；不要请求扫码、Cookie、登录态页面或录屏绕过。".to_string(),
        "如果当前打开产物是静态页草稿，用户要求修改标题、内容、图表、数据绑定或布局时，优先用 update_static_page_module；Host 只会把操作应用到当前已持久化草稿。".to_string(),
        "如果当前打开产物包含 structureSignals.sectionTitleHints，这些是供料给出的源文档结构线索；用于组织 docs-page 模块，但不要编造标题、接口细节或把标题当作完整内容。".to_string(),
        "如果弱规划目录或当前打开产物显示静态页 previewStale=true 或 previewStatus=stale，禁止直接 render_static_page；应先 submit_static_page_image_preview，等用户确认新的效果图后再渲染最终页。".to_string(),
        "静态页缺证决策：如果当前打开产物包含 missingEvidence.status=needs_evidence，先处理缺证，不要直接 submit_static_page_image_preview 或 render_static_page，除非用户明确接受部分草稿。".to_string(),
        "缺证 recommended_action/recommendedAction 映射：retrieve_evidence -> retrieve_evidence；read_document_detail -> read_document_detail，document_id 必须来自选中范围、detailTargets 或 observation；static_page.update_draft/update_static_page_module -> update_static_page_module，用于修复模块数据或保留缺失说明。".to_string(),
        "OpenClaw 和 Codex Host 都是可选外挂能力；openclaw_memory_recall、openclaw_readonly_execution、codex_host_task 可能被 Host 拒绝，不能绕过 V3 选中范围、记忆、任务隔离和执行 allowlist。".to_string(),
        "如果用户表达报表意图，先用 list_report_options；收到该 observation 后，才能用 report_choice，并只在 arguments.choice 填 continue_qa 或 create_report，不能编写报表正文。".to_string(),
        "如果已经可以回答，使用 action_type=final_answer，arguments.content 放最终正文。".to_string(),
        "final_answer 面向用户聊天框，只写自然语言结论、必要步骤和简短来源说明；禁止粘贴 observation JSON、execution_trail、react_trace、tool_trace、runtime_manifest、provider 原始载荷、私有路径或内部 URL。".to_string(),
        format!("当前 ReAct 步骤：{step_index}/{max_steps}"),
    ];
    sections.extend(assistant_run_v3_awareness_lines());
    sections.push(format!(
        "弱规划目录（只用于选择工具，不可直接作为回答证据）：{}",
        serde_json::to_string(&planning_catalog).unwrap_or_else(|_| "{}".to_string())
    ));
    if let Some(evidence_state) = evidence_state {
        if evidence_state.get("status").and_then(Value::as_str) != Some("not_requested") {
            if let Some(brief) = build_assistant_run_model_supply_brief(evidence_state) {
                sections.push(format!("供料综合提示：\n{brief}"));
            }
            let model_evidence_state = assistant_run_model_evidence_state(evidence_state);
            sections.push(format!(
                "可回答供料证据：{}",
                serde_json::to_string(&model_evidence_state).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if let Some(current_artifact) = request.current_artifact.as_ref() {
        let current_artifact_brief = assistant_run_current_artifact_brief(current_artifact);
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(&current_artifact_brief).unwrap_or_else(|_| "{}".to_string())
        ));
    }
    let history = request
        .messages
        .iter()
        .rev()
        .take(8)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("最近对话：\n{}", history.join("\n")));
    }
    if !observations.is_empty() {
        sections.push(format!(
            "已完成 observation：{}",
            serde_json::to_string(observations).unwrap_or_else(|_| "[]".to_string())
        ));
    }
    sections.push(format!("用户问题：{}", request.prompt.trim()));
    sections.join("\n\n")
}

fn build_assistant_run_react_continue_provider_input(
    run: &AssistantRun,
    request: &ContinueAssistantRunRequest,
    continue_prompt: &str,
    selected_scope: &Value,
    evidence_state: Option<&Value>,
    observations: &[Value],
    step_index: usize,
    max_steps: usize,
) -> String {
    let null_value = Value::Null;
    let scope_candidates = value_array(run.scope_candidates.clone());
    let evidence_for_catalog = evidence_state.unwrap_or(&null_value);
    let planning_catalog = build_assistant_run_react_planning_catalog(
        &run.startup_briefing,
        &scope_candidates,
        selected_scope,
        evidence_for_catalog,
    );
    let mut sections = vec![
        "你是智能数据工作台里的 Host-Controlled ReAct 继续执行运行时。".to_string(),
        "你只能提出下一步动作，不能假装已经执行平台动作。V3 Host 会验证、执行、记录并返回 observation。".to_string(),
        "只返回一个 JSON 对象，禁止 Markdown，禁止解释 JSON 外的文字。".to_string(),
        "JSON Schema: {\"action_type\":\"retrieve_evidence|web_search|read_document_detail|upgrade_parse_vlm|recall_conversation_memory|list_report_options|report_choice|resolve_video_url|extract_video_ppt_transcript|create_static_page_draft|update_static_page_module|submit_static_page_image_preview|render_static_page|create_report_draft|openclaw_memory_recall|openclaw_readonly_execution|codex_host_task|final_answer\",\"reason_summary\":\"给用户看的简短原因\",\"arguments\":{},\"requires_confirmation\":false}".to_string(),
        "目录、候选列表和系统说明只用于规划下一步，不是可引用证据。".to_string(),
        "选中数据集或对话记忆时，final_answer 必须基于已返回的 observation；否则先选择 retrieve_evidence、read_document_detail 或 recall_conversation_memory。".to_string(),
        "工具选择：retrieve_evidence 用于发现 V3 可见范围内的候选证据；web_search 用于请求 V3 受控外部/网页搜索证据，arguments 至少包含 query 和 reason；未收到带来源和时间的 V3 search evidence 前，不得声称已联网搜索或引用实时网页结果；read_document_detail 用于需要原文措辞、OCR、表格、音视频转写/场景或画像字段等细节时，document_id 必须来自选中范围或已返回 observation；upgrade_parse_vlm 是高成本内部解析修复动作，仅当 answerQualityGate/answer_quality_gate 显示 premium_action_budget > premium_action_used，且 PDF/图片/扫描件解析质量低、缺表格结构或 judge 明确要求升级解析时使用，arguments 必须包含可见 document_id，可选 page_hint/question_focus；它只返回 observation，不是最终答案；最终引用只能来自 observation。".to_string(),
        "如果弱规划目录或供料证据里出现 detailTargets，优先用其中的 document_id 调 read_document_detail；detailTargets 只是深读目标，不是可引用证据。".to_string(),
        "静态页或报表意图且存在数据集时，优先 retrieve_evidence；若需要模块数据、字段、表格/OCR 或原文措辞，继续 read_document_detail，再创建静态页/报表动作。".to_string(),
        "视频 PPT/原文提取：仅支持上传视频文件、直接视频 URL 或公开页面可解析视频地址；先用 resolve_video_url，已有登记视频素材后才用 extract_video_ppt_transcript；不要请求扫码、Cookie、登录态页面或录屏绕过。".to_string(),
        "如果当前打开产物是静态页草稿，用户要求修改标题、内容、图表、数据绑定或布局时，优先用 update_static_page_module；Host 只会把操作应用到当前已持久化草稿。".to_string(),
        "如果当前打开产物包含 structureSignals.sectionTitleHints，这些是供料给出的源文档结构线索；用于组织 docs-page 模块，但不要编造标题、接口细节或把标题当作完整内容。".to_string(),
        "如果弱规划目录或当前打开产物显示静态页 previewStale=true 或 previewStatus=stale，禁止直接 render_static_page；应先 submit_static_page_image_preview，等用户确认新的效果图后再渲染最终页。".to_string(),
        "静态页缺证决策：如果当前打开产物包含 missingEvidence.status=needs_evidence，先处理缺证，不要直接 submit_static_page_image_preview 或 render_static_page，除非用户明确接受部分草稿。".to_string(),
        "缺证 recommended_action/recommendedAction 映射：retrieve_evidence -> retrieve_evidence；read_document_detail -> read_document_detail，document_id 必须来自选中范围、detailTargets 或 observation；static_page.update_draft/update_static_page_module -> update_static_page_module，用于修复模块数据或保留缺失说明。".to_string(),
        "OpenClaw 和 Codex Host 都是可选外挂能力；openclaw_memory_recall、openclaw_readonly_execution、codex_host_task 可能被 Host 拒绝，不能绕过 V3 选中范围、记忆、任务隔离和执行 allowlist。".to_string(),
        "如果用户表达报表意图，先用 list_report_options；收到该 observation 后，才能用 report_choice，并只在 arguments.choice 填 continue_qa 或 create_report，不能编写报表正文。".to_string(),
        "如果已经可以回答，使用 action_type=final_answer，arguments.content 放最终正文。".to_string(),
        "final_answer 面向用户聊天框，只写自然语言结论、必要步骤和简短来源说明；禁止粘贴 observation JSON、execution_trail、react_trace、tool_trace、runtime_manifest、provider 原始载荷、私有路径或内部 URL。".to_string(),
        format!("当前 ReAct 步骤：{step_index}/{max_steps}"),
        format!("运行ID：{}", run.id),
        format!("原始问题：{}", run.user_prompt.trim()),
        format!("继续指令：{}", continue_prompt.trim()),
        format!(
            "弱规划目录（只用于选择工具，不可直接作为回答证据）：{}",
            serde_json::to_string(&planning_catalog).unwrap_or_else(|_| "{}".to_string())
        ),
    ];
    sections.extend(assistant_run_v3_awareness_lines());
    let pending_model_completion_requests =
        assistant_run_pending_model_completion_requests(&run.output_artifacts);
    if let Some(evidence_state) = evidence_state {
        if evidence_state.get("status").and_then(Value::as_str) != Some("not_requested") {
            if let Some(brief) = build_assistant_run_model_supply_brief(evidence_state) {
                sections.push(format!("供料综合提示：\n{brief}"));
            }
            let model_evidence_state = assistant_run_model_evidence_state(evidence_state);
            sections.push(format!(
                "可回答供料证据：{}",
                serde_json::to_string(&model_evidence_state).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }

    if let Some(current_artifact) = request.current_artifact.as_ref() {
        let current_artifact_brief = assistant_run_current_artifact_brief(current_artifact);
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(&current_artifact_brief).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    if !pending_model_completion_requests.is_empty() {
        sections.push("后台产物完成后存在模型接手请求：如果用户要求继续、查看结果、生成最终说明或确认视频/PPT任务状态，优先基于这些请求和已完成 observation 使用 final_answer，由模型自己写下一条助手消息。只能引用 ready_file_kinds、html_artifact_ids、warning_codes、missing_required_file_kinds、status 和 answer_contract 里的信息；不要声称缺失文件已就绪；不要展示私有路径、内部 URL、Cookie、Token、provider 原始载荷或本地文件系统路径；不要请求扫码、Cookie、登录态页面或录屏绕过。".to_string());
        sections.push(format!(
            "待模型接手的后台完成请求：{}",
            serde_json::to_string(&pending_model_completion_requests)
                .unwrap_or_else(|_| "[]".to_string())
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(8)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("继续前最近对话：\n{}", history.join("\n")));
    }
    if !observations.is_empty() {
        sections.push(format!(
            "已完成 observation：{}",
            serde_json::to_string(observations).unwrap_or_else(|_| "[]".to_string())
        ));
    }

    sections.join("\n\n")
}

fn assistant_run_pending_model_completion_requests(output_artifacts: &Value) -> Vec<Value> {
    value_array(output_artifacts.clone())
        .into_iter()
        .rev()
        .filter_map(|artifact| assistant_run_safe_model_completion_request(&artifact))
        .take(3)
        .collect()
}

fn assistant_run_safe_model_completion_request(artifact: &Value) -> Option<Value> {
    let request = assistant_run_model_completion_request_candidate(artifact)?;
    if request.get("kind").and_then(Value::as_str)
        != Some("video_extraction_model_completion_turn_request")
    {
        return None;
    }
    if request.get("required").and_then(Value::as_bool) != Some(true) {
        return None;
    }

    let mut safe = Map::new();
    assistant_run_copy_safe_scalar_fields(
        &mut safe,
        request,
        &[
            "kind",
            "version",
            "required",
            "turn_owner",
            "source_event",
            "instruction",
        ],
    );

    if let Some(context) = request.get("completion_context") {
        let mut safe_context = Map::new();
        assistant_run_copy_safe_scalar_fields(
            &mut safe_context,
            context,
            &[
                "title",
                "status",
                "warning_count",
                "has_pptx",
                "has_video_slides_markdown",
                "has_subtitle_page_map",
            ],
        );
        for key in [
            "ready_file_kinds",
            "html_artifact_ids",
            "warning_codes",
            "missing_required_file_kinds",
        ] {
            assistant_run_insert_safe_scalar_array_field(&mut safe_context, context, key, key, 20);
        }
        if let Some(primary_next_action) = context.get("primary_next_action") {
            if let Some(safe_action) =
                assistant_run_safe_model_completion_action(primary_next_action)
            {
                safe_context.insert("primary_next_action".to_string(), safe_action);
            }
        }
        if !safe_context.is_empty() {
            safe.insert(
                "completion_context".to_string(),
                Value::Object(safe_context),
            );
        }
    }

    if let Some(answer_contract) = request.get("answer_contract") {
        let mut safe_contract = Map::new();
        assistant_run_copy_safe_scalar_fields(
            &mut safe_contract,
            answer_contract,
            &[
                "must_write_in_model_voice",
                "must_reference_observation_only",
                "must_not_claim_missing_files",
                "must_not_include_private_paths_or_urls",
                "must_not_request_login_cookie_or_recording_bypass",
                "must_keep_missing_items_explicit",
                "no_host_composed_answer",
            ],
        );
        if !safe_contract.is_empty() {
            safe.insert("answer_contract".to_string(), Value::Object(safe_contract));
        }
    }

    let mut source_artifact = Map::new();
    assistant_run_copy_safe_scalar_fields(
        &mut source_artifact,
        artifact,
        &[
            "type",
            "id",
            "title",
            "assistant_run_id",
            "document_id",
            "dataset_id",
            "status",
        ],
    );
    if !source_artifact.is_empty() {
        safe.insert(
            "source_artifact".to_string(),
            Value::Object(source_artifact),
        );
    }

    (!safe.is_empty()).then_some(Value::Object(safe))
}

fn assistant_run_model_completion_request_candidate<'a>(artifact: &'a Value) -> Option<&'a Value> {
    for candidate in [
        artifact.get("model_completion_turn_request"),
        artifact.pointer("/completion_follow_up/model_follow_up"),
        artifact.pointer("/completionFollowUp/modelFollowUp"),
        artifact.pointer("/payload/model_completion_turn_request"),
        artifact.pointer("/payload/completion_follow_up/model_follow_up"),
        artifact.pointer("/payload/completionFollowUp/modelFollowUp"),
    ] {
        if candidate
            .and_then(|value| value.get("kind"))
            .and_then(Value::as_str)
            == Some("video_extraction_model_completion_turn_request")
        {
            return candidate;
        }
    }
    None
}

fn assistant_run_copy_safe_scalar_fields(
    target: &mut Map<String, Value>,
    source: &Value,
    keys: &[&str],
) {
    for key in keys {
        assistant_run_insert_safe_scalar_field(target, source, key, key);
    }
}

fn assistant_run_insert_safe_scalar_array_field(
    target: &mut Map<String, Value>,
    source: &Value,
    source_key: &str,
    target_key: &str,
    limit: usize,
) {
    if let Some(items) = source.get(source_key).and_then(Value::as_array) {
        let safe_items = items
            .iter()
            .take(limit)
            .filter_map(assistant_run_safe_artifact_scalar)
            .collect::<Vec<_>>();
        target.insert(target_key.to_string(), Value::Array(safe_items));
    }
}

fn assistant_run_safe_model_completion_action(action: &Value) -> Option<Value> {
    if let Some(value) = assistant_run_safe_artifact_scalar(action) {
        return Some(value);
    }

    let mut safe_action = Map::new();
    assistant_run_copy_safe_scalar_fields(
        &mut safe_action,
        action,
        &["kind", "action", "code", "label", "summary"],
    );
    (!safe_action.is_empty()).then_some(Value::Object(safe_action))
}

fn assistant_run_react_enabled(runtime_mode: &str) -> bool {
    runtime_mode != "placeholder" && env_flag("ASSISTANT_RUN_REACT_ENABLED", false)
}

fn assistant_run_react_max_steps() -> usize {
    std::env::var("ASSISTANT_RUN_REACT_MAX_STEPS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(ASSISTANT_RUN_REACT_DEFAULT_MAX_STEPS)
        .clamp(1, ASSISTANT_RUN_REACT_MAX_STEPS)
}

fn assistant_run_react_attach_trace(
    runtime_manifest: &mut Value,
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    trace_steps: &[Value],
) {
    let trace = assistant_run_react_trace_manifest(trace_id, assistant_run_id, trace_steps);
    if let Some(object) = runtime_manifest.as_object_mut() {
        object.insert("react_trace".to_string(), trace);
    } else {
        *runtime_manifest = json!({
            "runtime": runtime_manifest.clone(),
            "react_trace": trace,
        });
    }
}

fn assistant_run_react_trace_manifest(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    trace_steps: &[Value],
) -> Value {
    json!({
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "steps": trace_steps,
    })
}

fn assistant_run_react_trace_trail_step(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    trace_steps: &[Value],
) -> Value {
    json!({
        "status": "completed",
        "label": "ReAct 安全追踪",
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "step_count": trace_steps.len(),
        "react_trace": trace_steps,
        "at": Utc::now(),
    })
}

fn assistant_run_react_invalid_trace_step(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    pass_number: usize,
    safe_error_code: &str,
    duration_ms: u128,
) -> Value {
    json!({
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "pass_number": pass_number,
        "action_type": "invalid_action",
        "reason_summary": "",
        "status": "failed",
        "denied_count": 0,
        "returned_count": 0,
        "duration_ms": bounded_duration_ms(duration_ms),
        "safe_error_code": safe_error_code,
        "safe_message": "模型未返回有效动作",
    })
}

fn assistant_run_react_trace_step(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    pass_number: usize,
    action: &AssistantRunNextAction,
    observation_summary: &Value,
    duration_ms: u128,
) -> Value {
    json!({
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "pass_number": pass_number,
        "action_type": action.action_type.as_str(),
        "reason_summary": redact_react_trace_text(&action.reason_summary, ASSISTANT_RUN_REACT_REASON_TRACE_LIMIT),
        "status": observation_summary.get("status").and_then(Value::as_str).unwrap_or("unknown"),
        "denied_count": observation_summary.get("denied_count").and_then(Value::as_u64).unwrap_or(0),
        "returned_count": observation_summary.get("returned_count").and_then(Value::as_u64).unwrap_or(0),
        "detail_target_count": observation_summary.get("detail_target_count").and_then(Value::as_u64).unwrap_or(0),
        "duration_ms": bounded_duration_ms(duration_ms),
        "safe_error_code": observation_summary.get("safe_error_code").cloned().unwrap_or(Value::Null),
        "safe_message": observation_summary.get("safe_message").and_then(Value::as_str).unwrap_or(""),
    })
}

fn assistant_run_react_observation_summary(observation: &Value) -> Value {
    let status = observation
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let action_type = observation
        .get("action_type")
        .or_else(|| observation.get("actionType"))
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let denied_count = observation
        .get("denied")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or_default();
    let returned_count = assistant_run_react_returned_count(observation);
    let detail_target_count = observation
        .get("detail_target_count")
        .or_else(|| observation.get("detailTargetCount"))
        .and_then(Value::as_u64)
        .unwrap_or_default();
    let safe_error_code = observation
        .get("repair_code")
        .or_else(|| observation.get("error_code"))
        .and_then(Value::as_str)
        .map(|value| redact_react_trace_text(value, ASSISTANT_RUN_REACT_MESSAGE_TRACE_LIMIT))
        .or_else(|| {
            observation
                .get("error")
                .and_then(Value::as_str)
                .map(|_| "tool_failed".to_string())
        });
    let safe_message = observation
        .get("message")
        .and_then(Value::as_str)
        .map(|value| redact_react_trace_text(value, ASSISTANT_RUN_REACT_MESSAGE_TRACE_LIMIT))
        .or_else(|| {
            observation
                .get("error")
                .and_then(Value::as_str)
                .map(|_| "工具执行失败".to_string())
        })
        .unwrap_or_default();

    json!({
        "status": status,
        "action_type": action_type,
        "denied_count": denied_count,
        "returned_count": returned_count,
        "detail_target_count": detail_target_count,
        "safe_error_code": safe_error_code,
        "safe_message": safe_message,
    })
}

fn assistant_run_react_returned_count(observation: &Value) -> usize {
    if let Some(count) = observation
        .get("items")
        .and_then(Value::as_array)
        .map(Vec::len)
        .filter(|count| *count > 0)
    {
        return count;
    }
    if let Some(count) = observation
        .get("supplied_items")
        .and_then(Value::as_array)
        .map(Vec::len)
        .filter(|count| *count > 0)
    {
        return count;
    }
    observation
        .get("supplied_count")
        .and_then(Value::as_u64)
        .map(|value| value as usize)
        .unwrap_or_default()
}

fn bounded_duration_ms(duration_ms: u128) -> u64 {
    duration_ms.min(u64::MAX as u128) as u64
}

fn redact_react_trace_text(raw: &str, max_chars: usize) -> String {
    let value = raw.trim().chars().take(max_chars).collect::<String>();
    let lower = value.to_ascii_lowercase();
    if lower.contains("secret")
        || lower.contains("token")
        || lower.contains("password")
        || lower.contains("api_key")
        || lower.contains("apikey")
        || lower.contains("authorization")
        || lower.contains("bearer ")
        || lower.contains("sk-")
    {
        "[redacted]".to_string()
    } else {
        value
    }
}

#[allow(dead_code)]
pub(crate) fn build_react_protocol_repair(
    decision: &AssistantRunNextAction,
    observations: &[Value],
    selected_scope: &Value,
    evidence_state: &Value,
) -> Option<AssistantRunReactActionResult> {
    build_react_protocol_repair_at_step(decision, observations, selected_scope, evidence_state, 0)
}

fn build_react_protocol_repair_at_step(
    decision: &AssistantRunNextAction,
    observations: &[Value],
    selected_scope: &Value,
    evidence_state: &Value,
    step_index: usize,
) -> Option<AssistantRunReactActionResult> {
    if let Some(call_id) = assistant_run_react_replays_completed_tool_call(decision, observations) {
        return Some(build_assistant_run_react_policy_repair_result(
            decision,
            "duplicate tool-call replay detected; continue from the existing observation instead of replaying the same call.",
            step_index,
            vec![format!("tool_call:{call_id}")],
            "duplicate_tool_call_replay",
        ));
    }

    if let Some(pending) = assistant_run_react_pending_tool_output(observations) {
        let (message, repair_code) = if pending.repeated {
            (
                "tool-call liveness stall detected; request a continuation or choose a different whitelisted action.",
                "tool_call_liveness_stall",
            )
        } else {
            (
                "tool-call output is missing; wait for or repair the tool observation before continuing.",
                "missing_tool_output",
            )
        };
        return Some(build_assistant_run_react_policy_repair_result(
            decision,
            message,
            step_index,
            vec![format!("tool_call:{}", pending.call_id)],
            repair_code,
        ));
    }

    if assistant_run_react_should_repair_terminal_action(
        decision,
        selected_scope,
        evidence_state,
        observations,
    ) {
        return Some(assistant_run_react_policy_observation(
            decision,
            "final_answer requires a supply observation; choose a whitelisted action before answering.",
            step_index,
        ));
    }

    if decision.status == AssistantRunReActStatus::ReportChoice
        && !assistant_run_react_has_completed_action(observations, "list_report_options")
    {
        return Some(assistant_run_react_policy_observation(
            decision,
            "report_choice requires list_report_options observation before choosing a report path.",
            step_index,
        ));
    }

    if let Some(denied) = react_requested_scope_denial(decision, selected_scope) {
        return Some(build_assistant_run_react_policy_repair_result(
            decision,
            "requested dataset or document is outside the current selected scope.",
            step_index,
            vec![denied],
            "scope_denied",
        ));
    }

    if assistant_run_react_repeats_no_progress_action(decision, observations) {
        return Some(build_assistant_run_react_policy_repair_result(
            decision,
            "same no-progress action repeated; choose a different whitelisted action or cannot_answer.",
            step_index,
            vec![format!("repeated:{}", decision.action_type.as_str())],
            "repeated_no_progress_action",
        ));
    }

    None
}

struct AssistantRunReactPendingToolOutput {
    call_id: String,
    repeated: bool,
}

fn assistant_run_react_replays_completed_tool_call(
    decision: &AssistantRunNextAction,
    observations: &[Value],
) -> Option<String> {
    let call_id = assistant_run_react_call_id_from_value(&decision.arguments)?;
    let already_completed = observations.iter().any(|observation| {
        assistant_run_react_observation_call_id(observation).as_deref() == Some(call_id.as_str())
            && assistant_run_react_observation_status(observation).is_some_and(|status| {
                matches!(status, "completed" | "failed" | "rejected" | "denied")
            })
    });
    already_completed.then_some(call_id)
}

fn assistant_run_react_pending_tool_output(
    observations: &[Value],
) -> Option<AssistantRunReactPendingToolOutput> {
    let pending_observation = observations.iter().rev().find(|observation| {
        assistant_run_react_observation_status(observation).is_some_and(|status| {
            matches!(
                status,
                "tool_calls_emitted"
                    | "tool_call_requested"
                    | "pending_tool_output"
                    | "tool_output_missing"
            )
        })
    })?;
    let call_id = assistant_run_react_observation_call_id(pending_observation)?;
    let resolved = observations.iter().any(|observation| {
        assistant_run_react_observation_call_id(observation).as_deref() == Some(call_id.as_str())
            && assistant_run_react_observation_status(observation).is_some_and(|status| {
                matches!(status, "completed" | "failed" | "rejected" | "denied")
            })
    });
    if resolved {
        return None;
    }
    let repeated = observations
        .iter()
        .rev()
        .take(2)
        .filter(|observation| {
            assistant_run_react_observation_call_id(observation).as_deref()
                == Some(call_id.as_str())
                && assistant_run_react_observation_status(observation).is_some_and(|status| {
                    matches!(
                        status,
                        "tool_calls_emitted"
                            | "tool_call_requested"
                            | "pending_tool_output"
                            | "tool_output_missing"
                    )
                })
        })
        .count()
        >= 2;

    Some(AssistantRunReactPendingToolOutput { call_id, repeated })
}

fn assistant_run_react_call_id_from_value(value: &Value) -> Option<String> {
    value
        .get("tool_call_id")
        .or_else(|| value.get("toolCallId"))
        .or_else(|| value.get("call_id"))
        .or_else(|| value.get("callId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn assistant_run_react_observation_call_id(observation: &Value) -> Option<String> {
    assistant_run_react_call_id_from_value(observation).or_else(|| {
        observation
            .get("tool_call")
            .or_else(|| observation.get("toolCall"))
            .and_then(assistant_run_react_call_id_from_value)
    })
}

fn assistant_run_react_observation_status(observation: &Value) -> Option<&str> {
    observation
        .get("status")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn build_assistant_run_react_policy_repair_result(
    action: &AssistantRunNextAction,
    message: &str,
    step_index: usize,
    denied: Vec<String>,
    repair_code: &str,
) -> AssistantRunReactActionResult {
    AssistantRunReactActionResult {
        observation: json!({
            "status": "rejected",
            "action_type": "policy_observation",
            "actionType": "policy_observation",
            "message": message,
            "denied": denied,
            "items": [],
            "limits": {},
            "repair_required": true,
            "repair_code": repair_code,
            "step": step_index,
        }),
        trail_step: json!({
            "status": "rejected",
            "label": "ReAct 协议修复",
            "react_action": action.action_type.as_str(),
            "message": message,
            "react_step": step_index,
            "at": Utc::now(),
        }),
        final_answer: None,
    }
}

fn assistant_run_react_should_repair_terminal_action(
    action: &AssistantRunNextAction,
    selected_scope: &Value,
    evidence_state: &Value,
    observations: &[Value],
) -> bool {
    action.action_type == AssistantRunReactActionType::FinalAnswer
        && assistant_run_react_scope_requires_supply(selected_scope)
        && !assistant_run_react_has_supply_observation(evidence_state, observations)
}

fn assistant_run_react_has_completed_action(observations: &[Value], action_type: &str) -> bool {
    observations.iter().any(|observation| {
        observation
            .get("status")
            .and_then(Value::as_str)
            .is_some_and(|status| status == "completed")
            && observation
                .get("action_type")
                .or_else(|| observation.get("actionType"))
                .and_then(Value::as_str)
                .is_some_and(|value| value == action_type)
    })
}

fn assistant_run_react_repeats_no_progress_action(
    decision: &AssistantRunNextAction,
    observations: &[Value],
) -> bool {
    let action_type = decision.action_type.as_str();
    observations
        .iter()
        .rev()
        .take(2)
        .filter(|observation| {
            observation
                .get("status")
                .and_then(Value::as_str)
                .is_some_and(|status| matches!(status, "rejected" | "failed" | "denied"))
                && observation
                    .get("action_type")
                    .or_else(|| observation.get("actionType"))
                    .and_then(Value::as_str)
                    .is_some_and(|value| value == action_type)
        })
        .count()
        >= 2
}

fn react_requested_scope_denial(
    decision: &AssistantRunNextAction,
    selected_scope: &Value,
) -> Option<String> {
    let requested_dataset_id = decision
        .arguments
        .get("dataset_id")
        .or_else(|| decision.arguments.get("datasetId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if let Some(requested_dataset_id) = requested_dataset_id {
        let selected_dataset_ids = selected_dataset_ids_from_scope(selected_scope);
        let requested = Uuid::parse_str(requested_dataset_id).ok().map(DatasetId);
        if requested.is_none_or(|requested| !selected_dataset_ids.contains(&requested)) {
            return Some(format!("dataset:{requested_dataset_id}"));
        }
    }

    let requested_document_id = decision
        .arguments
        .get("document_id")
        .or_else(|| decision.arguments.get("documentId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if let Some(requested_document_id) = requested_document_id {
        let selected_document_ids = selected_document_ids_from_scope(selected_scope);
        let requested = Uuid::parse_str(requested_document_id).ok().map(DocumentId);
        if !selected_document_ids.is_empty()
            && requested.is_none_or(|requested| !selected_document_ids.contains(&requested))
        {
            return Some(format!("document:{requested_document_id}"));
        }
    }

    None
}

fn assistant_run_react_scope_requires_supply(selected_scope: &Value) -> bool {
    assistant_run_scope_intent(selected_scope) != "ordinary_chat"
        && (!selected_dataset_ids_from_scope(selected_scope).is_empty()
            || selected_scope_requests_conversation_memory(selected_scope))
}

fn assistant_run_react_has_supply_observation(
    evidence_state: &Value,
    observations: &[Value],
) -> bool {
    assistant_run_evidence_supplied_count(evidence_state) > 0
        || observations.iter().any(|observation| {
            observation
                .get("status")
                .and_then(Value::as_str)
                .is_some_and(|status| status == "completed")
                && observation
                    .get("action_type")
                    .or_else(|| observation.get("actionType"))
                    .and_then(Value::as_str)
                    .is_some_and(|action_type| {
                        matches!(
                            action_type,
                            "retrieve_evidence"
                                | "read_document_detail"
                                | "upgrade_parse_vlm"
                                | "recall_conversation_memory"
                        )
                    })
        })
}

fn ensure_react_requested_dataset_is_selected(
    arguments: &Value,
    selected_scope: &Value,
) -> std::result::Result<(), ApiError> {
    let Some(requested_dataset_id) = arguments
        .get("dataset_id")
        .or_else(|| arguments.get("datasetId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(());
    };
    let requested_dataset_id = Uuid::parse_str(requested_dataset_id)
        .map(DatasetId)
        .map_err(|_| {
            ApiError::bad_request("invalid_react_action", "dataset_id is invalid".to_string())
        })?;
    if selected_dataset_ids_from_scope(selected_scope)
        .into_iter()
        .any(|dataset_id| dataset_id == requested_dataset_id)
    {
        return Ok(());
    }
    Err(ApiError::bad_request(
        "react_dataset_not_selected",
        "ReAct retrieve_evidence can only use the current selected dataset scope".to_string(),
    ))
}

fn ensure_scope_requests_conversation_memory(mut selected_scope: Value) -> Value {
    ensure_json_object(&mut selected_scope);
    if let Some(object) = selected_scope.as_object_mut() {
        let should_insert_default = object
            .get("conversation_memory")
            .and_then(Value::as_array)
            .map(|items| {
                !items.iter().any(|item| {
                    item.as_str()
                        .map(str::trim)
                        .map(|value| !value.is_empty())
                        .unwrap_or(false)
                })
            })
            .unwrap_or(true);
        if should_insert_default {
            object.insert("conversation_memory".to_string(), json!(["current_thread"]));
        }
    }
    selected_scope
}

fn react_static_page_operations_from_arguments(
    arguments: &Value,
) -> std::result::Result<Vec<Value>, ApiError> {
    let operations = if let Some(operations) = arguments.get("operations").and_then(Value::as_array)
    {
        operations.clone()
    } else {
        let module_id = arguments
            .get("module_id")
            .or_else(|| arguments.get("moduleId"))
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                ApiError::bad_request(
                    "invalid_react_action",
                    "update_static_page_module requires module_id or operations".to_string(),
                )
            })?;
        let patch = arguments.get("patch").cloned().ok_or_else(|| {
            ApiError::bad_request(
                "invalid_react_action",
                "update_static_page_module requires patch or operations".to_string(),
            )
        })?;
        vec![json!({
            "type": "update_module",
            "targetModuleId": module_id,
            "patch": patch,
        })]
    };
    validate_static_page_operations(operations)
}

fn env_flag(key: &str, default_value: bool) -> bool {
    std::env::var(key)
        .ok()
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(default_value)
}

fn assistant_run_is_plain_ordinary_chat_scope(
    selected_scope: Option<&Value>,
    evidence_state: Option<&Value>,
    current_artifact: Option<&Value>,
) -> bool {
    if current_artifact.is_some() {
        return false;
    }
    let Some(selected_scope) = selected_scope else {
        return true;
    };
    let no_selected_supply = selected_dataset_ids_from_scope(selected_scope).is_empty()
        && selected_document_ids_from_scope(selected_scope).is_empty()
        && !selected_scope_requests_conversation_memory(selected_scope);
    let ordinary_intent = assistant_run_scope_intent(selected_scope) == "ordinary_chat";
    let no_evidence = evidence_state
        .and_then(|state| state.get("status"))
        .and_then(Value::as_str)
        .map(|status| matches!(status, "not_requested" | "empty"))
        .unwrap_or(true)
        && evidence_state
            .map(|state| assistant_run_evidence_supplied_count(state) == 0)
            .unwrap_or(true);

    ordinary_intent && no_selected_supply && no_evidence
}

fn assistant_run_react_enabled_for_scope(
    runtime_mode: &str,
    selected_scope: &Value,
    current_artifact: Option<&Value>,
) -> bool {
    assistant_run_react_enabled(runtime_mode)
        && assistant_run_react_scope_allows_tools(selected_scope, current_artifact)
}

fn assistant_run_react_scope_allows_tools(
    selected_scope: &Value,
    current_artifact: Option<&Value>,
) -> bool {
    (assistant_run_scope_intent(selected_scope) != "ordinary_chat" || current_artifact.is_some())
        && !assistant_run_is_plain_ordinary_chat_scope(Some(selected_scope), None, current_artifact)
}

#[derive(Clone, Debug)]
struct AssistantRunExecutorTransportSelection {
    effective_transport: AssistantRunExecutorTransportView,
    policy: Value,
}

fn assistant_run_executor_transport_selection_from_env(
) -> Option<AssistantRunExecutorTransportSelection> {
    std::env::var("ASSISTANT_RUN_EXECUTOR")
        .ok()
        .and_then(|value| {
            assistant_run_executor_transport_selection_from_value(
                &value,
                assistant_run_codex_real_transport_feature_gate_enabled(),
                assistant_run_codex_real_transport_promotion_review_approved(),
            )
        })
}

fn assistant_run_executor_transport_selection_from_value(
    value: &str,
    real_transport_feature_gate_enabled: bool,
    real_transport_promotion_review_approved: bool,
) -> Option<AssistantRunExecutorTransportSelection> {
    let requested_transport = assistant_run_executor_transport_from_value(value)?;
    let real_transport_requested = assistant_run_executor_transport_is_real(&requested_transport);
    let real_transport_allowed = !real_transport_requested
        || (real_transport_feature_gate_enabled && real_transport_promotion_review_approved);
    let downgraded = real_transport_requested && !real_transport_allowed;
    let effective_transport = if downgraded {
        AssistantRunExecutorTransportView::CodexPlanOnly
    } else {
        requested_transport.clone()
    };
    let downgrade_reason = if real_transport_requested && !real_transport_feature_gate_enabled {
        json!("real_transport_feature_gate_disabled")
    } else if real_transport_requested && !real_transport_promotion_review_approved {
        json!("real_transport_promotion_review_not_approved")
    } else if downgraded {
        json!("real_transport_not_allowed")
    } else {
        Value::Null
    };
    let next_step = if real_transport_requested && !real_transport_feature_gate_enabled {
        "keep_codex_in_shadow_plan_only_until_promotion_gate_review"
    } else if real_transport_requested && !real_transport_promotion_review_approved {
        "review_shadow_and_host_reports_before_enabling_real_transport"
    } else if real_transport_requested {
        "assistant_runtime_still_validates_real_transport_before_execution"
    } else {
        "run_codex_shadow_transport"
    };

    Some(AssistantRunExecutorTransportSelection {
        effective_transport: effective_transport.clone(),
        policy: json!({
            "requested_transport": requested_transport.as_str(),
            "effective_transport": effective_transport.as_str(),
            "real_transport_requested": real_transport_requested,
            "real_transport_feature_gate_enabled": real_transport_feature_gate_enabled,
            "real_transport_promotion_review_approved": real_transport_promotion_review_approved,
            "downgraded": downgraded,
            "downgrade_reason": downgrade_reason,
            "direct_execution_authoritative": true,
            "codex_mutation_allowed": false,
            "queue_allowed": false,
            "manual_feature_gate_required_for_real_transport": real_transport_requested,
            "promotion_review_required_for_real_transport": real_transport_requested,
            "host_validation_required_for_real_transport": real_transport_requested,
            "next_step": next_step,
        }),
    })
}

fn assistant_run_executor_transport_is_real(transport: &AssistantRunExecutorTransportView) -> bool {
    matches!(
        transport,
        AssistantRunExecutorTransportView::CodexExecSchema
            | AssistantRunExecutorTransportView::CodexSdkThread
            | AssistantRunExecutorTransportView::CodexAppServer
            | AssistantRunExecutorTransportView::CodexMcpServer
    )
}

fn assistant_run_codex_real_transport_feature_gate_enabled() -> bool {
    std::env::var("ASSISTANT_RUN_CODEX_REAL_TRANSPORT_FEATURE_GATE")
        .ok()
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "enabled" | "on" | "yes"
            )
        })
        .unwrap_or(false)
}

fn assistant_run_codex_real_transport_promotion_review_approved() -> bool {
    std::env::var("ASSISTANT_RUN_CODEX_REAL_TRANSPORT_PROMOTION_REVIEW_APPROVED")
        .ok()
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "approved" | "enabled" | "on" | "yes"
            )
        })
        .unwrap_or(false)
}

fn assistant_run_executor_transport_from_value(
    value: &str,
) -> Option<AssistantRunExecutorTransportView> {
    match value.trim().to_ascii_lowercase().as_str() {
        "" | "direct" => None,
        "codex" | "codex_dry_run" | "dry_run" | "shadow" | "shadow_dry_run" => {
            Some(AssistantRunExecutorTransportView::CodexDryRun)
        }
        "codex_plan_only" | "plan_only" | "plan" => {
            Some(AssistantRunExecutorTransportView::CodexPlanOnly)
        }
        "codex_exec_schema" | "exec_schema" => {
            Some(AssistantRunExecutorTransportView::CodexExecSchema)
        }
        "codex_sdk_thread" | "sdk_thread" => {
            Some(AssistantRunExecutorTransportView::CodexSdkThread)
        }
        "codex_app_server" | "app_server" => {
            Some(AssistantRunExecutorTransportView::CodexAppServer)
        }
        "codex_mcp_server" | "mcp_server" => {
            Some(AssistantRunExecutorTransportView::CodexMcpServer)
        }
        _ => None,
    }
}

fn build_assistant_run_codex_context_package(
    assistant_run_id: AssistantRunId,
    local_thread_id: Option<&str>,
    user_prompt: &str,
    messages: &[AssistantRunMessageView],
    startup_briefing: &Value,
    selected_scope: &Value,
    scope_candidates: &[Value],
    evidence_state: &Value,
    current_artifact: Option<&Value>,
    model_gateway: &Value,
    executor_transport: AssistantRunExecutorTransportView,
) -> AssistantRunCodexContextPackageView {
    let mut package =
        AssistantRunCodexContextPackageView::new(assistant_run_id, user_prompt.trim());
    let tool_output_policy = assistant_run_codex_tool_output_policy();
    let bounded_evidence_state =
        assistant_run_codex_bounded_evidence_state(evidence_state, &tool_output_policy);
    package.executor_transport = executor_transport;
    package.local_thread_id = local_thread_id.map(ToString::to_string);
    package.messages = messages.to_vec();
    package.startup_briefing = startup_briefing.clone();
    package.selected_scope = selected_scope.clone();
    package.inferred_scope_candidates = scope_candidates.to_vec();
    package.evidence_state = bounded_evidence_state.clone();
    package.supply_quality = assistant_run_codex_supply_quality(&bounded_evidence_state);
    package.model_gateway = model_gateway.clone();
    package.hidden_memory_candidates =
        assistant_run_codex_hidden_memory_candidates(&bounded_evidence_state);
    package.current_artifact = current_artifact.cloned();
    package.available_actions = assistant_run_codex_action_contracts(selected_scope);
    package.tool_output_policy = tool_output_policy;
    package.context_budget = assistant_run_codex_context_budget(
        user_prompt,
        messages,
        startup_briefing,
        selected_scope,
        scope_candidates,
        &bounded_evidence_state,
        current_artifact,
    );
    package
}

fn assistant_run_codex_runtime_selection() -> LlmRuntimeSelection {
    resolve_runtime_selection_from_env(
        "ASSISTANT_RUN_CODEX",
        MODEL_LANE_CODEX_CONVERSATION,
        DEFAULT_ASSISTANT_RUN_CODEX_RUNTIME_MODEL,
    )
}

fn assistant_run_codex_model_gateway_snapshot(runtime: &LlmRuntimeSelection) -> Value {
    let profile_env_prefix = std::env::var("ASSISTANT_RUN_CODEX_MODEL_PROFILE_ENV")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let profile = profile_env_prefix
        .as_deref()
        .and_then(|prefix| ModelProviderProfile::from_env(prefix).ok())
        .map(|profile| profile.public_manifest());
    let profile_status = match (&profile_env_prefix, &profile) {
        (Some(_), Some(_)) => "profile_loaded",
        (Some(_), None) => "profile_unavailable",
        (None, _) => "runtime_selection_only",
    };
    let profile_source = if profile.is_some() {
        "model_provider_profile_env"
    } else {
        "llm_gateway_runtime_selection"
    };

    json!({
        "lane": runtime.lane.as_str(),
        "selected_model": {
            "mode": runtime.mode.as_str(),
            "provider": runtime.provider.as_str(),
            "model": runtime.model.as_str(),
        },
        "profile_source": profile_source,
        "profile_status": profile_status,
        "profile_env_prefix": profile_env_prefix,
        "profile": profile.unwrap_or_else(|| assistant_run_codex_runtime_selection_profile(runtime)),
        "safety": {
            "secrets_redacted": true,
            "raw_provider_payloads_allowed": false,
            "codex_real_execution_allowed_on_this_host": false,
            "v3_validates_all_actions": true,
        }
    })
}

fn assistant_run_codex_runtime_selection_profile(runtime: &LlmRuntimeSelection) -> Value {
    json!({
        "profile_id": format!("{}:{}", runtime.provider, runtime.model),
        "provider_id": runtime.provider.as_str(),
        "model_id": runtime.model.as_str(),
        "wire_api": if runtime.mode == "placeholder" {
            "placeholder"
        } else {
            "runtime_selection"
        },
        "auth": {
            "env_key_name": Value::Null,
            "configured": runtime.mode == "placeholder",
        },
        "capabilities": [],
        "redaction": {
            "redact_provider_errors": true,
            "redact_request_payloads": true,
            "redact_response_payloads": true,
        }
    })
}

fn assistant_run_codex_supply_quality(evidence_state: &Value) -> Value {
    evidence_state
        .get("supply_quality")
        .or_else(|| evidence_state.get("supplyQuality"))
        .cloned()
        .unwrap_or_else(|| {
            json!({
                "status": "unknown",
                "modelGuidance": [
                    "supply quality report was not present in this evidence state",
                    "treat evidence_state.status and supplied_items conservatively"
                ]
            })
        })
}

fn assistant_run_codex_tool_output_policy() -> AssistantRunCodexToolOutputPolicyView {
    AssistantRunCodexToolOutputPolicyView {
        max_total_chars: assistant_run_codex_env_usize(
            "ASSISTANT_RUN_CODEX_TOOL_OUTPUT_MAX_TOTAL_CHARS",
            80_000,
        ),
        max_item_chars: assistant_run_codex_env_usize(
            "ASSISTANT_RUN_CODEX_TOOL_OUTPUT_MAX_ITEM_CHARS",
            16_000,
        ),
        preserve_recent_output_count: assistant_run_codex_env_usize(
            "ASSISTANT_RUN_CODEX_TOOL_OUTPUT_PRESERVE_RECENT",
            3,
        ),
        preserve_error_fields: env_flag("ASSISTANT_RUN_CODEX_TOOL_OUTPUT_PRESERVE_ERRORS", true),
        preserve_evidence_refs: env_flag("ASSISTANT_RUN_CODEX_TOOL_OUTPUT_PRESERVE_REFS", true),
        preserve_media_timestamps: env_flag(
            "ASSISTANT_RUN_CODEX_TOOL_OUTPUT_PRESERVE_MEDIA_TIMESTAMPS",
            true,
        ),
    }
}

fn assistant_run_codex_env_usize(key: &str, default_value: usize) -> usize {
    std::env::var(key)
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(default_value)
}

fn assistant_run_codex_bounded_evidence_state(
    evidence_state: &Value,
    policy: &AssistantRunCodexToolOutputPolicyView,
) -> Value {
    let mut bounded = evidence_state.clone();
    let Some(object) = bounded.as_object_mut() else {
        return bounded;
    };
    let Some(tool_outputs) = object.get_mut("tool_outputs").and_then(Value::as_array_mut) else {
        return bounded;
    };

    let total_output_count = tool_outputs.len();
    let mut trimmed_output_count = 0_usize;
    let mut trimmed_field_count = 0_usize;
    let mut largest_output_chars = 0_usize;
    let mut total_chars = 0_usize;
    for (index, output) in tool_outputs.iter_mut().enumerate() {
        let is_recent =
            total_output_count.saturating_sub(index) <= policy.preserve_recent_output_count;
        let before_chars = assistant_run_codex_value_chars(output);
        largest_output_chars = largest_output_chars.max(before_chars);
        total_chars = total_chars.saturating_add(before_chars);
        let trim_result = assistant_run_codex_trim_tool_output_value(output, policy, is_recent);
        if trim_result.trimmed {
            trimmed_output_count += 1;
            trimmed_field_count += trim_result.trimmed_field_count;
        }
    }

    let existing_trimmed_count = object
        .get("trimmed_item_count")
        .or_else(|| object.get("trimmedItemCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    if trimmed_output_count > 0 {
        object.insert(
            "trimmed_item_count".to_string(),
            json!(existing_trimmed_count + trimmed_output_count as u64),
        );
    }
    object.insert(
        "codex_tool_output_budget".to_string(),
        json!({
            "policy": policy,
            "tool_output_count": total_output_count,
            "trimmed_output_count": trimmed_output_count,
            "trimmed_field_count": trimmed_field_count,
            "largest_output_chars": largest_output_chars,
            "estimated_total_chars_before_trim": total_chars,
            "preserves": {
                "recent_output_count": policy.preserve_recent_output_count,
                "error_fields": policy.preserve_error_fields,
                "evidence_refs": policy.preserve_evidence_refs,
                "media_timestamps": policy.preserve_media_timestamps,
            }
        }),
    );
    bounded
}

#[derive(Default)]
struct AssistantRunCodexTrimResult {
    trimmed: bool,
    trimmed_field_count: usize,
}

fn assistant_run_codex_trim_tool_output_value(
    value: &mut Value,
    policy: &AssistantRunCodexToolOutputPolicyView,
    is_recent: bool,
) -> AssistantRunCodexTrimResult {
    match value {
        Value::Object(object) => {
            let mut result = AssistantRunCodexTrimResult::default();
            let mut trimmed_fields = Vec::new();
            let keys: Vec<String> = object.keys().cloned().collect();
            for key in keys {
                let Some(child) = object.get_mut(&key) else {
                    continue;
                };
                if let Value::String(text) = child {
                    if assistant_run_codex_should_trim_tool_output_field(&key, policy) {
                        let item_limit =
                            assistant_run_codex_tool_output_item_limit(policy, is_recent);
                        if let Some(trimmed) = assistant_run_codex_trim_text_value(text, item_limit)
                        {
                            *text = trimmed;
                            result.trimmed = true;
                            result.trimmed_field_count += 1;
                            trimmed_fields.push(key);
                        }
                    }
                    continue;
                }
                let nested = assistant_run_codex_trim_tool_output_value(child, policy, is_recent);
                if nested.trimmed {
                    result.trimmed = true;
                    result.trimmed_field_count += nested.trimmed_field_count;
                }
            }
            if !trimmed_fields.is_empty() {
                object.insert("codex_trimmed_fields".to_string(), json!(trimmed_fields));
            }
            result
        }
        Value::Array(items) => items.iter_mut().fold(
            AssistantRunCodexTrimResult::default(),
            |mut result, item| {
                let nested = assistant_run_codex_trim_tool_output_value(item, policy, is_recent);
                if nested.trimmed {
                    result.trimmed = true;
                    result.trimmed_field_count += nested.trimmed_field_count;
                }
                result
            },
        ),
        _ => AssistantRunCodexTrimResult::default(),
    }
}

fn assistant_run_codex_tool_output_item_limit(
    policy: &AssistantRunCodexToolOutputPolicyView,
    is_recent: bool,
) -> usize {
    if is_recent {
        policy
            .max_item_chars
            .saturating_mul(2)
            .min(policy.max_total_chars)
            .max(policy.max_item_chars)
    } else {
        policy.max_item_chars
    }
}

fn assistant_run_codex_should_trim_tool_output_field(
    key: &str,
    policy: &AssistantRunCodexToolOutputPolicyView,
) -> bool {
    let lower = key.to_ascii_lowercase();
    if policy.preserve_evidence_refs
        && ["id", "ref", "refs", "citation", "source", "locator"]
            .iter()
            .any(|needle| lower.contains(needle))
    {
        return false;
    }
    if policy.preserve_media_timestamps
        && [
            "timestamp",
            "timestamps",
            "time_window",
            "timecode",
            "start_ms",
            "end_ms",
        ]
        .iter()
        .any(|needle| lower.contains(needle))
    {
        return false;
    }
    if policy.preserve_error_fields
        && ["error_code", "failure_kind", "exit_code", "status"]
            .iter()
            .any(|needle| lower.contains(needle))
    {
        return false;
    }
    [
        "content",
        "output",
        "stdout",
        "stderr",
        "text",
        "body",
        "raw",
        "transcript",
        "result",
        "message",
        "error",
        "failure",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

fn assistant_run_codex_trim_text_value(value: &str, max_chars: usize) -> Option<String> {
    let original_chars = value.chars().count();
    if original_chars <= max_chars {
        return None;
    }
    if max_chars < 80 {
        return Some(format!(
            "[codex-trimmed original_chars={original_chars} kept_chars=0]"
        ));
    }
    let marker = format!(
        "\n[codex-trimmed original_chars={} omitted_chars={}]\n",
        original_chars,
        original_chars.saturating_sub(max_chars)
    );
    let marker_chars = marker.chars().count();
    let kept_chars = max_chars.saturating_sub(marker_chars).max(2);
    let head_chars = kept_chars / 2;
    let tail_chars = kept_chars.saturating_sub(head_chars);
    let head: String = value.chars().take(head_chars).collect();
    let tail_reversed: String = value.chars().rev().take(tail_chars).collect();
    let tail: String = tail_reversed.chars().rev().collect();
    Some(format!("{head}{marker}{tail}"))
}

fn assistant_run_codex_hidden_memory_candidates(evidence_state: &Value) -> Vec<Value> {
    evidence_state
        .get("conversation_memory_items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
}

fn assistant_run_codex_context_budget(
    user_prompt: &str,
    messages: &[AssistantRunMessageView],
    startup_briefing: &Value,
    selected_scope: &Value,
    scope_candidates: &[Value],
    evidence_state: &Value,
    current_artifact: Option<&Value>,
) -> AssistantRunCodexContextBudgetView {
    let max_prompt_chars = std::env::var("ASSISTANT_RUN_CODEX_MAX_PROMPT_CHARS")
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok());
    let category_soft_limit = std::env::var("ASSISTANT_RUN_CODEX_CATEGORY_SOFT_LIMIT_CHARS")
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .or_else(|| max_prompt_chars.map(|value| value.saturating_div(4).max(1)))
        .or(Some(12_000));
    let supplied_items = evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let hidden_memory_items = assistant_run_codex_hidden_memory_candidates(evidence_state);
    let detail_targets = evidence_state
        .get("detail_targets")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let artifact_state_chars = current_artifact
        .and_then(|artifact| serde_json::to_string(artifact).ok())
        .map(|value| value.chars().count())
        .unwrap_or(0);
    let tool_output_chars = serde_json::to_string(evidence_state)
        .map(|value| value.chars().count())
        .unwrap_or(0);
    let trimmed_item_count = evidence_state
        .get("trimmed_item_count")
        .or_else(|| evidence_state.get("trimmedItemCount"))
        .and_then(Value::as_u64)
        .map(|value| value as usize)
        .unwrap_or(0);
    let prompt_and_history_chars = user_prompt.chars().count()
        + messages
            .iter()
            .map(|message| message.content.chars().count())
            .sum::<usize>();
    let startup_briefing_chars = assistant_run_codex_value_chars(startup_briefing);
    let selected_scope_chars = assistant_run_codex_value_chars(selected_scope);
    let scope_candidate_chars = assistant_run_codex_values_chars(scope_candidates);
    let supplied_item_chars = assistant_run_codex_values_chars(&supplied_items);
    let hidden_memory_chars = assistant_run_codex_values_chars(&hidden_memory_items);
    let detail_target_chars = assistant_run_codex_values_chars(&detail_targets);
    let media_summary_count = assistant_run_codex_media_summary_count(&supplied_items);
    let media_summary_chars = assistant_run_codex_media_summary_chars(&supplied_items);
    let estimated_prompt_chars = prompt_and_history_chars
        + startup_briefing_chars
        + selected_scope_chars
        + scope_candidate_chars
        + tool_output_chars
        + artifact_state_chars;
    let budget_pressure =
        assistant_run_codex_budget_pressure(estimated_prompt_chars, max_prompt_chars);
    let items = vec![
        AssistantRunCodexContextBudgetItemView::new(
            "prompt_and_history",
            messages.len() + 1,
            prompt_and_history_chars,
            category_soft_limit,
            0,
            Some("user prompt plus recent visible conversation messages".to_string()),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "startup_briefing",
            usize::from(!startup_briefing.is_null()),
            startup_briefing_chars,
            category_soft_limit,
            0,
            Some("product and database briefing supplied by V3".to_string()),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "selected_scope",
            selected_dataset_ids_from_scope(selected_scope).len()
                + selected_document_ids_from_scope(selected_scope).len(),
            selected_scope_chars,
            category_soft_limit,
            0,
            Some("selected datasets, documents, memory flags, and supply policy".to_string()),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "inferred_scope_candidates",
            scope_candidates.len(),
            scope_candidate_chars,
            category_soft_limit,
            0,
            Some("visible scope candidates for model awareness, not direct evidence".to_string()),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "retrieval_evidence",
            supplied_items.len(),
            supplied_item_chars,
            category_soft_limit,
            trimmed_item_count,
            Some(
                "V3-visible supplied evidence; high-value ids and citations must survive trimming"
                    .to_string(),
            ),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "hidden_conversation_memory",
            hidden_memory_items.len(),
            hidden_memory_chars,
            category_soft_limit,
            0,
            Some("intent-gated conversation memory candidates".to_string()),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "detail_targets",
            detail_targets.len(),
            detail_target_chars,
            category_soft_limit,
            0,
            Some(
                "documents recommended for deeper read; not directly citable evidence".to_string(),
            ),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "media_payload_summaries",
            media_summary_count,
            media_summary_chars,
            category_soft_limit,
            0,
            Some("transcript, scene, keyframe OCR, and media evidence summaries".to_string()),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "current_artifact",
            usize::from(current_artifact.is_some()),
            artifact_state_chars,
            category_soft_limit,
            0,
            Some("current static page/report artifact skeleton supplied by V3".to_string()),
        ),
        AssistantRunCodexContextBudgetItemView::new(
            "tool_outputs",
            usize::from(!evidence_state.is_null()),
            tool_output_chars,
            max_prompt_chars.or(category_soft_limit),
            trimmed_item_count,
            Some("complete evidence/tool state currently supplied to the executor".to_string()),
        ),
    ];

    AssistantRunCodexContextBudgetView {
        max_prompt_chars,
        estimated_prompt_chars,
        budget_pressure,
        included_message_count: messages.len(),
        selected_dataset_count: selected_dataset_ids_from_scope(selected_scope).len(),
        evidence_item_count: assistant_run_evidence_supplied_count(evidence_state),
        hidden_memory_item_count: hidden_memory_items.len(),
        artifact_state_chars,
        tool_output_chars,
        trimmed_item_count,
        items,
        ..AssistantRunCodexContextBudgetView::default()
    }
}

fn assistant_run_codex_budget_pressure(char_count: usize, limit: Option<usize>) -> String {
    match limit {
        Some(limit) if limit > 0 && char_count > limit => "over_limit",
        Some(limit) if limit > 0 && char_count * 10 >= limit * 7 => "attention",
        Some(_) => "ok",
        None => "unbounded",
    }
    .to_string()
}

fn assistant_run_codex_value_chars(value: &Value) -> usize {
    if value.is_null() {
        return 0;
    }
    serde_json::to_string(value)
        .map(|value| value.chars().count())
        .unwrap_or(0)
}

fn assistant_run_codex_values_chars(values: &[Value]) -> usize {
    values.iter().map(assistant_run_codex_value_chars).sum()
}

fn assistant_run_codex_media_summary_count(items: &[Value]) -> usize {
    items
        .iter()
        .filter(|item| {
            item.get("media_context")
                .or_else(|| item.get("mediaContext"))
                .is_some()
        })
        .count()
}

fn assistant_run_codex_media_summary_chars(items: &[Value]) -> usize {
    items
        .iter()
        .filter_map(|item| {
            item.get("media_context")
                .or_else(|| item.get("mediaContext"))
        })
        .map(assistant_run_codex_value_chars)
        .sum()
}

