fn assistant_run_codex_provider_shim_observability_from_output(
    output: &CodexConversationExecutorOutput,
) -> Value {
    let wire_api = output
        .model_gateway
        .get("wire_api")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let is_provider_shim = matches!(
        wire_api,
        "codex_compatible_shim" | "codex-compatible-shim" | "codex_shim" | "provider_shim"
    );
    if !is_provider_shim {
        return Value::Null;
    }

    let selected_model = output
        .model_gateway
        .get("selected_model")
        .filter(|value| value.is_object())
        .unwrap_or(&Value::Null);
    let provider_id = selected_model
        .get("provider")
        .cloned()
        .unwrap_or(Value::Null);
    let model_id = selected_model.get("model").cloned().unwrap_or(Value::Null);
    let auth_configured = output
        .model_gateway
        .get("auth_configured")
        .cloned()
        .unwrap_or(Value::Bool(false));
    let profile_id = output
        .model_gateway
        .get("profile_id")
        .cloned()
        .unwrap_or(Value::Null);
    let capabilities = output
        .model_gateway
        .get("capabilities")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let capability_manifest = output
        .model_gateway
        .get("capability_manifest")
        .cloned()
        .unwrap_or(Value::Null);

    json!({
        "schema_version": 1,
        "source": "v3_codex_event_synthetic",
        "health": {
            "status": "unknown",
            "process_reachable": false,
            "upstream_reachable": false,
            "checked_at": Value::Null,
        },
        "profile": {
            "profile_id": profile_id,
            "provider_id": provider_id,
            "model_id": model_id,
            "wire_api": wire_api,
            "endpoint_scope": "v3_server_profile",
            "base_url_configured": false,
            "api_path": Value::Null,
            "auth_configured": auth_configured,
            "timeout_ms": Value::Null,
            "capabilities": capabilities,
            "capability_manifest": capability_manifest,
            "rate_limit": {
                "requests_per_minute": Value::Null,
                "tokens_per_minute": Value::Null,
                "concurrent_requests": Value::Null,
            },
            "cost": {
                "currency": Value::Null,
                "input_microusd_per_million_tokens": Value::Null,
                "output_microusd_per_million_tokens": Value::Null,
            },
            "redaction": {
                "redact_provider_errors": true,
                "redact_request_payloads": true,
                "redact_response_payloads": true,
                "max_error_chars": 0,
            },
        },
        "usage_summary": {
            "request_count": 0,
            "failed_request_count": 0,
            "input_tokens": 0,
            "output_tokens": 0,
            "total_tokens": 0,
            "last_request_id": Value::Null,
        },
        "recent_usage_events": [],
        "balance": {
            "supported": false,
            "currency": Value::Null,
            "amount_microunits": Value::Null,
            "checked_at": Value::Null,
        },
        "debug_trace_status": {
            "enabled": false,
            "redacted": true,
            "storage": "disabled",
            "retained_trace_count": 0,
            "latest_trace_id": Value::Null,
        },
        "context_budget_report": {
            "quality_first": output.context_budget.quality_first,
            "max_prompt_chars": output.context_budget.max_prompt_chars,
            "estimated_prompt_chars": output.context_budget.estimated_prompt_chars,
            "budget_pressure": output.context_budget.budget_pressure.clone(),
            "trimmed_item_count": output.context_budget.trimmed_item_count,
            "items": output.context_budget.items.clone(),
        },
        "tool_output_budget": {
            "largest_output_chars": 0,
            "trimmed_output_count": output.context_budget.trimmed_item_count,
            "preserved_recent_output_count": 0,
            "preserved_error_count": 0,
            "preserved_evidence_ref_count": output.context_budget.evidence_item_count,
        },
        "liveness_events": [],
    })
}

fn assistant_run_codex_shadow_comparison(
    output: &CodexConversationExecutorOutput,
    direct_react_enabled: bool,
    direct_runtime_manifest: &Value,
    direct_output_artifacts: &[Value],
    direct_react_events: &[AssistantRunReactEvent],
    selected_scope: &Value,
    current_artifact: Option<&Value>,
) -> Value {
    let artifact_types: Vec<Value> = direct_output_artifacts
        .iter()
        .filter_map(|artifact| artifact.get("type").and_then(Value::as_str))
        .map(|value| json!(value))
        .collect();
    let react_event_names: Vec<Value> = direct_react_events
        .iter()
        .map(|event| json!(event.event_name.as_str()))
        .collect();
    let direct_action_types =
        assistant_run_codex_direct_action_types(direct_output_artifacts, direct_react_events);
    let selected_intent = assistant_run_scope_intent(selected_scope);
    let static_page_context = selected_intent == "static_page"
        || current_artifact
            .map(assistant_run_is_static_page_artifact)
            .unwrap_or(false)
        || direct_output_artifacts.iter().any(|artifact| {
            artifact
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|kind| {
                    matches!(
                        kind,
                        "static_page_draft" | "static_page_image_job" | "static_page_render_output"
                    )
                })
        });
    let suggested_action_type = output
        .suggested_action
        .as_ref()
        .and_then(|action| {
            action
                .get("action_type")
                .or_else(|| action.get("actionType"))
                .or_else(|| action.get("type"))
        })
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    let suggested_action_allowed = suggested_action_type.as_ref().is_none_or(|action_type| {
        output
            .planned_action_types
            .iter()
            .any(|planned| planned == action_type)
    });
    let comparison_status = assistant_run_codex_shadow_comparison_status(
        &direct_action_types,
        suggested_action_type.as_deref(),
        suggested_action_allowed,
    );
    let direct_action_values: Vec<Value> = direct_action_types
        .iter()
        .map(|value| json!(value))
        .collect();

    json!({
        "mode": "shadow_comparison",
        "authoritative_executor": "direct",
        "codex_mutation_allowed": false,
        "codex_queue_allowed": false,
        "direct_state_authoritative": true,
        "static_page_flow_preserved": true,
        "static_page_context": static_page_context,
        "direct": {
            "react_enabled": direct_react_enabled,
            "runtime_mode": direct_runtime_manifest.get("mode").cloned().unwrap_or(Value::Null),
            "provider": direct_runtime_manifest.get("provider").cloned().unwrap_or(Value::Null),
            "model": direct_runtime_manifest.get("model").cloned().unwrap_or(Value::Null),
            "artifact_types": artifact_types,
            "react_event_names": react_event_names,
            "action_types": direct_action_values,
            "selected_intent": selected_intent,
        },
        "codex": {
            "transport": output.transport.as_str(),
            "status": output.status.as_str(),
            "codex_invoked": output.codex_invoked,
            "fallback_to_direct": output.fallback_to_direct,
            "planned_action_types": output.planned_action_types.clone(),
            "suggested_action_type": suggested_action_type,
            "suggested_action_allowed": suggested_action_allowed,
            "model_gateway": output.model_gateway.clone(),
        },
        "comparison": {
            "status": comparison_status,
            "codex_has_suggestion": output.suggested_action.is_some(),
            "actionable": false,
            "equivalence_scored": output.suggested_action.is_some(),
            "reason": if suggested_action_allowed {
                "shadow mode only; direct execution remains authoritative"
            } else {
                "codex suggested action is not in V3-provided action contracts"
            },
            "next_gate": "enable Codex mutation only after repeated matched shadow runs",
        }
    })
}

fn assistant_run_codex_direct_action_types(
    direct_output_artifacts: &[Value],
    direct_react_events: &[AssistantRunReactEvent],
) -> Vec<String> {
    let mut actions = Vec::new();
    for artifact in direct_output_artifacts {
        let Some(kind) = artifact.get("type").and_then(Value::as_str) else {
            continue;
        };
        let action = match kind {
            "static_page_draft" => Some("create_static_page_draft"),
            "static_page_image_job" => Some("submit_static_page_image_preview"),
            "static_page_render_output" => Some("render_static_page"),
            "assistant_message" => Some("final_answer"),
            "report_draft" => Some("create_report_draft"),
            _ => None,
        };
        if let Some(action) = action {
            push_unique_string(&mut actions, action);
        }
    }
    for event in direct_react_events {
        if let Some(action) = assistant_run_action_type_from_event_name(&event.event_name) {
            push_unique_string(&mut actions, action);
        }
    }
    actions
}

fn assistant_run_action_type_from_event_name(event_name: &str) -> Option<&'static str> {
    if event_name.contains("retrieve_evidence") {
        Some("retrieve_evidence")
    } else if event_name.contains("read_document_detail") {
        Some("read_document_detail")
    } else if event_name.contains("recall_conversation_memory") {
        Some("recall_conversation_memory")
    } else if event_name.contains("create_static_page_draft") {
        Some("create_static_page_draft")
    } else if event_name.contains("update_static_page_module") {
        Some("update_static_page_module")
    } else if event_name.contains("submit_static_page_image_preview") {
        Some("submit_static_page_image_preview")
    } else if event_name.contains("render_static_page") {
        Some("render_static_page")
    } else if event_name.contains("create_report_draft") {
        Some("create_report_draft")
    } else if event_name.contains("report_choice") {
        Some("report_choice")
    } else if event_name.contains("codex_host_task") {
        Some("codex_host_task")
    } else {
        None
    }
}

fn assistant_run_codex_shadow_comparison_status(
    direct_action_types: &[String],
    suggested_action_type: Option<&str>,
    suggested_action_allowed: bool,
) -> &'static str {
    let Some(suggested_action_type) = suggested_action_type else {
        return "no_codex_suggestion";
    };
    if !suggested_action_allowed {
        return "invalid_suggestion";
    }
    if direct_action_types
        .iter()
        .any(|action_type| action_type == suggested_action_type)
    {
        "matched"
    } else if direct_action_types.is_empty() {
        "codex_only"
    } else {
        "diverged"
    }
}

fn push_unique_string(items: &mut Vec<String>, item: &str) {
    let item = item.trim();
    if item.is_empty() {
        return;
    }
    if !items.iter().any(|existing| existing == item) {
        items.push(item.to_string());
    }
}

fn normalize_assistant_run_continue_max_steps(value: Option<usize>) -> usize {
    value
        .unwrap_or(ASSISTANT_RUN_CONTINUE_DEFAULT_MAX_STEPS)
        .clamp(1, ASSISTANT_RUN_CONTINUE_MAX_STEPS)
}

#[derive(Clone, Debug)]
struct ExternalAclFilterContext {
    principal: ExternalPrincipalContext,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct ExternalAclDocumentRef {
    source_id: String,
    document_external_id: String,
    revision_external_id: Option<String>,
}

async fn load_external_acl_filter_context(
    state: &AppState,
    selected_scope: &Value,
) -> std::result::Result<Option<ExternalAclFilterContext>, ApiError> {
    if selected_scope.get("type").and_then(Value::as_str) != Some("external_channel") {
        return Ok(None);
    }
    let platform = required_scope_string(selected_scope, "platform")?;
    let external_user_id = selected_scope
        .get("sender_external_id")
        .or_else(|| selected_scope.get("sender_external_user_id"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            ApiError::bad_request(
                "external_principal_missing",
                "external channel scope requires sender_external_id before retrieval".to_string(),
            )
        })?;

    let row = sqlx::query(
        r#"
        select v3_user_id,
               trust_level,
               is_disabled,
               external_department_ids,
               external_group_ids,
               external_role_ids
        from external_principals
        where tenant_id = $1 and platform = $2 and external_user_id = $3
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(platform)
    .bind(external_user_id)
    .fetch_optional(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let principal = if let Some(row) = row {
        ExternalPrincipalContext {
            tenant_id: state.tenant_id,
            platform: platform.to_string(),
            external_user_id: external_user_id.to_string(),
            external_department_ids: json_string_array(row.get("external_department_ids")),
            external_group_ids: json_string_array(row.get("external_group_ids")),
            external_role_ids: json_string_array(row.get("external_role_ids")),
            v3_user_id: row.get::<Option<Uuid>, _>("v3_user_id").map(UserId),
            trust_level: ExternalPrincipalTrustLevel::from_str(
                row.get::<String, _>("trust_level").as_str(),
            ),
            is_disabled: row.get("is_disabled"),
        }
    } else {
        ExternalPrincipalContext {
            tenant_id: state.tenant_id,
            platform: platform.to_string(),
            external_user_id: external_user_id.to_string(),
            external_department_ids: Vec::new(),
            external_group_ids: Vec::new(),
            external_role_ids: Vec::new(),
            v3_user_id: None,
            trust_level: ExternalPrincipalTrustLevel::Unresolved,
            is_disabled: false,
        }
    };

    Ok(Some(ExternalAclFilterContext { principal }))
}

fn required_scope_string<'a>(
    selected_scope: &'a Value,
    field_name: &str,
) -> std::result::Result<&'a str, ApiError> {
    selected_scope
        .get(field_name)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            ApiError::bad_request(
                "external_scope_invalid",
                format!("external channel scope requires {field_name}"),
            )
        })
}

async fn filter_retrieval_evidences_for_external_acl(
    state: &AppState,
    context: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
    evidences: Vec<RetrievalEvidence>,
) -> std::result::Result<Vec<RetrievalEvidence>, ApiError> {
    let Some(context) = context else {
        return Ok(evidences);
    };
    let resolver = ScopeResolver;
    let mut visible = Vec::new();
    let mut acl_cache =
        HashMap::<ExternalAclDocumentRef, Option<ExternalDocumentAclSnapshot>>::new();

    for evidence in evidences {
        let allow_without_snapshot = external_acl_allows_missing_snapshot_for_selected_document(
            evidence.document_id,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        );
        let Some(acl_ref) = external_acl_document_ref_from_value(&evidence.evidence_manifest)
        else {
            if allow_without_snapshot {
                visible.push(evidence);
            }
            continue;
        };
        let acl = load_external_acl_snapshot_cached(state, &mut acl_cache, &acl_ref).await?;
        match acl.as_ref() {
            Some(snapshot) => {
                if resolver
                    .can_access_external_document(&context.principal, snapshot)
                    .allowed
                {
                    visible.push(evidence);
                }
            }
            None if allow_without_snapshot => visible.push(evidence),
            None => {}
        }
    }

    Ok(visible)
}

async fn document_is_visible_for_external_acl(
    state: &AppState,
    context: Option<&ExternalAclFilterContext>,
    document: &Document,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<bool, ApiError> {
    let Some(context) = context else {
        return Ok(true);
    };
    let allow_without_snapshot = external_acl_allows_missing_snapshot_for_selected_document(
        document.id,
        selected_document_ids,
        allow_selected_documents_without_acl_snapshot,
    );
    let metadata = Value::Object(Map::from_iter(document.metadata.clone()));
    let Some(acl_ref) = external_acl_document_ref_from_value(&metadata) else {
        return Ok(allow_without_snapshot);
    };
    let mut acl_cache =
        HashMap::<ExternalAclDocumentRef, Option<ExternalDocumentAclSnapshot>>::new();
    let Some(acl) = load_external_acl_snapshot_cached(state, &mut acl_cache, &acl_ref).await?
    else {
        return Ok(allow_without_snapshot);
    };
    Ok(ScopeResolver
        .can_access_external_document(&context.principal, &acl)
        .allowed)
}

fn external_acl_allows_missing_snapshot_for_selected_document(
    document_id: DocumentId,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> bool {
    if !allow_selected_documents_without_acl_snapshot {
        return false;
    }
    selected_document_ids.is_empty() || selected_document_ids.contains(&document_id)
}

fn selected_scope_allows_external_document_range_without_acl_snapshot(
    selected_scope: &Value,
) -> bool {
    if selected_scope.get("type").and_then(Value::as_str) != Some("external_channel") {
        return false;
    }
    if selected_scope.get("mode").and_then(Value::as_str) != Some("external_document_scope") {
        return false;
    }
    if !matches!(
        selected_scope
            .get("external_document_scope_status")
            .and_then(Value::as_str),
        Some(
            "resolved" | "partial" | "source_resolved" | "dataset_resolved" | "v3_dataset_resolved",
        )
    ) {
        return false;
    }
    let has_requested_external_ids = selected_scope
        .get("available_document_external_ids")
        .and_then(Value::as_array)
        .is_some_and(|items| !items.is_empty());
    let has_source_document_scope = selected_scope
        .get("source_document_scope")
        .and_then(Value::as_object)
        .is_some()
        && !selected_dataset_ids_from_scope(selected_scope).is_empty();
    let has_dataset_document_scope = selected_scope
        .get("dataset_document_scope")
        .and_then(Value::as_object)
        .is_some()
        && !selected_dataset_ids_from_scope(selected_scope).is_empty();
    (has_requested_external_ids && !selected_document_ids_from_scope(selected_scope).is_empty())
        || has_source_document_scope
        || has_dataset_document_scope
}

async fn load_external_acl_snapshot_cached(
    state: &AppState,
    cache: &mut HashMap<ExternalAclDocumentRef, Option<ExternalDocumentAclSnapshot>>,
    acl_ref: &ExternalAclDocumentRef,
) -> std::result::Result<Option<ExternalDocumentAclSnapshot>, ApiError> {
    if let Some(snapshot) = cache.get(acl_ref) {
        return Ok(snapshot.clone());
    }
    let snapshot = load_external_acl_snapshot(state, acl_ref).await?;
    cache.insert(acl_ref.clone(), snapshot.clone());
    Ok(snapshot)
}

async fn load_external_acl_snapshot(
    state: &AppState,
    acl_ref: &ExternalAclDocumentRef,
) -> std::result::Result<Option<ExternalDocumentAclSnapshot>, ApiError> {
    let revision_filter = acl_ref.revision_external_id.as_deref().unwrap_or("");
    let row = sqlx::query(
        r#"
        select revision_external_id, acl_snapshot, acl_hash
        from external_permission_snapshots
        where tenant_id = $1
          and source_id = $2
          and document_external_id = $3
          and ($4 = '' or coalesce(revision_external_id, '') = $4)
        order by captured_at desc
        limit 1
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(&acl_ref.source_id)
    .bind(&acl_ref.document_external_id)
    .bind(revision_filter)
    .fetch_optional(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let Some(row) = row else {
        return Ok(None);
    };
    let acl_snapshot: Value = row.get("acl_snapshot");
    Ok(Some(ExternalDocumentAclSnapshot {
        source_id: acl_ref.source_id.clone(),
        document_external_id: acl_ref.document_external_id.clone(),
        revision_external_id: row
            .get::<Option<String>, _>("revision_external_id")
            .or_else(|| acl_ref.revision_external_id.clone()),
        allowed_user_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_user_external_ids",
            "user",
        ),
        allowed_department_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_department_external_ids",
            "department",
        ),
        allowed_group_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_group_external_ids",
            "group",
        ),
        allowed_role_external_ids: acl_subject_ids(
            &acl_snapshot,
            "allowed_role_external_ids",
            "role",
        ),
        denied_user_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_user_external_ids",
            "user",
        ),
        denied_department_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_department_external_ids",
            "department",
        ),
        denied_group_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_group_external_ids",
            "group",
        ),
        denied_role_external_ids: acl_denied_subject_ids(
            &acl_snapshot,
            "denied_role_external_ids",
            "role",
        ),
        acl_hash: row.get("acl_hash"),
    }))
}

fn external_acl_document_ref_from_value(value: &Value) -> Option<ExternalAclDocumentRef> {
    external_acl_document_ref_from_object(value).or_else(|| {
        let object = value.as_object()?;
        for key in [
            "external_acl",
            "externalAcl",
            "source_acl_snapshot",
            "sourceAclSnapshot",
            "external_source",
            "externalSource",
            "evidence",
        ] {
            if let Some(found) = object
                .get(key)
                .and_then(external_acl_document_ref_from_value)
            {
                return Some(found);
            }
        }
        None
    })
}

fn external_acl_document_ref_from_object(value: &Value) -> Option<ExternalAclDocumentRef> {
    let object = value.as_object()?;
    let source_id = object_string(object, &["source_id", "sourceId"])?;
    let document_external_id = object_string(
        object,
        &[
            "document_external_id",
            "documentExternalId",
            "external_document_id",
        ],
    )?;
    let revision_external_id = object_string(
        object,
        &["revision_external_id", "revisionExternalId", "revision"],
    );
    Some(ExternalAclDocumentRef {
        source_id,
        document_external_id,
        revision_external_id,
    })
}

fn object_string(object: &Map<String, Value>, keys: &[&str]) -> Option<String> {
    keys.iter()
        .filter_map(|key| object.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .next()
}

fn acl_subject_ids(snapshot: &Value, flat_key: &str, subject_type: &str) -> Vec<String> {
    let mut ids = json_string_array(snapshot.get(flat_key).cloned().unwrap_or(Value::Null));
    ids.extend(acl_nested_subject_ids(snapshot, "allow", subject_type));
    dedupe_strings(ids)
}

fn acl_denied_subject_ids(snapshot: &Value, flat_key: &str, subject_type: &str) -> Vec<String> {
    let mut ids = json_string_array(snapshot.get(flat_key).cloned().unwrap_or(Value::Null));
    ids.extend(acl_nested_subject_ids(snapshot, "deny", subject_type));
    dedupe_strings(ids)
}

fn acl_nested_subject_ids(
    snapshot: &Value,
    collection_key: &str,
    subject_type: &str,
) -> Vec<String> {
    snapshot
        .get(collection_key)
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|item| {
            item.get("subject_type")
                .or_else(|| item.get("subjectType"))
                .and_then(Value::as_str)
                == Some(subject_type)
        })
        .filter_map(|item| {
            item.get("subject_external_id")
                .or_else(|| item.get("subjectExternalId"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        })
        .collect()
}

fn json_string_array(value: Value) -> Vec<String> {
    value
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn dedupe_strings(values: Vec<String>) -> Vec<String> {
    let mut deduped = Vec::new();
    for value in values {
        if !deduped.contains(&value) {
            deduped.push(value);
        }
    }
    deduped
}

fn external_acl_supply_filter_summary(context: Option<&ExternalAclFilterContext>) -> Value {
    context
        .map(|context| {
            json!({
                "status": "enabled",
                "platform": context.principal.platform,
                "external_user_id": context.principal.external_user_id,
                "trust_level": external_principal_trust_level_label(&context.principal.trust_level),
                "permission_boundary": "source_acl_snapshot_before_model_context",
            })
        })
        .unwrap_or(Value::Null)
}

fn external_principal_trust_level_label(level: &ExternalPrincipalTrustLevel) -> &'static str {
    match level {
        ExternalPrincipalTrustLevel::Unresolved => "unresolved",
        ExternalPrincipalTrustLevel::Guest => "guest",
        ExternalPrincipalTrustLevel::ExternalUser => "external_user",
        ExternalPrincipalTrustLevel::Employee => "employee",
        ExternalPrincipalTrustLevel::Manager => "manager",
        ExternalPrincipalTrustLevel::Admin => "admin",
        ExternalPrincipalTrustLevel::SystemOperator => "system_operator",
    }
}

async fn build_assistant_run_evidence_state(
    state: &AppState,
    selected_scope: &Value,
    prompt: &str,
    local_thread_id: Option<&str>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<Value, ApiError> {
    let dataset_ids = selected_dataset_ids_from_scope(selected_scope);
    let conversation_memory_requested = selected_scope_requests_conversation_memory(selected_scope);
    if dataset_ids.is_empty() && !conversation_memory_requested {
        let empty_items: Vec<Value> = Vec::new();
        return Ok(json!({
            "status": "not_requested",
            "policy": "host_supplies_model_answers",
            "intent": assistant_run_scope_intent(selected_scope),
            "supply_policy": assistant_run_scope_supply_policy(selected_scope),
            "action_policy": assistant_run_scope_action_policy(selected_scope),
            "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
            "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
            "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
            "supply_quality": assistant_run_supply_quality_report(
                selected_scope,
                false,
                &empty_items,
                &empty_items,
                &empty_items,
                &empty_items,
                0,
                0,
            ),
            "supplied_items": [],
        }));
    }

    let prefer_detail = assistant_run_scope_prefers_detail(selected_scope);
    let limit = assistant_run_evidence_limit_for_scope_and_prompt(selected_scope, prompt);
    let dataset_entity_scan_requested =
        assistant_run_dataset_entity_scan_requested(selected_scope, prompt);
    let external_acl_filter = load_external_acl_filter_context(state, selected_scope).await?;
    let evidence_document_ids = selected_document_ids_for_evidence_from_scope(selected_scope);
    let allow_selected_documents_without_acl_snapshot =
        selected_scope_allows_external_document_range_without_acl_snapshot(selected_scope);
    let mut supplied_items = Vec::new();
    let mut supplied_datasets = Vec::new();
    let mut supplied_memory_items = Vec::new();
    let mut media_context_by_document: HashMap<DocumentId, Option<Value>> = HashMap::new();
    let mut retrieval_chunks_by_document: HashMap<DocumentId, Vec<DocumentChunk>> = HashMap::new();
    let mut unavailable_dataset_ids = Vec::new();

    for dataset_id in dataset_ids
        .into_iter()
        .take(ASSISTANT_RUN_EVIDENCE_DATASET_LIMIT)
    {
        let dataset = match load_visible_dataset_for_assistant_scope(
            state,
            dataset_id,
            active_secret_binding_ids,
            current_user_id,
            local_thread_id,
            selected_scope,
        )
        .await
        {
            Ok(dataset) => dataset,
            Err(error)
                if !assistant_run_scope_is_external_channel(Some(selected_scope))
                    && error.payload.code == "dataset_not_found" =>
            {
                unavailable_dataset_ids.push(dataset_id.to_string());
                continue;
            }
            Err(error) => return Err(error),
        };
        supplied_datasets.push(json!({
            "id": dataset.id,
            "key": dataset.key.clone(),
            "title": dataset.title.clone(),
            "visibility": dataset.visibility.as_str(),
        }));

        let parse_status_items = build_assistant_run_document_parse_status_supply(
            state,
            &dataset,
            current_user_id,
            external_acl_filter.as_ref(),
            &evidence_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?;
        supplied_items.extend(parse_status_items);

        if dataset_entity_scan_requested {
            let fact_snapshot_items = build_assistant_run_dataset_fact_snapshot_supply(
                state,
                &dataset,
                current_user_id,
                external_acl_filter.as_ref(),
                &evidence_document_ids,
                allow_selected_documents_without_acl_snapshot,
            )
            .await?;
            let fact_snapshot_available = !fact_snapshot_items.is_empty();
            let fact_snapshot_can_replace_scan =
                assistant_run_fact_snapshot_can_replace_dataset_entity_scan(prompt);
            supplied_items.extend(fact_snapshot_items);

            if !fact_snapshot_available || !fact_snapshot_can_replace_scan {
                let scan_items = build_assistant_run_dataset_entity_scan_supply(
                    state,
                    &dataset,
                    current_user_id,
                    external_acl_filter.as_ref(),
                    &evidence_document_ids,
                    allow_selected_documents_without_acl_snapshot,
                )
                .await?;
                supplied_items.extend(scan_items);
            }
        }

        let database_supply_items =
            build_assistant_run_database_aggregate_supply(state, &dataset, prompt).await?;
        supplied_items.extend(database_supply_items);

        let spreadsheet_row_analysis_items = build_assistant_run_spreadsheet_row_analysis_supply(
            state,
            &dataset,
            prompt,
            current_user_id,
            external_acl_filter.as_ref(),
            &evidence_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?;
        supplied_items.extend(spreadsheet_row_analysis_items);

        let evidences = state
            .storage
            .retrieval_evidences()
            .list_latest_by_dataset_scope(
                state.tenant_id,
                dataset.id,
                retrieval_search_scan_limit(limit),
            )
            .await
            .map_err(ApiError::from_storage)?;
        let evidences = filter_retrieval_evidences_for_assistant_evidence_scope(
            state,
            dataset.id,
            evidences,
            current_user_id,
            &evidence_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?;
        let evidences = filter_retrieval_evidences_for_external_acl(
            state,
            external_acl_filter.as_ref(),
            &evidence_document_ids,
            allow_selected_documents_without_acl_snapshot,
            evidences,
        )
        .await?;
        let evidences =
            filter_retrieval_evidences_for_selected_documents(evidences, &evidence_document_ids);

        let ranked_evidences = rank_retrieval_evidences_for_prompt(&evidences, prompt, limit);
        if ranked_evidences.is_empty() {
            let fallback_items = build_assistant_run_chunk_fallback_supply(
                state,
                &dataset,
                prompt,
                limit,
                current_user_id,
                external_acl_filter.as_ref(),
                &evidence_document_ids,
                allow_selected_documents_without_acl_snapshot,
                &mut media_context_by_document,
                "retrieval_evidence_unavailable",
            )
            .await?;
            supplied_items.extend(fallback_items);
            continue;
        }

        for ranked in ranked_evidences {
            let media_context = assistant_run_media_context_for_document(
                state,
                ranked.evidence.document_id,
                &mut media_context_by_document,
            )
            .await?;
            let content_excerpt = assistant_run_retrieval_supply_excerpt(
                state,
                ranked.evidence,
                prompt,
                &mut retrieval_chunks_by_document,
            )
            .await?;
            let mut supplied_item = json!({
                "type": "retrieval_evidence",
                "dataset_id": ranked.evidence.dataset_id,
                "document_id": ranked.evidence.document_id,
                "document_chunk_id": ranked.evidence.document_chunk_id,
                "retrieval_evidence_id": ranked.evidence.id,
                "chunk_index": ranked.evidence.chunk_index,
                "source_locator": ranked.evidence.source_locator.clone(),
                "summary": ranked.evidence.summary.clone(),
                "content_excerpt": content_excerpt,
                "payload_filter_key": ranked.evidence.payload_filter_key.clone(),
                "score": ranked.score,
                "lexical_score": ranked.lexical_score,
                "recall_score": ranked.recall_score,
                "evidence_manifest": ranked.evidence.evidence_manifest.clone(),
            });
            if let Some(media_context) = media_context {
                if let Some(object) = supplied_item.as_object_mut() {
                    object.insert("media_context".to_string(), media_context);
                }
            }
            supplied_items.push(supplied_item);
        }

        if assistant_run_prompt_requests_expanded_supply(prompt) {
            let expanded_prompt = assistant_run_expanded_supply_prompt(prompt);
            let expanded_fallback_items = build_assistant_run_chunk_fallback_supply(
                state,
                &dataset,
                &expanded_prompt,
                ASSISTANT_RUN_EVIDENCE_MAX_LIMIT,
                current_user_id,
                external_acl_filter.as_ref(),
                &evidence_document_ids,
                allow_selected_documents_without_acl_snapshot,
                &mut media_context_by_document,
                "weak_indexed_evidence_expansion",
            )
            .await?;
            append_deduped_assistant_supply_items(&mut supplied_items, expanded_fallback_items);
        }
    }

    if conversation_memory_requested {
        let memory_items = load_selected_conversation_memory_items(
            state,
            selected_scope,
            local_thread_id,
            current_user_id,
        )
        .await?;
        for supplied_item in memory_items {
            supplied_memory_items.push(supplied_item.clone());
            supplied_items.push(supplied_item);
        }
    }

    let status = if supplied_items.is_empty() {
        "empty"
    } else {
        "supplied"
    };
    let detail_targets = assistant_run_detail_targets_for_scope(selected_scope, &supplied_items);
    let fallback_supply_count = assistant_run_fallback_supply_count(&supplied_items);
    let supply_quality = assistant_run_supply_quality_report(
        selected_scope,
        true,
        &supplied_items,
        &supplied_datasets,
        &supplied_memory_items,
        &detail_targets,
        fallback_supply_count,
        limit,
    );
    let recovery_followup = assistant_run_recovery_followup_for_weak_supply(
        selected_scope,
        prompt,
        status,
        &supplied_items,
        &supply_quality,
        &unavailable_dataset_ids,
    );
    Ok(json!({
        "status": status,
        "policy": "host_supplies_model_answers",
        "intent": assistant_run_scope_intent(selected_scope),
        "supply_policy": assistant_run_scope_supply_policy(selected_scope),
        "action_policy": assistant_run_scope_action_policy(selected_scope),
        "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
        "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
        "detail_preferred": prefer_detail,
        "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
        "recommended_actions": assistant_run_recommended_supply_actions(
            selected_scope,
            !supplied_items.is_empty(),
            dataset_entity_scan_requested,
        ),
        "supply_quality": supply_quality,
        "recovery_followup": recovery_followup,
        "detail_targets": detail_targets,
        "selected_scope": selected_scope,
        "datasets": supplied_datasets,
        "unavailable_dataset_ids": unavailable_dataset_ids,
        "conversation_memory_items": supplied_memory_items,
        "supplied_items": supplied_items,
        "external_acl_filter": external_acl_supply_filter_summary(external_acl_filter.as_ref()),
        "fallback_supply_count": fallback_supply_count,
        "fallback_supply_policy": if fallback_supply_count > 0 { "visible_document_chunks_when_retrieval_evidence_missing" } else { "not_used" },
        "limit": limit,
    }))
}

async fn build_assistant_run_dataset_fact_snapshot_supply(
    state: &AppState,
    dataset: &Dataset,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<Vec<Value>, ApiError> {
    if !assistant_run_fact_index_enabled() {
        return Ok(Vec::new());
    }

    if external_acl_filter.is_some()
        || !selected_document_ids.is_empty()
        || dataset_is_external_temporary_scope(dataset)
    {
        let scoped_document_ids = assistant_run_dataset_fact_snapshot_scoped_document_ids(
            state,
            dataset,
            current_user_id,
            external_acl_filter,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?;
        if scoped_document_ids.is_empty() {
            return Ok(Vec::new());
        }
        let (mut manifest, source_fact_count, source_document_count) =
            fact_index::build_dataset_entity_rows_snapshot_manifest_for_documents(
                &state.storage,
                state.tenant_id,
                dataset.id,
                &scoped_document_ids,
                ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT as i64,
                Utc::now(),
            )
            .await
            .map_err(ApiError::from_storage)?;
        if source_fact_count <= 0 {
            return Ok(Vec::new());
        }

        let scope_filter = json!({
            "mode": "selected_or_authorized_documents",
            "external_acl_filtered": external_acl_filter.is_some(),
            "selected_document_count": selected_document_ids.len(),
            "temporary_dataset": dataset_is_external_temporary_scope(dataset),
            "scoped_document_count": scoped_document_ids.len(),
        });
        if let Some(object) = manifest.as_object_mut() {
            object.insert("scope_filter".to_string(), scope_filter.clone());
            object.insert(
                "scanned_document_count".to_string(),
                json!(scoped_document_ids.len()),
            );
            object.insert(
                "scoped_document_count".to_string(),
                json!(scoped_document_ids.len()),
            );
        }

        return Ok(vec![
            assistant_run_dataset_fact_snapshot_item_from_manifest(
                dataset,
                "document_facts_scoped_aggregate",
                fact_index::ENTITY_ROWS_BY_TYPE_SNAPSHOT_KIND,
                fact_index::ENTITY_ROWS_BY_TYPE_SNAPSHOT_KEY,
                manifest,
                source_fact_count,
                source_document_count,
                Some(scope_filter),
            ),
        ]);
    }

    let Some(snapshot) = state
        .storage
        .dataset_fact_snapshots()
        .get_dataset_fact_snapshot(
            state.tenant_id,
            dataset.id,
            fact_index::ENTITY_ROWS_BY_TYPE_SNAPSHOT_KIND,
            fact_index::ENTITY_ROWS_BY_TYPE_SNAPSHOT_KEY,
        )
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(Vec::new());
    };

    if !assistant_run_dataset_fact_snapshot_scope_is_visible(state, dataset, current_user_id)
        .await?
    {
        return Ok(Vec::new());
    }

    Ok(vec![assistant_run_dataset_fact_snapshot_item(
        dataset, &snapshot,
    )])
}

async fn assistant_run_dataset_fact_snapshot_scoped_document_ids(
    state: &AppState,
    dataset: &Dataset,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<Vec<DocumentId>, ApiError> {
    let documents = list_documents_for_dataset_scope(state, dataset.id).await?;
    let mut document_ids = Vec::new();
    for document in documents {
        if !owner_user_id_is_visible(document.owner_user_id, current_user_id) {
            continue;
        }
        if !selected_document_ids.is_empty() && !selected_document_ids.contains(&document.id) {
            continue;
        }
        if !document_is_visible_for_external_acl(
            state,
            external_acl_filter,
            &document,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?
        {
            continue;
        }
        if !document_ids.contains(&document.id) {
            document_ids.push(document.id);
        }
    }
    Ok(document_ids)
}

async fn assistant_run_dataset_fact_snapshot_scope_is_visible(
    state: &AppState,
    dataset: &Dataset,
    current_user_id: Option<UserId>,
) -> std::result::Result<bool, ApiError> {
    let documents = list_documents_for_dataset_scope(state, dataset.id).await?;
    Ok(documents
        .iter()
        .all(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id)))
}

fn assistant_run_fact_index_enabled() -> bool {
    std::env::var("ASSISTANT_RUN_FACT_INDEX_ENABLED")
        .ok()
        .map(|value| {
            let normalized = value.trim().to_ascii_lowercase();
            !matches!(normalized.as_str(), "" | "0" | "false" | "off" | "no")
        })
        .unwrap_or(true)
}

fn assistant_run_dataset_fact_snapshot_item(
    dataset: &Dataset,
    snapshot: &storage::DatasetFactSnapshot,
) -> Value {
    assistant_run_dataset_fact_snapshot_item_from_manifest(
        dataset,
        "dataset_fact_snapshots",
        &snapshot.snapshot_kind,
        &snapshot.snapshot_key,
        snapshot.snapshot_manifest.clone(),
        snapshot.source_fact_count,
        snapshot.source_document_count,
        None,
    )
}

#[allow(clippy::too_many_arguments)]
fn assistant_run_dataset_fact_snapshot_item_from_manifest(
    dataset: &Dataset,
    source: &str,
    snapshot_kind: &str,
    snapshot_key: &str,
    manifest: Value,
    source_fact_count: i64,
    source_document_count: i64,
    scope_filter: Option<Value>,
) -> Value {
    let mut manifest = manifest;
    if let Some(scope_filter) = scope_filter.as_ref() {
        if let Some(object) = manifest.as_object_mut() {
            object.insert("scope_filter".to_string(), scope_filter.clone());
        }
    }
    let entity_rows_by_type = manifest
        .get("entity_rows_by_type")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let row_count_by_type = manifest
        .get("row_count_by_type")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let scanned_document_count = manifest
        .get("scanned_document_count")
        .and_then(Value::as_i64)
        .unwrap_or(source_document_count);
    let row_summary = assistant_run_dataset_fact_snapshot_row_summary(&row_count_by_type);
    let summary = if row_summary.is_empty() {
        format!(
            "dataset fact snapshot: {scanned_document_count} documents, {} facts",
            source_fact_count
        )
    } else {
        format!(
            "dataset fact snapshot: {scanned_document_count} documents, {} facts, rows {row_summary}",
            source_fact_count
        )
    };
    let model_note = if scope_filter.is_some() {
        "Use this as the authoritative aggregate for the selected or authorized document scope. Use retrieval evidence only for examples, quotes, and validation."
    } else {
        "Use this as the authoritative dataset-level aggregate for count/list/rank questions. Use retrieval evidence only for examples, quotes, and validation."
    };

    json!({
        "type": "dataset_fact_snapshot",
        "source": source,
        "dataset_id": dataset.id,
        "dataset_key": dataset.key.clone(),
        "dataset_title": dataset.title.clone(),
        "snapshot_kind": snapshot_kind,
        "snapshot_key": snapshot_key,
        "scanned_document_count": scanned_document_count,
        "source_document_count": source_document_count,
        "source_fact_count": source_fact_count,
        "row_count_by_type": row_count_by_type,
        "entity_rows_by_type": entity_rows_by_type,
        "snapshot_manifest": manifest,
        "summary": summary,
        "model_note": model_note,
    })
}

fn assistant_run_dataset_fact_snapshot_row_summary(row_count_by_type: &Value) -> String {
    row_count_by_type
        .as_object()
        .map(|object| {
            object
                .iter()
                .filter_map(|(fact_type, count)| {
                    let count = count.as_u64()?;
                    (count > 0).then(|| format!("{fact_type}={count}"))
                })
                .collect::<Vec<_>>()
                .join(", ")
        })
        .unwrap_or_default()
}

async fn build_assistant_run_database_aggregate_supply(
    state: &AppState,
    dataset: &Dataset,
    prompt: &str,
) -> std::result::Result<Vec<Value>, ApiError> {
    let aggregate_requested = assistant_run_database_aggregate_requested(prompt);
    if !assistant_run_database_schema_context_requested(prompt) {
        return Ok(Vec::new());
    }

    let source_ids = load_dataset_external_source_ids(state, dataset.id).await?;
    if source_ids.is_empty() {
        return Ok(Vec::new());
    }

    let mut supplied_items = Vec::new();
    for source_id in source_ids
        .into_iter()
        .take(ASSISTANT_RUN_DATABASE_SOURCE_LIMIT)
    {
        let source = match load_enabled_database_source_connection(state, &source_id).await {
            Ok(source) => source,
            Err(_) => continue,
        };
        let config = match mysql_source_config_for_request(&source, &Value::Null) {
            Ok(config) => config,
            Err(error) => {
                supplied_items.push(json!({
                    "type": "database_aggregate_error",
                    "dataset_id": dataset.id,
                    "source_id": source_id,
                    "status": "config_unavailable",
                    "error_code": error.payload.code,
                    "message": error.payload.message,
                }));
                continue;
            }
        };
        let scan_limit = assistant_run_database_aggregate_scan_limit();
        if !aggregate_requested {
            for mapping in assistant_run_database_schema_mappings_for_prompt(&config, prompt) {
                let aggregate_plans =
                    assistant_run_database_aggregate_dimension_plans(mapping, prompt);
                let metrics = assistant_run_database_metric_columns(mapping);
                supplied_items.push(assistant_run_database_schema_context_item(
                    dataset,
                    &source,
                    mapping,
                    &aggregate_plans,
                    &metrics,
                    scan_limit,
                ));
            }
            continue;
        }
        let Some(mapping) = assistant_run_database_mapping_for_prompt(&config, prompt) else {
            continue;
        };
        let aggregate_plans = assistant_run_database_aggregate_dimension_plans(mapping, prompt);
        let metrics = assistant_run_database_aggregate_metrics(mapping, prompt);
        let aggregation = assistant_run_database_aggregation(prompt, !metrics.is_empty());
        supplied_items.push(assistant_run_database_schema_context_item(
            dataset,
            &source,
            mapping,
            &aggregate_plans,
            &metrics,
            scan_limit,
        ));
        let metric_requests = if metrics.is_empty() {
            vec![None]
        } else {
            metrics.into_iter().map(Some).collect::<Vec<_>>()
        };

        let mut aggregate_request_count = 0usize;
        'metric_requests: for metric in metric_requests
            .iter()
            .take(ASSISTANT_RUN_DATABASE_AGGREGATE_METRIC_LIMIT)
        {
            for aggregate_plan in &aggregate_plans {
                if aggregate_request_count >= ASSISTANT_RUN_DATABASE_AGGREGATE_REQUEST_LIMIT {
                    break 'metric_requests;
                }
                aggregate_request_count += 1;
                let order_direction =
                    assistant_run_database_aggregate_order_direction(prompt, metric.as_deref());
                let latest_time_column = assistant_run_database_aggregate_latest_time_column(
                    mapping,
                    prompt,
                    metric.as_deref(),
                    aggregate_plan,
                );
                let request = MySqlAggregateRequest {
                    table: mapping.table.clone(),
                    dimensions: aggregate_plan.dimensions.clone(),
                    metric: metric.clone(),
                    aggregation: aggregation.clone(),
                    order_direction: Some(order_direction.clone()),
                    latest_time_column: latest_time_column.clone(),
                    limit: Some(ASSISTANT_RUN_DATABASE_AGGREGATE_RESULT_LIMIT),
                    scan_limit: Some(scan_limit),
                };
                match aggregate_mysql_table(&config, &request).await {
                    Ok(result) => supplied_items.push(json!({
                        "type": "database_aggregate",
                        "source": "database_source",
                        "dataset_id": dataset.id,
                        "dataset_key": dataset.key,
                        "dataset_title": dataset.title,
                        "source_id": source.source_id,
                        "connector_kind": source.connector_kind,
                        "table": result.table,
                        "aggregate_role": aggregate_plan.role,
                        "aggregate_intent": aggregate_plan.intent,
                        "dimensions": result.dimensions,
                        "metric": result.metric,
                        "aggregation": result.aggregation,
                        "sort_direction": order_direction.clone(),
                        "time_filter": latest_time_column.as_ref().map(|column| json!({
                            "mode": "latest",
                            "column": column,
                        })),
                        "value_label": metric.clone().unwrap_or_else(|| "record_count".to_string()),
                        "field_semantics": assistant_run_database_field_semantics_for_columns(mapping, &result.columns),
                        "summary": assistant_run_database_aggregate_summary(
                            mapping,
                            aggregate_plan.role,
                            &result.dimensions,
                            result.metric.as_deref().or_else(|| metric.as_deref()),
                            &result.aggregation,
                            &order_direction,
                            latest_time_column.as_deref(),
                            result.rows.len(),
                            result.scan_limit,
                        ),
                        "columns": result.columns,
                        "rows": result.rows,
                        "row_limit": result.row_limit,
                        "scan_limit": result.scan_limit,
                        "source_scope": "selected_database_source_limited_scan",
                        "policy": "host_controlled_read_only_aggregate",
                        "note": "数据库型数据集的结构化聚合供料；scan_limit 表示本次最多扫描的源表行数，模型需要在回答中说明范围。",
                    })),
                    Err(error) => supplied_items.push(json!({
                        "type": "database_aggregate_error",
                        "source": "database_source",
                        "dataset_id": dataset.id,
                        "dataset_key": dataset.key,
                        "source_id": source.source_id,
                        "table": mapping.table,
                        "aggregate_role": aggregate_plan.role,
                        "aggregate_intent": aggregate_plan.intent,
                        "dimensions": aggregate_plan.dimensions.clone(),
                        "metric": metric,
                        "aggregation": aggregation,
                        "status": "aggregate_failed",
                        "message": error.to_string(),
                    })),
                }
            }
        }
    }

    Ok(supplied_items)
}

fn assistant_run_database_schema_context_item(
    dataset: &Dataset,
    source: &ExternalSourceConnectionSummary,
    mapping: &MySqlTableMapping,
    aggregate_plans: &[AssistantRunDatabaseAggregatePlan],
    metrics: &[String],
    scan_limit: u32,
) -> Value {
    let field_roles = assistant_run_database_mapping_field_roles(mapping);
    let metrics = if metrics.is_empty() {
        assistant_run_database_metric_columns(mapping)
    } else {
        metrics.to_vec()
    };
    let analysis_views = aggregate_plans
        .iter()
        .map(|plan| {
            json!({
                "role": plan.role,
                "intent": plan.intent,
                "dimensions": plan.dimensions,
            })
        })
        .collect::<Vec<_>>();
    json!({
        "type": "database_schema_context",
        "source": "database_source",
        "dataset_id": dataset.id,
        "dataset_key": dataset.key,
        "dataset_title": dataset.title,
        "source_id": source.source_id,
        "connector_kind": source.connector_kind,
        "table": mapping.table,
        "summary": assistant_run_database_schema_summary(mapping, &metrics, aggregate_plans, scan_limit),
        "field_roles": field_roles,
        "entity_dimensions": assistant_run_database_entity_dimensions(mapping),
        "time_dimensions": assistant_run_database_time_dimensions(mapping),
        "category_dimensions": assistant_run_database_category_dimensions(mapping),
        "metrics": metrics,
        "analysis_views": analysis_views,
        "answer_guidance": {
            "scope": "database_source_dataset_mapping",
            "metric_rule": "指标字段用于聚合，回答时说明 aggregation 和 scan_limit；若字段含义来自字段名启发式，应提示按业务口径确认。",
            "report_rule": "报表优先拆成实体排行、时间趋势、分类对比；不要把不同维度的聚合样本混成同一张图。",
            "scan_limit": scan_limit,
        },
    })
}

fn assistant_run_database_schema_summary(
    mapping: &MySqlTableMapping,
    metrics: &[String],
    aggregate_plans: &[AssistantRunDatabaseAggregatePlan],
    scan_limit: u32,
) -> String {
    let entity_dimensions = assistant_run_database_entity_dimensions(mapping);
    let time_dimensions = assistant_run_database_time_dimensions(mapping);
    let category_dimensions = assistant_run_database_category_dimensions(mapping);
    let view_labels = aggregate_plans
        .iter()
        .map(|plan| match plan.role {
            "ranking" => "实体排行",
            "trend" => "时间趋势",
            "comparison" => "分类对比",
            _ => "聚合分析",
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    format!(
        "数据库表 {}：实体维度 {}；时间维度 {}；分类维度 {}；指标 {}。本轮适合做 {}；聚合扫描上限 {} 行，回答或报表需说明聚合口径和采样范围。",
        mapping.table,
        assistant_run_database_join_or_dash(&entity_dimensions),
        assistant_run_database_join_or_dash(&time_dimensions),
        assistant_run_database_join_or_dash(&category_dimensions),
        assistant_run_database_join_or_dash(metrics),
        assistant_run_database_join_or_dash(&view_labels),
        scan_limit,
    )
}

fn assistant_run_database_join_or_dash<T: AsRef<str>>(items: &[T]) -> String {
    if items.is_empty() {
        "-".to_string()
    } else {
        items
            .iter()
            .map(|item| item.as_ref())
            .collect::<Vec<_>>()
            .join("/")
    }
}

fn assistant_run_database_mapping_field_roles(mapping: &MySqlTableMapping) -> Vec<Value> {
    assistant_run_database_mapping_columns(mapping)
        .into_iter()
        .map(|column| assistant_run_database_field_role(mapping, &column))
        .collect()
}

fn assistant_run_database_field_semantics_for_columns(
    mapping: &MySqlTableMapping,
    columns: &[String],
) -> Vec<Value> {
    columns
        .iter()
        .map(|column| {
            if column == "value" {
                json!({
                    "name": column,
                    "role": "aggregate_value",
                    "meaning": "聚合后的指标值",
                    "confidence": 95,
                    "source": "aggregate_result",
                })
            } else {
                assistant_run_database_field_role(mapping, column)
            }
        })
        .collect()
}

fn assistant_run_database_field_role(mapping: &MySqlTableMapping, column: &str) -> Value {
    let (role, confidence) = assistant_run_database_column_role(mapping, column);
    json!({
        "name": column,
        "role": role,
        "meaning": assistant_run_database_field_meaning(column, role),
        "confidence": confidence,
        "source": "mapping_and_name_heuristic",
    })
}

fn assistant_run_database_column_role(
    mapping: &MySqlTableMapping,
    column: &str,
) -> (&'static str, u8) {
    if mapping.id_column == column {
        return ("primary_key", 96);
    }
    if mapping.title_column.as_deref() == Some(column) {
        return ("entity", 92);
    }
    if assistant_run_database_time_dimensions(mapping)
        .iter()
        .any(|candidate| candidate == column)
    {
        return ("time", 90);
    }
    if assistant_run_database_metric_column_name(column) {
        return ("metric", 88);
    }
    if assistant_run_database_entity_column_name(column) {
        return ("entity", 84);
    }
    if mapping
        .id_columns
        .iter()
        .any(|candidate| candidate == column)
    {
        return ("primary_key", 86);
    }
    if assistant_run_database_category_dimensions(mapping)
        .iter()
        .any(|candidate| candidate == column)
    {
        return ("dimension", 84);
    }
    if mapping
        .metadata_columns
        .iter()
        .any(|candidate| candidate == column)
    {
        return ("dimension", 74);
    }
    if mapping
        .content_columns
        .iter()
        .any(|candidate| candidate == column)
    {
        return ("attribute", 64);
    }
    ("unknown", 42)
}

fn assistant_run_database_field_meaning(column: &str, role: &str) -> String {
    let lower = column.to_ascii_lowercase();
    if lower == "up" {
        return "上行/进入/进场方向的流量指标，具体业务口径需以客户定义为准。".to_string();
    }
    if lower == "down" {
        return "下行/离开/出场方向的流量指标，具体业务口径需以客户定义为准。".to_string();
    }
    if lower == "areaname" || lower.ends_with("area_name") || lower.contains("area_name") {
        return "区域或位置名称，适合作为排行、对比和筛选维度。".to_string();
    }
    if lower == "areatype" || lower.contains("area_type") {
        return "区域类型或分类，适合作为分类对比维度。".to_string();
    }
    if lower == "txdate" || lower.contains("date") || lower.contains("time") {
        return "业务发生时间或统计时间，适合作为趋势维度。".to_string();
    }
    if lower.ends_with("code") || lower.ends_with("_code") {
        return "业务编码字段，通常用于唯一识别或关联，不宜直接作为展示名称。".to_string();
    }
    if lower.ends_with("id") || lower.ends_with("_id") {
        return "业务 ID 字段，通常用于唯一识别或关联。".to_string();
    }
    match role {
        "metric" => "可聚合的数值指标，可用于汇总、排序、趋势和对比。".to_string(),
        "time" => "时间维度，可用于趋势、周期和时间范围分析。".to_string(),
        "entity" => "实体名称或对象名称，适合展示、排行和分组。".to_string(),
        "dimension" => "分类或属性维度，适合分组、筛选和对比。".to_string(),
        "primary_key" => "主键或近似主键，主要用于定位记录。".to_string(),
        "attribute" => "同步到数据集文档的属性字段，可用于补充上下文。".to_string(),
        _ => "字段语义暂不明确，使用时应结合样本值或业务说明确认。".to_string(),
    }
}

fn assistant_run_database_entity_dimensions(mapping: &MySqlTableMapping) -> Vec<String> {
    let mut dimensions = Vec::new();
    if let Some(title_column) = mapping.title_column.as_deref() {
        push_unique_string(&mut dimensions, title_column);
    }
    for column in assistant_run_database_mapping_columns(mapping) {
        let lower = column.to_ascii_lowercase();
        if lower.contains("name")
            || lower.ends_with("title")
            || assistant_run_database_entity_column_name(&column)
        {
            push_unique_string(&mut dimensions, &column);
        }
        if dimensions.len() >= 4 {
            break;
        }
    }
    if dimensions.is_empty() {
        push_unique_string(&mut dimensions, &mapping.id_column);
    }
    dimensions
}

fn assistant_run_database_time_dimensions(mapping: &MySqlTableMapping) -> Vec<String> {
    let mut dimensions = Vec::new();
    if let Some(time_column) = assistant_run_database_time_column(mapping) {
        push_unique_string(&mut dimensions, &time_column);
    }
    if let Some(updated_at_column) = mapping.updated_at_column.as_deref() {
        push_unique_string(&mut dimensions, updated_at_column);
    }
    dimensions
}

fn assistant_run_database_category_dimensions(mapping: &MySqlTableMapping) -> Vec<String> {
    let mut dimensions = Vec::new();
    if let Some(category_column) = assistant_run_database_category_dimension(mapping) {
        push_unique_string(&mut dimensions, &category_column);
    }
    let time_dimensions = assistant_run_database_time_dimensions(mapping);
    for column in assistant_run_database_mapping_columns(mapping) {
        if mapping.id_column == column
            || mapping
                .id_columns
                .iter()
                .any(|candidate| candidate == &column)
            || mapping.title_column.as_deref() == Some(column.as_str())
            || time_dimensions.iter().any(|candidate| candidate == &column)
            || assistant_run_database_metric_column_name(&column)
        {
            continue;
        }
        if assistant_run_database_dimension_column_name(&column) {
            push_unique_string(&mut dimensions, &column);
        }
        if dimensions.len() >= 6 {
            break;
        }
    }
    dimensions
}

fn assistant_run_database_metric_columns(mapping: &MySqlTableMapping) -> Vec<String> {
    let mut metrics = Vec::new();
    for column in assistant_run_database_mapping_columns(mapping) {
        if assistant_run_database_metric_column_name(&column) {
            push_unique_string(&mut metrics, &column);
        }
        if metrics.len() >= 8 {
            break;
        }
    }
    metrics
}

fn assistant_run_database_metric_column_name(column: &str) -> bool {
    let lower = column.to_ascii_lowercase();
    matches!(lower.as_str(), "up" | "down")
        || prompt_has_any(
            &lower,
            &[
                "count", "num", "amount", "total", "sum", "rate", "ratio", "score", "value",
                "price", "cost", "traffic", "flow", "volume", "qty", "avg", "duration", "amt",
                "sale", "sales", "sold", "rent", "fee", "zujin", "xiaoshou", "quekou", "jine",
                "ticheng", "dayamt", "yuezu", "fdxshje", "yze", "rdj",
            ],
        )
}

fn assistant_run_database_entity_column_name(column: &str) -> bool {
    let lower = column.to_ascii_lowercase();
    matches!(
        lower.as_str(),
        "shopdesc"
            | "shopname"
            | "shop_name"
            | "storedesc"
            | "store_desc"
            | "storename"
            | "store_name"
            | "branddesc"
            | "brand_name"
            | "brandname"
            | "leasename"
            | "lease_name"
    )
}

fn assistant_run_database_dimension_column_name(column: &str) -> bool {
    let lower = column.to_ascii_lowercase();
    prompt_has_any(
        &lower,
        &[
            "type", "status", "category", "class", "level", "gender", "city", "province",
            "district", "region", "area", "source", "channel", "tag",
        ],
    )
}

fn assistant_run_database_aggregate_summary(
    mapping: &MySqlTableMapping,
    role: &str,
    dimensions: &[String],
    metric: Option<&str>,
    aggregation: &str,
    order_direction: &str,
    latest_time_column: Option<&str>,
    row_count: usize,
    scan_limit: Option<u32>,
) -> String {
    let role_label = match role {
        "ranking" => "实体排行",
        "trend" => "时间趋势",
        "comparison" => "分类对比",
        _ => "聚合分析",
    };
    let order_label = if order_direction.eq_ignore_ascii_case("asc") {
        "升序"
    } else {
        "降序"
    };
    let time_filter = latest_time_column
        .map(|column| format!("；时间口径为最新 {column}"))
        .unwrap_or_default();
    format!(
        "{}：表 {} 按 {} 对 {} 做 {} 聚合并按聚合值{}{}，返回 {} 行样本，扫描上限 {}。",
        role_label,
        mapping.table,
        assistant_run_database_join_or_dash(dimensions),
        metric.unwrap_or("record_count"),
        aggregation,
        order_label,
        time_filter,
        row_count,
        scan_limit
            .map(|value| value.to_string())
            .unwrap_or_else(|| "-".to_string())
    )
}

async fn load_dataset_external_source_ids(
    state: &AppState,
    dataset_id: DatasetId,
) -> std::result::Result<Vec<String>, ApiError> {
    let rows = sqlx::query(
        r#"
        with document_sources as (
            select metadata #>> '{external_source,source_id}' as source_id,
                   count(*)::bigint as document_count,
                   0 as source_priority
            from documents
            where tenant_id = $1
              and dataset_id = $2
              and metadata #>> '{external_source,source_id}' is not null
            group by source_id
        ),
        configured_database_sources as (
            select id as source_id,
                   0::bigint as document_count,
                   1 as source_priority
            from external_source_connections
            where tenant_id = $1
              and disabled_at is null
              and lower(trim(connector_kind)) in ('mysql', 'mysql_source', 'database_source')
              and coalesce(
                    config_redacted #>> '{database_source,default_dataset_id}',
                    config_redacted #>> '{databaseSource,defaultDatasetId}',
                    config_redacted #>> '{mysql_source,default_dataset_id}',
                    config_redacted #>> '{mysqlSource,defaultDatasetId}'
                  ) = $2::text
        ),
        combined_sources as (
            select source_id, document_count, source_priority
            from document_sources
            union all
            select source_id, document_count, source_priority
            from configured_database_sources
        )
        select source_id
        from combined_sources
        where source_id is not null and btrim(source_id) <> ''
        group by source_id
        order by min(source_priority) asc, max(document_count) desc, source_id asc
        limit $3
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(dataset_id.0)
    .bind(ASSISTANT_RUN_DATABASE_SOURCE_LIMIT as i64)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    Ok(rows
        .into_iter()
        .filter_map(|row| row.try_get::<Option<String>, _>("source_id").ok().flatten())
        .map(|source_id| source_id.trim().to_string())
        .filter(|source_id| !source_id.is_empty())
        .collect())
}

#[derive(Clone, Debug)]
struct AssistantRunAttendanceRow {
    employee: String,
    date: String,
    shift: String,
    first_punch: Option<String>,
    last_punch: Option<String>,
    work_hours: Option<f64>,
    status: String,
    source_locator: String,
}

async fn build_assistant_run_spreadsheet_row_analysis_supply(
    state: &AppState,
    dataset: &Dataset,
    prompt: &str,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<Vec<Value>, ApiError> {
    if selected_document_ids.is_empty()
        || !prompt_requests_spreadsheet_row_level_analysis(prompt)
        || prompt_has_resume_signal(prompt)
    {
        return Ok(Vec::new());
    }

    let documents = list_documents_for_dataset_scope(state, dataset.id)
        .await?
        .into_iter()
        .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
        .filter(|document| selected_document_ids.contains(&document.id))
        .collect::<Vec<_>>();
    let mut rows = Vec::new();
    let mut document_refs = Vec::new();
    for document in documents {
        if !document_is_visible_for_external_acl(
            state,
            external_acl_filter,
            &document,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?
        {
            continue;
        }
        document_refs.push(json!({
            "document_id": document.id,
            "title": document.title.clone(),
        }));
        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        for chunk in chunks {
            let source_locator = document_chunk_fallback_source_locator(&document, &chunk);
            for line in chunk.content.lines() {
                if let Some(row) = parse_assistant_run_attendance_row(line, source_locator.clone())
                {
                    rows.push(row);
                }
            }
        }
    }
    if rows.is_empty() {
        return Ok(Vec::new());
    }

    let Some((analysis_kind, analysis_rows, content_excerpt)) =
        assistant_run_attendance_analysis_rows(prompt, &rows)
    else {
        return Ok(Vec::new());
    };
    if analysis_rows.is_empty() {
        return Ok(Vec::new());
    }

    Ok(vec![json!({
        "type": "spreadsheet_row_analysis",
        "source": "selected_document_table_rows",
        "dataset_id": dataset.id,
        "analysis_kind": analysis_kind,
        "summary": format!(
            "已从选中文档解析 {} 条考勤明细行，并按用户问题预计算 {} 条结果行。",
            rows.len(),
            analysis_rows.len()
        ),
        "content_excerpt": content_excerpt,
        "row_count": rows.len(),
        "result_row_count": analysis_rows.len(),
        "rows": analysis_rows,
        "documents": document_refs,
        "source_locator": format!("dataset://{}/spreadsheet-row-analysis/{}", dataset.id, analysis_kind),
        "score": 1.0,
        "lexical_score": 1.0,
        "recall_score": 1.0,
        "model_guidance": [
            "For attendance, work-hour, absence, and daily earliest-clock-in questions, treat spreadsheet_row_analysis.rows as the deterministic computed table.",
            "Use retrieval_evidence only to cross-check source wording; do not recompute maxima, minima, or earliest times from raw chunks when this item is present.",
            "For work-hour extremes, use rows whose category is longest/shortest; do not treat missing-punch, non-attendance, or 0-hour absence rows as shortest work time.",
            "Keep dates in YYYY-MM-DD and times in HH:MM."
        ]
    })])
}

fn parse_assistant_run_attendance_row(
    line: &str,
    source_locator: String,
) -> Option<AssistantRunAttendanceRow> {
    let tokens = line
        .split_whitespace()
        .map(str::trim)
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>();
    let date_index = tokens
        .iter()
        .position(|token| assistant_run_token_is_iso_date(token))?;
    if date_index == 0 || date_index + 1 >= tokens.len() {
        return None;
    }
    let employee = tokens[date_index - 1].trim_matches('|').to_string();
    let date = tokens[date_index].to_string();
    let shift = tokens[date_index + 1].to_string();
    if employee.is_empty() || employee == "员工" || shift == "班次" {
        return None;
    }

    let mut first_punch = None;
    let mut last_punch = None;
    let mut work_hours = None;
    let mut status_parts = Vec::new();
    for token in tokens.into_iter().skip(date_index + 2) {
        if let Some(time) = assistant_run_normalize_hhmm_token(token) {
            if first_punch.is_none() {
                first_punch = Some(time);
            } else if last_punch.is_none() {
                last_punch = Some(time);
            }
            continue;
        }
        if work_hours.is_none() {
            if let Some(hours) = assistant_run_parse_work_hours_token(token) {
                work_hours = Some(hours);
                continue;
            }
        }
        if token != "|" {
            status_parts.push(token.trim_matches('|').to_string());
        }
    }

    Some(AssistantRunAttendanceRow {
        employee,
        date,
        shift,
        first_punch,
        last_punch,
        work_hours,
        status: status_parts.join(" "),
        source_locator,
    })
}

fn assistant_run_token_is_iso_date(token: &str) -> bool {
    let bytes = token.as_bytes();
    bytes.len() == 10
        && bytes[4] == b'-'
        && bytes[7] == b'-'
        && bytes
            .iter()
            .enumerate()
            .all(|(index, byte)| matches!(index, 4 | 7) || byte.is_ascii_digit())
}

fn assistant_run_normalize_hhmm_token(token: &str) -> Option<String> {
    let token = token.trim_matches(|ch: char| ch == '|' || ch == ',' || ch == ';');
    let (hour, minute) = token.split_once(':')?;
    if hour.len() > 2 || minute.len() != 2 {
        return None;
    }
    let hour = hour.parse::<u32>().ok()?;
    let minute = minute.parse::<u32>().ok()?;
    if hour > 23 || minute > 59 {
        return None;
    }
    Some(format!("{hour:02}:{minute:02}"))
}

fn assistant_run_parse_work_hours_token(token: &str) -> Option<f64> {
    let token = token.trim_matches('|').trim_end_matches("小时");
    if token.is_empty() || token == "未打卡" {
        return None;
    }
    token.parse::<f64>().ok()
}

fn assistant_run_hhmm_minutes(value: &str) -> Option<u32> {
    let (hour, minute) = value.split_once(':')?;
    let hour = hour.parse::<u32>().ok()?;
    let minute = minute.parse::<u32>().ok()?;
    Some(hour * 60 + minute)
}

fn assistant_run_attendance_analysis_rows(
    prompt: &str,
    rows: &[AssistantRunAttendanceRow],
) -> Option<(&'static str, Vec<Value>, String)> {
    let requests_absence = prompt_contains_any(prompt, &["缺勤", "未打卡", "没打卡"]);
    let requests_work_hours = prompt_contains_any(prompt, &["最长", "最短", "长短", "工时"]);
    if requests_absence && requests_work_hours {
        let mut analysis_rows = assistant_run_absence_attendance_rows(rows);
        analysis_rows.extend(assistant_run_work_hour_extreme_rows(rows));
        let content_excerpt = assistant_run_combined_attendance_rows_markdown(&analysis_rows);
        return Some((
            "absence_and_work_hour_extremes",
            analysis_rows,
            content_excerpt,
        ));
    }
    if prompt_contains_any(prompt, &["最早", "上班"]) {
        let analysis_rows = assistant_run_daily_earliest_attendance_rows(rows);
        let content_excerpt = assistant_run_attendance_rows_markdown(
            "日期 | 最早上班员工 | 首打卡时间",
            &analysis_rows,
        );
        return Some(("daily_earliest_first_punch", analysis_rows, content_excerpt));
    }
    if prompt_contains_any(prompt, &["最长", "最短", "长短", "工时"]) {
        let analysis_rows = assistant_run_work_hour_extreme_rows(rows);
        let content_excerpt =
            assistant_run_attendance_rows_markdown("类别 | 日期 | 员工 | 工时", &analysis_rows);
        return Some(("work_hour_extremes", analysis_rows, content_excerpt));
    }
    if requests_absence {
        let analysis_rows = assistant_run_absence_attendance_rows(rows);
        let content_excerpt =
            assistant_run_attendance_rows_markdown("日期 | 员工 | 班次 | 状态", &analysis_rows);
        return Some(("absence_candidates", analysis_rows, content_excerpt));
    }
    None
}

fn assistant_run_daily_earliest_attendance_rows(rows: &[AssistantRunAttendanceRow]) -> Vec<Value> {
    let mut by_date = BTreeMap::<String, (&AssistantRunAttendanceRow, u32)>::new();
    for row in rows {
        let Some(first_punch) = row.first_punch.as_deref() else {
            continue;
        };
        let Some(minutes) = assistant_run_hhmm_minutes(first_punch) else {
            continue;
        };
        match by_date.get(&row.date) {
            Some((_, current_minutes)) if *current_minutes <= minutes => {}
            _ => {
                by_date.insert(row.date.clone(), (row, minutes));
            }
        }
    }
    by_date
        .into_iter()
        .rev()
        .map(|(date, (row, _))| {
            json!({
                "date": date,
                "employee": row.employee.clone(),
                "first_punch": row.first_punch.clone(),
                "shift": row.shift.clone(),
                "source_locator": row.source_locator.clone(),
            })
        })
        .collect()
}

fn assistant_run_work_hour_extreme_rows(rows: &[AssistantRunAttendanceRow]) -> Vec<Value> {
    let hour_rows = rows
        .iter()
        .filter_map(|row| {
            row.work_hours
                .filter(|hours| assistant_run_attendance_row_has_countable_work_hours(row, *hours))
                .map(|hours| (row, hours))
        })
        .collect::<Vec<_>>();
    let Some((shortest_row, shortest_hours)) = hour_rows
        .iter()
        .min_by(|left, right| left.1.total_cmp(&right.1))
        .copied()
    else {
        return Vec::new();
    };
    let Some((longest_row, longest_hours)) = hour_rows
        .iter()
        .max_by(|left, right| left.1.total_cmp(&right.1))
        .copied()
    else {
        return Vec::new();
    };
    vec![
        assistant_run_work_hour_extreme_value("longest", longest_row, longest_hours),
        assistant_run_work_hour_extreme_value("shortest", shortest_row, shortest_hours),
    ]
}

fn assistant_run_attendance_row_has_countable_work_hours(
    row: &AssistantRunAttendanceRow,
    hours: f64,
) -> bool {
    hours > 0.0
        && row.first_punch.is_some()
        && row.last_punch.is_some()
        && !row.status.contains("未打卡")
        && !row.status.contains("不考勤")
}

fn assistant_run_work_hour_extreme_value(
    category: &str,
    row: &AssistantRunAttendanceRow,
    hours: f64,
) -> Value {
    json!({
        "category": category,
        "date": row.date.clone(),
        "employee": row.employee.clone(),
        "work_hours": hours,
        "work_hours_text": format!("{hours:.2}小时"),
        "shift": row.shift.clone(),
        "first_punch": row.first_punch.clone(),
        "last_punch": row.last_punch.clone(),
        "status": row.status.clone(),
        "source_locator": row.source_locator.clone(),
    })
}

fn assistant_run_absence_attendance_rows(rows: &[AssistantRunAttendanceRow]) -> Vec<Value> {
    rows.iter()
        .filter(|row| row.first_punch.is_none() && row.status.contains("未打卡"))
        .filter(|row| row.shift.contains("坐班"))
        .map(|row| {
            json!({
                "date": row.date.clone(),
                "employee": row.employee.clone(),
                "shift": row.shift.clone(),
                "status": row.status.clone(),
                "counts_as_absence": !row.status.contains("不考勤"),
                "source_locator": row.source_locator.clone(),
            })
        })
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .take(80)
        .collect()
}

fn assistant_run_attendance_rows_markdown(header: &str, rows: &[Value]) -> String {
    let mut lines = vec![header.to_string()];
    for row in rows.iter().take(80) {
        if let Some(category) = row.get("category").and_then(Value::as_str) {
            lines.push(format!(
                "{} | {} | {} | {}",
                category,
                row.get("date").and_then(Value::as_str).unwrap_or(""),
                row.get("employee").and_then(Value::as_str).unwrap_or(""),
                row.get("work_hours_text")
                    .and_then(Value::as_str)
                    .unwrap_or("")
            ));
        } else if let Some(first_punch) = row.get("first_punch").and_then(Value::as_str) {
            lines.push(format!(
                "{} | {} | {}",
                row.get("date").and_then(Value::as_str).unwrap_or(""),
                row.get("employee").and_then(Value::as_str).unwrap_or(""),
                first_punch
            ));
        } else {
            lines.push(format!(
                "{} | {} | {} | {}",
                row.get("date").and_then(Value::as_str).unwrap_or(""),
                row.get("employee").and_then(Value::as_str).unwrap_or(""),
                row.get("shift").and_then(Value::as_str).unwrap_or(""),
                row.get("status").and_then(Value::as_str).unwrap_or("")
            ));
        }
    }
    lines.join("\n")
}

fn assistant_run_combined_attendance_rows_markdown(rows: &[Value]) -> String {
    let mut lines = vec!["类型 | 日期 | 员工 | 明细 | 状态".to_string()];
    for row in rows.iter().take(82) {
        if let Some(category) = row.get("category").and_then(Value::as_str) {
            lines.push(format!(
                "{} | {} | {} | {} | {}",
                category,
                row.get("date").and_then(Value::as_str).unwrap_or(""),
                row.get("employee").and_then(Value::as_str).unwrap_or(""),
                row.get("work_hours_text")
                    .and_then(Value::as_str)
                    .unwrap_or(""),
                row.get("status").and_then(Value::as_str).unwrap_or("")
            ));
        } else {
            lines.push(format!(
                "absence_candidate | {} | {} | {} | {}",
                row.get("date").and_then(Value::as_str).unwrap_or(""),
                row.get("employee").and_then(Value::as_str).unwrap_or(""),
                row.get("shift").and_then(Value::as_str).unwrap_or(""),
                row.get("status").and_then(Value::as_str).unwrap_or("")
            ));
        }
    }
    lines.join("\n")
}

