fn assistant_run_database_mapping_for_prompt<'a>(
    config: &'a MySqlSourceConfig,
    prompt: &str,
) -> Option<&'a MySqlTableMapping> {
    let normalized = prompt.to_ascii_lowercase();
    config
        .tables
        .iter()
        .find(|mapping| normalized.contains(&mapping.table.to_ascii_lowercase()))
        .or_else(|| config.tables.first())
}

fn assistant_run_database_schema_mappings_for_prompt<'a>(
    config: &'a MySqlSourceConfig,
    prompt: &str,
) -> Vec<&'a MySqlTableMapping> {
    let normalized = prompt.to_ascii_lowercase();
    let mut mappings = config
        .tables
        .iter()
        .filter(|mapping| normalized.contains(&mapping.table.to_ascii_lowercase()))
        .take(ASSISTANT_RUN_DATABASE_SCHEMA_TABLE_LIMIT)
        .collect::<Vec<_>>();
    if mappings.is_empty() {
        mappings = config
            .tables
            .iter()
            .take(ASSISTANT_RUN_DATABASE_SCHEMA_TABLE_LIMIT)
            .collect();
    }
    mappings
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct AssistantRunDatabaseAggregatePlan {
    role: &'static str,
    intent: &'static str,
    dimensions: Vec<String>,
}

fn assistant_run_database_aggregate_dimension_plans(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Vec<AssistantRunDatabaseAggregatePlan> {
    let wants_report = assistant_run_database_prompt_wants_report(prompt);
    let wants_rank = wants_report
        || prompt_has_any(
            prompt,
            &[
                "区域", "位置", "楼层", "门", "梯", "点位", "areaname", "area", "top", "排名",
                "排行", "排序", "前", "最高", "最大", "哪些", "哪个", "店铺", "门店", "分店",
                "品牌",
            ],
        );
    let wants_trend = wants_report
        || prompt_has_any(
            prompt,
            &[
                "时间", "日期", "小时", "日", "趋势", "变化", "txdate", "date", "time", "by time",
            ],
        );
    let wants_comparison = wants_report
        || prompt_has_any(
            prompt,
            &[
                "对比", "分类", "类型", "类别", "维度", "areatype", "category", "type",
            ],
        );

    let mut plans = Vec::new();
    if wants_rank {
        if let Some(dimension) = assistant_run_database_prompt_entity_dimension(mapping, prompt)
            .or_else(|| assistant_run_database_entity_dimension(mapping))
        {
            push_assistant_run_database_aggregate_plan(
                &mut plans,
                "ranking",
                "entity_topn",
                vec![dimension],
            );
        }
    }
    if wants_trend {
        if let Some(dimension) = assistant_run_database_time_column(mapping) {
            push_assistant_run_database_aggregate_plan(
                &mut plans,
                "trend",
                "time_series",
                vec![dimension],
            );
        }
    }
    if wants_comparison {
        if let Some(dimension) = assistant_run_database_category_dimension(mapping) {
            push_assistant_run_database_aggregate_plan(
                &mut plans,
                "comparison",
                "category_comparison",
                vec![dimension],
            );
        }
    }
    if plans.is_empty() {
        push_assistant_run_database_aggregate_plan(
            &mut plans,
            "primary",
            "prompt_requested",
            assistant_run_database_aggregate_dimensions(mapping, prompt),
        );
    }
    plans.truncate(ASSISTANT_RUN_DATABASE_AGGREGATE_REQUEST_LIMIT);
    plans
}

fn assistant_run_database_prompt_wants_report(prompt: &str) -> bool {
    prompt_has_any(
        prompt,
        &[
            "报表",
            "报告",
            "看板",
            "仪表盘",
            "图文",
            "静态页",
            "html",
            "dashboard",
            "report",
            "visual",
        ],
    )
}

fn push_assistant_run_database_aggregate_plan(
    plans: &mut Vec<AssistantRunDatabaseAggregatePlan>,
    role: &'static str,
    intent: &'static str,
    dimensions: Vec<String>,
) {
    if dimensions.is_empty()
        || plans
            .iter()
            .any(|existing| existing.dimensions == dimensions)
    {
        return;
    }
    plans.push(AssistantRunDatabaseAggregatePlan {
        role,
        intent,
        dimensions,
    });
}

fn assistant_run_database_entity_dimension(mapping: &MySqlTableMapping) -> Option<String> {
    mapping
        .title_column
        .as_deref()
        .map(ToOwned::to_owned)
        .or_else(|| Some(mapping.id_column.clone()))
}

fn assistant_run_database_prompt_entity_dimension(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Option<String> {
    let columns = assistant_run_database_mapping_columns(mapping);
    let find_column = |patterns: &[&str]| {
        patterns.iter().find_map(|pattern| {
            columns
                .iter()
                .find(|column| column.to_ascii_lowercase().contains(pattern))
                .cloned()
        })
    };
    if prompt_has_any(
        prompt,
        &["店铺", "门店", "分店", "店名", "柜组", "专柜", "shop"],
    ) {
        return find_column(&[
            "shopdesc",
            "shop_name",
            "shopname",
            "storedesc",
            "store_name",
            "storename",
            "store_init",
        ]);
    }
    if prompt_has_any(prompt, &["品牌", "租户", "商户", "brand", "lease"]) {
        return find_column(&[
            "branddesc",
            "brand_name",
            "brandname",
            "leasename",
            "lease_name",
        ]);
    }
    if prompt_has_any(prompt, &["品类", "业态", "类目", "category"]) {
        return find_column(&["catgldesc", "catgmdesc", "catgsdesc", "category"]);
    }
    if prompt_has_any(prompt, &["大区", "区域", "小区", "片区", "region", "area"]) {
        return find_column(&[
            "dist_name",
            "areaname",
            "area_name",
            "region",
            "omdname",
            "parentname",
            "area",
        ]);
    }
    if prompt_has_any(prompt, &["合同", "contract"]) {
        return find_column(&["contract_no", "htbh"]);
    }
    None
}

fn assistant_run_database_category_dimension(mapping: &MySqlTableMapping) -> Option<String> {
    let columns = assistant_run_database_mapping_columns(mapping);
    columns
        .iter()
        .find(|column| column.eq_ignore_ascii_case("areatype"))
        .cloned()
        .or_else(|| {
            columns
                .iter()
                .find(|column| {
                    let lower = column.to_ascii_lowercase();
                    lower.contains("category")
                        || lower.contains("type")
                        || lower.contains("class")
                        || lower.contains("kind")
                        || lower.contains("status")
                        || lower.contains("level")
                })
                .cloned()
        })
}

fn assistant_run_database_aggregate_metrics(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Vec<String> {
    let mut metrics = Vec::new();
    if prompt_has_metric_terms(
        prompt,
        &[
            "取高",
            "高分成",
            "分成线",
            "缺口",
            "差多少",
            "还差",
            "需增",
            "机会",
            "接近",
            "就快",
        ],
    ) {
        push_database_metric_if_present(mapping, &mut metrics, "xuzengxiaoshou");
        push_database_metric_if_present(mapping, &mut metrics, "quekou");
    }
    if prompt_has_metric_terms(prompt, &["销售", "销售额", "成交", "sale", "sales", "sold"])
    {
        push_database_metric_if_present(mapping, &mut metrics, "amttotal");
        push_database_metric_if_present(mapping, &mut metrics, "amtsold");
        push_database_metric_if_present(mapping, &mut metrics, "sale_num");
        push_database_metric_if_present(mapping, &mut metrics, "salenum");
    }
    if prompt_has_metric_terms(prompt, &["租金", "提成", "固定", "rent", "fee"]) {
        push_database_metric_if_present(mapping, &mut metrics, "tichengzujin");
        push_database_metric_if_present(mapping, &mut metrics, "yuezujin");
        push_database_metric_if_present(mapping, &mut metrics, "htzj");
    }
    if prompt_has_metric_terms(prompt, &["down", "下行", "离开", "离场", "出场", "出口"])
    {
        push_database_metric_if_present(mapping, &mut metrics, "down");
    }
    if prompt_has_metric_terms(prompt, &["up", "上行", "进入", "进场", "入口"]) {
        push_database_metric_if_present(mapping, &mut metrics, "up");
    }
    if metrics.is_empty() && prompt_has_metric_terms(prompt, &["流量", "客流", "traffic"]) {
        push_database_metric_if_present(mapping, &mut metrics, "up");
        push_database_metric_if_present(mapping, &mut metrics, "down");
    }
    if metrics.is_empty() {
        for column in assistant_run_database_metric_columns(mapping) {
            push_unique_string(&mut metrics, &column);
            if metrics.len() >= ASSISTANT_RUN_DATABASE_AGGREGATE_METRIC_LIMIT {
                break;
            }
        }
    }
    metrics.truncate(ASSISTANT_RUN_DATABASE_AGGREGATE_METRIC_LIMIT);
    metrics
}

fn push_database_metric_if_present(
    mapping: &MySqlTableMapping,
    metrics: &mut Vec<String>,
    column: &str,
) {
    if metrics.iter().any(|metric| metric == column) {
        return;
    }
    if assistant_run_database_mapping_columns(mapping)
        .iter()
        .any(|candidate| candidate == column)
    {
        metrics.push(column.to_string());
    }
}

fn assistant_run_database_aggregate_dimensions(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Vec<String> {
    let mut dimensions = Vec::new();
    let wants_time = prompt_has_any(
        prompt,
        &[
            "时间", "日期", "小时", "日", "趋势", "txdate", "date", "time", "by time",
        ],
    );
    let wants_entity = prompt_has_any(
        prompt,
        &[
            "区域", "位置", "楼层", "门", "梯", "点位", "areaname", "area", "top", "排名", "排行",
            "排序", "前",
        ],
    );
    if wants_entity {
        if let Some(dimension) = assistant_run_database_prompt_entity_dimension(mapping, prompt)
            .or_else(|| assistant_run_database_entity_dimension(mapping))
        {
            push_unique_string(&mut dimensions, &dimension);
        }
    }
    if wants_time {
        if let Some(time_column) = assistant_run_database_time_column(mapping) {
            push_unique_string(&mut dimensions, &time_column);
        }
    }
    if dimensions.is_empty() {
        if let Some(title_column) = mapping.title_column.as_deref() {
            push_unique_string(&mut dimensions, title_column);
        }
    }
    dimensions.truncate(3);
    dimensions
}

fn assistant_run_database_time_column(mapping: &MySqlTableMapping) -> Option<String> {
    let columns = assistant_run_database_mapping_columns(mapping);
    columns
        .iter()
        .find(|column| column.eq_ignore_ascii_case("txdate"))
        .cloned()
        .or_else(|| {
            columns
                .iter()
                .find(|column| {
                    let lower = column.to_ascii_lowercase();
                    lower.contains("date") || lower.contains("time")
                })
                .cloned()
        })
}

fn assistant_run_database_aggregation(prompt: &str, has_metric: bool) -> String {
    if !has_metric {
        return "count".to_string();
    }
    if prompt_has_any(prompt, &["平均", "avg", "average"]) {
        "avg".to_string()
    } else if prompt_has_any(prompt, &["最低", "最小", "min"]) {
        "min".to_string()
    } else if prompt_has_any(prompt, &["单点最大", "最大值", "max"]) {
        "max".to_string()
    } else {
        "sum".to_string()
    }
}

fn assistant_run_database_aggregate_order_direction(prompt: &str, metric: Option<&str>) -> String {
    if prompt_has_any(prompt, &["最低", "最小", "min", "升序"]) {
        return "asc".to_string();
    }
    let metric = metric.unwrap_or("").to_ascii_lowercase();
    let gap_metric = metric.contains("xuzeng")
        || metric.contains("quekou")
        || metric.contains("gap")
        || metric.contains("shortfall");
    if gap_metric
        && prompt_has_any(
            prompt,
            &[
                "取高机会",
                "机会最大",
                "最接近",
                "接近",
                "就快",
                "差多少",
                "还差",
                "高分成线",
            ],
        )
        && !prompt_has_any(prompt, &["缺口最大", "最大缺口", "差距最大"])
    {
        return "asc".to_string();
    }
    "desc".to_string()
}

fn assistant_run_database_aggregate_latest_time_column(
    mapping: &MySqlTableMapping,
    prompt: &str,
    metric: Option<&str>,
    aggregate_plan: &AssistantRunDatabaseAggregatePlan,
) -> Option<String> {
    if aggregate_plan.intent == "time_series" {
        return None;
    }
    let time_column = assistant_run_database_time_column(mapping)?;
    if aggregate_plan
        .dimensions
        .iter()
        .any(|dimension| dimension == &time_column)
    {
        return None;
    }
    if prompt_has_any(
        prompt,
        &[
            "趋势",
            "变化",
            "按日",
            "按天",
            "按时间",
            "历史",
            "区间",
            "同比",
            "环比",
            "trend",
        ],
    ) {
        return None;
    }
    let metric = metric.unwrap_or("").to_ascii_lowercase();
    let current_metric = metric.contains("yuezujin")
        || metric.contains("zujin")
        || metric.contains("rent")
        || metric.contains("amttotal")
        || metric.contains("ticheng")
        || metric.contains("xuzeng")
        || metric.contains("quekou")
        || metric.contains("dayamt")
        || metric.contains("salenum")
        || metric.contains("sale");
    let current_prompt = prompt_has_any(
        prompt,
        &[
            "当前",
            "现在",
            "目前",
            "本月",
            "最新",
            "经营健康度",
            "总览",
            "月租金",
            "租金",
            "取高",
            "高分成",
            "缺口",
            "销售额",
            "还差",
            "最接近",
        ],
    );
    if current_metric || current_prompt {
        return Some(time_column);
    }
    None
}

fn assistant_run_database_mapping_columns(mapping: &MySqlTableMapping) -> Vec<String> {
    let mut columns = Vec::new();
    push_unique_string(&mut columns, &mapping.id_column);
    for column in &mapping.id_columns {
        push_unique_string(&mut columns, column);
    }
    if let Some(column) = mapping.title_column.as_deref() {
        push_unique_string(&mut columns, column);
    }
    for column in &mapping.content_columns {
        push_unique_string(&mut columns, column);
    }
    if let Some(column) = mapping.updated_at_column.as_deref() {
        push_unique_string(&mut columns, column);
    }
    if let Some(column) = mapping.version_column.as_deref() {
        push_unique_string(&mut columns, column);
    }
    for column in &mapping.metadata_columns {
        push_unique_string(&mut columns, column);
    }
    columns
}

fn assistant_run_database_aggregate_scan_limit() -> u32 {
    std::env::var("ASSISTANT_RUN_DATABASE_AGGREGATE_SCAN_LIMIT")
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(ASSISTANT_RUN_DATABASE_AGGREGATE_SCAN_LIMIT_DEFAULT)
        .clamp(1, ASSISTANT_RUN_DATABASE_AGGREGATE_SCAN_LIMIT_MAX)
}

fn prompt_has_any(prompt: &str, needles: &[&str]) -> bool {
    let lower = prompt.to_ascii_lowercase();
    needles.iter().any(|needle| {
        let needle = needle.to_ascii_lowercase();
        !needle.is_empty() && lower.contains(&needle)
    })
}

fn prompt_has_metric_terms(prompt: &str, needles: &[&str]) -> bool {
    let lower = prompt.to_ascii_lowercase();
    needles.iter().any(|needle| {
        let needle = needle.to_ascii_lowercase();
        if needle.is_empty() {
            return false;
        }
        if needle
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || ch == '_')
        {
            return contains_ascii_token(&lower, &needle);
        }
        lower.contains(&needle)
    })
}

fn contains_ascii_token(haystack: &str, needle: &str) -> bool {
    haystack.match_indices(needle).any(|(index, _)| {
        let before = haystack[..index].chars().next_back();
        let after = haystack[index + needle.len()..].chars().next();
        !before.is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == '_')
            && !after.is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == '_')
    })
}

async fn build_assistant_run_document_parse_status_supply(
    state: &AppState,
    dataset: &Dataset,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<Vec<Value>, ApiError> {
    let candidate_documents = list_documents_for_dataset_scope(state, dataset.id)
        .await?
        .into_iter()
        .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
        .filter(|document| {
            selected_document_ids.is_empty() || selected_document_ids.contains(&document.id)
        })
        .collect::<Vec<_>>();

    if candidate_documents.is_empty() {
        return Ok(Vec::new());
    }

    let mut documents = Vec::new();
    let mut limited_by_document_limit = false;
    for document in candidate_documents {
        if documents.len() >= ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_DOCUMENT_LIMIT {
            limited_by_document_limit = true;
            break;
        }
        if !document_is_visible_for_external_acl(
            state,
            external_acl_filter,
            &document,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?
        {
            continue;
        }
        documents.push(document);
    }

    if documents.is_empty() {
        return Ok(Vec::new());
    }

    let document_ids = documents
        .iter()
        .map(|document| document.id)
        .collect::<Vec<_>>();
    let workflow_by_document =
        load_latest_upload_ingest_workflow_snapshots(state, dataset.id, &document_ids).await?;

    let mut scanned_document_count = 0usize;
    let mut status_counts = BTreeMap::<String, usize>::new();
    let mut attention_documents = Vec::new();
    let mut active_parse_count = 0usize;
    let mut failed_document_count = 0usize;
    let mut reparsing_document_count = 0usize;
    let mut degraded_parse_count = 0usize;

    for document in documents {
        scanned_document_count += 1;

        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        let parse_status = assistant_scope_document_parse_status(&document, &chunks);
        let inferred_parse_quality_summary =
            assistant_run_inferred_low_text_parse_quality_summary(&document, &chunks);
        let parse_quality_summary = assistant_run_document_parse_quality_summary(&document)
            .or_else(|| inferred_parse_quality_summary.clone());
        let parse_quality_status =
            assistant_run_document_parse_quality_status(&document).or_else(|| {
                parse_quality_summary
                    .as_ref()
                    .and_then(|summary| value_at_any_key(summary, &["status"]))
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .map(ToOwned::to_owned)
            });
        let workflow = workflow_by_document.get(&document.id);
        let model_status = assistant_run_document_parse_model_status(
            &document,
            &parse_status,
            chunks.len(),
            parse_quality_status.as_deref(),
            workflow,
        );
        *status_counts.entry(model_status.clone()).or_insert(0) += 1;

        if assistant_run_document_parse_status_is_active(&model_status) {
            active_parse_count += 1;
        }
        if model_status == "failed" {
            failed_document_count += 1;
        }
        if model_status == "reparsing" || model_status == "reparse_queued" {
            reparsing_document_count += 1;
        }
        if model_status == "parse_degraded" {
            degraded_parse_count += 1;
        }

        if assistant_run_document_parse_status_needs_attention(&model_status) {
            let mut item = json!({
                "document_id": document.id,
                "title": document.title.clone(),
                "content_type": document.content_type.clone(),
                "lifecycle": document.lifecycle.as_str(),
                "parse_status": parse_status,
                "model_status": model_status,
                "chunk_count": chunks.len(),
                "updated_at": document.updated_at,
                "ingest": assistant_run_document_ingest_summary(&document),
            });
            if let Some(parse_quality_status) = parse_quality_status {
                set_payload_string(&mut item, "parse_quality_status", &parse_quality_status);
            }
            if let Some(parse_quality_summary) = parse_quality_summary {
                set_payload_value(&mut item, "parse_quality_summary", parse_quality_summary);
            }
            if let Some(workflow) = workflow {
                set_payload_value(&mut item, "workflow", workflow.clone());
            }
            if let Some(external_ref) = assistant_run_document_external_ref(&document) {
                set_payload_value(&mut item, "external_document", external_ref);
            }
            attention_documents.push(item);
        }
    }

    if scanned_document_count == 0
        || (active_parse_count == 0 && failed_document_count == 0 && degraded_parse_count == 0)
    {
        return Ok(Vec::new());
    }

    let status_summary = assistant_scope_count_summary(&status_counts);
    let summary = format!(
        "文档解析状态：已扫描可见文档 {scanned_document_count} 份，状态分布 {status_summary}。未完成/失败/重解析中的文档仅代表资料暂不可完整引用；模型应据此说明解析状态，避免把未解析内容当作事实。"
    );

    Ok(vec![json!({
        "type": "document_parse_status",
        "source": "visible_document_ingest_state",
        "dataset_id": dataset.id,
        "summary": summary,
        "score": 1.0,
        "lexical_score": 1.0,
        "recall_score": 1.0,
        "scanned_document_count": scanned_document_count,
        "status_summary": status_summary,
        "status_counts": status_counts,
        "active_parse_count": active_parse_count,
        "failed_document_count": failed_document_count,
        "reparsing_document_count": reparsing_document_count,
        "degraded_parse_count": degraded_parse_count,
        "not_ready_document_count": active_parse_count + failed_document_count + degraded_parse_count,
        "attention_documents": attention_documents
            .into_iter()
            .take(ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_ATTENTION_LIMIT)
            .collect::<Vec<_>>(),
        "model_guidance": [
            "When a relevant document is parsing, queued, indexing, failed, reparsing, or parse_degraded, say the document content is not fully ready instead of guessing.",
            "Translate internal status codes such as parse_degraded or low_text_coverage into plain Chinese; do not show raw status identifiers to the user.",
            "If reparsing or reparse_queued is present, explain that a retry is already underway or queued.",
            "If parse_quality_summary.vlm_rescue is present, mention whether MiniMax VLM rescue was selected or whether the local parse was kept.",
            "Use ready retrieval evidence and fallback chunks for facts; use this item for document availability/status only."
        ],
        "limits": {
            "maxDocuments": ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_DOCUMENT_LIMIT,
            "maxAttentionDocuments": ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_ATTENTION_LIMIT,
            "limitedByDocumentLimit": limited_by_document_limit,
        },
    })])
}

async fn load_latest_upload_ingest_workflow_snapshots(
    state: &AppState,
    dataset_id: DatasetId,
    document_ids: &[DocumentId],
) -> std::result::Result<HashMap<DocumentId, Value>, ApiError> {
    if document_ids.is_empty() {
        return Ok(HashMap::new());
    }
    let document_id_strings = document_ids
        .iter()
        .map(ToString::to_string)
        .collect::<Vec<_>>();
    let rows = sqlx::query(
        r#"
        select distinct on (e.context ->> 'document_id')
               e.context ->> 'document_id' as document_id,
               e.id as execution_id,
               e.status,
               e.stage,
               e.attempt,
               e.context,
               e.created_at,
               e.updated_at,
               (
                   select jsonb_build_object(
                       'task_id', t.id,
                       'queue', t.queue,
                       'task_key', t.task_key,
                       'status', t.status,
                       'attempt', t.attempt,
                       'max_attempts', t.max_attempts,
                       'available_at', t.available_at,
                       'claimed_at', t.claimed_at,
                       'finished_at', t.finished_at,
                       'error', t.error
                   )
                   from workflow_tasks t
                   where t.execution_id = e.id
                   order by t.updated_at desc, t.created_at desc
                   limit 1
               ) as latest_task
        from workflow_executions e
        where e.tenant_id = $1
          and e.dataset_id = $2
          and e.kind = $3
          and e.context ? 'document_id'
          and e.context ->> 'document_id' = any($4)
        order by e.context ->> 'document_id', e.updated_at desc, e.created_at desc
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(dataset_id.0)
    .bind(WorkflowKind::UploadIngest.as_str())
    .bind(&document_id_strings)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let mut snapshots = HashMap::new();
    for row in rows {
        let Some(document_id) = row
            .get::<Option<String>, _>("document_id")
            .and_then(|raw| Uuid::parse_str(raw.trim()).ok().map(DocumentId))
        else {
            continue;
        };
        let context = row.get::<Value, _>("context");
        let latest_task = row
            .try_get::<Option<Value>, _>("latest_task")
            .ok()
            .flatten();
        snapshots.insert(
            document_id,
            json!({
                "execution_id": WorkflowExecutionId(row.get("execution_id")),
                "status": row.get::<String, _>("status"),
                "stage": row.get::<String, _>("stage"),
                "attempt": row.get::<i32, _>("attempt"),
                "retries_remaining": context.get("retries_remaining").cloned().unwrap_or(Value::Null),
                "retry_reason": context.get("retry_reason").cloned().unwrap_or(Value::Null),
                "last_error": context.get("last_error").cloned().unwrap_or(Value::Null),
                "latest_task": latest_task,
                "created_at": row.get::<DateTime<Utc>, _>("created_at"),
                "updated_at": row.get::<DateTime<Utc>, _>("updated_at"),
            }),
        );
    }
    Ok(snapshots)
}

fn assistant_run_document_parse_model_status(
    document: &Document,
    parse_status: &str,
    chunk_count: usize,
    parse_quality_status: Option<&str>,
    workflow: Option<&Value>,
) -> String {
    let workflow_status = workflow
        .and_then(|value| value.get("status"))
        .and_then(Value::as_str)
        .unwrap_or("");
    let workflow_stage = workflow
        .and_then(|value| value.get("stage"))
        .and_then(Value::as_str)
        .unwrap_or("");
    let workflow_active = matches!(workflow_status, "pending" | "running");

    if workflow_active && document.lifecycle == DocumentLifecycle::Failed {
        return if workflow_status == "pending" {
            "reparse_queued".to_string()
        } else {
            "reparsing".to_string()
        };
    }
    if workflow_active && workflow_stage == "index_retrieval_artifacts" {
        return "indexing".to_string();
    }
    if workflow_active {
        return if workflow_status == "pending" {
            "queued".to_string()
        } else {
            "parsing".to_string()
        };
    }
    if document.lifecycle == DocumentLifecycle::Failed || parse_status == "failed" {
        return "failed".to_string();
    }
    if matches!(parse_status, "parse_degraded" | "placeholder")
        || parse_quality_status
            .map(|status| status.contains("low_text_coverage"))
            .unwrap_or(false)
    {
        return "parse_degraded".to_string();
    }
    if document.lifecycle == DocumentLifecycle::Received {
        return "received".to_string();
    }
    if document.lifecycle == DocumentLifecycle::Indexed {
        return "ready".to_string();
    }
    if document.lifecycle == DocumentLifecycle::Extracted && chunk_count > 0 {
        return "extracted_pending_index".to_string();
    }
    document.lifecycle.as_str().to_string()
}

fn assistant_run_document_parse_status_is_active(status: &str) -> bool {
    matches!(
        status,
        "queued" | "parsing" | "indexing" | "reparsing" | "reparse_queued"
    )
}

fn assistant_run_document_parse_status_needs_attention(status: &str) -> bool {
    !matches!(status, "ready" | "extracted_pending_index" | "archived")
}

fn assistant_run_document_parse_quality_status(document: &Document) -> Option<String> {
    assistant_run_document_parse_quality_metadata(document)
        .and_then(|parse_quality| value_at_any_key(parse_quality, &["status"]))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn assistant_run_document_parse_quality_metadata(document: &Document) -> Option<&Value> {
    let ingest = document
        .metadata
        .get("ingest")
        .filter(|value| value.is_object())?;
    value_at_any_key(ingest, &["parse_metadata", "parseMetadata"])
        .and_then(|parse_metadata| {
            value_at_any_key(parse_metadata, &["parse_quality", "parseQuality"])
        })
        .filter(|value| value.is_object())
}

fn assistant_run_document_parse_quality_summary(document: &Document) -> Option<Value> {
    let ingest = document
        .metadata
        .get("ingest")
        .filter(|value| value.is_object())?;
    let parse_quality = assistant_run_document_parse_quality_metadata(document)?;
    let mut summary = Map::new();

    copy_json_fields(
        ingest,
        &mut summary,
        &[
            "parse_method",
            "parse_status",
            "parse_quality_status",
            "cloud_structured_provider",
        ],
    );
    copy_json_fields(
        parse_quality,
        &mut summary,
        &[
            "kind",
            "status",
            "text_chars",
            "min_usable_text_chars",
            "fallback_status",
            "recommended_fallback",
        ],
    );
    if let Some(fallback_from) = value_at_any_key(parse_quality, &["fallback_from", "fallbackFrom"])
        .and_then(compact_parse_quality_candidate_report)
    {
        summary.insert("fallback_from".to_string(), fallback_from);
    }
    if let Some(candidate_selection) =
        assistant_run_parse_quality_candidate_selection_summary(parse_quality)
    {
        summary.insert("candidate_selection".to_string(), candidate_selection);
    }
    if let Some(vlm_rescue) = assistant_run_parse_quality_vlm_rescue_summary(parse_quality) {
        summary.insert("vlm_rescue".to_string(), vlm_rescue);
    }
    if let Some(auto_reparse) = value_at_any_key(ingest, &["auto_reparse", "autoReparse"])
        .and_then(assistant_run_auto_reparse_summary)
    {
        summary.insert("auto_reparse".to_string(), auto_reparse);
    }

    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn assistant_run_inferred_low_text_parse_quality_summary(
    document: &Document,
    chunks: &[DocumentChunk],
) -> Option<Value> {
    if !assistant_run_document_is_pdf_like(document) || chunks.is_empty() {
        return None;
    }
    let text_chars = chunks
        .iter()
        .map(|chunk| assistant_run_low_text_parse_signal_chars(&chunk.content))
        .sum::<usize>();
    if text_chars >= ASSISTANT_RUN_INFERRED_LOW_TEXT_PARSE_MIN_CHARS {
        return None;
    }
    Some(json!({
        "kind": "pdf_text_extraction",
        "status": "low_text_coverage",
        "text_chars": text_chars,
        "min_usable_text_chars": ASSISTANT_RUN_INFERRED_LOW_TEXT_PARSE_MIN_CHARS,
        "inferred_from": "stored_document_chunks",
        "fallback_status": "recommended",
        "recommended_fallback": "ocr_reparse"
    }))
}

fn assistant_run_document_is_pdf_like(document: &Document) -> bool {
    document
        .content_type
        .eq_ignore_ascii_case("application/pdf")
        || document.title.to_ascii_lowercase().ends_with(".pdf")
        || document.object_key.to_ascii_lowercase().ends_with(".pdf")
}

fn assistant_run_low_text_parse_signal_chars(text: &str) -> usize {
    text.chars()
        .filter(|ch| {
            !ch.is_whitespace()
                && !ch.is_ascii_punctuation()
                && !matches!(
                    *ch,
                    '。' | '，'
                        | '、'
                        | '；'
                        | '：'
                        | '！'
                        | '？'
                        | '（'
                        | '）'
                        | '【'
                        | '】'
                        | '《'
                        | '》'
                        | '“'
                        | '”'
                        | '‘'
                        | '’'
                        | '-'
                        | '—'
                        | '_'
                        | '|'
                )
        })
        .count()
}

fn assistant_run_parse_quality_candidate_selection_summary(parse_quality: &Value) -> Option<Value> {
    let candidate_selection = value_at_any_key(
        parse_quality,
        &["candidate_selection", "candidateSelection"],
    )?;
    let mut summary = Map::new();
    copy_json_fields(
        candidate_selection,
        &mut summary,
        &["policy", "selected_method"],
    );
    if let Some(selected) = value_at_any_key(candidate_selection, &["selected"])
        .and_then(compact_parse_quality_candidate_report)
    {
        summary.insert("selected".to_string(), selected);
    }
    if let Some(candidate_count) = value_at_any_key(candidate_selection, &["candidates"])
        .and_then(Value::as_array)
        .map(Vec::len)
    {
        summary.insert("candidate_count".to_string(), json!(candidate_count));
    }
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn assistant_run_parse_quality_vlm_rescue_summary(parse_quality: &Value) -> Option<Value> {
    let vlm_rescue = value_at_any_key(parse_quality, &["vlm_rescue", "vlmRescue"])?;
    let mut summary = Map::new();
    copy_json_fields(vlm_rescue, &mut summary, &["policy", "selected"]);
    for key in ["existing", "vlm"] {
        if let Some(report) =
            value_at_any_key(vlm_rescue, &[key]).and_then(compact_parse_quality_candidate_report)
        {
            summary.insert(key.to_string(), report);
        }
    }
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn assistant_run_auto_reparse_summary(auto_reparse: &Value) -> Option<Value> {
    let mut summary = Map::new();
    copy_json_fields(
        auto_reparse,
        &mut summary,
        &[
            "status",
            "reason",
            "attempt_count",
            "max_attempts",
            "updated_at",
        ],
    );
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn compact_parse_quality_candidate_report(value: &Value) -> Option<Value> {
    let mut summary = Map::new();
    copy_json_fields(
        value,
        &mut summary,
        &[
            "method",
            "text_chars",
            "structure_block_count",
            "heading_count",
            "table_signal_count",
            "quality_score",
        ],
    );
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn value_at_any_key<'a>(value: &'a Value, keys: &[&str]) -> Option<&'a Value> {
    keys.iter().find_map(|key| value.get(*key))
}

fn copy_json_fields(source: &Value, target: &mut Map<String, Value>, keys: &[&str]) {
    for key in keys {
        if let Some(value) = value_at_any_key(source, &[*key])
            .filter(|value| !value.is_null())
            .cloned()
        {
            target.insert((*key).to_string(), value);
        }
    }
}

fn assistant_run_document_ingest_summary(document: &Document) -> Value {
    let Some(ingest) = document
        .metadata
        .get("ingest")
        .filter(|value| value.is_object())
    else {
        return Value::Null;
    };
    let mut summary = Map::new();
    for key in [
        "processor",
        "parse_method",
        "cloud_structured_provider",
        "chunk_count",
        "extracted_chars",
        "failed_at",
        "last_error",
    ] {
        if let Some(value) = ingest.get(key).cloned() {
            summary.insert(key.to_string(), value);
        }
    }
    if let Some(parse_quality_status) = assistant_run_document_parse_quality_status(document) {
        summary.insert(
            "parse_quality_status".to_string(),
            json!(parse_quality_status),
        );
    }
    if let Some(parse_quality_summary) = assistant_run_document_parse_quality_summary(document) {
        summary.insert("parse_quality_summary".to_string(), parse_quality_summary);
    }
    Value::Object(summary)
}

fn assistant_run_document_external_ref(document: &Document) -> Option<Value> {
    let external_source = document
        .metadata
        .get("external_source")
        .or_else(|| document.metadata.get("externalSource"))?
        .as_object()?;
    let source_id = external_source
        .get("source_id")
        .or_else(|| external_source.get("sourceId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let document_external_id = external_source
        .get("document_external_id")
        .or_else(|| external_source.get("documentExternalId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    Some(json!({
        "source_id": source_id,
        "document_external_id": document_external_id,
        "revision_external_id": external_source
            .get("revision_external_id")
            .or_else(|| external_source.get("revisionExternalId"))
            .and_then(Value::as_str),
    }))
}

async fn build_assistant_run_dataset_entity_scan_supply(
    state: &AppState,
    dataset: &Dataset,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<Vec<Value>, ApiError> {
    let documents = list_documents_for_dataset_scope(state, dataset.id)
        .await?
        .into_iter()
        .filter(|document| {
            document_is_visible_for_assistant_evidence_owner_scope(
                document,
                current_user_id,
                selected_document_ids,
                allow_selected_documents_without_acl_snapshot,
            )
        })
        .filter(|document| {
            selected_document_ids.is_empty() || selected_document_ids.contains(&document.id)
        })
        .collect::<Vec<_>>();

    let mut scanned_document_count = 0usize;
    let mut limited_by_document_limit = false;
    let mut entities_by_key: BTreeMap<(String, String), BTreeSet<String>> = BTreeMap::new();
    let mut candidate_terms_by_name: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut years_by_year: BTreeMap<i32, BTreeSet<String>> = BTreeMap::new();
    let mut sections_by_title: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut paragraphs_by_excerpt: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut tables_by_signal: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut document_hits = Vec::new();
    let mut resume_profile_rows = Vec::new();
    let mut resume_project_delivery_rows = Vec::new();

    for document in documents {
        if scanned_document_count >= ASSISTANT_RUN_DATASET_ENTITY_SCAN_DOCUMENT_LIMIT {
            limited_by_document_limit = true;
            break;
        }
        if !document_is_visible_for_external_acl(
            state,
            external_acl_filter,
            &document,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?
        {
            continue;
        }
        scanned_document_count += 1;

        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        let scan_text = dataset_entity_scan_text(&document, &chunks);
        let structured_entity_candidates =
            extract_document_entity_candidates_from_chunk_metadata(&chunks, 64);
        let has_structured_organizations = structured_entity_candidates
            .iter()
            .any(|candidate| candidate.entity_type == "organization");
        let text_scan = if has_structured_organizations {
            dataset_entity_scan_structured_text(&document, &chunks)
                .unwrap_or_else(|| scan_text.clone())
        } else {
            scan_text.clone()
        };
        let entity_candidates = merge_document_entity_candidates(
            structured_entity_candidates,
            extract_document_entity_candidates_from_text(&text_scan, 64),
            64,
        );
        let company_names = entity_candidates
            .iter()
            .filter(|candidate| candidate.entity_type == "organization")
            .map(|candidate| candidate.name.clone())
            .collect::<Vec<_>>();
        let candidate_terms = extract_document_candidate_terms_for_scan(&chunks, &scan_text, 32);
        let document_years = extract_resume_years(&scan_text, 32);
        let section_titles = extract_document_section_titles_for_scan(&chunks, &scan_text, 32);
        let paragraph_samples = extract_document_paragraphs_for_scan(&chunks, 16);
        let table_signals = extract_document_table_signals_for_scan(&chunks, &scan_text, 16);
        let resume_profile =
            extract_resume_document_profile(&document, &text_scan, &entity_candidates);
        let document_project_delivery_rows = extract_resume_project_delivery_rows(
            &document,
            &chunks,
            &resume_profile,
            &entity_candidates,
            ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_ROW_LIMIT
                .saturating_sub(resume_project_delivery_rows.len()),
        );
        if entity_candidates.is_empty()
            && candidate_terms.is_empty()
            && document_years.is_empty()
            && section_titles.is_empty()
            && paragraph_samples.is_empty()
            && table_signals.is_empty()
            && document_project_delivery_rows.is_empty()
            && resume_profile.is_empty()
        {
            continue;
        }

        for candidate in &entity_candidates {
            entities_by_key
                .entry((candidate.entity_type.to_string(), candidate.name.clone()))
                .or_default()
                .insert(document.id.to_string());
        }
        for term in &candidate_terms {
            candidate_terms_by_name
                .entry(term.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for year in &document_years {
            years_by_year
                .entry(*year)
                .or_default()
                .insert(document.id.to_string());
        }
        for title in &section_titles {
            sections_by_title
                .entry(title.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for paragraph in &paragraph_samples {
            paragraphs_by_excerpt
                .entry(paragraph.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for table_signal in &table_signals {
            tables_by_signal
                .entry(table_signal.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for delivery_row in &document_project_delivery_rows {
            if !delivery_row.project_name_is_placeholder() {
                entities_by_key
                    .entry(("project".to_string(), delivery_row.project_name.clone()))
                    .or_default()
                    .insert(document.id.to_string());
            }
        }
        if !resume_profile.is_empty()
            && resume_profile_rows.len() < ASSISTANT_RUN_RESUME_PROFILE_ROW_LIMIT
        {
            resume_profile_rows.push(resume_profile.to_value());
        }
        if !document_project_delivery_rows.is_empty()
            && resume_project_delivery_rows.len() < ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_ROW_LIMIT
        {
            resume_project_delivery_rows.extend(
                document_project_delivery_rows
                    .into_iter()
                    .take(
                        ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_ROW_LIMIT
                            .saturating_sub(resume_project_delivery_rows.len()),
                    )
                    .map(|row| row.to_value()),
            );
        }
        document_hits.push(json!({
            "document_id": document.id,
            "company_names": company_names,
            "entities": entity_candidates
                .iter()
                .take(24)
                .map(|candidate| json!({
                    "type": candidate.entity_type,
                    "name": candidate.name.clone(),
                }))
                .collect::<Vec<_>>(),
            "candidate_terms": candidate_terms,
            "years": document_years,
            "section_titles": section_titles,
            "paragraph_samples": paragraph_samples,
            "table_signals": table_signals,
        }));
    }

    if scanned_document_count == 0 {
        return Ok(Vec::new());
    }

    let entity_count = entities_by_key.len();
    let organization_count = entities_by_key
        .keys()
        .filter(|(entity_type, _)| entity_type == "organization")
        .count();
    let candidate_term_count = candidate_terms_by_name.len();
    let year_count = years_by_year.len();
    let section_count = sections_by_title.len();
    let paragraph_count = paragraphs_by_excerpt.len();
    let table_signal_count = tables_by_signal.len();
    let mut organization_rows = entities_by_key
        .iter()
        .filter(|((entity_type, _), _)| entity_type == "organization")
        .map(|((_, name), document_ids)| (name.clone(), document_ids.clone()))
        .collect::<Vec<_>>();
    organization_rows.sort_by(
        |(left_name, left_documents), (right_name, right_documents)| {
            right_documents
                .len()
                .cmp(&left_documents.len())
                .then_with(|| left_name.cmp(right_name))
        },
    );
    let company_rows = organization_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(name, document_ids)| {
            json!({
                "name": name,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect::<Vec<_>>();
    let company_names = organization_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(name, _)| name.clone())
        .collect::<Vec<_>>();
    let skill_rows = entity_rows_for_type(&entities_by_key, "skill");
    let project_rows = entity_rows_for_type(&entities_by_key, "project");
    let position_rows = entity_rows_for_type(&entities_by_key, "position");
    let location_rows = entity_rows_for_type(&entities_by_key, "location");
    let person_rows = entity_rows_for_type(&entities_by_key, "person");
    let school_rows = entity_rows_for_type(&entities_by_key, "school");
    let degree_rows = entity_rows_for_type(&entities_by_key, "degree");
    let certificate_rows = entity_rows_for_type(&entities_by_key, "certificate");
    let keyword_rows = candidate_term_rows_for_scan(&candidate_terms_by_name);
    let year_rows = year_rows_for_scan(&years_by_year);
    let section_rows = structure_rows_for_scan(&sections_by_title);
    let paragraph_rows = structure_rows_for_scan(&paragraphs_by_excerpt);
    let table_rows = structure_rows_for_scan(&tables_by_signal);
    let entity_rows_by_type = json!({
        "organization": company_rows.clone(),
        "skill": skill_rows.clone(),
        "project": project_rows.clone(),
        "position": position_rows.clone(),
        "location": location_rows.clone(),
        "person": person_rows.clone(),
        "school": school_rows.clone(),
        "degree": degree_rows.clone(),
        "certificate": certificate_rows.clone(),
        "keyword": keyword_rows.clone(),
        "year": year_rows.clone(),
        "section": section_rows.clone(),
        "paragraph": paragraph_rows.clone(),
        "table": table_rows.clone(),
    });
    let company_summary = organization_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .map(|(name, document_ids)| {
            if document_ids.len() > 1 {
                format!("{name}({}份)", document_ids.len())
            } else {
                name.clone()
            }
        })
        .collect::<Vec<_>>()
        .join("、");
    let entity_views = entities_by_key
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .map(|((entity_type, name), document_ids)| {
            json!({
                "type": entity_type,
                "name": name,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect::<Vec<_>>();
    let candidate_term_views = keyword_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .cloned()
        .collect::<Vec<_>>();
    let entity_summary = entities_by_key
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .map(|((entity_type, name), document_ids)| {
            let label = document_entity_type_label(entity_type);
            if document_ids.len() > 1 {
                format!("{label}:{name}({}份)", document_ids.len())
            } else {
                format!("{label}:{name}")
            }
        })
        .collect::<Vec<_>>()
        .join("、");
    let summary = if entity_summary.is_empty() {
        format!(
            "资料库实体扫描：已扫描可见文档 {scanned_document_count} 份，未识别到明确实体，候选名词 {candidate_term_count} 个。"
        )
    } else {
        let company_part = if company_summary.is_empty() {
            entity_summary
        } else {
            company_summary
        };
        format!(
            "资料库实体扫描：已扫描可见文档 {scanned_document_count} 份，识别实体 {entity_count} 个，其中公司/组织 {organization_count} 个，候选名词 {candidate_term_count} 个。公司/组织统计以 company_rows 和 company_count 为准：{company_part}。"
        )
    };

    let mut item = Map::new();
    item.insert("type".to_string(), json!("dataset_entity_scan"));
    item.insert("source".to_string(), json!("visible_document_scan"));
    item.insert("dataset_id".to_string(), json!(dataset.id));
    item.insert("entity_type".to_string(), json!("document_entity_scan"));
    item.insert(
        "legacy_entity_type".to_string(),
        json!("company_or_organization"),
    );
    item.insert(
        "entity_types".to_string(),
        json!([
            "organization",
            "person",
            "position",
            "skill",
            "location",
            "project",
            "school",
            "degree",
            "certificate",
            "keyword",
            "year",
            "section",
            "paragraph",
            "table"
        ]),
    );
    item.insert("summary".to_string(), json!(summary));
    item.insert("score".to_string(), json!(1.0));
    item.insert("lexical_score".to_string(), json!(1.0));
    item.insert("recall_score".to_string(), json!(1.0));
    item.insert(
        "scanned_document_count".to_string(),
        json!(scanned_document_count),
    );
    item.insert("entity_count".to_string(), json!(entity_count));
    item.insert("organization_count".to_string(), json!(organization_count));
    item.insert("company_count".to_string(), json!(organization_count));
    item.insert("company_rows".to_string(), Value::Array(company_rows));
    item.insert("skill_rows".to_string(), Value::Array(skill_rows));
    item.insert("project_rows".to_string(), Value::Array(project_rows));
    item.insert("position_rows".to_string(), Value::Array(position_rows));
    item.insert("location_rows".to_string(), Value::Array(location_rows));
    item.insert("person_rows".to_string(), Value::Array(person_rows));
    item.insert("school_rows".to_string(), Value::Array(school_rows));
    item.insert("degree_rows".to_string(), Value::Array(degree_rows));
    item.insert(
        "certificate_rows".to_string(),
        Value::Array(certificate_rows),
    );
    item.insert("entity_rows_by_type".to_string(), entity_rows_by_type);
    item.insert(
        "resume_profile_rows".to_string(),
        Value::Array(resume_profile_rows),
    );
    item.insert(
        "resume_project_delivery_rows".to_string(),
        Value::Array(resume_project_delivery_rows),
    );
    item.insert(
        "candidate_term_count".to_string(),
        json!(candidate_term_count),
    );
    item.insert("year_count".to_string(), json!(year_count));
    item.insert("section_count".to_string(), json!(section_count));
    item.insert("paragraph_count".to_string(), json!(paragraph_count));
    item.insert("table_signal_count".to_string(), json!(table_signal_count));
    item.insert("keyword_rows".to_string(), Value::Array(keyword_rows));
    item.insert("year_rows".to_string(), Value::Array(year_rows));
    item.insert("section_rows".to_string(), Value::Array(section_rows));
    item.insert("paragraph_rows".to_string(), Value::Array(paragraph_rows));
    item.insert("table_rows".to_string(), Value::Array(table_rows));
    item.insert("company_names".to_string(), json!(company_names));
    item.insert("entities".to_string(), Value::Array(entity_views));
    item.insert(
        "candidate_terms".to_string(),
        Value::Array(candidate_term_views),
    );
    item.insert(
        "document_hits".to_string(),
        Value::Array(document_hits.into_iter().take(24).collect::<Vec<_>>()),
    );
    item.insert(
        "answer_guidance".to_string(),
        json!({
            "company_count_authoritative": organization_count,
            "scanned_document_count_authoritative": scanned_document_count,
            "company_rows_authoritative": true,
            "entity_rows_by_type_authoritative": true,
            "keyword_rows_authoritative": true,
            "year_rows_authoritative": true,
            "section_rows_authoritative": true,
            "paragraph_rows_authoritative": true,
            "table_rows_authoritative": true,
            "resume_profile_rows_authoritative": true,
            "resume_project_delivery_rows_authoritative": true,
            "ignore_candidate_terms_for_company_count": true,
            "do_not_sum_company_row_document_counts_as_total_documents": true,
            "candidate_terms_are_only_noun_hints": true,
        }),
    );
    item.insert(
        "limits".to_string(),
        json!({
            "maxDocuments": ASSISTANT_RUN_DATASET_ENTITY_SCAN_DOCUMENT_LIMIT,
            "maxChunksPerDocument": ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT,
            "maxEntities": ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT,
            "maxCompanyRows": ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT,
            "limitedByDocumentLimit": limited_by_document_limit,
        }),
    );

    Ok(vec![Value::Object(item)])
}

