#[derive(Clone, Debug, Default, Eq, PartialEq)]
struct ResumeDocumentProfile {
    document_id: String,
    document_title: String,
    candidate_name: Option<String>,
    gender: Option<String>,
    age: Option<u64>,
    birth_year: Option<i32>,
    earliest_year: Option<i32>,
    latest_year: Option<i32>,
    year_count: usize,
    company_count: usize,
    skill_count: usize,
    project_count: usize,
    position_count: usize,
    location_count: usize,
    certificate_count: usize,
    company_names: Vec<String>,
    skill_names: Vec<String>,
    project_names: Vec<String>,
    position_names: Vec<String>,
    location_names: Vec<String>,
    school_names: Vec<String>,
    degree_names: Vec<String>,
    certificate_names: Vec<String>,
}

impl ResumeDocumentProfile {
    fn is_empty(&self) -> bool {
        self.candidate_name.is_none()
            && self.gender.is_none()
            && self.age.is_none()
            && self.birth_year.is_none()
            && self.earliest_year.is_none()
            && self.latest_year.is_none()
            && self.company_count == 0
            && self.skill_count == 0
            && self.project_count == 0
            && self.position_count == 0
            && self.location_count == 0
            && self.certificate_count == 0
            && self.school_names.is_empty()
            && self.degree_names.is_empty()
    }

    fn to_value(&self) -> Value {
        json!({
            "document_id": self.document_id,
            "document_title": self.document_title,
            "candidate_name": self.candidate_name,
            "gender": self.gender,
            "age": self.age,
            "birth_year": self.birth_year,
            "earliest_year": self.earliest_year,
            "latest_year": self.latest_year,
            "year_count": self.year_count,
            "company_count": self.company_count,
            "skill_count": self.skill_count,
            "project_count": self.project_count,
            "position_count": self.position_count,
            "location_count": self.location_count,
            "certificate_count": self.certificate_count,
            "company_names": &self.company_names,
            "skill_names": &self.skill_names,
            "project_names": &self.project_names,
            "position_names": &self.position_names,
            "location_names": &self.location_names,
            "school_names": &self.school_names,
            "degree_names": &self.degree_names,
            "certificate_names": &self.certificate_names,
        })
    }
}

