fn extract_document_section_titles_for_scan(
    chunks: &[DocumentChunk],
    scan_text: &str,
    limit: usize,
) -> Vec<String> {
    let mut titles = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        for title in document_chunk_section_title_hints(chunk) {
            push_document_structure_signal(&mut titles, title, limit);
        }
    }
    for title in infer_section_title_hints_from_text(scan_text, limit) {
        push_document_structure_signal(&mut titles, title, limit);
    }
    titles
}

fn extract_document_paragraphs_for_scan(chunks: &[DocumentChunk], limit: usize) -> Vec<String> {
    let mut paragraphs = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        if let Some(value) = chunk
            .metadata
            .get("parse_metadata")
            .and_then(|value| value.get("document_structure"))
        {
            for paragraph in document_structure_paragraph_samples(value, limit) {
                push_document_paragraph_sample(&mut paragraphs, paragraph, limit);
            }
        }
        for paragraph in infer_paragraph_samples_from_text(&chunk.content, limit) {
            push_document_paragraph_sample(&mut paragraphs, paragraph, limit);
        }
        if paragraphs.len() >= limit {
            break;
        }
    }
    paragraphs
}

fn extract_document_table_signals_for_scan(
    chunks: &[DocumentChunk],
    scan_text: &str,
    limit: usize,
) -> Vec<String> {
    let mut signals = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        for signal in document_chunk_table_signals(chunk, limit) {
            push_document_structure_signal(&mut signals, signal, limit);
        }
        if signals.len() >= limit {
            return signals;
        }
    }
    for signal in infer_table_signals_from_text(scan_text, limit) {
        push_document_structure_signal(&mut signals, signal, limit);
    }
    signals
}

fn document_chunk_table_signals(chunk: &DocumentChunk, limit: usize) -> Vec<String> {
    let mut signals = Vec::new();
    for key in [
        "table_signals",
        "tableSignals",
        "table_like_signals",
        "tableLikeSignals",
    ] {
        if let Some(value) = chunk.metadata.get(key) {
            collect_string_list(value, &mut signals);
        }
    }
    if let Some(value) = chunk
        .metadata
        .get("parse_metadata")
        .and_then(|value| value.get("table_like_signals"))
    {
        collect_string_list(value, &mut signals);
    }
    if let Some(value) = chunk
        .metadata
        .get("parse_metadata")
        .and_then(|value| value.get("document_structure"))
    {
        for signal in document_structure_table_signals(value, limit) {
            push_document_structure_signal(&mut signals, signal, limit);
        }
    }
    visit_document_vlm_payloads(&chunk.metadata, |payload| {
        if let Some(value) = payload
            .get("tableLikeSignals")
            .or_else(|| payload.get("table_like_signals"))
        {
            collect_string_list(value, &mut signals);
        }
        if payload
            .get("chartOrTableDetected")
            .or_else(|| payload.get("chart_or_table_detected"))
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            if let Some(summary) = payload
                .get("visualSummary")
                .or_else(|| payload.get("summary"))
                .and_then(Value::as_str)
            {
                push_document_structure_signal(&mut signals, summary, limit);
            }
        }
    });
    signals.truncate(limit);
    signals
}

fn document_structure_paragraph_samples(structure: &Value, limit: usize) -> Vec<String> {
    let mut paragraphs = Vec::new();
    let Some(blocks) = structure.get("blocks").and_then(Value::as_array) else {
        return paragraphs;
    };
    for block in blocks {
        if document_structure_block_is_title(block)
            || document_structure_block_is_term_source(block)
        {
            continue;
        }
        let block_type = document_structure_block_type(block);
        if !block_type.is_empty()
            && ![
                "text",
                "paragraph",
                "plain_text",
                "body",
                "content",
                "list",
                "list_item",
            ]
            .iter()
            .any(|value| block_type.contains(value))
        {
            continue;
        }
        let Some(text) = document_structure_block_text(block) else {
            continue;
        };
        push_document_paragraph_sample(&mut paragraphs, text, limit);
        if paragraphs.len() >= limit {
            break;
        }
    }
    paragraphs
}

fn document_structure_table_signals(structure: &Value, limit: usize) -> Vec<String> {
    let mut signals = Vec::new();
    let Some(blocks) = structure.get("blocks").and_then(Value::as_array) else {
        return signals;
    };
    for block in blocks {
        let block_type = document_structure_block_type(block);
        if !["table", "cell", "table_title"]
            .iter()
            .any(|value| block_type.contains(value))
        {
            continue;
        }
        let Some(text) = document_structure_block_text(block) else {
            continue;
        };
        push_document_structure_signal(&mut signals, text, limit);
        if signals.len() >= limit {
            break;
        }
    }
    signals
}

fn infer_paragraph_samples_from_text(text: &str, limit: usize) -> Vec<String> {
    let mut paragraphs = Vec::new();
    for raw in text.split("\n\n") {
        let normalized = raw
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>()
            .join(" ");
        if normalized.is_empty() {
            continue;
        }
        if normalize_section_title_hint(&normalized).is_some()
            || looks_like_table_signal_line(&normalized)
        {
            continue;
        }
        push_document_paragraph_sample(&mut paragraphs, normalized, limit);
        if paragraphs.len() >= limit {
            break;
        }
    }
    paragraphs
}

fn infer_table_signals_from_text(text: &str, limit: usize) -> Vec<String> {
    let mut signals = Vec::new();
    for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
        if !looks_like_table_signal_line(line) {
            continue;
        }
        push_document_structure_signal(&mut signals, line, limit);
        if signals.len() >= limit {
            break;
        }
    }
    signals
}

fn looks_like_table_signal_line(line: &str) -> bool {
    let pipe_count = line.matches('|').count();
    pipe_count >= 2
        || line.matches('\t').count() >= 2
        || (line.contains("｜") && line.matches('｜').count() >= 2)
}

fn push_document_structure_signal(output: &mut Vec<String>, value: impl AsRef<str>, limit: usize) {
    if output.len() >= limit {
        return;
    }
    let normalized_value = normalize_document_entity_value(value.as_ref());
    let normalized = normalized_value
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    let char_count = normalized.chars().count();
    if !(2..=120).contains(&char_count)
        || is_document_entity_noise(&normalized)
        || output.iter().any(|existing| existing == &normalized)
    {
        return;
    }
    output.push(normalized);
}

fn push_document_paragraph_sample(output: &mut Vec<String>, value: impl AsRef<str>, limit: usize) {
    if output.len() >= limit {
        return;
    }
    let normalized = value
        .as_ref()
        .trim()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .take(180)
        .collect::<String>();
    let char_count = normalized.chars().count();
    if !(12..=180).contains(&char_count)
        || is_document_entity_noise(&normalized)
        || output.iter().any(|existing| existing == &normalized)
    {
        return;
    }
    output.push(normalized);
}

fn extract_resume_document_profile(
    document: &Document,
    scan_text: &str,
    entity_candidates: &[DocumentEntityCandidate],
) -> ResumeDocumentProfile {
    let years = extract_resume_timeline_years(scan_text, 32);
    let company_names = resume_profile_entity_names(entity_candidates, "organization", 16);
    let skill_names = resume_profile_entity_names(entity_candidates, "skill", 24);
    let mut project_names = resume_profile_entity_names(entity_candidates, "project", 16);
    for name in extract_project_like_terms(scan_text, 16) {
        push_document_candidate_term(&mut project_names, name, 16);
    }
    let position_names = resume_profile_entity_names(entity_candidates, "position", 12);
    let location_names = resume_profile_entity_names(entity_candidates, "location", 12);
    let school_names = resume_profile_entity_names(entity_candidates, "school", 12);
    let degree_names = resume_profile_entity_names(entity_candidates, "degree", 8);
    let certificate_names = resume_profile_entity_names(entity_candidates, "certificate", 12);
    let mut profile = ResumeDocumentProfile {
        document_id: document.id.to_string(),
        document_title: resume_profile_display_title(document),
        candidate_name: extract_resume_candidate_name(scan_text)
            .or_else(|| extract_resume_candidate_name_from_title(&document.title))
            .or_else(|| extract_resume_candidate_name_from_marked_text(scan_text))
            .or_else(|| extract_resume_candidate_name_from_object_key(&document.object_key))
            .or_else(|| {
                entity_candidates
                    .iter()
                    .find(|candidate| candidate.entity_type == "person")
                    .map(|candidate| candidate.name.clone())
            }),
        gender: extract_resume_gender(scan_text),
        age: extract_resume_age(scan_text),
        birth_year: extract_resume_birth_year(scan_text),
        earliest_year: years.iter().min().copied(),
        latest_year: years.iter().max().copied(),
        year_count: years.len(),
        company_count: company_names.len(),
        skill_count: skill_names.len(),
        project_count: project_names.len(),
        position_count: position_names.len(),
        location_count: location_names.len(),
        certificate_count: certificate_names.len(),
        company_names,
        skill_names,
        project_names,
        position_names,
        location_names,
        school_names,
        degree_names,
        certificate_names,
    };
    if profile.age.is_none() {
        if let Some(birth_year) = profile.birth_year {
            let current_year = Utc::now().year();
            if (1950..=current_year).contains(&birth_year) {
                let age = current_year - birth_year;
                if (16..=80).contains(&age) {
                    profile.age = Some(age as u64);
                }
            }
        }
    }
    if !resume_profile_has_document_signal(document, scan_text, &profile) {
        return ResumeDocumentProfile::default();
    }
    profile
}

fn extract_resume_project_delivery_rows(
    document: &Document,
    chunks: &[DocumentChunk],
    profile: &ResumeDocumentProfile,
    entity_candidates: &[DocumentEntityCandidate],
    limit: usize,
) -> Vec<ResumeProjectDeliveryRow> {
    if limit == 0 {
        return Vec::new();
    }
    let candidate_name = profile
        .candidate_name
        .clone()
        .or_else(|| extract_resume_candidate_name_from_title(&document.title))
        .or_else(|| extract_resume_candidate_name_from_object_key(&document.object_key))
        .or_else(|| {
            entity_candidates
                .iter()
                .find(|candidate| candidate.entity_type == "person")
                .map(|candidate| candidate.name.clone())
        })
        .unwrap_or_else(|| "未知候选人".to_string());
    let document_title = resume_profile_display_title(document);
    let mut rows = Vec::new();
    let mut seen = BTreeSet::new();

    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_CHUNK_LIMIT)
    {
        let lines = resume_project_delivery_lines(&chunk.content);
        if lines.is_empty() || !resume_project_delivery_chunk_has_signal(&lines) {
            continue;
        }
        for (line_index, line) in lines.iter().enumerate() {
            let Some(project_name) = resume_project_delivery_project_name_from_line(line) else {
                continue;
            };
            if project_heading_is_noise(&project_name) {
                continue;
            }
            let block_lines = resume_project_delivery_block_lines(&lines, line_index);
            let delivery_summary =
                resume_project_delivery_summary_from_block(&block_lines, &project_name);
            if delivery_summary.is_empty() {
                continue;
            }
            let key = format!(
                "{}:{}:{}",
                document.id,
                normalize_document_entity_value(&candidate_name),
                normalize_document_entity_value(&project_name)
            );
            if !seen.insert(key) {
                continue;
            }
            let block_text = block_lines.join("\n");
            rows.push(ResumeProjectDeliveryRow {
                document_id: document.id.to_string(),
                document_title: document_title.clone(),
                candidate_name: candidate_name.clone(),
                project_name,
                delivery_summary,
                tech_stack: resume_project_delivery_tech_stack(&block_text, 8),
                source_locator: format!("document://{}/chunks/{}", document.id, chunk.chunk_index),
                chunk_index: chunk.chunk_index,
                confidence: "medium".to_string(),
            });
            if rows.len() >= limit {
                return rows;
            }
        }
    }

    if rows.is_empty() && resume_project_delivery_profile_has_project_names(profile) {
        for project_name in profile.project_names.iter().take(limit) {
            rows.push(ResumeProjectDeliveryRow {
                document_id: document.id.to_string(),
                document_title: document_title.clone(),
                candidate_name: candidate_name.clone(),
                project_name: project_name.clone(),
                delivery_summary: "识别到项目名称，但当前轻量扫描未抽到明确交付职责句。"
                    .to_string(),
                tech_stack: profile.skill_names.iter().take(8).cloned().collect(),
                source_locator: format!("document://{}/profile", document.id),
                chunk_index: -1,
                confidence: "low".to_string(),
            });
        }
    }

    rows
}

fn resume_project_delivery_profile_has_project_names(profile: &ResumeDocumentProfile) -> bool {
    !profile.project_names.is_empty()
}

fn resume_project_delivery_lines(text: &str) -> Vec<String> {
    text.lines()
        .map(normalize_document_entity_value)
        .filter(|line| !line.is_empty())
        .collect()
}

fn resume_project_delivery_chunk_has_signal(lines: &[String]) -> bool {
    lines.iter().any(|line| {
        prompt_contains_any(
            line,
            &[
                "项目经验",
                "项目经历",
                "项目名称",
                "项目职责",
                "项目描述",
                "项目成果",
                "交付",
                "上线",
                "落地",
            ],
        ) || resume_project_delivery_project_name_from_line(line).is_some()
    })
}

fn resume_project_delivery_block_lines(lines: &[String], start_index: usize) -> Vec<String> {
    let mut block_lines = Vec::new();
    for line in lines.iter().skip(start_index) {
        if block_lines.len() >= ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_BLOCK_LINE_LIMIT {
            break;
        }
        if !block_lines.is_empty() && resume_project_delivery_project_name_from_line(line).is_some()
        {
            break;
        }
        if !block_lines.is_empty()
            && normalize_section_title_hint(line).is_some()
            && !prompt_contains_any(line, &["职责", "成果", "描述", "技术", "交付"])
        {
            break;
        }
        block_lines.push(line.clone());
    }
    block_lines
}

fn resume_project_delivery_summary_from_block(lines: &[String], project_name: &str) -> String {
    let mut summaries = Vec::new();
    for line in lines {
        if resume_project_delivery_line_is_project_heading(line, project_name) {
            continue;
        }
        if !resume_project_delivery_line_has_summary_signal(line) {
            continue;
        }
        let summary = resume_project_delivery_clean_summary_line(line);
        if summary.is_empty() || summaries.iter().any(|existing| existing == &summary) {
            continue;
        }
        summaries.push(summary);
        if summaries.len() >= 3 {
            break;
        }
    }
    if summaries.is_empty() {
        for line in lines.iter().skip(1) {
            let summary = resume_project_delivery_clean_summary_line(line);
            if summary.chars().count() >= 8 {
                summaries.push(summary);
                break;
            }
        }
    }
    summaries.join("；")
}

fn resume_project_delivery_line_is_project_heading(line: &str, project_name: &str) -> bool {
    resume_project_delivery_project_name_from_line(line)
        .as_deref()
        .is_some_and(|name| name == project_name)
}

fn resume_project_delivery_line_has_summary_signal(line: &str) -> bool {
    prompt_contains_any(
        line,
        &[
            "负责", "职责", "参与", "主导", "带领", "设计", "开发", "实现", "完成", "交付", "上线",
            "落地", "搭建", "架构", "优化", "对接", "部署", "维护", "推进", "成果", "模块", "需求",
        ],
    )
}

fn resume_project_delivery_clean_summary_line(line: &str) -> String {
    let mut summary = normalize_document_entity_value(line);
    for label in [
        "项目职责",
        "项目描述",
        "项目成果",
        "职责描述",
        "责任描述",
        "主要职责",
        "工作职责",
        "工作内容",
        "项目内容",
        "项目介绍",
        "技术栈",
    ] {
        if let Some(value) = labeled_entity_value(&summary, label) {
            summary = normalize_document_entity_value(&value);
            break;
        }
    }
    summary.chars().take(140).collect()
}

fn resume_project_delivery_tech_stack(text: &str, limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for skill in [
        "Java",
        "Spring Boot",
        "SpringCloud",
        "Spring Cloud",
        "Python",
        "Go",
        "Rust",
        "JavaScript",
        "TypeScript",
        "React",
        "Vue",
        "Node.js",
        "MySQL",
        "PostgreSQL",
        "Redis",
        "MongoDB",
        "Kafka",
        "RabbitMQ",
        "Docker",
        "Kubernetes",
        "微服务",
        "物联网",
        "IoT",
        "AI",
        "大数据",
        "数据治理",
        "系统架构",
    ] {
        if text.contains(skill) {
            push_document_candidate_term(&mut values, skill, limit);
        }
        if values.len() >= limit {
            break;
        }
    }
    values
}

fn resume_profile_entity_names(
    entity_candidates: &[DocumentEntityCandidate],
    entity_type: &str,
    limit: usize,
) -> Vec<String> {
    let mut names = Vec::new();
    for candidate in entity_candidates {
        if candidate.entity_type == entity_type {
            push_document_candidate_term(&mut names, &candidate.name, limit);
        }
        if names.len() >= limit {
            break;
        }
    }
    names
}

fn resume_profile_has_document_signal(
    document: &Document,
    scan_text: &str,
    profile: &ResumeDocumentProfile,
) -> bool {
    profile.age.is_some()
        || profile.gender.is_some()
        || profile.birth_year.is_some()
        || resume_profile_text_has_signal(&document.title)
        || resume_profile_text_has_signal(&document.object_key)
        || resume_profile_text_has_signal(scan_text)
        || (profile.candidate_name.is_some()
            && resume_profile_title_has_candidate_file_shape(&document.title))
}

fn resume_profile_text_has_signal(text: &str) -> bool {
    let lower_text = text.to_ascii_lowercase();
    [
        "简历",
        "履历",
        "候选人",
        "求职",
        "应聘",
        "招聘",
        "人才",
        "面试",
        "工作经验",
        "工作经历",
        "项目经验",
        "教育经历",
        "专业技能",
        "自我评价",
    ]
    .iter()
    .any(|hint| text.contains(hint))
        || ["resume", "cv", "candidate", "recruit"]
            .iter()
            .any(|hint| lower_text.contains(hint))
}

fn resume_profile_title_has_candidate_file_shape(title: &str) -> bool {
    let lower_title = title.to_ascii_lowercase();
    let has_document_extension = [".pdf", ".doc", ".docx", ".wps", ".rtf"]
        .iter()
        .any(|suffix| lower_title.ends_with(suffix));
    has_document_extension && extract_resume_candidate_name_from_title(title).is_some()
}

fn extract_resume_candidate_name(text: &str) -> Option<String> {
    extract_labeled_entity_values(text, &["姓名", "候选人"], 4)
        .into_iter()
        .find(|value| looks_like_person_name(value))
}

fn extract_resume_candidate_name_from_title(text: &str) -> Option<String> {
    extract_resume_candidate_name_from_heading_text(text, true)
        .or_else(|| extract_resume_candidate_name_from_object_key(text))
}

fn extract_resume_candidate_name_from_marked_text(text: &str) -> Option<String> {
    extract_resume_candidate_name_from_heading_text(text, false)
}

fn extract_resume_candidate_name_from_object_key(object_key: &str) -> Option<String> {
    let file_label = resume_profile_object_key_label(object_key)?;
    for segment in file_label.split(['-', '_', ' ', '　']) {
        let raw_segment = normalize_document_entity_value(
            segment
                .split(['(', '（', '[', '【'])
                .next()
                .unwrap_or(segment),
        );
        let normalized = normalize_resume_file_person_segment(&raw_segment);
        if looks_like_person_name(&normalized) {
            return Some(normalized);
        }
        if looks_like_resume_ascii_person_name(&raw_segment) {
            return Some(raw_segment);
        }
        if let Some(name) = extract_resume_candidate_name_from_heading_text(&normalized, false) {
            return Some(name);
        }
        if let Some(prefix) = raw_segment
            .split_once("简历")
            .map(|(prefix, _)| normalize_resume_file_person_segment(prefix))
            .filter(|value| looks_like_person_name(value))
        {
            return Some(prefix);
        }
        if let Some(prefix) = raw_segment
            .split_once("简历")
            .map(|(prefix, _)| normalize_document_entity_value(prefix))
            .filter(|value| looks_like_resume_ascii_person_name(value))
        {
            return Some(prefix);
        }
    }
    extract_resume_candidate_name_from_heading_text(&file_label, false)
}

fn normalize_resume_file_person_segment(value: &str) -> String {
    let trimmed = value.trim().trim_start_matches(|ch: char| {
        ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-' | ' ' | '　')
    });
    normalize_document_entity_value(trimmed)
}

fn looks_like_resume_ascii_person_name(value: &str) -> bool {
    let normalized = value.trim();
    let lower = normalized.to_ascii_lowercase();
    let char_count = normalized.chars().count();
    let alpha_count = normalized
        .chars()
        .filter(|ch| ch.is_ascii_alphabetic())
        .count();
    (2..=32).contains(&char_count)
        && alpha_count >= 2
        && normalized
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '_' | ' '))
        && ![
            "boss", "cv", "iot", "java", "resume", "title", "profile", "document", "python",
            "golang", "backend", "frontend", "product", "manager",
        ]
        .contains(&lower.as_str())
}

fn resume_profile_display_title(document: &Document) -> String {
    let title = normalize_document_entity_value(&document.title);
    if !title.is_empty() && !resume_profile_generic_version_label(&title) {
        return title;
    }
    resume_profile_object_key_label(&document.object_key)
        .filter(|value| !resume_profile_generic_version_label(value))
        .unwrap_or(title)
}

fn resume_profile_generic_version_label(value: &str) -> bool {
    let normalized = value.trim().to_ascii_lowercase();
    if normalized.is_empty() {
        return true;
    }
    if normalized == "v" || normalized == "version" || normalized == "版本" {
        return true;
    }
    normalized
        .strip_prefix('v')
        .filter(|suffix| !suffix.is_empty())
        .is_some_and(|suffix| suffix.chars().all(|ch| ch.is_ascii_digit()))
}

fn resume_profile_object_key_label(object_key: &str) -> Option<String> {
    let file_name = object_key
        .rsplit(['/', '\\'])
        .next()
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let stem = file_name
        .rsplit_once('.')
        .map(|(prefix, _)| prefix)
        .unwrap_or(file_name);
    let parts = stem.splitn(4, '-').collect::<Vec<_>>();
    let label = if parts.len() == 4
        && parts[0].chars().all(|ch| ch.is_ascii_digit())
        && parts[1].chars().all(|ch| ch.is_ascii_hexdigit())
        && parts[2].chars().all(|ch| ch.is_ascii_digit())
    {
        parts[3]
    } else {
        stem
    };
    let normalized = normalize_document_entity_value(label);
    (!normalized.is_empty()).then_some(normalized)
}

fn extract_resume_candidate_name_from_heading_text(
    text: &str,
    allow_standalone_name_line: bool,
) -> Option<String> {
    for line in text.lines().take(16) {
        let normalized = normalize_document_entity_value(line);
        if allow_standalone_name_line && looks_like_person_name(&normalized) {
            return Some(normalized);
        }
        let compact = normalized
            .chars()
            .filter(|ch| !ch.is_whitespace())
            .collect::<String>();
        for marker in [
            "个人简历",
            "个人履历",
            "简历",
            "履历",
            "Personalresume",
            "Resume",
            "CV",
        ] {
            if let Some(index) = compact.find(marker) {
                let prefix = compact[..index].trim_matches(|ch: char| {
                    ch.is_whitespace()
                        || matches!(ch, ':' | '：' | '-' | '_' | '|' | '｜' | '/' | '\\')
                });
                if looks_like_person_name(prefix) {
                    return Some(prefix.to_string());
                }
            }
        }
    }
    None
}

fn extract_resume_gender(text: &str) -> Option<String> {
    for value in extract_labeled_resume_values(text, &["性别"], 4) {
        if let Some(gender) = normalize_resume_gender(&value) {
            return Some(gender.to_string());
        }
    }
    for line in text.lines().take(24) {
        for segment in line.split(|ch: char| {
            matches!(ch, '\t' | '|' | '｜' | '/' | '／' | '，' | ',' | '；' | ';')
        }) {
            let normalized = normalize_document_entity_value(segment);
            if let Some(gender) = normalize_resume_gender(&normalized) {
                return Some(gender.to_string());
            }
        }
    }
    None
}

fn normalize_resume_gender(value: &str) -> Option<&'static str> {
    let normalized = value.trim();
    if normalized.contains("男女") || normalized.contains("不限") {
        return None;
    }
    if normalized.starts_with('男') || normalized == "M" || normalized.eq_ignore_ascii_case("male")
    {
        Some("男")
    } else if normalized.starts_with('女')
        || normalized == "F"
        || normalized.eq_ignore_ascii_case("female")
    {
        Some("女")
    } else {
        None
    }
}

fn extract_resume_age(text: &str) -> Option<u64> {
    for value in extract_labeled_resume_values(text, &["年龄"], 4) {
        if let Some(age) = first_bounded_number(&value, 16, 80) {
            return Some(age);
        }
    }
    None
}

fn extract_resume_birth_year(text: &str) -> Option<i32> {
    for value in extract_labeled_resume_values(text, &["出生年月", "出生日期", "出生年", "生日"], 4)
    {
        if let Some(year) = extract_years_from_text(&value, 1).into_iter().next() {
            if (1950..=Utc::now().year()).contains(&year) {
                return Some(year);
            }
        }
    }
    for line in text.lines().take(32) {
        if !line.contains("出生") {
            continue;
        }
        if let Some(year) = extract_years_from_text(line, 1).into_iter().next() {
            if (1950..=Utc::now().year()).contains(&year) {
                return Some(year);
            }
        }
    }
    None
}

fn extract_labeled_resume_values(text: &str, labels: &[&str], limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for line in text.lines() {
        for segment in line.split(|ch: char| matches!(ch, '\t' | '|' | '；' | ';')) {
            let normalized = segment.trim();
            if normalized.is_empty() {
                continue;
            }
            for label in labels {
                if let Some(value) = labeled_entity_value(normalized, label) {
                    for item in split_entity_value_list(&value) {
                        let item = normalize_document_entity_value(&item);
                        if !item.is_empty() && !values.iter().any(|existing| existing == &item) {
                            values.push(item);
                        }
                        if values.len() >= limit {
                            return values;
                        }
                    }
                }
            }
        }
    }
    values
}

fn extract_resume_timeline_years(text: &str, limit: usize) -> Vec<i32> {
    let birth_year = extract_resume_birth_year(text);
    let timeline_text = text
        .lines()
        .filter(|line| {
            !["出生", "生日", "年龄", "身份证"]
                .iter()
                .any(|label| line.contains(label))
        })
        .collect::<Vec<_>>()
        .join("\n");
    let years = extract_resume_years(&timeline_text, limit)
        .into_iter()
        .filter(|year| *year >= 1990 && Some(*year) != birth_year)
        .collect::<Vec<_>>();
    if years.is_empty() {
        extract_resume_years(text, limit)
            .into_iter()
            .filter(|year| *year >= 1990 && Some(*year) != birth_year)
            .collect()
    } else {
        years
    }
}

fn extract_resume_years(text: &str, limit: usize) -> Vec<i32> {
    let mut years = extract_years_from_text(text, limit);
    years.sort_unstable();
    years.dedup();
    years
}

fn extract_years_from_text(text: &str, limit: usize) -> Vec<i32> {
    let current_year = Utc::now().year();
    let mut years = Vec::new();
    let chars = text.chars().collect::<Vec<_>>();
    for index in 0..chars.len().saturating_sub(3) {
        if !chars[index..index + 4].iter().all(|ch| ch.is_ascii_digit()) {
            continue;
        }
        let raw = chars[index..index + 4].iter().collect::<String>();
        let Ok(year) = raw.parse::<i32>() else {
            continue;
        };
        if (1950..=current_year + 1).contains(&year) && !years.contains(&year) {
            years.push(year);
            if years.len() >= limit {
                break;
            }
        }
    }
    years
}

fn first_bounded_number(text: &str, min: u64, max: u64) -> Option<u64> {
    let mut digits = String::new();
    for ch in text.chars() {
        if ch.is_ascii_digit() {
            digits.push(ch);
            continue;
        }
        if let Some(value) = parse_bounded_number(&digits, min, max) {
            return Some(value);
        }
        digits.clear();
    }
    parse_bounded_number(&digits, min, max)
}

fn parse_bounded_number(digits: &str, min: u64, max: u64) -> Option<u64> {
    if digits.is_empty() {
        return None;
    }
    let value = digits.parse::<u64>().ok()?;
    (min..=max).contains(&value).then_some(value)
}

fn dataset_entity_scan_text(document: &Document, chunks: &[DocumentChunk]) -> String {
    let mut parts = vec![document.title.trim().to_string()];
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        parts.push(chunk.content.trim().to_string());
        parts.extend(document_chunk_section_title_hints(chunk));
        parts.extend(document_chunk_noun_terms(chunk));
    }
    parts
        .into_iter()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

fn dataset_entity_scan_structured_text(
    document: &Document,
    chunks: &[DocumentChunk],
) -> Option<String> {
    let mut parts = Vec::new();
    let mut seen = BTreeSet::new();
    push_unique_scan_text_part(&mut parts, &mut seen, &document.title);
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        if chunk.content.contains("Visual summary:")
            || chunk.content.contains("Visual transcription:")
            || chunk.content.contains("Visual evidence:")
        {
            push_unique_scan_text_part(&mut parts, &mut seen, &chunk.content);
        }
        collect_document_metadata_scan_text(&chunk.metadata, &mut parts, &mut seen);
    }
    if parts.is_empty() {
        None
    } else {
        Some(parts.join("\n"))
    }
}

fn push_unique_scan_text_part(parts: &mut Vec<String>, seen: &mut BTreeSet<String>, value: &str) {
    let normalized = value.trim();
    if normalized.is_empty() {
        return;
    }
    let normalized = truncate_assistant_supply_text(normalized, 1600);
    if seen.insert(normalized.clone()) {
        parts.push(normalized);
    }
}

fn collect_document_metadata_scan_text(
    metadata: &BTreeMap<String, Value>,
    parts: &mut Vec<String>,
    seen: &mut BTreeSet<String>,
) {
    visit_document_vlm_payloads(metadata, |payload| {
        for field in ["summary", "visualSummary", "transcribedText"] {
            if let Some(value) = payload.get(field).and_then(Value::as_str) {
                push_unique_scan_text_part(parts, seen, value);
            }
        }
        if let Some(entities) = payload.get("entities").and_then(Value::as_array) {
            for entity in entities {
                if let Some(text) = entity.get("text").and_then(Value::as_str) {
                    push_unique_scan_text_part(parts, seen, text);
                }
            }
        }
        if let Some(fields) = payload.get("fieldCandidates").and_then(Value::as_array) {
            for field in fields {
                let key = field.get("key").and_then(Value::as_str).unwrap_or("");
                let value = field.get("value").and_then(Value::as_str).unwrap_or("");
                if !key.trim().is_empty() && !value.trim().is_empty() {
                    push_unique_scan_text_part(parts, seen, &format!("{key}: {value}"));
                }
            }
        }
        if let Some(blocks) = payload.get("evidenceBlocks").and_then(Value::as_array) {
            for block in blocks {
                let title = block.get("title").and_then(Value::as_str).unwrap_or("");
                let text = block.get("text").and_then(Value::as_str).unwrap_or("");
                if !title.trim().is_empty() || !text.trim().is_empty() {
                    push_unique_scan_text_part(parts, seen, &format!("{title}: {text}"));
                }
            }
        }
    });
}

fn extract_document_entity_candidates_from_text(
    text: &str,
    limit: usize,
) -> Vec<DocumentEntityCandidate> {
    let mut candidates = Vec::new();
    let mut seen = BTreeSet::new();
    for name in extract_company_names_from_text(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "organization", name, limit);
    }
    for name in extract_labeled_entity_values(text, &["姓名", "候选人", "联系人"], limit) {
        if looks_like_person_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "person", name, limit);
        }
    }
    for name in extract_labeled_entity_values(
        text,
        &["应聘岗位", "目标岗位", "岗位", "职位", "职务", "角色"],
        limit,
    ) {
        if looks_like_position_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "position", name, limit);
        }
    }
    for name in
        extract_labeled_entity_values(text, &["技能", "核心技能", "专业技能", "技术栈"], limit)
    {
        if looks_like_skill_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "skill", name, limit);
        }
    }
    for name in extract_known_skill_names(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "skill", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &[
            "工作地点",
            "项目地点",
            "所在地",
            "所在城市",
            "城市",
            "地点",
            "籍贯",
        ],
        limit,
    ) {
        if looks_like_location_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "location", name, limit);
        }
    }
    for name in extract_known_location_names(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "location", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &[
            "毕业院校",
            "毕业学校",
            "就读院校",
            "学校",
            "院校",
            "大学",
            "学院",
        ],
        limit,
    ) {
        if looks_like_school_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "school", name, limit);
        }
    }
    for name in extract_school_like_terms(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "school", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &["最高学历", "学历", "学位", "教育程度", "教育背景"],
        limit,
    ) {
        if let Some(degree) = normalize_degree_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "degree", degree, limit);
        }
    }
    for name in extract_known_degree_names(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "degree", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &["证书", "资格证书", "认证", "资质", "职业资格"],
        limit,
    ) {
        if looks_like_certificate_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "certificate", name, limit);
        }
    }
    for name in extract_certificate_like_terms(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "certificate", name, limit);
    }
    for name in
        extract_labeled_entity_values(text, &["项目名称", "项目/产品名称", "产品名称"], limit)
    {
        if looks_like_project_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "project", name, limit);
        }
    }
    for name in extract_project_like_terms(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "project", name, limit);
    }
    candidates.truncate(limit);
    candidates
}

fn extract_document_entity_candidates_from_chunk_metadata(
    chunks: &[DocumentChunk],
    limit: usize,
) -> Vec<DocumentEntityCandidate> {
    let mut candidates = Vec::new();
    let mut seen = BTreeSet::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        visit_document_vlm_payloads(&chunk.metadata, |payload| {
            collect_document_vlm_entity_candidates(payload, &mut candidates, &mut seen, limit);
        });
        if candidates.len() >= limit {
            break;
        }
    }
    candidates
}

fn visit_document_vlm_payloads<F>(metadata: &BTreeMap<String, Value>, mut visitor: F)
where
    F: FnMut(&Value),
{
    for value in metadata.values() {
        visit_document_vlm_payloads_value(value, &mut visitor);
    }
}

fn visit_document_vlm_payloads_value<F>(value: &Value, visitor: &mut F)
where
    F: FnMut(&Value),
{
    if let Some(object) = value.as_object() {
        if let Some(payload) = object
            .get("vlm")
            .and_then(|vlm| vlm.get("payload"))
            .filter(|payload| payload.is_object())
        {
            visitor(payload);
        }
        for child in object.values() {
            visit_document_vlm_payloads_value(child, visitor);
        }
    } else if let Some(array) = value.as_array() {
        for child in array {
            visit_document_vlm_payloads_value(child, visitor);
        }
    }
}

fn collect_document_vlm_entity_candidates(
    payload: &Value,
    candidates: &mut Vec<DocumentEntityCandidate>,
    seen: &mut BTreeSet<String>,
    limit: usize,
) {
    if let Some(entities) = payload.get("entities").and_then(Value::as_array) {
        for entity in entities {
            if candidates.len() >= limit {
                return;
            }
            let Some(entity_type) = entity
                .get("type")
                .and_then(Value::as_str)
                .and_then(document_metadata_entity_type)
            else {
                continue;
            };
            let Some(text) = entity.get("text").and_then(Value::as_str) else {
                continue;
            };
            push_document_metadata_entity_candidate(candidates, seen, entity_type, text, limit);
        }
    }

    if let Some(fields) = payload.get("fieldCandidates").and_then(Value::as_array) {
        for field in fields {
            if candidates.len() >= limit {
                return;
            }
            let Some(entity_type) = field
                .get("key")
                .and_then(Value::as_str)
                .and_then(document_field_candidate_entity_type)
            else {
                continue;
            };
            let Some(value) = field.get("value").and_then(Value::as_str) else {
                continue;
            };
            push_document_metadata_entity_candidate(candidates, seen, entity_type, value, limit);
        }
    }

    if let Some(blocks) = payload.get("evidenceBlocks").and_then(Value::as_array) {
        let mut block_text = String::new();
        for block in blocks {
            if let Some(title) = block.get("title").and_then(Value::as_str) {
                block_text.push_str(title);
                block_text.push('\n');
            }
            if let Some(text) = block.get("text").and_then(Value::as_str) {
                block_text.push_str(text);
                block_text.push('\n');
            }
        }
        for name in extract_company_names_from_text(&block_text, limit) {
            push_document_metadata_entity_candidate(candidates, seen, "organization", &name, limit);
        }
    }
}

fn merge_document_entity_candidates(
    primary: Vec<DocumentEntityCandidate>,
    secondary: Vec<DocumentEntityCandidate>,
    limit: usize,
) -> Vec<DocumentEntityCandidate> {
    let mut merged = Vec::new();
    let mut seen = BTreeSet::new();
    for candidate in primary.into_iter().chain(secondary) {
        push_document_entity_candidate(
            &mut merged,
            &mut seen,
            candidate.entity_type,
            candidate.name,
            limit,
        );
        if merged.len() >= limit {
            break;
        }
    }
    merged
}

fn push_document_entity_candidate(
    output: &mut Vec<DocumentEntityCandidate>,
    seen: &mut BTreeSet<String>,
    entity_type: &'static str,
    name: String,
    limit: usize,
) {
    if output.len() >= limit {
        return;
    }
    let normalized = normalize_document_entity_value(&name);
    if normalized.is_empty() {
        return;
    }
    let normalized = match entity_type {
        "project" => {
            let Some(project_name) = normalize_project_entity_name(&normalized) else {
                return;
            };
            project_name
        }
        "degree" => {
            let Some(degree_name) = normalize_degree_name(&normalized) else {
                return;
            };
            degree_name
        }
        _ => normalized,
    };
    let key = format!("{entity_type}:{normalized}");
    if seen.insert(key) {
        output.push(DocumentEntityCandidate {
            entity_type,
            name: normalized,
        });
    }
}

fn push_document_metadata_entity_candidate(
    output: &mut Vec<DocumentEntityCandidate>,
    seen: &mut BTreeSet<String>,
    entity_type: &'static str,
    value: &str,
    limit: usize,
) {
    let normalized = normalize_document_entity_value(value);
    let accepted = match entity_type {
        "organization" => looks_like_metadata_organization_name(&normalized),
        "person" => looks_like_person_name(&normalized),
        "position" => looks_like_position_name(&normalized),
        "skill" => looks_like_skill_name(&normalized),
        "location" => looks_like_location_name(&normalized),
        "school" => looks_like_school_name(&normalized),
        "degree" => normalize_degree_name(&normalized).is_some(),
        "certificate" => looks_like_certificate_name(&normalized),
        "project" => {
            looks_like_project_name(&normalized)
                && looks_like_project_heading_candidate(&normalized)
                && !project_heading_is_noise(&normalized)
        }
        _ => false,
    };
    if accepted {
        push_document_entity_candidate(output, seen, entity_type, normalized, limit);
    }
}

fn document_metadata_entity_type(raw: &str) -> Option<&'static str> {
    let normalized = raw.trim();
    let lower = normalized.to_ascii_lowercase();
    if lower.contains("organization")
        || lower.contains("company")
        || normalized.contains("公司")
        || normalized.contains("组织")
        || normalized.contains("单位")
    {
        Some("organization")
    } else if lower.contains("person") || normalized.contains("人名") || normalized == "姓名" {
        Some("person")
    } else if lower.contains("job")
        || lower.contains("title")
        || normalized.contains("职位")
        || normalized.contains("岗位")
        || normalized.contains("职务")
    {
        Some("position")
    } else if lower.contains("skill")
        || normalized.contains("技能")
        || normalized.contains("技术栈")
    {
        Some("skill")
    } else if lower.contains("location")
        || lower.contains("city")
        || normalized.contains("地点")
        || normalized.contains("城市")
    {
        Some("location")
    } else if lower.contains("school")
        || lower.contains("university")
        || lower.contains("college")
        || normalized.contains("学校")
        || normalized.contains("院校")
        || normalized.contains("大学")
        || normalized.contains("学院")
    {
        Some("school")
    } else if lower.contains("degree")
        || lower.contains("education")
        || normalized.contains("学历")
        || normalized.contains("学位")
    {
        Some("degree")
    } else if lower.contains("certificate")
        || lower.contains("certification")
        || lower.contains("credential")
        || normalized.contains("证书")
        || normalized.contains("认证")
        || normalized.contains("资质")
    {
        Some("certificate")
    } else if lower.contains("project")
        || lower.contains("product")
        || normalized.contains("项目")
        || normalized.contains("产品")
    {
        Some("project")
    } else {
        None
    }
}

fn document_field_candidate_entity_type(raw_key: &str) -> Option<&'static str> {
    let key = raw_key.trim();
    let lower = key.to_ascii_lowercase();
    if lower.contains("employer")
        || lower.contains("company")
        || lower.contains("work_unit")
        || key.contains("公司")
        || key.contains("雇主")
        || key.contains("工作单位")
        || key.contains("任职单位")
    {
        Some("organization")
    } else if lower.contains("name") || key == "姓名" || key.contains("候选人") {
        Some("person")
    } else if lower.contains("position")
        || lower.contains("job_title")
        || key.contains("职位")
        || key.contains("岗位")
    {
        Some("position")
    } else if lower.contains("skill") || key.contains("技能") || key.contains("技术栈") {
        Some("skill")
    } else if lower.contains("city")
        || lower.contains("location")
        || key.contains("城市")
        || key.contains("地点")
    {
        Some("location")
    } else if lower.contains("school")
        || lower.contains("university")
        || lower.contains("college")
        || key.contains("学校")
        || key.contains("院校")
        || key.contains("毕业院校")
    {
        Some("school")
    } else if lower.contains("degree")
        || lower.contains("education")
        || key.contains("学历")
        || key.contains("学位")
    {
        Some("degree")
    } else if lower.contains("certificate")
        || lower.contains("certification")
        || lower.contains("credential")
        || key.contains("证书")
        || key.contains("认证")
        || key.contains("资质")
    {
        Some("certificate")
    } else if lower.contains("project") || key.contains("项目") {
        Some("project")
    } else {
        None
    }
}

fn extract_document_candidate_terms_for_scan(
    chunks: &[DocumentChunk],
    scan_text: &str,
    limit: usize,
) -> Vec<String> {
    let mut terms = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        for hint in document_chunk_section_title_hints(chunk) {
            push_document_candidate_term(&mut terms, hint, limit);
        }
        for term in document_chunk_noun_terms(chunk) {
            push_document_candidate_term(&mut terms, term, limit);
        }
    }
    for term in extract_document_candidate_terms_from_text(scan_text, limit) {
        push_document_candidate_term(&mut terms, term, limit);
    }
    terms
}

fn extract_document_candidate_terms_from_text(text: &str, limit: usize) -> Vec<String> {
    let mut terms = BTreeSet::new();
    for token in lexical_query_tokens(text) {
        if document_candidate_term_has_signal(&token) {
            let normalized = normalize_document_entity_value(&token);
            if !normalized.is_empty() {
                terms.insert(normalized);
            }
        }
    }
    let mut terms = terms.into_iter().collect::<Vec<_>>();
    terms.sort_by(|left, right| {
        document_candidate_term_score(right)
            .cmp(&document_candidate_term_score(left))
            .then_with(|| right.chars().count().cmp(&left.chars().count()))
            .then_with(|| left.cmp(right))
    });
    terms.truncate(limit);
    terms
}

fn push_document_candidate_term(output: &mut Vec<String>, value: impl AsRef<str>, limit: usize) {
    if output.len() >= limit {
        return;
    }
    let normalized = normalize_document_entity_value(value.as_ref());
    let char_count = normalized.chars().count();
    if char_count < 2
        || char_count > 32
        || output.iter().any(|existing| existing == &normalized)
        || is_document_entity_noise(&normalized)
    {
        return;
    }
    output.push(normalized);
}

fn extract_labeled_entity_values(text: &str, labels: &[&str], limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for line in text.lines() {
        for segment in line.split(|ch: char| matches!(ch, '\t' | '|' | '；' | ';')) {
            let normalized = segment.trim();
            if normalized.is_empty() {
                continue;
            }
            for label in labels {
                if let Some(value) = labeled_entity_value(normalized, label) {
                    for item in split_entity_value_list(&value) {
                        push_document_candidate_term(&mut values, item, limit);
                    }
                }
            }
            if values.len() >= limit {
                return values;
            }
        }
    }
    values
}

fn labeled_entity_value(segment: &str, label: &str) -> Option<String> {
    let normalized = segment.trim();
    let label_position = normalized.find(label)?;
    if label_position > 4 {
        return None;
    }
    let mut rest = normalized[label_position + label.len()..].trim();
    rest = rest.trim_start_matches(|ch: char| {
        ch.is_whitespace() || matches!(ch, ':' | '：' | '-' | '—' | '–' | '=')
    });
    if rest.is_empty() {
        return None;
    }
    Some(rest.chars().take(120).collect())
}

fn split_entity_value_list(value: &str) -> Vec<String> {
    value
        .split(|ch: char| {
            matches!(
                ch,
                ',' | '，' | '、' | '/' | '／' | ';' | '；' | '|' | '\t' | '\n' | '\r'
            )
        })
        .map(normalize_document_entity_value)
        .filter(|value| !value.is_empty())
        .collect()
}

fn normalize_document_entity_value(value: &str) -> String {
    value
        .trim()
        .trim_matches(|ch: char| {
            ch.is_whitespace()
                || matches!(
                    ch,
                    ':' | '：'
                        | '-'
                        | '—'
                        | '–'
                        | '_'
                        | '，'
                        | ','
                        | '。'
                        | '；'
                        | ';'
                        | '、'
                        | '（'
                        | '('
                        | '）'
                        | ')'
                        | '【'
                        | '['
                        | '】'
                        | ']'
                        | '"'
                        | '\''
                )
        })
        .chars()
        .take(80)
        .collect::<String>()
}

fn looks_like_metadata_organization_name(value: &str) -> bool {
    let char_count = value.chars().count();
    if char_count < 2
        || char_count > 40
        || value.contains('@')
        || value.chars().all(|ch| ch.is_ascii_digit())
        || company_name_has_unbalanced_brackets(value)
        || is_document_entity_noise(value)
        || company_candidate_has_ocr_noise(value)
    {
        return false;
    }
    if is_valid_company_name(value) {
        return true;
    }
    let has_name_signal = value.chars().any(is_cjk_query_token_char)
        || value.chars().any(|ch| ch.is_ascii_alphabetic());
    has_name_signal
        && ![
            "公司",
            "集团",
            "网络有限公司",
            "顾问有限公司",
            "科技有限公司",
            "信息有限公司",
        ]
        .contains(&value)
}

fn looks_like_person_name(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 2
        && char_count <= 4
        && value.chars().all(is_cjk_query_token_char)
        && !is_document_entity_noise(value)
        && !is_resume_person_name_noise(value)
        && !looks_like_position_name(value)
        && ![
            "姓名",
            "候选人",
            "联系人",
            "公司",
            "项目",
            "岗位",
            "职位",
            "城市",
            "技能",
        ]
        .contains(&value)
}

fn is_resume_person_name_noise(value: &str) -> bool {
    [
        "男",
        "女",
        "简历",
        "履历",
        "个人",
        "个人简历",
        "个人履历",
        "个人优势",
        "个人介绍",
        "个人简介",
        "亮点",
        "优势",
        "简介",
        "博士",
        "硕士",
        "学士",
        "本科",
        "大专",
        "高中",
        "概况",
        "基本信息",
        "联系方式",
        "教育经历",
        "工作经历",
        "项目经验",
        "专业技能",
        "技能清单",
        "自我评价",
        "求职意向",
    ]
    .contains(&value)
}

fn looks_like_position_name(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 2
        && char_count <= 32
        && [
            "工程师",
            "经理",
            "总监",
            "主管",
            "专员",
            "架构师",
            "顾问",
            "负责人",
            "运营",
            "产品",
            "开发",
            "测试",
            "设计师",
            "分析师",
        ]
        .iter()
        .any(|suffix| value.ends_with(suffix) || value.contains(suffix))
        && !is_document_entity_noise(value)
}

fn looks_like_skill_name(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 2
        && char_count <= 32
        && !is_document_entity_noise(value)
        && (value.chars().any(|ch| ch.is_ascii_alphabetic())
            || [
                "微服务",
                "知识库",
                "数据治理",
                "机器学习",
                "深度学习",
                "项目管理",
                "流程优化",
                "系统架构",
            ]
            .iter()
            .any(|skill| value.contains(skill)))
}

fn looks_like_location_name(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 2
        && char_count <= 20
        && !is_document_entity_noise(value)
        && (value.ends_with('市')
            || value.ends_with('省')
            || value.ends_with('区')
            || value.ends_with("特别行政区")
            || known_location_names().iter().any(|item| value == *item))
}

fn looks_like_school_name(value: &str) -> bool {
    let char_count = value.chars().count();
    if !(2..=40).contains(&char_count)
        || value.contains('@')
        || value.chars().all(|ch| ch.is_ascii_digit())
        || is_document_entity_noise(value)
    {
        return false;
    }
    let lower = value.to_ascii_lowercase();
    value.contains("大学")
        || value.contains("学院")
        || value.contains("学校")
        || value.contains("中学")
        || lower.contains("university")
        || lower.contains("college")
        || lower.contains("school")
}

fn looks_like_certificate_name(value: &str) -> bool {
    let char_count = value.chars().count();
    if !(2..=40).contains(&char_count)
        || value.contains('@')
        || value.chars().all(|ch| ch.is_ascii_digit())
        || is_document_entity_noise(value)
    {
        return false;
    }
    let lower = value.to_ascii_lowercase();
    value.contains('证')
        || value.contains("认证")
        || value.contains("资质")
        || value.contains("资格")
        || [
            "软考",
            "系统架构设计师",
            "信息系统项目管理师",
            "高级项目管理师",
            "注册会计师",
            "建造师",
        ]
        .iter()
        .any(|term| value.contains(term))
        || [
            "pmp", "cpa", "cfa", "acp", "ocp", "aws", "azure", "cka", "ckad",
        ]
        .iter()
        .any(|term| lower.contains(term))
}

fn looks_like_project_name(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 3
        && char_count <= 40
        && !is_document_entity_noise(value)
        && ["项目", "系统", "平台", "知识库", "中台", "网站", "小程序"]
            .iter()
            .any(|suffix| value.ends_with(suffix) || value.contains(suffix))
}

fn normalize_project_entity_name(value: &str) -> Option<String> {
    let mut best: Option<(usize, String)> = None;
    for segment in project_entity_candidate_segments(value) {
        let Some(candidate) = normalize_project_entity_segment(&segment) else {
            continue;
        };
        let score = project_entity_candidate_score(&candidate);
        if best.as_ref().is_none_or(|(best_score, best_value)| {
            score > *best_score
                || (score == *best_score && candidate.chars().count() > best_value.chars().count())
        }) {
            best = Some((score, candidate));
        }
    }
    best.map(|(_, value)| value)
}

fn project_entity_candidate_segments(value: &str) -> Vec<String> {
    let normalized = normalize_document_entity_value(value);
    let mut segments = normalized
        .split(|ch: char| matches!(ch, '|' | '｜' | '\t' | '\r' | '\n'))
        .map(normalize_document_entity_value)
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    if segments.is_empty() && !normalized.is_empty() {
        segments.push(normalized);
    }
    segments
}

fn normalize_project_entity_segment(value: &str) -> Option<String> {
    let mut candidate = normalize_document_entity_value(value);
    candidate = strip_project_numeric_prefix(&candidate);
    candidate = normalize_section_title_hint(&candidate).unwrap_or(candidate);
    candidate = strip_project_numeric_prefix(&candidate);
    candidate = trim_project_role_suffix(&candidate);
    candidate = trim_project_descriptive_suffix(&candidate);
    candidate = compact_project_descriptive_phrase(&candidate);
    candidate = normalize_document_entity_value(&candidate);
    if project_heading_is_noise(&candidate)
        || !looks_like_project_heading_candidate(&candidate)
        || !looks_like_project_name(&candidate)
    {
        return None;
    }
    Some(candidate)
}

fn strip_project_numeric_prefix(value: &str) -> String {
    let trimmed = value.trim().trim_start_matches(|ch: char| {
        ch.is_whitespace() || matches!(ch, '#' | '*' | '•' | '·' | '●' | '➢')
    });
    let chars = trimmed.chars().collect::<Vec<_>>();
    if chars.is_empty() || !chars[0].is_ascii_digit() {
        return trimmed.to_string();
    }
    let mut index = 0usize;
    while index < chars.len()
        && (chars[index].is_ascii_digit()
            || matches!(chars[index], '.' | '．' | '-' | '_' | ' ' | '　'))
    {
        index += 1;
    }
    if index == 0 || index > 12 || index >= chars.len() {
        return trimmed.to_string();
    }
    chars[index..].iter().collect::<String>().trim().to_string()
}

fn trim_project_role_suffix(value: &str) -> String {
    let mut candidate = normalize_document_entity_value(value);
    for suffix in [
        "Java工程师",
        "研发工程师",
        "软件工程师",
        "架构师",
        "系统架构师",
        "产品经理",
        "项目经理",
        "销售经理",
        "销售专员",
        "研发主管",
        "研发负责人",
        "服务端研发",
        "技术管理",
        "版本研发",
        "产品开发",
        "平台工作",
        "系统工作",
        "工作",
    ] {
        if !candidate.ends_with(suffix) {
            continue;
        }
        let prefix = normalize_document_entity_value(
            candidate
                .strip_suffix(suffix)
                .unwrap_or(&candidate)
                .trim_end_matches(|ch: char| matches!(ch, '-' | '—' | '–' | '_' | ' ' | '　')),
        );
        if looks_like_project_name(&prefix) && prefix.chars().count() >= 3 {
            candidate = prefix;
            break;
        }
    }
    candidate
}

fn trim_project_descriptive_suffix(value: &str) -> String {
    let mut candidate = normalize_document_entity_value(value);
    for suffix in [
        "的技术可行性研究",
        "技术可行性研究",
        "可行性研究",
        "的数据链路",
        "数据链路",
        "的研发",
        "研发",
        "的研究",
        "研究",
        "解决方案研究",
        "解决方案研究与评估",
        "解决方案",
        "技术方案",
    ] {
        if !candidate.ends_with(suffix) {
            continue;
        }
        let prefix = normalize_document_entity_value(
            candidate
                .strip_suffix(suffix)
                .unwrap_or(&candidate)
                .trim_end_matches(|ch: char| {
                    matches!(ch, '-' | '—' | '–' | '_' | ' ' | '　' | '的')
                }),
        );
        if prefix.chars().count() >= 3 {
            candidate = prefix;
            break;
        }
    }
    candidate
}

fn compact_project_descriptive_phrase(value: &str) -> String {
    let candidate = normalize_document_entity_value(value);
    if !candidate.contains('的') {
        return candidate;
    }
    for segment in candidate.split('的').rev() {
        let segment = normalize_document_entity_value(segment);
        if segment.chars().count() >= 3
            && looks_like_project_name(&segment)
            && looks_like_project_heading_candidate(&segment)
            && !project_heading_is_noise(&segment)
        {
            return segment;
        }
    }
    candidate
}

fn project_entity_candidate_score(value: &str) -> usize {
    let mut score = value.chars().count();
    for signal in [
        "物联网",
        "IOT",
        "系统",
        "平台",
        "项目",
        "小程序",
        "网站",
        "中台",
    ] {
        if value.contains(signal) {
            score += 20;
        }
    }
    if looks_like_position_name(value) {
        score = score.saturating_sub(40);
    }
    score
}

