fn extract_school_like_terms(text: &str, limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
        for segment in split_entity_value_list(line) {
            for suffix in ["职业技术学院", "技术学院", "大学", "学院", "学校", "中学"]
            {
                if let Some(name) = extract_suffix_entity_from_segment(&segment, suffix, 40) {
                    if looks_like_school_name(&name) {
                        push_document_candidate_term(&mut values, name, limit);
                    }
                }
            }
            if values.len() >= limit {
                return values;
            }
        }
    }
    values
}

fn extract_certificate_like_terms(text: &str, limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for certificate in [
        "PMP",
        "CPA",
        "CFA",
        "软考高级",
        "系统架构设计师",
        "信息系统项目管理师",
        "高级项目管理师",
        "教师资格证",
        "法律职业资格",
        "注册会计师",
        "一级建造师",
        "二级建造师",
    ] {
        if text.contains(certificate) {
            push_document_candidate_term(&mut values, certificate, limit);
        }
    }
    for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
        if !prompt_contains_any(line, &["证书", "认证", "资质", "资格"]) {
            continue;
        }
        for segment in split_entity_value_list(line) {
            let candidate = normalize_document_entity_value(
                segment
                    .rsplit(|ch: char| matches!(ch, ':' | '：'))
                    .next()
                    .unwrap_or(segment.as_str()),
            );
            if looks_like_certificate_name(&candidate) {
                push_document_candidate_term(&mut values, candidate, limit);
            }
            if values.len() >= limit {
                return values;
            }
        }
    }
    values
}

fn extract_suffix_entity_from_segment(
    segment: &str,
    suffix: &str,
    max_chars: usize,
) -> Option<String> {
    let end = segment.find(suffix)? + suffix.len();
    let prefix = &segment[..end];
    let raw = prefix
        .rsplit(|ch: char| {
            ch.is_whitespace()
                || matches!(
                    ch,
                    ':' | '：'
                        | ','
                        | '，'
                        | ';'
                        | '；'
                        | '|'
                        | '｜'
                        | '/'
                        | '／'
                        | '('
                        | '（'
                        | ')'
                        | '）'
                )
        })
        .next()
        .unwrap_or(prefix);
    let trimmed = raw.trim_start_matches(|ch: char| {
        ch.is_ascii_digit() || matches!(ch, '-' | '—' | '–' | '.' | '．' | '_' | '年' | '月')
    });
    let value = normalize_document_entity_value(trimmed);
    ((2..=max_chars).contains(&value.chars().count())).then_some(value)
}

fn normalize_degree_name(value: &str) -> Option<String> {
    let normalized = normalize_document_entity_value(value);
    let lower = normalized.to_ascii_lowercase();
    let degree = if normalized.contains("博士") || lower.contains("phd") || lower.contains("doctor")
    {
        "博士"
    } else if normalized.contains("硕士")
        || normalized.contains("研究生")
        || normalized.contains("MBA")
        || normalized.contains("EMBA")
        || lower.contains("master")
    {
        if normalized.contains("博士") {
            "博士"
        } else {
            "硕士"
        }
    } else if normalized.contains("本科")
        || normalized.contains("学士")
        || lower.contains("bachelor")
    {
        "本科"
    } else if normalized.contains("大专") || normalized.contains("专科") {
        "大专"
    } else if normalized.contains("中专") {
        "中专"
    } else if normalized.contains("高中") {
        "高中"
    } else {
        return None;
    };
    Some(degree.to_string())
}

fn degree_rank(value: &str) -> Option<i64> {
    match normalize_degree_name(value)?.as_str() {
        "博士" => Some(6),
        "硕士" => Some(5),
        "本科" => Some(4),
        "大专" => Some(3),
        "中专" => Some(2),
        "高中" => Some(1),
        _ => None,
    }
}

fn extract_project_like_terms(text: &str, limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
        if let Some(name) = project_name_from_heading_line(line) {
            push_document_candidate_term(&mut values, name, limit);
        }
        if values.len() >= limit {
            break;
        }
    }
    values
}

fn project_name_from_heading_line(line: &str) -> Option<String> {
    let normalized = normalize_document_entity_value(line);
    if normalized.is_empty() {
        return None;
    }
    for label in ["项目名称", "项目名", "产品名称", "项目"] {
        if let Some(name) = labeled_project_name_from_line(&normalized, label) {
            return Some(name);
        }
    }
    let heading =
        normalize_section_title_hint(&normalized).unwrap_or_else(|| normalized.to_string());
    if project_heading_is_noise(&heading) || !looks_like_project_heading_candidate(&heading) {
        return None;
    }
    looks_like_project_name(&heading).then_some(heading)
}

fn resume_project_delivery_project_name_from_line(line: &str) -> Option<String> {
    let normalized = normalize_document_entity_value(line);
    if normalized.is_empty() {
        return None;
    }
    if let Some(name) = project_name_from_heading_line(&normalized) {
        return Some(name);
    }
    if let Some(name) = resume_project_name_from_numbered_label(&normalized) {
        return Some(name);
    }
    let stripped = strip_resume_project_bullet_prefix(&normalized);
    if stripped != normalized {
        if let Some(name) = normalize_project_entity_name(&stripped) {
            return Some(name);
        }
        if looks_like_project_heading_candidate(&stripped)
            && looks_like_project_name(&stripped)
            && !project_heading_is_noise(&stripped)
        {
            return Some(stripped);
        }
    }
    normalize_project_entity_name(&normalized)
}

fn resume_project_name_from_numbered_label(line: &str) -> Option<String> {
    let trimmed = line.trim();
    for prefix in [
        "项目一",
        "项目二",
        "项目三",
        "项目四",
        "项目五",
        "项目六",
        "项目七",
        "项目八",
        "项目九",
        "项目十",
    ] {
        if let Some(rest) = trimmed.strip_prefix(prefix) {
            return resume_project_name_from_label_rest(rest);
        }
    }
    if let Some(rest) = trimmed.strip_prefix("项目") {
        let rest_chars = rest.chars().collect::<Vec<_>>();
        let digit_len = rest_chars
            .iter()
            .take_while(|ch| ch.is_ascii_digit())
            .count();
        if digit_len > 0 {
            let rest_after_digit = rest_chars[digit_len..].iter().collect::<String>();
            return resume_project_name_from_label_rest(&rest_after_digit);
        }
    }
    None
}

fn resume_project_name_from_label_rest(rest: &str) -> Option<String> {
    let value = rest
        .trim_start_matches(|ch: char| {
            ch.is_whitespace() || matches!(ch, ':' | '：' | '-' | '—' | '–' | '=' | '.' | '．')
        })
        .trim();
    if value.is_empty() {
        return None;
    }
    normalize_project_entity_name(value).or_else(|| {
        let candidate = normalize_document_entity_value(
            value
                .split(|ch: char| matches!(ch, '，' | ',' | '。' | '；' | ';'))
                .next()
                .unwrap_or(value),
        );
        (looks_like_project_heading_candidate(&candidate)
            && looks_like_project_name(&candidate)
            && !project_heading_is_noise(&candidate))
        .then_some(candidate)
    })
}

fn strip_resume_project_bullet_prefix(value: &str) -> String {
    let trimmed = value.trim().trim_start_matches(|ch: char| {
        ch.is_whitespace() || matches!(ch, '#' | '*' | '•' | '·' | '●' | '➢')
    });
    let ascii_stripped = strip_project_numeric_prefix(trimmed);
    if ascii_stripped != trimmed {
        return ascii_stripped;
    }
    let chars = trimmed.chars().collect::<Vec<_>>();
    if chars.len() >= 3
        && matches!(
            chars[0],
            '一' | '二' | '三' | '四' | '五' | '六' | '七' | '八' | '九' | '十'
        )
        && matches!(chars[1], '、' | '.' | '．' | ')' | '）' | ':' | '：')
    {
        return chars[2..].iter().collect::<String>().trim().to_string();
    }
    trimmed.to_string()
}

fn labeled_project_name_from_line(line: &str, label: &str) -> Option<String> {
    let trimmed = line.trim();
    let label_position = trimmed.find(label)?;
    if label_position > 4 {
        return None;
    }
    let after_label = trimmed[label_position + label.len()..].trim_start();
    if !after_label
        .chars()
        .next()
        .is_some_and(|ch| matches!(ch, ':' | '：' | '-' | '—' | '–' | '='))
    {
        return None;
    }
    let value = labeled_entity_value(trimmed, label)?;
    let candidate = normalize_document_entity_value(
        value
            .split(|ch: char| matches!(ch, '，' | ',' | '。' | '；' | ';' | '\n' | '\r'))
            .next()
            .unwrap_or(&value),
    );
    if looks_like_project_heading_candidate(&candidate) && looks_like_project_name(&candidate) {
        Some(candidate)
    } else {
        None
    }
}

fn looks_like_project_heading_candidate(value: &str) -> bool {
    let char_count = value.chars().count();
    (3..=48).contains(&char_count)
        && !value.contains('@')
        && value.chars().filter(|ch| ch.is_ascii_digit()).count() < 8
        && !value
            .chars()
            .any(|ch| matches!(ch, '，' | ',' | '。' | '；' | ';' | '、' | '：' | ':'))
        && ![
            "熟悉",
            "完成",
            "负责",
            "参与",
            "带领",
            "使用",
            "采用",
            "主要",
            "职责",
            "团队",
            "描述",
            "内容",
            "经验",
            "能力",
            "以上",
            "以下",
            "公司",
            "各类",
            "入驻",
            "打通",
            "目的",
            "旨在",
            "面向",
            "项目情况",
            "项目需求",
            "项目报价",
            "项目跟进",
            "项目投标",
            "项目为",
            "项目是",
            "个主要项目",
            "实现",
            "协助",
            "落地",
            "编写",
            "协调",
            "挖掘",
            "记录",
            "交流",
            "部署",
            "链路",
            "调试",
            "交付阶段",
            "交付保障",
            "执行力",
            "角色",
            "本科",
            "硕士",
            "博士",
        ]
        .iter()
        .any(|noise| value.contains(noise))
}

fn project_heading_is_noise(value: &str) -> bool {
    is_document_entity_noise(value)
        || value.starts_with("该项目")
        || value.starts_with("此项目")
        || value.starts_with("本项目")
        || [
            "项目经验",
            "项目经历",
            "项目介绍",
            "项目描述",
            "项目职责",
            "项目业绩",
            "项目成果",
            "项目背景",
            "项目管理",
            "项目列表",
            "项目名称",
            "项目情况",
            "项目主管",
            "讲平台",
        ]
        .contains(&value)
}

fn document_candidate_term_has_signal(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 2
        && char_count <= 24
        && !is_document_entity_noise(value)
        && (chunk_like_business_suffix(value)
            || looks_like_position_name(value)
            || looks_like_skill_name(value)
            || looks_like_school_name(value)
            || looks_like_certificate_name(value)
            || normalize_degree_name(value).is_some()
            || looks_like_project_name(value))
}

fn document_candidate_term_score(value: &str) -> usize {
    let mut score = value.chars().count();
    if looks_like_project_name(value) {
        score += 30;
    }
    if chunk_like_business_suffix(value) {
        score += 20;
    }
    if looks_like_skill_name(value) {
        score += 12;
    }
    if looks_like_position_name(value) {
        score += 10;
    }
    if looks_like_school_name(value) {
        score += 10;
    }
    if looks_like_certificate_name(value) {
        score += 10;
    }
    if normalize_degree_name(value).is_some() {
        score += 8;
    }
    score
}

