fn extract_company_names_from_text(text: &str, limit: usize) -> Vec<String> {
    if limit == 0 {
        return Vec::new();
    }

    let mut names = Vec::new();
    let mut seen = BTreeSet::new();
    for segment in text.split(|ch: char| {
        matches!(
            ch,
            '\n' | '\r' | '，' | ',' | '；' | ';' | '。' | '、' | '|' | '/' | '／' | '\t'
        )
    }) {
        for name in extract_company_names_from_segment(segment) {
            if seen.insert(name.clone()) {
                names.push(name);
                if names.len() >= limit {
                    return names;
                }
            }
        }
    }
    names
}

fn extract_company_names_from_segment(segment: &str) -> Vec<String> {
    let normalized = segment.split_whitespace().collect::<String>();
    if !(normalized.contains("有限公司")
        || normalized.contains("有限责任公司")
        || normalized.contains("股份有限公司")
        || normalized.contains("集团"))
    {
        return Vec::new();
    }

    let mut names = Vec::new();
    let mut seen = BTreeSet::new();
    for suffix in ["股份有限公司", "有限责任公司", "有限公司", "集团"] {
        let mut offset = 0usize;
        while let Some(position) = normalized[offset..].find(suffix) {
            let end = offset + position + suffix.len();
            if suffix == "集团"
                && ["有限公司", "有限责任公司", "股份有限公司"]
                    .iter()
                    .any(|tail| normalized[end..].starts_with(tail))
            {
                offset = end;
                continue;
            }
            let candidate = normalize_company_relation_prefix(sanitize_company_candidate(
                &normalized[company_candidate_start(&normalized[..end])..end],
            ));
            if is_valid_company_name(&candidate) && seen.insert(candidate.clone()) {
                names.push(candidate);
            }
            offset = end;
        }
    }
    names
}

fn company_candidate_start(value: &str) -> usize {
    let mut start = 0usize;
    for (index, ch) in value.char_indices() {
        if matches!(
            ch,
            '：' | ':'
                | '-'
                | '－'
                | '—'
                | '–'
                | '】'
                | ']'
                | '，'
                | ','
                | '；'
                | ';'
                | '、'
                | '#'
                | '>'
                | '➢'
                | '•'
                | '·'
                | '~'
                | '～'
        ) {
            start = index + ch.len_utf8();
        }
    }
    start
}

fn sanitize_company_candidate(raw: &str) -> String {
    let mut value = strip_company_candidate_leading_noise(raw)
        .trim_matches(|ch: char| {
            ch.is_whitespace()
                || matches!(
                    ch,
                    ':' | '：'
                        | '-'
                        | '－'
                        | '—'
                        | '–'
                        | '_'
                        | '，'
                        | ','
                        | '。'
                        | '；'
                        | ';'
                        | '、'
                        | '（'
                        | '('
                        | '【'
                        | '['
                        | '#'
                        | '>'
                        | '➢'
                        | '•'
                        | '·'
                        | '~'
                        | '～'
                )
        })
        .to_string();

    loop {
        let before = value.clone();
        value = strip_company_candidate_leading_noise(&value);
        for prefix in [
            "最近就职公司",
            "就职公司",
            "任职公司",
            "所在公司",
            "公司名称",
            "工作单位",
            "任职单位",
            "所在单位",
            "工作经历",
            "曾任职于",
            "任职于",
            "就职于",
            "工作于",
            "供职于",
            "服务于",
            "来自",
            "给",
            "用房",
            "在职",
            "目前",
            "雇主",
        ] {
            if value.starts_with(prefix) {
                value = value[prefix.len()..].to_string();
            }
        }
        value = value
            .trim_matches(|ch: char| {
                ch.is_whitespace()
                    || matches!(
                        ch,
                        ':' | '：'
                            | '-'
                            | '－'
                            | '—'
                            | '–'
                            | '、'
                            | '，'
                            | ','
                            | '）'
                            | ')'
                            | '】'
                            | ']'
                            | '#'
                            | '>'
                            | '➢'
                            | '•'
                            | '·'
                            | '~'
                            | '～'
                    )
            })
            .to_string();
        if value == before {
            break;
        }
    }
    value
}

fn strip_company_candidate_leading_noise(raw: &str) -> String {
    let mut value = raw.trim().to_string();
    loop {
        let before = value.clone();
        value = value
            .trim_start_matches(|ch: char| {
                ch.is_ascii_digit()
                    || ch.is_whitespace()
                    || matches!(
                        ch,
                        '.' | '/'
                            | '\\'
                            | '-'
                            | '－'
                            | '—'
                            | '–'
                            | '_'
                            | '年'
                            | '月'
                            | '日'
                            | '至'
                            | '今'
                            | '一'
                            | '到'
                            | '）'
                            | ')'
                            | '】'
                            | ']'
                            | '#'
                            | '>'
                            | '➢'
                            | '•'
                            | '·'
                            | '~'
                            | '～'
                    )
            })
            .to_string();
        for prefix in ["工作经历", "项目经历", "任职经历", "教育经历"] {
            if value.starts_with(prefix) {
                value = value[prefix.len()..].to_string();
            }
        }
        if value == before {
            break;
        }
    }
    value
}

fn normalize_company_relation_prefix(mut value: String) -> String {
    loop {
        let before = value.clone();
        for marker in [
            "是由",
            "隶属于",
            "服务于",
            "任职于",
            "就职于",
            "供职于",
            "来自",
            "协同",
            "由",
            "和",
            "与",
            "及",
            "是",
            "的",
            "给",
            "在",
            "于",
        ] {
            if let Some(position) = value.rfind(marker) {
                if position > 0 {
                    let candidate = sanitize_company_candidate(&value[position + marker.len()..]);
                    if candidate.chars().count() >= 4 {
                        value = candidate;
                    }
                }
            }
        }
        value = sanitize_company_candidate(&value);
        if value == before {
            break;
        }
    }
    value
}

fn is_valid_company_name(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 4
        && char_count <= 40
        && !value.starts_with('#')
        && !value.starts_with('➢')
        && !value.chars().next().is_some_and(|ch| ch.is_ascii_digit())
        && ![
            "股份有限公司",
            "有限责任公司",
            "有限公司",
            "集团",
            "网络有限公司",
            "顾问有限公司",
            "络有限公司",
            "问有限公司",
        ]
        .contains(&value)
        && (value.ends_with("股份有限公司")
            || value.ends_with("有限责任公司")
            || value.ends_with("有限公司")
            || value.ends_with("集团"))
        && company_name_has_meaningful_stem(value)
        && !value.contains('@')
        && !company_name_has_unbalanced_brackets(value)
        && !company_candidate_has_ocr_noise(value)
        && ![
            "公司产品",
            "公司安排",
            "办公系统",
            "工作经历",
            "项目作为",
            "项目得到",
            "统筹规划",
            "统筹推进",
            "配合CIO",
            "实现集团",
            "实现了",
            "完成了",
            "开发了给",
            "参与1",
            "同办公系统",
            "客户公司",
            "本公司",
            "贵公司",
            "对公司",
            "为公司",
            "业务目标",
            "整个集团",
            "了全集团",
            "地亦股休",
            "服务讽备",
        ]
        .iter()
        .any(|fragment| value.contains(fragment))
        && ![
            "实现", "完成", "项目", "配合", "统筹", "参与", "定制", "后期", "在职", "了", "对接",
            "负责", "充分", "达成", "满足",
        ]
        .iter()
        .any(|prefix| value.starts_with(prefix))
}

fn company_name_has_meaningful_stem(value: &str) -> bool {
    ["股份有限公司", "有限责任公司", "有限公司", "集团"]
        .iter()
        .find_map(|suffix| value.strip_suffix(suffix))
        .is_some_and(|stem| stem.chars().filter(|ch| !ch.is_whitespace()).count() >= 2)
}

fn company_candidate_has_ocr_noise(value: &str) -> bool {
    let char_count = value.chars().count();
    if char_count == 0 {
        return true;
    }
    let rare_noise_chars = value
        .chars()
        .filter(|ch| {
            matches!(
                ch,
                '僧' | '牢' | '讽' | '玟' | '窟' | '赐' | '召' | '亦' | '休'
            )
        })
        .count();
    rare_noise_chars > 0
}

fn company_name_has_unbalanced_brackets(value: &str) -> bool {
    let left_cn = value.matches('（').count();
    let right_cn = value.matches('）').count();
    let left_ascii = value.matches('(').count();
    let right_ascii = value.matches(')').count();
    left_cn != right_cn || left_ascii != right_ascii
}

async fn build_assistant_run_chunk_fallback_supply(
    state: &AppState,
    dataset: &Dataset,
    prompt: &str,
    limit: usize,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
    media_context_by_document: &mut HashMap<DocumentId, Option<Value>>,
    fallback_reason: &str,
) -> std::result::Result<Vec<Value>, ApiError> {
    if limit == 0 {
        return Ok(Vec::new());
    }

    let documents = list_documents_for_dataset_scope(state, dataset.id)
        .await?
        .into_iter()
        .filter(|document| {
            document_is_visible_for_assistant_evidence_owner_scope(
                document,
                current_user_id,
                selected_document_ids,
                allow_selected_documents_without_acl_snapshot,
            )
        })
        .filter(|document| {
            selected_document_ids.is_empty() || selected_document_ids.contains(&document.id)
        })
        .collect::<Vec<_>>();
    let mut sources = Vec::new();
    for document in documents {
        if !document_is_visible_for_external_acl(
            state,
            external_acl_filter,
            &document,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?
        {
            continue;
        }
        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        for chunk in chunks
            .into_iter()
            .filter(|chunk| !chunk.content.trim().is_empty())
        {
            sources.push((document.clone(), chunk));
        }
    }

    let ranked = rank_document_chunks_for_prompt(sources, prompt, limit);
    let mut items = Vec::with_capacity(ranked.len());
    for ranked in ranked {
        let media_context = assistant_run_media_context_for_document(
            state,
            ranked.chunk.document_id,
            media_context_by_document,
        )
        .await?;
        let section_title_hints = document_chunk_section_title_hints(&ranked.chunk);
        let noun_terms = document_chunk_noun_terms(&ranked.chunk);
        let mut supplied_item = json!({
            "type": "retrieval_evidence",
            "source": "document_chunk_fallback",
            "fallback_reason": fallback_reason,
            "dataset_id": ranked.chunk.dataset_id,
            "document_id": ranked.chunk.document_id,
            "document_chunk_id": ranked.chunk.id,
            "chunk_index": ranked.chunk.chunk_index,
            "source_locator": document_chunk_fallback_source_locator(&ranked.document, &ranked.chunk),
            "summary": document_chunk_fallback_summary(&ranked.document, &ranked.chunk),
            "content_excerpt": truncate_assistant_supply_text(&ranked.chunk.content, 900),
            "payload_filter_key": format!("dataset/{}/document/{}", dataset.key, ranked.document.object_key),
            "score": ranked.score,
            "lexical_score": ranked.lexical_score,
            "recall_score": 0.0,
            "evidence_manifest": {
                "fallback": {
                    "source": "document_chunk",
                    "reason": fallback_reason
                },
                "evidence": {
                    "section_title_hints": &section_title_hints,
                    "noun_terms": &noun_terms
                },
                "embedding": {
                    "term_weights": limited_lexical_term_weights(&ranked.search_text, 40)
                }
            },
        });
        if let Some(media_context) = media_context {
            if let Some(object) = supplied_item.as_object_mut() {
                object.insert("media_context".to_string(), media_context);
            }
        }
        items.push(supplied_item);
    }
    Ok(items)
}

fn append_deduped_assistant_supply_items(target: &mut Vec<Value>, candidates: Vec<Value>) -> usize {
    let mut seen = target
        .iter()
        .filter_map(assistant_run_supply_item_identity)
        .collect::<BTreeSet<_>>();
    let before = target.len();
    for item in candidates {
        let Some(identity) = assistant_run_supply_item_identity(&item) else {
            target.push(item);
            continue;
        };
        if seen.insert(identity) {
            target.push(item);
        }
    }
    target.len().saturating_sub(before)
}

fn assistant_run_supply_item_identity(item: &Value) -> Option<String> {
    item.get("document_chunk_id")
        .or_else(|| item.get("documentChunkId"))
        .and_then(Value::as_str)
        .map(|value| format!("chunk:{value}"))
        .or_else(|| {
            item.get("retrieval_evidence_id")
                .or_else(|| item.get("retrievalEvidenceId"))
                .and_then(Value::as_str)
                .map(|value| format!("evidence:{value}"))
        })
        .or_else(|| {
            item.get("source_locator")
                .or_else(|| item.get("sourceLocator"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(|value| format!("locator:{value}"))
        })
}

fn assistant_run_prompt_requests_expanded_supply(prompt: &str) -> bool {
    prompt_requests_procedure_or_action(prompt)
        || prompt_contains_elder_fall_signal(prompt)
        || prompt_contains_elder_death_signal(prompt)
}

fn prompt_requests_procedure_or_action(prompt: &str) -> bool {
    prompt_contains_any(
        prompt,
        &[
            "怎么办",
            "怎么处理",
            "如何处理",
            "第一时间",
            "流程",
            "步骤",
            "应急",
            "处置",
            "处理规范",
            "操作规范",
            "风险",
            "注意事项",
        ],
    )
}

fn prompt_contains_elder_fall_signal(prompt: &str) -> bool {
    prompt_contains_any(
        prompt,
        &[
            "摔倒",
            "跌倒",
            "摔伤",
            "跌伤",
            "坠床",
            "骨折",
            "意外伤害",
            "突发事件",
            "人身意外",
        ],
    )
}

fn prompt_contains_elder_death_signal(prompt: &str) -> bool {
    prompt_contains_any(
        prompt,
        &[
            "离世",
            "去世",
            "死亡",
            "身故",
            "过世",
            "病故",
            "善后",
            "殡葬",
            "遗体",
            "遗物",
            "家属对接",
            "生命体征",
        ],
    )
}

fn assistant_run_expanded_supply_prompt(prompt: &str) -> String {
    let mut parts = vec![prompt.trim().to_string()];
    if prompt_requests_procedure_or_action(prompt) {
        parts.push(
            "流程 步骤 处理 处置 应急 措施 要求 报告 记录 通知 医护 家属 现场评估".to_string(),
        );
    }
    if prompt_contains_elder_fall_signal(prompt) {
        parts.push(
            "摔倒 跌倒 防跌倒 坠床 防坠床 摔伤 跌伤 骨折 老年人人身意外伤害 突发事件 应急处置 事故处理 120 通知家属 通知主管领导 医护人员 转院 记录 报告 不要急于扶起"
                .to_string(),
        );
    }
    if prompt_contains_elder_death_signal(prompt) {
        parts.push(
            "离世 去世 死亡 身故 病故 善后 殡葬 遗体 遗物 生命体征 医护确认 现场保护 通知负责人 通知家属 家属沟通 家属对接 死亡证明 殡仪接运 遗物清点 遗物交接 记录归档 事件报告"
                .to_string(),
        );
    }
    parts
        .into_iter()
        .map(|part| part.trim().to_string())
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join(" ")
}

fn assistant_run_recovery_followup_for_weak_supply(
    selected_scope: &Value,
    prompt: &str,
    status: &str,
    supplied_items: &[Value],
    supply_quality: &Value,
    unavailable_dataset_ids: &[String],
) -> Option<Value> {
    let supply_requested = supply_quality
        .get("supplyRequested")
        .and_then(Value::as_bool)
        .unwrap_or(status != "not_requested");
    if !supply_requested {
        return None;
    }

    let quality_status = supply_quality
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let answerable_supply_count = [
        "indexedEvidenceCount",
        "fallbackChunkCount",
        "datasetEntityScanCount",
        "datasetFactSnapshotCount",
        "spreadsheetRowAnalysisCount",
        "mediaContextCount",
        "conversationMemoryItemCount",
    ]
    .iter()
    .filter_map(|key| supply_quality.get(*key).and_then(Value::as_u64))
    .sum::<u64>();
    let has_weak_expansion =
        assistant_run_supply_has_weak_indexed_evidence_expansion(supplied_items, supply_quality);
    let has_low_text_evidence = supply_quality
        .get("lowTextEvidenceCount")
        .and_then(Value::as_u64)
        .map(|count| count > 0)
        .unwrap_or_else(|| {
            assistant_run_supply_quality_has_note(supply_quality, "low_text_document_evidence")
        });
    let has_parse_blocker = [
        "documentNotReadyCount",
        "documentFailedCount",
        "documentReparsingCount",
        "documentDegradedParseCount",
    ]
    .iter()
    .any(|key| {
        supply_quality
            .get(*key)
            .and_then(Value::as_u64)
            .map(|count| count > 0)
            .unwrap_or(false)
    });
    let procedure_question = prompt_requests_procedure_or_action(prompt);
    let no_answerable_supply = status == "empty"
        || quality_status == "missing"
        || (answerable_supply_count == 0 && (supplied_items.is_empty() || has_parse_blocker));
    let weak_but_answerable = answerable_supply_count > 0
        && (has_weak_expansion
            || has_low_text_evidence
            || has_parse_blocker
            || (procedure_question && quality_status == "partial"));
    if !no_answerable_supply && !weak_but_answerable {
        return None;
    }

    let selected_dataset_count = supply_quality
        .get("selectedDatasetCount")
        .and_then(Value::as_u64)
        .unwrap_or_else(|| selected_dataset_ids_from_scope(selected_scope).len() as u64);
    let selected_document_count =
        selected_document_ids_for_evidence_from_scope(selected_scope).len();
    let (trigger, status, question, model_rule) = if no_answerable_supply {
        (
            "no_answerable_supply",
            "needs_user_clarification",
            "当前可见资料里还没定位到可引用内容。请补充制度名称、章节/页码、关键词，或确认本轮要搜索的文档范围；收到补充后，我会沿用本会话继续扩大检索并完成回答。",
            "If the answer cannot be verified from supplied evidence, state the visible status briefly, ask this exact follow-up, and make it clear the same conversation can continue with expanded retrieval.",
        )
    } else if has_low_text_evidence || has_parse_blocker {
        (
            "parse_or_low_text_quality",
            "answer_with_current_evidence_then_followup_if_needed",
            "当前资料存在解析质量或就绪状态风险。请补充清晰文件、制度名称、章节/页码或关键词；我会沿用本会话继续重检索/细读并修正答案。",
            "Give a useful answer from current evidence and general professional knowledge first; clearly mark unverified parts, then ask this follow-up if exact source wording is still needed.",
        )
    } else if assistant_run_prompt_contains_elder_death_followup_signal(prompt) {
        (
            "weak_procedure_evidence_expansion",
            "answer_with_current_evidence_then_followup_if_needed",
            "我可以先按已检索到的突发事件/善后相关章节整理现场处置、家属沟通、上报记录和后续复盘；如需核对原文，请补充制度名称、章节/页码或关键词。",
            "Use the expanded chunks before saying the document lacks a direct section; organize the answer as a procedure, then ask this follow-up only for exact verification.",
        )
    } else if prompt_contains_elder_fall_signal(prompt) {
        (
            "weak_procedure_evidence_expansion",
            "answer_with_current_evidence_then_followup_if_needed",
            "我可以先按已检索到的防跌倒/突发事件相关章节整理现场处置、家属沟通、上报记录和后续复盘；如需核对原文，请补充制度名称、章节/页码或关键词。",
            "Use the expanded chunks before saying the document lacks a direct section; organize the answer as a procedure, then ask this follow-up only for exact verification.",
        )
    } else if procedure_question {
        (
            "weak_procedure_evidence_expansion",
            "answer_with_current_evidence_then_followup_if_needed",
            "我可以先按已检索到的相关章节整理可执行流程；如需核对原文，请补充制度名称、章节/页码或关键词。",
            "Use the expanded chunks before saying the document lacks a direct process; give a procedure-style answer, then ask this follow-up only for exact verification.",
        )
    } else {
        (
            "weak_document_evidence",
            "answer_with_current_evidence_then_followup_if_needed",
            "我可以先按已检索到的资料给出当前结论；如需更准确，请补充文档名称、页码、关键词或统计口径。",
            "Answer with current evidence first; if the requested fact cannot be verified, ask this follow-up instead of ending with a generic unavailable message.",
        )
    };

    Some(json!({
        "status": status,
        "trigger": trigger,
        "question": question,
        "model_rule": model_rule,
        "can_continue_same_conversation": true,
        "next_action": "continue_same_conversation_expanded_retrieval",
        "suggested_user_inputs": [
            "制度名称",
            "章节或页码",
            "关键词",
            "文档范围或数据集分组",
            "统计口径或对象"
        ],
        "prompt_kind": if procedure_question { "procedure_or_action" } else { "data_or_document_question" },
        "scope_summary": {
            "intent": assistant_run_scope_intent(selected_scope),
            "selected_dataset_count": selected_dataset_count,
            "selected_document_count": selected_document_count,
            "unavailable_dataset_count": unavailable_dataset_ids.len(),
            "unavailable_dataset_ids": unavailable_dataset_ids,
        },
        "answerable_supply_count": answerable_supply_count,
        "quality_status": quality_status,
    }))
}

fn assistant_run_supply_has_weak_indexed_evidence_expansion(
    supplied_items: &[Value],
    supply_quality: &Value,
) -> bool {
    supplied_items.iter().any(|item| {
        item.get("source").and_then(Value::as_str) == Some("document_chunk_fallback")
            && item.get("fallback_reason").and_then(Value::as_str)
                == Some("weak_indexed_evidence_expansion")
    }) || assistant_run_supply_quality_has_note(
        supply_quality,
        "supply_selection:weak_indexed_evidence_expanded_with_visible_chunks",
    )
}

fn assistant_run_supply_quality_has_note(supply_quality: &Value, expected: &str) -> bool {
    supply_quality
        .get("notes")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .any(|note| note.as_str() == Some(expected))
}

fn assistant_run_prompt_contains_elder_death_followup_signal(prompt: &str) -> bool {
    prompt_contains_elder_death_signal(prompt)
        || prompt_contains_any(
            prompt,
            &[
                "在院离世",
                "院内离世",
                "长者离世",
                "老人离世",
                "离世善后",
                "身故善后",
                "善后流程",
            ],
        )
}

fn filter_retrieval_evidences_for_selected_documents(
    evidences: Vec<RetrievalEvidence>,
    selected_document_ids: &[DocumentId],
) -> Vec<RetrievalEvidence> {
    if selected_document_ids.is_empty() {
        return evidences;
    }
    evidences
        .into_iter()
        .filter(|evidence| selected_document_ids.contains(&evidence.document_id))
        .collect()
}

fn assistant_run_supply_quality_report(
    selected_scope: &Value,
    supply_requested: bool,
    supplied_items: &[Value],
    supplied_datasets: &[Value],
    supplied_memory_items: &[Value],
    detail_targets: &[Value],
    fallback_supply_count: usize,
    limit: usize,
) -> Value {
    let supplied_item_count = supplied_items.len();
    let indexed_evidence_count = supplied_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str) == Some("retrieval_evidence")
                && item
                    .get("source")
                    .and_then(Value::as_str)
                    .map(|source| source != "document_chunk_fallback")
                    .unwrap_or(true)
        })
        .count();
    let media_context_count = supplied_items
        .iter()
        .filter(|item| item.get("media_context").is_some())
        .count();
    let dataset_entity_scan_count = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("dataset_entity_scan"))
        .count();
    let dataset_fact_snapshot_count = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("dataset_fact_snapshot"))
        .count();
    let spreadsheet_row_analysis_count = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("spreadsheet_row_analysis"))
        .count();
    let document_parse_status_count = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("document_parse_status"))
        .count();
    let document_not_ready_count: usize = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("document_parse_status"))
        .filter_map(|item| item.get("not_ready_document_count").and_then(Value::as_u64))
        .map(|value| value as usize)
        .sum();
    let document_failed_count: usize = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("document_parse_status"))
        .filter_map(|item| item.get("failed_document_count").and_then(Value::as_u64))
        .map(|value| value as usize)
        .sum();
    let document_reparsing_count: usize = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("document_parse_status"))
        .filter_map(|item| item.get("reparsing_document_count").and_then(Value::as_u64))
        .map(|value| value as usize)
        .sum();
    let document_degraded_parse_count: usize = supplied_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("document_parse_status"))
        .filter_map(|item| item.get("degraded_parse_count").and_then(Value::as_u64))
        .map(|value| value as usize)
        .sum();
    let low_text_evidence_count = assistant_run_low_text_evidence_count(supplied_items);
    let citation_locators = assistant_run_supply_citation_locators(supplied_items, 8);
    let prefer_detail = assistant_run_scope_prefers_detail(selected_scope);
    let status = if !supply_requested {
        "not_requested"
    } else if supplied_item_count == 0 {
        "missing"
    } else if document_not_ready_count > 0
        || document_failed_count > 0
        || document_reparsing_count > 0
        || document_degraded_parse_count > 0
        || low_text_evidence_count > 0
        || (prefer_detail && !detail_targets.is_empty())
    {
        "partial"
    } else {
        "grounded"
    };
    let mut notes = Vec::new();
    if !supply_requested {
        notes.push("ordinary_chat_without_forced_supply");
    }
    if indexed_evidence_count > 0 {
        notes.push("indexed_retrieval_evidence_available");
    }
    if fallback_supply_count > 0 {
        notes.push("fallback_visible_document_chunks_used");
    }
    if low_text_evidence_count > 0 {
        notes.push("low_text_document_evidence");
    }
    if !detail_targets.is_empty() {
        notes.push("detail_read_recommended_before_high_confidence_claims");
    }
    if dataset_entity_scan_count > 0 {
        notes.push("dataset_entity_scan_available");
    }
    if dataset_fact_snapshot_count > 0 {
        notes.push("dataset_fact_snapshot_available");
    }
    if spreadsheet_row_analysis_count > 0 {
        notes.push("spreadsheet_row_analysis_available");
    }
    if document_parse_status_count > 0 {
        notes.push("document_parse_status_available");
    }
    if document_not_ready_count > 0 {
        notes.push("some_documents_not_ready_or_reparsing");
    }
    if document_failed_count > 0 {
        notes.push("some_documents_failed_parse");
    }
    if document_reparsing_count > 0 {
        notes.push("document_reparse_in_progress");
    }
    if document_degraded_parse_count > 0 {
        notes.push("some_documents_parse_degraded");
    }
    if media_context_count > 0 {
        notes.push("media_context_available_with_timestamps_when_present");
    }
    if !supplied_memory_items.is_empty() {
        notes.push("conversation_memory_supplied_by_intent");
    }
    if citation_locators.is_empty() && supply_requested {
        notes.push("no_source_locator_available");
    }
    for note in assistant_run_supply_selection_notes(supplied_items) {
        if !notes.contains(&note) {
            notes.push(note);
        }
    }

    json!({
        "status": status,
        "intent": assistant_run_scope_intent(selected_scope),
        "supplyRequested": supply_requested,
        "qualityFirst": assistant_run_scope_prefers_detail(selected_scope)
            || selected_scope_requests_conversation_memory(selected_scope),
        "selectedDatasetCount": supplied_datasets.len(),
        "suppliedItemCount": supplied_item_count,
        "indexedEvidenceCount": indexed_evidence_count,
        "fallbackChunkCount": fallback_supply_count,
        "conversationMemoryItemCount": supplied_memory_items.len(),
        "mediaContextCount": media_context_count,
        "datasetEntityScanCount": dataset_entity_scan_count,
        "datasetFactSnapshotCount": dataset_fact_snapshot_count,
        "spreadsheetRowAnalysisCount": spreadsheet_row_analysis_count,
        "documentParseStatusCount": document_parse_status_count,
        "documentNotReadyCount": document_not_ready_count,
        "documentFailedCount": document_failed_count,
        "documentReparsingCount": document_reparsing_count,
        "documentDegradedParseCount": document_degraded_parse_count,
        "detailTargetCount": detail_targets.len(),
        "limit": limit,
        "citationLocatorCount": citation_locators.len(),
        "citationLocators": citation_locators,
        "notes": notes,
        "modelGuidance": [
            "treat supplied_items as citable context, not an answer template",
            "distinguish supplied document facts from general model knowledge",
            "when dataset_fact_snapshot is present, use it before runtime entity scans or retrieval for dataset-level count/list/rank questions",
            "when dataset_entity_scan contains company_count and company_rows, use those as the authoritative company statistics and do not extend the list from candidate_terms",
            "when dataset_entity_scan contains scanned_document_count, use it as the total scanned document count and do not sum company_rows.document_count as total documents",
            "when spreadsheet_row_analysis is present, use its rows as the deterministic computed table for attendance, work-hour, absence, and date/time row questions",
            "when document_parse_status reports not-ready, failed, reparsing, or degraded documents, tell the user the relevant document is still parsing or failed instead of claiming its contents",
            "fallback_visible_document_chunks_used means indexed retrieval was expanded with visible document chunks; do not describe that as parser-not-ready unless document_parse_status or low_text_document_evidence says so",
            "when fallback_reason is weak_indexed_evidence_expansion, use those expanded chunks before saying the document did not directly mention the requested flow",
            "when evidence_state.recovery_followup is present, answer with current evidence first; if still unverifiable, ask that follow-up and keep the task continuable in the same conversation",
            "when low_text_document_evidence is present, treat the document extraction as too sparse or low quality, avoid inferring contents from the title, and recommend OCR/reparse/manual review if needed",
            "read detail_targets before asserting exact source wording, tables, OCR, or media timestamps"
        ],
    })
}

fn assistant_run_supply_selection_notes(supplied_items: &[Value]) -> Vec<&'static str> {
    let mut notes = Vec::new();
    let mut has_dataset_fact_snapshot = false;
    let mut has_scoped_fact_snapshot = false;
    let mut has_dataset_entity_scan = false;
    let mut has_spreadsheet_row_analysis = false;
    let mut has_weak_evidence_expansion = false;

    for item in supplied_items {
        match item.get("type").and_then(Value::as_str) {
            Some("dataset_fact_snapshot") => {
                has_dataset_fact_snapshot = true;
                if item.get("source").and_then(Value::as_str)
                    == Some("document_facts_scoped_aggregate")
                {
                    has_scoped_fact_snapshot = true;
                }
            }
            Some("dataset_entity_scan") => {
                has_dataset_entity_scan = true;
            }
            Some("spreadsheet_row_analysis") => {
                has_spreadsheet_row_analysis = true;
            }
            _ => {}
        }
        if item.get("source").and_then(Value::as_str) == Some("document_chunk_fallback")
            && item.get("fallback_reason").and_then(Value::as_str)
                == Some("weak_indexed_evidence_expansion")
        {
            has_weak_evidence_expansion = true;
        }
    }

    if has_scoped_fact_snapshot {
        notes.push(
            "supply_selection:document_facts_scoped_aggregate_selected_for_scoped_document_aggregate",
        );
    } else if has_dataset_fact_snapshot {
        notes
            .push("supply_selection:dataset_fact_snapshot_selected_for_dataset_aggregate_question");
    }

    if has_dataset_entity_scan {
        if has_dataset_fact_snapshot {
            notes.push(
                "supply_selection:dataset_entity_scan_kept_for_dimensions_not_covered_by_snapshot",
            );
        } else {
            notes.push(
                "supply_selection:dataset_entity_scan_selected_when_snapshot_missing_or_runtime_scan_needed",
            );
        }
    }

    if has_spreadsheet_row_analysis {
        notes.push(
            "supply_selection:spreadsheet_row_analysis_selected_for_attendance_or_workhour_table_question",
        );
    }

    if has_weak_evidence_expansion {
        notes.push("supply_selection:weak_indexed_evidence_expanded_with_visible_chunks");
    }

    notes
}

fn assistant_run_low_text_evidence_count(supplied_items: &[Value]) -> usize {
    supplied_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str) == Some("retrieval_evidence")
                && item.get("source").and_then(Value::as_str) != Some("document_chunk_fallback")
        })
        .filter(|item| {
            let excerpt = item
                .get("content_excerpt")
                .and_then(Value::as_str)
                .or_else(|| item.get("summary").and_then(Value::as_str))
                .unwrap_or_default();
            let signal_chars = excerpt.chars().filter(|ch| !ch.is_whitespace()).count();
            signal_chars > 0 && signal_chars < 20
        })
        .count()
}

fn assistant_run_supply_citation_locators(items: &[Value], limit: usize) -> Vec<String> {
    let mut locators = Vec::new();
    let mut seen = BTreeSet::new();
    for item in items {
        let Some(locator) = item
            .get("source_locator")
            .or_else(|| item.get("sourceLocator"))
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        if seen.insert(locator.to_string()) {
            locators.push(locator.to_string());
        }
        if locators.len() >= limit {
            break;
        }
    }
    locators
}

#[cfg(test)]
fn assistant_run_evidence_limit_for_scope(selected_scope: &Value) -> usize {
    assistant_run_evidence_limit_for_scope_and_prompt(selected_scope, "")
}

fn assistant_run_evidence_limit_for_scope_and_prompt(
    selected_scope: &Value,
    prompt: &str,
) -> usize {
    if !selected_document_ids_for_evidence_from_scope(selected_scope).is_empty()
        && prompt_requests_spreadsheet_row_level_analysis(prompt)
        && !prompt_has_resume_signal(prompt)
    {
        return ASSISTANT_RUN_SELECTED_DOCUMENT_ROW_EVIDENCE_LIMIT;
    }
    if assistant_run_scope_prefers_detail(selected_scope)
        && !selected_dataset_ids_from_scope(selected_scope).is_empty()
    {
        ASSISTANT_RUN_EVIDENCE_MAX_LIMIT
    } else {
        assistant_run_evidence_limit()
    }
}

fn assistant_run_evidence_limit() -> usize {
    std::env::var("ASSISTANT_RUN_EVIDENCE_LIMIT")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(ASSISTANT_RUN_EVIDENCE_DEFAULT_LIMIT)
        .clamp(1, ASSISTANT_RUN_EVIDENCE_MAX_LIMIT)
}

fn assistant_run_recommended_supply_actions(
    selected_scope: &Value,
    has_supplied_items: bool,
    dataset_entity_scan_requested: bool,
) -> Vec<&'static str> {
    let mut actions = Vec::new();
    let recommended_tool_actions = assistant_run_scope_recommended_tool_actions(selected_scope);
    if !selected_dataset_ids_from_scope(selected_scope).is_empty() {
        actions.push("retrieve_evidence");
        if assistant_run_scope_prefers_detail(selected_scope) && has_supplied_items {
            actions.push("read_document_detail");
        }
        if dataset_entity_scan_requested {
            actions.push("scan_dataset_entities");
        }
    }
    if selected_scope_requests_conversation_memory(selected_scope) {
        actions.push("recall_conversation_memory");
    }
    match assistant_run_scope_intent(selected_scope) {
        "static_page" => actions.push("create_static_page_draft"),
        "report" => actions.push("list_report_options"),
        _ => {}
    }
    if recommended_tool_actions
        .iter()
        .any(|action| action == "media.resolve_video_url")
    {
        actions.push("resolve_video_url");
    }
    if recommended_tool_actions
        .iter()
        .any(|action| action == "media.extract_ppt_transcript")
    {
        actions.push("extract_video_ppt_transcript");
    }
    actions
}

fn assistant_run_fallback_supply_count(supplied_items: &[Value]) -> usize {
    supplied_items
        .iter()
        .filter(|item| {
            item.get("source")
                .and_then(Value::as_str)
                .is_some_and(|source| source == "document_chunk_fallback")
        })
        .count()
}

fn document_chunk_fallback_source_locator(document: &Document, chunk: &DocumentChunk) -> String {
    let base = if document.object_key.trim().is_empty() {
        document.title.trim()
    } else {
        document.object_key.trim()
    };
    format!("{}#chunk={}", base, chunk.chunk_index)
}

fn document_chunk_fallback_summary(document: &Document, chunk: &DocumentChunk) -> String {
    let title = if document.title.trim().is_empty() {
        document.object_key.trim()
    } else {
        document.title.trim()
    };
    let section = document_chunk_section_title_hints(chunk)
        .first()
        .map(|value| format!(" / {value}"))
        .unwrap_or_default();
    let excerpt = truncate_assistant_supply_text(&chunk.content, 180);
    if excerpt.is_empty() {
        format!("{title} chunk {}{section}", chunk.chunk_index)
    } else {
        format!("{title} chunk {}{section}: {excerpt}", chunk.chunk_index)
    }
}

fn document_chunk_search_text(document: &Document, chunk: &DocumentChunk) -> String {
    let section_title_hints = document_chunk_section_title_hints(chunk).join("\n");
    let noun_terms = document_chunk_noun_terms(chunk).join("\n");
    [
        document.title.trim(),
        document.object_key.trim(),
        section_title_hints.trim(),
        noun_terms.trim(),
        chunk.content.trim(),
    ]
    .into_iter()
    .filter(|value| !value.is_empty())
    .collect::<Vec<_>>()
    .join("\n")
}

fn document_chunk_section_title_hints(chunk: &DocumentChunk) -> Vec<String> {
    let mut hints = Vec::new();
    for key in [
        "section_title_hints",
        "sectionTitleHints",
        "section_titles",
        "sectionTitles",
        "heading_hints",
        "headingHints",
    ] {
        if let Some(value) = chunk.metadata.get(key) {
            collect_string_list(value, &mut hints);
        }
    }
    if let Some(value) = chunk
        .metadata
        .get("parse_metadata")
        .and_then(|value| value.get("section_title_hints"))
    {
        collect_string_list(value, &mut hints);
    }
    if let Some(value) = chunk
        .metadata
        .get("parse_metadata")
        .and_then(|value| value.get("document_structure"))
    {
        for hint in document_structure_section_title_hints(value, 6) {
            push_string_hint(&mut hints, hint);
        }
    }
    if let Some(value) = chunk.metadata.get("understanding").and_then(|value| {
        value
            .get("section_title_hints")
            .or_else(|| value.get("sectionTitleHints"))
    }) {
        collect_string_list(value, &mut hints);
    }
    if hints.is_empty() {
        for hint in infer_section_title_hints_from_text(&chunk.content, 6) {
            push_string_hint(&mut hints, hint);
        }
    }
    hints.truncate(6);
    hints
}

fn document_chunk_value_section_title_hints(
    metadata: &Value,
    content: &str,
    limit: usize,
) -> Vec<String> {
    let mut hints = Vec::new();
    for key in [
        "section_title_hints",
        "sectionTitleHints",
        "section_titles",
        "sectionTitles",
        "heading_hints",
        "headingHints",
    ] {
        if let Some(value) = metadata.get(key) {
            collect_string_list(value, &mut hints);
        }
    }
    if let Some(value) = metadata
        .get("parse_metadata")
        .and_then(|value| value.get("section_title_hints"))
    {
        collect_string_list(value, &mut hints);
    }
    if let Some(value) = metadata
        .get("parse_metadata")
        .and_then(|value| value.get("document_structure"))
    {
        for hint in document_structure_section_title_hints(value, limit) {
            push_string_hint(&mut hints, hint);
        }
    }
    if let Some(value) = metadata.get("understanding").and_then(|value| {
        value
            .get("section_title_hints")
            .or_else(|| value.get("sectionTitleHints"))
    }) {
        collect_string_list(value, &mut hints);
    }
    if hints.is_empty() {
        for hint in infer_section_title_hints_from_text(content, limit) {
            push_string_hint(&mut hints, hint);
        }
    }
    hints.truncate(limit);
    hints
}

fn document_chunk_noun_terms(chunk: &DocumentChunk) -> Vec<String> {
    let mut terms = Vec::new();
    if let Some(value) = chunk
        .metadata
        .get("understanding")
        .and_then(|value| value.get("noun_terms").or_else(|| value.get("nounTerms")))
    {
        collect_string_list(value, &mut terms);
    }
    for key in ["noun_terms", "nounTerms", "term_hints", "termHints"] {
        if let Some(value) = chunk.metadata.get(key) {
            collect_string_list(value, &mut terms);
        }
    }
    if let Some(value) = chunk
        .metadata
        .get("parse_metadata")
        .and_then(|value| value.get("document_structure"))
    {
        for term in document_structure_candidate_terms(value, 64) {
            push_string_hint(&mut terms, term);
        }
    }
    terms.truncate(64);
    terms
}

fn document_chunk_value_noun_terms(metadata: &Value) -> Vec<String> {
    let mut terms = Vec::new();
    if let Some(value) = metadata
        .get("understanding")
        .and_then(|value| value.get("noun_terms").or_else(|| value.get("nounTerms")))
    {
        collect_string_list(value, &mut terms);
    }
    for key in ["noun_terms", "nounTerms", "term_hints", "termHints"] {
        if let Some(value) = metadata.get(key) {
            collect_string_list(value, &mut terms);
        }
    }
    if let Some(value) = metadata
        .get("parse_metadata")
        .and_then(|value| value.get("document_structure"))
    {
        for term in document_structure_candidate_terms(value, 64) {
            push_string_hint(&mut terms, term);
        }
    }
    terms.truncate(64);
    terms
}

fn document_structure_section_title_hints(structure: &Value, limit: usize) -> Vec<String> {
    let mut hints = Vec::new();
    let Some(blocks) = structure.get("blocks").and_then(Value::as_array) else {
        return hints;
    };
    for block in blocks {
        if !document_structure_block_is_title(block) {
            continue;
        }
        let Some(text) = document_structure_block_text(block) else {
            continue;
        };
        let title = normalize_section_title_hint(&text).unwrap_or_else(|| {
            text.trim()
                .chars()
                .take(80)
                .collect::<String>()
                .trim()
                .to_string()
        });
        push_string_hint(&mut hints, title);
        if hints.len() >= limit {
            break;
        }
    }
    hints
}

fn document_structure_candidate_terms(structure: &Value, limit: usize) -> Vec<String> {
    let mut terms = Vec::new();
    let Some(blocks) = structure.get("blocks").and_then(Value::as_array) else {
        return terms;
    };
    for block in blocks {
        if !document_structure_block_is_term_source(block) {
            continue;
        }
        let Some(text) = document_structure_block_text(block) else {
            continue;
        };
        push_string_hint(&mut terms, &text);
        for token in lexical_query_tokens(&text) {
            if token.chars().count() >= 2 && token.chars().count() <= 16 {
                push_string_hint(&mut terms, token);
            }
            if terms.len() >= limit {
                return terms;
            }
        }
        if terms.len() >= limit {
            break;
        }
    }
    terms
}

fn document_structure_block_text(block: &Value) -> Option<String> {
    for key in ["text", "content", "rec_text", "markdown", "html"] {
        let Some(text) = block.get(key).and_then(Value::as_str) else {
            continue;
        };
        let normalized = text.trim();
        if !normalized.is_empty() {
            return Some(normalized.chars().take(240).collect());
        }
    }
    None
}

fn document_structure_block_type(block: &Value) -> String {
    for key in ["block_type", "type", "label", "category"] {
        let Some(value) = block.get(key).and_then(Value::as_str) else {
            continue;
        };
        let normalized = value.trim().to_ascii_lowercase();
        if !normalized.is_empty() {
            return normalized;
        }
    }
    String::new()
}

fn document_structure_block_is_title(block: &Value) -> bool {
    let block_type = document_structure_block_type(block);
    [
        "doc_title",
        "paragraph_title",
        "title",
        "header",
        "heading",
        "section_title",
    ]
    .iter()
    .any(|value| block_type.contains(value))
}

fn document_structure_block_is_term_source(block: &Value) -> bool {
    if document_structure_block_is_title(block) {
        return true;
    }
    let block_type = document_structure_block_type(block);
    ["table", "cell", "table_title", "figure_title", "caption"]
        .iter()
        .any(|value| block_type.contains(value))
}

fn collect_string_list(value: &Value, output: &mut Vec<String>) {
    match value {
        Value::String(text) => {
            push_string_hint(output, text);
        }
        Value::Array(items) => {
            for item in items {
                collect_string_list(item, output);
            }
        }
        _ => {}
    }
}

fn push_string_hint(output: &mut Vec<String>, text: impl AsRef<str>) {
    let normalized = text.as_ref().trim().chars().take(80).collect::<String>();
    if !normalized.is_empty() && !output.iter().any(|existing| existing == &normalized) {
        output.push(normalized);
    }
}

fn infer_section_title_hints_from_text(text: &str, limit: usize) -> Vec<String> {
    let mut hints = Vec::new();
    for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
        if let Some(title) = normalize_section_title_hint(line) {
            if !hints.contains(&title) {
                hints.push(title);
            }
            if hints.len() >= limit {
                break;
            }
        }
    }
    hints
}

fn normalize_section_title_hint(line: &str) -> Option<String> {
    let trimmed = line.trim().trim_matches(|ch: char| ch == '*' || ch == '`');
    if trimmed.is_empty() {
        return None;
    }
    let candidate = trimmed
        .strip_prefix('#')
        .map(|value| value.trim_start_matches('#').trim())
        .or_else(|| {
            if let Some((index, _)) = trimmed
                .char_indices()
                .find(|(_, value)| value.is_whitespace())
            {
                let marker = trimmed[..index].trim();
                if marker.chars().count() <= 12 && looks_like_heading_marker(marker) {
                    return Some(trimmed[index..].trim());
                }
            }
            let marker_end = trimmed
                .char_indices()
                .find_map(|(index, value)| {
                    if matches!(value, '、' | '.' | '．' | ')' | '）' | ':' | '：') {
                        Some(index + value.len_utf8())
                    } else {
                        None
                    }
                })
                .filter(|index| *index <= 12)?;
            let marker = trimmed[..marker_end].trim();
            looks_like_heading_marker(marker).then(|| trimmed[marker_end..].trim())
        })
        .or_else(|| {
            (trimmed.starts_with('第')
                && trimmed
                    .chars()
                    .take(8)
                    .any(|value| value == '章' || value == '节'))
            .then_some(trimmed)
        })
        .or_else(|| looks_like_standalone_heading(trimmed).then_some(trimmed))?;
    let normalized = normalize_toc_section_title_candidate(candidate)
        .trim_matches(|ch: char| ch.is_whitespace() || "#*-_".contains(ch))
        .chars()
        .take(80)
        .collect::<String>();
    (!normalized.is_empty()).then_some(normalized)
}

fn normalize_toc_section_title_candidate(candidate: &str) -> String {
    let mut value = candidate.trim().to_string();
    if let Some(index) = value.find("....") {
        value.truncate(index);
    } else if let Some(index) = value.find('…') {
        value.truncate(index);
    }
    value
        .trim_matches(|ch: char| {
            ch.is_whitespace()
                || matches!(ch, '.' | '．' | '。' | '·' | '•' | '-' | '_' | '—' | '–')
        })
        .to_string()
}

fn looks_like_heading_marker(value: &str) -> bool {
    value.chars().any(|ch| ch.is_ascii_digit())
        || value.chars().any(|ch| "一二三四五六七八九十".contains(ch))
}

fn looks_like_standalone_heading(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 2
        && char_count <= 32
        && !value.ends_with('。')
        && !value.ends_with('！')
        && !value.ends_with('？')
        && !value.ends_with(';')
        && !value.ends_with('；')
        && !value.contains('|')
}

fn truncate_assistant_supply_text(value: &str, max_chars: usize) -> String {
    value
        .trim()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .take(max_chars)
        .collect()
}

async fn assistant_run_retrieval_supply_excerpt(
    state: &AppState,
    evidence: &RetrievalEvidence,
    prompt: &str,
    chunk_cache: &mut HashMap<DocumentId, Vec<DocumentChunk>>,
) -> std::result::Result<String, ApiError> {
    if !chunk_cache.contains_key(&evidence.document_id) {
        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, evidence.document_id)
            .await
            .map_err(ApiError::from_storage)?;
        chunk_cache.insert(evidence.document_id, chunks);
    }

    let Some(chunks) = chunk_cache.get(&evidence.document_id) else {
        return Ok(evidence.content_excerpt.clone());
    };
    let Some(chunk) = chunks
        .iter()
        .find(|chunk| chunk.id == evidence.document_chunk_id)
        .or_else(|| {
            chunks
                .iter()
                .find(|chunk| chunk.chunk_index == evidence.chunk_index)
        })
    else {
        return Ok(evidence.content_excerpt.clone());
    };

    let excerpt = assistant_run_query_centered_supply_excerpt(
        &chunk.content,
        prompt,
        ASSISTANT_RUN_RETRIEVAL_SUPPLY_EXCERPT_CHARS,
    );
    if excerpt.trim().is_empty() {
        Ok(evidence.content_excerpt.clone())
    } else {
        Ok(excerpt)
    }
}

fn assistant_run_query_centered_supply_excerpt(
    content: &str,
    prompt: &str,
    max_chars: usize,
) -> String {
    let normalized = content
        .trim()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    let total_chars = normalized.chars().count();
    if total_chars <= max_chars {
        return normalized;
    }

    let start = assistant_run_prompt_match_char_index(&normalized, prompt)
        .map(|index| index.saturating_sub(max_chars / 4))
        .unwrap_or(0);
    let mut excerpt = normalized
        .chars()
        .skip(start)
        .take(max_chars)
        .collect::<String>();
    if start > 0 {
        excerpt = format!("...{excerpt}");
    }
    if start + max_chars < total_chars {
        excerpt.push_str("...");
    }
    excerpt
}

fn assistant_run_prompt_match_char_index(content: &str, prompt: &str) -> Option<usize> {
    let content_lower = content.to_lowercase();
    let mut tokens = lexical_query_tokens(prompt)
        .into_iter()
        .filter(|token| token.chars().count() >= 2)
        .collect::<Vec<_>>();
    tokens.sort_by(|left, right| {
        right
            .chars()
            .count()
            .cmp(&left.chars().count())
            .then_with(|| left.cmp(right))
    });
    tokens.dedup();
    tokens.into_iter().find_map(|token| {
        let token_lower = token.to_lowercase();
        content_lower
            .find(&token_lower)
            .map(|byte_index| content_lower[..byte_index].chars().count())
    })
}

fn assistant_run_detail_targets_for_scope(
    selected_scope: &Value,
    supplied_items: &[Value],
) -> Vec<Value> {
    if !assistant_run_scope_prefers_detail(selected_scope) {
        return Vec::new();
    }

    let mut seen_documents = HashSet::new();
    supplied_items
        .iter()
        .filter(|item| {
            item.get("type")
                .and_then(Value::as_str)
                .is_some_and(|item_type| item_type == "retrieval_evidence")
        })
        .filter_map(|item| {
            let document_id = item.get("document_id").or_else(|| item.get("documentId"))?;
            let document_key = document_id
                .as_str()
                .map(ToString::to_string)
                .unwrap_or_else(|| document_id.to_string());
            if document_key.trim().is_empty() || !seen_documents.insert(document_key) {
                return None;
            }

            let media_context = item
                .get("media_context")
                .or_else(|| item.get("mediaContext"));
            let has_media_context = media_context.is_some_and(Value::is_object);
            let has_timestamped_evidence = media_context
                .and_then(|context| context.get("has_timestamped_evidence"))
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let reason = if has_timestamped_evidence {
                "timestamped_media_detail_available"
            } else if has_media_context {
                "media_detail_available"
            } else {
                "detail_first_scope"
            };

            let mut target = Map::new();
            target.insert("type".to_string(), json!("document_detail_target"));
            for key in [
                "dataset_id",
                "datasetId",
                "document_id",
                "documentId",
                "retrieval_evidence_id",
                "retrievalEvidenceId",
                "chunk_index",
                "chunkIndex",
                "source_locator",
                "sourceLocator",
            ] {
                if let Some(value) = item.get(key).filter(|value| !value.is_null()) {
                    target.insert(key.to_string(), value.clone());
                }
            }
            target.insert("reason".to_string(), json!(reason));
            target.insert("has_media_context".to_string(), json!(has_media_context));
            target.insert(
                "has_timestamped_evidence".to_string(),
                json!(has_timestamped_evidence),
            );
            Some(Value::Object(target))
        })
        .take(ASSISTANT_RUN_DETAIL_TARGET_LIMIT)
        .collect()
}

async fn assistant_run_media_context_for_document(
    state: &AppState,
    document_id: DocumentId,
    cache: &mut HashMap<DocumentId, Option<Value>>,
) -> std::result::Result<Option<Value>, ApiError> {
    if let Some(cached) = cache.get(&document_id) {
        return Ok(cached.clone());
    }

    let chunks = state
        .storage
        .document_chunks()
        .list_by_document(state.tenant_id, document_id)
        .await
        .map_err(ApiError::from_storage)?;
    let context = extract_media_metadata_from_chunks(&chunks)
        .as_ref()
        .and_then(build_assistant_run_media_supply_context);
    cache.insert(document_id, context.clone());
    Ok(context)
}

fn build_assistant_run_media_supply_context(raw_media_metadata: &Value) -> Option<Value> {
    let media_kind = raw_media_metadata
        .get("kind")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let parse_status = raw_media_metadata
        .get("parse_status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let transcript_windows = collect_media_transcript_segments(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let scene_windows = collect_media_scenes(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let keyframe_ocr_snippets = collect_media_ocr_snippets(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let provider_evidence = collect_media_provider_evidence(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let has_timestamped_evidence = !transcript_windows.is_empty()
        || !scene_windows.is_empty()
        || !keyframe_ocr_snippets.is_empty();
    let has_context = has_timestamped_evidence
        || !provider_evidence.is_empty()
        || !matches!(media_kind, "unknown" | "");
    if !has_context {
        return None;
    }

    Some(json!({
        "media_kind": media_kind,
        "parse_status": parse_status,
        "has_timestamped_evidence": has_timestamped_evidence,
        "transcript_windows": transcript_windows,
        "scene_windows": scene_windows,
        "keyframe_ocr_snippets": keyframe_ocr_snippets,
        "provider_evidence": provider_evidence,
    }))
}

fn assistant_run_artifact_scope_candidates(
    client_candidates: &[Value],
    current_artifact: Option<&Value>,
) -> Vec<Value> {
    let Some(current_artifact) = current_artifact else {
        return Vec::new();
    };
    let Some(artifact_id) = static_page_artifact_id(current_artifact) else {
        return Vec::new();
    };
    let client_static_page_candidate = client_candidates.iter().find(|candidate| {
        candidate.get("type").and_then(Value::as_str) == Some("static_page_draft")
            && candidate.get("id").and_then(Value::as_str) == Some(artifact_id.as_str())
    });
    let label = static_page_artifact_label(current_artifact)
        .or_else(|| {
            client_static_page_candidate
                .and_then(|candidate| candidate.get("label"))
                .and_then(Value::as_str)
                .map(truncate_scope_candidate_text)
        })
        .unwrap_or_else(|| "当前静态页草稿".to_string());

    vec![json!({
        "type": "static_page_draft",
        "id": artifact_id,
        "label": label,
        "status": static_page_artifact_string(current_artifact, &["status", "backendStatus", "backend_status"]).unwrap_or_default(),
        "styleDirection": static_page_artifact_string(current_artifact, &["styleDirection", "style_direction"]).unwrap_or_default(),
        "moduleCount": static_page_artifact_module_count(current_artifact),
        "previewStatus": static_page_artifact_preview_status(current_artifact).unwrap_or_default(),
        "finalRenderStatus": static_page_artifact_final_status(current_artifact).unwrap_or_default(),
        "previewStale": static_page_artifact_preview_stale(current_artifact),
        "confidence": "high",
        "reason": "当前主区域打开了静态页草稿",
        "source": "active_artifact",
    })]
}

fn assistant_run_scope_with_current_artifact_context(
    selected_scope: Value,
    current_artifact: Option<&Value>,
    prompt: &str,
) -> Value {
    let Some(current_artifact) = current_artifact else {
        return selected_scope;
    };
    if !assistant_run_is_static_page_artifact(current_artifact) {
        return selected_scope;
    }
    let current_intent = assistant_run_scope_intent(&selected_scope);
    if current_intent != "static_page" && !prompt_touches_current_static_page_artifact(prompt) {
        return selected_scope;
    }

    let mut selected_scope = selected_scope;
    ensure_json_object(&mut selected_scope);
    let has_dataset = !selected_dataset_ids_from_scope(&selected_scope).is_empty();
    let has_memory = selected_scope_requests_conversation_memory(&selected_scope);
    if let Some(object) = selected_scope.as_object_mut() {
        object.insert("intent".to_string(), json!("static_page"));
        object.insert(
            "supply_policy".to_string(),
            assistant_run_active_static_page_supply_policy(has_dataset, has_memory),
        );
    }
    selected_scope
}

fn assistant_run_scope_with_requested_document_scope(
    mut selected_scope: Value,
    requested_scope: Option<&Value>,
) -> Value {
    let Some(requested_scope) = requested_scope else {
        return selected_scope;
    };
    let requested_dataset_ids = selected_dataset_ids_from_scope(requested_scope);
    if !selected_scope_has_document_selection(requested_scope) && requested_dataset_ids.is_empty() {
        return selected_scope;
    }

    ensure_json_object(&mut selected_scope);
    if !requested_dataset_ids.is_empty() {
        if let Some(datasets) = requested_scope.get("datasets").cloned() {
            set_payload_value(&mut selected_scope, "datasets", datasets);
        }
    } else if selected_dataset_ids_from_scope(&selected_scope).is_empty() {
        if let Some(datasets) = requested_scope.get("datasets").cloned() {
            set_payload_value(&mut selected_scope, "datasets", datasets);
        }
    }
    if let Some(mode) = requested_scope.get("mode").cloned() {
        set_payload_value(&mut selected_scope, "mode", mode);
    }
    if let Some(intent) = requested_scope.get("intent").cloned() {
        set_payload_value(&mut selected_scope, "intent", intent);
    }
    if let Some(supply_policy) = requested_scope
        .get("supply_policy")
        .or_else(|| requested_scope.get("supplyPolicy"))
        .cloned()
    {
        set_payload_value(&mut selected_scope, "supply_policy", supply_policy);
    } else if !requested_dataset_ids.is_empty() {
        set_payload_value(
            &mut selected_scope,
            "supply_policy",
            assistant_run_requested_dataset_supply_policy(assistant_run_scope_intent(
                requested_scope,
            )),
        );
    }
    for key in [
        "type",
        "platform",
        "documents",
        "selected",
        "canonical_datasets",
        "temporary_dataset",
        "dataset_document_scope",
        "source_document_scope",
        "available_document_source_id",
        "available_document_external_ids",
        "unresolved_document_external_ids",
        "external_document_scope_status",
        "external_document_scope_summary",
        "dataset_external_id",
        "dataset_external_ids",
        "requested_dataset_external_id",
        "requested_dataset_external_ids",
        "conversation_external_id",
        "channel_connection_id",
        "tenant_external_id",
        "bot_external_id",
        "sender_external_id",
        "message_external_id",
        "v3_system_user_id",
        "answer_policy",
    ] {
        if let Some(value) = requested_scope.get(key).cloned() {
            set_payload_value(&mut selected_scope, key, value);
        }
    }
    selected_scope
}

fn assistant_run_scope_with_visible_dataset_range(
    mut selected_scope: Value,
    visible_datasets: &[Dataset],
    prompt: &str,
) -> Value {
    if assistant_run_scope_is_external_channel(Some(&selected_scope))
        || selected_scope_has_document_selection(&selected_scope)
    {
        return selected_scope;
    }
    if assistant_run_scope_intent(&selected_scope) == "ordinary_chat" {
        return assistant_run_scope_without_unavailable_requested_datasets(
            selected_scope,
            visible_datasets,
        );
    }

    let visible_by_id = visible_datasets
        .iter()
        .map(|dataset| (dataset.id, dataset))
        .collect::<HashMap<_, _>>();
    if visible_by_id.is_empty() {
        return selected_scope;
    }

    let requested_dataset_ids = selected_dataset_ids_from_scope(&selected_scope);
    let mut seen = HashSet::new();
    let mut ordered_dataset_ids = Vec::new();
    let mut visible_requested_dataset_ids = Vec::new();
    let mut unavailable_requested_dataset_ids = Vec::new();
    let mut prompt_matched_datasets = visible_datasets
        .iter()
        .map(|dataset| {
            (
                dataset,
                assistant_dataset_prompt_match_score(dataset, prompt),
            )
        })
        .filter(|(dataset, score)| *score > 0 && dataset_has_assistant_supply_hint(dataset))
        .collect::<Vec<_>>();
    prompt_matched_datasets.sort_by(|(left_dataset, left_score), (right_dataset, right_score)| {
        right_score
            .cmp(left_score)
            .then_with(|| right_dataset.updated_at.cmp(&left_dataset.updated_at))
    });

    for dataset_id in &requested_dataset_ids {
        if visible_by_id.contains_key(dataset_id) {
            visible_requested_dataset_ids.push(*dataset_id);
        } else {
            unavailable_requested_dataset_ids.push(dataset_id.to_string());
        }
    }

    for dataset_id in &visible_requested_dataset_ids {
        if visible_by_id.get(dataset_id).is_some_and(|dataset| {
            dataset_has_assistant_supply_hint(dataset)
                && assistant_dataset_prompt_match_score(dataset, prompt) > 0
        }) && seen.insert(*dataset_id)
        {
            ordered_dataset_ids.push(*dataset_id);
        }
    }
    for (dataset, _) in &prompt_matched_datasets {
        if seen.insert(dataset.id) {
            ordered_dataset_ids.push(dataset.id);
        }
    }
    for dataset in visible_datasets {
        if dataset_has_assistant_supply_hint(dataset) && seen.insert(dataset.id) {
            ordered_dataset_ids.push(dataset.id);
        }
    }
    for dataset_id in &visible_requested_dataset_ids {
        if seen.insert(*dataset_id) {
            ordered_dataset_ids.push(*dataset_id);
        }
    }
    for dataset in visible_datasets {
        if seen.insert(dataset.id) {
            ordered_dataset_ids.push(dataset.id);
        }
    }

    if ordered_dataset_ids.is_empty() {
        return selected_scope;
    }

    let dataset_scope = ordered_dataset_ids
        .iter()
        .map(|dataset_id| json!({"type": "dataset", "id": dataset_id}))
        .collect::<Vec<_>>();
    set_payload_value(&mut selected_scope, "datasets", json!(dataset_scope));
    set_payload_value(&mut selected_scope, "selected", json!(dataset_scope));
    set_payload_value(
        &mut selected_scope,
        "preferred_dataset_ids",
        json!(visible_requested_dataset_ids
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()),
    );
    set_payload_value(
        &mut selected_scope,
        "dataset_scope_policy",
        json!("all_visible_datasets_with_preselection_priority"),
    );
    if !unavailable_requested_dataset_ids.is_empty() {
        set_payload_value(
            &mut selected_scope,
            "ignored_dataset_ids",
            json!(unavailable_requested_dataset_ids),
        );
    }

    let mut supply_policy = assistant_run_scope_supply_policy(&selected_scope);
    ensure_json_object(&mut supply_policy);
    if let Some(policy) = supply_policy.as_object_mut() {
        policy.insert(
            "candidatePolicy".to_string(),
            json!("all_visible_datasets_with_preselection_priority"),
        );
        policy.insert("retrievalPolicy".to_string(), json!("standard"));
        policy.insert("noFakeData".to_string(), json!(true));
        if policy
            .get("recommendedActions")
            .and_then(Value::as_array)
            .map(|actions| actions.is_empty())
            .unwrap_or(true)
        {
            policy.insert(
                "recommendedActions".to_string(),
                json!(["retrieval.search"]),
            );
        }
    }
    set_payload_value(&mut selected_scope, "supply_policy", supply_policy);
    selected_scope
}

fn assistant_run_scope_without_unavailable_requested_datasets(
    mut selected_scope: Value,
    visible_datasets: &[Dataset],
) -> Value {
    let requested_dataset_ids = selected_dataset_ids_from_scope(&selected_scope);
    if requested_dataset_ids.is_empty() {
        return selected_scope;
    }
    let visible_dataset_ids = visible_datasets
        .iter()
        .map(|dataset| dataset.id)
        .collect::<HashSet<_>>();
    let mut visible_requested_dataset_ids = Vec::new();
    let mut unavailable_requested_dataset_ids = Vec::new();
    for dataset_id in requested_dataset_ids {
        if visible_dataset_ids.contains(&dataset_id) {
            visible_requested_dataset_ids.push(dataset_id);
        } else {
            unavailable_requested_dataset_ids.push(dataset_id.to_string());
        }
    }
    if unavailable_requested_dataset_ids.is_empty() {
        return selected_scope;
    }

    let dataset_scope = visible_requested_dataset_ids
        .iter()
        .map(|dataset_id| json!({"type": "dataset", "id": dataset_id}))
        .collect::<Vec<_>>();
    set_payload_value(&mut selected_scope, "datasets", json!(dataset_scope));
    set_payload_value(&mut selected_scope, "selected", json!(dataset_scope));
    set_payload_value(
        &mut selected_scope,
        "preferred_dataset_ids",
        json!(visible_requested_dataset_ids
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()),
    );
    set_payload_value(
        &mut selected_scope,
        "ignored_dataset_ids",
        json!(unavailable_requested_dataset_ids),
    );
    set_payload_value(
        &mut selected_scope,
        "dataset_scope_policy",
        json!("requested_visible_datasets_only"),
    );
    if visible_requested_dataset_ids.is_empty()
        && !selected_scope_requests_conversation_memory(&selected_scope)
    {
        set_payload_value(&mut selected_scope, "mode", json!("ordinary_chat"));
    }

    let mut supply_policy = assistant_run_scope_supply_policy(&selected_scope);
    ensure_json_object(&mut supply_policy);
    if let Some(policy) = supply_policy.as_object_mut() {
        policy.insert(
            "candidatePolicy".to_string(),
            json!("requested_visible_datasets_only"),
        );
        policy.insert("retrievalPolicy".to_string(), json!("standard"));
        policy.insert("noFakeData".to_string(), json!(true));
    }
    set_payload_value(&mut selected_scope, "supply_policy", supply_policy);
    selected_scope
}

fn dataset_has_assistant_supply_hint(dataset: &Dataset) -> bool {
    dataset_metadata_usize_optional(
        dataset,
        &[
            "document_count",
            "documentCount",
            "documents_count",
            "documentsCount",
            "estimated_word_count",
            "estimatedWordCount",
            "database_source_count",
            "databaseSourceCount",
        ],
    )
    .is_some_and(|value| value > 0)
        || [
            "database_sources",
            "databaseSources",
            "database_source_ids",
            "databaseSourceIds",
            "database_schema",
            "databaseSchema",
            "database_profile",
            "databaseProfile",
        ]
        .iter()
        .any(|key| {
            dataset.metadata.get(*key).is_some_and(|value| match value {
                Value::Array(items) => !items.is_empty(),
                Value::Object(object) => !object.is_empty(),
                Value::String(text) => !text.trim().is_empty(),
                _ => false,
            })
        })
}

fn assistant_dataset_prompt_match_score(dataset: &Dataset, prompt: &str) -> usize {
    let prompt = prompt.trim();
    if prompt.is_empty() {
        return 0;
    }
    let normalized_prompt = prompt.to_ascii_lowercase();
    let haystack = assistant_dataset_prompt_haystack(dataset).to_ascii_lowercase();
    if haystack.trim().is_empty() {
        return 0;
    }

    let mut score = 0usize;
    for term in assistant_prompt_match_terms(prompt) {
        if haystack.contains(&term.to_ascii_lowercase()) {
            score += term.chars().count().max(1);
        }
    }
    for (prompt_terms, dataset_terms, bonus) in [
        (
            &["长者", "老人", "老年", "养老", "在院"][..],
            &["养老", "老年", "老人", "长者", "护理", "机构"][..],
            24usize,
        ),
        (
            &["离世", "去世", "死亡", "身故", "过世"][..],
            &["离世", "去世", "死亡", "身故", "善后", "殡葬"][..],
            18usize,
        ),
        (
            &["摔倒", "跌倒", "坠床"][..],
            &["摔倒", "跌倒", "坠床", "防跌倒", "意外伤害"][..],
            18usize,
        ),
        (
            &["烫伤", "烧伤"][..],
            &["烫伤", "烧伤", "热源", "创面"][..],
            18usize,
        ),
        (
            &["合同", "租赁", "停车"][..],
            &["合同", "租赁", "停车", "协议"][..],
            18usize,
        ),
    ] {
        if prompt_terms
            .iter()
            .any(|term| normalized_prompt.contains(term))
            && dataset_terms.iter().any(|term| haystack.contains(term))
        {
            score += bonus;
        }
    }
    score
}

fn assistant_dataset_prompt_haystack(dataset: &Dataset) -> String {
    let mut values = vec![
        dataset.title.clone(),
        dataset.key.clone(),
        dataset.description.clone().unwrap_or_default(),
    ];
    for key in [
        "document_title_hints",
        "documentTitleHints",
        "material_hints",
        "materialHints",
        "noun_term_hints",
        "nounTermHints",
        "section_title_hints",
        "sectionTitleHints",
        "document_section_hints",
        "documentSectionHints",
    ] {
        if let Some(value) = dataset.metadata.get(key) {
            collect_string_list(value, &mut values);
        }
    }
    values.join(" ")
}

fn assistant_prompt_match_terms(prompt: &str) -> Vec<String> {
    let chars = prompt
        .chars()
        .filter(|ch| ch.is_alphanumeric() || is_cjk_char(*ch))
        .collect::<Vec<_>>();
    let mut terms = Vec::new();
    for window_size in [4usize, 3, 2] {
        if chars.len() < window_size {
            continue;
        }
        for window in chars.windows(window_size) {
            let term = window.iter().collect::<String>();
            if term.trim().is_empty() || terms.contains(&term) {
                continue;
            }
            terms.push(term);
        }
    }
    for token in prompt
        .split(|ch: char| !(ch.is_alphanumeric() || is_cjk_char(ch)))
        .map(str::trim)
        .filter(|token| token.chars().count() >= 2)
    {
        if !terms.iter().any(|term| term == token) {
            terms.push(token.to_string());
        }
    }
    terms
}

fn is_cjk_char(ch: char) -> bool {
    ('\u{4e00}'..='\u{9fff}').contains(&ch)
        || ('\u{3400}'..='\u{4dbf}').contains(&ch)
        || ('\u{f900}'..='\u{faff}').contains(&ch)
}

fn assistant_run_requested_dataset_supply_policy(intent: &str) -> Value {
    json!({
        "intent": if intent.trim().is_empty() { "data_question" } else { intent.trim() },
        "retrievalPolicy": "standard",
        "preferDetail": false,
        "noFakeData": true,
        "answerPolicy": "model_authored_host_supplied",
        "candidatePolicy": "selected_or_inferred_visible_datasets_only",
        "recommendedActions": ["retrieval.search"],
    })
}

fn selected_scope_has_document_selection(scope: &Value) -> bool {
    !selected_document_ids_from_scope(scope).is_empty()
        || scope
            .get("documents")
            .and_then(Value::as_array)
            .is_some_and(|documents| !documents.is_empty())
        || scope
            .get("available_document_external_ids")
            .and_then(Value::as_array)
            .is_some_and(|document_ids| !document_ids.is_empty())
}

fn assistant_run_active_static_page_supply_policy(has_dataset: bool, has_memory: bool) -> Value {
    let mut recommended_actions = Vec::new();
    if has_dataset {
        recommended_actions.push("retrieval.search");
        recommended_actions.push("retrieval.read_detail");
    }
    recommended_actions.push("static_page.update_draft");

    json!({
        "intent": "static_page",
        "answerPolicy": "model_authored_host_supplied",
        "currentArtifactPolicy": "active_static_page_draft",
        "actionPolicy": "model_may_request_controlled_actions_host_validates",
        "contextBudgetPolicy": if has_dataset || has_memory {
            "quality_first_token_tolerant"
        } else {
            "compact_until_retrieval_needed"
        },
        "candidatePolicy": if has_dataset {
            "selected_or_inferred_visible_datasets_only"
        } else {
            "ordinary_chat_without_forced_dataset"
        },
        "historyPolicy": if has_memory {
            "intent_gated_selected"
        } else {
            "intent_gated"
        },
        "retrievalPolicy": if has_dataset {
            "detail_first"
        } else {
            "not_requested"
        },
        "preferDetail": has_dataset,
        "recommendedActions": recommended_actions,
        "noFakeData": true,
    })
}

