async fn load_document_detail_with_state_and_local_scope(
    state: &AppState,
    document_id: DocumentId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    local_thread_id: Option<&str>,
) -> std::result::Result<DocumentDetailView, ApiError> {
    let document = load_visible_document_for_user_with_local_scope(
        state,
        document_id,
        active_secret_binding_ids,
        current_user_id,
        local_thread_id,
    )
    .await?;
    let chunks = state
        .storage
        .document_chunks()
        .list_by_document(state.tenant_id, document_id)
        .await
        .map_err(ApiError::from_storage)?;
    let mut retrieval_evidences = state
        .storage
        .retrieval_evidences()
        .list_by_document(state.tenant_id, document_id)
        .await
        .map_err(ApiError::from_storage)?;
    sort_retrieval_evidences_by_relevance(&mut retrieval_evidences);
    let workflow_by_document =
        load_latest_upload_ingest_workflow_snapshots(state, document.dataset_id, &[document.id])
            .await?;
    let workflow = workflow_by_document.get(&document.id).cloned();

    Ok(to_document_detail_view(
        document,
        chunks,
        retrieval_evidences,
        workflow,
    ))
}

async fn compare_documents_with_state(
    state: &AppState,
    request: CompareDocumentsRequest,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<CompareDocumentsView, ApiError> {
    let mut unique_document_ids = Vec::new();
    for document_id in request.document_ids {
        if !unique_document_ids
            .iter()
            .any(|existing| *existing == document_id)
        {
            unique_document_ids.push(document_id);
        }
    }

    if unique_document_ids.len() < 2 {
        return Err(ApiError::bad_request(
            "compare_documents_requires_multiple_documents",
            "compare_documents requires at least 2 distinct document_ids".to_string(),
        ));
    }

    let mut expected_dataset: Option<(DocumentId, DatasetId)> = None;
    for document_id in &unique_document_ids {
        let document = load_visible_document_for_user(
            state,
            *document_id,
            active_secret_binding_ids,
            current_user_id,
        )
        .await?;

        if let Some((expected_document_id, expected_dataset_id)) = expected_dataset {
            if document.dataset_id != expected_dataset_id {
                return Err(ApiError::bad_request(
                    "compare_documents_requires_same_dataset",
                    format!(
                        "document {} belongs to dataset {}, which does not match document {} in dataset {}",
                        document.id, document.dataset_id, expected_document_id, expected_dataset_id
                    ),
                ));
            }
        } else {
            expected_dataset = Some((document.id, document.dataset_id));
        }
    }

    let mut documents = Vec::with_capacity(unique_document_ids.len());
    for document_id in unique_document_ids {
        documents.push(
            load_document_detail_with_state(
                state,
                document_id,
                active_secret_binding_ids,
                current_user_id,
            )
            .await?,
        );
    }

    Ok(to_compare_documents_view(documents))
}

async fn register_document(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(request): Json<RegisterDocumentRequest>,
) -> std::result::Result<(StatusCode, Json<RegisterDocumentResponse>), ApiError> {
    validate_required("title", &request.title)?;
    validate_required("object_key", &request.object_key)?;
    validate_required("content_type", &request.content_type)?;

    let active_secret_binding_ids = merge_secret_binding_ids(
        &active_secret_binding_ids_from_headers(&headers)?,
        &request.secret_binding_ids,
    );
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_dataset_for_user(
        &state,
        request.dataset_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    let document = state
        .storage
        .documents()
        .create(
            state.tenant_id,
            NewDocument {
                dataset_id: request.dataset_id,
                title: request.title.trim().to_string(),
                object_key: request.object_key.trim().to_string(),
                content_type: request.content_type.trim().to_string(),
                secret_binding_ids: request.secret_binding_ids,
                owner_user_id: current_user_id,
                metadata: request.metadata,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok((
        StatusCode::CREATED,
        Json(RegisterDocumentResponse {
            document: to_document_summary(document),
        }),
    ))
}

async fn create_document_ingest(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(document_id): Path<String>,
) -> std::result::Result<(StatusCode, Json<CreateDocumentIngestResponse>), ApiError> {
    let document_id = parse_document_id(&document_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let document = load_visible_document_for_user(
        &state,
        document_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    if document_is_zip_archive(&document) {
        let response = create_zip_archive_child_ingests(&state, &document).await?;
        return Ok((StatusCode::CREATED, Json(response)));
    }

    let execution = build_initial_upload_ingest_execution(&state, &document)?;
    let initial_event = build_initial_upload_ingest_event(&execution, &document);
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal(&state, execution.id, WorkflowSignal::Start).await?;

    Ok((
        StatusCode::CREATED,
        Json(CreateDocumentIngestResponse {
            document: to_document_summary(document),
            workflow_execution: started.execution,
            child_documents: Vec::new(),
            child_documents_camel: Vec::new(),
            child_workflow_executions: Vec::new(),
            child_workflow_executions_camel: Vec::new(),
        }),
    ))
}

#[derive(Clone, Debug)]
struct ExpandedZipEntry {
    entry_name: String,
    title: String,
    object_key: String,
    content_type: String,
    size_bytes: u64,
}

async fn create_zip_archive_child_ingests(
    state: &AppState,
    parent_document: &Document,
) -> std::result::Result<CreateDocumentIngestResponse, ApiError> {
    let entries = expand_zip_document_to_local_files(parent_document)?;
    if entries.is_empty() {
        return Err(ApiError::bad_request(
            "zip_archive_empty",
            "zip archive did not contain supported files to ingest".to_string(),
        ));
    }

    let mut child_documents = Vec::new();
    let mut child_workflow_executions = Vec::new();
    for (index, entry) in entries.into_iter().enumerate() {
        let child_document = state
            .storage
            .documents()
            .create(
                state.tenant_id,
                NewDocument {
                    dataset_id: parent_document.dataset_id,
                    title: entry.title.clone(),
                    object_key: entry.object_key.clone(),
                    content_type: entry.content_type.clone(),
                    secret_binding_ids: parent_document.secret_binding_ids.clone(),
                    owner_user_id: parent_document.owner_user_id,
                    metadata: json!({
                        "zip_parent": {
                            "document_id": parent_document.id,
                            "title": parent_document.title,
                            "object_key": parent_document.object_key,
                        },
                        "zip_entry": {
                            "name": entry.entry_name,
                            "index": index,
                            "size_bytes": entry.size_bytes,
                        },
                        "parse_state": {
                            "stage": "queued",
                            "user_blocking": false,
                        }
                    }),
                },
            )
            .await
            .map_err(ApiError::from_storage)?;

        let execution = build_initial_upload_ingest_execution(state, &child_document)?;
        let initial_event = build_initial_upload_ingest_event(&execution, &child_document);
        state
            .storage
            .workflow_executions()
            .create_with_initial_event(&execution, &initial_event)
            .await
            .map_err(ApiError::from_storage)?;
        let started = apply_workflow_signal(state, execution.id, WorkflowSignal::Start).await?;
        child_workflow_executions.push(started.execution);
        child_documents.push(child_document);
    }

    let child_document_views =
        to_document_summaries_with_dataset_ids(state, child_documents, None).await?;
    let parent_metadata = json!({
        "parse_status": "zip_expanded",
        "ingest": {
            "processor": "zip_expander",
            "parse_method": "zip-child-documents",
            "parse_status": "zip_expanded",
            "child_document_count": child_document_views.len(),
            "child_document_ids": child_document_views
                .iter()
                .map(|document| document.id.to_string())
                .collect::<Vec<_>>(),
            "extracted_at": Utc::now(),
        }
    });
    let updated_parent = state
        .storage
        .documents()
        .update_state(
            state.tenant_id,
            parent_document.id,
            DocumentLifecycle::Indexed,
            Some(&parent_document.title),
            &parent_metadata,
            Utc::now(),
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok(CreateDocumentIngestResponse {
        document: to_document_summary(updated_parent),
        workflow_execution: child_workflow_executions.first().cloned().ok_or_else(|| {
            ApiError::internal(
                "zip_archive_ingest_missing_child_workflow",
                "zip archive expansion did not create child workflows".to_string(),
            )
        })?,
        child_documents: child_document_views.clone(),
        child_documents_camel: child_document_views,
        child_workflow_executions: child_workflow_executions.clone(),
        child_workflow_executions_camel: child_workflow_executions,
    })
}

fn document_is_zip_archive(document: &Document) -> bool {
    let content_type = document
        .content_type
        .split(';')
        .next()
        .unwrap_or(&document.content_type)
        .trim()
        .to_ascii_lowercase();
    matches!(
        content_type.as_str(),
        "application/zip" | "application/x-zip-compressed" | "multipart/x-zip"
    ) || document.title.to_ascii_lowercase().ends_with(".zip")
        || document.object_key.to_ascii_lowercase().ends_with(".zip")
}

fn expand_zip_document_to_local_files(
    document: &Document,
) -> std::result::Result<Vec<ExpandedZipEntry>, ApiError> {
    let path = resolve_platform_local_object_path(&document.object_key).ok_or_else(|| {
        ApiError::bad_request(
            "zip_archive_object_not_found",
            "zip archive object file was not found on this server".to_string(),
        )
    })?;
    let file = File::open(&path).map_err(|error| {
        ApiError::bad_request(
            "zip_archive_open_failed",
            format!("failed to open zip archive: {error}"),
        )
    })?;
    let mut archive = ZipArchive::new(file).map_err(|error| {
        ApiError::bad_request(
            "zip_archive_invalid",
            format!("uploaded file is not a readable zip archive: {error}"),
        )
    })?;

    let max_entries = zip_ingest_env_usize("ZIP_INGEST_MAX_ENTRIES", 80).clamp(1, 500);
    let max_entry_bytes = zip_ingest_env_u64("ZIP_INGEST_MAX_ENTRY_BYTES", 80 * 1024 * 1024).max(1);
    let max_total_bytes =
        zip_ingest_env_u64("ZIP_INGEST_MAX_TOTAL_BYTES", 300 * 1024 * 1024).max(1);
    let output_root = zip_child_output_root(&path, document)?;
    fs::create_dir_all(&output_root).map_err(|error| {
        ApiError::internal(
            "zip_archive_expand_failed",
            format!("failed to create zip extraction directory: {error}"),
        )
    })?;

    let mut entries = Vec::new();
    let mut total_bytes = 0u64;
    for index in 0..archive.len() {
        if entries.len() >= max_entries {
            break;
        }
        let file = archive.by_index(index).map_err(|error| {
            ApiError::bad_request(
                "zip_archive_read_failed",
                format!("failed to read zip entry {index}: {error}"),
            )
        })?;
        if file.is_dir() {
            continue;
        }
        let Some(enclosed_name) = file.enclosed_name().map(PathBuf::from) else {
            continue;
        };
        let entry_name = enclosed_name.to_string_lossy().replace('\\', "/");
        if zip_entry_should_skip(&entry_name) {
            continue;
        }
        let extension = enclosed_name
            .extension()
            .and_then(|value| value.to_str())
            .map(|value| format!(".{}", value.to_ascii_lowercase()))
            .unwrap_or_default();
        if !zip_entry_extension_supported(&extension) {
            continue;
        }
        let entry_size = file.size();
        if entry_size > max_entry_bytes {
            continue;
        }
        total_bytes = total_bytes.saturating_add(entry_size);
        if total_bytes > max_total_bytes {
            return Err(ApiError::bad_request(
                "zip_archive_too_large",
                format!("zip expanded content exceeds {} bytes", max_total_bytes),
            ));
        }
        let safe_name = safe_zip_entry_output_name(entries.len(), &entry_name, &extension);
        let output_path = output_root.join(safe_name);
        let mut output = File::create(&output_path).map_err(|error| {
            ApiError::internal(
                "zip_archive_expand_failed",
                format!("failed to create extracted zip entry: {error}"),
            )
        })?;
        let copied =
            std::io::copy(&mut file.take(max_entry_bytes + 1), &mut output).map_err(|error| {
                ApiError::internal(
                    "zip_archive_expand_failed",
                    format!("failed to write extracted zip entry: {error}"),
                )
            })?;
        output.flush().map_err(|error| {
            ApiError::internal(
                "zip_archive_expand_failed",
                format!("failed to flush extracted zip entry: {error}"),
            )
        })?;
        if copied > max_entry_bytes {
            let _ = fs::remove_file(&output_path);
            continue;
        }
        entries.push(ExpandedZipEntry {
            entry_name: entry_name.clone(),
            title: zip_entry_title(&entry_name),
            object_key: output_path.to_string_lossy().to_string(),
            content_type: infer_zip_child_content_type(&extension).to_string(),
            size_bytes: copied,
        });
    }

    Ok(entries)
}

fn resolve_platform_local_object_path(object_key: &str) -> Option<PathBuf> {
    let raw = object_key.trim().trim_start_matches("file://");
    if raw.is_empty() {
        return None;
    }

    let direct = PathBuf::from(raw);
    if direct.is_file() {
        return Some(direct);
    }

    if cfg!(windows) {
        if let Some(rest) = raw.strip_prefix("/mnt/") {
            let mut parts = rest.splitn(2, '/');
            if let (Some(drive), Some(path)) = (parts.next(), parts.next()) {
                if drive.len() == 1 {
                    let windows_path = format!("{}:\\{}", drive, path.replace('/', "\\"));
                    let candidate = PathBuf::from(windows_path);
                    if candidate.is_file() {
                        return Some(candidate);
                    }
                }
            }
        }
    }

    let root = std::env::var("PLATFORM_LOCAL_OBJECT_ROOT").ok()?;
    let rooted = StdPath::new(&root).join(raw);
    rooted.is_file().then_some(rooted)
}

fn zip_child_output_root(
    zip_path: &StdPath,
    document: &Document,
) -> std::result::Result<PathBuf, ApiError> {
    let base = zip_path
        .parent()
        .map(StdPath::to_path_buf)
        .unwrap_or_else(|| {
            external_document_object_root().unwrap_or_else(|_| std::env::temp_dir())
        });
    Ok(base
        .join("_zip_extracted")
        .join(safe_external_path_segment(&document.id.to_string())))
}

fn safe_zip_entry_output_name(index: usize, entry_name: &str, extension: &str) -> String {
    let stem = StdPath::new(entry_name)
        .file_stem()
        .and_then(|value| value.to_str())
        .map(safe_external_path_segment)
        .unwrap_or_else(|| "entry".to_string());
    let safe_extension = if extension.len() <= 16 {
        extension.to_string()
    } else {
        String::new()
    };
    format!("{:03}-{}{}", index + 1, stem, safe_extension)
}

fn zip_entry_title(entry_name: &str) -> String {
    StdPath::new(entry_name)
        .file_name()
        .and_then(|value| value.to_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| entry_name.to_string())
}

fn zip_entry_should_skip(entry_name: &str) -> bool {
    let lower = entry_name.to_ascii_lowercase();
    lower.starts_with("__macosx/")
        || lower.ends_with("/.ds_store")
        || lower.contains("/.git/")
        || lower.contains("/node_modules/")
}

fn zip_entry_extension_supported(extension: &str) -> bool {
    matches!(
        extension,
        ".txt"
            | ".md"
            | ".csv"
            | ".json"
            | ".html"
            | ".htm"
            | ".xml"
            | ".pdf"
            | ".doc"
            | ".docx"
            | ".xlsx"
            | ".xlsm"
            | ".pptx"
            | ".pptm"
            | ".png"
            | ".jpg"
            | ".jpeg"
            | ".webp"
            | ".bmp"
            | ".tif"
            | ".tiff"
            | ".gif"
            | ".mp3"
            | ".wav"
            | ".m4a"
            | ".aac"
            | ".flac"
            | ".ogg"
            | ".opus"
            | ".mp4"
            | ".mov"
            | ".mkv"
            | ".webm"
            | ".avi"
            | ".mpeg"
            | ".mpg"
    )
}

fn infer_zip_child_content_type(extension: &str) -> &'static str {
    match extension {
        ".md" => "text/markdown",
        ".csv" => "text/csv",
        ".json" => "application/json",
        ".html" | ".htm" => "text/html",
        ".xml" => "application/xml",
        ".pdf" => "application/pdf",
        ".doc" => "application/msword",
        ".docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        ".xlsx" | ".xlsm" => "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        ".pptx" | ".pptm" => {
            "application/vnd.openxmlformats-officedocument.presentationml.presentation"
        }
        ".png" => "image/png",
        ".jpg" | ".jpeg" => "image/jpeg",
        ".webp" => "image/webp",
        ".bmp" => "image/bmp",
        ".tif" | ".tiff" => "image/tiff",
        ".gif" => "image/gif",
        ".mp3" => "audio/mpeg",
        ".wav" => "audio/wav",
        ".m4a" => "audio/mp4",
        ".aac" => "audio/aac",
        ".flac" => "audio/flac",
        ".ogg" => "audio/ogg",
        ".opus" => "audio/opus",
        ".mp4" => "video/mp4",
        ".mov" => "video/quicktime",
        ".mkv" => "video/x-matroska",
        ".webm" => "video/webm",
        ".avi" => "video/x-msvideo",
        ".mpeg" | ".mpg" => "video/mpeg",
        _ => "text/plain",
    }
}

fn zip_ingest_env_u64(name: &str, default: u64) -> u64 {
    std::env::var(name)
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(default)
}

fn zip_ingest_env_usize(name: &str, default: usize) -> usize {
    std::env::var(name)
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .unwrap_or(default)
}

async fn create_report_plan(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(request): Json<PlanReportRequest>,
) -> std::result::Result<(StatusCode, Json<CreateReportPlanResponse>), ApiError> {
    validate_required("title", &request.title)?;
    validate_required("objective", &request.objective)?;

    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_dataset_for_user(
        &state,
        request.dataset_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    let (plan, execution) = create_report_plan_and_execution(
        &state,
        request.dataset_id,
        request.title.trim(),
        request.objective.trim(),
        current_user_id,
        None,
    )
    .await?;

    Ok((
        StatusCode::CREATED,
        Json(CreateReportPlanResponse {
            plan: to_report_plan_summary(
                plan,
                workflow_execution_context_service_handoff(&execution),
            ),
            workflow_execution: to_workflow_execution_view(execution),
        }),
    ))
}

async fn list_report_plans(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> std::result::Result<Json<Vec<ReportPlanSummary>>, ApiError> {
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let local_thread_id = local_thread_id_from_headers(&headers);
    let visible_dataset_ids: HashSet<DatasetId> = filter_visible_datasets(
        state
            .storage
            .datasets()
            .list_by_tenant(state.tenant_id)
            .await
            .map_err(ApiError::from_storage)?,
        &active_secret_binding_ids,
        current_user_id,
        local_thread_id.as_deref(),
    )
    .into_iter()
    .map(|dataset| dataset.id)
    .collect();
    let plans = state
        .storage
        .report_plans()
        .list_by_tenant(state.tenant_id)
        .await
        .map_err(ApiError::from_storage)?;

    let mut views = Vec::with_capacity(plans.len());
    for plan in plans {
        if !visible_dataset_ids.contains(&plan.dataset_id) {
            continue;
        }
        if !report_owner_is_visible(plan.owner_user_id, current_user_id) {
            continue;
        }
        views.push(hydrate_report_plan_summary(&state, plan).await?);
    }

    Ok(Json(views))
}

async fn list_report_plan_ast_versions(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(plan_id): Path<String>,
) -> std::result::Result<Json<Vec<ReportPlanAstVersionView>>, ApiError> {
    let plan_id = parse_plan_id(&plan_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_report_plan_for_user(&state, plan_id, &active_secret_binding_ids, current_user_id)
        .await?;

    let versions = state
        .storage
        .report_plan_ast_versions()
        .list_by_plan(state.tenant_id, plan_id)
        .await
        .map_err(ApiError::from_storage)?;

    Ok(Json(
        versions
            .into_iter()
            .map(to_report_plan_ast_version_view)
            .collect(),
    ))
}

async fn continue_report_plan(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(plan_id): Path<String>,
) -> std::result::Result<Json<CreateReportPlanResponse>, ApiError> {
    let plan_id = parse_plan_id(&plan_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_report_plan_for_user(&state, plan_id, &active_secret_binding_ids, current_user_id)
        .await?;
    let response =
        continue_report_plan_response(&state, plan_id, &active_secret_binding_ids, current_user_id)
            .await?;
    Ok(Json(response))
}

async fn create_report_plan_and_execution(
    state: &AppState,
    dataset_id: DatasetId,
    title: &str,
    objective: &str,
    owner_user_id: Option<UserId>,
    service_handoff: Option<contracts::ManifestServiceHandoffView>,
) -> std::result::Result<(ReportPlan, WorkflowExecution), ApiError> {
    let plan = state
        .storage
        .report_plans()
        .create(
            state.tenant_id,
            NewReportPlan {
                dataset_id,
                title: title.trim().to_string(),
                objective: objective.trim().to_string(),
                theme_key: "default-local".to_string(),
                owner_user_id,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    let execution = build_initial_report_plan_execution(
        state,
        &plan,
        finalize_report_service_handoff(service_handoff, plan.id).as_ref(),
    )?;
    let initial_event = build_initial_execution_event(&execution, plan.id);
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;

    Ok((plan, execution))
}

async fn continue_report_plan_response(
    state: &AppState,
    plan_id: ReportPlanId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<CreateReportPlanResponse, ApiError> {
    let plan = load_visible_report_plan_for_user(
        state,
        plan_id,
        active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    if plan.status != domain_model::ReportPlanStatus::Draft || plan.current_ast_version_id.is_some()
    {
        return Err(ApiError::bad_request(
            "report_plan_continue_not_allowed",
            format!("report plan {} is not a draft planning candidate", plan_id),
        ));
    }

    let latest_execution = state
        .storage
        .workflow_executions()
        .get_latest_by_report_plan_and_kind(state.tenant_id, plan_id, WorkflowKind::ReportPlan)
        .await
        .map_err(ApiError::from_storage)?;
    if let Some(execution) = latest_execution {
        if matches!(
            execution.status,
            WorkflowStatus::Pending | WorkflowStatus::Running
        ) {
            return Err(ApiError::bad_request(
                "report_plan_execution_in_progress",
                format!(
                    "report plan {} already has an active planning execution {}",
                    plan_id, execution.id
                ),
            ));
        }
    }

    let service_handoff = load_report_plan_service_handoff(state, plan_id).await?;
    let execution = build_initial_report_plan_execution(state, &plan, service_handoff.as_ref())?;
    let initial_event = build_initial_execution_event(&execution, plan.id);
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;

    Ok(CreateReportPlanResponse {
        plan: hydrate_report_plan_summary(state, plan).await?,
        workflow_execution: to_workflow_execution_view(execution),
    })
}

async fn publish_report(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(plan_id): Path<String>,
    Json(request): Json<PublishReportRequest>,
) -> std::result::Result<(StatusCode, Json<PublishReportResponse>), ApiError> {
    let plan_id = parse_plan_id(&plan_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_report_plan_for_user(&state, plan_id, &active_secret_binding_ids, current_user_id)
        .await?;
    let response = publish_report_response(
        &state,
        plan_id,
        request,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    Ok((StatusCode::CREATED, Json(response)))
}

async fn publish_report_response(
    state: &AppState,
    plan_id: ReportPlanId,
    request: PublishReportRequest,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<PublishReportResponse, ApiError> {
    let plan = load_visible_report_plan_for_user(
        state,
        plan_id,
        active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    let render_output = state
        .storage
        .report_render_outputs()
        .get_latest_rendered_for_surface(state.tenant_id, plan_id, request.surface.clone())
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::bad_request(
                "report_render_output_not_found",
                format!(
                    "report plan {} does not have a rendered output for surface {}",
                    plan_id,
                    request.surface.as_str()
                ),
            )
        })?;
    let source_render_output =
        hydrate_report_render_output_view(state, render_output.clone()).await?;
    if !report_render_output_has_asset_path(&source_render_output) {
        return Err(ApiError::bad_request(
            "report_render_output_not_publishable",
            format!(
                "report render output {} does not expose a publishable asset path",
                render_output.id
            ),
        ));
    }

    let published_at = Utc::now();
    let report = match state
        .storage
        .published_reports()
        .get_by_plan(state.tenant_id, plan_id)
        .await
        .map_err(ApiError::from_storage)?
    {
        Some(report) => report,
        None => state
            .storage
            .published_reports()
            .create(
                state.tenant_id,
                &NewPublishedReport {
                    dataset_id: plan.dataset_id,
                    plan_id,
                    slug: build_published_report_slug(&plan),
                    created_at: published_at,
                    updated_at: published_at,
                },
            )
            .await
            .map_err(ApiError::from_storage)?,
    };
    let version = state
        .storage
        .published_report_versions()
        .create_next_version(
            state.tenant_id,
            report.id,
            &NewPublishedReportVersion {
                surface: request.surface,
                asset_manifest: build_published_report_version_manifest(
                    &render_output,
                    request.publish_note.as_deref(),
                    published_at,
                ),
                created_at: published_at,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    let report = state
        .storage
        .published_reports()
        .set_current_version(state.tenant_id, report.id, version.id, published_at)
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .report_plans()
        .mark_published(state.tenant_id, plan_id, published_at)
        .await
        .map_err(ApiError::from_storage)?;

    Ok(PublishReportResponse {
        report: to_published_report_view(report),
        version: to_published_report_version_view(version),
        source_render_output,
    })
}

