async fn load_workflow_runtime_inspect_view(
    state: &AppState,
    execution_id: WorkflowExecutionId,
) -> std::result::Result<WorkflowRuntimeInspectView, ApiError> {
    let execution = state
        .storage
        .workflow_executions()
        .get_by_id(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "workflow_execution_not_found",
                format!("workflow execution {} was not found", execution_id),
            )
        })?;
    let artifact_manifests = load_workflow_runtime_artifact_manifests(state, &execution).await?;

    let dataset_output = match state
        .storage
        .dataset_outputs()
        .get_by_execution_id(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
    {
        Some(output) => Some(hydrate_dataset_output_view(&state, output).await?),
        None => None,
    };
    let chat_session_record = state
        .storage
        .chat_sessions()
        .get_by_execution_id(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?;
    let (chat_session, chat_messages) = match chat_session_record {
        Some(session) => {
            let chat_messages = load_chat_message_views_for_session(state, session.id).await?;
            let latest_assistant_message = latest_assistant_message_from_views(&chat_messages);
            let chat_session = hydrate_chat_session_view_with_latest_assistant_message(
                state,
                session,
                latest_assistant_message,
            )
            .await?;
            (Some(chat_session), chat_messages)
        }
        None => (None, Vec::new()),
    };
    let report_plan = match execution.report_plan_id {
        Some(report_plan_id) => match state
            .storage
            .report_plans()
            .get_by_id(state.tenant_id, report_plan_id)
            .await
            .map_err(ApiError::from_storage)?
        {
            Some(plan) => Some(hydrate_report_plan_summary(state, plan).await?),
            None => None,
        },
        None => None,
    };
    let report_render_output = match state
        .storage
        .report_render_outputs()
        .get_by_execution_id(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
    {
        Some(output) => Some(hydrate_report_render_output_view(state, output).await?),
        None => None,
    };
    let llm_invocations: Vec<LlmInvocationView> = state
        .storage
        .llm_invocations()
        .list_by_execution(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .map(to_llm_invocation_view)
        .collect();
    let tool_executions: Vec<ToolExecutionView> = state
        .storage
        .tool_executions()
        .list_by_execution(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .map(to_tool_execution_view)
        .collect();
    let execution_scope_runtime: Option<contracts::WorkflowExecutionRuntimeSummaryView> =
        summarize_execution_scope_runtime(&llm_invocations, &tool_executions);

    let mut inspect = WorkflowRuntimeInspectView {
        execution: to_workflow_execution_view(execution),
        execution_scope_runtime,
        dataset_output,
        chat_session,
        report_plan,
        report_render_output,
        chat_messages,
        llm_invocations,
        tool_executions,
        model_facing: None,
        pretty_summaries: Vec::new(),
        artifact_manifests,
    };
    inspect.model_facing = Some(derive_model_facing_summary(&inspect));
    inspect.pretty_summaries = render_workflow_runtime_pretty_summaries(&inspect);

    Ok(inspect)
}

async fn load_workflow_runtime_artifact_manifests(
    state: &AppState,
    execution: &WorkflowExecution,
) -> std::result::Result<Vec<Value>, ApiError> {
    let Some(run_id) = workflow_runtime_assistant_run_id(&execution.context) else {
        return Ok(Vec::new());
    };
    let Some(run) = state
        .storage
        .assistant_runs()
        .get_by_id(state.tenant_id, run_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(Vec::new());
    };
    let mut manifests = output_artifact_manifests_from_output_artifacts(&run.output_artifacts);
    let events = state
        .storage
        .assistant_runs()
        .list_events(state.tenant_id, run_id)
        .await
        .map_err(ApiError::from_storage)?;
    manifests.extend(
        events
            .iter()
            .filter_map(|event| safe_output_artifact_manifest(&event.payload)),
    );
    Ok(dedupe_output_artifact_manifests(manifests))
}

fn workflow_runtime_assistant_run_id(context: &Value) -> Option<AssistantRunId> {
    workflow_context_uuid(context, "assistant_run_id")
        .or_else(|| {
            context
                .pointer("/fixed_task/assistant_run_id")
                .and_then(Value::as_str)
                .and_then(|raw| Uuid::parse_str(raw).ok())
        })
        .map(AssistantRunId)
}

fn output_artifact_manifests_from_output_artifacts(output_artifacts: &Value) -> Vec<Value> {
    dedupe_output_artifact_manifests(
        value_array(output_artifacts.clone())
            .into_iter()
            .filter_map(|artifact| safe_output_artifact_manifest(&artifact))
            .collect(),
    )
}

fn dedupe_output_artifact_manifests(manifests: Vec<Value>) -> Vec<Value> {
    let mut seen = BTreeSet::new();
    manifests
        .into_iter()
        .filter(|manifest| {
            let key = serde_json::to_string(manifest).unwrap_or_default();
            seen.insert(key)
        })
        .collect()
}

fn safe_output_artifact_manifest(artifact: &Value) -> Option<Value> {
    let manifest = artifact
        .get("artifact_manifest")
        .or_else(|| artifact.get("artifactManifest"))?;
    let schema = manifest.get("schema").and_then(Value::as_str)?;
    let schema_version = manifest
        .get("schema_version")
        .or_else(|| manifest.get("schemaVersion"))
        .and_then(Value::as_i64)?;
    if schema != "v3.output_artifact_manifest" || schema_version != 1 {
        return None;
    }
    Some(json!({
        "schema": "v3.output_artifact_manifest",
        "schema_version": 1,
        "artifact_type": manifest.get("artifact_type").cloned().unwrap_or(Value::Null),
        "artifact_kind": manifest.get("artifact_kind").cloned().unwrap_or(Value::Null),
        "title": manifest.get("title").cloned().unwrap_or(Value::Null),
        "status": manifest.get("status").cloned().unwrap_or(Value::Null),
        "primary_url": manifest.get("primary_url").cloned().unwrap_or(Value::Null),
        "links": manifest.get("links").cloned().unwrap_or_else(|| json!([])),
        "refs": manifest.get("refs").cloned().unwrap_or_else(|| json!({})),
        "safety": manifest.get("safety").cloned().unwrap_or_else(|| json!({})),
    }))
}

