fn to_document_summary(document: Document) -> DocumentSummary {
    let dataset_ids = vec![document.dataset_id];
    to_document_summary_with_dataset_ids(document, dataset_ids)
}

fn to_document_summary_with_dataset_ids(
    document: Document,
    dataset_ids: Vec<DatasetId>,
) -> DocumentSummary {
    let parse_status = document_metadata_parse_status(&document)
        .unwrap_or_else(|| document.lifecycle.as_str().to_string());
    let parse_quality_status = assistant_run_document_parse_quality_status(&document);
    let dataset_ids = normalize_document_dataset_ids(document.dataset_id, dataset_ids);
    DocumentSummary {
        id: document.id,
        dataset_id: document.dataset_id,
        dataset_ids: dataset_ids.clone(),
        dataset_ids_camel: dataset_ids,
        title: document.title,
        object_key: document.object_key,
        content_type: document.content_type,
        lifecycle: contracts::DocumentLifecycleView::from_domain(document.lifecycle),
        parse_status: parse_status.clone(),
        parse_status_camel: parse_status,
        parse_quality_status: parse_quality_status.clone(),
        parse_quality_status_camel: parse_quality_status,
        secret_binding_ids: document.secret_binding_ids,
        created_at: document.created_at,
        updated_at: document.updated_at,
    }
}

fn normalize_document_dataset_ids(
    canonical_dataset_id: DatasetId,
    dataset_ids: Vec<DatasetId>,
) -> Vec<DatasetId> {
    let mut seen = BTreeSet::new();
    let mut normalized = Vec::new();
    if seen.insert(canonical_dataset_id) {
        normalized.push(canonical_dataset_id);
    }
    for dataset_id in dataset_ids {
        if seen.insert(dataset_id) {
            normalized.push(dataset_id);
        }
    }
    normalized
}

async fn to_document_summaries_with_dataset_ids(
    state: &AppState,
    documents: Vec<Document>,
    visible_dataset_ids: Option<&HashSet<DatasetId>>,
) -> std::result::Result<Vec<DocumentSummary>, ApiError> {
    let document_ids: Vec<DocumentId> = documents.iter().map(|document| document.id).collect();
    let membership_pairs = state
        .storage
        .dataset_document_memberships()
        .list_dataset_ids_by_documents(state.tenant_id, &document_ids)
        .await
        .map_err(ApiError::from_storage)?;
    let mut memberships_by_document: HashMap<DocumentId, Vec<DatasetId>> = HashMap::new();
    for (document_id, dataset_id) in membership_pairs {
        if visible_dataset_ids.is_none_or(|visible| visible.contains(&dataset_id)) {
            memberships_by_document
                .entry(document_id)
                .or_default()
                .push(dataset_id);
        }
    }
    Ok(documents
        .into_iter()
        .map(|document| {
            let dataset_ids = memberships_by_document
                .remove(&document.id)
                .unwrap_or_default();
            to_document_summary_with_dataset_ids(document, dataset_ids)
        })
        .collect())
}

async fn hydrate_document_summary_dataset_ids(
    state: &AppState,
    summary: DocumentSummary,
    visible_dataset_ids: Option<&HashSet<DatasetId>>,
) -> std::result::Result<DocumentSummary, ApiError> {
    let membership_dataset_ids = state
        .storage
        .dataset_document_memberships()
        .list_dataset_ids_by_document(state.tenant_id, summary.id)
        .await
        .map_err(ApiError::from_storage)?;
    let mut dataset_ids = Vec::new();
    for dataset_id in membership_dataset_ids {
        if visible_dataset_ids.is_none_or(|visible| visible.contains(&dataset_id)) {
            dataset_ids.push(dataset_id);
        }
    }
    let dataset_ids = normalize_document_dataset_ids(summary.dataset_id, dataset_ids);
    Ok(DocumentSummary {
        dataset_ids: dataset_ids.clone(),
        dataset_ids_camel: dataset_ids,
        ..summary
    })
}

async fn document_dataset_membership_response(
    state: &AppState,
    document: Document,
    visible_dataset_ids: Option<&HashSet<DatasetId>>,
) -> std::result::Result<Json<DocumentDatasetMembershipResponse>, ApiError> {
    let document = hydrate_document_summary_dataset_ids(
        state,
        to_document_summary(document),
        visible_dataset_ids,
    )
    .await?;
    let dataset_ids = document.dataset_ids.clone();
    Ok(Json(DocumentDatasetMembershipResponse {
        canonical_dataset_id: document.dataset_id,
        canonical_dataset_id_camel: document.dataset_id,
        document,
        dataset_ids: dataset_ids.clone(),
        dataset_ids_camel: dataset_ids,
    }))
}

fn to_document_detail_view(
    document: Document,
    chunks: Vec<DocumentChunk>,
    retrieval_evidences: Vec<RetrievalEvidence>,
    workflow: Option<Value>,
) -> DocumentDetailView {
    let parse_state = build_document_parse_status_view(
        &document,
        &chunks,
        retrieval_evidences.len(),
        workflow.as_ref(),
    );
    let mut view = DocumentDetailView {
        document: to_document_summary(document),
        chunks: chunks.into_iter().map(to_document_chunk_view).collect(),
        retrieval_evidences: retrieval_evidences
            .into_iter()
            .map(to_retrieval_evidence_view)
            .collect(),
        parse_state,
        model_facing: None,
    };
    view.model_facing = Some(derive_document_detail_model_facing_summary(&view));
    view
}

fn build_document_parse_status_view(
    document: &Document,
    chunks: &[DocumentChunk],
    retrieval_evidence_count: usize,
    workflow: Option<&Value>,
) -> contracts::DocumentParseStatusView {
    let parse_status = assistant_scope_document_parse_status(document, chunks);
    let parse_quality_summary = assistant_run_document_parse_quality_summary(document)
        .or_else(|| assistant_run_inferred_low_text_parse_quality_summary(document, chunks));
    let parse_quality_status =
        assistant_run_document_parse_quality_status(document).or_else(|| {
            parse_quality_summary
                .as_ref()
                .and_then(|summary| value_at_any_key(summary, &["status"]))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        });
    let model_status = assistant_run_document_parse_model_status(
        document,
        &parse_status,
        chunks.len(),
        parse_quality_status.as_deref(),
        workflow,
    );
    contracts::DocumentParseStatusView {
        parse_status: parse_status.clone(),
        parse_status_camel: parse_status,
        parse_quality_status: parse_quality_status.clone(),
        parse_quality_status_camel: parse_quality_status,
        parse_quality_summary: parse_quality_summary.clone(),
        parse_quality_summary_camel: parse_quality_summary,
        model_status: model_status.clone(),
        model_status_camel: model_status,
        lifecycle: contracts::DocumentLifecycleView::from_domain(document.lifecycle.clone()),
        chunk_count: chunks.len(),
        retrieval_evidence_count,
        workflow: workflow.cloned(),
        ingest: document.metadata.get("ingest").cloned(),
    }
}

fn to_document_media_detail_view(
    document: Document,
    chunks: Vec<DocumentChunk>,
) -> DocumentMediaDetailView {
    let document = to_document_summary(document);
    let raw_media_metadata = extract_media_metadata_from_chunks(&chunks).unwrap_or_else(|| {
        json!({
            "kind": infer_media_kind_from_content_type(&document.content_type),
            "parse_status": "unknown",
            "transcript_segments": [],
            "scenes": [],
            "keyframe_ocr_snippets": [],
            "provider_evidence": []
        })
    });

    let mut view = DocumentMediaDetailView {
        media_kind: raw_media_metadata
            .get("kind")
            .and_then(Value::as_str)
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| infer_media_kind_from_content_type(&document.content_type))
            .to_string(),
        parse_status: raw_media_metadata
            .get("parse_status")
            .and_then(Value::as_str)
            .unwrap_or("unknown")
            .to_string(),
        transcript_segments: collect_media_transcript_segments(&raw_media_metadata),
        scenes: collect_media_scenes(&raw_media_metadata),
        keyframe_ocr_snippets: collect_media_ocr_snippets(&raw_media_metadata),
        provider_evidence: collect_media_provider_evidence(&raw_media_metadata),
        raw_media_metadata,
        document,
        model_facing: None,
    };
    view.model_facing = Some(derive_document_media_detail_model_facing_summary(&view));
    view
}

fn to_compare_documents_view(documents: Vec<DocumentDetailView>) -> CompareDocumentsView {
    let mut view = CompareDocumentsView {
        documents,
        model_facing: None,
    };
    view.model_facing = Some(derive_compare_documents_model_facing_summary(&view));
    view
}

fn to_document_chunk_view(chunk: DocumentChunk) -> DocumentChunkView {
    let section_title_hints = document_chunk_section_title_hints(&chunk);
    let mut metadata = Map::from_iter(chunk.metadata);
    if !section_title_hints.is_empty() {
        metadata.insert(
            "section_title_hints".to_string(),
            json!(section_title_hints),
        );
    }

    DocumentChunkView {
        id: chunk.id,
        document_id: chunk.document_id,
        chunk_index: chunk.chunk_index,
        token_count: chunk.token_count,
        state: contracts::DocumentChunkStateView::from_domain(chunk.state),
        content: chunk.content,
        metadata: Value::Object(metadata),
        created_at: chunk.created_at,
        updated_at: chunk.updated_at,
    }
}

fn extract_media_metadata_from_chunks(chunks: &[DocumentChunk]) -> Option<Value> {
    chunks.iter().find_map(|chunk| {
        let metadata = Value::Object(Map::from_iter(chunk.metadata.clone()));
        metadata
            .pointer("/parse_metadata/media")
            .or_else(|| metadata.get("media"))
            .cloned()
    })
}

fn infer_media_kind_from_content_type(content_type: &str) -> &'static str {
    let lower = content_type.trim().to_ascii_lowercase();
    if lower.starts_with("audio/") {
        "audio"
    } else if lower.starts_with("video/") {
        "video"
    } else {
        "unknown"
    }
}

fn collect_media_transcript_segments(
    raw_media_metadata: &Value,
) -> Vec<contracts::MediaTranscriptSegmentView> {
    raw_media_metadata
        .get("transcript_segments")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    let text = item
                        .get("text")
                        .and_then(Value::as_str)
                        .map(str::trim)
                        .filter(|text| !text.is_empty())?
                        .to_string();
                    Some(contracts::MediaTranscriptSegmentView {
                        start_seconds: media_numeric_field(item, &["start_seconds", "start"]),
                        end_seconds: media_numeric_field(item, &["end_seconds", "end"]),
                        text,
                        source: media_string_field(item, &["source"])
                            .unwrap_or_else(|| "unknown".to_string()),
                        language: media_string_field(item, &["language"]),
                        confidence: media_numeric_field(item, &["confidence", "score"]),
                    })
                })
                .collect()
        })
        .unwrap_or_default()
}

fn collect_media_scenes(raw_media_metadata: &Value) -> Vec<contracts::MediaSceneView> {
    raw_media_metadata
        .get("scenes")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    let summary = media_string_field(item, &["summary", "label"])
                        .unwrap_or_else(|| "Scene".to_string());
                    Some(contracts::MediaSceneView {
                        start_seconds: media_numeric_field(item, &["start_seconds", "start"]),
                        end_seconds: media_numeric_field(item, &["end_seconds", "end"]),
                        representative_seconds: media_numeric_field(
                            item,
                            &["representative_seconds", "timestamp_seconds", "timestamp"],
                        ),
                        summary,
                        source: media_string_field(item, &["source"])
                            .unwrap_or_else(|| "unknown".to_string()),
                    })
                })
                .collect()
        })
        .unwrap_or_default()
}

fn collect_media_ocr_snippets(raw_media_metadata: &Value) -> Vec<contracts::MediaOcrSnippetView> {
    raw_media_metadata
        .get("keyframe_ocr_snippets")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    let text = media_string_field(item, &["text", "content"])?;
                    Some(contracts::MediaOcrSnippetView {
                        timestamp_seconds: media_numeric_field(
                            item,
                            &["timestamp_seconds", "timestamp", "time"],
                        ),
                        text,
                        source: media_string_field(item, &["source"])
                            .unwrap_or_else(|| "unknown".to_string()),
                    })
                })
                .collect()
        })
        .unwrap_or_default()
}

fn collect_media_provider_evidence(
    raw_media_metadata: &Value,
) -> Vec<contracts::MediaProviderEvidenceView> {
    if let Some(items) = raw_media_metadata
        .get("provider_evidence")
        .and_then(Value::as_array)
    {
        return items
            .iter()
            .filter_map(media_provider_evidence_from_value)
            .collect();
    }

    raw_media_metadata
        .get("provider_capabilities")
        .and_then(Value::as_object)
        .map(|object| {
            [
                "audio_transcript",
                "native_video_understanding",
                "keyframe_image_vlm",
            ]
            .into_iter()
            .filter_map(|key| object.get(key))
            .filter_map(media_provider_evidence_from_value)
            .collect()
        })
        .unwrap_or_default()
}

fn media_provider_evidence_from_value(
    value: &Value,
) -> Option<contracts::MediaProviderEvidenceView> {
    Some(contracts::MediaProviderEvidenceView {
        provider: media_string_field(value, &["provider"]).unwrap_or_else(|| "unknown".to_string()),
        capability: media_string_field(value, &["capability"])?,
        status: media_string_field(value, &["status"]).unwrap_or_else(|| "unknown".to_string()),
        supported: value
            .get("supported")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        detail: media_string_field(value, &["detail"]).unwrap_or_default(),
        endpoint: media_string_field(value, &["endpoint"]),
        model: media_string_field(value, &["model"]).unwrap_or_default(),
    })
}

fn media_string_field(value: &Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        value
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .map(str::to_string)
    })
}

fn media_numeric_field(value: &Value, keys: &[&str]) -> Option<f64> {
    keys.iter().find_map(|key| {
        value.get(*key).and_then(|item| {
            item.as_f64()
                .or_else(|| item.as_str().and_then(|text| text.parse::<f64>().ok()))
        })
    })
}

