struct RankedRetrievalEvidence<'a> {
    evidence: &'a RetrievalEvidence,
    score: f64,
    lexical_score: f64,
    recall_score: f64,
    rank_hint: usize,
}

struct RankedDocumentChunk {
    document: Document,
    chunk: DocumentChunk,
    search_text: String,
    score: f64,
    lexical_score: f64,
}

struct AssistantRunRankQuery {
    text: String,
    weights: BTreeMap<String, f64>,
    norm: f64,
}

fn assistant_run_rank_query_variants(prompt: &str) -> Vec<AssistantRunRankQuery> {
    let mut texts = Vec::new();
    let mut seen = BTreeSet::new();
    for text in
        std::iter::once(prompt.trim().to_string()).chain(assistant_run_reduced_query_texts(prompt))
    {
        let text = normalize_assistant_reduced_query_text(&text);
        if text.is_empty() || !seen.insert(text.clone()) {
            continue;
        }
        let weights = lexical_query_term_weights(&text);
        let norm = vector_norm(&weights);
        if norm > 0.0 {
            texts.push(AssistantRunRankQuery {
                text,
                weights,
                norm,
            });
        }
    }
    texts
}

fn assistant_run_reduced_query_texts(prompt: &str) -> Vec<String> {
    let mut variants = Vec::new();
    let stripped = assistant_run_strip_question_noise(prompt);
    if !stripped.is_empty() && stripped != prompt.trim() {
        variants.push(stripped.clone());
    }

    let key_terms = assistant_run_key_terms_query(prompt, 10);
    if !key_terms.is_empty() {
        variants.push(key_terms);
    }

    if prompt_requests_procedure_or_action(prompt) && !stripped.is_empty() {
        variants.push(format!("{stripped} 处理 处置 应急 流程"));
    }
    if prompt_contains_elder_fall_signal(prompt) {
        variants.push("摔倒 跌倒 意外伤害 突发事件 事故处理 应急处置 120 通知家属".to_string());
    }
    if prompt_contains_elder_death_signal(prompt) {
        variants.push(
            "离世 去世 死亡 身故 善后 遗体 遗物 医护确认 生命体征 通知家属 家属沟通 殡仪接运 遗物交接 记录归档"
                .to_string(),
        );
    }

    let mut seen = BTreeSet::new();
    variants
        .into_iter()
        .map(|text| normalize_assistant_reduced_query_text(&text))
        .filter(|text| !text.is_empty() && seen.insert(text.clone()))
        .collect()
}

fn assistant_run_strip_question_noise(prompt: &str) -> String {
    let mut text = prompt.trim().to_string();
    for noise in [
        "请问",
        "帮我",
        "帮忙",
        "回答",
        "总结",
        "一下",
        "这个",
        "那个",
        "这份",
        "文档里",
        "文档里面",
        "资料里",
        "资料里面",
        "问题",
        "是什么",
        "是谁",
        "怎么办",
        "怎么处理",
        "如何处理",
        "如何",
        "哪些",
        "需要",
        "可以",
        "能不能",
        "应该",
        "到底",
        "吗",
        "呢",
    ] {
        text = text.replace(noise, " ");
    }
    normalize_assistant_reduced_query_text(&text)
}

fn assistant_run_key_terms_query(prompt: &str, limit: usize) -> String {
    let mut terms = lexical_query_term_weights(prompt)
        .into_iter()
        .filter(|(term, _)| assistant_run_reduced_query_term_is_signal(term))
        .collect::<Vec<_>>();
    terms.sort_by(|left, right| {
        right
            .1
            .partial_cmp(&left.1)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| right.0.chars().count().cmp(&left.0.chars().count()))
            .then_with(|| left.0.cmp(&right.0))
    });
    terms
        .into_iter()
        .map(|(term, _)| term)
        .take(limit)
        .collect::<Vec<_>>()
        .join(" ")
}

fn assistant_run_reduced_query_term_is_signal(term: &str) -> bool {
    let char_count = term.chars().count();
    if char_count < 2 || assistant_run_reduced_query_term_is_noise(term) {
        return false;
    }
    if term.chars().all(|value| is_cjk_query_token_char(value)) {
        return char_count >= 2;
    }
    term.chars().any(|value| value.is_ascii_alphanumeric())
}

fn assistant_run_reduced_query_term_is_noise(term: &str) -> bool {
    matches!(
        term,
        "请问"
            | "帮我"
            | "帮忙"
            | "回答"
            | "总结"
            | "一下"
            | "这个"
            | "那个"
            | "这份"
            | "文档"
            | "资料"
            | "里面"
            | "问题"
            | "是什么"
            | "是谁"
            | "怎么办"
            | "怎么处理"
            | "如何"
            | "哪些"
            | "需要"
            | "可以"
            | "能不能"
            | "应该"
            | "到底"
    )
}

fn normalize_assistant_reduced_query_text(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn rank_retrieval_evidences_for_prompt<'a>(
    evidences: &'a [RetrievalEvidence],
    prompt: &str,
    limit: usize,
) -> Vec<RankedRetrievalEvidence<'a>> {
    if evidences.is_empty() || limit == 0 {
        return Vec::new();
    }

    let query_variants = assistant_run_rank_query_variants(prompt);
    let mut ranked = evidences
        .iter()
        .map(|evidence| {
            let search_text = retrieval_evidence_search_text(evidence);
            let lexical_score = query_variants
                .iter()
                .map(|query| {
                    lexical_query_score(evidence, &query.weights, query.norm)
                        .max(lexical_text_score(&search_text, &query.weights, query.norm))
                        + lexical_domain_hint_score(&search_text, &query.text)
                })
                .fold(0.0, f64::max);
            let score = if lexical_score > 0.0 {
                lexical_score
            } else {
                evidence.recall_score
            };
            RankedRetrievalEvidence {
                evidence,
                score,
                lexical_score,
                recall_score: evidence.recall_score,
                rank_hint: rank_hint_from_evidence_manifest(evidence).unwrap_or(usize::MAX),
            }
        })
        .collect::<Vec<_>>();
    ranked.sort_by(|left, right| {
        right
            .lexical_score
            .partial_cmp(&left.lexical_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| {
                right
                    .score
                    .partial_cmp(&left.score)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .then_with(|| {
                right
                    .recall_score
                    .partial_cmp(&left.recall_score)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .then_with(|| left.rank_hint.cmp(&right.rank_hint))
            .then_with(|| right.evidence.created_at.cmp(&left.evidence.created_at))
            .then_with(|| left.evidence.chunk_index.cmp(&right.evidence.chunk_index))
    });
    ranked.into_iter().take(limit).collect()
}

fn rank_document_chunks_for_prompt(
    sources: Vec<(Document, DocumentChunk)>,
    prompt: &str,
    limit: usize,
) -> Vec<RankedDocumentChunk> {
    if sources.is_empty() || limit == 0 {
        return Vec::new();
    }

    let query_variants = assistant_run_rank_query_variants_for_chunks(prompt, &sources);
    let mut ranked = sources
        .into_iter()
        .map(|(document, chunk)| {
            let search_text = document_chunk_search_text(&document, &chunk);
            let mut lexical_score = query_variants
                .iter()
                .map(|query| {
                    lexical_text_score(&search_text, &query.weights, query.norm)
                        + lexical_domain_hint_score(&search_text, &query.text)
                })
                .fold(0.0, f64::max);
            lexical_score += lexical_original_query_signal_overlap_score(&search_text, prompt);
            if document_chunk_looks_like_toc_or_index(&chunk) {
                lexical_score *= 0.35;
            }
            RankedDocumentChunk {
                document,
                chunk,
                search_text,
                score: lexical_score,
                lexical_score,
            }
        })
        .collect::<Vec<_>>();

    ranked.sort_by(|left, right| {
        right
            .lexical_score
            .partial_cmp(&left.lexical_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| right.chunk.updated_at.cmp(&left.chunk.updated_at))
            .then_with(|| left.chunk.chunk_index.cmp(&right.chunk.chunk_index))
            .then_with(|| left.document.title.cmp(&right.document.title))
    });
    ranked.into_iter().take(limit).collect()
}

fn assistant_run_rank_query_variants_for_chunks(
    prompt: &str,
    sources: &[(Document, DocumentChunk)],
) -> Vec<AssistantRunRankQuery> {
    let mut variants = assistant_run_rank_query_variants(prompt);
    let mut seen = variants
        .iter()
        .map(|variant| variant.text.clone())
        .collect::<BTreeSet<_>>();
    for text in assistant_run_section_title_hop_query_texts(prompt, sources, 4) {
        let text = normalize_assistant_reduced_query_text(&text);
        if text.is_empty() || !seen.insert(text.clone()) {
            continue;
        }
        let weights = lexical_query_term_weights(&text);
        let norm = vector_norm(&weights);
        if norm > 0.0 {
            variants.push(AssistantRunRankQuery {
                text,
                weights,
                norm,
            });
        }
    }
    variants
}

fn assistant_run_section_title_hop_query_texts(
    prompt: &str,
    sources: &[(Document, DocumentChunk)],
    limit: usize,
) -> Vec<String> {
    if limit == 0
        || (!prompt_requests_procedure_or_action(prompt)
            && !prompt_contains_elder_fall_signal(prompt)
            && !prompt_contains_elder_death_signal(prompt))
    {
        return Vec::new();
    }
    let expanded_prompt = assistant_run_expanded_supply_prompt(prompt);
    let original_query_weights = lexical_query_term_weights(prompt);
    let original_query_norm = vector_norm(&original_query_weights);
    let query_weights = lexical_query_term_weights(&expanded_prompt);
    let query_norm = vector_norm(&query_weights);
    if query_weights.is_empty() || query_norm <= 0.0 {
        return Vec::new();
    }

    let mut scored_titles = Vec::<(String, f64, bool)>::new();
    for (_document, chunk) in sources {
        let title_hints = document_chunk_section_title_hints(chunk);
        if title_hints.is_empty() {
            continue;
        }
        let toc_like = document_chunk_looks_like_toc_or_index(chunk);
        for title in title_hints {
            let original_overlap_score =
                lexical_text_score(&title, &original_query_weights, original_query_norm);
            let domain_score = lexical_domain_hint_score(&title, &expanded_prompt);
            if original_overlap_score <= 0.0 && domain_score <= 0.0 {
                continue;
            }
            let score = lexical_text_score(&title, &query_weights, query_norm)
                + domain_score
                + original_overlap_score;
            if score > 0.0 {
                scored_titles.push((title, score, toc_like));
            }
        }
    }
    scored_titles.sort_by(|left, right| {
        right
            .1
            .partial_cmp(&left.1)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.2.cmp(&right.2))
            .then_with(|| left.0.cmp(&right.0))
    });

    let mut seen = BTreeSet::new();
    scored_titles
        .into_iter()
        .filter_map(|(title, _score, _toc_like)| {
            if seen.insert(title.clone()) {
                Some(format!("{title} {expanded_prompt}"))
            } else {
                None
            }
        })
        .take(limit)
        .collect()
}

fn document_chunk_looks_like_toc_or_index(chunk: &DocumentChunk) -> bool {
    let content = chunk.content.trim();
    if content.is_empty() {
        return false;
    }
    let dotted_leader_count = content.matches("....").count();
    let has_page_tail = content
        .split_whitespace()
        .last()
        .is_some_and(|tail| tail.chars().all(|ch| ch.is_ascii_digit()) && tail.len() <= 4);
    let short_line_count = content
        .lines()
        .filter(|line| line.trim().len() <= 80)
        .count();
    let line_count = content.lines().count().max(1);
    dotted_leader_count >= 1
        || (content.contains("目录") && short_line_count >= line_count.saturating_sub(1))
        || (has_page_tail && content.contains('…'))
}

fn lexical_original_query_signal_overlap_score(content: &str, prompt: &str) -> f64 {
    let lower_content = content.to_ascii_lowercase();
    let mut seen = BTreeSet::new();
    let mut cjk_score: f64 = 0.0;
    let mut ascii_score: f64 = 0.0;
    for term in lexical_query_term_weights(prompt).keys() {
        if !seen.insert(term.clone()) || !assistant_run_reduced_query_term_is_signal(term) {
            continue;
        }
        let char_count = term.chars().count();
        if term.chars().all(|value| is_cjk_query_token_char(value)) {
            if char_count >= 2 && content.contains(term) {
                cjk_score += (0.018 * char_count.min(6) as f64).min(0.08);
            }
        } else if lower_content.contains(&term.to_ascii_lowercase()) {
            ascii_score += 0.018;
        }
    }
    cjk_score.min(0.24) + ascii_score.min(0.06)
}

fn retrieval_evidence_search_text(evidence: &RetrievalEvidence) -> String {
    let mut parts = Vec::new();
    for value in [
        evidence.summary.trim(),
        evidence.content_excerpt.trim(),
        evidence.source_locator.trim(),
        evidence.payload_filter_key.trim(),
    ] {
        if !value.is_empty() {
            parts.push(value.to_string());
        }
    }
    let mut section_title_hints = Vec::new();
    for pointer in [
        "/evidence/section_title_hints",
        "/section_title_hints",
        "/metadata/section_title_hints",
    ] {
        if let Some(value) = evidence.evidence_manifest.pointer(pointer) {
            collect_string_list(value, &mut section_title_hints);
        }
    }
    parts.extend(section_title_hints);
    parts.join("\n")
}

fn select_retrieval_evidence_ids_for_prompt(
    evidences: &[RetrievalEvidence],
    prompt: &str,
    limit: usize,
) -> Vec<RetrievalEvidenceId> {
    rank_retrieval_evidences_for_prompt(evidences, prompt, limit)
        .into_iter()
        .map(|ranked| ranked.evidence.id)
        .collect()
}

fn search_retrieval_hits(
    evidences: &[RetrievalEvidence],
    prompt: &str,
    limit: usize,
) -> Vec<RetrievalSearchHitView> {
    rank_retrieval_evidences_for_prompt(evidences, prompt, limit)
        .into_iter()
        .map(|ranked| RetrievalSearchHitView {
            retrieval_evidence_id: ranked.evidence.id,
            document_id: ranked.evidence.document_id,
            score: ranked.score,
            summary: ranked.evidence.summary.clone(),
            source_locator: ranked.evidence.source_locator.clone(),
        })
        .collect()
}

fn normalize_retrieval_search_limit(limit: Option<usize>) -> usize {
    limit
        .unwrap_or(RETRIEVAL_SEARCH_DEFAULT_LIMIT)
        .clamp(1, RETRIEVAL_SEARCH_MAX_LIMIT)
}

fn retrieval_search_scan_limit(limit: usize) -> i64 {
    let _ = limit;
    DATASET_OUTPUT_RETRIEVAL_SCAN_LIMIT
}

fn normalize_static_page_draft_list_limit(limit: Option<i64>) -> i64 {
    limit
        .unwrap_or(STATIC_PAGE_DRAFT_LIST_DEFAULT_LIMIT)
        .max(1)
        .min(STATIC_PAGE_DRAFT_LIST_MAX_LIMIT)
}

fn normalize_html_artifact_list_limit(limit: Option<i64>) -> i64 {
    limit
        .unwrap_or(HTML_ARTIFACT_LIST_DEFAULT_LIMIT)
        .max(1)
        .min(HTML_ARTIFACT_LIST_MAX_LIMIT)
}

fn collect_html_artifacts_from_events(
    events: &[AssistantRunEvent],
    artifacts: &mut Vec<HtmlArtifactManifestView>,
    limit: usize,
) {
    for event in events.iter().rev() {
        collect_html_artifacts_from_value(&event.payload, artifacts, limit);
        if artifacts.len() >= limit {
            break;
        }
    }
}

fn collect_html_artifacts_from_records(
    records: &[HtmlArtifact],
    artifacts: &mut Vec<HtmlArtifactManifestView>,
    limit: usize,
) {
    for record in records {
        if artifacts.len() >= limit {
            break;
        }
        if let Ok(manifest) =
            serde_json::from_value::<HtmlArtifactManifestView>(record.manifest.clone())
        {
            artifacts.push(manifest);
        }
    }
}

fn collect_html_artifacts_from_value(
    value: &Value,
    artifacts: &mut Vec<HtmlArtifactManifestView>,
    limit: usize,
) {
    if artifacts.len() >= limit {
        return;
    }

    match value {
        Value::Object(object) => {
            if let Some(entries) = object.get("html_artifacts").and_then(Value::as_array) {
                for entry in entries {
                    if artifacts.len() >= limit {
                        break;
                    }
                    if let Ok(manifest) =
                        serde_json::from_value::<HtmlArtifactManifestView>(entry.clone())
                    {
                        artifacts.push(manifest);
                    }
                }
            }

            for (key, child) in object {
                if key == "html_artifacts" {
                    continue;
                }
                collect_html_artifacts_from_value(child, artifacts, limit);
                if artifacts.len() >= limit {
                    break;
                }
            }
        }
        Value::Array(entries) => {
            for entry in entries {
                collect_html_artifacts_from_value(entry, artifacts, limit);
                if artifacts.len() >= limit {
                    break;
                }
            }
        }
        _ => {}
    }
}

fn sort_and_dedupe_html_artifacts(artifacts: &mut Vec<HtmlArtifactManifestView>) {
    artifacts.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| left.id.cmp(&right.id))
    });
    let mut seen = HashSet::<String>::new();
    artifacts.retain(|artifact| seen.insert(artifact.id.clone()));
}

#[derive(Debug)]
struct HtmlArtifactDownloadableFile {
    path: PathBuf,
    file_name: String,
    content_type: String,
}

fn html_artifact_downloadable_file(
    artifact: &HtmlArtifactManifestView,
    file_index: usize,
) -> std::result::Result<HtmlArtifactDownloadableFile, ApiError> {
    if !matches!(
        artifact.template_id,
        contracts::HtmlArtifactTemplateIdView::VideoExtractionSummary
            | contracts::HtmlArtifactTemplateIdView::ThirdPartyHandoffDocument
    ) {
        return Err(ApiError::bad_request(
            "html_artifact_file_download_unsupported",
            "this HTML artifact does not expose downloadable generated files".to_string(),
        ));
    }
    let generated_artifacts = artifact
        .payload
        .get("generated_artifacts")
        .or_else(|| artifact.payload.get("generatedArtifacts"))
        .ok_or_else(|| {
            ApiError::not_found(
                "html_artifact_file_not_found",
                "HTML artifact does not expose generated files".to_string(),
            )
        })?;
    let files = generated_artifacts
        .get("files")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            ApiError::not_found(
                "html_artifact_file_not_found",
                "HTML artifact generated file list is missing".to_string(),
            )
        })?;
    let file = files.get(file_index).ok_or_else(|| {
        ApiError::not_found(
            "html_artifact_file_not_found",
            format!("generated file index {file_index} was not found"),
        )
    })?;
    let raw_path = html_artifact_file_string(file, &["path"]).ok_or_else(|| {
        ApiError::not_found(
            "html_artifact_file_not_found",
            "generated file path is missing".to_string(),
        )
    })?;
    let target_path = html_artifact_safe_local_path(&raw_path)?;
    let canonical_target = fs::canonicalize(&target_path).map_err(|error| {
        ApiError::not_found(
            "html_artifact_file_unavailable",
            format!("generated file is not available: {error}"),
        )
    })?;
    let allowed_roots = html_artifact_allowed_generated_roots(generated_artifacts);
    if allowed_roots.is_empty()
        || !allowed_roots
            .iter()
            .any(|root| canonical_target.starts_with(root))
    {
        return Err(ApiError::bad_request(
            "html_artifact_file_path_denied",
            "generated file path is outside the artifact workspace".to_string(),
        ));
    }
    let file_name = html_artifact_download_file_name(file, &canonical_target);
    let content_type = html_artifact_file_string(file, &["format", "mime", "content_type"])
        .unwrap_or_else(|| "application/octet-stream".to_string());
    Ok(HtmlArtifactDownloadableFile {
        path: canonical_target,
        file_name,
        content_type,
    })
}

fn html_artifact_file_string(value: &Value, keys: &[&str]) -> Option<String> {
    keys.iter()
        .find_map(|key| value.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn html_artifact_safe_local_path(raw_path: &str) -> std::result::Result<PathBuf, ApiError> {
    let raw_path = raw_path.trim();
    if raw_path.contains("://") || raw_path.starts_with("\\\\") {
        return Err(ApiError::bad_request(
            "html_artifact_file_path_denied",
            "generated file path must be a local file path".to_string(),
        ));
    }
    let path = PathBuf::from(raw_path);
    if !path.is_absolute() {
        return Err(ApiError::bad_request(
            "html_artifact_file_path_denied",
            "generated file path must be absolute".to_string(),
        ));
    }
    Ok(path)
}

fn html_artifact_allowed_generated_roots(generated_artifacts: &Value) -> Vec<PathBuf> {
    ["artifacts_dir", "session_dir", "manifest_path"]
        .into_iter()
        .filter_map(|key| generated_artifacts.get(key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.contains("://") && !value.starts_with("\\\\"))
        .filter_map(|value| {
            let path = PathBuf::from(value);
            if !path.is_absolute() {
                return None;
            }
            let root = if path.is_file() {
                path.parent().map(PathBuf::from)?
            } else {
                path
            };
            fs::canonicalize(root).ok()
        })
        .collect()
}

fn html_artifact_download_file_name(file: &Value, path: &std::path::Path) -> String {
    let raw = html_artifact_file_string(file, &["file_name", "filename", "name"])
        .or_else(|| {
            path.file_name()
                .and_then(|value| value.to_str())
                .map(str::to_string)
        })
        .unwrap_or_else(|| "video-artifact.bin".to_string());
    let safe = raw
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '_') {
                ch
            } else {
                '_'
            }
        })
        .collect::<String>()
        .trim_matches('_')
        .to_string();
    if safe.is_empty() {
        "video-artifact.bin".to_string()
    } else {
        safe.chars().take(120).collect()
    }
}

async fn load_report_render_summary_artifacts_for_plan(
    state: &AppState,
    plan_id: ReportPlanId,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    limit: usize,
) -> std::result::Result<(ReportPlan, Vec<HtmlArtifactManifestView>), ApiError> {
    let plan = load_visible_report_plan_for_user(
        state,
        plan_id,
        active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    let outputs = state
        .storage
        .report_render_outputs()
        .list_by_plan(state.tenant_id, plan.id)
        .await
        .map_err(ApiError::from_storage)?;
    let mut artifacts = Vec::new();
    for output in outputs.into_iter().take(limit) {
        let output_view = hydrate_report_render_output_view(state, output).await?;
        artifacts.push(report_render_summary_artifact_from_view(
            &plan,
            &output_view,
        ));
    }
    Ok((plan, artifacts))
}

fn report_render_summary_artifact_from_view(
    plan: &ReportPlan,
    output: &ReportRenderOutputView,
) -> HtmlArtifactManifestView {
    let output_id = output.id.to_string();
    let asset_path = report_render_output_asset_path(output).unwrap_or_default();
    let asset_kind = report_render_output_asset_kind(output).unwrap_or_default();
    let publishable = output.status == contracts::ReportRenderOutputStatusView::Rendered
        && !asset_path.is_empty();
    let title = format!("{} · 渲染摘要", plan.title);
    let status = html_artifact_serialized_variant(&output.status);
    let artifact_manifest = external_channel_output_artifact_manifest(
        "report",
        "report_render_summary",
        &title,
        json!(status.clone()),
        None,
        Vec::new(),
        json!({
            "report_plan_id": plan.id,
            "report_render_output_id": output.id,
            "workflow_execution_id": output.execution_id,
            "ast_version_id": output.ast_version_id,
            "asset_kind": asset_kind,
            "asset_path_present": !asset_path.is_empty(),
        }),
        json!({
            "customer_visible": true,
            "credentials_exposed": false,
            "raw_logs_exposed": false,
            "publishable": publishable,
        }),
    );

    HtmlArtifactManifestView {
        kind: "html_artifact".to_string(),
        version: 1,
        id: format!("html-report-render-{output_id}"),
        title,
        source_type: contracts::HtmlArtifactSourceTypeView::Report,
        template_id: contracts::HtmlArtifactTemplateIdView::ReportRenderSummary,
        owner_scope: contracts::HtmlArtifactOwnerScopeView {
            scope_type: "report_render_output".to_string(),
            id: output_id.clone(),
        },
        data_refs: vec![
            contracts::HtmlArtifactDataRefView {
                kind: "report_plan".to_string(),
                id: plan.id.to_string(),
                label: "Report Plan".to_string(),
            },
            contracts::HtmlArtifactDataRefView {
                kind: "report_render_output".to_string(),
                id: output_id.clone(),
                label: "Render Output".to_string(),
            },
            contracts::HtmlArtifactDataRefView {
                kind: "workflow_execution".to_string(),
                id: output.execution_id.to_string(),
                label: "Workflow".to_string(),
            },
        ],
        provenance: contracts::HtmlArtifactProvenanceView {
            producer: "v3-report-runtime".to_string(),
            reason: "report render output summary".to_string(),
            source_run_id: None,
        },
        interaction_mode: HtmlArtifactInteractionModeView::ReadOnly,
        created_at: output.created_at,
        payload: json!({
            "reportTitle": plan.title,
            "objective": plan.objective,
            "surface": output.surface.as_str(),
            "status": status,
            "publishable": publishable,
            "assetPath": asset_path,
            "assetKind": asset_kind,
            "artifactManifest": artifact_manifest,
            "reportPlanId": plan.id,
            "reportRenderOutputId": output.id,
            "workflowExecutionId": output.execution_id,
            "astVersionId": output.ast_version_id,
            "modelFacing": output.model_facing,
            "serviceHandoff": output.service_handoff,
            "warnings": report_render_summary_warnings(output, publishable),
        }),
    }
}

fn report_render_summary_warnings(
    output: &ReportRenderOutputView,
    publishable: bool,
) -> Vec<Value> {
    if publishable {
        return Vec::new();
    }
    let (title, detail) = if output.status == contracts::ReportRenderOutputStatusView::Failed {
        (
            "渲染失败",
            "需要重试渲染或检查 report-render-worker 写回的 asset manifest。",
        )
    } else {
        (
            "尚不可发布",
            "报告还没有可发布资产路径，先等待渲染完成或重新发起渲染。",
        )
    };
    vec![json!({
        "title": title,
        "detail": detail,
    })]
}

fn wechat_video_login_handoff_artifact_from_prompt(
    _run_id: AssistantRunId,
    prompt: &str,
    _created_at: DateTime<Utc>,
) -> Option<HtmlArtifactManifestView> {
    let lower = prompt.to_ascii_lowercase();
    let mentions_wechat_video = lower.contains("weixin.qq.com/sph/")
        || lower.contains("channels.weixin.qq.com/sph/")
        || prompt.contains("视频号");
    let wants_slide_output = lower.contains("ppt")
        || lower.contains("powerpoint")
        || prompt.contains("课件")
        || prompt.contains("幻灯片")
        || (prompt.contains("提取") && prompt.contains("视频"));
    // Login-gated acquisition, QR login, cookies, and recording bypasses are out of scope.
    // The current slice only supports uploaded video files or directly/publicly resolvable video URLs.
    if mentions_wechat_video && wants_slide_output {
        return None;
    }
    None
}

async fn load_static_page_handoff_artifacts_for_run(
    state: &AppState,
    run_id: AssistantRunId,
    current_user_id: Option<UserId>,
    limit: usize,
) -> std::result::Result<Vec<HtmlArtifactManifestView>, ApiError> {
    let drafts = state
        .storage
        .static_page_drafts()
        .list_by_assistant_run(state.tenant_id, run_id)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(drafts
        .into_iter()
        .filter(|draft| static_page_owner_is_visible(draft.owner_user_id, current_user_id))
        .take(limit)
        .map(static_page_handoff_artifact_from_draft)
        .collect())
}

fn static_page_handoff_artifact_from_draft(draft: StaticPageDraft) -> HtmlArtifactManifestView {
    let draft_id = draft.id.to_string();
    let payload = &draft.draft_payload;
    let modules = static_page_payload_modules(payload)
        .as_array()
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .map(|module| {
            let data_binding = module
                .get("dataBinding")
                .or_else(|| module.get("data_binding"))
                .cloned()
                .unwrap_or(Value::Null);
            json!({
                "id": module.get("id").and_then(Value::as_str).unwrap_or_default(),
                "title": module.get("title").and_then(Value::as_str).unwrap_or_default(),
                "content": module.get("content").and_then(Value::as_str).unwrap_or_default(),
                "dataBinding": data_binding,
                "dataBindingLabel": data_binding
                    .get("label")
                    .or_else(|| data_binding.get("fieldPath"))
                    .or_else(|| data_binding.get("field"))
                    .and_then(Value::as_str)
                    .unwrap_or("待绑定"),
                "visualizationType": module
                    .get("visualization")
                    .and_then(|visualization| visualization.get("type"))
                    .or_else(|| module.get("visualizationType"))
                    .and_then(Value::as_str)
                    .unwrap_or("text"),
                "layout": module.get("layout").cloned().unwrap_or(Value::Null),
                "dataQuality": module
                    .get("dataQuality")
                    .or_else(|| module.get("dataQualityStatus"))
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
            })
        })
        .collect::<Vec<_>>();

    HtmlArtifactManifestView {
        kind: "html_artifact".to_string(),
        version: 1,
        id: format!("html-static-page-handoff-{draft_id}"),
        title: format!("{} · 交接", draft.title),
        source_type: contracts::HtmlArtifactSourceTypeView::StaticPage,
        template_id: contracts::HtmlArtifactTemplateIdView::StaticPagePlanningHandoff,
        owner_scope: contracts::HtmlArtifactOwnerScopeView {
            scope_type: "static_page_draft".to_string(),
            id: draft_id.clone(),
        },
        data_refs: Vec::new(),
        provenance: contracts::HtmlArtifactProvenanceView {
            producer: "v3-platform-api".to_string(),
            reason: "static page planning handoff".to_string(),
            source_run_id: Some(draft.assistant_run_id.to_string()),
        },
        interaction_mode: HtmlArtifactInteractionModeView::ActionIntent,
        created_at: draft.updated_at,
        payload: json!({
            "objective": draft.title,
            "status": draft.status.as_str(),
            "styleDirection": static_page_payload_string(payload, &["styleDirection", "style_direction"]).unwrap_or_default(),
            "defaultAction": "apply_static_page_intent",
            "intentPlaceholder": "例如：把趋势模块标题改成月度增长趋势，风险模块缩小一点，图表改为折线图。",
            "modules": modules,
            "visualBridge": static_page_visual_bridge_payload(payload)
        }),
    }
}

fn static_page_visual_bridge_payload(payload: &Value) -> Value {
    let preview_contract =
        static_page_payload_value(payload, &["previewContract", "preview_contract"])
            .unwrap_or(Value::Null);
    let preview_image = static_page_payload_value(payload, &["previewImage", "preview_image"])
        .unwrap_or(Value::Null);
    let image_job =
        static_page_payload_value(payload, &["imageJob", "image_job"]).unwrap_or(Value::Null);
    let final_page =
        static_page_payload_value(payload, &["finalPage", "final_page"]).unwrap_or(Value::Null);
    let render_spec =
        static_page_payload_value(payload, &["renderSpec", "render_spec"]).unwrap_or(Value::Null);

    json!({
        "providerLane": "gpt-image-2-cloudflare-queue",
        "role": "effect_preview_reference_only",
        "rule": "效果图只锁定视觉方向和确认指纹；最终 HTML 由 Draft JSON、DataSnapshot、VisualSpec 和 renderer 生成。",
        "status": static_page_value_string(&preview_contract, &["status"])
            .or_else(|| static_page_value_string(&image_job, &["status"]))
            .unwrap_or_else(|| "not_requested".to_string()),
        "imageJobStatus": static_page_value_string(&image_job, &["status"])
            .unwrap_or_else(|| "not_requested".to_string()),
        "imageJobId": static_page_value_string(&image_job, &["id"])
            .or_else(|| static_page_value_string(&preview_contract, &["imageJobId", "image_job_id"]))
            .or_else(|| static_page_value_string(&preview_image, &["imageJobId", "image_job_id"]))
            .unwrap_or_default(),
        "queuePosition": static_page_value_i64(&image_job, &["queuePosition", "queue_position"]),
        "queueMessage": static_page_value_string(&image_job, &["queueMessage", "queue_message"])
            .unwrap_or_default(),
        "previewAssetKey": static_page_value_string(&preview_image, &["assetKey", "asset_key"])
            .or_else(|| static_page_value_string(&preview_contract, &["assetKey", "asset_key"]))
            .or_else(|| static_page_value_string(&image_job, &["previewAssetKey", "preview_asset_key"]))
            .unwrap_or_default(),
        "previousAssetKey": static_page_value_string(&preview_contract, &["previousAssetKey", "previous_asset_key"])
            .unwrap_or_default(),
        "draftFingerprint": static_page_value_string(&preview_contract, &["draftFingerprint", "draft_fingerprint"])
            .unwrap_or_default(),
        "confirmedAt": static_page_value_string(&preview_contract, &["confirmedAt", "confirmed_at"])
            .unwrap_or_default(),
        "staleReason": static_page_value_string(&preview_contract, &["staleReason", "stale_reason"])
            .unwrap_or_default(),
        "styleDirection": static_page_payload_string(payload, &["styleDirection", "style_direction"])
            .unwrap_or_default(),
        "renderModel": static_page_value_string(&render_spec, &["componentModel", "component_model"])
            .or_else(|| {
                final_page
                    .get("assetManifest")
                    .or_else(|| final_page.get("asset_manifest"))
                    .and_then(|asset_manifest| {
                        asset_manifest
                            .get("render_spec")
                            .or_else(|| asset_manifest.get("renderSpec"))
                    })
                    .and_then(|render_spec| {
                        static_page_value_string(render_spec, &["componentModel", "component_model"])
                    })
            })
            .unwrap_or_default(),
        "finalRenderStatus": static_page_value_string(&final_page, &["status"])
            .unwrap_or_else(|| "not_requested".to_string())
    })
}

async fn load_static_page_data_quality_artifacts_for_run(
    state: &AppState,
    run_id: AssistantRunId,
    current_user_id: Option<UserId>,
    limit: usize,
) -> std::result::Result<Vec<HtmlArtifactManifestView>, ApiError> {
    let drafts = state
        .storage
        .static_page_drafts()
        .list_by_assistant_run(state.tenant_id, run_id)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(drafts
        .into_iter()
        .filter(|draft| static_page_owner_is_visible(draft.owner_user_id, current_user_id))
        .filter_map(static_page_data_quality_artifact_from_draft)
        .take(limit)
        .collect())
}

fn static_page_data_quality_artifact_from_draft(
    draft: StaticPageDraft,
) -> Option<HtmlArtifactManifestView> {
    let final_page = static_page_payload_value(&draft.draft_payload, &["finalPage", "final_page"])?;
    let asset_manifest = final_page
        .get("assetManifest")
        .or_else(|| final_page.get("asset_manifest"))?;
    let summary = static_page_final_data_quality_summary(asset_manifest)?;
    let modules = static_page_final_data_quality_modules(asset_manifest);
    if modules.is_empty()
        && !summary.as_object().is_some_and(|object| {
            object
                .values()
                .any(|value| value.as_i64().unwrap_or_default() > 0)
        })
    {
        return None;
    }

    let draft_id = draft.id.to_string();
    Some(HtmlArtifactManifestView {
        kind: "html_artifact".to_string(),
        version: 1,
        id: format!("html-static-page-quality-{draft_id}"),
        title: format!("{} · 数据质量报告", draft.title),
        source_type: contracts::HtmlArtifactSourceTypeView::StaticPage,
        template_id: contracts::HtmlArtifactTemplateIdView::StaticPageDataQualityReport,
        owner_scope: contracts::HtmlArtifactOwnerScopeView {
            scope_type: "static_page_draft".to_string(),
            id: draft_id.clone(),
        },
        data_refs: Vec::new(),
        provenance: contracts::HtmlArtifactProvenanceView {
            producer: "v3-static-page-renderer".to_string(),
            reason: "static page final render data quality report".to_string(),
            source_run_id: Some(draft.assistant_run_id.to_string()),
        },
        interaction_mode: HtmlArtifactInteractionModeView::ReadOnly,
        created_at: draft.updated_at,
        payload: json!({
            "draftId": draft_id,
            "finalStatus": final_page.get("status").and_then(Value::as_str).unwrap_or("unknown"),
            "summary": summary,
            "modules": modules,
            "note": "最终渲染数据质量报告用于交付前检查模块数据、ECharts 可水合状态和静态回退。"
        }),
    })
}

fn static_page_final_data_quality_summary(asset_manifest: &Value) -> Option<Value> {
    asset_manifest
        .get("export_package")
        .and_then(|package| package.get("debug"))
        .and_then(|debug| debug.get("data_quality_summary"))
        .cloned()
        .or_else(|| {
            asset_manifest
                .get("chart_runtime")
                .and_then(|runtime| runtime.get("dataQualitySummary"))
                .cloned()
        })
        .or_else(|| asset_manifest.get("data_quality_summary").cloned())
}

fn static_page_final_data_quality_modules(asset_manifest: &Value) -> Vec<Value> {
    asset_manifest
        .get("export_package")
        .and_then(|package| package.get("debug"))
        .and_then(|debug| debug.get("data_quality_modules"))
        .or_else(|| {
            asset_manifest
                .get("chart_runtime")
                .and_then(|runtime| runtime.get("modules"))
        })
        .or_else(|| asset_manifest.get("data_quality_modules"))
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .map(static_page_data_quality_module_payload)
                .collect()
        })
        .unwrap_or_default()
}

fn static_page_data_quality_module_payload(module: &Value) -> Value {
    json!({
        "moduleId": module.get("moduleId").or_else(|| module.get("module_id")).and_then(Value::as_str).unwrap_or_default(),
        "title": module.get("title").and_then(Value::as_str).unwrap_or("未命名模块"),
        "dataQuality": module.get("dataQuality").or_else(|| module.get("data_quality")).and_then(Value::as_str).unwrap_or("unknown"),
        "dataQualityStatus": module.get("dataQualityStatus").or_else(|| module.get("data_quality_status")).and_then(Value::as_str).unwrap_or("unknown"),
        "dataQualityReason": module.get("dataQualityReason").or_else(|| module.get("data_quality_reason")).and_then(Value::as_str).unwrap_or_default(),
        "recommendedAction": module.get("recommendedAction").or_else(|| module.get("recommended_action")).and_then(Value::as_str).unwrap_or_default(),
        "chartRuntime": module.get("chartRuntime").or_else(|| module.get("chart_runtime")).and_then(Value::as_str).unwrap_or("deterministic"),
        "fallback": module.get("fallback").and_then(Value::as_bool).unwrap_or(false),
        "sampleDataRows": module.get("sampleDataRows").or_else(|| module.get("sample_data_rows")).and_then(Value::as_i64).unwrap_or(0),
        "echartsHydratable": module.get("echartsHydratable").or_else(|| module.get("echarts_hydratable")).and_then(Value::as_bool).unwrap_or(false),
    })
}

struct CodeReviewSummaryArtifactCandidate {
    payload: Value,
    created_at: DateTime<Utc>,
    source_kind: &'static str,
    source_event_name: Option<String>,
    sequence_no: Option<i32>,
    source_index: usize,
}

async fn load_code_review_summary_artifacts_for_run(
    state: &AppState,
    run: &AssistantRun,
    limit: usize,
) -> std::result::Result<Vec<HtmlArtifactManifestView>, ApiError> {
    let events = state
        .storage
        .assistant_runs()
        .list_events(state.tenant_id, run.id)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(code_review_summary_artifacts_from_run_values(
        run, &events, limit,
    ))
}

fn code_review_summary_artifacts_from_run_values(
    run: &AssistantRun,
    events: &[AssistantRunEvent],
    limit: usize,
) -> Vec<HtmlArtifactManifestView> {
    let mut candidates = Vec::<CodeReviewSummaryArtifactCandidate>::new();
    for (source_index, artifact) in value_array(run.output_artifacts.clone())
        .into_iter()
        .enumerate()
    {
        assistant_run_collect_code_review_payloads(
            &artifact,
            false,
            &mut candidates,
            limit,
            run.updated_at,
            "assistant_run_output_artifact",
            None,
            None,
            source_index,
        );
        if candidates.len() >= limit {
            break;
        }
    }

    for event in events {
        if candidates.len() >= limit {
            break;
        }
        let force_marker = assistant_run_code_review_marker_text(&event.event_name);
        assistant_run_collect_code_review_payloads(
            &event.payload,
            force_marker,
            &mut candidates,
            limit,
            event.created_at,
            "assistant_run_event",
            Some(event.event_name.clone()),
            Some(event.sequence_no),
            event.sequence_no.max(0) as usize,
        );
    }

    let mut seen = HashSet::<String>::new();
    let mut artifacts = Vec::new();
    for candidate in candidates {
        if artifacts.len() >= limit {
            break;
        }
        let signature = code_review_summary_payload_signature(&candidate.payload);
        if !seen.insert(signature.clone()) {
            continue;
        }
        if let Some(artifact) =
            code_review_summary_artifact_from_candidate(run, candidate, &signature)
        {
            artifacts.push(artifact);
        }
    }
    sort_and_dedupe_html_artifacts(&mut artifacts);
    artifacts.truncate(limit);
    artifacts
}

#[allow(clippy::too_many_arguments)]
fn assistant_run_collect_code_review_payloads(
    value: &Value,
    force_marker: bool,
    candidates: &mut Vec<CodeReviewSummaryArtifactCandidate>,
    limit: usize,
    created_at: DateTime<Utc>,
    source_kind: &'static str,
    source_event_name: Option<String>,
    sequence_no: Option<i32>,
    source_index: usize,
) {
    if candidates.len() >= limit {
        return;
    }

    match value {
        Value::Object(object) => {
            if assistant_run_code_review_payload_candidate(value, force_marker) {
                candidates.push(CodeReviewSummaryArtifactCandidate {
                    payload: value.clone(),
                    created_at,
                    source_kind,
                    source_event_name,
                    sequence_no,
                    source_index,
                });
                return;
            }
            for (child_index, (key, child)) in object.iter().enumerate() {
                if key == "html_artifacts" {
                    continue;
                }
                assistant_run_collect_code_review_payloads(
                    child,
                    force_marker,
                    candidates,
                    limit,
                    created_at,
                    source_kind,
                    source_event_name.clone(),
                    sequence_no,
                    source_index.saturating_mul(100).saturating_add(child_index),
                );
                if candidates.len() >= limit {
                    break;
                }
            }
        }
        Value::Array(entries) => {
            for (child_index, entry) in entries.iter().enumerate() {
                assistant_run_collect_code_review_payloads(
                    entry,
                    force_marker,
                    candidates,
                    limit,
                    created_at,
                    source_kind,
                    source_event_name.clone(),
                    sequence_no,
                    source_index.saturating_mul(100).saturating_add(child_index),
                );
                if candidates.len() >= limit {
                    break;
                }
            }
        }
        _ => {}
    }
}

fn assistant_run_code_review_payload_candidate(value: &Value, force_marker: bool) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    let marker = [
        "type",
        "kind",
        "category",
        "artifact_type",
        "artifactType",
        "template_id",
        "templateId",
        "name",
    ]
    .iter()
    .filter_map(|key| object.get(*key).and_then(Value::as_str))
    .any(assistant_run_code_review_marker_text);
    let has_findings = ["findings", "issues", "items"].iter().any(|key| {
        object
            .get(*key)
            .and_then(Value::as_array)
            .is_some_and(|items| !items.is_empty())
    });
    let has_summary = code_review_payload_string(
        value,
        &["summary", "message", "description", "body", "conclusion"],
    )
    .is_some();
    marker || (force_marker && (has_findings || has_summary))
}

fn assistant_run_code_review_marker_text(value: &str) -> bool {
    let normalized = value
        .trim()
        .to_ascii_lowercase()
        .replace(['-', ' ', '.'], "_");
    normalized.contains("code_review")
        || normalized.contains("review_summary")
        || normalized.contains("code_review_summary")
}

fn code_review_summary_artifact_from_candidate(
    run: &AssistantRun,
    candidate: CodeReviewSummaryArtifactCandidate,
    signature: &str,
) -> Option<HtmlArtifactManifestView> {
    let findings = code_review_summary_findings(&candidate.payload);
    let summary = code_review_payload_string(
        &candidate.payload,
        &["summary", "message", "description", "body", "conclusion"],
    )
    .map(|value| html_artifact_safe_summary_text(&value, 900))
    .filter(|value| !value.is_empty())
    .unwrap_or_else(|| {
        if findings.is_empty() {
            String::new()
        } else {
            format!("本次代码审查归纳出 {} 个发现。", findings.len())
        }
    });
    if summary.is_empty() && findings.is_empty() {
        return None;
    }

    let title = code_review_payload_string(&candidate.payload, &["title", "name"])
        .map(|value| html_artifact_safe_summary_text(&value, 120))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "代码审查摘要".to_string());
    let signature_digest = sha256_hex([
        run.id.to_string().as_bytes(),
        b":",
        signature.as_bytes(),
        b":",
        candidate.source_kind.as_bytes(),
        b":",
        candidate.source_index.to_string().as_bytes(),
    ]);
    let artifact_id = format!("html-code-review-{}", &signature_digest[..16]);
    let run_id = run.id.to_string();
    let finding_count = findings.len();

    Some(HtmlArtifactManifestView {
        kind: "html_artifact".to_string(),
        version: 1,
        id: artifact_id,
        title,
        source_type: contracts::HtmlArtifactSourceTypeView::CodeReview,
        template_id: contracts::HtmlArtifactTemplateIdView::CodeReviewSummary,
        owner_scope: contracts::HtmlArtifactOwnerScopeView {
            scope_type: "assistant_run".to_string(),
            id: run_id.clone(),
        },
        data_refs: vec![contracts::HtmlArtifactDataRefView {
            kind: "assistant_run".to_string(),
            id: run_id.clone(),
            label: "Assistant Run".to_string(),
        }],
        provenance: contracts::HtmlArtifactProvenanceView {
            producer: "v3-platform-api".to_string(),
            reason: "code review summary synthesis".to_string(),
            source_run_id: Some(run_id),
        },
        interaction_mode: HtmlArtifactInteractionModeView::ReadOnly,
        created_at: candidate.created_at,
        payload: json!({
            "summary": summary,
            "findings": findings,
            "findingCount": finding_count,
            "sourceKind": candidate.source_kind,
            "sourceEventName": candidate
                .source_event_name
                .as_deref()
                .map(|value| html_artifact_safe_summary_text(value, 120))
                .unwrap_or_default(),
            "sourceSequenceNo": candidate.sequence_no,
            "modelGuidance": "这是 V3 从结构化代码审查输出中合成的只读摘要；如需执行修改，应重新进入受控 AssistantRun/Codex action 流程。"
        }),
    })
}

fn code_review_summary_findings(payload: &Value) -> Vec<Value> {
    ["findings", "issues", "items"]
        .iter()
        .find_map(|key| payload.get(*key).and_then(Value::as_array))
        .map(|items| {
            items
                .iter()
                .take(30)
                .filter_map(code_review_summary_finding_payload)
                .collect()
        })
        .unwrap_or_default()
}

fn code_review_summary_finding_payload(finding: &Value) -> Option<Value> {
    if let Some(text) = finding.as_str() {
        let title = html_artifact_safe_summary_text(text, 180);
        return (!title.is_empty()).then(|| {
            json!({
                "severity": "P?",
                "title": title,
                "detail": "",
                "file": "",
                "line": Value::Null,
            })
        });
    }

    let object = finding.as_object()?;
    let severity = code_review_payload_string(finding, &["severity", "priority", "level"])
        .map(|value| html_artifact_safe_summary_text(&value, 24))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "P?".to_string());
    let title = code_review_payload_string(finding, &["title", "message", "summary", "rule"])
        .map(|value| html_artifact_safe_summary_text(&value, 180))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| {
            code_review_payload_string(finding, &["file", "path"])
                .map(|value| html_artifact_safe_summary_text(&value, 180))
                .filter(|value| !value.is_empty())
                .unwrap_or_else(|| "问题".to_string())
        });
    let detail = code_review_payload_string(finding, &["detail", "body", "description"])
        .map(|value| html_artifact_safe_summary_text(&value, 700))
        .unwrap_or_default();
    let file = code_review_payload_string(finding, &["file", "path", "filename"])
        .map(|value| html_artifact_safe_summary_text(&value, 180))
        .unwrap_or_default();
    let line = [
        "line",
        "startLine",
        "start_line",
        "lineNumber",
        "line_number",
    ]
    .iter()
    .find_map(|key| object.get(*key).and_then(Value::as_u64));
    if title.is_empty() && detail.is_empty() && file.is_empty() {
        return None;
    }
    Some(json!({
        "severity": severity,
        "title": title,
        "detail": detail,
        "file": file,
        "line": line,
    }))
}

fn code_review_payload_string(payload: &Value, keys: &[&str]) -> Option<String> {
    keys.iter()
        .find_map(|key| {
            payload.get(*key).and_then(|value| match value {
                Value::String(text) => Some(text.trim().to_string()),
                Value::Number(number) => Some(number.to_string()),
                _ => None,
            })
        })
        .filter(|value| !value.is_empty())
}

fn code_review_summary_payload_signature(payload: &Value) -> String {
    let summary = code_review_payload_string(payload, &["summary", "message", "description"])
        .unwrap_or_default();
    let first_finding = ["findings", "issues", "items"]
        .iter()
        .find_map(|key| payload.get(*key).and_then(Value::as_array))
        .and_then(|items| items.first())
        .and_then(|finding| {
            code_review_payload_string(finding, &["title", "message", "summary", "file", "path"])
                .or_else(|| finding.as_str().map(ToOwned::to_owned))
        })
        .unwrap_or_default();
    format!("{summary}|{first_finding}")
}

fn html_artifact_safe_summary_text(value: &str, max_chars: usize) -> String {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return String::new();
    }
    let lowered = trimmed.to_ascii_lowercase();
    let unsafe_patterns = [
        "<script",
        "<iframe",
        "<object",
        "<embed",
        "<link",
        "<meta",
        "<form",
        "javascript:",
        "data:text/html",
        "srcdoc",
        "src=",
        "href=",
        "http://",
        "https://",
        "api_key",
        "api-key",
        "access_token",
        "access-token",
        "authorization",
        "bearer ",
        "cookie",
        "secret",
        "onerror=",
        "onclick=",
        "onload=",
    ];
    if unsafe_patterns
        .iter()
        .any(|pattern| lowered.contains(pattern))
    {
        return "[已移除敏感或不安全内容]".to_string();
    }
    let mut output = trimmed.chars().take(max_chars).collect::<String>();
    if trimmed.chars().count() > max_chars {
        output.push('…');
    }
    output
}

async fn load_html_artifacts_from_run_events(
    state: &AppState,
    run_id: AssistantRunId,
    limit: usize,
) -> std::result::Result<Vec<HtmlArtifactManifestView>, ApiError> {
    let events = state
        .storage
        .assistant_runs()
        .list_events(state.tenant_id, run_id)
        .await
        .map_err(ApiError::from_storage)?;
    let mut artifacts = Vec::<HtmlArtifactManifestView>::new();
    collect_html_artifacts_from_events(&events, &mut artifacts, limit);
    sort_and_dedupe_html_artifacts(&mut artifacts);
    artifacts.truncate(limit);
    Ok(artifacts)
}

async fn persist_html_artifacts_for_run(
    state: &AppState,
    run: &AssistantRun,
    artifacts: &[HtmlArtifactManifestView],
) -> std::result::Result<(), ApiError> {
    for artifact in artifacts {
        let manifest = serde_json::to_value(artifact).map_err(|error| {
            ApiError::internal(
                "html_artifact_serialize_failed",
                format!("failed to serialize HTML artifact manifest: {error}"),
            )
        })?;
        state
            .storage
            .html_artifacts()
            .upsert(
                state.tenant_id,
                &NewHtmlArtifact {
                    id: artifact.id.clone(),
                    owner_user_id: run.user_id,
                    assistant_run_id: Some(run.id),
                    local_thread_id: run.local_thread_id.clone(),
                    source_type: html_artifact_serialized_variant(&artifact.source_type),
                    template_id: html_artifact_serialized_variant(&artifact.template_id),
                    interaction_mode: html_artifact_serialized_variant(&artifact.interaction_mode),
                    manifest,
                    created_at: artifact.created_at,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
    }
    Ok(())
}

async fn persist_html_artifacts_for_report_plan(
    state: &AppState,
    plan: &ReportPlan,
    artifacts: &[HtmlArtifactManifestView],
) -> std::result::Result<(), ApiError> {
    for artifact in artifacts {
        let manifest = serde_json::to_value(artifact).map_err(|error| {
            ApiError::internal(
                "html_artifact_serialize_failed",
                format!("failed to serialize HTML artifact manifest: {error}"),
            )
        })?;
        state
            .storage
            .html_artifacts()
            .upsert(
                state.tenant_id,
                &NewHtmlArtifact {
                    id: artifact.id.clone(),
                    owner_user_id: plan.owner_user_id,
                    assistant_run_id: None,
                    local_thread_id: None,
                    source_type: html_artifact_serialized_variant(&artifact.source_type),
                    template_id: html_artifact_serialized_variant(&artifact.template_id),
                    interaction_mode: html_artifact_serialized_variant(&artifact.interaction_mode),
                    manifest,
                    created_at: artifact.created_at,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
    }
    Ok(())
}

fn html_artifact_serialized_variant<T: Serialize>(value: &T) -> String {
    serde_json::to_value(value)
        .ok()
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .unwrap_or_else(|| "unknown".to_string())
}

async fn load_html_artifact_from_record_for_run(
    state: &AppState,
    run_id: AssistantRunId,
    artifact_id: &str,
) -> std::result::Result<Option<HtmlArtifactManifestView>, ApiError> {
    let Some(record) = state
        .storage
        .html_artifacts()
        .get_by_id(state.tenant_id, artifact_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(None);
    };
    if record.assistant_run_id != Some(run_id) {
        return Ok(None);
    }
    let manifest =
        serde_json::from_value::<HtmlArtifactManifestView>(record.manifest).map_err(|error| {
            ApiError::internal(
                "html_artifact_manifest_invalid",
                format!("stored HTML artifact manifest is invalid: {error}"),
            )
        })?;
    Ok(Some(manifest))
}

async fn load_visible_html_artifact_for_submit(
    state: &AppState,
    current_user_id: Option<UserId>,
    artifact_id: &str,
    request: &SubmitHtmlArtifactEventRequest,
) -> std::result::Result<(AssistantRun, HtmlArtifactManifestView), ApiError> {
    if let Some(raw_run_id) = request
        .assistant_run_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let run_id = parse_assistant_run_id(raw_run_id)?;
        let run = load_visible_assistant_run_for_user(state, run_id, current_user_id).await?;
        if let Some(artifact) =
            load_html_artifact_from_record_for_run(state, run.id, artifact_id).await?
        {
            return Ok((run, artifact));
        }
        let artifact = load_html_artifact_from_run_events(state, run.id, artifact_id).await?;
        persist_html_artifacts_for_run(state, &run, std::slice::from_ref(&artifact)).await?;
        return Ok((run, artifact));
    }

    if let Some(local_thread_id) = request
        .local_thread_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let runs = state
            .storage
            .assistant_runs()
            .list_by_local_thread(
                state.tenant_id,
                local_thread_id,
                HTML_ARTIFACT_LIST_MAX_LIMIT,
            )
            .await
            .map_err(ApiError::from_storage)?;
        for run in runs
            .into_iter()
            .filter(|run| owner_user_id_is_visible(run.user_id, current_user_id))
        {
            if let Some(artifact) =
                load_html_artifact_from_record_for_run(state, run.id, artifact_id).await?
            {
                return Ok((run, artifact));
            }
            match load_html_artifact_from_run_events(state, run.id, artifact_id).await {
                Ok(artifact) => {
                    persist_html_artifacts_for_run(state, &run, std::slice::from_ref(&artifact))
                        .await?;
                    return Ok((run, artifact));
                }
                Err(error) if error.payload.code == "html_artifact_not_found" => continue,
                Err(error) => return Err(error),
            }
        }
    }

    Err(ApiError::not_found(
        "html_artifact_not_found",
        format!("html artifact {artifact_id} was not found"),
    ))
}

async fn load_html_artifact_from_run_events(
    state: &AppState,
    run_id: AssistantRunId,
    artifact_id: &str,
) -> std::result::Result<HtmlArtifactManifestView, ApiError> {
    load_html_artifacts_from_run_events(state, run_id, HTML_ARTIFACT_LIST_MAX_LIMIT as usize)
        .await?
        .into_iter()
        .find(|artifact| artifact.id == artifact_id)
        .ok_or_else(|| {
            ApiError::not_found(
                "html_artifact_not_found",
                format!("html artifact {artifact_id} was not found"),
            )
        })
}

fn validate_html_artifact_event_request(
    artifact: &HtmlArtifactManifestView,
    request: &SubmitHtmlArtifactEventRequest,
) -> std::result::Result<(), ApiError> {
    let event_type = request.event_type.trim();
    match &artifact.interaction_mode {
        HtmlArtifactInteractionModeView::ReadOnly => {
            return Err(ApiError::bad_request(
                "html_artifact_read_only",
                "read-only HTML artifacts cannot submit events".to_string(),
            ));
        }
        HtmlArtifactInteractionModeView::JsonPatch if event_type != "html_artifact.patch" => {
            return Err(ApiError::bad_request(
                "html_artifact_event_type_mismatch",
                "json_patch artifacts may only submit html_artifact.patch".to_string(),
            ));
        }
        HtmlArtifactInteractionModeView::ActionIntent
            if event_type != "html_artifact.action_intent" =>
        {
            return Err(ApiError::bad_request(
                "html_artifact_event_type_mismatch",
                "action_intent artifacts may only submit html_artifact.action_intent".to_string(),
            ));
        }
        _ => {}
    }

    validate_html_artifact_event_payload_is_safe(&request.payload, "$")?;
    if event_type == "html_artifact.patch" {
        validate_html_artifact_patch_payload(&request.payload)?;
    } else {
        validate_html_artifact_action_intent_payload(&request.payload)?;
    }
    Ok(())
}

async fn apply_html_artifact_event_to_product(
    state: &AppState,
    current_user_id: Option<UserId>,
    run: &AssistantRun,
    artifact: &HtmlArtifactManifestView,
    request: &SubmitHtmlArtifactEventRequest,
) -> std::result::Result<Option<Value>, ApiError> {
    if request.event_type.trim() != "html_artifact.patch" {
        return apply_html_artifact_action_intent_to_product(
            state,
            current_user_id,
            run,
            artifact,
            request,
        )
        .await;
    }
    if !matches!(
        artifact.source_type,
        contracts::HtmlArtifactSourceTypeView::StaticPage
    ) || !matches!(
        artifact.template_id,
        contracts::HtmlArtifactTemplateIdView::StaticPagePlanningHandoff
    ) {
        return Ok(None);
    }
    if artifact.owner_scope.scope_type != "static_page_draft" {
        return Ok(None);
    }

    let draft_id = parse_static_page_draft_id(&artifact.owner_scope.id)?;
    let mut draft = load_visible_static_page_draft(state, draft_id, current_user_id).await?;
    if draft.assistant_run_id != run.id {
        return Err(ApiError::bad_request(
            "html_artifact_owner_mismatch",
            "HTML artifact owner scope does not match the assistant run".to_string(),
        ));
    }

    let operations =
        static_page_operations_from_html_artifact_patch(&draft.draft_payload, &request.payload)?;
    if operations.is_empty() {
        return Err(ApiError::bad_request(
            "html_artifact_patch_noop",
            "HTML artifact patch did not contain supported static page changes".to_string(),
        ));
    }

    let summary = format!("已从 HTML 产物应用 {} 个静态页修改。", operations.len());
    let mut draft_payload = apply_static_page_operations_to_payload(
        draft.draft_payload.clone(),
        &operations,
        Some(&summary),
    );
    finalize_static_page_operations_payload(
        &mut draft_payload,
        &operations,
        Some("html_artifact.patch"),
        &summary,
    );
    draft.status = status_from_static_page_payload(&draft_payload)
        .or_else(|| status_from_static_page_operations(&operations))
        .unwrap_or(StaticPageDraftStatus::Planned);
    draft.draft_payload = draft_payload;

    let updated = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &updated,
        "static_page_draft.html_artifact_patch_applied",
        json!({
            "draft_id": updated.id,
            "artifact_id": artifact.id,
            "operation_count": operations.len(),
            "summary": summary,
        }),
    )
    .await?;

    Ok(Some(json!({
        "status": "applied",
        "target_type": "static_page_draft",
        "draft_id": updated.id,
        "operation_count": operations.len(),
        "summary": summary,
    })))
}

async fn apply_html_artifact_action_intent_to_product(
    state: &AppState,
    current_user_id: Option<UserId>,
    run: &AssistantRun,
    artifact: &HtmlArtifactManifestView,
    request: &SubmitHtmlArtifactEventRequest,
) -> std::result::Result<Option<Value>, ApiError> {
    if request.event_type.trim() != "html_artifact.action_intent" {
        return Ok(None);
    }
    if !matches!(
        artifact.source_type,
        contracts::HtmlArtifactSourceTypeView::StaticPage
    ) || !matches!(
        artifact.template_id,
        contracts::HtmlArtifactTemplateIdView::StaticPagePlanningHandoff
    ) {
        return Ok(None);
    }
    if artifact.owner_scope.scope_type != "static_page_draft" {
        return Ok(None);
    }

    let prompt = html_artifact_action_intent_prompt(&request.payload)?;
    let draft_id = parse_static_page_draft_id(&artifact.owner_scope.id)?;
    let mut draft = load_visible_static_page_draft(state, draft_id, current_user_id).await?;
    if draft.assistant_run_id != run.id {
        return Err(ApiError::bad_request(
            "html_artifact_owner_mismatch",
            "HTML artifact owner scope does not match the assistant run".to_string(),
        ));
    }

    let intent = interpret_static_page_draft_intent_for_api(
        state,
        &draft,
        &prompt,
        &draft.draft_payload,
        Vec::new(),
    )
    .await?;
    if intent.operations.is_empty() {
        return Err(ApiError::bad_request(
            "html_artifact_action_intent_noop",
            "HTML artifact action intent did not produce static page changes".to_string(),
        ));
    }

    let mut draft_payload = apply_static_page_operations_to_payload(
        draft.draft_payload.clone(),
        &intent.operations,
        Some(&intent.summary),
    );
    finalize_static_page_operations_payload(
        &mut draft_payload,
        &intent.operations,
        Some(&prompt),
        &intent.summary,
    );
    draft.status = status_from_static_page_payload(&draft_payload)
        .or_else(|| status_from_static_page_operations(&intent.operations))
        .unwrap_or(StaticPageDraftStatus::Planned);
    draft.draft_payload = draft_payload;

    let updated = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &updated,
        "static_page_draft.html_artifact_intent_applied",
        json!({
            "draft_id": updated.id,
            "artifact_id": artifact.id,
            "prompt": prompt,
            "operation_count": intent.operations.len(),
            "summary": intent.summary,
            "runtime": intent.runtime,
        }),
    )
    .await?;

    Ok(Some(json!({
        "status": "applied",
        "target_type": "static_page_draft",
        "draft_id": updated.id,
        "operation_count": intent.operations.len(),
        "summary": intent.summary,
        "runtime": intent.runtime,
    })))
}

fn html_artifact_action_intent_prompt(payload: &Value) -> std::result::Result<String, ApiError> {
    let object = payload.as_object().ok_or_else(|| {
        ApiError::bad_request(
            "html_artifact_invalid_action_intent",
            "action_intent payload must be an object".to_string(),
        )
    })?;
    for key in ["prompt", "instruction", "message", "text", "note"] {
        if let Some(prompt) = object
            .get(key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            if prompt.chars().count() > 2000 {
                return Err(ApiError::bad_request(
                    "html_artifact_invalid_action_intent",
                    "action_intent prompt is too long".to_string(),
                ));
            }
            return Ok(prompt.to_string());
        }
    }
    Err(ApiError::bad_request(
        "html_artifact_invalid_action_intent",
        "action_intent payload requires prompt, instruction, message, text, or note".to_string(),
    ))
}

fn static_page_operations_from_html_artifact_patch(
    draft_payload: &Value,
    payload: &Value,
) -> std::result::Result<Vec<Value>, ApiError> {
    let operations = html_artifact_patch_operations(payload)?;
    let mut translated = Vec::new();
    for operation in operations {
        if let Some(translated_operation) =
            static_page_operation_from_html_patch_operation(draft_payload, operation)?
        {
            translated.push(translated_operation);
        }
    }
    validate_static_page_operations(translated)
}

fn html_artifact_patch_operations(payload: &Value) -> std::result::Result<&[Value], ApiError> {
    payload
        .as_object()
        .and_then(|object| object.get("operations").or_else(|| object.get("patch")))
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .ok_or_else(|| {
            ApiError::bad_request(
                "html_artifact_invalid_patch",
                "patch payload.operations must be an array".to_string(),
            )
        })
}

fn static_page_operation_from_html_patch_operation(
    draft_payload: &Value,
    operation: &Value,
) -> std::result::Result<Option<Value>, ApiError> {
    let object = operation.as_object().ok_or_else(|| {
        ApiError::bad_request(
            "html_artifact_invalid_patch",
            "each patch operation must be an object".to_string(),
        )
    })?;
    let op = object
        .get("op")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or_default();
    if !matches!(op, "add" | "replace" | "remove") {
        return Err(ApiError::bad_request(
            "html_artifact_patch_operation_unsupported",
            format!("{op} cannot be executed against static page drafts"),
        ));
    }
    let path = object
        .get("path")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or_default();
    let tokens = decode_html_artifact_json_pointer(path)?;
    let value = if op == "remove" {
        Value::Null
    } else {
        object.get("value").cloned().ok_or_else(|| {
            ApiError::bad_request(
                "html_artifact_invalid_patch",
                "add/replace patch operations require value".to_string(),
            )
        })?
    };

    match tokens.as_slice() {
        [field] if field == "styleDirection" || field == "style_direction" => {
            html_patch_string_value(&value, "styleDirection")?;
            Ok(Some(json!({
                "type": "change_style_direction",
                "styleDirection": value,
            })))
        }
        [field] if field == "mobileOrder" || field == "mobile_order" => {
            if !value.is_array() {
                return Err(ApiError::bad_request(
                    "html_artifact_patch_value_invalid",
                    "mobileOrder must be an array".to_string(),
                ));
            }
            Ok(Some(json!({
                "type": "reorder_modules",
                "order": value,
            })))
        }
        [modules, module_selector, field @ ..] if modules == "modules" => {
            let module_id =
                static_page_module_id_from_patch_selector(draft_payload, module_selector)?;
            let operation = static_page_module_operation_from_html_patch(
                draft_payload,
                &module_id,
                field,
                value,
            )?;
            Ok(Some(operation))
        }
        _ => Err(ApiError::bad_request(
            "html_artifact_patch_target_unsupported",
            format!("{path} is not a supported static page patch path"),
        )),
    }
}

fn decode_html_artifact_json_pointer(path: &str) -> std::result::Result<Vec<String>, ApiError> {
    if !path.starts_with('/') {
        return Err(ApiError::bad_request(
            "html_artifact_invalid_patch",
            "patch operation path must be a JSON pointer".to_string(),
        ));
    }
    Ok(path
        .split('/')
        .skip(1)
        .map(|token| token.replace("~1", "/").replace("~0", "~"))
        .collect())
}

fn static_page_module_id_from_patch_selector(
    draft_payload: &Value,
    selector: &str,
) -> std::result::Result<String, ApiError> {
    let modules = draft_payload
        .get("modules")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            ApiError::bad_request(
                "html_artifact_patch_target_missing",
                "static page draft has no modules".to_string(),
            )
        })?;
    if let Ok(index) = selector.parse::<usize>() {
        return modules
            .get(index)
            .and_then(|module| module.get("id"))
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
            .ok_or_else(|| {
                ApiError::bad_request(
                    "html_artifact_patch_target_missing",
                    format!("module index {index} was not found"),
                )
            });
    }
    if modules.iter().any(|module| {
        module
            .get("id")
            .and_then(Value::as_str)
            .is_some_and(|id| id == selector)
    }) {
        return Ok(selector.to_string());
    }
    Err(ApiError::bad_request(
        "html_artifact_patch_target_missing",
        format!("module {selector} was not found"),
    ))
}

fn static_page_module_operation_from_html_patch(
    draft_payload: &Value,
    module_id: &str,
    field: &[String],
    value: Value,
) -> std::result::Result<Value, ApiError> {
    let Some(root) = field.first().map(String::as_str) else {
        return Err(ApiError::bad_request(
            "html_artifact_patch_target_unsupported",
            "module patch path must include a field".to_string(),
        ));
    };
    let patch = match root {
        "title" | "content" | "dataLabel" if field.len() == 1 => json!({ root: value }),
        "data_binding" if field.len() == 1 => json!({ "dataBinding": value }),
        "dataBinding" if field.len() == 1 => json!({ "dataBinding": value }),
        "dataBinding" | "data_binding" => {
            if field.len() != 2 {
                return Err(ApiError::bad_request(
                    "html_artifact_patch_target_unsupported",
                    "dataBinding patch paths may only target one field".to_string(),
                ));
            }
            let key = normalize_static_page_nested_patch_key(root, &field[1])?;
            let object = merge_static_page_current_module_object_field(
                draft_payload,
                module_id,
                "dataBinding",
                &key,
                value,
            );
            json!({ "dataBinding": object })
        }
        "visualizationType" if field.len() == 1 => {
            html_patch_string_value(&value, "visualizationType")?;
            json!({ "visualization": { "type": value } })
        }
        "visualization" if field.len() == 1 => json!({ "visualization": value }),
        "visualization" => {
            if field.len() != 2 {
                return Err(ApiError::bad_request(
                    "html_artifact_patch_target_unsupported",
                    "visualization patch paths may only target one field".to_string(),
                ));
            }
            let key = normalize_static_page_nested_patch_key(root, &field[1])?;
            let object = merge_static_page_current_module_object_field(
                draft_payload,
                module_id,
                "visualization",
                &key,
                value,
            );
            json!({ "visualization": object })
        }
        "chartRuntime" if field.len() == 1 => json!({ "chartRuntime": value }),
        "chartOptions" if field.len() == 1 => json!({ "chartOptions": value }),
        "layout" if field.len() == 1 => {
            validate_html_artifact_layout_patch(&value)?;
            json!({ "layout": value })
        }
        "layout" => {
            if field.len() != 2 {
                return Err(ApiError::bad_request(
                    "html_artifact_patch_target_unsupported",
                    "layout patch paths may only target one field".to_string(),
                ));
            }
            let key = field[1].as_str();
            if !matches!(key, "x" | "y" | "w" | "h") {
                return Err(ApiError::bad_request(
                    "html_artifact_patch_target_unsupported",
                    format!("layout.{key} cannot be patched"),
                ));
            }
            validate_html_artifact_layout_number(&value, key)?;
            let object = merge_static_page_current_module_object_field(
                draft_payload,
                module_id,
                "layout",
                key,
                value,
            );
            let layout_value = Value::Object(object);
            validate_html_artifact_layout_patch(&layout_value)?;
            json!({ "layout": layout_value })
        }
        _ => {
            return Err(ApiError::bad_request(
                "html_artifact_patch_target_unsupported",
                format!("modules/{module_id}/{root} cannot be patched"),
            ))
        }
    };
    Ok(json!({
        "type": "update_module",
        "targetModuleId": module_id,
        "patch": patch,
    }))
}

fn normalize_static_page_nested_patch_key(
    parent: &str,
    key: &str,
) -> std::result::Result<String, ApiError> {
    let normalized = match (parent, key) {
        ("data_binding", "source_id") | ("dataBinding", "source_id") => "sourceId",
        ("data_binding", "field_path") | ("dataBinding", "field_path") => "fieldPath",
        ("data_binding", "evidence_ids") | ("dataBinding", "evidence_ids") => "evidenceIds",
        ("visualization", "chart_runtime") => "chartRuntime",
        ("visualization", "chart_options") => "chartOptions",
        ("visualization", "sample_data") => "sampleData",
        _ => key,
    };
    Ok(normalized.to_string())
}

fn merge_static_page_current_module_object_field(
    draft_payload: &Value,
    module_id: &str,
    field: &str,
    key: &str,
    value: Value,
) -> Map<String, Value> {
    let mut object = draft_payload
        .get("modules")
        .and_then(Value::as_array)
        .and_then(|modules| {
            modules.iter().find(|module| {
                module
                    .get("id")
                    .and_then(Value::as_str)
                    .is_some_and(|id| id == module_id)
            })
        })
        .and_then(|module| module.get(field))
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    object.insert(key.to_string(), value);
    object
}

fn html_patch_string_value(value: &Value, field_name: &str) -> std::result::Result<(), ApiError> {
    if value
        .as_str()
        .map(str::trim)
        .is_some_and(|value| !value.is_empty())
    {
        return Ok(());
    }
    Err(ApiError::bad_request(
        "html_artifact_patch_value_invalid",
        format!("{field_name} must be a non-empty string"),
    ))
}

fn validate_html_artifact_layout_patch(value: &Value) -> std::result::Result<(), ApiError> {
    let Some(object) = value.as_object() else {
        return Err(ApiError::bad_request(
            "html_artifact_patch_value_invalid",
            "layout patch must be an object".to_string(),
        ));
    };
    for (key, value) in object {
        if !matches!(key.as_str(), "x" | "y" | "w" | "h") {
            return Err(ApiError::bad_request(
                "html_artifact_patch_target_unsupported",
                format!("layout.{key} cannot be patched"),
            ));
        }
        validate_html_artifact_layout_number(value, key)?;
    }
    Ok(())
}

fn validate_html_artifact_layout_number(
    value: &Value,
    field_name: &str,
) -> std::result::Result<(), ApiError> {
    let Some(number) = value.as_f64() else {
        return Err(ApiError::bad_request(
            "html_artifact_patch_value_invalid",
            format!("layout.{field_name} must be a number"),
        ));
    };
    let valid = match field_name {
        "x" | "y" => (0.0..=100.0).contains(&number),
        "w" | "h" => (1.0..=100.0).contains(&number),
        _ => false,
    };
    if valid {
        Ok(())
    } else {
        Err(ApiError::bad_request(
            "html_artifact_patch_value_invalid",
            format!("layout.{field_name} is outside the supported range"),
        ))
    }
}

fn validate_html_artifact_action_intent_payload(
    payload: &Value,
) -> std::result::Result<(), ApiError> {
    let action = payload
        .as_object()
        .and_then(|object| object.get("action"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            ApiError::bad_request(
                "html_artifact_invalid_action_intent",
                "action_intent payload.action is required".to_string(),
            )
        })?;
    if action.chars().count() > 120 {
        return Err(ApiError::bad_request(
            "html_artifact_invalid_action_intent",
            "action_intent payload.action is too long".to_string(),
        ));
    }
    Ok(())
}

fn validate_html_artifact_patch_payload(payload: &Value) -> std::result::Result<(), ApiError> {
    let Some(object) = payload.as_object() else {
        return Err(ApiError::bad_request(
            "html_artifact_invalid_patch",
            "patch payload must be an object".to_string(),
        ));
    };
    let operations = object
        .get("operations")
        .or_else(|| object.get("patch"))
        .and_then(Value::as_array)
        .ok_or_else(|| {
            ApiError::bad_request(
                "html_artifact_invalid_patch",
                "patch payload.operations must be an array".to_string(),
            )
        })?;
    if operations.is_empty() || operations.len() > 50 {
        return Err(ApiError::bad_request(
            "html_artifact_invalid_patch",
            "patch operations must contain 1-50 operations".to_string(),
        ));
    }

    for operation in operations {
        let Some(operation_object) = operation.as_object() else {
            return Err(ApiError::bad_request(
                "html_artifact_invalid_patch",
                "each patch operation must be an object".to_string(),
            ));
        };
        let op = operation_object
            .get("op")
            .and_then(Value::as_str)
            .map(str::trim)
            .unwrap_or_default();
        if !matches!(op, "add" | "replace" | "remove" | "move" | "copy" | "test") {
            return Err(ApiError::bad_request(
                "html_artifact_invalid_patch",
                format!("{op} is not an allowed patch operation"),
            ));
        }
        let path = operation_object
            .get("path")
            .and_then(Value::as_str)
            .map(str::trim)
            .unwrap_or_default();
        if !path.starts_with('/') || path.chars().count() > 240 {
            return Err(ApiError::bad_request(
                "html_artifact_invalid_patch",
                "patch operation path must be a JSON pointer under 240 chars".to_string(),
            ));
        }
        if matches!(op, "move" | "copy") {
            let from = operation_object
                .get("from")
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or_default();
            if !from.starts_with('/') || from.chars().count() > 240 {
                return Err(ApiError::bad_request(
                    "html_artifact_invalid_patch",
                    "move/copy patch operation requires a valid from JSON pointer".to_string(),
                ));
            }
        }
    }
    Ok(())
}

fn validate_html_artifact_event_payload_is_safe(
    value: &Value,
    path: &str,
) -> std::result::Result<(), ApiError> {
    match value {
        Value::String(text) => validate_html_artifact_safe_string(text, path),
        Value::Array(entries) => {
            if entries.len() > 100 {
                return Err(ApiError::bad_request(
                    "html_artifact_payload_too_large",
                    format!("{path} contains too many entries"),
                ));
            }
            for (index, entry) in entries.iter().enumerate() {
                validate_html_artifact_event_payload_is_safe(entry, &format!("{path}[{index}]"))?;
            }
            Ok(())
        }
        Value::Object(object) => {
            if object.len() > 80 {
                return Err(ApiError::bad_request(
                    "html_artifact_payload_too_large",
                    format!("{path} contains too many fields"),
                ));
            }
            for (key, child) in object {
                validate_html_artifact_safe_string(key, &format!("{path}.{key}"))?;
                validate_html_artifact_event_payload_is_safe(child, &format!("{path}.{key}"))?;
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

fn validate_html_artifact_safe_string(text: &str, path: &str) -> std::result::Result<(), ApiError> {
    if text.chars().count() > 4000 {
        return Err(ApiError::bad_request(
            "html_artifact_payload_too_large",
            format!("{path} is too long"),
        ));
    }
    let lowered = text.to_ascii_lowercase();
    let unsafe_patterns = [
        "<script",
        "<iframe",
        "<object",
        "<embed",
        "<link",
        "<meta",
        "<form",
        "javascript:",
        "data:text/html",
        "srcdoc",
        "http://",
        "https://",
        "api_key",
        "access_token",
        "authorization",
        "bearer ",
        "cookie",
        "secret",
        "onerror=",
        "onclick=",
        "onload=",
    ];
    if let Some(pattern) = unsafe_patterns
        .iter()
        .find(|pattern| lowered.contains(**pattern))
    {
        return Err(ApiError::bad_request(
            "html_artifact_unsafe_payload",
            format!("{path} contains unsafe content: {pattern}"),
        ));
    }
    Ok(())
}

fn sort_retrieval_evidences_by_relevance(evidences: &mut [RetrievalEvidence]) {
    evidences.sort_by(|left, right| {
        right
            .recall_score
            .partial_cmp(&left.recall_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| {
                rank_hint_from_evidence_manifest(left)
                    .unwrap_or(usize::MAX)
                    .cmp(&rank_hint_from_evidence_manifest(right).unwrap_or(usize::MAX))
            })
            .then_with(|| left.chunk_index.cmp(&right.chunk_index))
            .then_with(|| right.created_at.cmp(&left.created_at))
    });
}

fn lexical_query_score(
    evidence: &RetrievalEvidence,
    query_weights: &BTreeMap<String, f64>,
    query_norm: f64,
) -> f64 {
    if query_weights.is_empty() || query_norm <= 0.0 {
        return 0.0;
    }

    let evidence_weights = evidence_term_weights_from_manifest(evidence);
    let evidence_norm = vector_norm(&evidence_weights);
    if evidence_weights.is_empty() || evidence_norm <= 0.0 {
        return 0.0;
    }

    let dot_product = query_weights
        .iter()
        .filter_map(|(term, query_weight)| {
            evidence_weights
                .get(term)
                .map(|evidence_weight| query_weight * evidence_weight)
        })
        .sum::<f64>();
    if dot_product <= 0.0 {
        return 0.0;
    }

    (dot_product / (query_norm * evidence_norm) * 10_000.0).round() / 10_000.0
}

fn lexical_text_score(
    content: &str,
    query_weights: &BTreeMap<String, f64>,
    query_norm: f64,
) -> f64 {
    if query_weights.is_empty() || query_norm <= 0.0 {
        return 0.0;
    }

    let content_weights = lexical_query_term_weights(content);
    let content_norm = vector_norm(&content_weights);
    if content_weights.is_empty() || content_norm <= 0.0 {
        return 0.0;
    }

    let dot_product = query_weights
        .iter()
        .filter_map(|(term, query_weight)| {
            content_weights
                .get(term)
                .map(|content_weight| query_weight * content_weight)
        })
        .sum::<f64>();
    if dot_product <= 0.0 {
        return 0.0;
    }

    (dot_product / (query_norm * content_norm) * 10_000.0).round() / 10_000.0
}

fn lexical_domain_hint_score(content: &str, query: &str) -> f64 {
    let medication_dispense_query = query.contains("发药")
        || query.contains("服药")
        || query.contains("用药")
        || query.contains("药品")
        || (query.contains("药") && (query.contains("核对") || query.contains("发放")));
    let elder_fall_query = prompt_contains_elder_fall_signal(query);
    let elder_death_query = prompt_contains_elder_death_signal(query);
    let nursing_handover_query = prompt_contains_nursing_handover_signal(query);
    if !medication_dispense_query
        && !elder_fall_query
        && !elder_death_query
        && !nursing_handover_query
    {
        return 0.0;
    }
    if content.contains("................................................................") {
        return 0.0;
    }

    let mut score = 0.0;
    if medication_dispense_query
        && (content.contains("老人自带药品管理规范")
            || content.contains("老年人自带药品")
            || content.contains("药品发放人员")
            || content.contains("2.4 发药")
            || (content.contains("备药") && content.contains("发药")))
    {
        score += 0.5;
    } else if medication_dispense_query
        && (content.contains("药品委托发放") || content.contains("药品统一管理风险告知"))
    {
        score += 0.25;
    } else if medication_dispense_query
        && (content.contains("协助老年人用药") || content.contains("用药安全"))
    {
        score += 0.12;
    }

    if medication_dispense_query
        && (query.contains("核对") || query.contains("查对"))
        && (content.contains("核对信息")
            || content.contains("核对确认")
            || content.contains("药品名称")
            || content.contains("药品使用剂量"))
    {
        score += 0.2;
    }

    if elder_fall_query {
        if content.contains("老年人人身意外伤害")
            || content.contains("突发事件应急预防与处置")
            || content.contains("典型突发事件应急处置")
            || content.contains("事故处理与报告")
            || content.contains("事故处理")
        {
            score += 0.65;
        } else if content.contains("防跌倒")
            || content.contains("跌倒")
            || content.contains("坠床")
            || content.contains("骨折")
            || content.contains("摔伤")
        {
            score += 0.25;
        }
        if prompt_requests_procedure_or_action(query)
            && (content.contains("120")
                || content.contains("通知")
                || content.contains("报告")
                || content.contains("记录")
                || content.contains("转院")
                || content.contains("医护人员"))
        {
            score += 0.3;
        }
    }

    if elder_death_query {
        if content.contains("离世")
            || content.contains("去世")
            || content.contains("死亡")
            || content.contains("身故")
            || content.contains("病故")
            || content.contains("善后")
            || content.contains("遗体")
            || content.contains("殡仪")
            || content.contains("殡葬")
        {
            score += 0.65;
        }
        if prompt_requests_procedure_or_action(query)
            && (content.contains("生命体征")
                || content.contains("医护确认")
                || content.contains("通知家属")
                || content.contains("联系家属")
                || content.contains("保护现场")
                || content.contains("遗物")
                || content.contains("交接")
                || content.contains("记录")
                || content.contains("归档"))
        {
            score += 0.35;
        }
    }

    if nursing_handover_query {
        if content.contains("四、交接内容")
            || content.contains("护理记录单")
            || content.contains("晨会交接记录本")
            || content.contains("交班护理员")
            || content.contains("接班护理员")
        {
            score += 0.75;
        } else if content.contains("交接班制度")
            || content.contains("交接及处置记录")
            || content.contains("床旁交接班")
        {
            score += 0.2;
        }

        if content.contains("药物服用情况")
            || content.contains("身体异常状况")
            || content.contains("情绪异常状况")
            || content.contains("皮肤受压情况")
            || content.contains("管路通畅")
        {
            score += 0.35;
        }
    }

    score
}

fn limited_lexical_term_weights(content: &str, limit: usize) -> BTreeMap<String, f64> {
    let mut weights = lexical_query_term_weights(content)
        .into_iter()
        .collect::<Vec<_>>();
    weights.sort_by(|left, right| {
        right
            .1
            .partial_cmp(&left.1)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.0.cmp(&right.0))
    });
    weights.into_iter().take(limit).collect()
}

fn evidence_term_weights_from_manifest(evidence: &RetrievalEvidence) -> BTreeMap<String, f64> {
    evidence
        .evidence_manifest
        .get("embedding")
        .and_then(|value| value.get("term_weights"))
        .and_then(Value::as_object)
        .map(|weights| {
            weights
                .iter()
                .filter_map(|(term, weight)| weight.as_f64().map(|value| (term.clone(), value)))
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default()
}

fn rank_hint_from_evidence_manifest(evidence: &RetrievalEvidence) -> Option<usize> {
    evidence
        .evidence_manifest
        .get("recall")
        .and_then(|value| value.get("rank_hint"))
        .and_then(Value::as_u64)
        .map(|value| value as usize)
}

fn lexical_query_term_weights(query: &str) -> BTreeMap<String, f64> {
    let mut frequencies: BTreeMap<String, f64> = BTreeMap::new();
    for token in lexical_query_tokens(query) {
        *frequencies.entry(token).or_insert(0.0) += 1.0;
    }

    frequencies
        .into_iter()
        .map(|(term, count)| {
            let boost = lexical_cjk_phrase_boost(&term);
            (term, (1.0 + count.ln()) * boost)
        })
        .collect()
}

fn vector_norm(weights: &BTreeMap<String, f64>) -> f64 {
    weights
        .values()
        .map(|weight| weight * weight)
        .sum::<f64>()
        .sqrt()
}

fn lexical_query_tokens(content: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut ascii_token = String::new();
    let mut cjk_chars = Vec::new();

    for value in content.chars() {
        if value.is_ascii_alphanumeric() {
            flush_lexical_cjk_terms(&mut tokens, &mut cjk_chars);
            ascii_token.push(value.to_ascii_lowercase());
            continue;
        }
        flush_lexical_ascii_token(&mut tokens, &mut ascii_token);
        if is_cjk_query_token_char(value) {
            cjk_chars.push(value);
        } else {
            flush_lexical_cjk_terms(&mut tokens, &mut cjk_chars);
        }
    }
    flush_lexical_ascii_token(&mut tokens, &mut ascii_token);
    flush_lexical_cjk_terms(&mut tokens, &mut cjk_chars);
    extend_lexical_ascii_connector_tokens(content, &mut tokens);
    extend_lexical_domain_hint_tokens(content, &mut tokens);
    tokens
}

