fn assistant_run_codex_provider_shim_observability_summary(snapshot: Option<&Value>) -> Value {
    let Some(snapshot) = snapshot.filter(|value| value.is_object()) else {
        return Value::Null;
    };
    let health = snapshot
        .get("health")
        .filter(|value| value.is_object())
        .map(|health| {
            json!({
                "status": health.get("status").cloned().unwrap_or(Value::Null),
                "process_reachable": health
                    .get("process_reachable")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "upstream_reachable": health
                    .get("upstream_reachable")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "checked_at": health.get("checked_at").cloned().unwrap_or(Value::Null),
                "has_message": health.get("message").is_some(),
            })
        })
        .unwrap_or(Value::Null);
    let profile = snapshot
        .get("profile")
        .filter(|value| value.is_object())
        .map(|profile| {
            json!({
                "profile_id": profile.get("profile_id").cloned().unwrap_or(Value::Null),
                "provider_id": profile.get("provider_id").cloned().unwrap_or(Value::Null),
                "model_id": profile.get("model_id").cloned().unwrap_or(Value::Null),
                "wire_api": profile.get("wire_api").cloned().unwrap_or(Value::Null),
                "endpoint_scope": profile.get("endpoint_scope").cloned().unwrap_or(Value::Null),
                "base_url_configured": profile
                    .get("base_url_configured")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "api_path": profile.get("api_path").cloned().unwrap_or(Value::Null),
                "auth_configured": profile
                    .get("auth_configured")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "timeout_ms": profile.get("timeout_ms").cloned().unwrap_or(Value::Null),
                "capabilities": profile
                    .get("capabilities")
                    .cloned()
                    .unwrap_or_else(|| json!([])),
                "rate_limit": {
                    "requests_per_minute": profile
                        .pointer("/rate_limit/requests_per_minute")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "tokens_per_minute": profile
                        .pointer("/rate_limit/tokens_per_minute")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "concurrent_requests": profile
                        .pointer("/rate_limit/concurrent_requests")
                        .cloned()
                        .unwrap_or(Value::Null),
                },
                "cost": {
                    "currency": profile.pointer("/cost/currency").cloned().unwrap_or(Value::Null),
                    "input_microusd_per_million_tokens": profile
                        .pointer("/cost/input_microusd_per_million_tokens")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "output_microusd_per_million_tokens": profile
                        .pointer("/cost/output_microusd_per_million_tokens")
                        .cloned()
                        .unwrap_or(Value::Null),
                },
                "redaction": {
                    "redact_provider_errors": profile
                        .pointer("/redaction/redact_provider_errors")
                        .cloned()
                        .unwrap_or(Value::Bool(true)),
                    "redact_request_payloads": profile
                        .pointer("/redaction/redact_request_payloads")
                        .cloned()
                        .unwrap_or(Value::Bool(true)),
                    "redact_response_payloads": profile
                        .pointer("/redaction/redact_response_payloads")
                        .cloned()
                        .unwrap_or(Value::Bool(true)),
                    "max_error_chars": profile
                        .pointer("/redaction/max_error_chars")
                        .cloned()
                        .unwrap_or(Value::Null),
                },
            })
        })
        .unwrap_or(Value::Null);
    let usage_summary = snapshot
        .get("usage_summary")
        .filter(|value| value.is_object())
        .map(|usage| {
            json!({
                "request_count": usage.get("request_count").cloned().unwrap_or(Value::Null),
                "failed_request_count": usage
                    .get("failed_request_count")
                    .cloned()
                    .unwrap_or(Value::Null),
                "input_tokens": usage.get("input_tokens").cloned().unwrap_or(Value::Null),
                "output_tokens": usage.get("output_tokens").cloned().unwrap_or(Value::Null),
                "total_tokens": usage.get("total_tokens").cloned().unwrap_or(Value::Null),
                "has_last_request_id": usage.get("last_request_id").is_some(),
            })
        })
        .unwrap_or(Value::Null);
    let recent_usage_events = snapshot
        .get("recent_usage_events")
        .and_then(Value::as_array)
        .map(|events| {
            let failed_count = events
                .iter()
                .filter(|event| {
                    event
                        .get("status")
                        .and_then(Value::as_str)
                        .map(|status| status != "ok" && status != "completed")
                        .unwrap_or(false)
                })
                .count();
            json!({
                "event_count": events.len(),
                "failed_event_count": failed_count,
                "latest_status": events
                    .last()
                    .and_then(|event| event.get("status"))
                    .cloned()
                    .unwrap_or(Value::Null),
                "latest_failure_kind": events
                    .last()
                    .and_then(|event| event.get("provider_failure_kind"))
                    .cloned()
                    .unwrap_or(Value::Null),
            })
        })
        .unwrap_or_else(|| {
            json!({
                "event_count": 0,
                "failed_event_count": 0,
                "latest_status": Value::Null,
                "latest_failure_kind": Value::Null,
            })
        });
    let balance = snapshot
        .get("balance")
        .filter(|value| value.is_object())
        .map(|balance| {
            json!({
                "supported": balance.get("supported").cloned().unwrap_or(Value::Bool(false)),
                "currency": balance.get("currency").cloned().unwrap_or(Value::Null),
                "has_amount": balance.get("amount_microunits").is_some(),
                "checked_at": balance.get("checked_at").cloned().unwrap_or(Value::Null),
                "has_note": balance.get("note").is_some(),
            })
        })
        .unwrap_or(Value::Null);
    let debug_trace_status = snapshot
        .get("debug_trace_status")
        .filter(|value| value.is_object())
        .map(|trace| {
            json!({
                "enabled": trace.get("enabled").cloned().unwrap_or(Value::Bool(false)),
                "redacted": trace.get("redacted").cloned().unwrap_or(Value::Bool(true)),
                "storage": trace.get("storage").cloned().unwrap_or(Value::Null),
                "retained_trace_count": trace
                    .get("retained_trace_count")
                    .cloned()
                    .unwrap_or(Value::Null),
                "has_latest_trace": trace.get("latest_trace_id").is_some(),
                "has_note": trace.get("note").is_some(),
            })
        })
        .unwrap_or(Value::Null);
    let context_budget_report = snapshot
        .get("context_budget_report")
        .filter(|value| value.is_object())
        .map(|budget| {
            json!({
                "quality_first": budget.get("quality_first").cloned().unwrap_or(Value::Bool(true)),
                "max_prompt_chars": budget.get("max_prompt_chars").cloned().unwrap_or(Value::Null),
                "estimated_prompt_chars": budget
                    .get("estimated_prompt_chars")
                    .cloned()
                    .unwrap_or(Value::Null),
                "budget_pressure": budget.get("budget_pressure").cloned().unwrap_or(Value::Null),
                "trimmed_item_count": budget
                    .get("trimmed_item_count")
                    .cloned()
                    .unwrap_or(Value::Null),
                "item_count": budget
                    .get("items")
                    .and_then(Value::as_array)
                    .map(Vec::len)
                    .unwrap_or(0),
            })
        })
        .unwrap_or(Value::Null);
    let tool_output_budget = snapshot
        .get("tool_output_budget")
        .filter(|value| value.is_object())
        .map(|budget| {
            json!({
                "largest_output_chars": budget
                    .get("largest_output_chars")
                    .cloned()
                    .unwrap_or(Value::Null),
                "trimmed_output_count": budget
                    .get("trimmed_output_count")
                    .cloned()
                    .unwrap_or(Value::Null),
                "preserved_recent_output_count": budget
                    .get("preserved_recent_output_count")
                    .cloned()
                    .unwrap_or(Value::Null),
                "preserved_error_count": budget
                    .get("preserved_error_count")
                    .cloned()
                    .unwrap_or(Value::Null),
                "preserved_evidence_ref_count": budget
                    .get("preserved_evidence_ref_count")
                    .cloned()
                    .unwrap_or(Value::Null),
                "has_note": budget.get("note").is_some(),
            })
        })
        .unwrap_or(Value::Null);
    let liveness_events = snapshot
        .get("liveness_events")
        .and_then(Value::as_array)
        .map(|events| {
            json!({
                "event_count": events.len(),
                "latest": events.last().map(|event| {
                    json!({
                        "event_type": event.get("event_type").cloned().unwrap_or(Value::Null),
                        "status": event.get("status").cloned().unwrap_or(Value::Null),
                        "retry_count": event.get("retry_count").cloned().unwrap_or(Value::Null),
                        "action": event.get("action").cloned().unwrap_or(Value::Null),
                        "occurred_at": event.get("occurred_at").cloned().unwrap_or(Value::Null),
                        "has_note": event.get("note").is_some(),
                    })
                }).unwrap_or(Value::Null),
            })
        })
        .unwrap_or_else(|| json!({"event_count": 0, "latest": Value::Null}));

    json!({
        "schema_version": snapshot.get("schema_version").cloned().unwrap_or(Value::Null),
        "health": health,
        "profile": profile,
        "usage_summary": usage_summary,
        "recent_usage_events": recent_usage_events,
        "balance": balance,
        "debug_trace_status": debug_trace_status,
        "context_budget_report": context_budget_report,
        "tool_output_budget": tool_output_budget,
        "liveness_events": liveness_events,
        "raw_payloads_exposed": false,
    })
}

fn assistant_run_codex_recent_shadow_events(
    events: &[&AssistantRunEvent],
    limit: usize,
) -> Vec<Value> {
    events
        .iter()
        .rev()
        .take(limit)
        .copied()
        .map(assistant_run_codex_shadow_event_summary)
        .collect()
}

fn assistant_run_codex_shadow_event_summary(event: &AssistantRunEvent) -> Value {
    let payload = &event.payload;
    let shadow = payload.get("shadow_comparison").unwrap_or(&Value::Null);
    let suggested_action = payload.get("suggested_action").unwrap_or(&Value::Null);
    let model_gateway = payload.get("model_gateway").unwrap_or(&Value::Null);

    json!({
        "event_id": event.id.to_string(),
        "sequence_no": event.sequence_no,
        "transport": payload.get("transport").cloned().unwrap_or(Value::Null),
        "transport_policy": assistant_run_codex_transport_policy_summary(
            payload.get("transport_policy"),
        ),
        "status": payload.get("status").cloned().unwrap_or(Value::Null),
        "comparison_status": shadow
            .pointer("/comparison/status")
            .cloned()
            .unwrap_or(Value::Null),
        "actionable": shadow
            .pointer("/comparison/actionable")
            .cloned()
            .unwrap_or(Value::Bool(false)),
        "codex_has_suggestion": shadow
            .pointer("/comparison/codex_has_suggestion")
            .cloned()
            .unwrap_or(Value::Bool(false)),
        "direct_action_types": shadow
            .pointer("/direct/action_types")
            .cloned()
            .unwrap_or_else(|| json!([])),
        "codex_suggested_action_type": shadow
            .pointer("/codex/suggested_action_type")
            .cloned()
            .or_else(|| suggested_action.get("action_type").cloned())
            .unwrap_or(Value::Null),
        "codex_suggested_action_allowed": shadow
            .pointer("/codex/suggested_action_allowed")
            .cloned()
            .unwrap_or(Value::Null),
        "mutation_allowed": suggested_action
            .get("mutation_allowed")
            .cloned()
            .unwrap_or(Value::Bool(false)),
        "codex_mutation_allowed": shadow
            .get("codex_mutation_allowed")
            .cloned()
            .unwrap_or(Value::Bool(false)),
        "model_gateway_lane": model_gateway
            .get("lane")
            .cloned()
            .unwrap_or(Value::Null),
        "model_provider": model_gateway
            .pointer("/selected_model/provider")
            .cloned()
            .unwrap_or(Value::Null),
        "model": model_gateway
            .pointer("/selected_model/model")
            .cloned()
            .unwrap_or(Value::Null),
        "profile_status": model_gateway
            .get("profile_status")
            .cloned()
            .unwrap_or(Value::Null),
        "next_gate": shadow
            .pointer("/comparison/next_gate")
            .cloned()
            .unwrap_or(Value::Null),
    })
}

fn assistant_run_codex_model_gateway_gate_summary(latest: Option<&AssistantRunEvent>) -> Value {
    let Some(event) = latest else {
        return json!({
            "status": "not_run",
            "ready_for_promotion_review": false,
            "profile_available": false,
            "auth_configured": false,
            "codex_surface_supported": false,
            "next_step": "run_codex_shadow_diagnostics_with_model_gateway_snapshot",
        });
    };
    let model_gateway = event.payload.get("model_gateway").unwrap_or(&Value::Null);
    let summary = assistant_run_codex_model_gateway_diagnostics_summary(Some(model_gateway));
    let profile_available = summary
        .get("profile_available")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let auth_configured = summary
        .get("auth_configured")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let codex_surface = summary.get("codex_surface").unwrap_or(&Value::Null);
    let wire_api = summary
        .get("wire_api")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let codex_compatible = codex_surface
        .get("codex_compatible")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| {
            matches!(
                wire_api,
                "codex_compatible_shim" | "codex-compatible-shim" | "codex_shim" | "provider_shim"
            )
        });
    let json_actions_supported = codex_surface
        .get("json_actions_supported")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| matches!(wire_api, "responses" | "codex_compatible_shim"));
    let tool_calls_supported = codex_surface
        .get("tool_calls_supported")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let codex_surface_supported = codex_compatible || json_actions_supported;
    let status = if !profile_available {
        "profile_missing"
    } else if !auth_configured {
        "auth_not_configured"
    } else if !codex_surface_supported {
        "unsupported_codex_surface"
    } else {
        "ready"
    };
    let next_step = match status {
        "ready" => "continue_shadow_and_host_gate_review",
        "profile_missing" => "configure_codex_conversation_model_profile",
        "auth_not_configured" => "configure_codex_model_profile_auth",
        "unsupported_codex_surface" => "select_codex_compatible_or_json_action_profile",
        _ => "inspect_model_gateway_diagnostics",
    };

    json!({
        "status": status,
        "ready_for_promotion_review": status == "ready",
        "profile_available": profile_available,
        "profile_source": summary.get("profile_source").cloned().unwrap_or(Value::Null),
        "profile_status": summary.get("profile_status").cloned().unwrap_or(Value::Null),
        "profile_id": summary.get("profile_id").cloned().unwrap_or(Value::Null),
        "provider_id": summary.get("provider_id").cloned().unwrap_or(Value::Null),
        "model_id": summary.get("model_id").cloned().unwrap_or(Value::Null),
        "wire_api": summary.get("wire_api").cloned().unwrap_or(Value::Null),
        "auth_configured": auth_configured,
        "capabilities": summary
            .get("capabilities")
            .cloned()
            .unwrap_or_else(|| json!([])),
        "capability_manifest": summary
            .get("capability_manifest")
            .cloned()
            .unwrap_or(Value::Null),
        "codex_surface": {
            "codex_compatible": codex_compatible,
            "json_actions_supported": json_actions_supported,
            "tool_calls_supported": tool_calls_supported,
            "real_execution_block_reason": codex_surface
                .get("real_execution_block_reason")
                .cloned()
                .unwrap_or(Value::Null),
        },
        "direct_execution_authoritative": true,
        "local_execution_allowed": false,
        "codex_mutation_allowed": false,
        "queue_allowed": false,
        "next_step": next_step,
    })
}

fn assistant_run_codex_shadow_gate_summary(events: &[&AssistantRunEvent]) -> Value {
    const MIN_STABLE_SHADOW_EVENTS: usize = 3;
    const SHADOW_GATE_WINDOW: usize = 20;

    let window = events
        .iter()
        .rev()
        .take(SHADOW_GATE_WINDOW)
        .copied()
        .collect::<Vec<_>>();
    let mut matched_count = 0_usize;
    let mut diverged_count = 0_usize;
    let mut invalid_count = 0_usize;
    let mut no_suggestion_count = 0_usize;
    let mut unsafe_mutation_signal_count = 0_usize;
    let mut matched_streak_count = 0_usize;
    let mut streak_open = true;
    let mut last_blocking_event = Value::Null;

    for event in &window {
        let comparison = event
            .payload
            .get("shadow_comparison")
            .unwrap_or(&Value::Null);
        let comparison_status = comparison
            .pointer("/comparison/status")
            .and_then(Value::as_str)
            .unwrap_or("missing");
        let unsafe_mutation_signal = comparison
            .get("codex_mutation_allowed")
            .and_then(Value::as_bool)
            .unwrap_or(false)
            || event
                .payload
                .get("suggested_action")
                .and_then(|action| action.get("mutation_allowed"))
                .and_then(Value::as_bool)
                .unwrap_or(false);

        if streak_open {
            if comparison_status == "matched" && !unsafe_mutation_signal {
                matched_streak_count += 1;
            } else {
                streak_open = false;
            }
        }
        if last_blocking_event.is_null()
            && (comparison_status != "matched" || unsafe_mutation_signal)
        {
            last_blocking_event = assistant_run_codex_shadow_event_summary(event);
        }

        match comparison_status {
            "matched" => matched_count += 1,
            "diverged" => diverged_count += 1,
            "invalid_suggestion" => invalid_count += 1,
            "no_codex_suggestion" => no_suggestion_count += 1,
            _ => no_suggestion_count += 1,
        }
        if unsafe_mutation_signal {
            unsafe_mutation_signal_count += 1;
        }
    }

    let status = if window.len() < MIN_STABLE_SHADOW_EVENTS {
        "insufficient_sample"
    } else if invalid_count > 0 || unsafe_mutation_signal_count > 0 {
        "blocked"
    } else if diverged_count > 0 || no_suggestion_count > 0 {
        "warming"
    } else {
        "eligible_for_host_validation"
    };
    let reason = match status {
        "insufficient_sample" => "not enough Codex shadow diagnostic events",
        "blocked" => "invalid or unsafe Codex shadow suggestion was observed",
        "warming" => "Codex shadow suggestions are not consistently matched yet",
        "eligible_for_host_validation" => {
            "recent Codex shadow suggestions match direct actions; host validation can be considered"
        }
        _ => "unknown shadow gate status",
    };

    json!({
        "status": status,
        "reason": reason,
        "window_size": window.len(),
        "required_stable_events": MIN_STABLE_SHADOW_EVENTS,
        "matched_count": matched_count,
        "diverged_count": diverged_count,
        "invalid_count": invalid_count,
        "no_suggestion_count": no_suggestion_count,
        "unsafe_mutation_signal_count": unsafe_mutation_signal_count,
        "matched_streak_count": matched_streak_count,
        "last_blocking_event": last_blocking_event,
        "host_validation": assistant_run_codex_host_validation_readiness(
            status,
            window.len(),
            matched_streak_count,
            &last_blocking_event,
        ),
        "host_validation_allowed": status == "eligible_for_host_validation",
        "codex_mutation_allowed": false,
        "queue_allowed": false,
        "next_gate": if status == "eligible_for_host_validation" {
            "jump_host_or_mac_host_validation"
        } else {
            "continue_shadow_comparison"
        },
    })
}

fn assistant_run_codex_host_validation_readiness(
    gate_status: &str,
    window_size: usize,
    matched_streak_count: usize,
    last_blocking_event: &Value,
) -> Value {
    let ready = gate_status == "eligible_for_host_validation";
    let blocked_by = if ready {
        Value::Null
    } else if gate_status == "insufficient_sample" {
        json!("insufficient_shadow_sample")
    } else if !last_blocking_event.is_null() {
        last_blocking_event
            .get("comparison_status")
            .cloned()
            .unwrap_or_else(|| json!("shadow_gate_not_stable"))
    } else {
        json!("shadow_gate_not_stable")
    };

    json!({
        "ready_for_jump_host_validation": ready,
        "ready_for_mac_host_validation": ready,
        "required_host_kinds": ["windows_jump", "mac_host"],
        "candidate_transports": [
            "codex_exec_schema",
            "codex_sdk_thread",
            "codex_app_server"
        ],
        "local_execution_allowed": false,
        "direct_execution_authoritative": true,
        "codex_mutation_allowed_before_host_validation": false,
        "queue_allowed_before_host_validation": false,
        "requires_task_workspace_root": true,
        "requires_real_exec_allow_flag": true,
        "requires_v3_action_validation": true,
        "shadow_window_size": window_size,
        "matched_streak_count": matched_streak_count,
        "blocked_by": blocked_by,
        "next_step": if ready {
            "run_jump_host_smoke_with_codex_host_agent"
        } else {
            "continue_shadow_comparison_until_stable"
        },
    })
}

fn assistant_run_codex_host_validation_results(
    events: &[AssistantRunEvent],
    limit: usize,
) -> Vec<Value> {
    events
        .iter()
        .rev()
        .filter_map(assistant_run_codex_host_validation_event_summary)
        .take(limit)
        .collect()
}

fn assistant_run_codex_host_validation_summary(results: &[Value]) -> Value {
    let completed_count = results
        .iter()
        .filter(|result| assistant_run_codex_host_validation_result_completed(result))
        .count();
    let invalid_host_count = results
        .iter()
        .filter(|result| {
            result.get("mode").and_then(Value::as_str) == Some("codex_exec")
                && result.get("status").and_then(Value::as_str) == Some("completed")
                && !result
                    .get("host_kind_allowed")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
        })
        .count();
    let guard_failed_count = results
        .iter()
        .filter(|result| {
            result.get("mode").and_then(Value::as_str) == Some("codex_exec")
                && result.get("status").and_then(Value::as_str) == Some("completed")
                && result
                    .get("host_kind_allowed")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                && !assistant_run_codex_host_validation_result_completed(result)
        })
        .count();
    let failed_count = results
        .iter()
        .filter(|result| {
            result.get("mode").and_then(Value::as_str) == Some("codex_exec")
                && !assistant_run_codex_host_validation_result_completed(result)
        })
        .count();
    let latest = results.first();
    let latest_status = latest
        .map(|result| {
            if assistant_run_codex_host_validation_result_completed(result) {
                "validated"
            } else if result.get("mode").and_then(Value::as_str) == Some("codex_exec")
                && result.get("status").and_then(Value::as_str) == Some("completed")
                && !result
                    .get("host_kind_allowed")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
            {
                "invalid_host"
            } else if result.get("mode").and_then(Value::as_str) == Some("codex_exec") {
                "failed"
            } else {
                "observed_non_exec"
            }
        })
        .unwrap_or("not_run");
    let next_step = match latest_status {
        "validated" => "review_host_report_then_consider_feature_gate_promotion",
        "invalid_host" => "rerun_codex_host_smoke_on_windows_jump_or_mac_host",
        "failed" => "inspect_redacted_codex_host_report_and_retry_on_jump_host",
        _ => "run_jump_host_smoke_with_codex_host_agent_when_shadow_gate_ready",
    };
    let latest_summary = latest
        .map(|result| {
            json!({
                "mode": result.get("mode").cloned().unwrap_or(Value::Null),
                "status": result.get("status").cloned().unwrap_or(Value::Null),
                "host_kind": result.get("host_kind").cloned().unwrap_or(Value::Null),
                "host_kind_allowed": result
                    .get("host_kind_allowed")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "capability": result.get("capability").cloned().unwrap_or(Value::Null),
                "codex_invoked": result
                    .get("codex_invoked")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "validation_requirements_met": assistant_run_codex_host_validation_result_completed(result),
                "profile_kind": result.pointer("/profile/kind").cloned().unwrap_or(Value::Null),
                "model": result.pointer("/profile/model").cloned().unwrap_or(Value::Null),
                "workspace_configured": result
                    .pointer("/command_plan/workspace_configured")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "prompt_redacted": result
                    .pointer("/command_plan/prompt_redacted")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "exit_code": result.pointer("/process/exit_code").cloned().unwrap_or(Value::Null),
                "task_memory_isolated": result
                    .get("task_memory_isolated")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "task_memory_space_configured": result
                    .get("task_memory_space_configured")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "html_artifact_count": result
                    .get("html_artifact_count")
                    .cloned()
                    .unwrap_or(Value::Null),
            })
        })
        .unwrap_or(Value::Null);

    json!({
        "status": latest_status,
        "result_count": results.len(),
        "completed_count": completed_count,
        "failed_count": failed_count,
        "invalid_host_count": invalid_host_count,
        "guard_failed_count": guard_failed_count,
        "latest": latest_summary,
        "direct_execution_authoritative": true,
        "local_execution_allowed": false,
        "codex_mutation_allowed": false,
        "queue_allowed": false,
        "next_step": next_step,
    })
}

fn assistant_run_codex_promotion_gate_summary_with_model_gateway(
    shadow_gate: &Value,
    host_validation: &Value,
    model_gateway_gate: &Value,
) -> Value {
    let shadow_ready = shadow_gate
        .get("host_validation_allowed")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let host_validated = host_validation.get("status").and_then(Value::as_str) == Some("validated");
    let model_gateway_ready = model_gateway_gate
        .get("ready_for_promotion_review")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let status = if shadow_ready && host_validated && model_gateway_ready {
        "eligible_for_feature_gate_review"
    } else if !shadow_ready {
        "blocked_by_shadow_gate"
    } else if !host_validated {
        "blocked_by_host_validation"
    } else {
        "blocked_by_model_gateway"
    };
    let blocked_by = match status {
        "eligible_for_feature_gate_review" => Value::Null,
        "blocked_by_shadow_gate" => shadow_gate
            .get("status")
            .cloned()
            .unwrap_or_else(|| json!("shadow_gate_not_ready")),
        "blocked_by_host_validation" => host_validation
            .get("status")
            .cloned()
            .unwrap_or_else(|| json!("host_validation_not_run")),
        "blocked_by_model_gateway" => model_gateway_gate
            .get("status")
            .cloned()
            .unwrap_or_else(|| json!("model_gateway_not_ready")),
        _ => json!("unknown"),
    };
    let next_step = match status {
        "eligible_for_feature_gate_review" => {
            "review_shadow_and_host_reports_before_enabling_codex_executor_gate"
        }
        "blocked_by_shadow_gate" => "continue_shadow_comparison_until_stable",
        "blocked_by_host_validation" => "run_or_fix_jump_host_validation",
        "blocked_by_model_gateway" => "fix_codex_model_gateway_profile_before_promotion",
        _ => "inspect_codex_executor_diagnostics",
    };
    let shadow_gate_status = shadow_gate.get("status").cloned().unwrap_or(Value::Null);
    let host_validation_status = host_validation
        .get("status")
        .cloned()
        .unwrap_or(Value::Null);
    let model_gateway_status = model_gateway_gate
        .get("status")
        .cloned()
        .unwrap_or(Value::Null);

    json!({
        "status": status,
        "shadow_gate_status": shadow_gate_status,
        "host_validation_status": host_validation_status,
        "model_gateway_status": model_gateway_status,
        "readiness_checks": {
            "shadow_gate": {
                "ready": shadow_ready,
                "status": shadow_gate_status,
            },
            "host_validation": {
                "ready": host_validated,
                "status": host_validation_status,
            },
            "model_gateway": {
                "ready": model_gateway_ready,
                "status": model_gateway_status,
            },
            "all_ready": shadow_ready && host_validated && model_gateway_ready,
        },
        "eligible_for_feature_gate_review": status == "eligible_for_feature_gate_review",
        "blocked_by": blocked_by,
        "direct_execution_authoritative": true,
        "local_execution_allowed": false,
        "codex_mutation_allowed": false,
        "queue_allowed": false,
        "requires_manual_feature_gate_change": true,
        "next_step": next_step,
    })
}

fn assistant_run_codex_host_validation_event_summary(event: &AssistantRunEvent) -> Option<Value> {
    let output = assistant_run_codex_host_output_payload(&event.payload)?;
    let mode = output
        .get("mode")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    if !event.event_name.starts_with("codex_host")
        && !event.event_name.contains("codex_host")
        && mode != "codex_exec"
    {
        return None;
    }
    let status = output
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let host_kind = output.get("host_kind").and_then(Value::as_str);
    let host_kind_allowed = assistant_run_codex_host_kind_is_allowed(host_kind);
    let process = output.get("process").unwrap_or(&Value::Null);
    let command_plan = output.get("command_plan").unwrap_or(&Value::Null);
    let profile = output.get("profile").unwrap_or(&Value::Null);
    let codex_invoked = output
        .get("codex_invoked")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let workspace_configured = command_plan
        .get("workspace_configured")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let prompt_redacted = command_plan
        .get("prompt_redacted")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let exit_code_is_zero = process
        .get("exit_code")
        .and_then(Value::as_i64)
        .is_some_and(|exit_code| exit_code == 0);
    let task_memory_isolated = output
        .get("task_memory_isolated")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let task_memory_space_configured = output.get("task_memory_space_id").is_some();
    let host_validation_completed = mode == "codex_exec"
        && status == "completed"
        && host_kind_allowed
        && codex_invoked
        && workspace_configured
        && prompt_redacted
        && exit_code_is_zero
        && task_memory_isolated
        && task_memory_space_configured;
    let stdout_chars = process
        .get("stdout_chars")
        .and_then(Value::as_u64)
        .map(|value| value as usize)
        .or_else(|| {
            process
                .get("stdout_excerpt")
                .and_then(Value::as_str)
                .map(|value| value.chars().count())
        })
        .unwrap_or(0);
    let stderr_chars = process
        .get("stderr_chars")
        .and_then(Value::as_u64)
        .map(|value| value as usize)
        .or_else(|| {
            process
                .get("stderr_excerpt")
                .and_then(Value::as_str)
                .map(|value| value.chars().count())
        })
        .unwrap_or(0);
    let html_artifact_count = output
        .get("html_artifacts")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);

    Some(json!({
        "event_id": event.id.to_string(),
        "sequence_no": event.sequence_no,
        "event_name": event.event_name.clone(),
        "mode": mode,
        "status": status,
        "host_kind": host_kind,
        "host_kind_allowed": host_kind_allowed,
        "host_validation_completed": host_validation_completed,
        "codex_invoked": codex_invoked,
        "capability": output.get("capability").cloned().unwrap_or(Value::Null),
        "profile": {
            "id": profile.get("id").cloned().unwrap_or(Value::Null),
            "kind": profile.get("kind").cloned().unwrap_or(Value::Null),
            "model": profile.get("model").cloned().unwrap_or(Value::Null),
            "provider_id": profile.get("provider_id").cloned().unwrap_or(Value::Null),
            "wire_api": profile.get("wire_api").cloned().unwrap_or(Value::Null),
            "base_url_configured": profile
                .get("base_url_configured")
                .cloned()
                .unwrap_or(Value::Bool(false)),
            "allowed_capability_count": profile
                .get("allowed_capabilities")
                .and_then(Value::as_array)
                .map(Vec::len)
                .unwrap_or(0),
        },
        "command_plan": {
            "program": command_plan.get("program").cloned().unwrap_or(Value::Null),
            "sandbox": command_plan.get("sandbox").cloned().unwrap_or(Value::Null),
            "prompt_chars": command_plan.get("prompt_chars").cloned().unwrap_or(Value::Null),
            "workspace_configured": command_plan
                .get("workspace_configured")
                .cloned()
                .unwrap_or(Value::Bool(false)),
            "workspace_label": command_plan
                .get("workspace_label")
                .cloned()
                .unwrap_or(Value::Null),
            "prompt_redacted": command_plan
                .get("prompt_redacted")
                .cloned()
                .unwrap_or(Value::Bool(true)),
        },
        "process": {
            "exit_code": process.get("exit_code").cloned().unwrap_or(Value::Null),
            "stdout_chars": stdout_chars,
            "stderr_chars": stderr_chars,
        },
        "task_chars": output.get("task_chars").cloned().unwrap_or(Value::Null),
        "local_thread_id": output
            .get("local_thread_id")
            .cloned()
            .unwrap_or(Value::Null),
        "task_memory_isolated": output
            .get("task_memory_isolated")
            .cloned()
            .unwrap_or(Value::Bool(false)),
        "task_memory_space_configured": task_memory_space_configured,
        "html_artifact_count": html_artifact_count,
        "raw_logs_exposed": false,
    }))
}

fn assistant_run_codex_host_validation_result_completed(result: &Value) -> bool {
    result.get("mode").and_then(Value::as_str) == Some("codex_exec")
        && result.get("status").and_then(Value::as_str) == Some("completed")
        && result
            .get("host_kind_allowed")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        && result
            .get("codex_invoked")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        && result
            .pointer("/command_plan/workspace_configured")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        && result
            .pointer("/command_plan/prompt_redacted")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        && result
            .pointer("/process/exit_code")
            .and_then(Value::as_i64)
            .is_some_and(|exit_code| exit_code == 0)
        && result
            .get("task_memory_isolated")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        && result
            .get("task_memory_space_configured")
            .and_then(Value::as_bool)
            .unwrap_or(false)
}

fn assistant_run_codex_host_kind_is_allowed(host_kind: Option<&str>) -> bool {
    matches!(
        host_kind,
        Some("windows_jump" | "mac_host" | "cloudflare_codex")
    )
}

fn assistant_run_codex_host_output_payload(payload: &Value) -> Option<&Value> {
    if payload.get("mode").and_then(Value::as_str).is_some() {
        return Some(payload);
    }
    let output = payload.get("output")?;
    if output.get("mode").and_then(Value::as_str).is_some() {
        Some(output)
    } else {
        None
    }
}

fn assistant_run_provider_usage_events(
    run: &AssistantRun,
    events: &[AssistantRunEvent],
) -> Vec<Value> {
    let mut usage_events = events
        .iter()
        .filter_map(|event| {
            let runtime = event.payload.get("runtime")?;
            assistant_run_provider_usage_event_from_runtime_manifest(
                run.id,
                Some(event.sequence_no),
                Some(event.event_name.as_str()),
                runtime,
            )
        })
        .collect::<Vec<_>>();

    if usage_events.is_empty() {
        if let Some(event) = assistant_run_provider_usage_event_from_runtime_manifest(
            run.id,
            None,
            Some("assistant_run.current_runtime"),
            &run.runtime_manifest,
        ) {
            usage_events.push(event);
        }
    }

    usage_events
}

fn assistant_run_provider_usage_event_from_runtime_manifest(
    run_id: AssistantRunId,
    sequence_no: Option<i32>,
    event_name: Option<&str>,
    runtime: &Value,
) -> Option<Value> {
    let provider = runtime.get("provider").and_then(Value::as_str)?;
    let model = runtime.get("model").and_then(Value::as_str)?;
    let usage = runtime.get("usage").filter(|value| value.is_object());
    let provider_failure = runtime
        .get("provider_failure")
        .filter(|value| value.is_object());

    Some(json!({
        "assistant_run_id": run_id.to_string(),
        "sequence_no": sequence_no,
        "event_name": event_name,
        "mode": runtime.get("mode").and_then(Value::as_str),
        "provider": provider,
        "model": model,
        "lane": runtime.get("lane").and_then(Value::as_str),
        "request_id": runtime.get("request_id").and_then(Value::as_str),
        "status": if provider_failure.is_some() { "failed" } else { "responded" },
        "input_tokens": usage
            .and_then(|usage| usage.get("input_tokens"))
            .and_then(Value::as_u64),
        "output_tokens": usage
            .and_then(|usage| usage.get("output_tokens"))
            .and_then(Value::as_u64),
        "total_tokens": usage
            .and_then(|usage| usage.get("total_tokens"))
            .and_then(Value::as_u64),
        "latency_ms": runtime.get("latency_ms").and_then(Value::as_u64),
        "provider_failure_kind": provider_failure
            .and_then(|failure| failure.get("kind"))
            .and_then(Value::as_str),
    }))
}

fn assistant_run_provider_usage_summary(events: &[Value]) -> Value {
    json!({
        "request_count": events.len(),
        "failed_request_count": events
            .iter()
            .filter(|event| event.get("status").and_then(Value::as_str) == Some("failed"))
            .count(),
        "input_tokens": assistant_run_sum_usage_field(events, "input_tokens"),
        "output_tokens": assistant_run_sum_usage_field(events, "output_tokens"),
        "total_tokens": assistant_run_sum_usage_field(events, "total_tokens"),
        "last_request_id": events
            .iter()
            .rev()
            .find_map(|event| event.get("request_id").and_then(Value::as_str))
    })
}

fn assistant_run_recent_provider_usage_events(mut events: Vec<Value>, limit: usize) -> Vec<Value> {
    if events.len() > limit {
        events = events.split_off(events.len() - limit);
    }
    events
}

fn assistant_run_sum_usage_field(events: &[Value], field: &str) -> u64 {
    events
        .iter()
        .filter_map(|event| event.get(field).and_then(Value::as_u64))
        .sum()
}

fn value_array(value: Value) -> Vec<Value> {
    match value {
        Value::Array(items) => items,
        _ => Vec::new(),
    }
}

