fn build_initial_static_page_draft_payload(run: &AssistantRun, prompt: &str) -> Value {
    let style_direction = "client-delivery";
    let visual_spec = build_static_page_visual_spec(style_direction);
    let render_spec = build_static_page_render_spec();
    let data_snapshot = build_static_page_data_snapshot_with_evidence(
        &json!({ "modules": [] }),
        &run.selected_scope,
        Some(&run.evidence_state),
        "assistant_run",
    );
    let preview_contract = build_static_page_preview_contract(
        style_direction,
        &Value::Array(Vec::new()),
        &render_spec,
        &Value::Array(Vec::new()),
        None,
    );
    json!({
        "version": 1,
        "status": "draft",
        "title": derive_static_page_draft_title(prompt),
        "prompt": prompt,
        "modules": [],
        "mobileOrder": [],
        "styleDirection": style_direction,
        "style_direction": style_direction,
        "visualSpec": visual_spec.clone(),
        "visual_spec": visual_spec,
        "renderSpec": render_spec.clone(),
        "render_spec": render_spec,
        "dataSnapshot": data_snapshot.clone(),
        "data_snapshot": data_snapshot,
        "previewContract": preview_contract.clone(),
        "preview_contract": preview_contract,
        "data_bindings": [],
        "assistant_context": {
            "assistant_run_id": run.id,
            "selected_scope": run.selected_scope,
            "evidence_state": run.evidence_state,
        },
    })
}

fn build_static_page_image_prompt_payload(draft: &StaticPageDraft, prompt: Option<&str>) -> Value {
    let payload = &draft.draft_payload;
    let style_direction =
        static_page_payload_string(payload, &["styleDirection", "style_direction"])
            .unwrap_or_else(|| "client-delivery".to_string());
    let modules = static_page_payload_modules(payload);
    let visual_spec = static_page_payload_value(payload, &["visualSpec", "visual_spec"])
        .unwrap_or_else(|| build_static_page_visual_spec(&style_direction));
    let render_spec = static_page_payload_value(payload, &["renderSpec", "render_spec"])
        .unwrap_or_else(build_static_page_render_spec);
    let mobile_order = static_page_payload_mobile_order(payload, &modules);
    let data_snapshot = static_page_payload_value(payload, &["dataSnapshot", "data_snapshot"])
        .unwrap_or_else(|| build_static_page_data_snapshot(payload, &draft.selected_scope));
    let template_reference = payload
        .get("templateReference")
        .or_else(|| payload.get("template_reference"))
        .or_else(|| payload.pointer("/source/templateReference"))
        .cloned()
        .unwrap_or(Value::Null);
    let template_references = payload
        .get("designReferences")
        .or_else(|| payload.get("design_references"))
        .or_else(|| payload.pointer("/source/templateReferences"))
        .cloned()
        .unwrap_or_else(|| Value::Array(Vec::new()));
    let preview_contract =
        static_page_payload_value(payload, &["previewContract", "preview_contract"])
            .unwrap_or_else(|| {
                build_static_page_preview_contract(
                    &style_direction,
                    &modules,
                    &render_spec,
                    &mobile_order,
                    None,
                )
            });
    json!({
        "draft_id": draft.id,
        "assistant_run_id": draft.assistant_run_id,
        "title": draft.title,
        "prompt": prompt.map(str::trim).filter(|value| !value.is_empty()),
        "promptText": prompt.map(str::trim).filter(|value| !value.is_empty()),
        "prompt_text": prompt.map(str::trim).filter(|value| !value.is_empty()),
        "style_direction": style_direction,
        "visual_spec": visual_spec,
        "render_spec": render_spec,
        "data_snapshot": data_snapshot,
        "template_reference": template_reference,
        "template_references": template_references,
        "template_reuse_contract": {
            "policy": "reuse_generated_template_when_available",
            "data_rule": "template controls visual structure only; bind current selected_scope data",
            "image2_rule": "new Image2 is only required when no usable template exists or the user explicitly asks to change style",
        },
        "preview_contract": preview_contract,
        "design_contract": {
            "contract_source": "StaticPageDraft",
            "visual_source": "effect image is a preview contract, not final source code",
            "final_source": "generated effect image visual blueprint + real data_snapshot",
            "editable_core": "DOM text + SVG/chart components + safe ECharts JSON options",
        },
        "image_first_contract": {
            "role": "requirements_to_image2_then_image_to_html",
            "rule": "Generate the effect image from requirements first; then infer the visual layout from the image and bind real data_snapshot into HTML.",
            "fake_data_allowed": false
        },
        "selected_scope": draft.selected_scope,
        "visibility_snapshot": draft.visibility_snapshot,
        "modules": modules,
        "mobile_order": mobile_order,
        "data_bindings": payload.get("data_bindings").cloned().unwrap_or_else(|| json!([])),
        "queue_copy": "资源正在排队，可以联系商务开通高级用户跳过等待。",
    })
}

fn static_page_image_prompt_payload_is_prompt_only(payload: &Value) -> bool {
    payload
        .get("promptOnly")
        .or_else(|| payload.get("prompt_only"))
        .and_then(Value::as_bool)
        .unwrap_or(false)
}

fn static_page_preview_data_quality_gate_for_draft(
    draft: &StaticPageDraft,
) -> Option<(String, Value)> {
    let mut payload = draft.draft_payload.clone();
    ensure_json_object(&mut payload);
    if let Some(object) = payload.as_object_mut() {
        object
            .entry("selected_scope".to_string())
            .or_insert_with(|| draft.selected_scope.clone());
    }
    refresh_static_page_payload_design_contract(&mut payload);

    static_page_preview_data_quality_gate_for_payload(&payload)
}

fn static_page_preview_data_quality_gate_for_payload(payload: &Value) -> Option<(String, Value)> {
    let attention_modules = static_page_preview_data_quality_attention_modules(payload);
    if attention_modules.is_empty() {
        return None;
    }
    let message = static_page_preview_data_quality_message(&attention_modules);
    let details = static_page_data_quality_gate_details(
        &attention_modules,
        &message,
        "submit_static_page_image_preview",
        "Return to module editing, add sample rows or rebind weak fields, then submit the effect preview again.",
        &[
            "static_page.update_draft",
            "retrieval.search",
            "static_page.submit_preview_after_repair",
        ],
    );
    Some((message, details))
}

fn static_page_final_render_data_quality_gate_for_draft(
    draft: &StaticPageDraft,
) -> Option<(String, Value)> {
    let mut payload = draft.draft_payload.clone();
    ensure_json_object(&mut payload);
    if let Some(object) = payload.as_object_mut() {
        object
            .entry("selected_scope".to_string())
            .or_insert_with(|| draft.selected_scope.clone());
    }
    refresh_static_page_payload_design_contract(&mut payload);

    let attention_modules = static_page_final_render_data_quality_attention_modules(&payload);
    if attention_modules.is_empty() {
        return None;
    }
    let message = static_page_preview_data_quality_message(&attention_modules);
    let details = static_page_data_quality_gate_details(
        &attention_modules,
        &message,
        "render_static_page",
        "Return to module editing, add sample rows or rebind weak fields, then regenerate and confirm the effect preview before final render.",
        &[
            "static_page.update_draft",
            "retrieval.search",
            "submit_static_page_image_preview",
        ],
    );
    Some((message, details))
}

fn static_page_preview_data_quality_attention_modules(payload: &Value) -> Vec<Value> {
    payload
        .get("dataSnapshot")
        .or_else(|| payload.get("data_snapshot"))
        .and_then(|snapshot| {
            snapshot
                .get("moduleBindings")
                .or_else(|| snapshot.get("module_bindings"))
        })
        .and_then(Value::as_array)
        .map(|bindings| {
            bindings
                .iter()
                .take(24)
                .map(assistant_run_static_page_binding_quality_module_brief)
                .filter(static_page_preview_binding_module_needs_attention)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn static_page_preview_binding_module_needs_attention(module: &Value) -> bool {
    let status = static_page_artifact_string(
        module,
        &["bindingQualityStatus", "binding_quality_status", "status"],
    )
    .unwrap_or_default();
    if !status.is_empty()
        && !matches!(
            status.as_str(),
            "confirmed" | "ready" | "non_chart" | "partial"
        )
    {
        return true;
    }

    let chart_data_fit = static_page_artifact_string(module, &["chartDataFit", "chart_data_fit"])
        .unwrap_or_default();
    if !chart_data_fit.is_empty()
        && !matches!(
            chart_data_fit.as_str(),
            "ready" | "not_required" | "non_chart_ready" | "needs_sample_rows" | "inferred_signal"
        )
    {
        return true;
    }

    let visualization_type =
        static_page_artifact_string(module, &["visualizationType", "visualization_type"])
            .unwrap_or_default();
    let has_binding = static_page_preview_module_has_binding_source(module)
        || module
            .get("binding")
            .or_else(|| module.get("dataBinding"))
            .or_else(|| module.get("data_binding"))
            .is_some_and(static_page_preview_module_has_binding_source);
    static_page_visualization_needs_sample_rows(&visualization_type)
        && static_page_preview_quality_u64(module, &["sampleRows", "sample_rows"]) == 0
        && !has_binding
}

fn static_page_preview_module_has_binding_source(binding: &Value) -> bool {
    static_page_artifact_string(
        binding,
        &["sourceId", "source_id", "fieldPath", "field_path", "label"],
    )
    .is_some()
}

fn static_page_final_render_data_quality_attention_modules(payload: &Value) -> Vec<Value> {
    payload
        .get("dataSnapshot")
        .or_else(|| payload.get("data_snapshot"))
        .and_then(|snapshot| {
            snapshot
                .get("moduleBindings")
                .or_else(|| snapshot.get("module_bindings"))
        })
        .and_then(Value::as_array)
        .map(|bindings| {
            bindings
                .iter()
                .take(24)
                .map(assistant_run_static_page_binding_quality_module_brief)
                .filter(static_page_final_render_binding_module_needs_attention)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn static_page_final_render_binding_module_needs_attention(module: &Value) -> bool {
    let status = static_page_artifact_string(
        module,
        &["bindingQualityStatus", "binding_quality_status", "status"],
    )
    .unwrap_or_default();
    if !status.is_empty()
        && !matches!(
            status.as_str(),
            "confirmed" | "ready" | "non_chart" | "partial"
        )
    {
        return true;
    }

    let chart_data_fit = static_page_artifact_string(module, &["chartDataFit", "chart_data_fit"])
        .unwrap_or_default();
    if !chart_data_fit.is_empty()
        && !matches!(
            chart_data_fit.as_str(),
            "ready" | "not_required" | "non_chart_ready" | "needs_sample_rows" | "inferred_signal"
        )
    {
        return true;
    }

    let visualization_type =
        static_page_artifact_string(module, &["visualizationType", "visualization_type"])
            .unwrap_or_default();
    let has_binding = static_page_preview_module_has_binding_source(module)
        || module
            .get("binding")
            .or_else(|| module.get("dataBinding"))
            .or_else(|| module.get("data_binding"))
            .is_some_and(static_page_preview_module_has_binding_source);
    static_page_visualization_needs_sample_rows(&visualization_type)
        && static_page_preview_quality_u64(module, &["sampleRows", "sample_rows"]) == 0
        && !has_binding
}

fn static_page_preview_quality_u64(value: &Value, keys: &[&str]) -> u64 {
    keys.iter()
        .find_map(|key| {
            value
                .get(*key)
                .and_then(|item| item.as_u64().or_else(|| item.as_str()?.parse::<u64>().ok()))
        })
        .unwrap_or(0)
}

fn static_page_preview_data_quality_message(modules: &[Value]) -> String {
    let labels = modules
        .iter()
        .take(3)
        .map(static_page_preview_data_quality_module_label)
        .collect::<Vec<_>>()
        .join("、");
    let suffix = format!(" {} 个模块", modules.len());
    format!(
        "当前静态页还有{suffix}的数据绑定未达到效果图生成要求：{labels}。请先让 V3 补充样本行、重新匹配字段，或检索/修复模块数据。"
    )
}

fn static_page_data_quality_gate_details(
    modules: &[Value],
    message: &str,
    blocked_action: &str,
    next_step: &str,
    recommended_actions: &[&str],
) -> Value {
    let modules = modules
        .iter()
        .take(24)
        .map(static_page_data_quality_gate_module)
        .collect::<Vec<_>>();
    let module_count = modules.len();
    let gate_reason_counts = static_page_data_quality_gate_reason_counts(&modules);
    json!({
        "gate": "static_page_preview_data_quality",
        "blockedAction": blocked_action,
        "blocked_action": blocked_action,
        "reason": message,
        "attentionModuleCount": module_count,
        "attention_module_count": module_count,
        "attentionModules": modules.clone(),
        "attention_modules": modules,
        "gateReasonCounts": gate_reason_counts.clone(),
        "gate_reason_counts": gate_reason_counts,
        "recommendedActions": recommended_actions,
        "recommended_actions": recommended_actions,
        "nextStep": next_step,
        "next_step": next_step
    })
}

fn static_page_data_quality_gate_module(module: &Value) -> Value {
    let mut module = module.clone();
    let gate_reasons = static_page_preview_binding_module_gate_reasons(&module);
    if let Some(object) = module.as_object_mut() {
        let gate_reasons = json!(gate_reasons);
        object.insert("gateReasons".to_string(), gate_reasons.clone());
        object.insert("gate_reasons".to_string(), gate_reasons);
    }
    module
}

fn static_page_preview_binding_module_gate_reasons(module: &Value) -> Vec<String> {
    let mut reasons = Vec::new();
    let status = static_page_artifact_string(
        module,
        &["bindingQualityStatus", "binding_quality_status", "status"],
    )
    .unwrap_or_default();
    if !status.is_empty() && !matches!(status.as_str(), "confirmed" | "ready" | "non_chart") {
        reasons.push(format!("binding_quality_status:{status}"));
    }

    let chart_data_fit = static_page_artifact_string(module, &["chartDataFit", "chart_data_fit"])
        .unwrap_or_default();
    if !chart_data_fit.is_empty()
        && !matches!(
            chart_data_fit.as_str(),
            "ready" | "not_required" | "non_chart_ready"
        )
    {
        reasons.push(format!("chart_data_fit:{chart_data_fit}"));
    }

    let visualization_type =
        static_page_artifact_string(module, &["visualizationType", "visualization_type"])
            .unwrap_or_default();
    if static_page_visualization_needs_sample_rows(&visualization_type)
        && static_page_preview_quality_u64(module, &["sampleRows", "sample_rows"]) == 0
    {
        reasons.push("chart_sample_rows_missing".to_string());
    }

    if reasons.is_empty() {
        reasons.push("data_quality_attention_required".to_string());
    }
    reasons
}

fn static_page_data_quality_gate_reason_counts(modules: &[Value]) -> Value {
    let mut counts = BTreeMap::<String, u64>::new();
    for reason in modules
        .iter()
        .filter_map(|module| module.get("gateReasons").and_then(Value::as_array))
        .flatten()
        .filter_map(Value::as_str)
    {
        *counts.entry(reason.to_string()).or_insert(0) += 1;
    }
    json!(counts)
}

fn static_page_preview_data_quality_module_label(module: &Value) -> String {
    let title = static_page_artifact_string(module, &["title"])
        .or_else(|| static_page_artifact_string(module, &["moduleId", "module_id", "id"]))
        .unwrap_or_else(|| "未命名模块".to_string());
    let chart_data_fit = static_page_artifact_string(module, &["chartDataFit", "chart_data_fit"])
        .unwrap_or_default();
    let status = static_page_artifact_string(
        module,
        &["bindingQualityStatus", "binding_quality_status", "status"],
    )
    .unwrap_or_default();
    let marker = if !chart_data_fit.is_empty()
        && !matches!(
            chart_data_fit.as_str(),
            "ready" | "not_required" | "non_chart_ready"
        ) {
        chart_data_fit
    } else {
        status
    };
    if marker.is_empty() {
        title
    } else {
        format!("{title}（{marker}）")
    }
}

fn build_static_page_render_queue_manifest(
    draft: &StaticPageDraft,
    image_job: Option<&StaticPageImageJob>,
    workflow_execution: Option<&WorkflowExecution>,
    workflow_task_id: Option<domain_model::WorkflowTaskId>,
) -> Value {
    let payload = &draft.draft_payload;
    let data_snapshot = static_page_payload_value(payload, &["dataSnapshot", "data_snapshot"])
        .unwrap_or_else(|| build_static_page_data_snapshot(payload, &draft.selected_scope));
    let modules = static_page_payload_modules(payload);
    let export_package =
        build_static_page_queued_export_package_manifest(draft, &modules, &data_snapshot);
    json!({
        "draft_id": draft.id,
        "assistant_run_id": draft.assistant_run_id,
        "status": "queued",
        "renderer": "static-page-renderer-v1",
        "workflow_execution_id": workflow_execution.map(|execution| execution.id),
        "workflow_task_id": workflow_task_id,
        "workflow": {
            "status": "queued",
            "executionId": workflow_execution.map(|execution| execution.id),
            "taskId": workflow_task_id,
        },
        "image_job_id": image_job.map(|job| job.id),
        "preview_asset_key": image_job.and_then(|job| job.preview_asset_key.clone()),
        "visual_spec": static_page_payload_value(payload, &["visualSpec", "visual_spec"])
            .unwrap_or_else(|| build_static_page_visual_spec("client-delivery")),
        "render_spec": static_page_payload_value(payload, &["renderSpec", "render_spec"])
            .unwrap_or_else(build_static_page_render_spec),
        "data_snapshot": data_snapshot,
        "export_package": export_package,
        "queue_copy": "最终静态页正在后台制作，可以继续聊天或修改其他内容。",
    })
}

fn build_static_page_queued_export_package_manifest(
    draft: &StaticPageDraft,
    modules: &Value,
    data_snapshot: &Value,
) -> Value {
    let module_count = modules.as_array().map(Vec::len).unwrap_or(0);
    let echarts_requested_modules = modules
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter(|module| static_page_module_chart_runtime(module) == "echarts")
                .count()
        })
        .unwrap_or(0);
    json!({
        "kind": "static-page-export-package",
        "version": 1,
        "status": "queued",
        "draft_id": draft.id,
        "files": [
            {
                "path": "index.html",
                "role": "rendered_static_page",
                "mime": "text/html"
            },
            {
                "path": "asset-manifest.json",
                "role": "renderer_manifest",
                "mime": "application/json"
            },
            {
                "path": "data-snapshot.json",
                "role": "render_data_snapshot",
                "mime": "application/json"
            },
            {
                "path": "data.json",
                "role": "dynamic_data_snapshot",
                "mime": "application/json"
            },
            {
                "path": "modules.json",
                "role": "editable_module_plan",
                "mime": "application/json"
            }
        ],
        "dynamic_page_contract": build_static_page_dynamic_page_contract(),
        "debug": {
            "renderer": "static-page-renderer-v1",
            "module_count": module_count,
            "echarts_requested_modules": echarts_requested_modules,
            "data_snapshot_source": data_snapshot.get("source")
                .and_then(Value::as_str)
                .unwrap_or("unknown")
        }
    })
}

fn build_static_page_dynamic_page_contract() -> Value {
    json!({
        "version": 1,
        "data_file": "data.json",
        "source_snapshot_file": "data-snapshot.json",
        "data_role": "client_refresh_snapshot",
        "default_controls": ["time_range", "primary_partition", "manual_refresh", "auto_refresh"],
        "refresh_policy": {
            "mode": "poll_data_json_when_published",
            "interval_seconds": 60,
            "change_detection_fields": ["snapshotVersion", "updatedAt", "snapshot_version", "updated_at"]
        },
        "rendering_policy": "final_html_should_render_stateful_business_modules_from_data_json_when_present"
    })
}

fn build_static_page_fixed_task_dynamic_page_contract() -> Value {
    json!({
        "required": true,
        "data_file": "data.json",
        "source_snapshot_file": "data-snapshot.json",
        "time_selector_required": true,
        "time_range_selector_required": true,
        "primary_partition_selector_required": true,
        "manual_refresh_required": true,
        "auto_refresh_required": true,
        "refresh_interval_seconds": 60,
        "change_detection_fields": ["snapshotVersion", "updatedAt", "snapshot_version", "updated_at"],
        "static_html_must_render_from_data_json": true,
        "report_time_range": build_static_page_report_time_range_contract(),
    })
}

fn build_static_page_report_time_range_contract() -> Value {
    json!({
        "required": true,
        "selector": "time_range",
        "default_granularity": "month",
        "default_preset": "latest_available_month",
        "operating_report_default": "month",
        "supported_granularities": ["month", "quarter", "year", "custom_range"],
        "field_hints": [
            "month",
            "stat_month",
            "biz_month",
            "period_month",
            "date",
            "stat_date",
            "txdate",
            "created_at",
            "updated_at"
        ],
        "fallback_policy": "when only daily dates are available, aggregate or label operating reports by month while preserving custom range selection"
    })
}

fn normalize_static_page_dynamic_page_contract(candidate: Value) -> Value {
    if candidate.is_null() {
        return build_static_page_dynamic_page_contract();
    }
    let mut normalized = build_static_page_dynamic_page_contract();
    if let (Some(normalized_object), Some(candidate_object)) =
        (normalized.as_object_mut(), candidate.as_object())
    {
        for (key, value) in candidate_object {
            if key == "report_time_range" || key == "time_range_selector_required" {
                continue;
            }
            normalized_object.insert(key.clone(), value.clone());
        }
    }
    normalized
}

