fn build_static_page_data_snapshot(payload: &Value, selected_scope: &Value) -> Value {
    let evidence_state = payload
        .get("assistant_context")
        .and_then(|context| context.get("evidence_state"));
    build_static_page_data_snapshot_with_evidence(
        payload,
        selected_scope,
        evidence_state,
        "static_page_draft",
    )
}

fn build_static_page_data_snapshot_with_evidence(
    payload: &Value,
    selected_scope: &Value,
    evidence_state: Option<&Value>,
    source: &str,
) -> Value {
    let data_source_candidates =
        build_static_page_data_source_candidates(selected_scope, evidence_state);
    let field_candidates = build_static_page_field_candidates(selected_scope, evidence_state);
    let is_docs_page_template =
        static_page_template_reference_id_from_payload(payload) == Some("docs-page");
    let heading_candidate = if is_docs_page_template {
        static_page_heading_field_candidate(&field_candidates)
    } else {
        None
    };
    let module_bindings = static_page_payload_modules(payload)
        .as_array()
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .map(|mut module| {
            let sample_data =
                build_static_page_module_sample_data(&module, evidence_state, &field_candidates);
            let data_quality = static_page_sample_data_quality(&sample_data);
            let mut binding = module
                .get("dataBinding")
                .or_else(|| module.get("data_binding"))
                .cloned()
                .unwrap_or(Value::Null);
            binding = enrich_docs_page_heading_binding(&module, binding, heading_candidate);
            if binding.is_object() {
                if let Some(object) = module.as_object_mut() {
                    object.insert("dataBinding".to_string(), binding.clone());
                    object.insert("data_binding".to_string(), binding.clone());
                }
            }
            let visualization_type = module
                .get("visualization")
                .and_then(|visualization| visualization.get("type"))
                .cloned()
                .unwrap_or_else(|| json!("text-insight"));
            let chart_runtime = static_page_module_chart_runtime(&module);
            let chart_options = module
                .get("visualization")
                .and_then(|visualization| visualization.get("chartOptions"))
                .or_else(|| module.get("chartOptions"))
                .cloned()
                .unwrap_or_else(|| json!({}));
            let binding_quality = static_page_module_binding_quality(
                &module,
                &binding,
                &field_candidates,
                &sample_data,
                data_quality,
            );
            json!({
                "moduleId": module.get("id").cloned().unwrap_or(Value::Null),
                "title": module.get("title").cloned().unwrap_or(Value::Null),
                "binding": binding,
                "visualizationType": visualization_type,
                "chartRuntime": chart_runtime,
                "chartOptions": chart_options,
                "sampleData": sample_data,
                "dataQuality": data_quality,
                "bindingQuality": binding_quality.clone(),
                "bindingQualityStatus": binding_quality
                    .get("status")
                    .cloned()
                    .unwrap_or_else(|| json!("partial")),
                "chartDataFit": binding_quality
                    .get("chartDataFit")
                    .cloned()
                    .unwrap_or_else(|| json!("unknown")),
                "recommendedAction": binding_quality
                    .get("recommendedAction")
                    .cloned()
                    .unwrap_or(Value::Null),
            })
        })
        .collect::<Vec<_>>();
    let structure_signals =
        build_static_page_structure_signals(&field_candidates, &module_bindings);
    let snapshot_version = static_page_data_snapshot_version(
        source,
        selected_scope,
        &data_source_candidates,
        &field_candidates,
        &module_bindings,
    );
    let updated_at = static_page_data_snapshot_updated_at(evidence_state);
    let validation_summary = build_static_page_data_snapshot_validation_summary(
        &data_source_candidates,
        &field_candidates,
        &module_bindings,
        &updated_at,
    );
    json!({
        "version": 1,
        "snapshotVersion": snapshot_version,
        "snapshot_version": snapshot_version,
        "updatedAt": updated_at,
        "updated_at": updated_at,
        "source": source,
        "selected_scope": selected_scope,
        "evidence_status": evidence_state
            .and_then(|state| state.get("status"))
            .cloned()
            .unwrap_or(Value::Null),
        "refresh": {
            "dataFile": "data.json",
            "sourceSnapshotFile": "data-snapshot.json",
            "policy": "replace_data_json_then_client_refresh",
            "manualRefresh": true,
            "autoRefresh": true,
            "pollIntervalSeconds": 60,
            "changeDetectionFields": ["snapshotVersion", "updatedAt", "snapshot_version", "updated_at"],
        },
        "refresh_policy": {
            "data_file": "data.json",
            "source_snapshot_file": "data-snapshot.json",
            "policy": "replace_data_json_then_client_refresh",
            "manual_refresh": true,
            "auto_refresh": true,
            "poll_interval_seconds": 60,
            "change_detection_fields": ["snapshotVersion", "updatedAt", "snapshot_version", "updated_at"],
        },
        "data_source_candidates": data_source_candidates,
        "field_candidates": field_candidates,
        "module_bindings": module_bindings,
        "structure_signals": structure_signals,
        "validation_summary": validation_summary,
        "sampleRowCount": validation_summary.get("sampleRowCount").cloned().unwrap_or(Value::Null),
        "detailRowCount": validation_summary.get("detailRowCount").cloned().unwrap_or(Value::Null),
        "unitHints": validation_summary.get("unitHints").cloned().unwrap_or_else(|| json!([])),
    })
}

fn static_page_data_snapshot_version(
    source: &str,
    selected_scope: &Value,
    data_source_candidates: &Value,
    field_candidates: &Value,
    module_bindings: &[Value],
) -> String {
    let fingerprint = json!({
        "source": source,
        "selected_scope": selected_scope,
        "data_source_candidates": data_source_candidates,
        "field_candidates": field_candidates,
        "module_bindings": module_bindings,
    });
    let serialized = serde_json::to_string(&fingerprint).unwrap_or_else(|_| source.to_string());
    let mut hasher = DefaultHasher::new();
    serialized.hash(&mut hasher);
    format!("static-page-data-v1-{:016x}", hasher.finish())
}

fn static_page_data_snapshot_updated_at(evidence_state: Option<&Value>) -> Value {
    let Some(evidence_state) = evidence_state else {
        return Value::Null;
    };
    let mut timestamps = Vec::<String>::new();
    collect_static_page_data_snapshot_timestamp_hints(evidence_state, &mut timestamps);
    if let Some(items) = evidence_state
        .get("supplied_items")
        .or_else(|| evidence_state.get("suppliedItems"))
        .and_then(Value::as_array)
    {
        for item in items {
            collect_static_page_data_snapshot_timestamp_hints(item, &mut timestamps);
        }
    }
    timestamps.sort();
    timestamps.pop().map(Value::String).unwrap_or(Value::Null)
}

fn collect_static_page_data_snapshot_timestamp_hints(value: &Value, timestamps: &mut Vec<String>) {
    for key in [
        "updated_at",
        "updatedAt",
        "indexed_at",
        "indexedAt",
        "generated_at",
        "generatedAt",
        "snapshot_at",
        "snapshotAt",
        "completed_at",
        "completedAt",
        "created_at",
        "createdAt",
    ] {
        if let Some(timestamp) = value.get(key).and_then(Value::as_str) {
            let timestamp = timestamp.trim();
            if !timestamp.is_empty() {
                push_string_hint(timestamps, timestamp);
            }
        }
    }
}

fn build_static_page_data_snapshot_validation_summary(
    data_source_candidates: &Value,
    field_candidates: &Value,
    module_bindings: &[Value],
    updated_at: &Value,
) -> Value {
    let mut module_count = 0usize;
    let mut bound_module_count = 0usize;
    let mut ready_module_count = 0usize;
    let mut missing_binding_count = 0usize;
    let mut needs_sample_rows_count = 0usize;
    let mut sample_row_count = 0usize;
    let mut detail_row_count = 0usize;
    let mut unit_hints = Vec::<String>::new();

    if let Some(candidates) = field_candidates.as_array() {
        for candidate in candidates {
            collect_static_page_unit_hints(candidate, &mut unit_hints);
        }
    }

    for module in module_bindings {
        module_count += 1;
        let status = module
            .get("bindingQualityStatus")
            .or_else(|| module.get("binding_quality_status"))
            .and_then(Value::as_str)
            .unwrap_or("partial");
        let chart_data_fit = module
            .get("chartDataFit")
            .or_else(|| module.get("chart_data_fit"))
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        if status != "missing" {
            bound_module_count += 1;
        }
        if status == "confirmed" || matches!(chart_data_fit, "ready" | "not_required") {
            ready_module_count += 1;
        }
        if status == "missing" {
            missing_binding_count += 1;
        }
        if chart_data_fit == "needs_sample_rows" {
            needs_sample_rows_count += 1;
        }
        if let Some(rows) = module.get("sampleData").and_then(Value::as_array) {
            sample_row_count += rows.len();
            detail_row_count += rows.iter().filter(|row| row.is_object()).count();
            for row in rows {
                collect_static_page_unit_hints(row, &mut unit_hints);
            }
        }
    }

    unit_hints.truncate(12);
    let status = if module_count == 0 {
        "missing"
    } else if missing_binding_count > 0 || needs_sample_rows_count > 0 {
        "partial"
    } else {
        "ready"
    };

    json!({
        "version": 1,
        "status": status,
        "moduleCount": module_count,
        "boundModuleCount": bound_module_count,
        "readyModuleCount": ready_module_count,
        "missingBindingCount": missing_binding_count,
        "needsSampleRowsCount": needs_sample_rows_count,
        "sampleRowCount": sample_row_count,
        "detailRowCount": detail_row_count,
        "fieldCandidateCount": field_candidates.as_array().map(Vec::len).unwrap_or(0),
        "dataSourceCandidateCount": data_source_candidates.as_array().map(Vec::len).unwrap_or(0),
        "snapshotDate": updated_at.clone(),
        "unitHints": unit_hints,
    })
}

fn collect_static_page_unit_hints(value: &Value, hints: &mut Vec<String>) {
    let metric = static_page_artifact_string(value, &["metric", "valueLabel", "value_label"]);
    let aggregation =
        static_page_artifact_string(value, &["aggregation", "recommendedAggregation"]);
    if let Some(metric) = metric.as_deref() {
        push_string_hint(hints, metric);
        if let Some(aggregation) = aggregation.as_deref() {
            push_string_hint(hints, &format!("{aggregation}({metric})"));
        }
    }
    for key in [
        "unit",
        "unitHint",
        "unit_hint",
        "valueUnit",
        "value_unit",
        "displayUnit",
        "display_unit",
    ] {
        if let Some(unit) = value.get(key).and_then(Value::as_str) {
            let unit = unit.trim();
            if !unit.is_empty() {
                push_string_hint(hints, unit);
            }
        }
    }
}

fn build_static_page_structure_signals(
    field_candidates: &Value,
    module_bindings: &[Value],
) -> Value {
    const HINT_LIMIT: usize = 12;
    const FIELD_LIMIT: usize = 4;
    const MODULE_LIMIT: usize = 8;

    let mut section_title_hints = Vec::<String>::new();
    let field_candidate_briefs = field_candidates
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter(|candidate| {
                    static_page_artifact_string(candidate, &["fieldPath", "field_path", "field"])
                        .as_deref()
                        == Some("retrieval.section_title_hints")
                })
                .take(FIELD_LIMIT)
                .map(|candidate| {
                    let hints =
                        assistant_run_static_page_section_title_hints(candidate, HINT_LIMIT);
                    for hint in &hints {
                        push_string_hint(&mut section_title_hints, hint);
                    }
                    json!({
                        "sourceId": static_page_artifact_string(candidate, &["sourceId", "source_id"]).unwrap_or_default(),
                        "fieldPath": "retrieval.section_title_hints",
                        "label": static_page_artifact_string(candidate, &["label"]).unwrap_or_default(),
                        "kind": static_page_artifact_string(candidate, &["kind"]).unwrap_or_default(),
                        "confidence": candidate.get("confidence").cloned().unwrap_or(Value::Null),
                        "evidenceIds": candidate
                            .get("evidenceIds")
                            .or_else(|| candidate.get("evidence_ids"))
                            .cloned()
                            .unwrap_or_else(|| json!([])),
                        "sectionTitleHints": hints,
                    })
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let bound_modules = module_bindings
        .iter()
        .filter_map(|module| {
            let binding = module
                .get("binding")
                .or_else(|| module.get("dataBinding"))
                .or_else(|| module.get("data_binding"))
                .unwrap_or(&Value::Null);
            let binding_quality = module
                .get("bindingQuality")
                .or_else(|| module.get("binding_quality"))
                .unwrap_or(&Value::Null);
            let matched_candidate = binding_quality
                .get("matchedFieldCandidate")
                .or_else(|| binding_quality.get("matched_field_candidate"))
                .unwrap_or(&Value::Null);
            let field_path = static_page_artifact_string(binding, &["fieldPath", "field_path", "field"])
                .or_else(|| static_page_artifact_string(binding_quality, &["fieldPath", "field_path", "field"]))
                .or_else(|| static_page_artifact_string(matched_candidate, &["fieldPath", "field_path", "field"]));
            if field_path.as_deref() != Some("retrieval.section_title_hints") {
                return None;
            }
            let hints =
                assistant_run_static_page_section_title_hints(matched_candidate, HINT_LIMIT);
            for hint in &hints {
                push_string_hint(&mut section_title_hints, hint);
            }
            Some(json!({
                "moduleId": static_page_artifact_string(module, &["moduleId", "module_id"]).unwrap_or_default(),
                "title": static_page_artifact_string(module, &["title"]).unwrap_or_default(),
                "fieldPath": "retrieval.section_title_hints",
                "bindingQualityStatus": static_page_artifact_string(module, &["bindingQualityStatus", "binding_quality_status"])
                    .or_else(|| static_page_artifact_string(binding_quality, &["status"]))
                    .unwrap_or_default(),
                "sectionTitleHints": hints,
            }))
        })
        .take(MODULE_LIMIT)
        .collect::<Vec<_>>();

    section_title_hints.truncate(HINT_LIMIT);
    json!({
        "version": 1,
        "status": if section_title_hints.is_empty() { "none" } else { "available" },
        "policy": "source_structure_only_no_body_no_sample_rows",
        "sectionTitleHints": section_title_hints,
        "fieldCandidates": field_candidate_briefs,
        "boundModules": bound_modules,
    })
}

fn static_page_heading_field_candidate(field_candidates: &Value) -> Option<&Value> {
    field_candidates.as_array()?.iter().find(|candidate| {
        candidate
            .get("sourceId")
            .or_else(|| candidate.get("source_id"))
            .and_then(Value::as_str)
            == Some("evidence")
            && candidate
                .get("fieldPath")
                .or_else(|| candidate.get("field_path"))
                .and_then(Value::as_str)
                == Some("retrieval.section_title_hints")
            && !static_page_field_candidate_section_title_hints(candidate).is_empty()
    })
}

fn static_page_field_candidate_section_title_hints(candidate: &Value) -> Vec<String> {
    let mut hints = Vec::new();
    for key in ["sectionTitleHints", "section_title_hints"] {
        if let Some(value) = candidate.get(key) {
            collect_string_list(value, &mut hints);
        }
    }
    hints.truncate(6);
    hints
}

fn enrich_docs_page_heading_binding(
    module: &Value,
    binding: Value,
    heading_candidate: Option<&Value>,
) -> Value {
    let Some(heading_candidate) = heading_candidate else {
        return binding;
    };
    if !docs_page_structure_module_uses_heading_hints(module) {
        return binding;
    }
    if let Some(field_path) = static_page_binding_string(&binding, &["fieldPath", "field_path"]) {
        if field_path != "retrieval.section_title_hints" {
            return binding;
        }
    }

    let mut next = binding.as_object().cloned().unwrap_or_default();
    next.insert("type".to_string(), json!("retrieval_evidence"));
    next.insert("sourceId".to_string(), json!("evidence"));
    next.insert(
        "fieldPath".to_string(),
        json!("retrieval.section_title_hints"),
    );
    next.insert(
        "label".to_string(),
        heading_candidate
            .get("label")
            .and_then(Value::as_str)
            .map(|label| json!(label))
            .unwrap_or_else(|| json!("文档段落标题线索")),
    );
    if let Some(evidence_ids) = heading_candidate.get("evidenceIds") {
        next.insert("evidenceIds".to_string(), evidence_ids.clone());
    }
    Value::Object(next)
}

fn docs_page_structure_module_uses_heading_hints(module: &Value) -> bool {
    for key in ["id", "role"] {
        match module.get(key).and_then(Value::as_str) {
            Some("scope" | "steps" | "interfaces" | "checks") => return true,
            _ => {}
        }
    }
    false
}

fn build_static_page_data_source_candidates(
    selected_scope: &Value,
    evidence_state: Option<&Value>,
) -> Value {
    let mut candidates = vec![
        json!({
            "sourceId": "model",
            "type": "model_summary",
            "label": "模型总结",
            "available": true,
        }),
        json!({
            "sourceId": "conversation_memory",
            "type": "conversation_memory",
            "label": "对话历史",
            "available": selected_scope_requests_conversation_memory(selected_scope),
        }),
    ];

    let selected_dataset_ids = selected_dataset_ids_from_scope(selected_scope);
    if !selected_dataset_ids.is_empty() {
        candidates.push(json!({
            "sourceId": "selected_scope",
            "type": "selected_scope",
            "label": "当前选中范围",
            "available": true,
            "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
        }));
        candidates.push(json!({
            "sourceId": "dataset",
            "type": "dataset_metrics",
            "label": "数据集指标摘要",
            "available": true,
            "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
        }));
        candidates.push(json!({
            "sourceId": "evidence",
            "type": "retrieval_evidence",
            "label": "检索证据",
            "available": true,
            "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
        }));
    }

    push_static_page_database_data_source_candidates(&mut candidates, evidence_state);

    Value::Array(candidates)
}

fn push_static_page_database_data_source_candidates(
    candidates: &mut Vec<Value>,
    evidence_state: Option<&Value>,
) {
    let Some(evidence_items) = evidence_state
        .and_then(|state| state.get("supplied_items"))
        .and_then(Value::as_array)
    else {
        return;
    };

    let mut schema_dataset_ids = BTreeSet::new();
    let mut schema_source_ids = BTreeSet::new();
    let mut schema_tables = BTreeSet::new();
    let mut aggregate_dataset_ids = BTreeSet::new();
    let mut aggregate_source_ids = BTreeSet::new();
    let mut aggregate_tables = BTreeSet::new();
    let mut aggregate_fields = BTreeSet::new();

    for item in evidence_items {
        match item.get("type").and_then(Value::as_str).unwrap_or_default() {
            "database_schema_context" => {
                collect_static_page_candidate_string(item, "dataset_id", &mut schema_dataset_ids);
                collect_static_page_candidate_string(item, "source_id", &mut schema_source_ids);
                collect_static_page_candidate_string(item, "table", &mut schema_tables);
            }
            "database_aggregate" => {
                collect_static_page_candidate_string(
                    item,
                    "dataset_id",
                    &mut aggregate_dataset_ids,
                );
                collect_static_page_candidate_string(item, "source_id", &mut aggregate_source_ids);
                collect_static_page_candidate_string(item, "table", &mut aggregate_tables);
                collect_static_page_candidate_string(item, "value_label", &mut aggregate_fields);
                collect_static_page_candidate_string(item, "metric", &mut aggregate_fields);
            }
            _ => {}
        }
    }

    if !schema_tables.is_empty() {
        candidates.push(json!({
            "sourceId": "database_schema",
            "type": "database_schema_context",
            "label": "数据库结构语义",
            "available": true,
            "datasetIds": schema_dataset_ids.into_iter().collect::<Vec<_>>(),
            "sourceDatabaseIds": schema_source_ids.into_iter().collect::<Vec<_>>(),
            "tables": schema_tables.into_iter().collect::<Vec<_>>(),
        }));
    }
    if !aggregate_tables.is_empty() {
        candidates.push(json!({
            "sourceId": "database_aggregate",
            "type": "database_aggregate",
            "label": "数据库聚合样本",
            "available": true,
            "datasetIds": aggregate_dataset_ids.into_iter().collect::<Vec<_>>(),
            "sourceDatabaseIds": aggregate_source_ids.into_iter().collect::<Vec<_>>(),
            "tables": aggregate_tables.into_iter().collect::<Vec<_>>(),
            "fields": aggregate_fields.into_iter().collect::<Vec<_>>(),
        }));
    }
}

fn collect_static_page_candidate_string(item: &Value, key: &str, output: &mut BTreeSet<String>) {
    if let Some(value) = item.get(key).and_then(Value::as_str) {
        let value = value.trim();
        if !value.is_empty() {
            output.insert(value.to_string());
        }
    }
}

fn build_static_page_field_candidates(
    selected_scope: &Value,
    evidence_state: Option<&Value>,
) -> Value {
    const FIELD_CANDIDATE_LIMIT: usize = 24;

    let mut candidates = Vec::new();
    let mut seen = BTreeSet::new();
    let selected_dataset_ids = selected_dataset_ids_from_scope(selected_scope);
    if !selected_dataset_ids.is_empty() {
        push_static_page_field_candidate(
            &mut candidates,
            &mut seen,
            json!({
                "sourceId": "dataset",
                "fieldPath": "dataset.metrics_summary",
                "label": "数据集指标摘要",
                "kind": "summary",
                "recommendedAggregation": Value::Null,
                "confidence": 0.55,
                "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
            }),
            FIELD_CANDIDATE_LIMIT,
        );
    }

    let Some(evidence_items) = evidence_state
        .and_then(|state| state.get("supplied_items"))
        .and_then(Value::as_array)
    else {
        return Value::Array(candidates);
    };

    for item in evidence_items {
        match item.get("type").and_then(Value::as_str).unwrap_or_default() {
            "database_schema_context" => {
                push_static_page_database_schema_field_candidates(
                    &mut candidates,
                    &mut seen,
                    item,
                    FIELD_CANDIDATE_LIMIT,
                );
            }
            "database_aggregate" => {
                push_static_page_database_aggregate_field_candidates(
                    &mut candidates,
                    &mut seen,
                    item,
                    FIELD_CANDIDATE_LIMIT,
                );
            }
            "retrieval_evidence" => {
                let evidence_ref = static_page_evidence_ref(item);
                let evidence_ids = static_page_evidence_ids(item);
                push_static_page_field_candidate(
                    &mut candidates,
                    &mut seen,
                    json!({
                        "sourceId": "evidence",
                        "fieldPath": "retrieval.summary",
                        "label": "证据摘要",
                        "kind": "text",
                        "recommendedAggregation": Value::Null,
                        "confidence": 0.72,
                        "evidenceIds": evidence_ids,
                        "evidenceRef": evidence_ref,
                    }),
                    FIELD_CANDIDATE_LIMIT,
                );
                push_static_page_field_candidate(
                    &mut candidates,
                    &mut seen,
                    json!({
                        "sourceId": "evidence",
                        "fieldPath": "retrieval.content_excerpt",
                        "label": "证据原文片段",
                        "kind": "text",
                        "recommendedAggregation": Value::Null,
                        "confidence": 0.70,
                        "evidenceIds": static_page_evidence_ids(item),
                        "evidenceRef": static_page_evidence_ref(item),
                    }),
                    FIELD_CANDIDATE_LIMIT,
                );
                let section_title_hints = static_page_evidence_section_title_hints(item);
                if !section_title_hints.is_empty() {
                    push_static_page_field_candidate(
                        &mut candidates,
                        &mut seen,
                        json!({
                            "sourceId": "evidence",
                            "fieldPath": "retrieval.section_title_hints",
                            "label": format!("段落标题：{}", section_title_hints.join(" / ")),
                            "kind": "section_title",
                            "recommendedAggregation": Value::Null,
                            "confidence": 0.74,
                            "evidenceIds": static_page_evidence_ids(item),
                            "evidenceRef": static_page_evidence_ref(item),
                            "sectionTitleHints": section_title_hints,
                        }),
                        FIELD_CANDIDATE_LIMIT,
                    );
                }

                if let Some(media_context) =
                    item.get("media_context").filter(|value| value.is_object())
                {
                    push_static_page_media_field_candidates(
                        &mut candidates,
                        &mut seen,
                        media_context,
                        item,
                        FIELD_CANDIDATE_LIMIT,
                    );
                }

                let evidence_text = static_page_evidence_text(item).to_lowercase();
                for (field_path, label, kind, aggregation, keywords, confidence) in [
                    (
                        "orders.amount",
                        "订单金额/收入",
                        "metric",
                        Some("sum"),
                        &[
                            "order", "orders", "amount", "revenue", "sales", "gmv", "订单", "金额",
                            "收入",
                        ][..],
                        0.84,
                    ),
                    (
                        "orders.count",
                        "订单数量",
                        "metric",
                        Some("count"),
                        &["order", "orders", "count", "volume", "订单", "数量", "单量"][..],
                        0.78,
                    ),
                    (
                        "customers.count",
                        "客户数量",
                        "metric",
                        Some("count"),
                        &["customer", "customers", "client", "客户", "用户"][..],
                        0.76,
                    ),
                    (
                        "profit.margin",
                        "利润/毛利",
                        "metric",
                        Some("sum"),
                        &["profit", "margin", "gross", "利润", "毛利"][..],
                        0.76,
                    ),
                    (
                        "risk.level",
                        "风险等级",
                        "dimension",
                        None,
                        &["risk", "delay", "warning", "风险", "延期", "预警"][..],
                        0.80,
                    ),
                    (
                        "time.month",
                        "月份/时间",
                        "dimension",
                        None,
                        &[
                            "month", "date", "time", "period", "月份", "日期", "时间", "周期",
                        ][..],
                        0.72,
                    ),
                    (
                        "engagement.rate",
                        "触达/互动",
                        "metric",
                        Some("avg"),
                        &[
                            "engagement",
                            "newsletter",
                            "open",
                            "click",
                            "触达",
                            "互动",
                            "打开",
                            "点击",
                        ][..],
                        0.70,
                    ),
                ] {
                    if !static_page_text_contains_any(&evidence_text, keywords) {
                        continue;
                    }
                    push_static_page_field_candidate(
                        &mut candidates,
                        &mut seen,
                        json!({
                            "sourceId": "evidence",
                            "fieldPath": field_path,
                            "label": label,
                            "kind": kind,
                            "recommendedAggregation": aggregation,
                            "confidence": confidence,
                            "evidenceIds": static_page_evidence_ids(item),
                            "evidenceRef": static_page_evidence_ref(item),
                        }),
                        FIELD_CANDIDATE_LIMIT,
                    );
                }
            }
            "conversation_memory_item" => {
                push_static_page_field_candidate(
                    &mut candidates,
                    &mut seen,
                    json!({
                        "sourceId": "conversation_memory",
                        "fieldPath": "conversation.summary",
                        "label": "相关历史对话摘要",
                        "kind": "text",
                        "recommendedAggregation": Value::Null,
                        "confidence": 0.66,
                        "conversationMemoryItemId": item
                            .get("conversation_memory_item_id")
                            .cloned()
                            .unwrap_or(Value::Null),
                    }),
                    FIELD_CANDIDATE_LIMIT,
                );
            }
            _ => {}
        }
    }

    Value::Array(candidates)
}

fn push_static_page_database_schema_field_candidates(
    candidates: &mut Vec<Value>,
    seen: &mut BTreeSet<String>,
    item: &Value,
    limit: usize,
) {
    let table = static_page_artifact_string(item, &["table"]).unwrap_or_else(|| "database".into());
    let dataset_id = item.get("dataset_id").cloned().unwrap_or(Value::Null);
    let source_id = item.get("source_id").cloned().unwrap_or(Value::Null);
    let mut push_role_group = |group_key: &str,
                               label: &str,
                               kind: &str,
                               confidence: f64,
                               recommended_aggregation: Value| {
        let fields = item
            .get(group_key)
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        if fields.is_empty() {
            return;
        }
        push_static_page_field_candidate(
            candidates,
            seen,
            json!({
                "sourceId": "database_schema",
                "fieldPath": format!("database.schema.{table}.{group_key}"),
                "label": format!("{label}：{}", fields.iter().filter_map(Value::as_str).collect::<Vec<_>>().join(" / ")),
                "kind": kind,
                "recommendedAggregation": recommended_aggregation,
                "confidence": confidence,
                "datasetId": dataset_id.clone(),
                "sourceDatabaseId": source_id.clone(),
                "table": table.clone(),
                "fields": fields,
                "summary": item.get("summary").cloned().unwrap_or(Value::Null),
            }),
            limit,
        );
    };

    push_role_group("metrics", "数据库指标字段", "metric", 0.86, json!("sum"));
    push_role_group(
        "entity_dimensions",
        "数据库实体维度",
        "dimension",
        0.82,
        Value::Null,
    );
    push_role_group(
        "time_dimensions",
        "数据库时间维度",
        "dimension",
        0.82,
        Value::Null,
    );
    push_role_group(
        "category_dimensions",
        "数据库分类维度",
        "dimension",
        0.80,
        Value::Null,
    );
}

fn push_static_page_database_aggregate_field_candidates(
    candidates: &mut Vec<Value>,
    seen: &mut BTreeSet<String>,
    item: &Value,
    limit: usize,
) {
    let rows = item
        .get("rows")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    if rows == 0 {
        return;
    }
    let table = static_page_artifact_string(item, &["table"]).unwrap_or_else(|| "database".into());
    let aggregation =
        static_page_artifact_string(item, &["aggregation"]).unwrap_or_else(|| "sum".into());
    let metric = static_page_artifact_string(item, &["metric", "value_label"])
        .unwrap_or_else(|| "record_count".into());
    let field_path = static_page_database_aggregate_field_path(item);
    let label = format!("数据库聚合：{table} {aggregation}({metric})");
    let aggregate_sample_data =
        static_page_database_aggregate_sample_points_from_item(item, Some(&field_path));

    push_static_page_field_candidate(
        candidates,
        seen,
        json!({
            "sourceId": "database_aggregate",
            "fieldPath": field_path,
            "label": label,
            "kind": "metric",
            "recommendedAggregation": aggregation,
            "confidence": 0.92,
            "datasetId": item.get("dataset_id").cloned().unwrap_or(Value::Null),
            "sourceDatabaseId": item.get("source_id").cloned().unwrap_or(Value::Null),
            "table": table,
            "dimensions": item.get("dimensions").cloned().unwrap_or_else(|| json!([])),
            "metric": metric,
            "unit": item.get("unit").cloned().unwrap_or(Value::Null),
            "columns": item.get("columns").cloned().unwrap_or_else(|| json!([])),
            "sampleRows": rows,
            "sampleData": aggregate_sample_data,
            "scanLimit": item.get("scan_limit").cloned().unwrap_or(Value::Null),
            "rowLimit": item.get("row_limit").cloned().unwrap_or(Value::Null),
        }),
        limit,
    );

    let dataset_sample_data = static_page_database_aggregate_sample_points_from_item(
        item,
        Some("dataset.metrics_summary"),
    );
    push_static_page_field_candidate(
        candidates,
        seen,
        json!({
            "sourceId": "dataset",
            "fieldPath": "dataset.metrics_summary",
            "label": format!("数据集聚合指标：{metric}"),
            "kind": "metric",
            "recommendedAggregation": aggregation,
            "confidence": 0.88,
            "datasetId": item.get("dataset_id").cloned().unwrap_or(Value::Null),
            "sourceIdAlias": "database_aggregate",
            "table": table,
            "dimensions": item.get("dimensions").cloned().unwrap_or_else(|| json!([])),
            "metric": metric,
            "unit": item.get("unit").cloned().unwrap_or(Value::Null),
            "sampleRows": rows,
            "sampleData": dataset_sample_data,
            "scanLimit": item.get("scan_limit").cloned().unwrap_or(Value::Null),
        }),
        limit,
    );
}

fn static_page_module_binding_quality(
    module: &Value,
    binding: &Value,
    field_candidates: &Value,
    sample_data: &Value,
    data_quality: &str,
) -> Value {
    let visualization_type = module
        .get("visualization")
        .and_then(|visualization| visualization.get("type"))
        .and_then(Value::as_str)
        .unwrap_or("text-insight");
    let chart_runtime = static_page_module_chart_runtime(module);
    let source_id =
        static_page_binding_string(binding, &["sourceId", "source_id"]).unwrap_or_default();
    let field_path = static_page_module_field_path(module).map(ToString::to_string);
    let sample_rows = sample_data.as_array().map(Vec::len).unwrap_or(0);
    let chart_needs_rows = static_page_visualization_needs_sample_rows(visualization_type);
    let matched_candidate = field_path.as_deref().and_then(|field| {
        static_page_matching_field_candidate(field_candidates, &source_id, field)
    });
    let has_binding = binding.is_object()
        && (!source_id.is_empty()
            || field_path.is_some()
            || static_page_binding_string(binding, &["label"]).is_some());
    let has_confirmed_rows = (sample_rows > 0
        && matches!(
            data_quality,
            "module_data" | "evidence_value" | "schema_context"
        ))
        || static_page_sample_data_contains_kind(sample_data, "media_window")
        || static_page_sample_data_contains_kind(sample_data, "database_schema");
    let has_inferred_rows = sample_rows > 0 && !has_confirmed_rows;

    let (status, reason, chart_data_fit, recommended_action) = if has_confirmed_rows {
        (
            "confirmed",
            "renderable_data_rows",
            "ready",
            "数据样本可直接驱动该模块；交付前只需确认字段口径。",
        )
    } else if has_inferred_rows {
        (
            "partial",
            "inferred_evidence_signal",
            "inferred_signal",
            "当前只有检索信号或媒体线索，建议补充明确数据行或让模型先抽取结构化数据。",
        )
    } else if chart_needs_rows && field_path.is_none() && !has_binding {
        (
            "missing",
            "chart_without_binding",
            "missing_binding",
            "图表模块缺少字段绑定和样本数据，需要先绑定字段或补充数据行。",
        )
    } else if chart_needs_rows && matched_candidate.is_some() {
        (
            "partial",
            "matched_field_candidate_without_rows",
            "needs_sample_rows",
            "已匹配候选字段，但还缺少可渲染样本行；生成效果图前建议抽取或填写数据。",
        )
    } else if chart_needs_rows {
        (
            "partial",
            "binding_without_sample_rows",
            "needs_sample_rows",
            "已有绑定意图但缺少可渲染数据行，最终页会降级为待确认状态。",
        )
    } else if has_binding
        || matches!(
            source_id.as_str(),
            "model" | "session" | "conversation_memory"
        )
    {
        (
            "confirmed",
            "non_chart_binding_ready",
            "not_required",
            "文本或结论模块不强制要求数值样本，可按当前绑定继续规划。",
        )
    } else {
        (
            "missing",
            "non_chart_without_binding",
            "not_required",
            "该模块缺少内容来源，建议绑定模型总结、会话摘要或检索证据。",
        )
    };

    json!({
        "status": status,
        "reason": reason,
        "chartDataFit": chart_data_fit,
        "recommendedAction": recommended_action,
        "sourceId": if source_id.is_empty() { Value::Null } else { json!(source_id) },
        "fieldPath": field_path,
        "visualizationType": visualization_type,
        "chartRuntime": chart_runtime,
        "sampleRows": sample_rows,
        "dataQuality": data_quality,
        "matchedFieldCandidate": matched_candidate.cloned().unwrap_or(Value::Null),
        "confidence": static_page_binding_confidence(matched_candidate, sample_rows, status),
    })
}

fn static_page_visualization_needs_sample_rows(visualization_type: &str) -> bool {
    matches!(
        visualization_type,
        "kpi-cards" | "bar-chart" | "line-chart" | "donut-chart" | "table" | "risk-matrix"
    )
}

fn static_page_binding_string(binding: &Value, keys: &[&str]) -> Option<String> {
    keys.iter()
        .find_map(|key| binding.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
}

fn static_page_matching_field_candidate<'a>(
    field_candidates: &'a Value,
    source_id: &str,
    field_path: &str,
) -> Option<&'a Value> {
    field_candidates.as_array()?.iter().find(|candidate| {
        let candidate_field = candidate
            .get("fieldPath")
            .or_else(|| candidate.get("field_path"))
            .or_else(|| candidate.get("field"))
            .and_then(Value::as_str)
            .map(str::trim);
        if candidate_field != Some(field_path) {
            return false;
        }
        if source_id.is_empty() {
            return true;
        }
        candidate
            .get("sourceId")
            .or_else(|| candidate.get("source_id"))
            .and_then(Value::as_str)
            .map(str::trim)
            .map_or(true, |candidate_source| candidate_source == source_id)
    })
}

fn static_page_sample_data_contains_kind(sample_data: &Value, kind: &str) -> bool {
    sample_data.as_array().is_some_and(|items| {
        items
            .iter()
            .any(|item| item.get("kind").and_then(Value::as_str) == Some(kind))
    })
}

fn static_page_binding_confidence(
    matched_candidate: Option<&Value>,
    sample_rows: usize,
    status: &str,
) -> Value {
    if let Some(confidence) = matched_candidate
        .and_then(|candidate| candidate.get("confidence"))
        .and_then(Value::as_f64)
    {
        return json!(confidence);
    }
    match (status, sample_rows) {
        ("confirmed", rows) if rows > 0 => json!(0.92),
        ("confirmed", _) => json!(0.72),
        ("partial", rows) if rows > 0 => json!(0.62),
        ("partial", _) => json!(0.48),
        _ => json!(0.0),
    }
}

fn push_static_page_media_field_candidates(
    candidates: &mut Vec<Value>,
    seen: &mut BTreeSet<String>,
    media_context: &Value,
    item: &Value,
    limit: usize,
) {
    for (key, field_path, label, confidence) in [
        (
            "transcript_windows",
            "media.transcript_windows",
            "媒体转写时间窗",
            0.82,
        ),
        (
            "scene_windows",
            "media.scene_windows",
            "视频场景时间窗",
            0.78,
        ),
        (
            "keyframe_ocr_snippets",
            "media.keyframe_ocr_snippets",
            "关键帧 OCR 片段",
            0.76,
        ),
    ] {
        let has_items = media_context
            .get(key)
            .and_then(Value::as_array)
            .is_some_and(|items| !items.is_empty());
        if !has_items {
            continue;
        }
        push_static_page_field_candidate(
            candidates,
            seen,
            json!({
                "sourceId": "evidence",
                "fieldPath": field_path,
                "label": label,
                "kind": "media",
                "recommendedAggregation": Value::Null,
                "confidence": confidence,
                "evidenceIds": static_page_evidence_ids(item),
                "evidenceRef": static_page_evidence_ref(item),
                "mediaKind": media_context
                    .get("media_kind")
                    .cloned()
                    .unwrap_or_else(|| json!("unknown")),
                "timestamped": media_context
                    .get("has_timestamped_evidence")
                    .cloned()
                    .unwrap_or_else(|| json!(false)),
            }),
            limit,
        );
    }
}

fn build_static_page_module_sample_data(
    module: &Value,
    evidence_state: Option<&Value>,
    field_candidates: &Value,
) -> Value {
    let field_path = static_page_module_field_path(module);
    let explicit_points = build_static_page_module_explicit_points(module, field_path);
    if !explicit_points.is_empty() {
        return Value::Array(explicit_points);
    }
    let evidence_items = evidence_state
        .and_then(|state| state.get("supplied_items"))
        .and_then(Value::as_array);
    if let Some(evidence_items) = evidence_items {
        if let Some(field_path) = field_path.filter(|field_path| field_path.starts_with("media.")) {
            let media_points = build_static_page_media_sample_points(evidence_items, field_path);
            if !media_points.is_empty() {
                return Value::Array(media_points);
            }
        }

        let schema_points =
            build_static_page_database_schema_sample_points(evidence_items, module, field_path);
        if !schema_points.is_empty() {
            return Value::Array(schema_points);
        }

        let database_points =
            build_static_page_database_aggregate_sample_points(evidence_items, module, field_path);
        if !database_points.is_empty() {
            return Value::Array(database_points);
        }
    }

    let Some(field_path) = field_path else {
        return json!([]);
    };

    let candidate_points =
        build_static_page_field_candidate_sample_points(field_candidates, module, field_path);
    if !candidate_points.is_empty() {
        return Value::Array(candidate_points);
    }

    let Some(evidence_items) = evidence_items else {
        return json!([]);
    };

    let keywords = static_page_field_keywords(field_path);
    if keywords.is_empty() {
        return json!([]);
    }

    let explicit_points =
        build_static_page_explicit_metric_points(evidence_items, field_path, &keywords);
    if !explicit_points.is_empty() {
        return Value::Array(explicit_points);
    }

    let points = evidence_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str).unwrap_or_default() == "retrieval_evidence"
        })
        .enumerate()
        .filter_map(|(index, item)| {
            let value = static_page_keyword_signal_score(item, &keywords);
            if value <= 0.0 {
                return None;
            }
            Some(json!({
                "label": static_page_evidence_point_label(item, index),
                "value": value,
                "kind": "evidence_signal",
                "fieldPath": field_path,
                "evidenceIds": static_page_evidence_ids(item),
            }))
        })
        .take(6)
        .collect::<Vec<_>>();
    Value::Array(points)
}

fn static_page_module_field_path(module: &Value) -> Option<&str> {
    module
        .get("dataBinding")
        .or_else(|| module.get("data_binding"))
        .and_then(|binding| {
            binding
                .get("fieldPath")
                .or_else(|| binding.get("field_path"))
                .or_else(|| binding.get("field"))
        })
        .or_else(|| {
            module
                .get("visualization")
                .and_then(|visualization| visualization.get("chartOptions"))
                .and_then(|chart_options| chart_options.get("dataKey"))
        })
        .or_else(|| {
            module
                .get("chartOptions")
                .and_then(|chart_options| chart_options.get("dataKey"))
        })
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn static_page_module_source_id(module: &Value) -> String {
    module
        .get("dataBinding")
        .or_else(|| module.get("data_binding"))
        .and_then(|binding| {
            binding
                .get("sourceId")
                .or_else(|| binding.get("source_id"))
                .and_then(Value::as_str)
        })
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_default()
        .to_string()
}

fn build_static_page_field_candidate_sample_points(
    field_candidates: &Value,
    module: &Value,
    field_path: &str,
) -> Vec<Value> {
    let source_id = static_page_module_source_id(module);
    let Some(candidate) =
        static_page_matching_field_candidate(field_candidates, &source_id, field_path)
    else {
        return Vec::new();
    };
    static_page_field_candidate_sample_points(candidate, field_path)
}

fn static_page_field_candidate_sample_points(candidate: &Value, field_path: &str) -> Vec<Value> {
    for key in [
        "sampleData",
        "sample_data",
        "rows",
        "items",
        "values",
        "data",
        "sampleRows",
        "sample_rows",
    ] {
        let Some(array) = candidate.get(key).and_then(Value::as_array) else {
            continue;
        };
        let points = array
            .iter()
            .enumerate()
            .filter_map(|(index, item)| {
                static_page_field_candidate_sample_point(item, index, field_path)
            })
            .take(12)
            .collect::<Vec<_>>();
        if !points.is_empty() {
            return points;
        }
    }
    Vec::new()
}

fn static_page_field_candidate_sample_point(
    item: &Value,
    index: usize,
    field_path: &str,
) -> Option<Value> {
    let value = static_page_explicit_point_value(item)?;
    let label = static_page_explicit_point_label(item, index);
    let mut point = item.as_object().cloned().unwrap_or_default();
    point
        .entry("label".to_string())
        .or_insert_with(|| json!(label));
    point.insert("value".to_string(), json!(value));
    point
        .entry("kind".to_string())
        .or_insert_with(|| json!("field_candidate_sample"));
    point
        .entry("source".to_string())
        .or_insert_with(|| json!("field_candidate"));
    point
        .entry("fieldPath".to_string())
        .or_insert_with(|| json!(field_path));
    Some(Value::Object(point))
}

fn build_static_page_media_sample_points(evidence_items: &[Value], field_path: &str) -> Vec<Value> {
    let Some(array_key) = static_page_media_sample_array_key(field_path) else {
        return Vec::new();
    };
    evidence_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str).unwrap_or_default() == "retrieval_evidence"
        })
        .flat_map(|item| {
            item.get("media_context")
                .and_then(|context| context.get(array_key))
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(move |window| {
                    let text = static_page_media_sample_text(window, array_key)?;
                    let start_seconds = media_numeric_field(
                        window,
                        &["start_seconds", "start", "timestamp_seconds", "timestamp"],
                    );
                    let end_seconds = media_numeric_field(window, &["end_seconds", "end"]);
                    let timestamp_label =
                        static_page_media_timestamp_label(start_seconds, end_seconds);
                    let citation_label =
                        static_page_media_citation_label(item, timestamp_label.as_deref());
                    Some(json!({
                        "label": static_page_media_sample_label(window, array_key),
                        "value": 1.0,
                        "kind": "media_window",
                        "fieldPath": field_path,
                        "text": text,
                        "startSeconds": start_seconds,
                        "endSeconds": end_seconds,
                        "timestampLabel": timestamp_label,
                        "citationLabel": citation_label,
                        "source": media_string_field(window, &["source"]).unwrap_or_else(|| "media".to_string()),
                        "sourceLocator": item.get("source_locator").cloned().unwrap_or(Value::Null),
                        "evidenceIds": static_page_evidence_ids(item),
                        "evidenceRef": static_page_evidence_ref(item),
                    }))
                })
                .collect::<Vec<_>>()
        })
        .take(6)
        .collect()
}

fn build_static_page_database_schema_sample_points(
    evidence_items: &[Value],
    module: &Value,
    field_path: Option<&str>,
) -> Vec<Value> {
    let requested_schema = field_path.and_then(static_page_database_schema_field_path_parts);
    if requested_schema.is_none()
        && !static_page_module_requests_database_schema_overview(module, field_path)
    {
        return Vec::new();
    }

    let mut points = Vec::new();
    for item in evidence_items
        .iter()
        .filter(|item| item.get("type").and_then(Value::as_str) == Some("database_schema_context"))
    {
        let table =
            static_page_artifact_string(item, &["table"]).unwrap_or_else(|| "database".to_string());
        if let Some((requested_table, requested_group)) = requested_schema.as_ref() {
            if requested_table != &table {
                continue;
            }
            let fields = static_page_database_schema_group_fields(item, requested_group);
            if fields.is_empty() {
                continue;
            }
            points.push(static_page_database_schema_group_sample_point(
                item,
                &table,
                requested_group,
                fields,
                field_path,
            ));
        } else {
            points.push(static_page_database_schema_overview_sample_point(
                item, &table,
            ));
        }
        if points.len() >= 8 {
            break;
        }
    }
    points
}

fn static_page_database_schema_field_path_parts(field_path: &str) -> Option<(String, String)> {
    let mut parts = field_path.split('.');
    match (parts.next(), parts.next(), parts.next(), parts.next()) {
        (Some("database"), Some("schema"), Some(table), Some(group))
            if !table.trim().is_empty() && !group.trim().is_empty() =>
        {
            Some((table.trim().to_string(), group.trim().to_string()))
        }
        _ => None,
    }
}

fn static_page_module_requests_database_schema_overview(
    module: &Value,
    field_path: Option<&str>,
) -> bool {
    if field_path.is_some_and(|path| path.starts_with("database.schema")) {
        return true;
    }
    let module_text =
        static_page_database_aggregate_module_text(module, field_path).to_ascii_lowercase();
    static_page_text_contains_any(
        &module_text,
        &[
            "数据库",
            "数据表",
            "结构",
            "字段",
            "指标",
            "维度",
            "口径",
            "schema",
            "table",
            "field",
            "metric",
            "dimension",
        ],
    )
}

fn static_page_database_schema_group_fields(item: &Value, group: &str) -> Vec<String> {
    let mut fields = Vec::new();
    if group == "field_roles" {
        if let Some(roles) = item.get("field_roles").and_then(Value::as_array) {
            for role in roles {
                if let Some(name) = role.get("name").and_then(Value::as_str) {
                    push_string_hint(&mut fields, name);
                }
            }
        }
        return fields;
    }
    if let Some(value) = item.get(group) {
        collect_string_list(value, &mut fields);
    }
    fields
}

fn static_page_database_schema_group_sample_point(
    item: &Value,
    table: &str,
    group: &str,
    fields: Vec<String>,
    field_path: Option<&str>,
) -> Value {
    json!({
        "label": format!("{table} {}", static_page_database_schema_group_label(group)),
        "value": fields.len() as f64,
        "kind": "database_schema",
        "source": "database_schema",
        "fieldPath": field_path.map(ToString::to_string).unwrap_or_else(|| format!("database.schema.{table}.{group}")),
        "datasetId": item.get("dataset_id").cloned().unwrap_or(Value::Null),
        "sourceId": item.get("source_id").cloned().unwrap_or(Value::Null),
        "table": table,
        "fieldGroup": group,
        "fields": fields,
        "summary": item.get("summary").cloned().unwrap_or(Value::Null),
        "text": static_page_database_schema_group_text(item, table, group),
    })
}

fn static_page_database_schema_overview_sample_point(item: &Value, table: &str) -> Value {
    let metrics = static_page_database_schema_group_fields(item, "metrics");
    let entity_dimensions = static_page_database_schema_group_fields(item, "entity_dimensions");
    let time_dimensions = static_page_database_schema_group_fields(item, "time_dimensions");
    let category_dimensions = static_page_database_schema_group_fields(item, "category_dimensions");
    let field_count =
        metrics.len() + entity_dimensions.len() + time_dimensions.len() + category_dimensions.len();
    json!({
        "label": table,
        "value": field_count as f64,
        "kind": "database_schema",
        "source": "database_schema",
        "fieldPath": format!("database.schema.{table}.overview"),
        "datasetId": item.get("dataset_id").cloned().unwrap_or(Value::Null),
        "sourceId": item.get("source_id").cloned().unwrap_or(Value::Null),
        "table": table,
        "summary": item.get("summary").cloned().unwrap_or(Value::Null),
        "fieldGroups": {
            "metrics": metrics,
            "entityDimensions": entity_dimensions,
            "timeDimensions": time_dimensions,
            "categoryDimensions": category_dimensions,
        },
        "text": item
            .get("summary")
            .and_then(Value::as_str)
            .map(ToString::to_string)
            .unwrap_or_else(|| format!("数据库表 {table} 的结构语义。")),
    })
}

fn static_page_database_schema_group_label(group: &str) -> &'static str {
    match group {
        "metrics" => "指标字段",
        "entity_dimensions" => "实体维度",
        "time_dimensions" => "时间维度",
        "category_dimensions" => "分类维度",
        "field_roles" => "字段角色",
        _ => "字段",
    }
}

fn static_page_database_schema_group_text(item: &Value, table: &str, group: &str) -> String {
    let fields = static_page_database_schema_group_fields(item, group);
    let fields = if fields.is_empty() {
        "-".to_string()
    } else {
        fields.join(" / ")
    };
    format!(
        "数据库表 {table} 的{}：{fields}。",
        static_page_database_schema_group_label(group)
    )
}

fn build_static_page_database_aggregate_sample_points(
    evidence_items: &[Value],
    module: &Value,
    field_path: Option<&str>,
) -> Vec<Value> {
    let visualization_type = module
        .get("visualization")
        .and_then(|visualization| visualization.get("type"))
        .and_then(Value::as_str)
        .unwrap_or("text-insight");
    let can_drive_module = static_page_visualization_needs_sample_rows(visualization_type)
        || field_path
            .map(|path| {
                path.starts_with("database.aggregate")
                    || path == "dataset.metrics_summary"
                    || path == "selected_scope.metrics_summary"
            })
            .unwrap_or(false);
    if !can_drive_module {
        return Vec::new();
    }

    let Some(item) = static_page_database_aggregate_best_item(
        evidence_items,
        module,
        field_path,
        visualization_type,
    ) else {
        return Vec::new();
    };
    static_page_database_aggregate_sample_points_from_item(item, field_path)
}

fn static_page_database_aggregate_sample_points_from_item(
    item: &Value,
    field_path: Option<&str>,
) -> Vec<Value> {
    let Some(rows) = item.get("rows").and_then(Value::as_array) else {
        return Vec::new();
    };

    rows.iter()
        .enumerate()
        .filter_map(move |(index, row)| {
            let value = static_page_database_aggregate_row_value(row, item)?;
            Some(json!({
                "label": static_page_database_aggregate_row_label(row, item, index),
                "value": value,
                "kind": "database_aggregate",
                "source": "database_aggregate",
                "fieldPath": field_path
                    .map(ToString::to_string)
                    .unwrap_or_else(|| static_page_database_aggregate_field_path(item)),
                "datasetId": item.get("dataset_id").cloned().unwrap_or(Value::Null),
                "sourceId": item.get("source_id").cloned().unwrap_or(Value::Null),
                "table": item.get("table").cloned().unwrap_or(Value::Null),
                "aggregateRole": item.get("aggregate_role").cloned().unwrap_or(Value::Null),
                "aggregateIntent": item.get("aggregate_intent").cloned().unwrap_or(Value::Null),
                "dimensions": item.get("dimensions").cloned().unwrap_or_else(|| json!([])),
                "metric": item
                    .get("metric")
                    .cloned()
                    .or_else(|| item.get("value_label").cloned())
                    .unwrap_or(Value::Null),
                "unit": item.get("unit").cloned().unwrap_or(Value::Null),
                "aggregation": item.get("aggregation").cloned().unwrap_or(Value::Null),
                "scanLimit": item.get("scan_limit").cloned().unwrap_or(Value::Null),
                "rowLimit": item.get("row_limit").cloned().unwrap_or(Value::Null),
            }))
        })
        .take(12)
        .collect()
}

fn static_page_database_aggregate_best_item<'a>(
    evidence_items: &'a [Value],
    module: &Value,
    field_path: Option<&str>,
    visualization_type: &str,
) -> Option<&'a Value> {
    let module_text = static_page_database_aggregate_module_text(module, field_path);
    let mut best_item: Option<&Value> = None;
    let mut best_score = i32::MIN;
    for item in evidence_items.iter().filter(|item| {
        item.get("type").and_then(Value::as_str) == Some("database_aggregate")
            && item
                .get("rows")
                .and_then(Value::as_array)
                .is_some_and(|rows| !rows.is_empty())
    }) {
        let score =
            static_page_database_aggregate_module_score(item, &module_text, visualization_type);
        if score > best_score {
            best_score = score;
            best_item = Some(item);
        }
    }
    best_item
}

fn static_page_database_aggregate_module_score(
    item: &Value,
    module_text: &str,
    visualization_type: &str,
) -> i32 {
    let role = item
        .get("aggregate_role")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let dimension_text = static_page_database_aggregate_dimensions_text(item);
    let visualization_type = visualization_type.to_ascii_lowercase();
    let module_wants_trend = visualization_type == "line-chart"
        || prompt_has_any(
            module_text,
            &[
                "趋势", "变化", "时间", "日期", "日", "周", "月", "txdate", "date", "time", "trend",
            ],
        );
    let module_wants_comparison = prompt_has_any(
        module_text,
        &[
            "对比",
            "分类",
            "类型",
            "类别",
            "占比",
            "分布",
            "category",
            "type",
            "class",
            "comparison",
        ],
    );
    let module_wants_ranking = visualization_type == "kpi-cards"
        || prompt_has_any(
            module_text,
            &[
                "top", "排名", "排行", "排序", "前", "最高", "最大", "区域", "门店", "点位",
                "area", "rank",
            ],
        );
    let aggregate_is_time = role == "trend"
        || prompt_has_any(
            &dimension_text,
            &["txdate", "date", "time", "day", "month", "year"],
        );
    let aggregate_is_category = role == "comparison"
        || prompt_has_any(
            &dimension_text,
            &[
                "areatype", "category", "type", "class", "kind", "status", "level",
            ],
        );
    let aggregate_is_ranking = role == "ranking"
        || prompt_has_any(
            &dimension_text,
            &["areaname", "area", "name", "title", "store", "region"],
        );

    let mut score = 1;
    if module_wants_trend {
        score += if aggregate_is_time { 60 } else { -15 };
    }
    if module_wants_comparison {
        score += if aggregate_is_category { 60 } else { -10 };
    }
    if module_wants_ranking {
        score += if aggregate_is_ranking { 45 } else { -8 };
    }
    if !module_wants_trend && !module_wants_comparison && !module_wants_ranking {
        match role {
            "ranking" => score += 12,
            "comparison" => score += 8,
            "trend" => score += 6,
            _ => {}
        }
    }
    score
}

fn static_page_database_aggregate_module_text(module: &Value, field_path: Option<&str>) -> String {
    let mut parts = Vec::new();
    for key in ["id", "title", "subtitle", "role", "description", "summary"] {
        if let Some(value) = module.get(key).and_then(Value::as_str) {
            parts.push(value);
        }
    }
    if let Some(binding) = module
        .get("dataBinding")
        .or_else(|| module.get("data_binding"))
    {
        for key in [
            "sourceId",
            "source_id",
            "fieldPath",
            "field_path",
            "field",
            "label",
        ] {
            if let Some(value) = binding.get(key).and_then(Value::as_str) {
                parts.push(value);
            }
        }
    }
    if let Some(visualization) = module.get("visualization") {
        if let Some(value) = visualization.get("type").and_then(Value::as_str) {
            parts.push(value);
        }
        if let Some(chart_options) = visualization.get("chartOptions") {
            for key in ["dataKey", "labelKey", "valueKey", "categoryKey"] {
                if let Some(value) = chart_options.get(key).and_then(Value::as_str) {
                    parts.push(value);
                }
            }
        }
    }
    if let Some(chart_options) = module.get("chartOptions") {
        for key in ["dataKey", "labelKey", "valueKey", "categoryKey"] {
            if let Some(value) = chart_options.get(key).and_then(Value::as_str) {
                parts.push(value);
            }
        }
    }
    if let Some(field_path) = field_path {
        parts.push(field_path);
    }
    parts.join(" ")
}

fn static_page_database_aggregate_dimensions_text(item: &Value) -> String {
    item.get("dimensions")
        .and_then(Value::as_array)
        .map(|dimensions| {
            dimensions
                .iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join(" ")
        })
        .unwrap_or_default()
}

fn static_page_database_aggregate_field_path(item: &Value) -> String {
    static_page_artifact_string(item, &["metric", "value_label"])
        .map(|metric| format!("database.aggregate.{metric}"))
        .unwrap_or_else(|| "database.aggregate.value".to_string())
}

fn static_page_database_aggregate_row_value(row: &Value, item: &Value) -> Option<f64> {
    let object = row.as_object()?;
    if let Some(value) = object.get("value").and_then(static_page_json_number) {
        return Some(value);
    }
    if let Some(metric) = static_page_artifact_string(item, &["metric", "value_label"]) {
        if let Some(value) = object
            .get(metric.as_str())
            .and_then(static_page_json_number)
        {
            return Some(value);
        }
    }
    object.values().find_map(static_page_json_number)
}

fn static_page_database_aggregate_row_label(row: &Value, item: &Value, index: usize) -> String {
    let Some(object) = row.as_object() else {
        return format!("数据 {}", index + 1);
    };
    if let Some(dimensions) = item.get("dimensions").and_then(Value::as_array) {
        let label_parts = dimensions
            .iter()
            .filter_map(Value::as_str)
            .filter_map(|dimension| object.get(dimension).and_then(Value::as_str))
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
            .collect::<Vec<_>>();
        if !label_parts.is_empty() {
            return label_parts.join(" / ").chars().take(32).collect();
        }
    }
    static_page_explicit_point_label(row, index)
}

fn static_page_media_sample_array_key(field_path: &str) -> Option<&'static str> {
    let normalized = field_path.to_ascii_lowercase();
    if normalized.contains("media.transcript") {
        Some("transcript_windows")
    } else if normalized.contains("media.scene") {
        Some("scene_windows")
    } else if normalized.contains("media.keyframe") || normalized.contains("media.ocr") {
        Some("keyframe_ocr_snippets")
    } else {
        None
    }
}

fn static_page_media_sample_text(window: &Value, array_key: &str) -> Option<String> {
    match array_key {
        "scene_windows" => media_string_field(window, &["summary", "label"]),
        _ => media_string_field(window, &["text", "content", "summary"]),
    }
}

fn static_page_media_sample_label(window: &Value, array_key: &str) -> String {
    let timestamp = media_numeric_field(
        window,
        &["start_seconds", "start", "timestamp_seconds", "timestamp"],
    );
    let prefix = match array_key {
        "scene_windows" => "场景",
        "keyframe_ocr_snippets" => "关键帧",
        _ => "转写",
    };
    timestamp
        .map(|seconds| format!("{prefix} {:.1}s", seconds))
        .unwrap_or_else(|| prefix.to_string())
}

fn static_page_media_timestamp_label(
    start_seconds: Option<f64>,
    end_seconds: Option<f64>,
) -> Option<String> {
    match (start_seconds, end_seconds) {
        (Some(start), Some(end)) => Some(format!(
            "{} - {}",
            static_page_format_media_timestamp(start),
            static_page_format_media_timestamp(end)
        )),
        (Some(start), None) => Some(static_page_format_media_timestamp(start)),
        (None, Some(end)) => Some(static_page_format_media_timestamp(end)),
        (None, None) => None,
    }
}

fn static_page_media_citation_label(item: &Value, timestamp_label: Option<&str>) -> String {
    let source = item
        .get("source_locator")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("media");
    timestamp_label
        .map(|label| format!("{source} @ {label}"))
        .unwrap_or_else(|| source.to_string())
}

fn static_page_format_media_timestamp(seconds: f64) -> String {
    let safe_seconds = seconds.max(0.0);
    let total = safe_seconds.floor() as u64;
    let millis = ((safe_seconds - total as f64) * 1000.0).round() as u64;
    let hours = total / 3600;
    let minutes = (total % 3600) / 60;
    let secs = total % 60;
    if hours > 0 {
        format!("{hours:02}:{minutes:02}:{secs:02}.{millis:03}")
    } else {
        format!("{minutes:02}:{secs:02}.{millis:03}")
    }
}

fn static_page_module_chart_runtime(module: &Value) -> &'static str {
    let runtime = module
        .get("visualization")
        .and_then(|visualization| {
            visualization
                .get("chartRuntime")
                .or_else(|| visualization.get("runtime"))
                .or_else(|| {
                    visualization
                        .get("chartOptions")
                        .and_then(|chart_options| chart_options.get("chartRuntime"))
                })
                .or_else(|| {
                    visualization
                        .get("chartOptions")
                        .and_then(|chart_options| chart_options.get("runtime"))
                })
        })
        .or_else(|| module.get("chartRuntime"))
        .or_else(|| {
            module
                .get("chartOptions")
                .and_then(|chart_options| chart_options.get("chartRuntime"))
        })
        .and_then(Value::as_str)
        .map(str::trim);
    match runtime {
        Some("echarts") => "echarts",
        _ => "deterministic",
    }
}

fn build_static_page_module_explicit_points(
    module: &Value,
    field_path: Option<&str>,
) -> Vec<Value> {
    for candidate in static_page_module_explicit_data_candidates(module) {
        let points = static_page_explicit_points_from_value(candidate, field_path);
        if !points.is_empty() {
            return points;
        }
    }
    Vec::new()
}

fn static_page_module_explicit_data_candidates(module: &Value) -> Vec<&Value> {
    let mut candidates = Vec::new();
    if let Some(visualization) = module.get("visualization") {
        for key in [
            "sampleData",
            "sample_data",
            "data",
            "values",
            "rows",
            "items",
        ] {
            if let Some(value) = visualization.get(key) {
                candidates.push(value);
            }
        }
    }
    if let Some(binding) = module
        .get("dataBinding")
        .or_else(|| module.get("data_binding"))
    {
        for key in [
            "sampleData",
            "sample_data",
            "data",
            "values",
            "rows",
            "items",
        ] {
            if let Some(value) = binding.get(key) {
                candidates.push(value);
            }
        }
    }
    for key in [
        "sampleData",
        "sample_data",
        "data",
        "values",
        "rows",
        "items",
    ] {
        if let Some(value) = module.get(key) {
            candidates.push(value);
        }
    }
    candidates
}

fn static_page_explicit_points_from_value(value: &Value, field_path: Option<&str>) -> Vec<Value> {
    if let Some(array) = value.as_array() {
        return static_page_explicit_points_from_array(array, field_path);
    }
    for key in [
        "sampleData",
        "sample_data",
        "data",
        "values",
        "rows",
        "items",
    ] {
        if let Some(array) = value.get(key).and_then(Value::as_array) {
            let points = static_page_explicit_points_from_array(array, field_path);
            if !points.is_empty() {
                return points;
            }
        }
    }
    Vec::new()
}

fn static_page_explicit_points_from_array(array: &[Value], field_path: Option<&str>) -> Vec<Value> {
    array
        .iter()
        .enumerate()
        .filter_map(|(index, item)| static_page_explicit_point_from_item(item, index, field_path))
        .take(12)
        .collect()
}

fn static_page_explicit_point_from_item(
    item: &Value,
    index: usize,
    field_path: Option<&str>,
) -> Option<Value> {
    let value = static_page_explicit_point_value(item)?;
    let label = static_page_explicit_point_label(item, index);
    let mut point = Map::new();
    point.insert("label".to_string(), json!(label));
    point.insert("value".to_string(), json!(value));
    point.insert(
        "kind".to_string(),
        item.get("kind")
            .and_then(Value::as_str)
            .map(|kind| json!(kind))
            .unwrap_or_else(|| json!("module_data")),
    );
    point.insert("source".to_string(), json!("module_explicit_data"));
    if let Some(field_path) = field_path {
        point.insert("fieldPath".to_string(), json!(field_path));
    }
    Some(Value::Object(point))
}

fn static_page_explicit_point_value(item: &Value) -> Option<f64> {
    if let Some(value) = static_page_json_number(item) {
        return Some(value);
    }
    if let Some(array) = item.as_array() {
        return array.iter().find_map(static_page_json_number);
    }
    let object = item.as_object()?;
    for key in [
        "value",
        "amount",
        "count",
        "total",
        "score",
        "metric",
        "y",
        "订单金额",
        "金额",
        "收入",
        "数量",
    ] {
        if let Some(value) = object.get(key).and_then(static_page_json_number) {
            return Some(value);
        }
    }
    object.values().find_map(static_page_json_number)
}

fn static_page_explicit_point_label(item: &Value, index: usize) -> String {
    if let Some(array) = item.as_array() {
        if let Some(label) = array
            .iter()
            .find_map(|value| value.as_str().map(str::trim))
            .filter(|value| !value.is_empty())
        {
            return label.chars().take(18).collect();
        }
    }
    if let Some(object) = item.as_object() {
        for key in [
            "label", "name", "month", "date", "period", "category", "x", "月份", "日期", "分类",
        ] {
            if let Some(label) = object
                .get(key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            {
                return label.chars().take(18).collect();
            }
        }
        for value in object.values() {
            if let Some(label) = value
                .as_str()
                .map(str::trim)
                .filter(|candidate| !candidate.is_empty())
            {
                return label.chars().take(18).collect();
            }
        }
    }
    format!("数据 {}", index + 1)
}

fn static_page_json_number(value: &Value) -> Option<f64> {
    if let Some(number) = value.as_f64() {
        return Some(number);
    }
    let text = value.as_str()?.trim();
    if text.is_empty() {
        return None;
    }
    let normalized = text
        .trim_end_matches('%')
        .replace(',', "")
        .replace('，', "");
    normalized.parse::<f64>().ok()
}

fn static_page_sample_data_quality(sample_data: &Value) -> &'static str {
    let Some(items) = sample_data.as_array() else {
        return "not_available";
    };
    if items.is_empty() {
        return "not_available";
    }
    if items
        .iter()
        .any(|item| item.get("kind").and_then(Value::as_str) == Some("evidence_value"))
    {
        return "evidence_value";
    }
    if items
        .iter()
        .any(|item| item.get("kind").and_then(Value::as_str) == Some("database_aggregate"))
    {
        return "evidence_value";
    }
    if items
        .iter()
        .any(|item| item.get("kind").and_then(Value::as_str) == Some("field_candidate_sample"))
    {
        return "evidence_value";
    }
    if items
        .iter()
        .any(|item| item.get("kind").and_then(Value::as_str) == Some("module_data"))
    {
        return "module_data";
    }
    if items
        .iter()
        .any(|item| item.get("kind").and_then(Value::as_str) == Some("database_schema"))
    {
        return "schema_context";
    }
    "evidence_signal"
}

fn build_static_page_explicit_metric_points(
    evidence_items: &[Value],
    field_path: &str,
    keywords: &[&str],
) -> Vec<Value> {
    evidence_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str).unwrap_or_default() == "retrieval_evidence"
        })
        .enumerate()
        .flat_map(|(evidence_index, item)| {
            static_page_evidence_value_lines(item)
                .into_iter()
                .enumerate()
                .filter_map(move |(line_index, line)| {
                    let line_lower = line.to_lowercase();
                    if !static_page_text_contains_any(&line_lower, keywords) {
                        return None;
                    }
                    let value = static_page_metric_value_from_line(&line)?;
                    Some(json!({
                        "label": static_page_metric_label_from_line(&line, item, evidence_index, line_index, keywords),
                        "value": value,
                        "kind": "evidence_value",
                        "fieldPath": field_path,
                        "evidenceIds": static_page_evidence_ids(item),
                        "evidenceRef": static_page_evidence_ref(item),
                        "sectionTitleHints": static_page_evidence_section_title_hints(item),
                    }))
                })
                .collect::<Vec<_>>()
        })
        .take(6)
        .collect()
}

fn static_page_evidence_value_lines(item: &Value) -> Vec<String> {
    let mut text = String::new();
    for key in ["content_excerpt", "summary"] {
        if let Some(value) = item.get(key).and_then(Value::as_str) {
            if !text.is_empty() {
                text.push('\n');
            }
            text.push_str(value);
        }
    }
    text.split(|character| matches!(character, '\n' | '\r' | ';' | '；'))
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn static_page_metric_value_from_line(line: &str) -> Option<f64> {
    let candidates = static_page_number_candidates(line);
    if candidates.is_empty() {
        return None;
    }
    if candidates.len() == 1 {
        let value = candidates.first().copied()?;
        if static_page_number_looks_like_year(value)
            || (static_page_number_looks_like_period_part(value)
                && static_page_line_mentions_period(line))
        {
            return None;
        }
        return Some(value);
    }

    candidates
        .iter()
        .copied()
        .filter(|value| !static_page_number_looks_like_year(*value))
        .next_back()
        .or_else(|| candidates.last().copied())
}

fn static_page_number_candidates(line: &str) -> Vec<f64> {
    let mut values = Vec::new();
    let mut token = String::new();
    for character in line.chars().chain(std::iter::once(' ')) {
        let can_continue_number = character.is_ascii_digit()
            || character == '.'
            || character == ','
            || ((character == '-' || character == '+') && token.is_empty());
        if can_continue_number {
            token.push(character);
            continue;
        }
        if token.chars().any(|candidate| candidate.is_ascii_digit()) {
            let normalized = token.replace(',', "");
            if let Ok(value) = normalized.parse::<f64>() {
                values.push(value);
            }
        }
        token.clear();
    }
    values
}

fn static_page_number_looks_like_year(value: f64) -> bool {
    (1900.0..=2100.0).contains(&value) && value.fract().abs() < f64::EPSILON
}

fn static_page_number_looks_like_period_part(value: f64) -> bool {
    (1.0..=31.0).contains(&value) && value.fract().abs() < f64::EPSILON
}

fn static_page_line_mentions_period(line: &str) -> bool {
    let lower = line.to_lowercase();
    ["月", "日", "date", "month", "period", "季度", "周"]
        .iter()
        .any(|marker| lower.contains(marker))
}

fn static_page_metric_label_from_line(
    line: &str,
    item: &Value,
    evidence_index: usize,
    line_index: usize,
    keywords: &[&str],
) -> String {
    for part in line.split([',', '，', '|', '\t']) {
        let candidate = part.trim();
        if candidate.is_empty() {
            continue;
        }
        let candidate_lower = candidate.to_lowercase();
        if static_page_text_contains_any(&candidate_lower, keywords) {
            continue;
        }
        if static_page_string_is_numeric_only(candidate) {
            continue;
        }
        return candidate.chars().take(18).collect();
    }

    if line_index == 0 {
        static_page_evidence_point_label(item, evidence_index)
    } else {
        format!(
            "{}-{}",
            static_page_evidence_point_label(item, evidence_index),
            line_index + 1
        )
    }
}

fn static_page_string_is_numeric_only(value: &str) -> bool {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return false;
    }
    let numeric_chars = trimmed
        .chars()
        .filter(|character| {
            character.is_ascii_digit()
                || matches!(character, '.' | ',' | '-' | '+' | '%' | ' ' | '万' | '亿')
        })
        .count();
    numeric_chars == trimmed.chars().count()
}

fn static_page_field_keywords(field_path: &str) -> Vec<&'static str> {
    let normalized = field_path.to_ascii_lowercase();
    if normalized.contains("orders.amount") || normalized.contains("revenue") {
        return vec![
            "order", "orders", "amount", "revenue", "sales", "gmv", "订单", "金额", "收入",
        ];
    }
    if normalized.contains("orders.count") || normalized.contains("order_count") {
        return vec!["order", "orders", "count", "volume", "订单", "数量", "单量"];
    }
    if normalized.contains("customer") {
        return vec!["customer", "customers", "client", "客户", "用户"];
    }
    if normalized.contains("profit") || normalized.contains("margin") {
        return vec!["profit", "margin", "gross", "利润", "毛利"];
    }
    if normalized.contains("risk") {
        return vec!["risk", "delay", "warning", "风险", "延期", "预警"];
    }
    if normalized.contains("time") || normalized.contains("month") || normalized.contains("date") {
        return vec![
            "month", "date", "time", "period", "月份", "日期", "时间", "周期",
        ];
    }
    if normalized.contains("engagement") {
        return vec![
            "engagement",
            "newsletter",
            "open",
            "click",
            "触达",
            "互动",
            "打开",
            "点击",
        ];
    }
    Vec::new()
}

fn static_page_keyword_signal_score(item: &Value, keywords: &[&str]) -> f64 {
    let text = static_page_evidence_text(item).to_lowercase();
    let mut score = keywords
        .iter()
        .filter(|keyword| text.contains(&keyword.to_lowercase()))
        .count() as f64;

    if let Some(term_weights) = item
        .get("evidence_manifest")
        .and_then(|manifest| manifest.pointer("/embedding/term_weights"))
        .and_then(Value::as_object)
    {
        for (term, weight) in term_weights {
            if keywords
                .iter()
                .any(|keyword| keyword.eq_ignore_ascii_case(term))
            {
                score += weight.as_f64().unwrap_or(0.0).max(0.0);
            }
        }
    }

    if let Some(score_value) = item.get("score").and_then(Value::as_f64) {
        score += score_value.clamp(0.0, 1.0);
    } else if let Some(recall_score) = item.get("recall_score").and_then(Value::as_f64) {
        score += recall_score.clamp(0.0, 1.0);
    }

    (score * 10.0).round() / 10.0
}

fn static_page_evidence_point_label(item: &Value, index: usize) -> String {
    item.get("source_locator")
        .and_then(Value::as_str)
        .map(|value| {
            value
                .rsplit('/')
                .next()
                .unwrap_or(value)
                .split('#')
                .next()
                .unwrap_or(value)
                .trim()
                .to_string()
        })
        .filter(|value| !value.is_empty())
        .or_else(|| {
            item.get("summary")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(|value| value.chars().take(18).collect::<String>())
        })
        .unwrap_or_else(|| format!("证据{}", index + 1))
}

fn push_static_page_field_candidate(
    candidates: &mut Vec<Value>,
    seen: &mut BTreeSet<String>,
    candidate: Value,
    limit: usize,
) {
    if candidates.len() >= limit {
        return;
    }
    let key = format!(
        "{}:{}",
        candidate
            .get("sourceId")
            .and_then(Value::as_str)
            .unwrap_or("unknown"),
        candidate
            .get("fieldPath")
            .and_then(Value::as_str)
            .unwrap_or_default(),
    );
    if key.ends_with(':') || !seen.insert(key) {
        return;
    }
    candidates.push(candidate);
}

fn static_page_evidence_ids(item: &Value) -> Vec<Value> {
    item.get("retrieval_evidence_id")
        .cloned()
        .map(|value| vec![value])
        .unwrap_or_default()
}

fn static_page_evidence_ref(item: &Value) -> Value {
    json!({
        "retrievalEvidenceId": item.get("retrieval_evidence_id").cloned().unwrap_or(Value::Null),
        "datasetId": item.get("dataset_id").cloned().unwrap_or(Value::Null),
        "documentId": item.get("document_id").cloned().unwrap_or(Value::Null),
        "documentChunkId": item.get("document_chunk_id").cloned().unwrap_or(Value::Null),
        "sourceLocator": item.get("source_locator").cloned().unwrap_or(Value::Null),
        "sectionTitleHints": static_page_evidence_section_title_hints(item),
    })
}

fn static_page_evidence_text(item: &Value) -> String {
    let mut parts = Vec::new();
    for key in [
        "summary",
        "content_excerpt",
        "source_locator",
        "payload_filter_key",
    ] {
        if let Some(value) = item.get(key).and_then(Value::as_str) {
            parts.push(value.to_string());
        }
    }
    parts.extend(static_page_evidence_section_title_hints(item));
    if let Some(term_weights) = item
        .get("evidence_manifest")
        .and_then(|manifest| manifest.pointer("/embedding/term_weights"))
        .and_then(Value::as_object)
    {
        parts.extend(term_weights.keys().cloned());
    }
    parts.join(" ")
}

fn static_page_evidence_section_title_hints(item: &Value) -> Vec<String> {
    let mut hints = Vec::new();
    for pointer in [
        "/evidence_manifest/evidence/section_title_hints",
        "/evidence_manifest/section_title_hints",
        "/evidence_manifest/metadata/section_title_hints",
        "/evidence/section_title_hints",
        "/section_title_hints",
        "/metadata/section_title_hints",
    ] {
        if let Some(value) = item.pointer(pointer) {
            collect_string_list(value, &mut hints);
        }
    }
    hints.truncate(6);
    hints
}

fn static_page_text_contains_any(text: &str, keywords: &[&str]) -> bool {
    keywords
        .iter()
        .any(|keyword| text.contains(&keyword.to_lowercase()))
}

fn build_static_page_preview_contract(
    style_direction: &str,
    modules: &Value,
    render_spec: &Value,
    mobile_order: &Value,
    patch: Option<Value>,
) -> Value {
    let contract_source = json!({
        "style_direction": style_direction,
        "modules": modules,
        "render_spec": render_spec,
        "mobile_order": mobile_order,
    });
    let next_fingerprint = static_page_design_fingerprint(&contract_source);
    let should_mark_stale = patch.as_ref().is_some_and(|previous_contract| {
        static_page_preview_contract_is_stale(previous_contract, &next_fingerprint)
    });
    let mut contract = json!({
        "version": 1,
        "kind": "static-page-preview-contract",
        "status": "not_requested",
        "draftFingerprint": next_fingerprint,
        "imageJobId": Value::Null,
        "assetKey": Value::Null,
        "confirmedAt": Value::Null,
        "renderExpectation": "final HTML/CSS/SVG should reproduce the generated preview without baking editable text or charts into the image",
    });
    if let Some(patch) = patch {
        merge_json_value(&mut contract, &patch);
        set_payload_string(
            &mut contract,
            "draftFingerprint",
            &static_page_design_fingerprint(&contract_source),
        );
    }
    if should_mark_stale {
        mark_static_page_preview_contract_stale(
            &mut contract,
            "draft design changed after the preview was requested or confirmed",
        );
    }
    contract
}

fn static_page_preview_contract_is_stale(
    previous_contract: &Value,
    next_fingerprint: &str,
) -> bool {
    let Some(previous_fingerprint) = previous_contract
        .get("draftFingerprint")
        .or_else(|| previous_contract.get("draft_fingerprint"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return false;
    };
    if previous_fingerprint == next_fingerprint {
        return false;
    }
    matches!(
        previous_contract
            .get("status")
            .and_then(Value::as_str)
            .map(str::trim),
        Some("queued" | "running" | "preview_ready" | "confirmed" | "rendering" | "rendered")
    )
}

fn mark_static_page_preview_contract_stale(contract: &mut Value, reason: &str) {
    set_payload_string(contract, "status", "stale");
    set_payload_value(contract, "imageJobId", Value::Null);
    set_payload_value(contract, "assetKey", Value::Null);
    set_payload_value(contract, "confirmedAt", Value::Null);
    set_payload_string(contract, "staleReason", reason);
    set_payload_string(contract, "staleAt", &Utc::now().to_rfc3339());
}

fn static_page_preview_contract_status(contract: &Value) -> Option<&str> {
    contract
        .get("status")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn static_page_design_fingerprint(value: &Value) -> String {
    let serialized = serde_json::to_string(value).unwrap_or_else(|_| "{}".to_string());
    let mut hash: u32 = 0;
    for byte in serialized.bytes() {
        hash = hash.wrapping_mul(31).wrapping_add(byte as u32);
    }
    format!("design-{hash:08x}")
}

fn static_page_payload_modules(payload: &Value) -> Value {
    payload
        .get("modules")
        .and_then(Value::as_array)
        .cloned()
        .map(Value::Array)
        .unwrap_or_else(|| Value::Array(Vec::new()))
}

fn static_page_payload_mobile_order(payload: &Value, modules: &Value) -> Value {
    let module_ids = modules
        .as_array()
        .map(|items| {
            items
                .iter()
                .filter_map(|module| {
                    module
                        .get("id")
                        .and_then(Value::as_str)
                        .map(str::trim)
                        .filter(|value| !value.is_empty())
                        .map(ToOwned::to_owned)
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let module_id_set = module_ids.iter().cloned().collect::<BTreeSet<_>>();
    let mut seen = BTreeSet::<String>::new();
    let mut ordered = Vec::<Value>::new();
    if let Some(requested) = static_page_payload_value(payload, &["mobileOrder", "mobile_order"])
        .and_then(|value| value.as_array().cloned())
    {
        for item in requested {
            let Some(id) = item
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
            else {
                continue;
            };
            if module_id_set.contains(&id) && seen.insert(id.clone()) {
                ordered.push(json!(id));
            }
        }
    }
    for id in module_ids {
        if seen.insert(id.clone()) {
            ordered.push(json!(id));
        }
    }
    Value::Array(ordered)
}

fn static_page_payload_string(payload: &Value, keys: &[&str]) -> Option<String> {
    static_page_value_string(payload, keys)
}

fn static_page_value_string(value: &Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        value
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    })
}

fn static_page_value_i64(value: &Value, keys: &[&str]) -> Option<i64> {
    keys.iter()
        .find_map(|key| value.get(*key).and_then(Value::as_i64))
}

fn static_page_payload_value(payload: &Value, keys: &[&str]) -> Option<Value> {
    keys.iter().find_map(|key| payload.get(*key).cloned())
}

