    fn wecom_test_encoding_aes_key() -> String {
        use base64::{engine::general_purpose, Engine as _};

        let key: Vec<u8> = (1u8..=32).collect();
        general_purpose::STANDARD
            .encode(key)
            .trim_end_matches('=')
            .to_string()
    }

    fn encrypt_feishu_test_payload(payload: &Value, encrypt_key: &str) -> String {
        use aes::Aes256;
        use base64::{engine::general_purpose, Engine as _};
        use cbc::cipher::{block_padding::NoPadding, BlockEncryptMut, KeyIvInit};

        let key = Sha256::digest(encrypt_key.as_bytes());
        let iv = [0x24u8; 16];
        let mut plaintext = payload.to_string().into_bytes();
        let padding = 16 - (plaintext.len() % 16);
        let padding = if padding == 0 { 16 } else { padding };
        plaintext.extend(std::iter::repeat_n(padding as u8, padding));
        let plaintext_len = plaintext.len();
        let encrypted = cbc::Encryptor::<Aes256>::new_from_slices(&key, &iv)
            .expect("test AES encryptor should initialize")
            .encrypt_padded_mut::<NoPadding>(&mut plaintext, plaintext_len)
            .expect("test plaintext is block aligned");
        let mut envelope = iv.to_vec();
        envelope.extend_from_slice(encrypted);
        general_purpose::STANDARD.encode(envelope)
    }

    fn encrypt_wecom_test_xml(xml: &str, receive_id: &str, encoding_aes_key: &str) -> String {
        use aes::Aes256;
        use base64::{engine::general_purpose, Engine as _};
        use cbc::cipher::{block_padding::NoPadding, BlockEncryptMut, KeyIvInit};

        let key = general_purpose::STANDARD
            .decode(format!("{encoding_aes_key}="))
            .expect("test EncodingAESKey should decode");
        let mut plaintext = vec![0x42; 16];
        plaintext.extend_from_slice(&(xml.len() as u32).to_be_bytes());
        plaintext.extend_from_slice(xml.as_bytes());
        plaintext.extend_from_slice(receive_id.as_bytes());
        let padding = 32 - (plaintext.len() % 32);
        let padding = if padding == 0 { 32 } else { padding };
        plaintext.extend(std::iter::repeat_n(padding as u8, padding));
        let plaintext_len = plaintext.len();
        let encrypted = cbc::Encryptor::<Aes256>::new_from_slices(&key, &key[..16])
            .expect("test AES encryptor should initialize")
            .encrypt_padded_mut::<NoPadding>(&mut plaintext, plaintext_len)
            .expect("test plaintext is block aligned");
        general_purpose::STANDARD.encode(encrypted)
    }

    #[test]
    fn external_bot_message_maps_to_assistant_run_request_scope() {
        let message = sample_external_bot_message();
        let request = external_bot_message_to_assistant_run_request("generic-chat-main", &message);

        assert_eq!(request.prompt, "订单延期风险有哪些？");
        assert_eq!(
            request.local_thread_id.as_deref(),
            Some("external:generic_chat:tenant-ext-001:bot-v3:chat-risk-room")
        );
        assert_eq!(
            request
                .startup_briefing
                .as_ref()
                .and_then(|value| value.get("surface"))
                .and_then(Value::as_str),
            Some("external_channel")
        );
        let startup_briefing = request
            .startup_briefing
            .as_ref()
            .expect("external request should include startup briefing");
        assert_eq!(
            startup_briefing["modelAwarenessPolicy"]["externalSearchPolicy"]["status"],
            json!("planned_v3_controlled_read_only")
        );
        assert!(
            startup_briefing["modelAwarenessPolicy"]["additiveContextRule"]
                .as_str()
                .expect("additive context rule")
                .contains("不是能力限制")
        );
        assert!(
            startup_briefing["modelAwarenessPolicy"]["unavailableEvidenceRule"]
                .as_str()
                .expect("unavailable evidence rule")
                .contains("当前不可见/未供料")
        );
        assert_eq!(
            startup_briefing["visibleScopePolicy"]["permission_filtering"],
            json!("before_model_context")
        );
        assert_eq!(
            startup_briefing["visibleScopePolicy"]["hidden_documents_supplied"],
            json!(false)
        );
        assert_eq!(
            request
                .selected_scope
                .as_ref()
                .and_then(|value| value.get("channel_connection_id"))
                .and_then(Value::as_str),
            Some("generic-chat-main")
        );
        assert_eq!(
            request
                .context_policy_hint
                .as_ref()
                .and_then(|value| value.get("permission_boundary"))
                .and_then(Value::as_str),
            Some("resolve_external_principal_before_retrieval")
        );
        assert_eq!(request.scope_candidates.len(), 1);
    }

    #[test]
    fn external_requested_skills_are_supplied_to_model_policy() {
        let mut message = sample_external_bot_message();
        message.requested_skills = vec![ExternalRequestedSkillView {
            skill_id: "contract_review".to_string(),
            version: Some("2026-05-20".to_string()),
            mode: Some("required".to_string()),
            arguments: Some(json!({
                "focus": "risk",
                "do_not_log_secret": "token-like-value"
            })),
        }];

        let request = external_bot_message_to_assistant_run_request("generic-chat-main", &message);
        let startup_briefing = request
            .startup_briefing
            .as_ref()
            .expect("external request should include startup briefing");
        assert_eq!(
            startup_briefing["requestedSkills"]["skills"][0]["skill_id"],
            json!("contract_review")
        );
        assert_eq!(
            startup_briefing["requestedSkills"]["skills"][0]["mode"],
            json!("required")
        );
        assert_eq!(
            startup_briefing["requestedSkills"]["skills"][0]["arguments"]["focus"],
            json!("risk")
        );
        assert_eq!(
            request
                .context_policy_hint
                .as_ref()
                .expect("context policy")["skill_policy"]["requested_skills"]["skills"][0]
                ["version"],
            json!("2026-05-20")
        );

        let input = build_assistant_run_provider_input(&request);
        assert!(input.contains("本轮 SKILL 策略"));
        assert!(input.contains("contract_review"));

        let summary = external_bot_message_payload_summary(&message);
        let serialized_summary = summary.to_string();
        assert_eq!(summary["requested_skill_count"], json!(1));
        let argument_keys = summary["requested_skills"][0]["argument_keys"]
            .as_array()
            .expect("argument keys should be listed");
        assert!(argument_keys.contains(&json!("do_not_log_secret")));
        assert!(argument_keys.contains(&json!("focus")));
        assert!(!serialized_summary.contains("token-like-value"));
    }

