    #[test]
    fn static_page_stable_artifact_key_uses_canonical_dataset_not_temporary_dataset() {
        let canonical_dataset_id = DatasetId::new();
        let temporary_dataset_id = DatasetId::new();
        let selected_scope = json!({
            "dataset_external_ids": ["xinbai-main"],
            "canonical_datasets": [{"type": "dataset", "id": canonical_dataset_id}],
            "datasets": [{"type": "dataset", "id": temporary_dataset_id}]
        });
        let source_refs = json!({
            "source": "external_channel_static_page_artifact_request",
            "channel_connection_id": "generic-chat-main"
        });

        let key = static_page_dataset_artifact_key(
            &selected_scope,
            &source_refs,
            "template:default",
            Some("generic-chat-main"),
        )
        .expect("stable key");

        assert!(key.contains("dataset_external_id:xinbai-main"));
        assert!(key.contains("channel:generic-chat-main"));
        assert!(!key.contains(&temporary_dataset_id.to_string()));
        assert!(!static_page_prompt_requests_explicit_redesign(
            "把标题改一下"
        ));
        assert!(static_page_prompt_requests_existing_artifact_revision(
            "把标题改一下"
        ));
        assert!(static_page_prompt_requests_existing_artifact_revision(
            "修复近7日销售，切换区域和门店后需要跟着变化"
        ));
        assert!(!static_page_prompt_requests_existing_artifact_revision(
            "把之前生成过的报表链接再发我一下"
        ));
        assert!(!static_page_prompt_allows_stable_artifact_reuse(
            "把标题改一下"
        ));
        assert!(!static_page_prompt_allows_stable_artifact_reuse(
            "修复近7日销售，切换区域和门店后需要跟着变化"
        ));
        assert!(static_page_prompt_allows_stable_artifact_reuse(
            "把之前生成过的报表链接再发我一下"
        ));
        let existing_artifact = static_page_existing_artifact_reference_from_prompt(
            "修复这个页面：https://v3.elepcloud.com/generated-artifacts/database-static-pages/xinbai/report/index.html?token=fixture#frag，切换门店后近7日销售要重算。",
        );
        assert_eq!(
            existing_artifact["public_url"],
            json!("https://v3.elepcloud.com/generated-artifacts/database-static-pages/xinbai/report/index.html")
        );
        assert_eq!(
            existing_artifact["data_url"],
            json!("https://v3.elepcloud.com/generated-artifacts/database-static-pages/xinbai/report/data.json")
        );
        assert_eq!(existing_artifact["revision_requested"], json!(true));
        assert_eq!(
            static_page_existing_artifact_reference_from_prompt("重新做一个经营分析报表"),
            Value::Null
        );
        assert!(static_page_prompt_requests_explicit_redesign(
            "重新出图，换个风格"
        ));
        let metadata = static_page_artifact_stability_metadata(
            &key,
            "candidate",
            Some("https://v3.elepcloud.com/generated-artifacts/static-pages/demo/index.html"),
            Utc::now(),
        );
        assert_eq!(
            metadata["reuse_policy"],
            json!("reuse_accepted_baseline_unless_explicit_redesign")
        );
        assert_eq!(
            metadata["style_reuse_policy"],
            json!("reuse_style_unless_explicit_redesign")
        );
        assert_eq!(
            metadata["default_template_scope"],
            json!("dataset_combination")
        );
        assert_eq!(
            metadata["data_refresh_policy"],
            json!("refresh_data_files_from_dataset_sources")
        );
    }

