    #[tokio::test]
    async fn generic_chat_page_event_endpoint_requires_configured_bearer_token() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        clear_assistant_openclaw_env();
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "provider");
        std::env::set_var("ASSISTANT_RUN_RUNTIME_PROVIDER", "scripted");
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODEL", "assistant-run-scripted-v1");
        std::env::set_var("ASSISTANT_RUN_RUNTIME_OUTPUT_TEXT", "鉴权后模型直答。");
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping generic chat bearer auth test: {reason}");
                clear_assistant_openclaw_env();
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("generic-chat-bearer-test-{}", Uuid::new_v4()),
                "Generic Chat Bearer Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage.clone(),
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        insert_generic_external_channel_connection_with_config(
            &state,
            "generic-chat-main",
            json!({
                "tenant_external_id": "tenant-ext-001",
                "bot_external_id": "bot-v3",
                "inbound_bearer_token": "inbound-secret"
            }),
        )
        .await;
        let app = router(
            storage.clone(),
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );

        let message = sample_external_bot_message();
        let missing = post_json_request_with_authorization(
            app.clone(),
            "/v1/external/channels/generic-chat-main/events",
            &message,
            None,
        )
        .await;
        assert_eq!(missing.status(), StatusCode::UNAUTHORIZED);
        let missing_error: ApiErrorResponse = read_json_response(missing).await;
        assert_eq!(missing_error.code, "external_channel_auth_failed");
        assert!(!missing_error.message.contains("inbound-secret"));

        let wrong = post_json_request_with_authorization(
            app.clone(),
            "/v1/external/channels/generic-chat-main/events",
            &message,
            Some("Bearer wrong-secret"),
        )
        .await;
        assert_eq!(wrong.status(), StatusCode::UNAUTHORIZED);
        let wrong_error: ApiErrorResponse = read_json_response(wrong).await;
        assert_eq!(wrong_error.code, "external_channel_auth_failed");
        assert!(!wrong_error.message.contains("wrong-secret"));

        let accepted = post_json_request_with_authorization(
            app,
            "/v1/external/channels/generic-chat-main/events",
            &message,
            Some("Bearer inbound-secret"),
        )
        .await;
        assert_eq!(accepted.status(), StatusCode::ACCEPTED);
        let accepted: ExternalChannelEventResponse = read_json_response(accepted).await;
        assert!(accepted.accepted);
        assert_eq!(accepted.idempotency_key, message.idempotency_key);
        assert!(accepted.assistant_run_id.is_some());

        let event_count: i64 = sqlx::query_scalar(
            r#"
            select count(*)
            from external_message_events
            where tenant_id = $1
              and idempotency_key = $2
            "#,
        )
        .bind(tenant.id.0)
        .bind(&message.idempotency_key)
        .fetch_one(storage.pool())
        .await
        .expect("message events should be queryable");
        assert_eq!(event_count, 1);
        clear_assistant_openclaw_env();
    }

    #[tokio::test]
    async fn generic_chat_page_event_returns_provider_model_text_when_configured() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        clear_assistant_openclaw_env();
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "provider");
        std::env::set_var("ASSISTANT_RUN_RUNTIME_PROVIDER", "scripted");
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODEL", "assistant-run-scripted-v1");
        std::env::set_var(
            "ASSISTANT_RUN_RUNTIME_OUTPUT_TEXT",
            "这是外部模型自然回答。",
        );
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping generic chat provider endpoint test: {reason}");
                clear_assistant_openclaw_env();
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("generic-chat-provider-test-{}", Uuid::new_v4()),
                "Generic Chat Provider Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage.clone(),
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        insert_generic_external_channel_connection(&state, "generic-chat-main").await;
        let app = router(
            storage.clone(),
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );

        let mut message = sample_external_bot_message();
        message.text = Some("第三方对接联通性测试，请返回已接收状态。".to_string());
        message.message_external_id = "msg-provider-status-word-001".to_string();
        message.idempotency_key = "generic:tenant-ext-001:msg-provider-status-word-001".to_string();
        let response = post_json_request(
            app.clone(),
            "/v1/external/channels/generic-chat-main/events",
            &message,
            None,
        )
        .await;
        assert_eq!(response.status(), StatusCode::ACCEPTED);
        let body: ExternalChannelEventResponse = read_json_response(response).await;
        assert_eq!(body.reply.reply_type, ExternalBotReplyTypeView::Text);
        assert_eq!(body.reply.task_status.as_deref(), Some("answered"));
        assert_eq!(body.reply.text.as_deref(), Some("这是外部模型自然回答。"));

        let run_id = body.assistant_run_id.expect("assistant run id");
        let run = storage
            .assistant_runs()
            .get_by_id(tenant.id, run_id)
            .await
            .expect("run should load")
            .expect("run should exist");
        let output_artifacts = run
            .output_artifacts
            .as_array()
            .expect("output artifacts should be an array");
        assert_eq!(run.runtime_manifest["mode"], json!("provider"));
        assert_eq!(run.runtime_manifest["provider"], json!("scripted"));
        assert_eq!(
            run.runtime_manifest["model"],
            json!("assistant-run-scripted-v1")
        );
        assert!(output_artifacts.iter().any(|artifact| {
            artifact.get("source").and_then(Value::as_str) == Some("external_channel_model_reply")
                && artifact.get("content").and_then(Value::as_str) == Some("这是外部模型自然回答。")
        }));
        let events = storage
            .assistant_runs()
            .list_events(tenant.id, run_id)
            .await
            .expect("events should load");
        assert!(events.iter().any(|event| {
            event.event_name == "assistant_run.external_channel_model_reply_completed"
        }));
        clear_assistant_openclaw_env();
    }

