    #[test]
    fn assistant_run_attendance_row_analysis_computes_earliest_and_extremes() {
        let rows = [
            "A3 2026-05-14 坐班0900 08:51 18:10 9.32小时 正常考勤",
            "A4 2026-05-14 坐班0900 08:56 18:02 9.10小时 正常考勤",
            "A5 2026-05-13 坐班0900 未打卡 不考勤",
            "A5 2026-05-19 坐班0900 0.00小时 不考勤",
            "A8 2026-02-07 休息 08:18 20:51 12.55小时 正常考勤",
            "A8 2026-02-25 坐班0930 09:25 13:43 4.30小时 正常考勤",
        ]
        .into_iter()
        .filter_map(|line| {
            parse_assistant_run_attendance_row(line, "document://demo/chunks/0".to_string())
        })
        .collect::<Vec<_>>();

        let daily_rows = assistant_run_daily_earliest_attendance_rows(&rows);
        assert_eq!(daily_rows[0]["date"], json!("2026-05-14"));
        assert_eq!(daily_rows[0]["employee"], json!("A3"));
        assert_eq!(daily_rows[0]["first_punch"], json!("08:51"));

        let hour_rows = assistant_run_work_hour_extreme_rows(&rows);
        assert_eq!(hour_rows[0]["category"], json!("longest"));
        assert_eq!(hour_rows[0]["employee"], json!("A8"));
        assert_eq!(hour_rows[0]["date"], json!("2026-02-07"));
        assert_eq!(hour_rows[1]["category"], json!("shortest"));
        assert_eq!(hour_rows[1]["date"], json!("2026-02-25"));

        let (analysis_kind, combined_rows, excerpt) =
            assistant_run_attendance_analysis_rows(&"列出缺勤，并找工时最长和最短", &rows)
                .expect("combined attendance analysis should be computed");
        assert_eq!(analysis_kind, "absence_and_work_hour_extremes");
        assert!(combined_rows
            .iter()
            .any(|row| row.get("employee") == Some(&json!("A5"))));
        assert!(combined_rows
            .iter()
            .any(|row| row.get("category") == Some(&json!("longest"))));
        assert!(excerpt.contains("absence_candidate | 2026-05-13 | A5"));
    }

    #[test]
    fn assistant_run_attendance_row_analysis_handles_frequent_absence_workhour_prompt() {
        let rows = [
            "A3 2026-05-20 坐班0900 08:59 18:15 9.27小时 正常考勤",
            "A5 2026-05-13 坐班0900 未打卡 不考勤",
            "A5 2026-05-19 坐班0900 0.00小时 不考勤",
            "A8 2026-05-15 坐班0930 未打卡 0.00小时 正常考勤",
            "A8 2026-02-07 休息 08:18 20:51 12.55小时 正常考勤",
            "A8 2026-02-25 坐班0930 09:25 13:43 4.30小时 正常考勤",
            "A9 2026-02-25 坐班0930 09:31 18:01 8.50小时 正常考勤",
        ]
        .into_iter()
        .filter_map(|line| {
            parse_assistant_run_attendance_row(line, "document://attendance/chunks/0".to_string())
        })
        .collect::<Vec<_>>();

        let (analysis_kind, analysis_rows, excerpt) = assistant_run_attendance_analysis_rows(
            &"这份考勤表里最近有没缺勤的人？工时最长和最短分别是谁？请按日期、员工、班次、工时出表。",
            &rows,
        )
        .expect("frequent attendance prompt should compute deterministic rows");

        assert_eq!(analysis_kind, "absence_and_work_hour_extremes");
        assert_eq!(analysis_rows.len(), 4);
        assert!(analysis_rows
            .iter()
            .any(|row| row.get("employee") == Some(&json!("A5"))
                && row.get("counts_as_absence") == Some(&json!(false))));
        assert!(analysis_rows
            .iter()
            .any(|row| row.get("category") == Some(&json!("longest"))
                && row.get("employee") == Some(&json!("A8"))
                && row.get("date") == Some(&json!("2026-02-07"))));
        assert!(analysis_rows
            .iter()
            .any(|row| row.get("category") == Some(&json!("shortest"))
                && row.get("employee") == Some(&json!("A8"))
                && row.get("date") == Some(&json!("2026-02-25"))));
        assert!(excerpt.contains("absence_candidate | 2026-05-13 | A5 | 坐班0900 | 未打卡 不考勤"));
        assert!(excerpt.contains("longest | 2026-02-07 | A8 | 12.55小时"));
        assert!(excerpt.contains("shortest | 2026-02-25 | A8 | 4.30小时"));
        assert!(!excerpt.contains("shortest | 2026-05-19"));
        assert!(!excerpt.contains("shortest | 2026-05-15"));
        assert!(!excerpt.contains("46162"));
    }

