        assert!(answer.contains("| 广州寓力地产顾问有限公司 | 2 |"));
        assert!(!answer.contains("document_ids"));
        assert!(
            assistant_run_preferred_dataset_entity_scan_direct_answer(&request, &evidence)
                .is_some()
        );

