    #[test]
    fn assistant_run_extracts_typed_document_entities_and_candidate_terms() {
        let text = "姓名：张三\n\
            应聘岗位：高级Java工程师\n\
            核心技能：Rust、Kubernetes、微服务\n\
            项目名称：智能知识库平台\n\
            工作地点：深圳\n\
            毕业院校：华南师范大学\n\
            学历：硕士研究生\n\
            证书：PMP、系统架构设计师\n\
            任职公司：深圳星拓智能科技有限公司\n\
            负责订单风险识别系统和客户数据治理。";

        let entities = extract_document_entity_candidates_from_text(text, 32);
        let pairs = entities
            .iter()
            .map(|candidate| (candidate.entity_type, candidate.name.as_str()))
            .collect::<Vec<_>>();

        assert!(pairs.contains(&("organization", "深圳星拓智能科技有限公司")));
        assert!(pairs.contains(&("person", "张三")));
        assert!(pairs.contains(&("position", "高级Java工程师")));
        assert!(pairs.contains(&("skill", "Rust")));
        assert!(pairs.contains(&("skill", "Kubernetes")));
        assert!(pairs.contains(&("skill", "微服务")));
        assert!(pairs.contains(&("project", "智能知识库平台")));
        assert!(pairs.contains(&("location", "深圳")));
        assert!(pairs.contains(&("school", "华南师范大学")));
        assert!(pairs.contains(&("degree", "硕士")));
        assert!(pairs.contains(&("certificate", "PMP")));
        assert!(pairs.contains(&("certificate", "系统架构设计师")));

        let terms = extract_document_candidate_terms_from_text(text, 32);
        assert!(terms.contains(&"知识库平台".to_string()));
        assert!(terms.contains(&"风险识别系统".to_string()));
        assert!(terms.contains(&"数据治理".to_string()));
    }

    #[test]
    fn assistant_run_extracts_resume_file_name_and_project_headings_conservatively() {
        assert_eq!(
            extract_resume_candidate_name_from_object_key(
                "documents/0002-f2b9ff07478e-1777027714711-吴启伟-Java(中规中矩，做开发类型.pdf"
            )
            .as_deref(),
            Some("吴启伟")
        );
        assert_eq!(
            extract_resume_candidate_name_from_object_key(
                "documents/0005-f2b9ff07478e-1777027714709-龙念祖简历(做过物联网平台）.pdf"
            )
            .as_deref(),
            Some("龙念祖")
        );
        assert_eq!(
            extract_resume_candidate_name_from_object_key(
                "documents/产品经理-朱亚光_简历-BOSS-蓝月亮及金发-华南师范硕士.pdf"
            )
            .as_deref(),
            Some("朱亚光")
        );
        assert_eq!(
            extract_resume_candidate_name_from_object_key("documents/a孙武钊-简历.pdf").as_deref(),
            Some("孙武钊")
        );
        assert_eq!(
            extract_resume_candidate_name_from_title("陈京-深圳简历.pdf").as_deref(),
            Some("陈京")
        );
        assert_eq!(
            extract_resume_candidate_name_from_object_key(
                "/srv/aiv3/shared/objects/external-documents/source/doc-id/v1.pdf"
            ),
            None
        );

        let text = "项目经验\n\
            1的2B/2C项目，带领五人团队，展现项目管理能力。\n\
            项目名称：智能知识库平台\n\
            ## 订单风险识别系统";
        let entities = extract_document_entity_candidates_from_text(text, 32);
        let projects = entities
            .iter()
            .filter(|candidate| candidate.entity_type == "project")
            .map(|candidate| candidate.name.as_str())
            .collect::<Vec<_>>();

        assert!(projects.contains(&"智能知识库平台"));
        assert!(projects.contains(&"订单风险识别系统"));
        assert!(!projects
            .iter()
            .any(|project| project.contains("带领五人团队")));
        assert!(projects.len() <= 2);

        assert_eq!(
            normalize_project_entity_name("产品经理|物联网设备监管平台").as_deref(),
            Some("物联网设备监管平台")
        );
        assert_eq!(
            normalize_project_entity_name("1.3 自助彩票销售系统").as_deref(),
            Some("自助彩票销售系统")
        );
        assert_eq!(
            resume_project_delivery_project_name_from_line("项目一：智慧社区物联网平台").as_deref(),
            Some("智慧社区物联网平台")
        );
        assert_eq!(
            resume_project_delivery_project_name_from_line("二、门店运营中台").as_deref(),
            Some("门店运营中台")
        );
        assert_eq!(
            normalize_project_entity_name("广东电信大数据实时计算平台Java工程师").as_deref(),
            Some("广东电信大数据实时计算平台")
        );
        assert_eq!(
            normalize_project_entity_name("自动化监控平台工作").as_deref(),
            Some("自动化监控平台")
        );
        assert_eq!(
            normalize_project_entity_name(
                "基于Knime的面向大数据平台的趋势分析平台的技术可行性研究"
            )
            .as_deref(),
            Some("趋势分析平台")
        );
        assert_eq!(
            normalize_project_entity_name("基于区块链的cue币交易平台").as_deref(),
            Some("cue币交易平台")
        );
        assert_eq!(
            normalize_project_entity_name("netgain监控平台V6版本研发").as_deref(),
            Some("netgain监控平台V6")
        );
        assert_eq!(
            normalize_project_entity_name("打通商户数据与溯源平台的数据链路"),
            None
        );
        assert_eq!(normalize_project_entity_name("入驻“腾讯课程”平台"), None);
        assert_eq!(normalize_project_entity_name("该项目的研发"), None);
        assert_eq!(normalize_project_entity_name("讲平台"), None);
    }

    #[test]
    fn assistant_run_extracts_resume_profile_dimensions() {
        let now = Utc::now();
        let document = Document {
            id: DocumentId::new(),
            tenant_id: TenantId::new(),
            dataset_id: DatasetId::new(),
            owner_user_id: None,
            title: "张三简历.docx".to_string(),
            object_key: "documents/resume.docx".to_string(),
            content_type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                .to_string(),
            lifecycle: domain_model::DocumentLifecycle::Indexed,
            secret_binding_ids: vec![],
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };
        let text = "姓名：张三\n\
            性别：男\n\
            年龄：32岁\n\
            出生年月：1994年5月\n\
            应聘岗位：高级Java工程师\n\
            核心技能：Java、Rust、Kubernetes\n\
            项目名称：智能知识库平台\n\
            工作地点：深圳\n\
            毕业院校：华南师范大学\n\
            学历：硕士研究生\n\
            证书：PMP、系统架构设计师\n\
            2018.06-2024.03 任职深圳星拓智能科技有限公司";
        let entities = extract_document_entity_candidates_from_text(text, 32);

        let profile = extract_resume_document_profile(&document, text, &entities);

        assert_eq!(profile.candidate_name.as_deref(), Some("张三"));
        assert_eq!(profile.gender.as_deref(), Some("男"));
        assert_eq!(profile.age, Some(32));
        assert_eq!(profile.birth_year, Some(1994));
        assert_eq!(profile.earliest_year, Some(2018));
        assert_eq!(profile.latest_year, Some(2024));
        assert!(profile.company_count >= 1);
        assert!(profile.skill_count >= 3);
        assert!(profile.project_count >= 1);
        assert!(profile.skill_names.contains(&"Java".to_string()));
        assert!(profile
            .project_names
            .contains(&"智能知识库平台".to_string()));
        assert!(profile.school_names.contains(&"华南师范大学".to_string()));
        assert!(profile.degree_names.contains(&"硕士".to_string()));
        assert!(profile.certificate_names.contains(&"PMP".to_string()));
        assert!(profile
            .certificate_names
            .contains(&"系统架构设计师".to_string()));
        assert_eq!(profile.certificate_count, 2);

        let external_version_document = Document {
            title: "郑宇宁简历.pdf".to_string(),
            object_key: "/srv/aiv3/shared/objects/external-documents/source/doc-id/v1.pdf"
                .to_string(),
            ..document.clone()
        };
        let external_profile = extract_resume_document_profile(&external_version_document, "", &[]);
        assert_eq!(external_profile.candidate_name.as_deref(), Some("郑宇宁"));
        assert_eq!(external_profile.document_title, "郑宇宁简历.pdf");

        let terse_title_document = Document {
            title: "王贤.pdf".to_string(),
            object_key: "/srv/aiv3/shared/objects/external-documents/source/doc-id/v1.pdf"
                .to_string(),
            ..document
        };
        let terse_profile = extract_resume_document_profile(&terse_title_document, "", &[]);
        assert_eq!(terse_profile.candidate_name.as_deref(), Some("王贤"));
    }

    #[test]
    fn assistant_run_answers_multi_resume_project_delivery_from_structured_scan() {
        let now = Utc::now();
        let tenant_id = TenantId::new();
        let dataset_id = DatasetId::new();
        let document = |title: &str| Document {
            id: DocumentId::new(),
            tenant_id,
            dataset_id,
            owner_user_id: None,
            title: title.to_string(),
            object_key: format!("documents/{title}"),
            content_type: "application/pdf".to_string(),
            lifecycle: domain_model::DocumentLifecycle::Indexed,
            secret_binding_ids: vec![],
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };
        let chunk = |document: &Document, content: &str, index: i32| DocumentChunk {
            id: DocumentChunkId::new(),
            tenant_id: document.tenant_id,
            dataset_id: document.dataset_id,
            document_id: document.id,
            chunk_index: index,
            content: content.to_string(),
            token_count: 160,
            state: DocumentChunkState::Extracted,
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };

        let zhang = document("张三简历.pdf");
        let li = document("李四简历.pdf");
        let wang = document("王五简历.pdf");
        let zhang_text = "姓名：张三\n项目经验\n项目一：智慧社区物联网平台\n负责设备接入、规则引擎和上线交付，完成多门店试点。\n技术栈：Java、Spring Boot、Redis";
        let li_text = "姓名：李四\n项目经历\n1.3 自助彩票销售系统\n主导支付对接、订单模块开发和生产部署，保障系统落地。\n技术栈：Vue、MySQL";
        let wang_text = "姓名：王五\n工作经历\n负责内部系统维护。";
        let zhang_profile = extract_resume_document_profile(
            &zhang,
            zhang_text,
            &extract_document_entity_candidates_from_text(zhang_text, 32),
        );
        let li_profile = extract_resume_document_profile(
            &li,
            li_text,
            &extract_document_entity_candidates_from_text(li_text, 32),
        );
        let wang_profile = extract_resume_document_profile(
            &wang,
            wang_text,
            &extract_document_entity_candidates_from_text(wang_text, 32),
        );
        let zhang_rows = extract_resume_project_delivery_rows(
            &zhang,
            &[chunk(&zhang, zhang_text, 0)],
            &zhang_profile,
            &[],
            16,
        );
        let li_rows = extract_resume_project_delivery_rows(
            &li,
            &[chunk(&li, li_text, 0)],
            &li_profile,
            &[],
            16,
        );

        assert_eq!(zhang_rows[0].project_name, "智慧社区物联网平台");
        assert!(zhang_rows[0].delivery_summary.contains("上线交付"));
        assert_eq!(li_rows[0].project_name, "自助彩票销售系统");

        let request = CreateAssistantRunRequest {
            prompt: "把这14个人的项目交付经历，罗列出来".to_string(),
            local_thread_id: None,
            startup_briefing: None,
            selected_scope: None,
            scope_candidates: Vec::new(),
            context_policy_hint: None,
            current_artifact: None,
            messages: Vec::new(),
        };
        let evidence = json!({
            "status": "supplied",
            "supplied_items": [{
                "type": "dataset_entity_scan",
                "source": "visible_document_scan",
                "scanned_document_count": 14,
                "resume_profile_rows": [
                    zhang_profile.to_value(),
                    li_profile.to_value(),
                    wang_profile.to_value()
                ],
                "resume_project_delivery_rows": zhang_rows
                    .into_iter()
                    .chain(li_rows)
                    .map(ResumeProjectDeliveryRow::to_value)
                    .collect::<Vec<_>>()
            }]
        });

        let answer = assistant_run_dataset_entity_scan_direct_answer(&request, &evidence)
            .expect("project delivery prompts should use structured scan rows");
        assert!(answer.contains("覆盖 14 份文档"));
        assert!(answer.contains("智慧社区物联网平台"));
        assert!(answer.contains("自助彩票销售系统"));
        assert!(answer.contains("| 王五 | 未识别到项目交付段 |"));

        let artifact = assistant_run_resume_project_delivery_html_artifact(
            AssistantRunId::new(),
            &request,
            &evidence,
            now,
        )
        .expect("high-information project delivery answers should expose a HTML artifact");
        assert_eq!(
            artifact.template_id,
            HtmlArtifactTemplateIdView::ResumeProjectDeliveryMatrix
        );
        assert_eq!(
            artifact.interaction_mode,
            HtmlArtifactInteractionModeView::ReadOnly
        );
        assert_eq!(
            artifact.payload["summary"]["scannedDocumentCount"].as_u64(),
            Some(14)
        );
        assert_eq!(
            artifact.payload["generationPolicy"]["route"],
            ASSISTANT_RUN_HTML_GENERATION_ROUTE_RAPID_ARTIFACT
        );
        assert_eq!(
            artifact.payload["generationPolicy"]["image2Required"],
            false
        );
        assert_eq!(
            artifact.payload["generationPolicy"]["staticPagePipeline"],
            false
        );
        let artifact_rows = artifact.payload["rows"]
            .as_array()
            .expect("artifact rows should be structured");
        assert_eq!(artifact_rows.len(), 3);
        assert!(artifact_rows
            .iter()
            .any(|row| row["projectName"] == "智慧社区物联网平台"));
        assert!(artifact_rows
            .iter()
            .any(|row| row["status"] == "missing_project_delivery_section"));
    }

