    #[test]
    fn assistant_run_generic_document_rows_do_not_become_resume_profiles() {
        let now = Utc::now();
        let document = Document {
            id: DocumentId::new(),
            tenant_id: TenantId::new(),
            dataset_id: DatasetId::new(),
            owner_user_id: None,
            title: "2024年度采购风险分析".to_string(),
            object_key: "documents/risk-report.md".to_string(),
            content_type: "text/markdown".to_string(),
            lifecycle: domain_model::DocumentLifecycle::Indexed,
            secret_binding_ids: vec![],
            metadata: BTreeMap::new(),
            created_at: now,
            updated_at: now,
        };
        let text = "2024年度采购风险分析\n\
            风险识别系统、供应商数据治理、客户询问需要按周统计。\n\
            2023年度数据用于同比参考。";
        let profile = extract_resume_document_profile(&document, text, &[]);
        assert!(profile.is_empty());

        let mut terms_by_name = BTreeMap::new();
        for term in extract_document_candidate_terms_from_text(text, 8) {
            terms_by_name
                .entry(term)
                .or_insert_with(BTreeSet::new)
                .insert(document.id.to_string());
        }
        let keyword_rows = candidate_term_rows_for_scan(&terms_by_name);
        assert!(keyword_rows
            .iter()
            .any(|row| row.get("name").and_then(Value::as_str) == Some("风险识别系统")));

        let mut years_by_year = BTreeMap::new();
        for year in extract_resume_years(text, 8) {
            years_by_year
                .entry(year)
                .or_insert_with(BTreeSet::new)
                .insert(document.id.to_string());
        }
        let year_rows = year_rows_for_scan(&years_by_year);
        assert_eq!(year_rows[0]["name"], json!("2024"));
        assert_eq!(year_rows[1]["name"], json!("2023"));

        let chunk = DocumentChunk {
            id: DocumentChunkId::new(),
            tenant_id: document.tenant_id,
            dataset_id: document.dataset_id,
            document_id: document.id,
            chunk_index: 0,
            content: "# 采购风险概览\n\n系统需要在上传后快速完成轻解析，并在后台继续执行详细解析。\n\n字段 | 类型 | 说明\n--- | --- | ---\nsource | string | 来源".to_string(),
            token_count: 80,
            state: DocumentChunkState::Extracted,
            metadata: BTreeMap::from([(
                "parse_metadata".to_string(),
                json!({
                    "document_structure": {
                        "blocks": [
                            {"type": "paragraph_title", "text": "采购风险概览"},
                            {"type": "paragraph", "text": "系统需要在上传后快速完成轻解析，并在后台继续执行详细解析。"},
                            {"type": "table", "text": "字段 | 类型 | 说明"}
                        ]
                    }
                }),
            )]),
            created_at: now,
            updated_at: now,
        };
        let chunks = vec![chunk];

        let section_titles = extract_document_section_titles_for_scan(&chunks, text, 8);
        assert!(section_titles.contains(&"采购风险概览".to_string()));

        let paragraph_samples = extract_document_paragraphs_for_scan(&chunks, 8);
        assert!(paragraph_samples
            .iter()
            .any(|sample| sample.contains("轻解析")));

        let table_signals = extract_document_table_signals_for_scan(&chunks, text, 8);
        assert!(table_signals
            .iter()
            .any(|signal| signal == "字段 | 类型 | 说明"));
    }

