    #[test]
    fn assistant_run_react_action_parser_rejects_unknown_and_unsafe_actions() {
        let action = parse_assistant_run_next_action(
            r#"{"action_type":"final_answer","reason_summary":"完成","arguments":{"content":"可以回答"},"requires_confirmation":false}"#,
        )
        .expect("valid action should parse");

        assert_eq!(action.action_type, AssistantRunReactActionType::FinalAnswer);
        assert_eq!(action.arguments["content"], json!("可以回答"));

        let search = parse_assistant_run_next_action(
            r#"{"action_type":"web_search","reason_summary":"请求 V3 搜索证据","arguments":{"query":"外部集成最新状态","reason":"用户询问最新进展","freshness":"latest"},"requires_confirmation":false}"#,
        )
        .expect("web search action should parse");
        assert_eq!(search.action_type, AssistantRunReactActionType::WebSearch);
        assert_eq!(search.arguments["freshness"], json!("latest"));

        let unknown = parse_assistant_run_next_action(
            r#"{"action_type":"run_shell","reason_summary":"执行命令","arguments":{},"requires_confirmation":false}"#,
        )
        .expect_err("unknown actions must be rejected");
        assert!(unknown.contains("action_type"));

        let unsafe_key = parse_assistant_run_next_action(
            r#"{"action_type":"final_answer","reason_summary":"污染对象","arguments":{"__proto__":{"polluted":true}},"requires_confirmation":false}"#,
        )
        .expect_err("unsafe argument keys must be rejected");
        assert!(unsafe_key.contains("unsafe"));
    }

    #[test]
    fn assistant_run_react_repairs_premature_final_answer_for_scoped_data() {
        let dataset_id = DatasetId::new();
        let selected_scope = json!({
            "mode": "selected",
            "selected": [{"type": "dataset", "id": dataset_id.to_string()}],
            "intent": "data_question",
        });
        let ordinary_scope = json!({"mode": "ordinary_chat"});
        let ordinary_selected_scope = json!({
            "mode": "user_selected",
            "selected": [{"type": "dataset", "id": dataset_id.to_string()}],
            "intent": "ordinary_chat",
        });
        let mut final_action = react_test_action(
            AssistantRunReActStatus::FinalAnswer,
            AssistantRunReactActionType::FinalAnswer,
            json!({"content": "未供料回答"}),
        );
        final_action.answer = Some("未供料回答".to_string());

        assert!(assistant_run_react_should_repair_terminal_action(
            &final_action,
            &selected_scope,
            &json!({"status": "empty", "supplied_items": []}),
            &[],
        ));
        assert!(!assistant_run_react_should_repair_terminal_action(
            &final_action,
            &ordinary_scope,
            &json!({"status": "not_requested", "supplied_items": []}),
            &[],
        ));
        assert!(!assistant_run_react_should_repair_terminal_action(
            &final_action,
            &ordinary_selected_scope,
            &json!({"status": "empty", "supplied_items": []}),
            &[],
        ));
        assert!(!assistant_run_react_should_repair_terminal_action(
            &final_action,
            &selected_scope,
            &json!({"status": "empty", "supplied_items": []}),
            &[json!({
                "status": "completed",
                "action_type": "retrieve_evidence",
                "supplied_count": 0,
            })],
        ));
        assert!(!assistant_run_react_should_repair_terminal_action(
            &final_action,
            &selected_scope,
            &json!({
                "status": "supplied",
                "supplied_items": [{"type": "retrieval_evidence"}],
            }),
            &[],
        ));
    }

