    #[tokio::test]
    async fn static_page_draft_can_be_created_under_assistant_run() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "placeholder");
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping static page draft test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("static-page-draft-test-{}", Uuid::new_v4()),
                "Static Page Draft Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );

        let (_, Json(run_response)) = create_assistant_run(
            State(state.clone()),
            HeaderMap::new(),
            Json(CreateAssistantRunRequest {
                prompt: "生成一页经营分析静态页".to_string(),
                local_thread_id: Some("static-page-draft-thread".to_string()),
                startup_briefing: Some(json!({"capabilities": ["static_page_plan"]})),
                selected_scope: Some(json!({"mode": "ordinary_chat"})),
                scope_candidates: Vec::new(),
                context_policy_hint: None,
                current_artifact: None,
                messages: Vec::new(),
            }),
        )
        .await
        .expect("assistant run should be created");

        let (draft_status, Json(draft_response)) = create_static_page_draft_for_assistant_run(
            State(state.clone()),
            HeaderMap::new(),
            Path(run_response.assistant_run_id.to_string()),
            Json(CreateStaticPageDraftRequest {
                title: Some("经营分析静态页".to_string()),
                prompt: Some("生成一页经营分析静态页".to_string()),
                template_reference_id: Some("data-report".to_string()),
                selected_scope: None,
                visibility_snapshot: None,
                source_refs: Value::Null,
                draft_payload: json!({
                    "version": 1,
                    "status": "planning",
                    "styleDirection": "client-delivery",
                    "mobileOrder": ["hero", "kpi", "trend", "risk", "next-steps"],
                    "modules": [
                        { "id": "hero", "title": "核心判断", "content": "先给出主结论。" },
                        { "id": "kpi", "title": "关键指标", "content": "展示指标。" },
                        { "id": "trend", "title": "趋势变化", "content": "展示趋势。" },
                        { "id": "risk", "title": "风险与机会", "content": "展示风险。" },
                        { "id": "next-steps", "title": "建议动作", "content": "展示动作。" }
                    ]
                }),
            }),
        )
        .await
        .expect("static page draft should be created");

        assert_eq!(draft_status, StatusCode::CREATED);
        assert_eq!(draft_response.draft.title, "经营分析静态页");
        assert_eq!(
            draft_response.draft.status,
            contracts::StaticPageDraftStatusView::Planned
        );
        assert_eq!(
            draft_response.draft.assistant_run_id,
            run_response.assistant_run_id
        );
        assert_eq!(
            draft_response.draft.draft_payload["modules"][0]["title"],
            json!("核心判断")
        );
        assert_eq!(
            draft_response.draft.draft_payload["templateReferenceId"],
            json!("data-report")
        );
        assert_eq!(
            draft_response.draft.draft_payload["designReferences"][0]["source"],
            json!("html-anything")
        );
        assert_eq!(
            draft_response.draft.draft_payload["templateReference"]["templateId"],
            json!("data-report")
        );
        assert_eq!(
            draft_response.draft.draft_payload["templateEvidenceSummary"]["status"],
            json!("not_requested")
        );
        assert_eq!(
            draft_response.draft.draft_payload["missingEvidence"]["status"],
            json!("needs_evidence")
        );
        assert_eq!(
            draft_response.draft.source_refs["template_reference_id"],
            json!("data-report")
        );
        assert!(value_array(
            draft_response.draft.draft_payload["dataSnapshot"]["data_source_candidates"].clone()
        )
        .iter()
        .any(|candidate| candidate["sourceId"] == json!("model")));

        let Json(local_thread_drafts) = list_static_page_drafts(
            State(state.clone()),
            HeaderMap::new(),
            Query(StaticPageDraftListQuery {
                local_thread_id: Some("static-page-draft-thread".to_string()),
                assistant_run_id: None,
                limit: Some(10),
            }),
        )
        .await
        .expect("static page drafts should list by local thread");
        assert_eq!(local_thread_drafts.len(), 1);
        assert_eq!(local_thread_drafts[0].id, draft_response.draft.id);

        let Json(run_drafts) = list_static_page_drafts(
            State(state.clone()),
            HeaderMap::new(),
            Query(StaticPageDraftListQuery {
                local_thread_id: None,
                assistant_run_id: Some(run_response.assistant_run_id.to_string()),
                limit: Some(10),
            }),
        )
        .await
        .expect("static page drafts should list by assistant run");
        assert_eq!(run_drafts.len(), 1);
        assert_eq!(
            run_drafts[0].assistant_run_id,
            run_response.assistant_run_id
        );

        let Json(loaded) = get_static_page_draft(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
        )
        .await
        .expect("static page draft should load");
        assert_eq!(loaded.id, draft_response.draft.id);
        assert_eq!(
            loaded.visibility_snapshot["policy"],
            json!("assistant_run_scope_snapshot")
        );

        let (intent_status, Json(intent_response)) = apply_static_page_draft_intent(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
            Json(ApplyStaticPageDraftIntentRequest {
                prompt: "给老板看，突出风险，趋势换成柱状图".to_string(),
                draft_payload: None,
                messages: Vec::new(),
            }),
        )
        .await
        .expect("static page intent should apply");
        assert_eq!(intent_status, StatusCode::CREATED);
        assert_eq!(
            intent_response.draft.status,
            contracts::StaticPageDraftStatusView::Planned
        );
        assert_eq!(
            intent_response.draft.draft_payload["styleDirection"],
            json!("decision-brief")
        );
        assert_eq!(
            intent_response.draft.draft_payload["modules"][3]["title"],
            json!("优先风险与机会")
        );
        assert!(intent_response
            .operations
            .iter()
            .any(|operation| operation["type"] == json!("change_visualization")));

        let (module_operation_status, Json(module_operation_response)) =
            append_static_page_draft_operations(
                State(state.clone()),
                HeaderMap::new(),
                Path(draft_response.draft.id.to_string()),
                Json(AppendStaticPageDraftOperationsRequest {
                    prompt: Some("趋势模块接当前数据源，并改成折线图".to_string()),
                    summary: None,
                    operations: vec![json!({
                        "type": "update_module",
                        "targetModuleId": "trend",
                        "patch": {
                            "title": "订单趋势",
                            "content": "展示订单金额按月变化。",
                            "dataBinding": {
                                "type": "selected_scope",
                                "label": "订单金额",
                                "sourceId": "selected_scope",
                                "fieldPath": "orders.amount"
                            },
                            "visualization": {
                                "type": "line-chart",
                                "label": "趋势折线图",
                                "chartOptions": {
                                    "showLegend": true,
                                    "showAxis": true,
                                    "valueFormat": "currency",
                                    "dataKey": "orders.amount"
                                }
                            }
                        }
                    })],
                    draft_payload: None,
                }),
            )
            .await
            .expect("static page module operation should append");
        assert_eq!(module_operation_status, StatusCode::CREATED);
        let trend_module =
            value_array(module_operation_response.draft.draft_payload["modules"].clone())
                .into_iter()
                .find(|module| module["id"] == json!("trend"))
                .expect("trend module should exist");
        assert_eq!(trend_module["title"], json!("订单趋势"));
        assert_eq!(
            trend_module["dataBinding"]["fieldPath"],
            json!("orders.amount")
        );
        assert_eq!(
            trend_module["visualization"]["chartOptions"]["dataKey"],
            json!("orders.amount")
        );
        assert!(value_array(
            module_operation_response.draft.draft_payload["dataSnapshot"]["module_bindings"]
                .clone()
        )
        .iter()
        .any(|binding| binding["moduleId"] == json!("trend")
            && binding["chartOptions"]["dataKey"] == json!("orders.amount")));

        let (operation_status, Json(operation_response)) = append_static_page_draft_operations(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
            Json(AppendStaticPageDraftOperationsRequest {
                prompt: Some("直接排队出效果图".to_string()),
                summary: None,
                operations: vec![json!({
                    "type": "queue_image_job",
                    "queuePosition": 2,
                })],
                draft_payload: None,
            }),
        )
        .await
        .expect("static page operations should append");
        assert_eq!(operation_status, StatusCode::CREATED);
        assert_eq!(
            operation_response.draft.status,
            contracts::StaticPageDraftStatusView::Queued
        );
        assert_eq!(
            operation_response.draft.draft_payload["imageJob"]["status"],
            json!("queued")
        );

        let invalid_operation = append_static_page_draft_operations(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
            Json(AppendStaticPageDraftOperationsRequest {
                prompt: Some("执行未知操作".to_string()),
                summary: None,
                operations: vec![json!({
                    "type": "run_shell",
                })],
                draft_payload: None,
            }),
        )
        .await
        .expect_err("unknown static page operation should be rejected");
        assert_eq!(
            invalid_operation.payload.code,
            "invalid_static_page_operation"
        );

        let render_before_confirm = create_static_page_render(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
            Json(CreateStaticPageRenderRequest {
                image_job_id: None,
                background: false,
                direct_html: false,
            }),
        )
        .await
        .expect_err("render should require confirmed preview");
        assert_eq!(
            render_before_confirm.payload.code,
            "static_page_preview_not_confirmed"
        );

        let (job_status, Json(job_response)) = create_static_page_image_job(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
            Json(CreateStaticPageImageJobRequest {
                prompt: Some("生成一张经营分析效果图".to_string()),
                image_prompt_payload: Value::Null,
            }),
        )
        .await
        .expect("preview queue should allow planned design before data repair");
        assert_eq!(job_status, StatusCode::CREATED);
        assert_eq!(
            job_response.image_job.status,
            contracts::StaticPageImageJobStatusView::Queued
        );
        assert_eq!(job_response.image_job.queue_position, Some(1));
        assert_eq!(
            job_response.image_job.image_prompt_payload["queue_copy"],
            json!("资源正在排队，可以联系商务开通高级用户跳过等待。")
        );
        assert_eq!(
            job_response.image_job.image_prompt_payload["design_contract"]["editable_core"],
            json!("DOM text + SVG/chart components + safe ECharts JSON options")
        );
        assert_eq!(
            job_response.image_job.image_prompt_payload["render_spec"]["componentModel"],
            json!("dom-text-svg-chart")
        );
        assert_eq!(
            job_response.image_job.image_prompt_payload["render_spec"]["chartRuntime"],
            json!("deterministic-with-echarts-advanced")
        );

        let (data_repair_status, Json(data_repair_response)) = append_static_page_draft_operations(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
            Json(AppendStaticPageDraftOperationsRequest {
                prompt: Some("补齐效果图所需模块数据".to_string()),
                summary: Some("补齐图表模块样本行，允许效果图入队。".to_string()),
                operations: vec![
                    json!({
                        "type": "update_module",
                        "targetModuleId": "hero",
                        "patch": {
                            "dataBinding": {
                                "type": "model_summary",
                                "label": "模型总结",
                                "sourceId": "model"
                            },
                            "visualization": {
                                "type": "headline",
                                "label": "大标题 + 关键结论"
                            }
                        }
                    }),
                    json!({
                        "type": "update_module",
                        "targetModuleId": "kpi",
                        "patch": {
                            "dataBinding": {
                                "type": "module_data",
                                "label": "关键指标样本",
                                "sourceId": "dataset",
                                "fieldPath": "dataset.metrics_summary"
                            },
                            "visualization": {
                                "type": "kpi-cards",
                                "label": "关键指标卡",
                                "data": [
                                    {"label": "收入", "value": 1200},
                                    {"label": "客户数", "value": 320}
                                ]
                            }
                        }
                    }),
                    json!({
                        "type": "update_module",
                        "targetModuleId": "trend",
                        "patch": {
                            "dataBinding": {
                                "type": "module_data",
                                "label": "订单金额",
                                "sourceId": "dataset",
                                "fieldPath": "orders.amount"
                            },
                            "visualization": {
                                "type": "line-chart",
                                "label": "趋势折线图",
                                "chartOptions": {
                                    "showLegend": true,
                                    "showAxis": true,
                                    "valueFormat": "currency",
                                    "dataKey": "orders.amount"
                                },
                                "data": [
                                    {"label": "1月", "value": 1200},
                                    {"label": "2月", "value": 1380}
                                ]
                            }
                        }
                    }),
                    json!({
                        "type": "update_module",
                        "targetModuleId": "risk",
                        "patch": {
                            "dataBinding": {
                                "type": "module_data",
                                "label": "风险样本",
                                "sourceId": "model",
                                "fieldPath": "risk.score"
                            },
                            "visualization": {
                                "type": "risk-matrix",
                                "label": "风险优先级矩阵",
                                "data": [
                                    {"label": "交付风险", "value": 0.7},
                                    {"label": "机会空间", "value": 0.4}
                                ]
                            }
                        }
                    }),
                    json!({
                        "type": "update_module",
                        "targetModuleId": "next-steps",
                        "patch": {
                            "dataBinding": {
                                "type": "model_summary",
                                "label": "模型建议动作",
                                "sourceId": "model"
                            },
                            "visualization": {
                                "type": "timeline",
                                "label": "阶段时间线"
                            }
                        }
                    }),
                ],
                draft_payload: None,
            }),
        )
        .await
        .expect("static page data repair operations should append");
        assert_eq!(data_repair_status, StatusCode::CREATED);
        assert_eq!(
            data_repair_response.draft.draft_payload["dataSnapshot"]["module_bindings"][0]
                ["bindingQualityStatus"],
            json!("confirmed")
        );

        let image_workflows = state
            .storage
            .workflow_executions()
            .list_by_tenant(state.tenant_id)
            .await
            .expect("workflow executions should list");
        let image_workflow = image_workflows
            .iter()
            .find(|execution| execution.kind == WorkflowKind::StaticPageImageGeneration)
            .expect("static page image generation workflow should be created");
        assert_eq!(image_workflow.status, WorkflowStatus::Running);
        assert_eq!(
            image_workflow.context["static_page_image_job_id"],
            json!(job_response.image_job.id.to_string())
        );
        let image_tasks = state
            .storage
            .workflow_tasks()
            .list_by_execution(image_workflow.id)
            .await
            .expect("static page image workflow tasks should list");
        assert_eq!(image_tasks.len(), 1);
        assert_eq!(image_tasks[0].queue, "static_page");
        assert_eq!(image_tasks[0].task_key, "generate_static_page_image");

        let Json(loaded_job) = get_static_page_image_job(
            State(state.clone()),
            HeaderMap::new(),
            Path(job_response.image_job.id.to_string()),
        )
        .await
        .expect("static page image job should load");
        assert_eq!(loaded_job.id, job_response.image_job.id);

        let Json(image_jobs) = list_static_page_image_jobs(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
        )
        .await
        .expect("static page image jobs should list");
        assert_eq!(image_jobs.len(), 1);
        assert_eq!(image_jobs[0].id, job_response.image_job.id);

        let Json(confirmed) = confirm_static_page_image_job(
            State(state.clone()),
            HeaderMap::new(),
            Path(job_response.image_job.id.to_string()),
            Json(ConfirmStaticPageImageJobRequest {
                preview_asset_key: Some("previews/static-page-1.png".to_string()),
            }),
        )
        .await
        .expect("static page image job should confirm");
        assert_eq!(
            confirmed.image_job.status,
            contracts::StaticPageImageJobStatusView::Confirmed
        );
        assert_eq!(
            confirmed.draft.status,
            contracts::StaticPageDraftStatusView::Confirmed
        );
        assert_eq!(
            confirmed.draft.draft_payload["previewImage"]["assetKey"],
            json!("previews/static-page-1.png")
        );
        assert_eq!(
            confirmed.draft.draft_payload["previewContract"]["status"],
            json!("confirmed")
        );

        let (background_render_status, Json(background_render_response)) =
            create_static_page_render(
                State(state.clone()),
                HeaderMap::new(),
                Path(draft_response.draft.id.to_string()),
                Json(CreateStaticPageRenderRequest {
                    image_job_id: Some(job_response.image_job.id),
                    background: true,
                    direct_html: false,
                }),
            )
            .await
            .expect("background static page render should be queued");
        assert_eq!(background_render_status, StatusCode::CREATED);
        assert_eq!(
            background_render_response.render_output.status,
            contracts::StaticPageRenderOutputStatusView::Rendering
        );
        assert_eq!(background_render_response.render_output.html, "");
        assert_eq!(
            background_render_response.render_output.asset_manifest["status"],
            json!("rendering")
        );
        assert_eq!(
            background_render_response.render_output.asset_manifest["image_job_id"],
            json!(job_response.image_job.id)
        );
        assert_eq!(
            background_render_response.render_output.asset_manifest["workflow"]["status"],
            json!("running")
        );
        assert_eq!(
            background_render_response.render_output.asset_manifest["export_package"]["kind"],
            json!("static-page-export-package")
        );
        assert_eq!(
            background_render_response.render_output.asset_manifest["export_package"]["files"][0]
                ["path"],
            json!("index.html")
        );
        let render_workflows = state
            .storage
            .workflow_executions()
            .list_by_tenant(state.tenant_id)
            .await
            .expect("workflow executions should list after background render");
        let render_workflow = render_workflows
            .iter()
            .find(|execution| execution.kind == WorkflowKind::StaticPageRender)
            .expect("static page render workflow should be created");
        assert_eq!(render_workflow.status, WorkflowStatus::Running);
        assert_eq!(
            render_workflow.context["static_page_render_output_id"],
            json!(background_render_response.render_output.id.to_string())
        );
        sync_static_page_render_output_for_workflow(&state, render_workflow.id)
            .await
            .expect("running render workflow should sync output status");
        let running_background_output = state
            .storage
            .static_page_render_outputs()
            .get_by_id(state.tenant_id, background_render_response.render_output.id)
            .await
            .expect("running render output should load")
            .expect("running render output should exist");
        assert_eq!(
            running_background_output.status,
            StaticPageRenderOutputStatus::Rendering
        );
        assert_eq!(
            running_background_output.asset_manifest["status"],
            json!("rendering")
        );
        let render_tasks = state
            .storage
            .workflow_tasks()
            .list_by_execution(render_workflow.id)
            .await
            .expect("static page render workflow tasks should list");
        assert_eq!(render_tasks.len(), 1);
        assert_eq!(render_tasks[0].queue, "static_page");
        assert_eq!(render_tasks[0].task_key, "render_static_page");
        assert_eq!(
            running_background_output.asset_manifest["workflow"]["taskId"],
            json!(render_tasks[0].id)
        );
        let Json(cancel_transition) = send_workflow_signal(
            State(state.clone()),
            HeaderMap::new(),
            Path(render_workflow.id.to_string()),
            Json(contracts::WorkflowSignalRequest {
                kind: contracts::WorkflowSignalKindView::CancelRequested,
                task_key: None,
                output: None,
                error: None,
                reason: Some("customer_changed_render_request".to_string()),
                note: None,
            }),
        )
        .await
        .expect("background static page render workflow should cancel");
        assert_eq!(
            cancel_transition.execution.status,
            WorkflowStatus::Cancelled
        );
        let cancelled_background_output = state
            .storage
            .static_page_render_outputs()
            .get_by_id(state.tenant_id, background_render_response.render_output.id)
            .await
            .expect("background render output should load")
            .expect("background render output should exist");
        assert_eq!(
            cancelled_background_output.status,
            StaticPageRenderOutputStatus::Cancelled
        );
        assert_eq!(
            cancelled_background_output.asset_manifest["workflow"]["status"],
            json!("cancelled")
        );

        let (render_status, Json(render_response)) = create_static_page_render(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
            Json(CreateStaticPageRenderRequest {
                image_job_id: Some(job_response.image_job.id),
                background: false,
                direct_html: false,
            }),
        )
        .await
        .expect("static page render should be created");
        assert_eq!(render_status, StatusCode::CREATED);
        assert_eq!(
            render_response.render_output.status,
            contracts::StaticPageRenderOutputStatusView::Rendered
        );
        assert!(render_response.render_output.html.contains("核心判断"));
        assert!(render_response
            .render_output
            .html
            .contains("previews/static-page-1.png"));
        assert_eq!(
            render_response.render_output.asset_manifest["design_contract"]["preview_role"],
            json!("visual_contract")
        );
        assert_eq!(
            render_response.render_output.asset_manifest["render_spec"]["componentModel"],
            json!("dom-text-svg-chart")
        );
        assert_eq!(
            render_response.draft.status,
            contracts::StaticPageDraftStatusView::Rendered
        );

        let Json(render_outputs) = list_static_page_render_outputs(
            State(state.clone()),
            HeaderMap::new(),
            Path(draft_response.draft.id.to_string()),
        )
        .await
        .expect("static page render outputs should list");
        assert_eq!(render_outputs.len(), 2);
        assert!(render_outputs
            .iter()
            .any(|output| output.id == render_response.render_output.id));
        assert!(render_outputs
            .iter()
            .any(|output| output.id == background_render_response.render_output.id));

        let Json(detail) = get_assistant_run(
            State(state),
            HeaderMap::new(),
            Path(run_response.assistant_run_id.to_string()),
        )
        .await
        .expect("assistant run detail should load");
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_draft.created"));
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_draft.intent_applied"));
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_draft.operations_appended"));
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_image_job.created"));
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_image_job.confirmed"));
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_render.queued"));
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_render.created"));
    }

    #[tokio::test]
    async fn assistant_run_react_can_create_template_assisted_static_page_draft() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        clear_assistant_openclaw_env();
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "placeholder");
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping react static page create test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("react-static-page-create-test-{}", Uuid::new_v4()),
                "ReAct Static Page Create Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );

        let (_, Json(run_response)) = create_assistant_run(
            State(state.clone()),
            HeaderMap::new(),
            Json(CreateAssistantRunRequest {
                prompt: "做一个运营监控看板".to_string(),
                local_thread_id: Some("react-static-page-create-thread".to_string()),
                startup_briefing: Some(json!({"capabilities": ["static_page_plan"]})),
                selected_scope: Some(json!({"mode": "ordinary_chat"})),
                scope_candidates: Vec::new(),
                context_policy_hint: None,
                current_artifact: None,
                messages: Vec::new(),
            }),
        )
        .await
        .expect("assistant run should be created");

        let action = react_test_action(
            AssistantRunReActStatus::Act,
            AssistantRunReactActionType::CreateStaticPageDraft,
            json!({
                "prompt": "做一个运营监控看板，突出风险和最近动作"
            }),
        );
        let mut evidence_state = json!({"status": "not_requested"});

        let result = execute_assistant_run_react_action(
            &state,
            &action,
            &json!({"mode": "ordinary_chat"}),
            &mut evidence_state,
            None,
            Some(run_response.assistant_run_id),
            "做一个运营监控看板",
            Some("react-static-page-create-thread"),
            &[],
            None,
        )
        .await
        .expect("react static page create should apply");

        assert_eq!(result.observation["status"], json!("completed"));
        assert_eq!(
            result.observation["template_reference"]["templateId"],
            json!("dashboard")
        );
        assert_eq!(
            result.observation["missing_evidence"]["status"],
            json!("needs_evidence")
        );
        let draft_id = result.observation["draft_id"]
            .as_str()
            .expect("draft id should be present")
            .to_string();

        let Json(loaded) =
            get_static_page_draft(State(state.clone()), HeaderMap::new(), Path(draft_id))
                .await
                .expect("created static page draft should load");
        assert_eq!(
            loaded.draft_payload["templateReferenceId"],
            json!("dashboard")
        );
        assert_eq!(
            loaded.draft_payload["templateReference"]["templateId"],
            json!("dashboard")
        );
        assert_eq!(
            loaded.draft_payload["missingEvidence"]["status"],
            json!("needs_evidence")
        );
        assert!(value_array(loaded.draft_payload["modules"].clone())
            .iter()
            .any(|module| module["id"] == json!("activity")));

        let Json(detail) = get_assistant_run(
            State(state),
            HeaderMap::new(),
            Path(run_response.assistant_run_id.to_string()),
        )
        .await
        .expect("assistant run detail should load");
        let created_event = detail
            .events
            .iter()
            .find(|event| event.event_name == "static_page_draft.created")
            .expect("created event should be appended");
        assert_eq!(
            created_event.payload["template_reference"]["templateId"],
            json!("dashboard")
        );
        assert_eq!(
            created_event.payload["missing_evidence"]["status"],
            json!("needs_evidence")
        );
        assert!(detail
            .events
            .iter()
            .any(|event| event.event_name == "static_page_draft.react_created"));
    }

    #[tokio::test]
    async fn docs_page_draft_creation_uses_supplied_section_title_hints() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "placeholder");
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping docs page draft creation test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("docs-page-draft-test-{}", Uuid::new_v4()),
                "Docs Page Draft Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );

        let (_, Json(run_response)) = create_assistant_run(
            State(state.clone()),
            HeaderMap::new(),
            Json(CreateAssistantRunRequest {
                prompt: "整理接口交接文档和验收步骤".to_string(),
                local_thread_id: Some("docs-page-draft-thread".to_string()),
                startup_briefing: Some(json!({"capabilities": ["static_page_plan"]})),
                selected_scope: Some(json!({"mode": "ordinary_chat"})),
                scope_candidates: Vec::new(),
                context_policy_hint: None,
                current_artifact: None,
                messages: Vec::new(),
            }),
        )
        .await
        .expect("assistant run should be created");
        let evidence_state = json!({
            "status": "supplied",
            "supplied_items": [{
                "type": "retrieval_evidence",
                "retrieval_evidence_id": Uuid::new_v4().to_string(),
                "source_locator": "documents/api-handoff.md#chunk=0",
                "summary": "接口交接与验收说明",
                "content_excerpt": "## 接口与数据\n输入输出字段说明。\n## 校验与交付\n运行 smoke 验证。",
                "evidence_manifest": {
                    "evidence": {
                        "section_title_hints": ["接口与数据", "校验与交付"]
                    }
                }
            }]
        });
        state
            .storage
            .assistant_runs()
            .update_evidence_state(
                state.tenant_id,
                run_response.assistant_run_id,
                &evidence_state,
            )
            .await
            .expect("evidence state should update");

        let (draft_status, Json(draft_response)) = create_static_page_draft_for_assistant_run(
            State(state.clone()),
            HeaderMap::new(),
            Path(run_response.assistant_run_id.to_string()),
            Json(CreateStaticPageDraftRequest {
                title: None,
                prompt: Some("整理接口交接文档和验收步骤".to_string()),
                template_reference_id: Some("docs-page".to_string()),
                selected_scope: None,
                visibility_snapshot: None,
                source_refs: Value::Null,
                draft_payload: Value::Null,
            }),
        )
        .await
        .expect("docs page static draft should be created");

        assert_eq!(draft_status, StatusCode::CREATED);
        assert_eq!(
            draft_response.draft.draft_payload["templateReferenceId"],
            json!("docs-page")
        );
        assert_eq!(
            draft_response.draft.draft_payload["missingEvidence"]["status"],
            json!("ready")
        );
        assert!(
            value_array(draft_response.draft.draft_payload["modules"].clone())
                .iter()
                .any(|module| module["id"] == json!("interfaces"))
        );

        let bindings = value_array(
            draft_response.draft.draft_payload["dataSnapshot"]["module_bindings"].clone(),
        );
        for module_id in ["scope", "steps", "interfaces", "checks"] {
            let binding = bindings
                .iter()
                .find(|binding| binding["moduleId"] == json!(module_id))
                .expect("docs-page structure module should be bound");
            assert_eq!(binding["binding"]["sourceId"], json!("evidence"));
            assert_eq!(
                binding["binding"]["fieldPath"],
                json!("retrieval.section_title_hints")
            );
            assert_eq!(
                binding["bindingQuality"]["matchedFieldCandidate"]["sectionTitleHints"][0],
                json!("接口与数据")
            );
        }
    }

