    #[test]
    fn external_channel_system_user_email_is_scoped_per_interface() {
        let left = external_system_user_email("channel", "generic-chat-main");
        let right = external_system_user_email("channel", "another-chat-main");

        assert_ne!(left, right);
        assert!(left.ends_with("@aidp.local"));
        assert_eq!(
            left,
            external_system_user_email("channel", "generic-chat-main")
        );
    }

    #[test]
    fn static_page_owner_visibility_requires_matching_user() {
        let owner_user_id = UserId::new();

        assert!(static_page_owner_is_visible(None, None));
        assert!(static_page_owner_is_visible(None, Some(owner_user_id)));
        assert!(static_page_owner_is_visible(
            Some(owner_user_id),
            Some(owner_user_id)
        ));
        assert!(!static_page_owner_is_visible(Some(owner_user_id), None));
        assert!(!static_page_owner_is_visible(
            Some(owner_user_id),
            Some(UserId::new())
        ));
    }

    #[test]
    fn report_owner_visibility_requires_matching_user() {
        let owner_user_id = UserId::new();

        assert!(report_owner_is_visible(None, None));
        assert!(report_owner_is_visible(None, Some(owner_user_id)));
        assert!(report_owner_is_visible(
            Some(owner_user_id),
            Some(owner_user_id)
        ));
        assert!(!report_owner_is_visible(Some(owner_user_id), None));
        assert!(!report_owner_is_visible(
            Some(owner_user_id),
            Some(UserId::new())
        ));
    }

    #[tokio::test]
    async fn create_dataset_secret_binding_marks_dataset_private() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping dataset secret binding route test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("dataset-secret-test-{}", Uuid::new_v4()),
                "Dataset Secret Test",
            )
            .await
            .expect("tenant should exist");
        let dataset = storage
            .datasets()
            .create(
                tenant.id,
                NewDataset {
                    key: format!("private-{}", Uuid::new_v4()),
                    title: "Private Dataset".to_string(),
                    description: None,
                    owner_user_id: None,
                },
            )
            .await
            .expect("dataset should be created");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );

        let (status, Json(response)) = create_dataset_secret_binding(
            State(state.clone()),
            HeaderMap::new(),
            Json(CreateDatasetSecretBindingRequest {
                dataset_id: dataset.id,
                fingerprint: "local-secret-fingerprint".to_string(),
                label: None,
            }),
        )
        .await
        .expect("secret binding should be created");

        assert_eq!(status, StatusCode::CREATED);
        assert_eq!(response.dataset.visibility, DatasetVisibility::Private);
        assert_eq!(
            response.secret_binding_id,
            response.dataset.secret_binding_ids[0]
        );

        let Json(without_secret) = list_datasets(State(state.clone()), HeaderMap::new())
            .await
            .expect("datasets should list");
        assert!(!without_secret
            .iter()
            .any(|item| item.id == response.dataset.id));

        let mut headers = HeaderMap::new();
        headers.insert(
            ACTIVE_SECRET_BINDING_IDS_HEADER,
            axum::http::HeaderValue::from_str(&response.secret_binding_id.to_string())
                .expect("secret binding header should parse"),
        );
        let Json(with_secret) = list_datasets(State(state), headers)
            .await
            .expect("datasets should list with secret");
        assert!(with_secret
            .iter()
            .any(|item| item.id == response.dataset.id));
    }

